[75018] = { ["id"] = 75018, ["name"] = "Into the Dark", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["mapID"] = 2174, ["storyline"] = { 74521, 74522, 74523, 74525, 75018, 75028, 75029, 75417 }, ["description"] = "My Blacktalon forces continue to secure the laboratory, but I think we are done here, <name>. We have secured some slitherdrakes to take us down to the central platform. From there we can continue below, to where Sarkareth fell. I am certain Ebyssian and Emberthal will benefit from our presence.", ["objectivesText"] = "Meet with Ebyssian and Emberthal in the room at the bottom of the laboratory.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 26010, 26024, 26036, 38734, 39033, 39060, 39098, 62849, 62850, 62851, 131271, 131640, 184165 }, ["starts"] = { { ["npcID"] = 202809 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 202809, ["questType"] = "standard", ["sourceQuests"] = { 74522, 74523, 74525 }, ["questLines"] = { { ["id"] = 1397, ["name"] = "A Flame, Extinguished", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 66, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2600, ["db2PoiUiMapID"] = 2174 },
