[75023] = { ["id"] = 75023, ["name"] = "Memories of Sindragosa and Malygos", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "I admit, I forgot about this phenomenon. Blue dragons who meet violent ends occasionally have some lingering arcane energy. That energy may manifest in various ways once their essences are laid to rest. Luckily, it is a simple enough process to dispel them. Simply wave anything through the energy and it will dissipate. I shall investigate the essences of Sindragosa and Malygos within this gravestone while you handle that.", ["objectivesText"] = "Dispel the lingering memories of Sindragosa and Malygos. Progress: How strange that these memories still linger...", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 200447, ["x"] = 0.67, ["y"] = 0.118 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 200447, ["x"] = 0.67, ["y"] = 0.118 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.118 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 73069 }, ["questLines"] = { { ["id"] = 1398, ["name"] = "The Veiled Ossuary", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] =