[75024] = { ["id"] = 75024, ["name"] = "Sneaky Pebbles", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14433, ["description"] = "Beetles are swarming our support creche! Some of them are now eating pieces of broken Infusers, and that's making them stronger. We keep trying to smush them, but they won't stay smushed. Now it's harder to get rid of them, but we have a plan. We've discovered that hitting them with pieces of broken Infusers can weaken them again! Do you mind helping us clear out these Infused Beetles?", ["rewardCurrencies"] = { { ["id"] = 2118, ["amount"] = 450 } }, ["starts"] = { { ["npcID"] = 200727, ["x"] = 0.348, ["y"] = 0.574, ["zoneID"] = 14433 } }, ["ends"] = { { ["npcID"] = 200727, ["x"] = 0.348, ["y"] = 0.574, ["zoneID"] = 14433 } }, ["coords"] = { ["x"] = 0.348, ["y"] = 0.574, ["source"] = "quest_giver", ["zoneID"] = 14433 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 73157, 74769, 75050 } },
[75025] = { ["id"] = 75025, ["name"] = "A Good Day for Rolling", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14433, ["description"] = "I have an... odd request for you. I need help with some squirrels. Primalists have corrupted them, and it's making them unstable! I know just the thing to cool them off. Snow! If you could roll the creatures up in a big snowball, they would cool down as the snow melts. Ingenious, yes? Can you help me? I can't concentrate or finish my cataloguing, and I don't have time to write more eloquent prose. If nothing else, think of the loss to great literature!", ["rewardCurrencies"] = { { ["id"] = 2118, ["amount"] = 450 } }, ["starts"] = { { ["npcID"] = 201291, ["x"] = 0.344, ["y"] = 0.592, ["zoneID"] = 14433 } }, ["ends"] = { { ["npcID"] = 201291, ["x"] = 0.344, ["y"] = 0.592, ["zoneID"] = 14433 } }, ["coords"] = { ["x"] = 0.344, ["y"] = 0.592, ["source"] = "quest_giver", ["zoneID"] = 14433 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 73157, 74769, 75050 } },
[75026] = { ["id"] = 75026, ["name"] = "Up to the Highest Height!", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14433, ["description"] = "Tuskarr children sure do love kites! I've seen some of them running around with them outside Morqut Village. I've also seen a lot of those kites stuck in trees. Can you do me a favor? Could you lasso some of those kites and pull them down? They'll probably fall down in pieces, but the children can always put their kites back together. Who knows? Maybe it will teach them to be more careful.", ["rewardCurrencies"] = { { ["id"] = 2118, ["amount"] = 450 } }, ["starts"] = { { ["npcID"] = 200558, ["x"] = 0.344, ["y"] = 0.586, ["zoneID"] = 14433 } }, ["ends"] = { { ["npcID"] = 200558, ["x"] = 0.344, ["y"] = 0.586, ["zoneID"] = 14433 } }, ["coords"] = { ["x"] = 0.344, ["y"] = 0.586, ["source"] = "quest_giver", ["zoneID"] = 14433 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 73157, 74769, 75050 } },
[75028] = { ["id"] = 75028, ["name"] = "All the Broken Pieces", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["mapID"] = 2174, ["storyline"] = { 74521, 74522, 74523, 74525, 75018, 75028, 75029, 75417 }, ["description"] = "Emberthal is in mourning. In truth, she has been grieving for Sarkareth for some time now. The way forward is for her to determine. We can only be there to support her along the way. There are shards of Sarkareth's signet scattered all over this room. Would you gather them? I believe she would appreciate the gesture.", ["objectivesText"] = "Collect the shards of Sarkareth's signet. Progress: <Emberthal is in no mood to speak just yet.>", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.499, ["y"] = 0.709, ["mapID"] = 2174, ["npcID"] = 202928 } }, ["ends"] = { { ["x"] = 0.499, ["y"] = 0.709, ["mapID"] = 2174, ["npcID"] = 202928 } }, ["coords"] = { ["mapID"] = 2174, ["x"] = 0.499, ["y"] = 0.709 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 202928, ["questTurnInID"] = 202928, ["questType"] = "standard", ["sourceQuests"] = { 75018 }, ["questLines"] = { { ["id"] = 1397, ["name"] = "A Flame, Extinguished", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 67, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2600, ["db2PoiUiMapID"] = 2174 },
[75029] = { ["id"] = 75029, ["name"] = "A Legacy, Reforged", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 74521, 74522, 74523, 74525, 75018, 75028, 75029, 75417 }, ["description"] = "Grief is a painful burden to bear. It warms my heart to see Emberthal emerge from her sorrow and focus on her people. The pain of her loss will ebb, in due time. We need to inform Alexstrasza and the others of what has transpired here... and of the future of the black dragonflight. With all that you have done to ensure that we have a chance at a future, I would like you to be there.", ["objectivesText"] = "Meet Ebyssian at the Seat of the Aspects in Valdrakken. Progress: We shall see you there, <name>.", ["rewardXP"] = 1770, ["rewardItems"] = { 206006 }, ["starts"] = { { ["x"] = 0.499, ["y"] = 0.709, ["mapID"] = 2174, ["npcID"] = 202928 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 203011, ["x"] = 0.584, ["y"] = 0.395 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.395 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questGiverID"] = 202928, ["questType"] = "standard", ["sourceQuests"] = { 75028 }, ["questLines"] = { { ["id"] = 1397, ["name"] = "A Flame, Extinguished", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 68, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
