[75154] = { ["id"] = 75154, ["name"] = "Waygate: Morqut Islet", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13644, ["mapID"] = 2022, ["description"] = "We have access tae The Forbidden Reach now, and Cataloger Daela is already waitin' fer ya there. She's sent me a word of a very promising spire not far from the village where she's stayin'. Think there might be another dormant Waygate around? Go on an' find out!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["npcID"] = 189066, ["x"] = 0.472, ["y"] = 0.902, ["mapID"] = 2022 } }, ["ends"] = { { ["npcID"] = 189066, ["x"] = 0.472, ["y"] = 0.902, ["mapID"] = 2022 } }, ["coords"] = { ["x"] = 0.472, ["y"] = 0.902, ["source"] = "quest_giver", ["mapID"] = 2022 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 75444 } },
