[75230] = { ["id"] = 75230, ["name"] = "Reconcilable Dissidents", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72411, 72412, 72413, 72414, 72415, 72416, 72417, 72418, 72419, 72420, 72421, 72422, 75230 }, ["description"] = "My hope, <name>, is that our work to understand the rebels will allow us to find a path to peace. My concern is if we are not able to come to an understanding with Belaphon, other rebels may see her as a martyr for the cause. Whatever happens, you have my gratitude for your assistance throughout this rebellion.", ["objectivesText"] = "Listen to Alexstrasza's conversation with Instigator Belaphon. Progress: I hope Belaphon can see the way forward for Dragonkin.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 200839, ["x"] = 0.765, ["y"] = 0.335 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 200839, ["x"] = 0.765, ["y"] = 0.335 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.765, ["y"] = 0.335 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 72420, 72421, 72422 }, ["questLines"] = { { ["id"] = 5368, ["name"] = "Rebel Resurgence", ["orderIndex"] = 12, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
