[75237] = { ["id"] = 75237, ["name"] = "Reach West", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14433, ["description"] = "You and your drakes seem to enjoy your adventures in Forbidden Reach, don't you? I heard the windstreams in the western Forbidden Reach are especially good today. Why don't you try a few courses out there?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardCurrencies"] = { { ["id"] = 2118, ["amount"] = 450 } }, ["starts"] = { { ["npcID"] = 200563, ["x"] = 0.34, ["y"] = 0.598, ["zoneID"] = 14433 } }, ["ends"] = { { ["npcID"] = 200563, ["x"] = 0.34, ["y"] = 0.598, ["zoneID"] = 14433 } }, ["coords"] = { ["x"] = 0.34, ["y"] = 0.598, ["source"] = "quest_giver", ["zoneID"] = 14433 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 74911 } },
