[75244] = { ["id"] = 75244, ["name"] = "Reunited Again", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 72527, 72529, 72530, 72532, 72533, 72534, 72650, 72651, 72652, 72653, 72654, 72655, 72656, 72657, 72659, 72660, 72661, 72670, 72674, 72679, 72831, 72832, 72833, 72900, 72921, 72933, 72934, 72935, 72936, 72937, 72938, 72940, 72942, 72946, 72947, 72948, 72949, 72950, 72951, 72988, 73026, 73069, 73090, 73181, 73188, 73227, 73399, 73404, 73405, 73406, 74291, 74335, 74354, 74356, 74783, 75023, 75244, 91466, 91467 }, ["description"] = "Thanks to you, <name>, all of the blue dragons are accounted for. We can get back to caring for Azeroth's magic and making sure its power isn't abused. I believe a speech is in order. I would be honored if you would stay for it. We can head to the Nexus afterwards to see what Azuregos has discovered about Sindragosa and Malygos's arcane memories.", ["objectivesText"] = "Listen to Kalecgos 's speech. Progress: It is good to see so many blue dragons returned.", ["rewardGold"] = 28900, ["rewardXP"] = 615, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 73181, 74291, 74335, 74356, 74783 }, ["questLines"] = { { ["id"] = 1404, ["name"] = "United Again", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5955, ["name"] = "The Blue Dragons", ["orderIndex"] = 58, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 209, ["title"] = "Blue Dragonflight", ["questLineID"] = 1404, ["questLineOrder"] = 6 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5955, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[75258] = { ["id"] = 75258, ["name"] = "A Final Word", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13645, ["mapID"] = 2023, ["description"] = "I have sent a message to Mayla in Valdrakken, relaying what has happened here. I suspect she will be relieved to hear from me... and in knowing she was right to send you. Before you leave, I would like to speak with you a moment.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 203679, 203725, 204084 }, ["rewardCurrencies"] = { { ["id"] = 2003, ["amount"] = 50 } }, ["starts"] = { { ["npcID"] = 201566, ["x"] = 0.726, ["y"] = 0.56, ["mapID"] = 2023 } }, ["ends"] = { { ["npcID"] = 201566, ["x"] = 0.726, ["y"] = 0.56, ["mapID"] = 2023 } }, ["coords"] = { ["x"] = 0.726, ["y"] = 0.56, ["source"] = "quest_giver", ["mapID"] = 2023 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 72611 }, ["questLines"] = { { ["id"] = 1407, ["name"] = "Old Hatreds", ["orderIndex"] = 19, ["flags"] = 0 } } },
[75259] = { ["id"] = 75259, ["name"] = "Aiding the Accord: Zskera Vaults", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["description"] = "Our allies once again seek your assistance as our efforts continue across the Isles. Words within the walls of Valdrakken whisper a resounding comfort knowing your efforts have helped shape our future. Now then, to business. Pathfinders of the Dragonscale Expedition are delving deeper into the Zskera Vaults on the Forbidden Reach. They are asking for brave adventurers to help them explore these new mysteries. We await your return, .", ["rewardXP"] = 14275, ["rewardItems"] = { 200073, 201921, 201922, 201923, 201924 }, ["rewardCurrencies"] = { { ["id"] = 2031, ["amount"] = 500 }, { ["id"] = 2106, ["amount"] = 500 }, { ["id"] = 2108, ["amount"] = 500 }, { ["id"] = 2109, ["amount"] = 500 } }, ["starts"] = { { ["npcID"] = 196499, ["x"] = 0.502, ["y"] = 0.56, ["mapID"] = 2112 } }, ["ends"] = { { ["npcID"] = 196499, ["x"] = 0.502, ["y"] = 0.56, ["mapID"] = 2112 } }, ["coords"] = { ["x"] = 0.502, ["y"] = 0.56, ["source"] = "quest_giver", ["mapID"] = 2112 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 71232, 72366 }, ["questLines"] = { { ["id"] = 1367, ["name"] = "Dragon Isles Emissary", ["orderIndex"] = 7, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 201, ["title"] = "Dragonflight", ["questLineID"] = 1367, ["questLineOrder"] = 0 } } },
