[75360] = { ["id"] = 75360, ["name"] = "Subterrax", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "daily", "elite" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75360 }, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 1, ["objectID"] = 203662 } }, ["db2QuestInfoID"] = 111, ["db2QuestInfoName"] = "Elite World Quest" },
[75362] = { ["id"] = 75362, ["name"] = "Cephalo-crystalization", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14022, ["mapID"] = 2112, ["storyline"] = { 75362 }, ["description"] = "Well, hello there! Have you seen those snails in Zaralek Cavern with the crystals growing from their shells? When crushed to powder and mixed with a proper solution of slime, those crystals make a paste that adds a considerable luster to our gems! Bring some to my good friend Fanilly , and I'm sure she'll be happy to chat your ear off about jewelcrafting!", ["objectivesText"] = "Collect 10 Whelkshell Crystals and deliver them to Fanilly in Loamm. Progress: You know, a good shine on a gemstone is very important to us... we have such a hard time seeing it otherwise!", ["rewardItems"] = { 198612, 204794 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 203516, ["x"] = 0.365, ["y"] = 0.6245 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 203612, ["x"] = 0.566, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.6245 }, ["mapCandidates"] = { ["npc"] = { 2112, 2133 }, ["zone"] = { 14022 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 42 },
[75363] = { ["id"] = 75363, ["name"] = "Deepflayer Dust", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14022, ["mapID"] = 2112, ["storyline"] = { 75363 }, ["description"] = "Why, I just got another letter from my good friend Mistie . She's been looking for interesting ingredient ideas for her smelly concoctions! A while ago, the kithguards took down a deepflayer near Loamm. I noticed a peculiar dust it shed when it perished. It had a unique aroma to it, and I'm sure Mistie would love to experiment with something like that! Could you gather some from the deepflayers near Loamm, then bring it to Miss Mistie ? You'll be doing us a favor, too!", ["objectivesText"] = "Collect 10 Deepflayer Dust and deliver them to Mistie in Loamm. Progress: Such a mysterious musty aroma... the grim note of death alongside the gentleness of soil.", ["rewardItems"] = { 198608, 204796 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 203516, ["x"] = 0.365, ["y"] = 0.6245 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 203607, ["x"] = 0.56, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.6245 }, ["mapCandidates"] = { ["npc"] = { 2112, 2133 }, ["zone"] = { 14022 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 42 },
[75364] = { ["id"] = 75364, ["name"] = "Emberdusk", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "daily", "elite" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75364 }, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 1, ["objectID"] = 203664 } }, ["db2QuestInfoID"] = 111, ["db2QuestInfoName"] = "Elite World Quest" },
