[75367] = { ["id"] = 75367, ["name"] = "The Obsidian Rest", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72987, 74393, 74538, 74539, 74540, 74542, 74557, 74562, 74563, 75367 }, ["series"] = { 72987, 74393 }, ["description"] = "It is a miracle this outpost survived so long after Neltharion's... disappearance. For weeks now local scouts have reported increased djaradin activity in the area. They are amassing an army, and they are also becoming increasingly aggressive in their efforts to expand their territory. We must take every possible precaution and try to understand our enemy's motivations.", ["objectivesText"] = "Gather information and resources at the Obsidian Rest. Progress: These are trying times for all of us.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 204819 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200046, ["x"] = 0.5, ["y"] = 0.275 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200046, ["x"] = 0.5, ["y"] = 0.275 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.275 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 72987 }, ["questLines"] = { { ["id"] = 1395, ["name"] = "Inherited Sin", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 42, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[75368] = { ["id"] = 75368, ["name"] = "Stones and Scales", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14022, ["mapID"] = 2112, ["storyline"] = { 75368 }, ["description"] = "I'm sure you've run into some of the mean beasties we have down in Zaralek while you were on your adventures! Have you seen any rock vipers yet? They're covered in both scales and stones! And have massive fangs! Mister Garram has offered a reward for anyone brave enough to bring him some of their hides! I'm sure he will make it worth your while!", ["objectivesText"] = "Collect 10 Scaly Stone Hides from rock vipers in Zaralek Cavern . Progress: Have you collected those hides yet? Those snakes are a little scary, but I think a <class> like you can handle them!", ["rewardXP"] = 1415, ["rewardItems"] = { 198613, 204800 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 203516, ["x"] = 0.365, ["y"] = 0.6245 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 203644, ["x"] = 0.572, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.6245 }, ["mapCandidates"] = { ["npc"] = { 2112, 2133 }, ["zone"] = { 14022 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 42 },
[75369] = { ["id"] = 75369, ["name"] = "Use Your Coin!", ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 75369 }, ["description"] = "Use that coin on the Warcraft Rumble machine over there.", ["objectivesText"] = "Use that coin on the Warcraft Rumble machine over there.", ["rewardItems"] = { 202162, 202163, 204731 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13862 } }, ["questType"] = "standard" },
