[75398] = { ["id"] = 75398, ["name"] = "Honor the Flame", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13644, ["mapID"] = 2022, ["description"] = "The Midsummer Fire Festival is a time to honor the elements. The element of fire stirs passion within us all. Many times, that passion pours out into aggressive actions. But here, in this land, we focus our passion on reverence. We will honor the flame as tradition dictates. Will you honor the flame with us, ?", ["rewardGold"] = 154900, ["rewardXP"] = 100, ["rewardItems"] = { 23247 }, ["starts"] = { { ["npcID"] = 203749, ["x"] = 0.46, ["y"] = 0.828, ["mapID"] = 2022 } }, ["ends"] = { { ["npcID"] = 397992, ["x"] = 0.46, ["y"] = 0.828, ["mapID"] = 2022 } }, ["coords"] = { ["x"] = 0.46, ["y"] = 0.828, ["source"] = "quest_giver", ["mapID"] = 2022 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[75407] = { ["id"] = 75407, ["name"] = "Silk Scavenging", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 75407 }, ["description"] = "Hello friend! You're a tailor, right? So you must know about silk! Mister Rossmar down in Loamm knows how to make special silk from the cocoons of the Underlight Moths, but could use some help gathering them up! You should be able to find them in the mushroomy area near Glimmerogg. I'll sure he will make it worth your while!", ["objectivesText"] = "Collect 10 Underlight Cocoons Fibers in Zaralek Cavern . Progress: Hey, uplander! Do you have those cocoons yet?", ["rewardItems"] = { 198609, 204817 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 203516, ["x"] = 0.365, ["y"] = 0.6245 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 203608, ["x"] = 0.56, ["y"] = 0.566 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.6245 }, ["mapCandidates"] = { ["npc"] = { 2112, 2133 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 42 },
[75408] = { ["id"] = 75408, ["name"] = "Calling All Dracthyr!", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["requiredRaces"] = { 52, 70 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 75408 }, ["description"] = "<This flyer is illustrated with inviting sketches of dracthyr eating, sparring, and having fun.> Calling all dracthyr! Do you feel adrift after the events of the underground? Do you want to bond with your creche mates? Do you just need someone to talk to? Come join us at Weyrnrest for food, fun, and camaraderie! ALL dracthyr welcome!", ["objectivesText"] = "Go to the party at Weyrnrest in Valdrakken .", ["rewardGold"] = 280900, ["rewardXP"] = 4925, ["starts"] = { { ["x"] = 0.551, ["y"] = 0.4, ["mapID"] = 2112, ["objectID"] = 398674 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 201766, ["x"] = 0.24, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.24, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 75417 } },
