[75440] = { ["id"] = 75440, ["name"] = "Satiating Sharpbeak", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75440 }, ["description"] = "Sheridon Hastle was our flight master and Sharpbeak 's rider. After his death, she won't let anyone touch her. <Narvra clutches her side in pain.> Or feed her. Rupert tried but... she just won't. The rest of us are too injured to move... I'm worried about her. Can you... ow... try? Someone new may get through to her. Her feed is in the bag by the tent. And... if you can get her to accept food, she might let you ride her.", ["objectivesText"] = "Feed Sharpbeak in the Dragonscale Camp in Zaralek Cavern . Progress: < Sharpbeak looks at you mournfully.>", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 205217 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200953, ["x"] = 0.4655, ["y"] = 0.4805 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200300, ["x"] = 0.402, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.4655, ["y"] = 0.4805 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 75145 } },
