[75456] = { ["id"] = 75456, ["name"] = "News From Beneath", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["description"] = "Before I arrived, I was informed that the Life-Binder has need of our aid. There is news of the Incarnates, and she requests our presence at the Seat of the Aspects. As for Emberthal -- there is very little we can do for now. It is best we allow her to reflect and gather thoughts alone.", ["rewardGold"] = 77400, ["rewardXP"] = 355, ["starts"] = { { ["npcID"] = 200277, ["x"] = 0.768, ["y"] = 0.382, ["zoneID"] = 14433 } }, ["ends"] = { { ["npcID"] = 201281, ["x"] = 0.612, ["y"] = 0.42, ["mapID"] = 2112 } }, ["coords"] = { ["x"] = 0.768, ["y"] = 0.382, ["source"] = "quest_giver", ["mapID"] = 2112 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 72717 }, ["questLines"] = { { ["id"] = 1392, ["name"] = "Breaking Ground", ["orderIndex"] = 1, ["flags"] = 0 } } },
