[75622] = { ["id"] = 75622, ["name"] = "Calling All Competitors!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["description"] = "The Artisan's Consortium has struck a deal with the quartermasters of the Gladiator's Refuge! In addition to the usual selection of powerful combat equipment they offer, worthy combatants can now purchase tokens that can be used in Crafting Orders or one's own crafts to certify the equipment for use in battlegrounds and arenas! Present this flier to Calderax to receive two complimentary Trophies of Conquest, on us! - Rabul", ["rewardItems"] = { 204187, 204186 }, ["ends"] = { { ["npcID"] = 199599, ["x"] = 0.444, ["y"] = 0.368, ["mapID"] = 2112 } }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[75625] = { ["id"] = 75625, ["name"] = "Wanna Play a Game?", ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 75625 }, ["series"] = { 75709 }, ["description"] = "<You open a scribbled note.> Heya pal! The name's Mizzen , and I hear you're pretty good at findin' stuff. See, I've been playin' this new game called Warcraft Rumble but I'm fresh outta coins. How about we meet up and I'll tell you where to find some?", ["objectivesText"] = "Speak with Mizzen at the Stormwind Harbor.", ["rewardItems"] = { 205189 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 201230, ["x"] = 0.423333, ["y"] = 0.468333 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.423333, ["y"] = 0.468333 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["startItems"] = { 205189 } },
[75626] = { ["id"] = 75626, ["name"] = "Wanna Play a Game?", ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 75626 }, ["series"] = { 75711 }, ["description"] = "<You open a scribbled note.> Heya pal! The name's Mizzen , and I hear you're pretty good at findin' stuff. See, I've been playin' this new game called Warcraft Rumble but I'm fresh outta coins. How about we meet up and I'll tell you where to find some?", ["objectivesText"] = "Speak with Mizzen in Orgrimmar 's Valley of Strength.", ["rewardItems"] = { 205190 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 201230, ["x"] = 0.423333, ["y"] = 0.468333 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.423333, ["y"] = 0.468333 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["startItems"] = { 205190 } },
[75632] = { ["id"] = 75632, ["name"] = "A Dislocated Disc", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 75632, 75633, 75634, 75635, 75636, 75637, 75638, 75950, 75951, 75952, 75953, 76171, 76176 }, ["description"] = "As a gesture of good will, Eternus has pledged her assistance in finding the disc that contains Tyr's memories. The infinites have devices that can aid in divining its location. To quote Eternus , \"This is a mess Deios made. It is fair we help clean it up.\" I feel some responsibility as well after our attempt to wake Tyr with the Silver Scale. Meet Eternus at Tyrhold. She will brief you on her progress. Perhaps now our old friend will finally join us once more.", ["objectivesText"] = "Meet Eternus in Tyrhold.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 208198, 208200 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 187669, ["x"] = 0.610286, ["y"] = 0.389143 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 204574, ["x"] = 0.604, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.610286, ["y"] = 0.389143 }, ["mapCandidates"] = { ["npc"] = { 2025, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 72444 }, ["questLines"] = { { ["id"] = 5455, ["name"] = "Reforging the Tyr's Guard", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 5455, ["questLineOrder"] = 2 }, { ["id"] = 234, ["title"] = "Catching Up!", ["questLineID"] = 5455, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[75633] = { ["id"] = 75633, ["name"] = "We Have the Technology", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75632, 75633, 75634, 75635, 75636, 75637, 75638, 75950, 75951, 75952, 75953, 76171, 76176 }, ["description"] = "During our... long discussion about how to find Tyr's disc, Chromie and I agreed that you were the right person to help us, <name>. But finding the location of Tyr's disc could be very dangerous and would likely require more than just your help. While I work here to narrow down what we need to find the disc, Chromie can give you more details.", ["objectivesText"] = "Ask Chromie about the plan to recover Tyr's memory disc.", ["rewardGold"] = 84900, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 204574, ["x"] = 0.604, ["y"] = 0.59 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 204577, ["x"] = 0.604, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 75632 }, ["questLines"] = { { ["id"] = 5455, ["name"] = "Reforging the Tyr's Guard", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 5455, ["questLineOrder"] = 2 }, { ["id"] = 234, ["title"] = "Catching Up!", ["questLineID"] = 5455, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[75634] = { ["id"] = 75634, ["name"] = "Reforging the Tyr's Guard", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75632, 75633, 75634, 75635, 75636, 75637, 75638, 75950, 75951, 75952, 75953, 76171, 76176 }, ["description"] = "After the tomb was destroyed and the Silver Scale failed to bring Tyr back, I made the decision to rededicate my life to Tyr. And I made the even harder decision to leave the past behind and reforge Tyr's Guard. I had faith Tyr would need me again soon. And, after consulting with the Silver Hand, Koranos and I believe we have found four worthy Tyr's Guard recruits. Come with me to Brackenhide Hollow, and assist me in their final training. Then we can venture into the timeways to find Tyr's disc.", ["objectivesText"] = "Meet Travard at the Tyr's Guard camp in Brackenhide Hollow.", ["rewardGold"] = 70225, ["rewardXP"] = 355, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 204577, ["x"] = 0.604, ["y"] = 0.59 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 206221, ["x"] = 0.176, ["y"] = 0.315 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = { 2024, 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 75633 }, ["questLines"] = { { ["id"] = 5455, ["name"] = "Reforging the Tyr's Guard", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 5455, ["questLineOrder"] = 2 }, { ["id"] = 234, ["title"] = "Catching Up!", ["questLineID"] = 5455, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[75635] = { ["id"] = 75635, ["name"] = "For Tyr!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 75632, 75633, 75634, 75635, 75636, 75637, 75638, 75950, 75951, 75952, 75953, 76171, 76176 }, ["description"] = "Did they all complete their trials successfully? Good. I'm sure you played no small part in that. There's one final step we need to take before I can formally induct our recruits as full-fledged members of the Tyr's Guard: the Tyr's Guard initiation ceremony. It would make me proud if you stood with us on the steps of Tyrhold as I formally reforge the Tyr's Guard. Will you join us?", ["objectivesText"] = "Witness the induction ceremony of the Tyr's Guard on the steps of Tyrhold.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 199197, 201302, 201303, 201304, 201305, 201306, 201307, 201308, 201309, 208198 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 206221, ["x"] = 0.176, ["y"] = 0.315 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 208968, ["x"] = 0.598, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.176, ["y"] = 0.315 }, ["mapCandidates"] = { ["npc"] = { 2024, 2025 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 75950, 75951, 75952, 75953 }, ["questLines"] = { { ["id"] = 5455, ["name"] = "Reforging the Tyr's Guard", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 5455, ["questLineOrder"] = 2 }, { ["id"] = 234, ["title"] = "Catching Up!", ["questLineID"] = 5455, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[75636] = { ["id"] = 75636, ["name"] = "Tyrangulation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75632, 75633, 75634, 75635, 75636, 75637, 75638, 75950, 75951, 75952, 75953, 76171, 76176 }, ["description"] = "The portals are ready. The sooner your team deploys those beacons, the sooner we can get the location of the disc. How you deploy your forces is up to you--and Travard.", ["objectivesText"] = "Protect Travard at the Temple of Order.", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 204667, ["x"] = 0.604, ["y"] = 0.588 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 206686, ["x"] = 0.604, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.588 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 76176 }, ["questLines"] = { { ["id"] = 5455, ["name"] = "Reforging the Tyr's Guard", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 5455, ["questLineOrder"] = 2 }, { ["id"] = 234, ["title"] = "Catching Up!", ["questLineID"] = 5455, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[75637] = { ["id"] = 75637, ["name"] = "The Final Beacon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75632, 75633, 75634, 75635, 75636, 75637, 75638, 75950, 75951, 75952, 75953, 76171, 76176 }, ["description"] = "Valunei and Talthis still aren't back. They must have had trouble with their beacon. We can't find the disc without it, and there's no way to help from here. We must lead the Tyr's Guard through their portal to help. Are you ready, <name>?", ["objectivesText"] = "Help the Tyr's Guard activate the Final Beacon. Progress: We must discover what was happened.", ["rewardGold"] = 842700, ["rewardXP"] = 2125, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 206682, ["x"] = 0.604, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 204605, ["x"] = 0.604, ["y"] = 0.588 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 75636 }, ["questLines"] = { { ["id"] = 5455, ["name"] = "Reforging the Tyr's Guard", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 5455, ["questLineOrder"] = 2 }, { ["id"] = 234, ["title"] = "Catching Up!", ["questLineID"] = 5455, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[75638] = { ["id"] = 75638, ["name"] = "Dislocated Disc Located", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75632, 75633, 75634, 75635, 75636, 75637, 75638, 75950, 75951, 75952, 75953, 76171, 76176 }, ["description"] = "We were successful, <name>, but we barely made it back from our battle with the Black Empire. Eternus is still divining the location of the disc, and while she does, I'd like to ask a favor. I have unwavering faith in my recruits, but... I am worried about Valunei . I would speak to her, but I don't want it to appear as though I think she has failed us. Talk to her and make sure she's all right. It may also be a good idea to check in with the rest of Tyr's Guard as well.", ["objectivesText"] = "Check in with the Tyr's Guard. Progress: I'm worried about my recruits, but maybe I should be worried about myself. Reforming the Tyr's Guard has been a kind of catharsis. But I'm worried that it may be too much so. I was devastated by the loss of my comrades in the Tyr's Guard... I worry that I may be pushing them too hard. Or myself. I've been at this a long time, <name>. But to see Tyr alive once more... that gives me purpose. I just hope wisdom comes with my age, and I do right by my new recruits. And that they all come home.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 208200 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 204605, ["x"] = 0.604, ["y"] = 0.588 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 204605, ["x"] = 0.604, ["y"] = 0.588 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.588 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 75637 }, ["questLines"] = { { ["id"] = 5455, ["name"] = "Reforging the Tyr's Guard", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 5455, ["questLineOrder"] = 2 }, { ["id"] = 234, ["title"] = "Catching Up!", ["questLineID"] = 5455, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[75639] = { ["id"] = 75639, ["name"] = "Fel Suspicions", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 5861, ["mapID"] = 407, ["storyline"] = { 75538, 75539, 75540, 75541, 75542, 75543, 75544, 75639, 76155, 76163, 76410, 76427, 76430 }, ["description"] = "At the risk of stating the obvious, something very wrong is going on. I know you feel it too. Madam Shadow is sending myself and the other initiates to the Altar of Storms, to try our hand at summoning demons. Please, $p, poke your head around here and see if you can't piece together what she's up to. I saw her and her servant heading towards the back of the faire... I'm sure she has her guard up. Maybe there's some way you can get close without drawing attention to yourself?", ["objectivesText"] = "Spy on Madam Shadow and Assistant Phineas in the Darkmoon Faire.", ["rewardGold"] = 140450, ["rewardXP"] = 2060, ["starts"] = { { ["x"] = 0.589, ["y"] = 0.631, ["mapID"] = 407, ["npcID"] = 205433 } }, ["ends"] = { { ["x"] = 0.589, ["y"] = 0.631, ["mapID"] = 407, ["npcID"] = 205433 } }, ["coords"] = { ["mapID"] = 407, ["x"] = 0.589, ["y"] = 0.631 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questGiverID"] = 205433, ["questTurnInID"] = 205433, ["questType"] = "standard", ["sourceQuests"] = { 75542 }, ["questLines"] = { { ["id"] = 5383, ["name"] = "Some Wicked Things", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 974, ["db2PoiUiMapID"] = 407 },
[75640] = { ["id"] = 75640, ["name"] = "Honor the Flame", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13646, ["mapID"] = 2024, ["description"] = "The Midsummer Fire Festival is a time to honor the elements. The element of fire stirs passion within us all. Many times, that passion pours out into aggressive actions. But here, in this land, we focus our passion on reverence. We will honor the flame as tradition dictates. Will you honor the flame with us, ?", ["rewardGold"] = 154900, ["rewardXP"] = 100, ["rewardItems"] = { 23247 }, ["starts"] = { { ["npcID"] = 204414, ["x"] = 0.122, ["y"] = 0.476, ["mapID"] = 2024 } }, ["ends"] = { { ["npcID"] = 401141, ["x"] = 0.122, ["y"] = 0.476, ["mapID"] = 2024 } }, ["coords"] = { ["x"] = 0.122, ["y"] = 0.476, ["source"] = "quest_giver", ["mapID"] = 2024 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[75643] = { ["id"] = 75643, ["name"] = "Orientation: Loamm Niffen", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72872, 72873, 72874, 72970, 72973, 72974, 72975, 72976, 72977, 72978, 72979, 72980, 72981, 75456, 75643, 75644 }, ["description"] = "I'm impressed. Elder Honeypelt speaks highly of you--and that's rare! Your friends Ebyssian and Emberthal admittedly made similar impressions with us after we caught their scent. They told me of your hunt for the fiery monster that's invaded Zaralek from the uplands. A worthy reason to become allies. But we'll need a bit more time to discuss it. Why not take a short break to meet with my people. Trade, leisure, travel--there's no shortage of ways to spend your time here in Loamm!", ["objectivesText"] = "Meet the Flight Master in Loamm. Progress: Smells around every corner, but nothing dangerous!", ["rewardGold"] = 280900, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 204522, ["x"] = 0.57, ["y"] = 0.556 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200052, ["x"] = 0.561333, ["y"] = 0.554667 }, { ["mapID"] = 2133, ["npcID"] = 204522, ["x"] = 0.57, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 72973 }, ["questLines"] = { { ["id"] = 1392, ["name"] = "Breaking Ground", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[75644] = { ["id"] = 75644, ["name"] = "Six Hundred Feet Under", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 72872, 72873, 72874, 72970, 72973, 72974, 72975, 72976, 72977, 72978, 72979, 72980, 72981, 75456, 75643, 75644 }, ["description"] = "That was just a taste of the niffen lifestyle. There's still far more to Loamm and even more from Zaralek Cavern . Continue exploring while you pursue the fiery monster, and let its scents continue to amaze you! For now, Ebyssian asked that I send you his way. Seems your companions are planning what to do next.", ["objectivesText"] = "Discuss the next plan of action with Ebyssian . Progress: There is much to discuss.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200052, ["x"] = 0.561333, ["y"] = 0.554667 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201366, ["x"] = 0.557, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.561333, ["y"] = 0.554667 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 72974, 75643 }, ["questLines"] = { { ["id"] = 1392, ["name"] = "Breaking Ground", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 5957, ["name"] = "Zaralek Cavern", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5957, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[75645] = { ["id"] = 75645, ["name"] = "Honor the Flame", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["description"] = "The Midsummer Fire Festival is a time to honor the elements. The element of fire stirs passion within us all. Many times, that passion pours out into aggressive actions. But here, in this land, we focus our passion on reverence. We will honor the flame as tradition dictates. Will you honor the flame with us, ?", ["rewardGold"] = 154900, ["rewardXP"] = 100, ["rewardItems"] = { 23247 }, ["starts"] = { { ["npcID"] = 204415, ["x"] = 0.532, ["y"] = 0.62, ["mapID"] = 2112 } }, ["ends"] = { { ["npcID"] = 401234, ["x"] = 0.535, ["y"] = 0.622, ["mapID"] = 2112 } }, ["coords"] = { ["x"] = 0.532, ["y"] = 0.62, ["source"] = "quest_giver", ["mapID"] = 2112 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[75647] = { ["id"] = 75647, ["name"] = "Honor the Flame", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13642, ["mapID"] = 2151, ["description"] = "The Midsummer Fire Festival is a time to honor the elements. The element of fire stirs passion within us all. Many times, that passion pours out into aggressive actions. But here, in this land, we focus our passion on reverence. We will honor the flame as tradition dictates. Will you honor the flame with us, ?", ["rewardGold"] = 154900, ["rewardXP"] = 100, ["rewardItems"] = { 23247 }, ["starts"] = { { ["npcID"] = 204416, ["x"] = 0.35, ["y"] = 0.608, ["zoneID"] = 14433 } }, ["ends"] = { { ["npcID"] = 401235, ["x"] = 0.349, ["y"] = 0.609, ["zoneID"] = 14433 }, { ["npcID"] = 401235, ["x"] = 0.623, ["y"] = 0.123, ["zoneID"] = 13642 } }, ["coords"] = { ["x"] = 0.35, ["y"] = 0.608, ["source"] = "quest_giver", ["zoneID"] = 14433 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13642 } }, ["questType"] = "standard" },
[75657] = { ["id"] = 75657, ["name"] = "Time-Lost Trio", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13645, ["mapID"] = 2025, ["storyline"] = { 75657 }, ["description"] = "We have a teensy problem I could use your help with. But it's... complicated. Some time ago, King Varian Wrynn was in a gladiator trio with Broll Bearmantle and Valeera Sanguinar . Those three just showed up in this 'Field of Ferocity' place and they're not only taking on all challengers, they're beating them too! They won't return through our portals until they lose. Do you think you could find some friends and defeat them? We'll be able to convince them to go back if you can, I'm sure of it!", ["objectivesText"] = "Defeat Valeera, Broll, and Lo'Gosh. Progress: You need to speak with Gurgthock to start the round, then defeat the time-lost gladiators.", ["rewardGold"] = 561800, ["rewardXP"] = 11895, ["rewardItems"] = { 207002 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 205424, ["x"] = 0.522, ["y"] = 0.816 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188871, ["x"] = 0.532, ["y"] = 0.372 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.816 }, ["mapCandidates"] = { ["npc"] = { 2023, 2025 }, ["zone"] = { 13645 } }, ["questType"] = "group", ["db2LabelIDs"] = { 2705 } },
