[75709] = { ["id"] = 75709, ["name"] = "Find a Rumble Coin", ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 84, ["storyline"] = { 75709 }, ["series"] = { 75625 }, ["description"] = "To use this game machine, you need a Rumble Coin . There are a bunch of coins hidden all around the Dragon Isles. We'll chat about those later. I stashed one coin here at the docks. If you find it, it's all yours, pal. Insert that Rumble Coin into the Rumble machine and watch the fun begin!", ["objectivesText"] = "Find a Rumble Coin in Stormwind Harbor and insert it into the Warcraft Rumble machine . Progress: <The Warcraft Rumble machine stands before you. A small sign reads:> Insert Rumble Coin to play.", ["rewardItems"] = { 202162, 202163 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 201230, ["x"] = 0.423333, ["y"] = 0.468333 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 201230, ["x"] = 0.423333, ["y"] = 0.468333 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.423333, ["y"] = 0.468333 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 13862 } }, ["questTurnInID"] = 201230, ["questType"] = "standard" },
