[75720] = { ["id"] = 75720, ["name"] = "Care to Barter?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75720 }, ["description"] = "Hey, Uplander! I hear you like helping. Maybe you could help me out? I need some packages sent to Valdrakken. If you don't peek and don't ask, I can make it worthwhile. Stop by when you're in Loamm. We can work out a deal! Your new friend, Ponzo .", ["objectivesText"] = "Talk to Ponzo in Loamm.", ["rewardGold"] = 16980, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 205127, ["x"] = 0.564, ["y"] = 0.566 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 204693, ["x"] = 0.58, ["y"] = 0.538 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.566 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["nextQuests"] = { 75721 } },
[75721] = { ["id"] = 75721, ["name"] = "Bartering 101", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75721 }, ["description"] = "So here's what I need you to do. A friend of mine, Kayann , went all the way up to Valdrakken . He's expecting a delivery from me. Can you get it to him? No questions, though. Don't look, don't smell, don't taste. This is for Kayann 's nose only! If that's all right with you, I'll send you on your way--with my thanks, of course!", ["objectivesText"] = "Deliver Ponzo 's box to Kayann in Valdrakken .", ["rewardItems"] = { 204985 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 204693, ["x"] = 0.58, ["y"] = 0.538 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 203516, ["x"] = 0.365, ["y"] = 0.6245 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.538 }, ["mapCandidates"] = { ["npc"] = { 2112, 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 75720 } },
[75722] = { ["id"] = 75722, ["name"] = "Bag of Gold", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75722 }, ["description"] = "Hello, $p! I heard you've been helping us out! Good deeds should be rewarded--and I've got something special for you! Why don't you meet me in Loamm? Keep up the good work, Mimuup", ["objectivesText"] = "Talk to Mimuup in Loamm.", ["rewardItems"] = { 204195 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 205127, ["x"] = 0.564, ["y"] = 0.566 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 204254, ["x"] = 0.565, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.566 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[75723] = { ["id"] = 75723, ["name"] = "Cavern Drakewatching", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75723 }, ["description"] = "Well hey there, Uplander! Word is, you've been helping us out a lot! We got a little something for you in return. See me in Loamm and I'll hand it over! Best, Harlowe Marl", ["objectivesText"] = "Talk to Harlowe Marl in Loamm.", ["rewardItems"] = { 203310, 203316, 203327 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 205127, ["x"] = 0.564, ["y"] = 0.566 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 202468, ["x"] = 0.564, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.566 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[75724] = { ["id"] = 75724, ["name"] = "Like the Niffen Do", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75724 }, ["description"] = "Hello there, $p! We want to thank you for all the help you've given us. It's only right! Meet me in Loamm and I'll teach you to dig like we niffen do! Sincerely, Mimuup", ["objectivesText"] = "Talk to Mimuup in Loamm.", ["rewardItems"] = { 205255 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 205127, ["x"] = 0.564, ["y"] = 0.566 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 204254, ["x"] = 0.565, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.566 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[75725] = { ["id"] = 75725, ["name"] = "Off to the Track", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75725 }, ["description"] = "Hey Champ! We got a fresh golden opportunity for you. Snail racing! One of the most dynamic sports in the games! Ponzo said you'd be interested. Called you a real go-getter! So go! Get to the track in Glimmerogg! See ya there, Briggul", ["objectivesText"] = "Talk to Briggul in Glimmerogg.", ["rewardGold"] = 303800, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 205127, ["x"] = 0.564, ["y"] = 0.566 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201752, ["x"] = 0.442, ["y"] = 0.8 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.566 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[75726] = { ["id"] = 75726, ["name"] = "Sweaty Armor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75726 }, ["description"] = "Well hey there, friend! Word is starting to spread about your continued support! We found some armor that might help you out, in thanks for all your troubles. Make sure to swing by Loamm so we can get you situated. Best, Harlowe Marl See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(75726)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(75726))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["objectivesText"] = "Talk to Harlowe Marl in Loamm.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[75727] = { ["id"] = 75727, ["name"] = "The Smelliest Tabard", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75727 }, ["description"] = "Greetings, $p! You just keep doing us amazing favors, don't you? Come on back to Loamm for an extra special reward! Sincerely, Mimuup", ["objectivesText"] = "Talk to Mimuup in Loamm.", ["rewardItems"] = { 205286 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 205127, ["x"] = 0.564, ["y"] = 0.566 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 204254, ["x"] = 0.565, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.566 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[75728] = { ["id"] = 75728, ["name"] = "Bartering Boulders", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75728 }, ["description"] = "Oh hey, Uplander! I could use your help again. I like your battering style. But you know these bricks? They're useless! Boulders are where it's at! Come see me in Loamm, and I'll give you all the details. Ponzo", ["objectivesText"] = "Talk to Ponzo in Loamm.", ["rewardItems"] = { 204985, 205188 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 205127, ["x"] = 0.564, ["y"] = 0.566 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 204693, ["x"] = 0.58, ["y"] = 0.538 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.566 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[75729] = { ["id"] = 75729, ["name"] = "Attune to the Observer", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "Can you believe this used to be an observatory? Our records indicate that the dragonkin here were mapping heavenly bodies in an attempt to predict the future. How do you think they did it? I'm picking up a partial signature that matches the time window we're shooting for. Put on the Technoscryers and try to pinpoint the sources so we can dial it in.", ["objectivesText"] = "Technoscry for the three attunement relics. Progress: Without those attunement relics we won't be able to solve this mystery, <name>.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 202247 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 204835, ["x"] = 0.564, ["y"] = 0.44 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 204835, ["x"] = 0.564, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 77434 }, ["questLines"] = { { ["id"] = 5469, ["name"] = "Azerothian Archives - Technoscrying Sites", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5515, ["name"] = "Technoscrying: Concord Observatory", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 12, ["flags"] = 0 } }, ["db2LabelIDs"] = { 3079 }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
