[75859] = { ["id"] = 75859, ["name"] = "Aiding the Accord: Sniffenseeking", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70750, 71232, 72068, 72373, 72374, 72375, 72585, 75259, 75859, 75860, 75861, 77254, 77976, 78446, 78447, 78861, 80385, 80386, 80388, 80389 }, ["description"] = "Our allies once again seek your assistance as our efforts continue across the Isles. Words within the walls of Valdrakken whisper a resounding comfort knowing your efforts have helped shape our future. Now then, to business. Our niffen allies in Zaralek Cavern are always on the lookout for something new and exciting--or smelly. Join them on a dig through the many lost and forgotten caverns in their domain, and see what you find. We await your return, <name>.", ["objectivesText"] = "Travel to Zaralek Cavern and accompany Myrrit in Loamm on a dig underground. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles. Progress: Do you bring news of your success?", ["rewardXP"] = 2125, ["rewardItems"] = { 200073, 201921, 201922, 201923, 201924, 202180, 203655, 204867, 205185, 205186, 205202, 205277, 205412, 205689, 205938, 205939, 205941, 205969, 205990, 206000, 206001, 206002 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.5605 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 71232, 72366 }, ["questLines"] = { { ["id"] = 1367, ["name"] = "Dragon Isles Emissary", ["orderIndex"] = 8, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 201, ["title"] = "Dragonflight", ["questLineID"] = 1367, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 3026 }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
[75860] = { ["id"] = 75860, ["name"] = "Aiding the Accord: Researchers Under Fire", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70750, 71232, 72068, 72373, 72374, 72375, 72585, 75259, 75859, 75860, 75861, 77254, 77976, 78446, 78447, 78861, 80385, 80386, 80388, 80389 }, ["description"] = "Our allies once again seek your assistance as our efforts continue across the Isles. Words within the walls of Valdrakken whisper a resounding comfort knowing your efforts have helped shape our future. Now then, to business. Researchers of the Dragonscale Expedition are exploring the depths of Zaralek Cavern. They are asking for brave adventurers to help protect them from the many dangers in that area. We await your return, <name>.", ["objectivesText"] = "Travel to Zaralek Cavern and protect the Researchers Under Fire. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles.", ["rewardXP"] = 2125, ["rewardItems"] = { 200073, 201921, 201922, 201923, 201924, 204076, 207002, 208090, 208945, 208951, 208952 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.5605 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 71232, 72366 }, ["questLines"] = { { ["id"] = 1367, ["name"] = "Dragon Isles Emissary", ["orderIndex"] = 9, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 201, ["title"] = "Dragonflight", ["questLineID"] = 1367, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 3026 }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
[75861] = { ["id"] = 75861, ["name"] = "Aiding the Accord: Suffusion Camp", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13644, ["mapID"] = 2112, ["storyline"] = { 70750, 71232, 72068, 72373, 72374, 72375, 72585, 75259, 75859, 75860, 75861, 77254, 77976, 78446, 78447, 78861, 80385, 80386, 80388, 80389 }, ["description"] = "Ash blows from the south. A dark bargain has been made, <name>, between the djaradin of the Zaqali and Fyrakk. Their forces are building... something. We do not know what their goals are, but they have had no hesitation in displacing anyone and everything in their path. Please, <name>, we need champions like you to undermine these villains and deprive them of their resources. We await your return, <name>.", ["objectivesText"] = "Travel to a Suffusion Camp and loot a Secured Shipment. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles.", ["rewardXP"] = 12250, ["rewardItems"] = { 200073, 201921, 201922, 201923, 201924 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 }, { ["mapID"] = 2022, ["npcID"] = 199336, ["x"] = 0.765, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.5605 }, ["mapCandidates"] = { ["npc"] = { 2022, 2112 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 71232, 72366 }, ["questLines"] = { { ["id"] = 1367, ["name"] = "Dragon Isles Emissary", ["orderIndex"] = 10, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 201, ["title"] = "Dragonflight", ["questLineID"] = 1367, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 3026 }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
[75865] = { ["id"] = 75865, ["name"] = "Relic Rustler", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14022, ["mapID"] = 2112, ["storyline"] = { 75865 }, ["description"] = "A group of mean, scaly uplanders moved in near the old titan ruins south of Loamm and started tearing the place apart. Rude, but they're sure to have uncovered all sorts of ancient titan scraps. And that stuff is almost always magic in some way. Grab some and go see what Dustmonger Topuiz back in Loamm can make of it!", ["objectivesText"] = "Collect 8 Relic Shards . Progress: I can't wait to see what you uncover!", ["rewardItems"] = { 198610, 205449 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 203516, ["x"] = 0.365, ["y"] = 0.6245 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 203172, ["x"] = 0.56, ["y"] = 0.568 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.6245 }, ["mapCandidates"] = { ["npc"] = { 2112, 2133 }, ["zone"] = { 14022 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 40 },
[75867] = { ["id"] = 75867, ["name"] = "A Link to the Past", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "Okay, calibrations complete! Mine too, so I'll be able to see what you see. Let's head over to that telescope and we'll see what we see.", ["objectivesText"] = "Observe the events from the past. Progress: I wonder what we'll find?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 202247 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 204835, ["x"] = 0.564, ["y"] = 0.44 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 204835, ["x"] = 0.564, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 75729 }, ["questLines"] = { { ["id"] = 5469, ["name"] = "Azerothian Archives - Technoscrying Sites", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5515, ["name"] = "Technoscrying: Concord Observatory", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 13, ["flags"] = 0 } }, ["db2LabelIDs"] = { 3079 }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[75868] = { ["id"] = 75868, ["name"] = "A Window into the Future", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "Those lenses are a wondrous integration of technology and arcane artifice. I'm sure we could learn much, and maybe even upgrade my own invention. But first we'll need to find it. You're a dragonrider, right? Can you fly up and recover the lens? It's possible the dreadsqualls still have it in one of their nests.", ["objectivesText"] = "Search Dreadsqualls nests to recover the lens. Progress: Did you recover the lens, <name>?", ["rewardGold"] = 561800, ["rewardXP"] = 11895, ["rewardItems"] = { 205455, 207460 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 204835, ["x"] = 0.564, ["y"] = 0.44 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 204835, ["x"] = 0.564, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 75867 }, ["questLines"] = { { ["id"] = 5469, ["name"] = "Azerothian Archives - Technoscrying Sites", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5515, ["name"] = "Technoscrying: Concord Observatory", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 14, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[75874] = { ["id"] = 75874, ["name"] = "Time to Fly", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 75874 }, ["description"] = "Zandalar is home to many pterrordaxes. One will accompany you into the skies. Visit Beast Master Kalatak at Dazar'alor in Zuldazar.", ["objectivesText"] = "Find Beast Master Kalatak.", ["rewardGold"] = 70225, ["rewardXP"] = 1030, ["rewardItems"] = { 206566, 206567 }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 122696, ["x"] = 0.458, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.362 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard" },
[75877] = { ["id"] = 75877, ["name"] = "Time to Fly", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 75877 }, ["description"] = "Kul Tiras is home to many gryphons. One will accompany you into the skies. Visit Leila Stafford at the Tradewinds Market in Boralus.", ["objectivesText"] = "Find Leila Stafford .", ["rewardGold"] = 73000, ["rewardXP"] = 1030, ["rewardItems"] = { 206566, 206567 }, ["ends"] = { { ["npcID"] = 142073, ["x"] = 0.696, ["y"] = 0.13, ["mapID"] = 1161 } }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[75885] = { ["id"] = 75885, ["name"] = "Get Rich Quick", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75885 }, ["description"] = "Uplander! I have a question for you. Do you want to wear an expensive hat like mine? Own the best snails in town? Enjoy the good life? If the answer is yes, you're ready to make more wealth than you've ever dreamed of! Ponzo style! Together we can both be rich! Of course I'm already rich, but you can be too! Just take these items I have here and show them around town. I'll cut you in for a share of the profits for every order you get.", ["objectivesText"] = "Get the citizens of Loamm to order some Ponzo 's Cream and Glimmerogg Timeshare Vouchers. Progress: Did you get any orders?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 204985, 205188 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 204693, ["x"] = 0.58, ["y"] = 0.538 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 204693, ["x"] = 0.58, ["y"] = 0.538 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.538 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[75887] = { ["id"] = 75887, ["name"] = "Fyrakk's Forces", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14022, ["mapID"] = 2112, ["storyline"] = { 75887 }, ["description"] = "Champion, Fyrakk and his Primalist allies have struck a dark bargain with the djaradin. We have received word that their forces are assaulting the Dragon Isles in search of resources for some nefarious project. Please, champion, find one of these Suffusion Camps and assist any of our allies you can find there.", ["objectivesText"] = "Journey to a Suffusion Camp.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 205647, ["x"] = 0.492667, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 201648, ["x"] = 0.752, ["y"] = 0.692 }, { ["mapID"] = 2024, ["npcID"] = 203520, ["x"] = 0.58, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.492667, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 2023, 2024, 2112 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["nextQuests"] = { 75888 }, ["questLines"] = { { ["id"] = 5478, ["name"] = "Suffusion Camp", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[75888] = { ["id"] = 75888, ["name"] = "Suffusion Camp", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13646, ["mapID"] = 2023, ["storyline"] = { 75888 }, ["description"] = "Fyrakk has made a deal with the dragon hunting djaradin! Their blacksmith, Igira, has sent her finest crafters under the aegis of Fyrakk's Primalists. They are gathering materials for the construction of... something. Find a way to access their Suffusion Crucibles and Molds. Keep what you find but we must learn more about what they are doing. The forces appear to require special wards to access the Crucibles and Molds. Start there.", ["objectivesText"] = "Loot a Suffusion Crucible and a Suffusion Mold. Progress: What have you found in the Crucibles and Molds? All of this shadowflame about makes my scales crawl.", ["rewardGold"] = 842700, ["rewardXP"] = 12250, ["rewardItems"] = { 203430, 203683 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 201648, ["x"] = 0.752, ["y"] = 0.692 }, { ["mapID"] = 2024, ["npcID"] = 203520, ["x"] = 0.58, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 201648, ["x"] = 0.752, ["y"] = 0.692 }, { ["mapID"] = 2024, ["npcID"] = 203520, ["x"] = 0.58, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.752, ["y"] = 0.692 }, ["mapCandidates"] = { ["npc"] = { 2023, 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 75887 } },
[75890] = { ["id"] = 75890, ["name"] = "The Clarion Call", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 4 }, ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 75890, 75891, 76194, 76195, 76196, 76197, 76203, 76205, 76206, 76207, 76212, 76213 }, ["series"] = { 75891, 76194 }, ["description"] = "Good to see you, <name>. I have a message from someone called Arko'narin Starshade . It reads... \"As a protector of the kaldorei, I must ask for you to meet me near the embassy in Stormwind. Tyrande has called the Wardens to action, and Maiev Shadowsong herself requested your aid in this matter as well.\" Arko'narin Starshade", ["objectivesText"] = "Speak with Arko'narin Starshade near the Stormwind Embassy in Stormwind City. Provided item:", ["rewardGold"] = 31900, ["rewardXP"] = 850, ["rewardItems"] = { 170063, 174077, 203176, 206942, 208476, 210054, 218105, 218118, 218119, 242520, 264334 }, ["starts"] = { { ["x"] = 0.524, ["y"] = 0.142, ["mapID"] = 84, ["objectID"] = 405958 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 207353, ["x"] = 0.525, ["y"] = 0.045 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.045 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5399, ["name"] = "Night Elf Heritage Armor", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 84, ["startItems"] = { 206942 } },
[75891] = { ["id"] = 75891, ["name"] = "Ancient Curses", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 75890, 75891, 76194, 76195, 76196, 76197, 76203, 76205, 76206, 76207, 76212, 76213 }, ["series"] = { 75890, 76194 }, ["description"] = "Thank you for answering my call so quickly, <name>. Demonic corruption has seen a resurgence in Felwood recently. Tyrande sent out a contingent of Sentinels and one of her own priestesses to investigate the matter further. None have returned. Tyrande asked the Wardens to look into the matter--and Maiev has asked for your assistance personally. We need to make haste to Felwood, and see what Maiev has discovered.", ["objectivesText"] = "Meet Maiev Shadowsong in Felwood. Progress: May Elune guide us all to victory in this forsaken place.", ["rewardGold"] = 34100, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 207353, ["x"] = 0.525, ["y"] = 0.045 } }, ["ends"] = { { ["mapID"] = 77, ["npcID"] = 202702, ["x"] = 0.372667, ["y"] = 0.549333 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.045 }, ["mapCandidates"] = { ["npc"] = { 77, 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["sourceQuests"] = { 75890 }, ["questLines"] = { { ["id"] = 5399, ["name"] = "Night Elf Heritage Armor", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 77 },
[75918] = { ["id"] = 75918, ["name"] = "Fire Season", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 75918, 75919, 75920, 75921, 75922, 75923 }, ["description"] = "No doubt you have seen the destruction that Fyrakk continues to leave in his wake. While others fight him directly, my troops and I have been serving as the eyes and ears of the green dragonflight. Although Fyrakk's actions may seem erratic, there are trends to his strategies. We learned that he is to have a secret meeting with Vyranoth soon in Lunedane. This is a deviation from his recent tactics, and we need to know why. Given the danger, we would value your aid. Meet me in Lunedane.", ["objectivesText"] = "Meet Shandris at Lunedane in the Ohn'ahran Plains .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 205067, ["x"] = 0.502, ["y"] = 0.533 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 205068, ["x"] = 0.186, ["y"] = 0.798 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.533 }, ["mapCandidates"] = { ["npc"] = { 2023, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 91695 }, ["questLines"] = { { ["id"] = 5381, ["name"] = "The Coalition of Flames", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5381, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[75919] = { ["id"] = 75919, ["name"] = "Dousing the Wards", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 75918, 75919, 75920, 75921, 75922, 75923 }, ["description"] = "Fyrakk and Vyranoth are already here. I spotted them near the overlook at the northeastern edge of Lunedane. Landing close to their location would reveal our presence, thus we are forced to begin our mission here. However, the bridge connecting this area to the overlook has been protected with fire magic. We will not be able to break through it. Fyrakk's Primalist allies appear to be maintaining the fire using wards set up around this area. If we destroy the wards, the fire should subside.", ["objectivesText"] = "Destroy 4 Warding Firestones. Progress: We need to bring that barrier down so we can get closer to the Incarnates. We cannot hear them from this far away.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 205068, ["x"] = 0.186, ["y"] = 0.798 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 205068, ["x"] = 0.186, ["y"] = 0.798 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.186, ["y"] = 0.798 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questTurnInID"] = 205068, ["questType"] = "standard", ["sourceQuests"] = { 75918 }, ["questLines"] = { { ["id"] = 5381, ["name"] = "The Coalition of Flames", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5381, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[75920] = { ["id"] = 75920, ["name"] = "Eyes of Fire", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 75918, 75919, 75920, 75921, 75922, 75923 }, ["description"] = "This area is swarming with far more Primalists than I expected. Fyrakk does not generally travel with guards, so I doubt the Primalists are here to accompany him. They seem to be trying to establish a foothold here. But why? Perhaps whatever the Incarnates are discussing will answer that question. In the meantime, let us thin out the Primalists guarding this area. We cannot risk having them in full force behind us as we cross the bridge.", ["objectivesText"] = "Kill 8 Burning Flamespeakers or Blazing Overseers . Progress: We will need to work quickly. We cannot risk drawing the attention of the Incarnates.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 205068, ["x"] = 0.186, ["y"] = 0.798 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 205068, ["x"] = 0.186, ["y"] = 0.798 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.186, ["y"] = 0.798 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questTurnInID"] = 205068, ["questType"] = "standard", ["sourceQuests"] = { 75918 }, ["questLines"] = { { ["id"] = 5381, ["name"] = "The Coalition of Flames", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5381, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[75921] = { ["id"] = 75921, ["name"] = "Through the Flames", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 75918, 75919, 75920, 75921, 75922, 75923 }, ["description"] = "Druids of the Flame... <Shandris frowns deeply, eyes shut as she holds back her anger.> To think that they still exist. That any of our people would join Fyrakk and his-- <She stops, releases a heavy breath, and continues.> We have a mission to complete. We need to cross the bridge to get close enough to the Incarnates that we can overhear their conversation. I will shroud us so that we can move between the elementals still guarding the way forward.", ["objectivesText"] = "Collect 4 Smoldering Blossoms while crossing the bridge towards Fyrakk and Vyranoth. Progress: We need be as close to the Incarnates as we can. We cannot afford to miss a single word of their conversation.", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 59529, 59530, 131310, 175470, 175471, 175472, 175473, 206598 }, ["starts"] = { { ["npcID"] = 205892 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 205134, ["x"] = 0.218, ["y"] = 0.772 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.218, ["y"] = 0.772 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questGiverID"] = 205892, ["questType"] = "standard", ["sourceQuests"] = { 75919, 75920 }, ["questLines"] = { { ["id"] = 5381, ["name"] = "The Coalition of Flames", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5381, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[75922] = { ["id"] = 75922, ["name"] = "Inflammatory Information", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 75918, 75919, 75920, 75921, 75922, 75923 }, ["description"] = "<Shandris whispers to you.> Do you see that up ahead? The Druids of the Flame have captured what appears to be a keeper--a guardian of nature, sacred to our people. If their power is already enough to... <Shandris shakes her head, then gestures at the dense shrubbery nearby.> Stay hidden with me and we will listen to the Incarnates, and perhaps discern what the druids intend to do with the keeper.", ["objectivesText"] = "Eavesdrop on Fyrakk and Vyranoth. Progress: I will hold off any reinforcements that come. Deal with the keeper!", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 205134, ["x"] = 0.218, ["y"] = 0.772 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 205142, ["x"] = 0.216, ["y"] = 0.77 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.218, ["y"] = 0.772 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 75921 }, ["questLines"] = { { ["id"] = 5381, ["name"] = "The Coalition of Flames", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5381, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[75923] = { ["id"] = 75923, ["name"] = "Raise the Alarm", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 75918, 75919, 75920, 75921, 75922, 75923 }, ["description"] = "So the Druids of the Flame have allied with Fyrakk to help him invade the Emerald Dream. They were able to turn that keeper to the flame with hardly any effort. Fyrakk must be bolstering their power, perhaps as payment for their aid in accessing the Dream. We need to mobilize troops immediately to find every Druid of the Flame on the Dragon Isles and stop them. Go to Captain Drine in Valdrakken and alert her. She will dispatch the drakonid. I will go to Merithra and handle things here.", ["objectivesText"] = "Deliver your report to Captain Drine at the Seat of the Aspects in Valdrakken.", ["rewardGold"] = 34100, ["rewardXP"] = 175, ["rewardItems"] = { 206353 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 205142, ["x"] = 0.216, ["y"] = 0.77 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 206041, ["x"] = 0.544, ["y"] = 0.4724 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.216, ["y"] = 0.77 }, ["mapCandidates"] = { ["npc"] = { 2023, 2112 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 75922 }, ["questLines"] = { { ["id"] = 5381, ["name"] = "The Coalition of Flames", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5381, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
[75932] = { ["id"] = 75932, ["name"] = "Loamm Niffen", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = { "emissary", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 75932 }, ["rewardGold"] = 280900, ["rewardXP"] = 4925, ["rewardItems"] = { 204712, 205983, 205985 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["worldSystems"] = { ["bounties"] = { { ["id"] = 465, ["factionID"] = 2564, ["bountySetID"] = 119 } } } },
[75935] = { ["id"] = 75935, ["name"] = "Time, Signature", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75935 }, ["description"] = "Oh good, an adventurer. You've heard of Pedgi, I presume? The composer? No? Well, don't tell him that. We were traveling to research his next song, when we stumbled upon a dragon named Tempo. Pedgi is now convinced they're the only one who can help us. Yes, because of the name. That's really all it takes for him. But Tempo here is, understandably, too busy to help us. Could you talk to them? See if we can help clear their schedule?", ["objectivesText"] = "See if Tempo would be willing to help Pedgi with his music. Progress: Yes, he's always like this. But he pays well and I get to travel.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 204990, ["x"] = 0.538, ["y"] = 0.8416 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 204990, ["x"] = 0.538, ["y"] = 0.8416 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.8416 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 77437 } },
[75936] = { ["id"] = 75936, ["name"] = "Slimy Yet Satisfying", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75936 }, ["description"] = "<A worm. You know someone who might love this.>", ["objectivesText"] = "Bring 1 Wriggling Worm to Marie Shellie in Loamm. Progress: < Marie Shellie drips slime.>", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 204985, 205188, 205795 }, ["starts"] = { { ["x"] = 0.569, ["y"] = 0.521, ["mapID"] = 2133 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 204356, ["x"] = 0.568, ["y"] = 0.54 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["startItems"] = { 205795 } },
[75949] = { ["id"] = 75949, ["name"] = "Downbeat Data", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75949 }, ["description"] = "You say that Tempo mentioned objects from other timelines? I have a device used for syncing melodies. Strangely enough, it seems to have the same effect on timelines in this town. Perhaps a side effect of the chaotic temporal energies here? I've upgraded Pedgi's glasses to allow him to observe the rhythms of the world. They may make it easier to find mis-timed entities. Ask if you can borrow them.", ["objectivesText"] = "Use Melly's device near objects from other timelines. Pedgi's sunglasses will make them easier to find. Progress: Have you found any mis-timed entities?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 208235, 208236 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 204990, ["x"] = 0.538, ["y"] = 0.8416 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 204990, ["x"] = 0.538, ["y"] = 0.8416 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.8416 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 77432 } },
[75950] = { ["id"] = 75950, ["name"] = "An Exemplar of Justice: Hadwin", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 75632, 75633, 75634, 75635, 75636, 75637, 75638, 75950, 75951, 75952, 75953, 76171, 76176 }, ["description"] = "We've been out here for a good bit of time. Time enough for me to watch the gnolls around here. Gnolls are usually a nuisance, but the decay gnolls around Brackenhide Hollow... The decay doesn't just warp their bodies. It warps their minds too. Decaymonger Rotpaw is the worst of them. She's indiscriminate in who or what she spreads her decay to: the unwilling of her people, travelers, animals, children... If there's any justice in this world, she should be taken down.", ["objectivesText"] = "Help Hadwin defeat Decaymonger Rotpaw .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 204590, ["x"] = 0.176, ["y"] = 0.314 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 204590, ["x"] = 0.176, ["y"] = 0.314 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.176, ["y"] = 0.314 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 76171 }, ["questLines"] = { { ["id"] = 5455, ["name"] = "Reforging the Tyr's Guard", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 5455, ["questLineOrder"] = 2 }, { ["id"] = 234, ["title"] = "Catching Up!", ["questLineID"] = 5455, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[75951] = { ["id"] = 75951, ["name"] = "An Exemplar of Order: Talthis", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 75632, 75633, 75634, 75635, 75636, 75637, 75638, 75950, 75951, 75952, 75953, 76171, 76176 }, ["description"] = "I know why Travard chose this area for our training. The decay here is... chaotic and disordered. Things that Tyr and the titans are not! The nearby gnolls revel in the decay. Revolting. They have taken over territory that was once occupied by the proud, noble, and civil tuskarr. The tuskarr have asked that relics they had to abandon are returned to them. Please help me fight the gnolls and retrieve the relics so the tuskarr can continue their rituals in Iskaara.", ["objectivesText"] = "Bring Talthis 5 Tuskarr relics. Progress: The gnolls had no right to those relics. They belong to the tuskarr.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 206204 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 204593, ["x"] = 0.175, ["y"] = 0.314 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 204593, ["x"] = 0.175, ["y"] = 0.314 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.175, ["y"] = 0.314 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 76171 }, ["questLines"] = { { ["id"] = 5455, ["name"] = "Reforging the Tyr's Guard", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 5455, ["questLineOrder"] = 2 }, { ["id"] = 234, ["title"] = "Catching Up!", ["questLineID"] = 5455, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[75952] = { ["id"] = 75952, ["name"] = "An Exemplar of Sacrifice: Nolaki", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 75632, 75633, 75634, 75635, 75636, 75637, 75638, 75950, 75951, 75952, 75953, 76171, 76176 }, ["description"] = "Much is said about how decay spreads through the air and ground. But it also spreads through the water. Slimes that live in the rivers and streams ooze pestilence. The water is toxic with it. But if we wade in and kill the big one, the poison in the water will diminish. It may poison me in the process, but I am going to kill one if it's the last thing I do. This place needs a purging. Are you with me, <name>?", ["objectivesText"] = "Help Nolaki defeat a massive slime.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 204592, ["x"] = 0.175, ["y"] = 0.314 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 204592, ["x"] = 0.175, ["y"] = 0.314 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.175, ["y"] = 0.314 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 76171 }, ["questLines"] = { { ["id"] = 5455, ["name"] = "Reforging the Tyr's Guard", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 5455, ["questLineOrder"] = 2 }, { ["id"] = 234, ["title"] = "Catching Up!", ["questLineID"] = 5455, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[75953] = { ["id"] = 75953, ["name"] = "An Exemplar of Compassion: Valunei", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 75632, 75633, 75634, 75635, 75636, 75637, 75638, 75950, 75951, 75952, 75953, 76171, 76176 }, ["description"] = "It makes my heart ache to see what the decay has done to some of the wildlife here... I cannot save all the creatures that live around Brackenhide Hollow, but I wish for my trial to at least save some. In a cave to the west, there is a family of bears that has recently been corrupted. I believe I can fight my way there and heal them. Will you help me, <name>?", ["objectivesText"] = "Protect Valunei from decay gnolls.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 204591, ["x"] = 0.176, ["y"] = 0.314 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 204591, ["x"] = 0.176, ["y"] = 0.314 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.176, ["y"] = 0.314 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 76171 }, ["questLines"] = { { ["id"] = 5455, ["name"] = "Reforging the Tyr's Guard", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 5455, ["questLineOrder"] = 2 }, { ["id"] = 234, ["title"] = "Catching Up!", ["questLineID"] = 5455, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[75966] = { ["id"] = 75966, ["name"] = "Compose Yourself", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75966 }, ["description"] = "I promise he's not always like this. But he is, often, like this. Usually it takes him a few days to come out of his funk, but we don't have that sort of time. The commission he got to write this song won't last forever. Maybe we can speed up the process. Could you help raise Pedgi 's confidence?", ["objectivesText"] = "Raise Pedgi 's confidence. Progress: Hmm...", ["rewardGold"] = 280900, ["rewardXP"] = 7135, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 204990, ["x"] = 0.538, ["y"] = 0.8416 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 204987, ["x"] = 0.538, ["y"] = 0.8416 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.8416 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 75949 } },
[75970] = { ["id"] = 75970, ["name"] = "Tracked Through Time", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75970 }, ["description"] = "A Timewalker spotted a bear cub who stumbled into our present time. She was so frightened she ran off before he could catch her! Can you find the poor thing? You'll need to calm her down before she'll follow you. Bring her back here and I'll open a temporal portal to take her home.", ["objectivesText"] = "Rescue a Time-Lost Cub and return her to her proper time. Progress: That cub must be so scared, all alone and in a strange place. We need to get her back home!", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 207002 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 205424, ["x"] = 0.522, ["y"] = 0.816 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 205424, ["x"] = 0.522, ["y"] = 0.816 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.816 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2705 } },
[75971] = { ["id"] = 75971, ["name"] = "Squeaky Toy of Time and Space", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75971 }, ["description"] = "We have detected another time anomaly. A strange object that even we cannot understand the significance of. This artifact must be returned before it does irreparable damage to the true timeline and the world as we know it. Return here once you have recovered the artifact. I will open a portal so you may return it to its proper place.", ["objectivesText"] = "Find the Time-Displaced Toy and return it to its proper time. Progress: All of our fates depend on returning that artifact to its proper time.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 206161, 207002 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 205769, ["x"] = 0.522, ["y"] = 0.816 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 205769, ["x"] = 0.522, ["y"] = 0.816 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.816 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2705 } },
[75985] = { ["id"] = 75985, ["name"] = "Rest Well, Warrior", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 75985 }, ["description"] = "Shalkeel deserves to be seen off properly. I want to dress his burial area and say a few words. I know your time is precious, but would you take the shovel and bury his ashes while I perform the rites?", ["objectivesText"] = "Assist Khasar with Shalkeel's burial. Progress: If I were able to handle his ashes, I'd have poured them out over the stream he and I played in when we were children.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 204461 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 202788, ["x"] = 0.87, ["y"] = 0.272 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 202788, ["x"] = 0.87, ["y"] = 0.272 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.87, ["y"] = 0.272 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 72978 } },
[75986] = { ["id"] = 75986, ["name"] = "Feats Per Minute", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75986 }, ["description"] = "Alright, one last problem to help solve. Succeed at this and we'll surely have earned an audience with Tempo! The investigators discovered another Time Slime. A much larger, powerful Time Slime. We've come to call it Time Slime Prime . Its temporal energies are greatly accelerated, making it especially deadly. I recommend using the metronographer several times to slow it back down before engaging in combat.", ["objectivesText"] = "Re-synchronize and defeat the Time Slime Prime .", ["rewardGold"] = 280900, ["rewardXP"] = 11895, ["rewardItems"] = { 206997, 208401 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 204990, ["x"] = 0.538, ["y"] = 0.8416 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 195773, ["x"] = 0.548, ["y"] = 0.816 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.8416 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 76552 } },
[75987] = { ["id"] = 75987, ["name"] = "Woolomancer", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75987 }, ["description"] = "Somehow, Jaina Proudmoore has found a magic wand. Not our Jaina, of course, but her childhood self. She is far too young to have access to such power. We need you to help clean up the mess she's made and confiscate that wand.", ["objectivesText"] = "Dispel 8 Polymorphed Creatures and confiscate Jaina's Wand of Mass Polymorph . Progress: Jaina must not practice magic until she is old enough to handle it responsibly. I trust you to put a stop to this before the situation becomes dire.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 206368, 207002 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 205769, ["x"] = 0.522, ["y"] = 0.816 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 205769, ["x"] = 0.522, ["y"] = 0.816 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.816 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2705 } },
[75988] = { ["id"] = 75988, ["name"] = "Lucky Hearthstone Card", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75988 }, ["description"] = "I was playing Hearthstone with my father when I somehow ended up here. Then some dragon whelps flew off with my lucky card to add it to their... card tornado? Then all the adults started saying I need to go home. But I can't leave without my lucky card! Can you please help me? I promise I'll go home if you bring it back for me!", ["objectivesText"] = "Kill the Enchanted Card Swarm and retrieve Anduin's Lucky Hearthstone Card . Progress: I feel a little better. Bob gave me some juice. But I still don't know what's going on. Where is this place? How did I get here?", ["rewardGold"] = 561800, ["rewardXP"] = 11895, ["rewardItems"] = { 206022, 207002 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 205604, ["x"] = 0.522, ["y"] = 0.816 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 205604, ["x"] = 0.522, ["y"] = 0.816 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.816 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2705 } },
[75989] = { ["id"] = 75989, ["name"] = "The Black Prince Parade", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75989 }, ["description"] = "Five separate portals opened up here at the same time, and the same person stepped out of each one. Now we have an inn full of Wrathions. All different ages, dealing with different things in their own lives, and very eager to blame each other for their problems. Let's get them all back to their proper times before they cause too much trouble.", ["objectivesText"] = "Send each Wrathion back to his time through his temporal portal. Progress: All this commotion is bad for business.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 206683, 207002 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 203769, ["x"] = 0.522, ["y"] = 0.815 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 203769, ["x"] = 0.522, ["y"] = 0.815 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.815 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2705 } },
[75990] = { ["id"] = 75990, ["name"] = "Star-Crossed Lovers", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75990 }, ["description"] = "We found a time disruption long, long ago. Someone helped Illidan charm Tyrande, dooming us all to the Burning Legion! Malfurion is so distraught he can't even sleep. He has no idea how to win her back. We need you to help him out before the timeline is ruined.", ["objectivesText"] = "Help Malfurion gain Tyrande's affection in Val'sharah. Progress: As painful as it can be, heartbreak can be essential for making us who we are. Even if who are isn't always... nice.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 206695, 207002 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 205424, ["x"] = 0.522, ["y"] = 0.816 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 205424, ["x"] = 0.522, ["y"] = 0.816 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.816 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2705 } },
[75991] = { ["id"] = 75991, ["name"] = "What Could Have Been", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75991 }, ["description"] = "A mysterious stranger showed up here a bit ago through one of those time portals. Said there's a threat nearby they need your help with. Some kind of cloaking device. Though you might not like what you see once it's disabled. In fact, you may not particularly like this stranger, for that matter.", ["objectivesText"] = "Help an alternate version of yourself defeat a mutual foe. Progress: I know it must be hard to see yourself like this. At least you're on the same side for this one.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 207002 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 203769, ["x"] = 0.522, ["y"] = 0.815 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 203769, ["x"] = 0.522, ["y"] = 0.815 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.815 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2705 } },
[75998] = { ["id"] = 75998, ["name"] = "Crispety Crunchety", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75998 }, ["description"] = "<You've seen this kind of beetle near the stables in Loamm. Maybe the stable master will know more about them?>", ["objectivesText"] = "Bring the Crunchy Beetle to Vanndual in Loamm. Progress: A cherry beetle!", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 204985, 205188, 205901 }, ["starts"] = { { ["x"] = 0.573, ["y"] = 0.493, ["mapID"] = 2133 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 203294, ["x"] = 0.576, ["y"] = 0.578 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.578 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["startItems"] = { 205901 } },
[76004] = { ["id"] = 76004, ["name"] = "Deep Cuts", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 76004 }, ["description"] = "<You find a discarded deepflayer claw . You've seen some niffen wield these as weapons.>", ["objectivesText"] = "Bring 1 Deepflayer Claw to Kilnmaster Crubus in Loamm. Progress: Be careful, those are sharp.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 204985, 205188, 205902 }, ["starts"] = { { ["x"] = 0.576, ["y"] = 0.564, ["mapID"] = 2133 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 203170, ["x"] = 0.57, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["startItems"] = { 205902 } },
