[76026] = { ["id"] = 76026, ["name"] = "Surveying the Tower", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "Get a load of those rock formations! Surveying doesn't get much better than this. This tower has been here for ages. The black dragonflight used it for some seriously dark stuff, but that's not why we're here. After the dragons left, a troupe of niffen bandits took shelter in the ruins and robbed the place blind. But they left a bunch of trash everywhere. Imagine what we could learn about the niffen from that trash once we get digging!", ["objectivesText"] = "Speak with Roska to start the dig, then excavate artifacts from around the tower.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 210834 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 205413, ["x"] = 0.486, ["y"] = 0.484 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 208055, ["x"] = 0.476, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.486, ["y"] = 0.484 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 77486 }, ["questLines"] = { { ["id"] = 5468, ["name"] = "Azerothian Archives - Excavation Sites", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 23, ["flags"] = 0 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[76027] = { ["id"] = 76027, ["name"] = "Flapping and Screaming", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = { "bonusobjective" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14022, ["storyline"] = { 76027 }, ["objectivesText"] = "Treasure Chest unlocked", ["rewardItems"] = { 205969 }, ["starts"] = { { ["x"] = 0.546, ["y"] = 0.495, ["mapID"] = 2133 } }, ["ends"] = { { ["x"] = 0.546, ["y"] = 0.495, ["mapID"] = 2133 } }, ["coords"] = { ["mapID"] = 2133, ["x"] = 0.546, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Treasure Chest unlocked", ["amount"] = 1, ["type"] = 2, ["objectID"] = 402595, ["orderIndex"] = 1 } }, ["db2QuestInfoID"] = 283, ["db2QuestInfoName"] = "Bonus Objective with Completion Toast" },
[76030] = { ["id"] = 76030, ["name"] = "Airborne Winding", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 76030 }, ["description"] = "Well hello there! Word around here is that we've got your continued support--so we got a little something for you. Meet me in Loamm so I can hand it over! Best, Harlowe Marl", ["objectivesText"] = "Talk to Harlowe Marl in Loamm.", ["rewardItems"] = { 203347, 203362, 203365 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 205127, ["x"] = 0.564, ["y"] = 0.566 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 202468, ["x"] = 0.564, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.566 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[76032] = { ["id"] = 76032, ["name"] = "Hidden in the Midden", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "<This dragon statue is similar to others found in the region but has been covered in paint. Googly eyes, stink lines, whiskers, and all manner of other rude drawings decorate the otherwise-imposing stone. The paint looks old and is flaking in places but is not as old as the statue itself. Roska will want to have a look at this!>", ["objectivesText"] = "Carefully excavate the defaced dragon statue . Progress: Nothing like volcanic rock, eh <name>? Never know what you'll find!", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 210834 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 207931, ["x"] = 0.475, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 208055, ["x"] = 0.476, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 76026 }, ["questLines"] = { { ["id"] = 5468, ["name"] = "Azerothian Archives - Excavation Sites", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 24, ["flags"] = 0 } }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
