[76083] = { ["id"] = 76083, ["name"] = "Aberrus, the Shadowed Crucible: Echoes of the Earth-Warder", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14663, ["storyline"] = { 76083 }, ["description"] = "I sense a dark presence somewhere within these halls... something strangely familiar. Perhaps it will reveal itself as we explore the many chambers of Aberrus. If you can find evidence of this looming evil, we may be able to gain easier access to the depths below.", ["objectivesText"] = "Collect 3 Tomes of the Earth-Warder from the Echo of Neltharion within Aberrus, the Shadowed Crucible on Normal Difficulty. Progress: The knowledge gained from these may allow us to access the lower depths of Aberrus more directly.", ["rewardGold"] = 561800, ["rewardXP"] = 11895, ["rewardItems"] = { 205994 }, ["starts"] = { { ["npcID"] = 201574 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14663 } }, ["questGiverID"] = 201574, ["questType"] = "raid" },
