[76276] = { ["id"] = 76276, ["name"] = "A Changed Land", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66218, 66223, 76276 }, ["description"] = "The arrival of Amirdrassil brings great change to Azeroth. Its roots are finding a home in the soil beneath even as its branches stretch skyward to taste the air. This is an auspicious moment, but we must not forget our allies from the Isles. Visit with those nearby to ensure they are safe and sound.", ["objectivesText"] = "Check on nearby Dragon Isles residents. Progress: Amirdrassil has safely arrived, but we must make sure our allies are also safe and sound.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 209806, 209915, 209916 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 206397, ["x"] = 0.148, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 206397, ["x"] = 0.148, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.148, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 77780 }, ["questLines"] = { { ["id"] = 5473, ["name"] = "New Beginnings", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5740, ["name"] = "11.1.7 Lorewalking - Training (LAS)", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 59, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5473, ["questLineOrder"] = 6 }, { ["id"] = 273, ["title"] = "Lorewalking: Training", ["questLineID"] = 5740, ["questLineOrder"] = 0 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
