[76281] = { ["id"] = 76281, ["name"] = "Something Worth Celebrating", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15105, ["mapID"] = 2239, ["storyline"] = { 76276, 76280, 76281, 76282, 76283, 77200, 77201, 77329, 77780, 77781 }, ["description"] = "At long last... let us celebrate all that we have overcome, and the hope that burns brightly amongst these gathered kaldorei. Come, join the festivities.", ["objectivesText"] = "Serve tables at the celebration in Bel'ameth. Progress: Have you thoroughly enjoyed yourself, Champion?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2239, ["npcID"] = 208537, ["x"] = 0.508, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 2239, ["npcID"] = 206849, ["x"] = 0.542, ["y"] = 0.578 } }, ["coords"] = { ["mapID"] = 2239, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 2239 }, ["zone"] = { 15105 } }, ["questType"] = "standard", ["sourceQuests"] = { 76280 }, ["questLines"] = { { ["id"] = 5473, ["name"] = "New Beginnings", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 64, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5473, ["questLineOrder"] = 6 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2239 },
[76282] = { ["id"] = 76282, ["name"] = "A Disquieting Feeling", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15105, ["mapID"] = 2239, ["storyline"] = { 76276, 76280, 76281, 76282, 76283, 77200, 77201, 77329, 77780, 77781 }, ["description"] = "Ah, <name>! You're just the person I was looking for. I'm a little concerned about Khadgar. I don't think it's anything dire, but he doesn't seem to be enjoying himself like everyone else--he just seems... distracted. I don't want to pry, but perhaps you could bring him a drink for me? He may open up to you.", ["objectivesText"] = "Bring Khadgar a drink in Bel'ameth. Progress: Were you able to cheer up Khadgar, <name>?", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 208221, 209316, 209317, 209318, 209319, 209322, 209323, 209324, 209326, 209912, 209913, 209914 }, ["starts"] = { { ["mapID"] = 2239, ["npcID"] = 209042, ["x"] = 0.542, ["y"] = 0.578 } }, ["ends"] = { { ["mapID"] = 2239, ["npcID"] = 209042, ["x"] = 0.542, ["y"] = 0.578 } }, ["coords"] = { ["mapID"] = 2239, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.578 }, ["mapCandidates"] = { ["npc"] = { 2239 }, ["zone"] = { 15105 } }, ["questType"] = "standard", ["sourceQuests"] = { 76280 }, ["questLines"] = { { ["id"] = 5473, ["name"] = "New Beginnings", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 66, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5473, ["questLineOrder"] = 6 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2239 },
