[76317] = { ["id"] = 76317, ["name"] = "Call of the Dream", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 76317, 76318, 76319, 76320, 76321, 76322, 76323, 76324, 76325, 76326 }, ["series"] = { 76318, 76319, 76320 }, ["description"] = "A great tree grows within the Dream. Soon, it will emerge in Azeroth. But before it does, we must protect it from Fyrakk's forces. We must band together and see it through its verdant birth. Join me and the others in the Ancient Bough. Together, we will travel into the Emerald Dream .", ["objectivesText"] = "Meet Merithra within the Ancient Bough in the Ohn'ahran Plains.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 206353, 208047, 208067, 208181, 210246, 210412, 210704, 210730, 210757, 210847 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 187590, ["x"] = 0.186, ["y"] = 0.518 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 187590, ["x"] = 0.186, ["y"] = 0.518 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.186, ["y"] = 0.518 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5456, ["name"] = "Enter the Dream", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5461, ["name"] = "Emerald Dream Campaign", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5456, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[76318] = { ["id"] = 76318, ["name"] = "Emerald Welcome", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 76317, 76318, 76319, 76320, 76321, 76322, 76323, 76324, 76325, 76326 }, ["series"] = { 76317, 76319, 76320 }, ["description"] = "We protected the tree by guarding all entrances to the Emerald Dream . Now Fyrakk has found allies to open the way for him. I will do the same for you and our allies. The green dragonflight cannot do this alone. Through this portal, we will enter the Dream together. We must protect that realm and all that grows within it.", ["objectivesText"] = "Enter the Emerald Dream through the portal in Ancient Bough. Progress: There is much to be done.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 210412 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 187590, ["x"] = 0.186, ["y"] = 0.518 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206425, ["x"] = 0.694, ["y"] = 0.54 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.186, ["y"] = 0.518 }, ["mapCandidates"] = { ["npc"] = { 2023, 2200 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 76317 }, ["questLines"] = { { ["id"] = 5456, ["name"] = "Enter the Dream", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5461, ["name"] = "Emerald Dream Campaign", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5456, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
[76319] = { ["id"] = 76319, ["name"] = "Feast or Flaming", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76317, 76318, 76319, 76320, 76321, 76322, 76323, 76324, 76325, 76326 }, ["series"] = { 76317, 76318, 76320 }, ["description"] = "Already Fyrakk damages the fabric of the Dream. I can feel it burning, as if flames were consuming my scales. And I know that simmering agony is only a fraction of what my son felt when Fyrakk tormented him. But we have a potent weapon against this fire. Our faerie drakes and dragons consume what does not belong here. They are excellent allies, if a bit difficult to manage. Now they need our help. Use this. Clear the skies of encroaching flame.", ["objectivesText"] = "Dragonride or ride the Faerie Drake to consume fiery patches in the Dream. Progress: The Dream is my home and the home of my flight. I will not let it fall to fire.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206425, ["x"] = 0.694, ["y"] = 0.54 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206510, ["x"] = 0.642, ["y"] = 0.582 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.694, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 76318 }, ["questLines"] = { { ["id"] = 5456, ["name"] = "Enter the Dream", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5461, ["name"] = "Emerald Dream Campaign", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5456, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
[76320] = { ["id"] = 76320, ["name"] = "Wild Gods in Our Midst", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76317, 76318, 76319, 76320, 76321, 76322, 76323, 76324, 76325, 76326 }, ["series"] = { 76317, 76318, 76319 }, ["description"] = "The Emerald Dream is the home of nature's Wild Gods. We will need their strength and their power to counteract the damage that Fyrakk has brought to this realm. The first to seek out is Goldrinn . The ancient wolf has a fondness for Azeroth and mortals, so he is sure to aid us. Others may need more convincing. I will meet you nearby in the Fields of Reverie, where dryads and keepers reside.", ["objectivesText"] = "Seek out Wild Gods and allies within the Emerald Dream .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206510, ["x"] = 0.642, ["y"] = 0.582 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206583, ["x"] = 0.626667, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.582 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 76319 }, ["questLines"] = { { ["id"] = 5456, ["name"] = "Enter the Dream", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5461, ["name"] = "Emerald Dream Campaign", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5456, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2254 },
[76321] = { ["id"] = 76321, ["name"] = "Burning Assault", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76317, 76318, 76319, 76320, 76321, 76322, 76323, 76324, 76325, 76326 }, ["description"] = "The Druids of the Flame are opening a way into the Dream for Fyrakk's forces. Every moment, more of them enter. We must stop this rising tide before it becomes a flood.", ["objectivesText"] = "Slay Primalists, Djaradin, and Druids of the Flame. Progress: Fyrakk's forces must be cut down before they can establish a hold on the Dream.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206583, ["x"] = 0.626667, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206688, ["x"] = 0.628, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.626667, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 76320 }, ["questLines"] = { { ["id"] = 5456, ["name"] = "Enter the Dream", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5461, ["name"] = "Emerald Dream Campaign", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5456, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
[76322] = { ["id"] = 76322, ["name"] = "The Face of Our Enemies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76317, 76318, 76319, 76320, 76321, 76322, 76323, 76324, 76325, 76326 }, ["description"] = "Powerful foes lurk among the enemies Fyrakk summoned into the Emerald Dream . I have not seen Cassaphine since she came up out of the barrows. Find her, and assist our allies by striking down these leaders.", ["objectivesText"] = "Defeat Fyrakk's powerful lieutenants and secure the battlefield. Progress: It saddens me to see the children of the Dream so twisted.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206583, ["x"] = 0.626667, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206688, ["x"] = 0.628, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.626667, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 76320 }, ["questLines"] = { { ["id"] = 5456, ["name"] = "Enter the Dream", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5461, ["name"] = "Emerald Dream Campaign", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5456, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
[76323] = { ["id"] = 76323, ["name"] = "Amirdrassil", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76317, 76318, 76319, 76320, 76321, 76322, 76323, 76324, 76325, 76326 }, ["series"] = { 76324, 76325, 76326, 77283, 77818 }, ["description"] = "This tree has grown peacefully in the Emerald Dream since it was planted here. We have watched over it and nurtured it. And now, just when it is about to leave the cradle of this realm and enter Azeroth, our enemies see it as a means to further their own plans. It is so much more. Come. Let us go to Amirdrassil.", ["objectivesText"] = "Meet Merithra at the base of Amirdrassil.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 206960, 208047, 210180, 210916 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206806, ["x"] = 0.589333, ["y"] = 0.615333 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206809, ["x"] = 0.538, ["y"] = 0.638 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.589333, ["y"] = 0.615333 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 77818 }, ["questLines"] = { { ["id"] = 5456, ["name"] = "Enter the Dream", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5461, ["name"] = "Emerald Dream Campaign", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5456, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
[76324] = { ["id"] = 76324, ["name"] = "Lost to the Flame", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76317, 76318, 76319, 76320, 76321, 76322, 76323, 76324, 76325, 76326 }, ["series"] = { 76323, 76325, 76326, 77283, 77818 }, ["description"] = "The Druids of the Flame pose more of a threat than I realized. Not only do they let Fyrakk and his forces pour into the Dream, but they also tempt the Dream's denizens to the flame! We cannot dwell on how this happened. It pains me greatly, but Elder Cassaphine must be stopped. Go with Tyrande and... end the dryad.", ["objectivesText"] = "Defeat Elder Cassaphine at the base of Amirdrassil.", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 209924, 209938 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206809, ["x"] = 0.538, ["y"] = 0.638 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206979, ["x"] = 0.508, ["y"] = 0.7 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.638 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 76323 }, ["questLines"] = { { ["id"] = 5456, ["name"] = "Enter the Dream", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5461, ["name"] = "Emerald Dream Campaign", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5456, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
[76325] = { ["id"] = 76325, ["name"] = "Between Fyrakk and a Hard Place", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76317, 76318, 76319, 76320, 76321, 76322, 76323, 76324, 76325, 76326 }, ["series"] = { 76323, 76324, 76326, 77283, 77818 }, ["description"] = "I hear approaching wings and smell shadowflame. Fyrakk is here. < Merithra 's anger is quiet but terrible.> Gerithus' pain will not go unanswered.", ["objectivesText"] = "Speak to Merithra and prepare for Fyrakk's attack.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206979, ["x"] = 0.508, ["y"] = 0.7 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206979, ["x"] = 0.508, ["y"] = 0.7 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.7 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 76324 }, ["questLines"] = { { ["id"] = 5456, ["name"] = "Enter the Dream", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5461, ["name"] = "Emerald Dream Campaign", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5456, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
[76326] = { ["id"] = 76326, ["name"] = "Home in the Dream", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76317, 76318, 76319, 76320, 76321, 76322, 76323, 76324, 76325, 76326 }, ["series"] = { 76323, 76324, 76325, 77283, 77818 }, ["description"] = "Fyrakk has withdrawn from Amirdrassil, but that only increases my concern. He must have another target within the Emerald Dream . We must convene with the others at the base of the tree. Tyrande and the kaldorei have established a camp. I need to speak with Alexstrasza to determine our next step.", ["objectivesText"] = "Meet Merithra at the central encampment beneath Amirdrassil.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206979, ["x"] = 0.508, ["y"] = 0.7 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206896, ["x"] = 0.508, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.7 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 76325 }, ["questLines"] = { { ["id"] = 5456, ["name"] = "Enter the Dream", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5461, ["name"] = "Emerald Dream Campaign", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5456, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
[76327] = { ["id"] = 76327, ["name"] = "Eye of Ysera", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76327, 76328, 76329, 76330, 76331, 76332, 76333, 76334, 76335, 76336, 76337, 78646 }, ["description"] = "Galenori's report is deeply troubling. The Eye's temple is my seat of power here in the Dream. From it, I commune with the Eye's energies and monitor the health of the Dream and its denizens. The Eye's power flows throughout the Dream, and helps Amirdrassil grow. If the djaradin take control of it, they could pervert its nature and stunt the growth of the tree. My daughter knows the Eye's importance. I will follow her lead--and so should you.", ["objectivesText"] = "Take the portal from Amirdrassil into the Eye of Ysera .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206408, ["x"] = 0.518, ["y"] = 0.454 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206416, ["x"] = 0.531, ["y"] = 0.2885 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.454 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 77178 }, ["questLines"] = { { ["id"] = 5460, ["name"] = "Eye of Ysera", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 35, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5460, ["questLineOrder"] = 4 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
[76328] = { ["id"] = 76328, ["name"] = "A New Brute", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76327, 76328, 76329, 76330, 76331, 76332, 76333, 76334, 76335, 76336, 76337, 78646 }, ["description"] = "Galok is but another one of Fyrakk's minions. I will not be baited by his bluster. The fire orb must be his doing. Its magic threatens to overwhelm the Eye. Ysera is channeling a shield from inside the temple, but it doesn't seem to be as effective as we expected. Now, I must confront Galok. Use my magic to bolster our casters if they weaken. The defense must not fall!", ["objectivesText"] = "Use The Dreamer's Essence on 5 Emerald Preservers. Then, meet Ysera inside the temple in the Eye of Ysera . Progress: With haste, <name>! Our defenders are in pain.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 208124, 209912, 209913, 209914 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206416, ["x"] = 0.531, ["y"] = 0.2885 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206406, ["x"] = 0.5225, ["y"] = 0.2785 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.531, ["y"] = 0.2885 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 76327 }, ["questLines"] = { { ["id"] = 5460, ["name"] = "Eye of Ysera", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 36, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5460, ["questLineOrder"] = 4 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
[76329] = { ["id"] = 76329, ["name"] = "In and Out Scout", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76327, 76328, 76329, 76330, 76331, 76332, 76333, 76334, 76335, 76336, 76337, 78646 }, ["description"] = "Bodwin reports that Galok is not the only new threat to the Eye. The djaradin forces below are led by two others--a warrior and a mage. It is unwise to engage them directly in their own, well-established base. But I am certain they are a part of Galok's plan of attack. Please gather more information from these djaradin leaders. We need to know how best to counteract their attacks. Bodwin can grant you stealth so that you may move unseen in the camp.", ["objectivesText"] = "Spy on the djaradin leaders in Slagfell Hold. Progress: What have you seen?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 53429, 53432, 80768, 80769, 80770, 80771, 80772, 121653, 121654, 121655, 121672, 130276, 130277, 130278, 130279, 131365, 143488, 169482, 169483, 169485, 188011, 188017, 188025, 188033, 209917, 209918, 210016, 210235, 210236, 228439, 228440, 228441, 228442 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206406, ["x"] = 0.5225, ["y"] = 0.2785 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206406, ["x"] = 0.5225, ["y"] = 0.2785 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.5225, ["y"] = 0.2785 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 78646 }, ["questLines"] = { { ["id"] = 5460, ["name"] = "Eye of Ysera", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 38, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5460, ["questLineOrder"] = 4 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
[76330] = { ["id"] = 76330, ["name"] = "Disarm Specialist", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76327, 76328, 76329, 76330, 76331, 76332, 76333, 76334, 76335, 76336, 76337, 78646 }, ["description"] = "Bodwin's scouting sortie returned more key information. The djaradin plan to use suffused weapons to turn the tide of the battle. We must dispatch their smiths and destroy their weapons. Targeting both will weaken and slow them. Then we will have time to consider our next move. You will be in great danger on this mission. Take this. Throwing it onto enemies will temporarily put them to sleep. Use it so that you may avoid becoming overwhelmed in combat. Good luck, $p.", ["objectivesText"] = "Kill 6 Suffusion Shapers and destroy 8 Suffused Supplies. Progress: Tread carefully, <name>. Igira will have your head if you are caught.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 208184 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206406, ["x"] = 0.5225, ["y"] = 0.2785 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206406, ["x"] = 0.5225, ["y"] = 0.2785 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.5225, ["y"] = 0.2785 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 78646 }, ["questLines"] = { { ["id"] = 5460, ["name"] = "Eye of Ysera", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 39, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5460, ["questLineOrder"] = 4 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
[76331] = { ["id"] = 76331, ["name"] = "Merithra's Gambit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76327, 76328, 76329, 76330, 76331, 76332, 76333, 76334, 76335, 76336, 76337, 78646 }, ["description"] = "We are ready as we can be. Our guard is in place, and our trap ripe to spring. The emerald preservers' magic is linked to Ysera's. Upon your signal, they will simultaneously drop the magical defense. This is what Galok's been waiting for. His forces will swoop in like carrion birds. We await your word, <name>.", ["objectivesText"] = "Tell Ysera to drop the magical defense. Progress: Here we go.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206406, ["x"] = 0.5225, ["y"] = 0.2785 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206406, ["x"] = 0.5225, ["y"] = 0.2785 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.5225, ["y"] = 0.2785 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 76332 }, ["questLines"] = { { ["id"] = 5460, ["name"] = "Eye of Ysera", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 42, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5460, ["questLineOrder"] = 4 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
[76332] = { ["id"] = 76332, ["name"] = "Putting Roots Down", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76327, 76328, 76329, 76330, 76331, 76332, 76333, 76334, 76335, 76336, 76337, 78646 }, ["description"] = "Our trap is many-layered. Plant these seeds around town. Our gardeners have already prepared the soil. These plants will be effective tools to poisoning our enemy. Handle them carefully, for some may sprout sooner than later. Also, Kiya Featherpaw, our umbraclaw keeper, has an idea to mobilize the very strong creatures. Go speak with her. Finally, meet with Somnikus to give everyone the signal that battle is imminent.", ["objectivesText"] = "Plant seeds in 8 Tilled Soil and speak to Kiya Featherpaw. Then, speak with Somnikus. Progress: Our trap will work, I know it. Make haste, <name>. Even with my mother's and my strength...It is like some part of her is holding back her attunement. I dare not dwell on it.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 209910 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206406, ["x"] = 0.5225, ["y"] = 0.2785 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206406, ["x"] = 0.5225, ["y"] = 0.2785 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.5225, ["y"] = 0.2785 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 76334 }, ["questLines"] = { { ["id"] = 5460, ["name"] = "Eye of Ysera", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 41, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5460, ["questLineOrder"] = 4 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
[76333] = { ["id"] = 76333, ["name"] = "Triple Threat", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76327, 76328, 76329, 76330, 76331, 76332, 76333, 76334, 76335, 76336, 76337, 78646 }, ["description"] = "Galok is here. All is going according to plan then. We will put an end to him and any of his lieutenants.", ["objectivesText"] = "Slay Galok Wingslicer and his djaradin lieutenants The Anvil and Moltenbinder . Progress: We may have the stronger ground, but don't underestimate any of them.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 209894 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206406, ["x"] = 0.5225, ["y"] = 0.2785 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206416, ["x"] = 0.531, ["y"] = 0.2885 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.5225, ["y"] = 0.2785 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 76331 }, ["questLines"] = { { ["id"] = 5460, ["name"] = "Eye of Ysera", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 44, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5460, ["questLineOrder"] = 4 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
[76334] = { ["id"] = 76334, ["name"] = "Good Counsel", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76327, 76328, 76329, 76330, 76331, 76332, 76333, 76334, 76335, 76336, 76337, 78646 }, ["description"] = "Galok is a coward. He refuses to engage us directly until he is sure of success. We do not have the resources to attack his base. But if we cannot go to him, maybe we can entangle him in our own territory. I am confident we can prepare a trap here for Galok and his forces. My plan is not without risks, and controlling the playing field will be our key advantage. The question remains... how do we lure them here?", ["objectivesText"] = "Discuss Merithra 's plan with the green dragonflight. Progress: I must understand everyone's perspectives, especially for a maneuver this big.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206406, ["x"] = 0.5225, ["y"] = 0.2785 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206406, ["x"] = 0.5225, ["y"] = 0.2785 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.5225, ["y"] = 0.2785 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 76329, 76330 }, ["questLines"] = { { ["id"] = 5460, ["name"] = "Eye of Ysera", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 40, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5460, ["questLineOrder"] = 4 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
[76335] = { ["id"] = 76335, ["name"] = "Might of the Forest", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76327, 76328, 76329, 76330, 76331, 76332, 76333, 76334, 76335, 76336, 76337, 78646 }, ["description"] = "Use the traps you have laid to your advantage, <name>. Defeat every monster that dares threaten us!", ["objectivesText"] = "Eliminate the djaradin threat in the Eye of Ysera. Activate traps to help you in battle. Progress: We must protect the Dream!", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206406, ["x"] = 0.5225, ["y"] = 0.2785 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206416, ["x"] = 0.531, ["y"] = 0.2885 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.5225, ["y"] = 0.2785 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 76331 }, ["questLines"] = { { ["id"] = 5460, ["name"] = "Eye of Ysera", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 43, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5460, ["questLineOrder"] = 4 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
[76336] = { ["id"] = 76336, ["name"] = "Flight and Fight", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76327, 76328, 76329, 76330, 76331, 76332, 76333, 76334, 76335, 76336, 76337, 78646 }, ["description"] = "We have secured the land beneath our feet... now for the skies. Galok flies from us, but he is weakened. The time to strike is now.", ["objectivesText"] = "Slay 25 Fireswarm Shalewings flying above the Eye of Ysera by striking them with your dragonriding mount.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 209888 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206416, ["x"] = 0.531, ["y"] = 0.2885 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206406, ["x"] = 0.5225, ["y"] = 0.2785 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.531, ["y"] = 0.2885 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 76333, 76335 }, ["questLines"] = { { ["id"] = 5460, ["name"] = "Eye of Ysera", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 45, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5460, ["questLineOrder"] = 4 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
[76337] = { ["id"] = 76337, ["name"] = "The Ember Still Smolders", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76327, 76328, 76329, 76330, 76331, 76332, 76333, 76334, 76335, 76336, 76337, 78646 }, ["description"] = "I... almost cannot believe this worked. I am ever grateful for everyone's trust and faith. We could not have won this battle without the help of our allies and the flight. But the fight is far from over. Based on the intel we have gathered, Fyrakk and his minions are preparing an even greater assault. Their bases stand strong and terrifyingly close to the Dream's Hope, bastion of Amirdrassil. The Eye might have only been a distraction. We will regroup at Amirdrassil with the rest of our allies.", ["objectivesText"] = "Regroup with Merithra at Amirdrassil.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 208067, 210847 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206406, ["x"] = 0.5225, ["y"] = 0.2785 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206896, ["x"] = 0.508, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.5225, ["y"] = 0.2785 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 76336 }, ["questLines"] = { { ["id"] = 5460, ["name"] = "Eye of Ysera", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 46, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5460, ["questLineOrder"] = 4 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
