[76342] = { ["id"] = 76342, ["name"] = "Light 'Em Up!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76342, 76343, 76344, 76345, 76347, 76348, 76403, 76532, 77178 }, ["description"] = "After Vyranoth left, Fyrakk put all four of the Claws of Vyranoth on different tasks. He left me in charge of this camp and told me to keep the portals open at all costs. The Druids of the Flame are empowering the portals for the Primalist's reinforcements to come through. We should close those portals and thin out their ranks.", ["objectivesText"] = "Weaken the Primalist encampment in the Primalist Stronghold. Progress: The Primalists will only multiply in numbers if we do not hinder them.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 29735, 35884, 35885, 35886, 35887, 36888, 36937, 36938, 38213, 44018, 44039, 44041, 44042, 44043, 65482, 122637, 124634, 124635, 124636, 124637, 124638, 139693, 140610, 140611, 140612, 140613, 140614, 140615, 140616, 140617, 155656, 157829, 158667, 159124, 159152, 159153, 159154, 159155, 181368, 181377, 181612, 181745, 182487, 182496, 182505, 182514, 183744, 184294, 184362, 184363, 184765, 184766, 184767, 184768, 184842, 184843, 185717, 207101, 209883, 209889, 220161, 223432, 223472, 224817, 242241, 246936, 247234, 247915, 248027, 248028, 248029, 248053, 248555, 248556, 248557, 248558, 248559, 248560, 248561, 248562, 249400, 249780, 251257, 251724, 251725, 251726, 251727, 251728, 251729, 251730, 251731, 251732, 251733, 251734, 253467, 254267, 254579, 254878, 257143, 264675, 265106, 265631 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206619, ["x"] = 0.368, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206619, ["x"] = 0.368, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.26 }, ["mapCandidates"] =