[76379] = { ["id"] = 76379, ["name"] = "A Murloc and a Dragon Walk into a Time Rift...", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76379 }, ["description"] = "Grurguglg. Guuglrllghulgrgl grugll gur. Murgllgllrugl guglrllg murgu gruggullgl. Murglgurrrr gurgll Gurlgul, guruuuurllgr gurgull gurgllglrl . Argurgulul? <You aren't certain what's being said. This world's version of Alexstrasza is handing you an hourglass and miming flipping it. It is probably of interest to Soridormi .>", ["objectivesText"] = "Bring the Azmerlothian Hourglass to Soridormi in the Tyrhold Reservoir. Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 206599, 208186 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 206822, ["x"] = 0.51, ["y"] = 0.57 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 204450, ["x"] = 0.51, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["startItems"] = { 206599 } },
