[76398] = { ["id"] = 76398, ["name"] = "Aerial Supremacy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76384, 76385, 76386, 76387, 76388, 76389, 76398, 76401, 76416, 76436 }, ["description"] = "The dragonflights have arrived. The skies are ours to reclaim! And you shall help us tip the scales. Mount your drake and target the enemies above. You need only swoop in and take their forces by surprise. Your drake shall handle the rest.", ["objectivesText"] = "Slay 15 enemy proto-drakes flying above the Field of Flames by striking them with your dragonriding mount. Progress: The faster we can take down Fyrakk's aerial forces, the faster we can make our way to the temple and put a stop to this madness.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208567, ["x"] = 0.35, ["y"] = 0.354 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208567, ["x"] = 0.35, ["y"] = 0.354 }, { ["mapID"] = 2200, ["npcID"] = 208573, ["x"] = 0.35, ["y"] = 0.335 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.354 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 76388 }, ["questLines"] = { { ["id"] = 5465, ["name"] = "A Dream of Fields and Fire", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 55, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5465, ["questLineOrder"] = 5 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
