[76401] = { ["id"] = 76401, ["name"] = "Echo of the Firelands", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76384, 76385, 76386, 76387, 76388, 76389, 76398, 76401, 76416, 76436 }, ["description"] = "We have finally broken through the enemy's ranks, yet the Prophet of the Flame now bars our path. And he has unleashed his full power. The Prophet must be defeated if we have any hope of making our way to the temple. I ask you to face him, champion. We shall hold back his forces as you do so. The end is in sight. Let us finally finish this war.", ["objectivesText"] = "Defeat the Prophet of the Flame.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 209931 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208572, ["x"] = 0.35, ["y"] = 0.335 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206921, ["x"] = 0.28, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.335 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 76389, 76398 }, ["questLines"] = { { ["id"] = 5465, ["name"] = "A Dream of Fields and Fire", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 56, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5465, ["questLineOrder"] = 5 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
[76402] = { ["id"] = 76402, ["name"] = "Amirdrassil, the Dream's Hope: Fyrakk", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 75918, 75919, 75920, 75921, 75922, 75923, 76276, 76280, 76281, 76282, 76283, 76317, 76318, 76319, 76320, 76321, 76322, 76323, 76324, 76325, 76326, 76327, 76328, 76329, 76330, 76331, 76332, 76333, 76334, 76335, 76336, 76337, 76342, 76343, 76344, 76345, 76347, 76348, 76384, 76385, 76386, 76387, 76388, 76389, 76398, 76401, 76402, 76403, 76416, 76433, 76434, 76435, 76436, 76437, 76441, 76442, 76443, 76532, 77178, 77200, 77201, 77283, 77329, 77436, 77780, 77781, 77818, 78643, 78646, 78865, 92875 }, ["description"] = "Fyrakk may have entered the temple, but our fight has not ended. Thanks to your efforts, we have broken through his forces. There is still time to stop him. You must gather your allies and follow Fyrakk into the Wellspring Temple. We will cover your flank. Know that it is not only Amirdrassil that you protect this day, <name>. All of Azeroth will burn if Fyrakk claims the World Tree. He must be stopped, here and now. This is our final stand.", ["objectivesText"] = "Enter Amirdrassil, the Dream's Hope, and defeat Fyrakk. Progress: Once, Fyrakk sought to free dragonkind. He raged a war against us for that very ideal. What drove him to seek domination instead? Was it the need for revenge? The desire for power? The same fire that burns can also renew. Yet Fyrakk's flames would swallow the whole world.", ["rewardGold"] = 1239200, ["rewardXP"] = 2830, ["rewardItems"] = { 206960, 208047, 210180, 210916 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206921, ["x"] = 0.28, ["y"] = 0.312 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208503, ["x"] = 0.508, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.28, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "raid", ["sourceQuests"] = { 76401 }, ["questLines"] = { { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 57, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
[76403] = { ["id"] = 76403, ["name"] = "Mayhem Incarnate", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76342, 76343, 76344, 76345, 76347, 76348, 76403, 76532, 77178 }, ["description"] = "We need to uncover exactly what Fyrakk's plan is. He is holding his forces away from the tree, but we do not know why. I can do some scouting, but direct conflict with Fyrakk would not help our cause right now. Follow me further into the Dream. There is a Primalist encampment to the north. Let us start there, so we can put an end to this madness.", ["objectivesText"] = "Speak with Vyranoth near the Primalist encampment.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208506, ["x"] = 0.508, ["y"] = 0.628 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206612, ["x"] = 0.368, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 76443 }, ["questLines"] = { { ["id"] = 5472, ["name"] = "Ice and Fire", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 26, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5472, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
[76404] = { ["id"] = 76404, ["name"] = "Cogs in a Machine", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76404 }, ["description"] = "<This cog spiraled out of a mechanized creature as you sent it back to its timeway. While its design is similar to Mechagnome technology, it's sleeker and more refined. It bears a small inscription. Soridormi will want to see this.>", ["objectivesText"] = "After completing a Time Rift, return to Soridormi in the Tyrhold Reservoir. Progress: Hello again, <name>. What do you have there?", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 206602, 208186 }, ["starts"] = { { ["x"] = 0.577, ["y"] = 0.642, ["mapID"] = 2199 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 204450, ["x"] = 0.51, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["startItems"] = { 206602 } },
[76406] = { ["id"] = 76406, ["name"] = "The Sins of the Ashbringer", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76406 }, ["description"] = "<As you near this blade, you can feel necromantic power thrumming from it. Perhaps you should wrap the sword in cloth and avoid touching it directly. Soridormi will want to see this.>", ["objectivesText"] = "After completing a Time Rift, return to Soridormi in the Tyrhold Reservoir.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 206638, 208186 }, ["starts"] = { { ["x"] = 0.397, ["y"] = 0.58, ["mapID"] = 2199, ["npcID"] = 208328 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 204450, ["x"] = 0.51, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questGiverID"] = 208328, ["questType"] = "standard", ["startItems"] = { 206638 } },
[76407] = { ["id"] = 76407, ["name"] = "Not Today, Fate", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76407, 76419, 76420, 76421, 76422, 76423, 77417 }, ["description"] = "Eternus intends to show us what happened. I think she also seeks to change the past. Normally, I would not entertain this idea, but understanding the infinites is the only way forward.", ["objectivesText"] = "Enter the Time Rift to witness the past. Progress: Eternus has something to show us--I expect we will learn a great deal about her.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 207106, ["x"] = 0.655, ["y"] = 0.802 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 206971, ["x"] = 0.375333, ["y"] = 0.835333 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.655, ["y"] = 0.802 }, ["mapCandidates"] = { ["npc"] = { 71, 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 77417 }, ["questLines"] = { { ["id"] = 5508, ["name"] = "Bronze Reconciliation", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 71 },
[76410] = { ["id"] = 76410, ["name"] = "A Dark Summons", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 75538, 75539, 75540, 75541, 75542, 75543, 75544, 75639, 76155, 76163, 76410 }, ["description"] = "Denizens of Azeroth, Do you thirst for power? Do you wish to change your circumstances, to become... more? More free. More respected. More feared. Do you wish to become a Warlock? If your response to any of the above is \"yes\", then meet with my humble servant Phineas. In temptation, Madam Shadow", ["objectivesText"] = "Talk to Assistant Phineas in the Mage Quarter in Stormwind.", ["rewardGold"] = 84900, ["rewardXP"] = 2060, ["rewardItems"] = { 207101, 208226 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 204198, ["x"] = 0.490667, ["y"] = 0.769333 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.490667, ["y"] = 0.769333 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["nextQuests"] = { 75538 }, ["questLines"] = { { ["id"] = 5383, ["name"] = "Some Wicked Things", ["orderIndex"] = 11, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 84, ["startItems"] = { 208226 } },
[76416] = { ["id"] = 76416, ["name"] = "Forward Unto Fire", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76384, 76385, 76386, 76387, 76388, 76389, 76398, 76401, 76416, 76436 }, ["description"] = "Amirdrassil draws power from the Wellspring Temple in preparation for its bloom. The barrier protecting the temple will not last much longer under Fyrakk's assault. I have sent messengers all across Azeroth asking for reinforcements, but none have yet arrived. Something blocks their path into the Dream. For now, we must rely on the forces we have. I ask you to travel to the Verdant Pass. If there is anyone I would have by my side, it is you.", ["objectivesText"] = "Meet Alexstrasza at the Verdant Pass.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208503, ["x"] = 0.508, ["y"] = 0.628 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208550, ["x"] = 0.388, ["y"] = 0.39 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 76384 }, ["questLines"] = { { ["id"] = 5465, ["name"] = "A Dream of Fields and Fire", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 48, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5465, ["questLineOrder"] = 5 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
[76419] = { ["id"] = 76419, ["name"] = "Violence Will Solve It", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 76407, 76419, 76420, 76421, 76422, 76423, 77417 }, ["description"] = "Do you not agree that Moraidormi can be saved? We infinites often save those we think suffered needlessly--worthy or not. Supposedly, Mori died too close to the Caverns of Time just east of us. Using too much time magic here could have... consequences. But this should be quick. Chrono-Lord Deios was in possession of artifacts that could forcefully rewind time. The bronze dragonflight has them now. We will rewind time and then destroy Vexemia . Simple.", ["objectivesText"] = "Rewind time and defend Moraidormi from Vexemia 's attack. Progress: This will be easy. Which makes one wonder why the bronze dragonflight did not do it before!", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 207634, ["x"] = 0.376, ["y"] = 0.835333 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 207634, ["x"] = 0.376, ["y"] = 0.835333 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.376, ["y"] = 0.835333 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["sourceQuests"] = { 76407 }, ["questLines"] = { { ["id"] = 5508, ["name"] = "Bronze Reconciliation", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 71, ["db2QuestSortName"] = "Nightborne" },
[76420] = { ["id"] = 76420, ["name"] = "Butterfly Effects", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 76407, 76419, 76420, 76421, 76422, 76423, 77417 }, ["description"] = "We were overwhelmed by her companions. Moraidormi was still killed. I need another strategy, one that will actually protect her. She is what matters. Go rewind time, including our actions. After the rewind, I will hold time in place. Then we can try to make defenses for her.", ["objectivesText"] = "After rewinding time, create defenses for Moraidormi and test them. Progress: What else can we do?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 208099 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 207634, ["x"] = 0.376, ["y"] = 0.835333 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 207634, ["x"] = 0.376, ["y"] = 0.835333 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.376, ["y"] = 0.835333 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["sourceQuests"] = { 76419 }, ["questLines"] = { { ["id"] = 5508, ["name"] = "Bronze Reconciliation", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 71, ["db2QuestSortName"] = "Nightborne" },
[76421] = { ["id"] = 76421, ["name"] = "The Fate We Make", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 76407, 76419, 76420, 76421, 76422, 76423, 77417 }, ["description"] = "We just need to be stronger and faster! We cannot leave it like this, not with the eggs also destroyed. I will come up with another idea. Restart time, and... < Eternus sighs.> Perhaps I will listen to Nozdormu. He keeps telling me I have \"missed\" something...", ["objectivesText"] = "Rewind history again and see what Nozdormu has to say. Progress: Doing nothing makes no sense to me, but I will be patient. For now.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 207634, ["x"] = 0.376, ["y"] = 0.835333 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 207634, ["x"] = 0.376, ["y"] = 0.835333 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.376, ["y"] = 0.835333 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["sourceQuests"] = { 76420 }, ["questLines"] = { { ["id"] = 5508, ["name"] = "Bronze Reconciliation", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 71, ["db2QuestSortName"] = "Nightborne" },
[76422] = { ["id"] = 76422, ["name"] = "Infinity and Beyond", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 76407, 76419, 76420, 76421, 76422, 76423, 77417 }, ["description"] = "If we continue to look into the past, we miss out on the present--or even the future. Let us return to Thaldraszus . Do not worry about these time fracture elementals. They too will heal with time. As we all do.", ["objectivesText"] = "Return to the present to check in with Chromie . Progress: I hope this experience can bring us together.", ["rewardGold"] = 140450, ["rewardXP"] = 4760, ["rewardItems"] = { 162690, 204076, 210024 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 206971, ["x"] = 0.375333, ["y"] = 0.835333 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 207106, ["x"] = 0.655, ["y"] = 0.802 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.375333, ["y"] = 0.835333 }, ["mapCandidates"] = { ["npc"] = { 71, 2025 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["sourceQuests"] = { 76421 }, ["questLines"] = { { ["id"] = 5508, ["name"] = "Bronze Reconciliation", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["db2QuestSortName"] = "Nightborne" },
[76423] = { ["id"] = 76423, ["name"] = "No Limits", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76407, 76419, 76420, 76421, 76422, 76423, 77417 }, ["description"] = "After confronting the infinites and, well, myself--we have had a lot to think about. Eternus, one of the infinites, has apparently been thinking a lot too. The infinites want to change Nozdormu into his infinite form, Murozond. We don't want that. And after learning about Nozdormu , I think Eternus may be persuaded to not want that either. I've set up a meeting between Nozdormu and Eternus to get them talking. But I want someone else there... in case something goes wrong.", ["objectivesText"] = "Check on Eternus and Nozdormu .", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 210024 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 206086, ["x"] = 0.592, ["y"] = 0.815 }, { ["mapID"] = 2025, ["npcID"] = 208035, ["x"] = 0.654, ["y"] = 0.804 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 207106, ["x"] = 0.655, ["y"] = 0.802 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.815 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5508, ["name"] = "Bronze Reconciliation", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[76425] = { ["id"] = 76425, ["name"] = "Renowned with the Dream Wardens", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76425 }, ["description"] = "Champion! A moment of your time. We wanted to recognize all your efforts. Meet me back at Central Encampment. We have a token of our appreciation that we'd like to give you.", ["objectivesText"] = "Speak with Keeper Amrymn at the Central Encampment.", ["rewardItems"] = { 210992 }, ["starts"] = { { ["x"] = 0.502, ["y"] = 0.616, ["mapID"] = 2200, ["npcID"] = 208143 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208143, ["x"] = 0.502, ["y"] = 0.616 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.616 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questGiverID"] = 208143, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2575, ["threshold"] = 7500 } } } },
[76426] = { ["id"] = 76426, ["name"] = "The Kalimdor Cup Circuit", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 616, ["mapID"] = 2112, ["storyline"] = { 76426 }, ["series"] = { 76429 }, ["description"] = "The Riders of Azeroth have learned much from us, and now we test their mettle, as well as yours, skyrider! My bronze colleagues have traveled to Kalimdor to create new challenges. They await you with many races across the continent. Are you up to the task?", ["objectivesText"] = "Fly through the Kalimdor Cup courses. Progress: Have you taken wing today?", ["rewardGold"] = 77400, ["rewardXP"] = 1030, ["rewardItems"] = { 197615, 203322, 203349, 206588, 206589, 206590, 206591, 206592, 206593, 206594 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 206737, ["x"] = 0.27, ["y"] = 0.474 }, { ["mapID"] = 84, ["npcID"] = 214111, ["x"] = 0.6, ["y"] = 0.663 }, { ["mapID"] = 85, ["npcID"] = 214112, ["x"] = 0.524, ["y"] = 0.599 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 206737, ["x"] = 0.27, ["y"] = 0.474 }, { ["mapID"] = 84, ["npcID"] = 214111, ["x"] = 0.6, ["y"] = 0.663 }, { ["mapID"] = 85, ["npcID"] = 214112, ["x"] = 0.524, ["y"] = 0.599 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.27, ["y"] = 0.474 }, ["mapCandidates"] = { ["npc"] = { 84, 85, 2112 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["sourceQuests"] = { 76429, 79125, 79126 }, ["db2QuestSortName"] = "Engine of Innovation" },
[76427] = { ["id"] = 76427, ["name"] = "A Dark Summons", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 75539, 75540, 75541, 75542, 75543, 75544, 75639, 76155, 76163, 76427, 76430 }, ["series"] = { 76430 }, ["description"] = "Denizens of Azeroth, Do you thirst for power? Do you wish to change your circumstances, to become... more? More free. More respected. More feared. Do you wish to become a Warlock? If your response to any of the above is \"yes\", then meet with my humble servant Phineas. In temptation, Madam Shadow", ["objectivesText"] = "Talk to Assistant Phineas in the Cleft of Shadow in Orgrimmar.", ["rewardGold"] = 140450, ["rewardXP"] = 2060, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1637 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5383, ["name"] = "Some Wicked Things", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 86, ["startItems"] = { 208227 } },
[76429] = { ["id"] = 76429, ["name"] = "The Kalimdor Cup Begins", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 76429 }, ["series"] = { 76426 }, ["description"] = "Skyrider! You just missed Lord Andestrasz . He's looking for capable skyriders like yourself to compete in new races!", ["objectivesText"] = "Visit Lord Andestrasz in Valdrakken.", ["rewardGold"] = 16980, ["rewardXP"] = 515, ["rewardItems"] = { 197615, 203322, 203349, 206588, 206589, 206590, 206591, 206592, 206593, 206594 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199261, ["x"] = 0.390667, ["y"] = 0.61 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 206737, ["x"] = 0.27, ["y"] = 0.474 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.390667, ["y"] = 0.61 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["nextQuests"] = { 76426 } },
[76430] = { ["id"] = 76430, ["name"] = "Beginning Impositions", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["requiredClasses"] = { 9 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 1637, ["mapID"] = 407, ["storyline"] = { 75539, 75540, 75541, 75542, 75543, 75544, 75639, 76155, 76163, 76427, 76430 }, ["series"] = { 76427 }, ["description"] = "Darkest greetings, <race>. Ahem, yes. Yes! Darkest greetings indeed. <The lanky man seems to suddenly remember where he is.> On behalf of my patron, I bid you travel to the Darkmoon Faire. The Faire! Who doesn't love it? Yes. Yes! Ahem. She requires your presence, she does! Our Lady of the Midnight Moon. The Damsel of Darkness! The Mother of Crows... ... Madam Shadow .", ["objectivesText"] = "Travel to the Darkmoon Faire. Progress: Everyone knows the way to the Faire...", ["rewardGold"] = 140450, ["rewardXP"] = 2060, ["rewardItems"] = { 206681, 207101, 207294, 208227 }, ["starts"] = { { ["x"] = 0.425, ["y"] = 0.518, ["mapID"] = 85, ["npcID"] = 207051 } }, ["ends"] = { { ["x"] = 0.425, ["y"] = 0.518, ["mapID"] = 85, ["npcID"] = 207051 } }, ["coords"] = { ["mapID"] = 85, ["x"] = 0.425, ["y"] = 0.518 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1637 } }, ["questGiverID"] = 207051, ["questTurnInID"] = 207051, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5383, ["name"] = "Some Wicked Things", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 974, ["db2PoiUiMapID"] = 407 },
[76433] = { ["id"] = 76433, ["name"] = "Ashen Soil", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76433, 76434, 76435, 76437, 76441, 76442, 76443, 77436 }, ["description"] = "It seems the Druids of the Flame wasted no time in seeking to expand their influence. Deep within these barrow dens, some manner of corruption has taken root. It will spread if left unchecked, consuming the entire den before expanding outwards to threaten the rest of the dream. Time is short, <name>. Delve into the barrow, seek out the sources of the spreading flame, and excise them before the smoldering embers can grow and spread.", ["objectivesText"] = "Find and excise the source of the barrow den's flame corruption. Progress: Make haste. These flames grow brighter by the moment.", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206247, ["x"] = 0.514, ["y"] = 0.428 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206247, ["x"] = 0.514, ["y"] = 0.428 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.514, ["y"] = 0.428 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 77436 }, ["questLines"] = { { ["id"] = 5471, ["name"] = "Druids of the Flame", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 19, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5471, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
[76434] = { ["id"] = 76434, ["name"] = "Not Yet Lost", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76433, 76434, 76435, 76437, 76441, 76442, 76443, 77436 }, ["description"] = "The flame did not take root here on a whim. No doubt there are servants of the Firelands cloistered within, trying to spread their flame to the creatures that reside within these barrows. We must do what we can to save those who can still be saved, and mete out swift justice to the heretics that lurk within.", ["objectivesText"] = "Rescue the denizens of the Sor'theril Barrow Den. Progress: If even one soul remains languishing within these dens, we must do everything we can to save them.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 209917, 209918, 210235, 210236 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206247, ["x"] = 0.514, ["y"] = 0.428 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206247, ["x"] = 0.514, ["y"] = 0.428 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.514, ["y"] = 0.428 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 77436 }, ["questLines"] = { { ["id"] = 5471, ["name"] = "Druids of the Flame", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 20, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5471, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
[76435] = { ["id"] = 76435, ["name"] = "The Smoldering Copse", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76433, 76434, 76435, 76437, 76441, 76442, 76443, 77436 }, ["description"] = "Andi'thur tells me of smoke rising from a grove to the west. Norana's new allies are not exactly the subtle sort. I do not care what her motivations are. I will not allow her to set another inch of this land ablaze. Ride for the western groves. However the Druids of the Flame plan to seek their so-called rebirth, we will do all we can to stop them.", ["objectivesText"] = "Investigate the Smoldering Copse.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206247, ["x"] = 0.514, ["y"] = 0.428 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 207160, ["x"] = 0.392, ["y"] = 0.486 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.514, ["y"] = 0.428 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 76433, 76434 }, ["questLines"] = { { ["id"] = 5471, ["name"] = "Druids of the Flame", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 21, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5471, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
[76436] = { ["id"] = 76436, ["name"] = "A Scrap of Hope", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76384, 76385, 76386, 76387, 76388, 76389, 76398, 76401, 76416, 76436 }, ["description"] = "It is only a matter of time before Fyrakk's forces decimate our own. And then there will be nothing stopping him from entering the Wellspring Temple. If the Prophet of the Flame is responsible for blocking our reinforcements from entering the Dream, there must be some record or communication of his plan. We just have to find it. Search for any communications amongst Fyrakk's forces at Skystone Falls. If we can disrupt their efforts in some way, we might have a chance to turn the tide.", ["objectivesText"] = "Collect 8 Scraps of Parchment from Fyrakk's forces at Skystone Falls. Progress: If Fyrakk enters the Wellspring Temple, it is not just Amirdrassil that will burn. All of Azeroth will burn with it.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 210023 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208550, ["x"] = 0.388, ["y"] = 0.39 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208550, ["x"] = 0.388, ["y"] = 0.39 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 76385, 76386 }, ["questLines"] = { { ["id"] = 5465, ["name"] = "A Dream of Fields and Fire", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 52, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5465, ["questLineOrder"] = 5 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
[76437] = { ["id"] = 76437, ["name"] = "Burning Ground", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76433, 76434, 76435, 76437, 76441, 76442, 76443, 77436 }, ["description"] = "We allowed ourselves to be distracted. We thought the Druids of the Flame had followed us into the Dream, when clearly they arrived before we did. With Amirdrassil so close at hand, we cannot allow them to plant their ashen roots here. Release their prisoners. Ransack their supplies. Do whatever you can to ensure that this burning corruption does not spread further.", ["objectivesText"] = "Disrupt the Smoldering Copse. Progress: We must act quickly. The further this flame-blighted ground spreads, the more danger our allies will face in the days to come.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 209903, 209905, 209908, 209909 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 207160, ["x"] = 0.392, ["y"] = 0.486 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 207160, ["x"] = 0.392, ["y"] = 0.486 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.392, ["y"] = 0.486 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 76435 }, ["questLines"] = { { ["id"] = 5471, ["name"] = "Druids of the Flame", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 22, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5471, ["questLineOrder"] = 2 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
