[76448] = { ["id"] = 76448, ["name"] = "The Fate of Scalecommander Abereth", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "According to our colleagues, this cave was used to test prospective scalecommanders. Excuse me. It either tested them or housed their remains. The trials were so difficult that it usually amounted to the same thing. We're searching for an ancient scalecommander referenced in our records as \"The Cleaving Blade\": a promising young dracthyr whose future ended abruptly somewhere near this cave. Perhaps we'll discover how their story ends.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["npcID"] = 207311, ["x"] = 0.77, ["y"] = 0.384, ["zoneID"] = 14433 } }, ["ends"] = { { ["npcID"] = 207311, ["x"] = 0.77, ["y"] = 0.384, ["zoneID"] = 14433 } }, ["coords"] = { ["x"] = 0.77, ["y"] = 0.384, ["source"] = "quest_giver", ["zoneID"] = 14433 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 77483 }, ["questLines"] = { { ["id"] = 5517, ["name"] = "Technoscrying: Dragonskull Island", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5469, ["name"] = "Azerothian Archives - Technoscrying Sites", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 33, ["flags"] = 0 } } },
[76449] = { ["id"] = 76449, ["name"] = "The Endless Conflict", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14845, ["mapID"] = 2025, ["storyline"] = { 76449 }, ["description"] = "<You notice a book beside the body of a Great Glorious Alliance soldier. Quickly flicking through the pages, you see that it's some type of journal. Parts of it were ruined by a puddle of oil. Soridormi will want to see this.>", ["objectivesText"] = "Bring the Oil-Soaked Log Book to Soridormi in the Tyrhold Reservoir. Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 206749, 208186 }, ["starts"] = { { ["x"] = 0.12, ["y"] = 0.309, ["mapID"] = 2207 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 204450, ["x"] = 0.51, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 14845 } }, ["questType"] = "standard", ["startItems"] = { 206749 } },
[76453] = { ["id"] = 76453, ["name"] = "A Stony Reception", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14841, ["mapID"] = 2025, ["storyline"] = { 76453 }, ["description"] = "<This chipped stone tablet stands out from its surroundings. As you go to pick it up, it weighs quite a lot more than you expected. Soridormi will want to see this.>", ["objectivesText"] = "Bring the Chipped Stone Tablet to Soridormi in the Tyrhold Reservoir. Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 206859, 208186 }, ["starts"] = { { ["x"] = 0.457, ["y"] = 0.239, ["mapID"] = 2201 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 204450, ["x"] = 0.51, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 14841 } }, ["questType"] = "standard", ["startItems"] = { 206859 } },
[76456] = { ["id"] = 76456, ["name"] = "Using the Idol", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2025, ["storyline"] = { 76456 }, ["description"] = "Ah, the Idol of Ohn'ahra! Let's use it to find gems. I've hidden three gems nearby in Valdrakken , all outside. The idol will reveal the gems when you're near. Come back when you've tracked them down.", ["objectivesText"] = "Use the Idol of Ohn'ahra to find 3 hidden gems , then speak with Preservationist Kathos . Progress: Have you found the gems?", ["rewardItems"] = { 207730, 208092 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 206864, ["x"] = 0.604, ["y"] = 0.59 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 206864, ["x"] = 0.604, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 77304 } },
[76459] = { ["id"] = 76459, ["name"] = "The Resistance", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76459 }, ["description"] = "<The person in front of you is clearly an uncorrupted night elf, albeit significantly more feral and malnourished than usual.> Nice world. No Legion. No fel. If you can, send help. Suramar, ask for Tyrande. < Soridormi may want to see this.>", ["objectivesText"] = "After completing a Time Rift, return to Soridormi in the Tyrhold Reservoir. Progress: Hello again, <name>. What do you have there?", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 206775, 208186 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 207297, ["x"] = 0.51, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 204450, ["x"] = 0.51, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["startItems"] = { 206775 } },
[76460] = { ["id"] = 76460, ["name"] = "A Dragon in Hand is Worth Two in the Roost", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2025, ["storyline"] = { 76460, 76461, 76462, 76463, 76464, 76465, 77195, 77197, 77198 }, ["description"] = "Ah, <name>, so wonderful to see you! You have arrived just in time. I was tasked with seeking out potential allies to aid with the protection of the world tree. Your accomplishments speak for themselves--your help in this matter would be greatly appreciated. What do you say, up for some diplomacy?", ["objectivesText"] = "Talk to Wrathion about his potential allies. Progress: I'm quite excited to meet these new dragons.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 207350, ["x"] = 0.474, ["y"] = 0.676 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 207350, ["x"] = 0.474, ["y"] = 0.676 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.676 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5474, ["name"] = "Misfit Dragons", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
[76461] = { ["id"] = 76461, ["name"] = "Draconic Diplomacy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2025, ["storyline"] = { 76460, 76461, 76462, 76463, 76464, 76465, 77195, 77197, 77198 }, ["description"] = "I suspect Vyranoth might also be interested in recruiting new dragons to our cause... but she'll need a little convincing. I just so happen to be very good at convincing. I'll speak with Vyranoth, and we'll meet you in Valdrakken once she's decided to join us.", ["objectivesText"] = "Talk to Prince Mordenaku at the Petitioners Concourse in Valdrakken. Progress: The netherwing are a fascinating flight.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 207350, ["x"] = 0.474, ["y"] = 0.676 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 207350, ["x"] = 0.474, ["y"] = 0.676 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.676 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 76460 }, ["questLines"] = { { ["id"] = 5474, ["name"] = "Misfit Dragons", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[76462] = { ["id"] = 76462, ["name"] = "Cavern Cleaning", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 634, ["storyline"] = { 76460, 76461, 76462, 76463, 76464, 76465, 77195, 77197, 77198 }, ["description"] = "This cave is adequate. It has a commanding view of the surrounding land, and is highly defensible. But the state of it is not acceptable. I will place an enchantment upon you. When you draw near to the smaller spiders, it will freeze them, allowing us to relocate them. The sacs and larger spider will need to be addressed with more... finality. See that it is done.", ["objectivesText"] = "Clean out the spiders in the cave above the Sand-Lost Sanctum in Thaldraszus. Progress: Have you finished?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 207351, ["x"] = 0.51, ["y"] = 0.838 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 207351, ["x"] = 0.51, ["y"] = 0.838 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.838 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 77195 }, ["questLines"] = { { ["id"] = 5474, ["name"] = "Misfit Dragons", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[76463] = { ["id"] = 76463, ["name"] = "Delectable Delicacies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 76460, 76461, 76462, 76463, 76464, 76465, 77195, 77197, 77198 }, ["description"] = "Of course we will take care of the netherwhelps. However, we might run low on snacks. The beetles close by are a delicious treat for the little ones. Can you bring me back some juicy beetle bits ? Only the best for the little darlings!", ["objectivesText"] = "Retrieve 10 Juicy Beetle Bits from Juicy Beetles in the Ruby Lifepools in Waking Shores. Progress: The whelps just love to gobble up those beetle bits.", ["rewardGold"] = 280900, ["rewardXP"] = 1060, ["rewardItems"] = { 208060 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 185904, ["x"] = 0.615, ["y"] = 0.686 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 185904, ["x"] = 0.615, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.686 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 77197 }, ["questLines"] = { { ["id"] = 5474, ["name"] = "Misfit Dragons", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[76464] = { ["id"] = 76464, ["name"] = "The Thorignir", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 634, ["storyline"] = { 76460, 76461, 76462, 76463, 76464, 76465, 77195, 77197, 77198 }, ["description"] = "The Thorignir of Stormheim have the strength and power to greatly aid us in defending Amirdrassil, but they have yet to come to the Dragon Isles. I suspect this... Odyn has interfered with their journey. We will go and speak with their matriarch. Wrathion tells me her brood is amenable to your kind, and to assisting others. We will investigate.", ["objectivesText"] = "Speak with the Thorignir Broodmother. Progress: We will find out why this brood of storm drakes did not heed the call of the Isles.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 207351, ["x"] = 0.51, ["y"] = 0.838 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 207351, ["x"] = 0.51, ["y"] = 0.838 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.838 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 77198 }, ["questLines"] = { { ["id"] = 5474, ["name"] = "Misfit Dragons", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[76465] = { ["id"] = 76465, ["name"] = "Dragon Keeping", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 634, ["storyline"] = { 76460, 76461, 76462, 76463, 76464, 76465, 77195, 77197, 77198 }, ["description"] = "First he opposes dragonkind, then he enslaves them, denying them their birthrights. We shall visit these so-called \"Halls of Valor,\" defeat any who oppose us, and liberate the storm drakes from that which binds them. Come along.", ["objectivesText"] = "Speak to Vyranoth and complete the Storm the Halls of Valor scenario. Progress: These dragons will be freed.", ["rewardGold"] = 929400, ["rewardXP"] = 2125, ["rewardItems"] = { 14344, 206156, 208067, 210959 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 207351, ["x"] = 0.51, ["y"] = 0.838 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208506, ["x"] = 0.508, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.838 }, ["mapCandidates"] = { ["npc"] = { 634, 2200 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 76464 }, ["questLines"] = { { ["id"] = 5474, ["name"] = "Misfit Dragons", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
