[76504] = { ["id"] = 76504, ["name"] = "The Tricked-Out Thinking Cap", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 76504 }, ["series"] = { 76560 }, ["description"] = "The cap has an amazing function: Put it on, and you'll know where you're going! Let's practice! The arrow above me has a clue on it, to another arrow somewhere in Valdrakken . And THAT arrow leads to another... Follow the arrows until you find them all, and the prize at the end!", ["objectivesText"] = "Use the Tricked-Out Thinking Cap to find Fangli's clues, then return to Fangli Hoot . Progress: You must wear your cap at all times while contemplating secrets. You never know what frequencies you might tap into, or who might tapping into yours.", ["rewardItems"] = { 206696, 206944 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 207697, ["x"] = 0.2656, ["y"] = 0.5432 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 207697, ["x"] = 0.2656, ["y"] = 0.5432 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.2656, ["y"] = 0.5432 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 77237 } },
