[76532] = { ["id"] = 76532, ["name"] = "Assault on the Wellspring", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76342, 76343, 76344, 76345, 76347, 76348, 76403, 76532, 77178 }, ["description"] = "Terro gave his life to protect the Dream. Which means we must see it through. Vyranoth should be able to handle Lethka, we must find Suzska . I hope Lethka did not attack her first. We should start looking near the Wellspring. Meet me there so we can continue our search.", ["objectivesText"] = "Spy on the Wellspring of Life with Buri . Progress: Come on, let's head to the Wellspring.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 210178, ["x"] = 0.395, ["y"] = 0.228 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208378, ["x"] = 0.276, ["y"] = 0.322 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.228 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 76344, 76345 }, ["questLines"] = { { ["id"] = 5472, ["name"] = "Ice and Fire", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 31, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5472, ["questLineOrder"] = 3 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
[76533] = { ["id"] = 76533, ["name"] = "Dangerous Documentation", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14846, ["mapID"] = 2025, ["storyline"] = { 76533 }, ["description"] = "<The flickering of a hologram stands out among the surrounding greenery.> A quick investigation of the item reveals this is some sort of catalog left by a Watcher in its timeway. It details observations of the yaungol, ancestors of the tauren. < Soridormi will want to see this.>", ["objectivesText"] = "Return to Soridormi in the Tyrhold Reservoir. Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 206962, 208186 }, ["starts"] = { { ["x"] = 0.582, ["y"] = 0.39, ["mapID"] = 2205, ["npcID"] = 207525 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 204450, ["x"] = 0.51, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 14846 } }, ["questGiverID"] = 207525, ["questType"] = "standard", ["startItems"] = { 206962 } },
