[76552] = { ["id"] = 76552, ["name"] = "In Sync", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76552 }, ["description"] = "While Pedgi had you out killing slimes, I asked the investigators here how we can actually help. Seems quite a few of them are stuck in time anomalies. Luckily, I've just finished giving the metronographer a few temporal upgrades. It should now help the investigators get back in sync. But we need to test it out first. Looks like there's someone nearby who will do the trick.", ["objectivesText"] = "Test the upgraded Metronographer. Progress: Oh, I saw that Pedgi had you collect time slime grime for me. I did not ask for it and I do not need it. <Melly sighs a long suffering sigh.> At least he's trying to be helpful.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 166846, 208401 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 204990, ["x"] = 0.538, ["y"] = 0.8416 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 204990, ["x"] = 0.538, ["y"] = 0.8416 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.8416 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 74476, 74942 } },
