[76562] = { ["id"] = 76562, ["name"] = "Moat Maintenance", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76562 }, ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.511, ["y"] = 0.185, ["mapID"] = 2200 } }, ["ends"] = { { ["x"] = 0.511, ["y"] = 0.185, ["mapID"] = 2200 } }, ["coords"] = { ["mapID"] = 2200, ["x"] = 0.511, ["y"] = 0.185 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14529 } }, ["questType"] = "world", ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 6, ["objectID"] = 209523 }, { ["orderIndex"] = 1, ["type"] = 0, ["amount"] = 6, ["objectID"] = 209521 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[76564] = { ["id"] = 76564, ["name"] = "The Tools of the Dragonkillers", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "If you're going to go after a dragon, who better to employ than the Djaradin? Let's see what we can find, <name>.", ["objectivesText"] = "Locate the three attunement relics. Progress: Without those attunement relics we won't be able to solve this mystery, <name>.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 202247 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 207763, ["x"] = 0.382, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 207763, ["x"] = 0.382, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.382, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 77484 }, ["questLines"] = { { ["id"] = 5469, ["name"] = "Azerothian Archives - Technoscrying Sites", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5516, ["name"] = "Technoscrying: Igira's Watch", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 38, ["flags"] = 0 } }, ["db2LabelIDs"] = { 3079 }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[76566] = { ["id"] = 76566, ["name"] = "The Dryad Garden", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76566 }, ["description"] = "$p, there is a situation I am personally concerned about. A garden cared for by my kin, the dryads, has suffered from growing pains amidst Amirdrassil's growth. An overwrought druid currently tends the garden, but I suspect he will need more assistance than he has requested. Please assist him in his task on my behalf.", ["objectivesText"] = "Speak with Ethidris Creekward in the Root-Bound Sanctuary.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 209318, ["x"] = 0.508, ["y"] = 0.62 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 207779, ["x"] = 0.538, ["y"] = 0.745 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 78904 }, ["nextQuests"] = { 76567 } },
[76567] = { ["id"] = 76567, ["name"] = "Grousing Garden", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76567 }, ["series"] = { 76568, 76569, 76570 }, ["description"] = "The sanctuary has been overrun! The roots of the World Tree have grown alongside this garden, but it seems the wildlife have grown uncomfortable with the change. Please help them get out their restless energy. Perhaps tired out, they will relax in this space again.", ["objectivesText"] = "Tire out 8 wildlife in the Root-Bound Sanctuary. Progress: <Ethidris winces and rubs his shoulder.> You would think being a bear would lend oneself resistance to being knocked around by deer.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 207779, ["x"] = 0.538, ["y"] = 0.745 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 207779, ["x"] = 0.538, ["y"] = 0.745 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.745 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 76566 } },
[76568] = { ["id"] = 76568, ["name"] = "Pineshrew Panic", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76568 }, ["series"] = { 76567, 76569, 76570 }, ["description"] = "With the garden in such disarray, the pineshrews here are hoarding seeds. Important seeds. Seeds we've spent a lot of time caring for and teaching. A gentle shake will release the seeds properly. Please hurry before they run off with any more!", ["objectivesText"] = "Shake out 20 Pineshrew seeds in the Root-Bound Sanctuary. Progress: Ordinarily, pineshrews shake out collected seeds across the Dream to promote variety and growth. It's a beautiful cycle. If you have a few hours, I have a lesson prepared about pineshrew migration habits.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 207779, ["x"] = 0.538, ["y"] = 0.745 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 207779, ["x"] = 0.538, ["y"] = 0.745 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.745 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[76569] = { ["id"] = 76569, ["name"] = "Druid-Guardian Conference", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76569 }, ["series"] = { 76567, 76568, 76570 }, ["description"] = "Typically, the druid assigned to a dryad sanctuary would guide a newborn dryad until they were ready to take on a position of their own. Unfortunately, it is difficult to separate a dryad from whoever she imprints on. <Ethidris sighs and rubs his eyes.> Which she has made very clear. Regardless, tell me about yourself. Perhaps you will be just as apt a caretaker as I would have been.", ["objectivesText"] = "Speak with Ethidris Creekward about raising a dryad in the Root-Bound Sanctuary. Progress: <Ethidris furrows his brow at Dionaessa.> Among so many other things happening right now, there's a new dryad to raise.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 211371 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 207779, ["x"] = 0.538, ["y"] = 0.745 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 207779, ["x"] = 0.538, ["y"] = 0.745 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.745 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 76568 } },
[76570] = { ["id"] = 76570, ["name"] = "The Family Business", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76570 }, ["series"] = { 76567, 76568, 76569 }, ["description"] = "I was charged with imparting knowledge on every dryad seed. Dionaessa will have retained all of my teachings, but she will be unpracticed in implementing them. Since it seems you are practiced at completing tasks, you will show Dionaessa the ropes. A group of lashers have grown strangely restless in the Twisting Wood just outside the garden. Collect some of their hearts so we can discern what has happened.", ["objectivesText"] = "Collect 6 Lasher Hearts in the Twisting Wood near the Root-Bound Sanctuary. Progress: The druid Creekward told me lashers tend to lie in wait for their prey. I'm glad these are not. Makes the fight more interesting!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 208732 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 207779, ["x"] = 0.538, ["y"] = 0.745 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 207779, ["x"] = 0.538, ["y"] = 0.745 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.745 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questTurnInID"] = 207779, ["questType"] = "standard", ["sourceQuests"] = { 76569 } },
[76571] = { ["id"] = 76571, ["name"] = "Growth Experience", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76571 }, ["description"] = "Dionaessa's connection to Cenarius gives her the ability to grow plants, but she needs space to practice. The stirred-up wildlife here will be in your way. The Twisting Wood nearby will have plenty of space with far fewer hooves. <Melyrine smiles. Her eyes shine with intensity.> If she gets poisoned by a podling, don't worry. Dryads are immune to poison. You are not.", ["objectivesText"] = "Have Dionaessa grow 3 flowers in the Twisting Wood. Progress: Do you smell that? <Dionaessa scrunches up her face.> The druid Creekward did not describe lashers and podlings as smelling so foul. I have been misled!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 207781, ["x"] = 0.538, ["y"] = 0.745 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 207781, ["x"] = 0.538, ["y"] = 0.745 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.745 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questTurnInID"] = 207781, ["questType"] = "standard", ["sourceQuests"] = { 76569 } },
[76572] = { ["id"] = 76572, ["name"] = "A Poisonous Promotion", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76572 }, ["description"] = "Guardian! These podlings have been poisoning the lashers, and now they have twisted that mandragora! If we do not stop it, it will spread the poison to the garden. This must be what had the wildlife in the garden so disturbed. They were on the verge of invasion! Let us kill it. This is what you have prepared me for--a dire quest!", ["objectivesText"] = "Defeat the Sickened Growth in the Twisting Wood.", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 208067 }, ["starts"] = { { ["npcID"] = 210813 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 209788, ["x"] = 0.538, ["y"] = 0.745 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.745 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questGiverID"] = 210813, ["questType"] = "standard", ["sourceQuests"] = { 76570, 76571 } },
[76576] = { ["id"] = 76576, ["name"] = "An Unlikely Proposal", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "Tuskarr artifacts, underground, deep in Djaradin territory? If we didn't find it ourselves I wouldn't believe it. What do you think they were doing down here? Ok looks like the nexus point is right here in this cave. Let's get to the bottom of this!", ["objectivesText"] = "Observe the Scene from the past. Progress: I wonder what we'll find?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 202247 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 207763, ["x"] = 0.382, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 207763, ["x"] = 0.382, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.382, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["sourceQuests"] = { 76564 }, ["questLines"] = { { ["id"] = 5469, ["name"] = "Azerothian Archives - Technoscrying Sites", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5516, ["name"] = "Technoscrying: Igira's Watch", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 39, ["flags"] = 0 } }, ["db2LabelIDs"] = { 3079 }, ["db2PoiMapID"] = 2454, ["db2PoiUiMapID"] = 2133 },
[76577] = { ["id"] = 76577, ["name"] = "Brewfest in Valdrakken", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Brewfest", ["expansion"] = 10, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 76577 }, ["description"] = "We've sent some Brewfest shipments off to the Dragon Isles. I've heard they've started some of their own celebrations! Of course ye can't beat the festivities here, but it may be worth paying the dragons a visit!", ["objectivesText"] = "Speak to Bragdur Battlebrew in Valdrakken on the Dragon Isles.", ["starts"] = { { ["mapID"] = 27, ["npcID"] = 24710, ["x"] = 0.506, ["y"] = 0.491 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 207496, ["x"] = 0.298, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.506, ["y"] = 0.491 }, ["mapCandidates"] = { ["npc"] = { 27, 2112 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Epic" },
[76578] = { ["id"] = 76578, ["name"] = "Khaz Algar Rally", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 76578 }, ["description"] = "Race through the checkpoint rings marking the course. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(76578)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(76578))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["objectivesText"] = "Race through the rings.", ["rewardItems"] = { 188134, 191140 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14717 } }, ["questType"] = "standard" },
