[76588] = { ["id"] = 76588, ["name"] = "Defender of the Flame", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 76588 }, ["description"] = "The Expedition forces face formidable adversaries. Drawn like moths to our keyflames, creatures of all types are intent on snuffing out the light and thwarting our rebuilding efforts. Please help us defeat two of the most menacing denizens that threaten our keyflames. Together, we can drive back this darkness.", ["objectivesText"] = "Eliminate two rare creatures within the areas controlled by the keyflames. Progress: Have you eliminated the threats?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 206350, 228741, 233290, 233299 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 215527, ["x"] = 0.654, ["y"] = 0.322 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 215527, ["x"] = 0.654, ["y"] = 0.322 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.654, ["y"] = 0.322 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 81990 }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[76591] = { ["id"] = 76591, ["name"] = "Bubbling Brews", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["event"] = "Brewfest", ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 76591 }, ["description"] = "Drat! I might've made a mistake asking the dracthyr to help with these deliveries. They've been rolling barrels of brews through the city and crashing 'em all over the place! Well, we shouldn't let the brew go to waste if we can help it! Take a barrel an' take to the skies! Try to collect and save as much of the brew as you can by collecting the bubbles.", ["objectivesText"] = "Collect brew bubbles in Valdrakken. Progress: Have ye filled up the barrel?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 37829 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 207496, ["x"] = 0.298, ["y"] = 0.565 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 207496, ["x"] = 0.298, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.298, ["y"] = 0.565 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2751 } },
[76592] = { ["id"] = 76592, ["name"] = "A Single Wing", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13646, ["mapID"] = 2024, ["description"] = "Amythora has returned with grave news. The Sundered Flame live on! We have been trying to locate and repatriate independent bands of dracthyr here in Valdrakken. I sent Amythora and Marithos to talk to the last of them, but Amythora reports they are a remnant of the Sundered Flame. And they have captured Marithos! Given that he used to be one of them, Marithos could be in grave danger. We must investigate and ensure his safety.", ["rewardGold"] = 140450, ["rewardXP"] = 4760, ["starts"] = { { ["npcID"] = 207790, ["x"] = 0.232, ["y"] = 0.372, ["mapID"] = 2112 } }, ["ends"] = { { ["npcID"] = 208236, ["x"] = 0.74, ["y"] = 0.548, ["mapID"] = 2024 } }, ["coords"] = { ["x"] = 0.232, ["y"] = 0.372, ["source"] = "quest_giver", ["mapID"] = 2024 }, ["mapCandidates"] = { ["npc"] = { 2024, 2112 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5464, ["name"] = "Reconciliation", ["orderIndex"] = 0, ["flags"] = 0 } } },
[76593] = { ["id"] = 76593, ["name"] = "The Best Intentions", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 76592, 76593, 76594, 76595, 76597, 77098, 77163 }, ["description"] = "Not only did they beat him--they put him in shackles too! What's worse is... I probably would have done the same... We will not be able to carry Marithos out of here with this weight chained to him. The key must be around the camp somewhere. Try to find it, <name>, while I keep him comfortable.", ["objectivesText"] = "Look for a key to Marithos's shackles in the Lonely Falls. Progress: We must free Marithos from his bonds.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 208014 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 207819, ["x"] = 0.748, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 207819, ["x"] = 0.748, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.748, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 77098 }, ["questLines"] = { { ["id"] = 5464, ["name"] = "Reconciliation", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[76594] = { ["id"] = 76594, ["name"] = "Dracthyr Down", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 76592, 76593, 76594, 76595, 76597, 77098, 77163 }, ["description"] = "What was done to Marithos goes beyond what simple healing can fix. If we expect him to fly out of here, he will need extra care. Thankfully, there are herbs nearby that may give his healing a boost--enough to get him standing, anyway. Look around and collect some of the Wingfoil nearby, <name>.", ["objectivesText"] = "Look for Wingfoil herbs in the Lonely Falls. Progress: Have you found that Wingfoil ? Marithos cannot fly without it.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 208004 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 207819, ["x"] = 0.748, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 207819, ["x"] = 0.748, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.748, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 77098 }, ["questLines"] = { { ["id"] = 5464, ["name"] = "Reconciliation", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[76595] = { ["id"] = 76595, ["name"] = "Urgent Exfiltration", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 76592, 76593, 76594, 76595, 76597, 77098, 77163 }, ["description"] = "The Sundered Flame here are not going to take Quartermaster Doros's death well... They are going to come looking for me. Marithos and Amythora are vulnerable. We cannot let them find us. Secure the perimeter and keep the Sundered Flame away from Amythora and Marithos.", ["objectivesText"] = "Keep the Sundered Flame away from Amythora and Marithos. Progress: If they find us, I do not think the Sundered Flame loyalists will take prisoners.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 204076 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 207820, ["x"] = 0.748, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 207820, ["x"] = 0.748, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.748, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 76593, 76594, 77163 }, ["questLines"] = { { ["id"] = 5464, ["name"] = "Reconciliation", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[76597] = { ["id"] = 76597, ["name"] = "On New Wings", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 76592, 76593, 76594, 76595, 76597, 77098, 77163 }, ["description"] = "I am glad that Winglord Dezran arrived when he did. If he had not, this would have gone... very differently. We must take Marithos back to Valdrakken so he can recuperate, but once I have debriefed Dezran, we will send an envoy to help re-introduce them to our people. They have suffered. We have suffered. Perhaps now we can all heal. Follow me back to Valdrakken. We have much to discuss.", ["objectivesText"] = "Talk to Emberthal in Valdrakken.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 250912 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 207820, ["x"] = 0.748, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 207790, ["x"] = 0.232, ["y"] = 0.374 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.748, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 2024, 2112 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 76595 }, ["questLines"] = { { ["id"] = 5464, ["name"] = "Reconciliation", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
[76598] = { ["id"] = 76598, ["name"] = "Rough Edges", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76598 }, ["description"] = "I apologize for not meeting you in person, <name>, but this method seemed most timely. Our war against the Primalists has always troubled our queen, but recently she has grown increasingly upset. Something weighs on her. I know how heavy the burdens of the mind can become. She left Valdrakken some time ago, saying she needed to find a quiet place to think, but... I am concerned. Please--seek her out, and make sure she is all right. She does not need to know I sent you.", ["objectivesText"] = "Find Alexstrasza and check on her.", ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 208052, ["x"] = 0.548, ["y"] = 0.814 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 208004, ["x"] = 0.565, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.814 }, ["mapCandidates"] = { ["npc"] = { 2022, 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 77437 } },
[76600] = { ["id"] = 76600, ["name"] = "Right Between the Gyro-Optics", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 76600 }, ["description"] = "My husband Ezgi loves those harvesters, but I don't trust them, and now you can see why! The lights go out, and they all start trying to kill us! You want to help me sort this out? I'm a crack shot with a rifle. You mark the target, and I'll start shooting!", ["objectivesText"] = "With Auebry's help, eliminate 8 Dark-Crazed Harvesters .", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 207084, 228741 }, ["rewardCurrencies"] = { { ["id"] = 2899, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 206441, ["x"] = 0.652, ["y"] = 0.28 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 212398, ["x"] = 0.652, ["y"] = 0.28 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.28 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 76599 } },
[76733] = { ["id"] = 76733, ["name"] = "Tater Trawl", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 76733 }, ["description"] = "Harvesting in this area has become a challenge, with crazed Harvesters destroying most of our crops. There are potatoes to be found if you look closely. If you light the harvest torches, you might uncover some potatoes hiding in the shadows. Using those lights, gather as many potatoes as you can. Every bit helps in these trying times.", ["objectivesText"] = "Light 5 Harvest Torches and gather 15 Firelight Spuds . Progress: Have you found any spuds?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 210745 }, ["rewardCurrencies"] = { { ["id"] = 2899, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 206441, ["x"] = 0.652, ["y"] = 0.28 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 206441, ["x"] = 0.652, ["y"] = 0.28 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.28 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 76599 } },
