[76997] = { ["id"] = 76997, ["name"] = "Lost in Shadows", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 76997 }, ["description"] = "Greetings, <name>. I find myself in a dire situation. Some fresh recruits and I were on patrol in these lands when our torches went out, leaving us utterly lost and disoriented. I found safety in this house, but most of the recruits fled, confused into the darkness. Will you help me locate them? I have a spare Patrol Torch . The mere sight of it should rally them to your side.", ["objectivesText"] = "Find and rally 3 Demoralized Recruits using the Patrol Torch . Progress: Have you found the recruits?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 211872, 228741 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 40 }, { ["id"] = 2899, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 208186, ["x"] = 0.646, ["y"] = 0.306 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 208186, ["x"] = 0.646, ["y"] = 0.306 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.646, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78452 } },
