[77100] = { ["id"] = 77100, ["name"] = "Surveying the Cliffside", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "Nothing like brisk ocean air to get you in the mood to dig! We're standing in the rubble of an ancient dragonkin fishing village. These dragonkin were ancestors of the blue dragonkin that live on the island today. Humble as it is, the remote location means it's gone relatively undisturbed by treasure hunters. If there's anything left that hasn't fallen into the sea, we'll find it!", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["npcID"] = 208362, ["x"] = 0.172, ["y"] = 0.164, ["zoneID"] = 14433 } }, ["ends"] = { { ["npcID"] = 208398, ["x"] = 0.142, ["y"] = 0.148, ["zoneID"] = 14433 } }, ["coords"] = { ["x"] = 0.172, ["y"] = 0.164, ["source"] = "quest_giver", ["zoneID"] = 14433 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 77487 }, ["questLines"] = { { ["id"] = 5468, ["name"] = "Azerothian Archives - Excavation Sites", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 28, ["flags"] = 0 } } },
[77101] = { ["id"] = 77101, ["name"] = "Ingredient Quest Template", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77101 }, ["description"] = "Ricket sent word that she was here in Mechagon, so I came right away to help with the uh... research. I had the peons scour the island for any technology they could find. With da stuff we got here, we gonna make some amazing weapons to fight King Mechagon. Then afterwards, we get rich selling 'em! Help me wrangle everyone's ideas into one perfect weapon!", ["objectivesText"] = "Help Rocket-Chief Fuselage build the perfect weapon.", ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14529 } }, ["questType"] = "standard" },
