[77154] = { ["id"] = 77154, ["name"] = "A Taste of the Past", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14433, ["mapID"] = 2151, ["description"] = "Usually, we go to great lengths to avoid busting artifacts open, but I think in this case we'll learn more about the past from what's inside than just staring at a sealed barrel. That said, there's someone we should get permission from first. It's her history, after all. In fact, I think she's the only person still around who might have a personal stake in this find. I'll see to getting this up the cliff. Ask if Atrenosh Hailstone wants to watch us crack 'er open, eh?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["npcID"] = 208398, ["x"] = 0.142, ["y"] = 0.148, ["zoneID"] = 14433 } }, ["ends"] = { { ["npcID"] = 208362, ["x"] = 0.172, ["y"] = 0.164, ["zoneID"] = 14433 } }, ["coords"] = { ["x"] = 0.142, ["y"] = 0.148, ["source"] = "quest_giver", ["zoneID"] = 14433 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14433 } }, ["questType"] = "standard", ["sourceQuests"] = { 77151 }, ["questLines"] = { { ["id"] = 5468, ["name"] = "Azerothian Archives - Excavation Sites", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 30, ["flags"] = 0 } } },
