[77166] = { ["id"] = 77166, ["name"] = "A Practical Test", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "Now that you know how to use the device, we will put your skills to the test. I have attuned your Technoscryers to a valuable item hidden somewhere on this island. Provided you can find it, we will use it to view a scene from the past and deduce how it got there. It is time for science! Put... the goggles... on! Resume your scrying!", ["objectivesText"] = "Use the Technoscryers to find the hidden object. Progress: Have you found that hidden object, <name>?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 202247 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 208355, ["x"] = 0.616, ["y"] = 0.305333 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 208355, ["x"] = 0.616, ["y"] = 0.305333 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.305333 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 77231 }, ["questLines"] = { { ["id"] = 5466, ["name"] = "Azerothian Archives - Tutorial", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2LabelIDs"] = { 3079 }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
