[77208] = { ["id"] = 77208, ["name"] = "Barreling Down", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["event"] = "Brewfest", ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 77208 }, ["description"] = "If it's ale ye be looking for, we've plenty to sample! Or at least we would if the Valdrakken folk would hurry up and bring the rest of the barrels down here. We've shipped our Brewfest brews here so they can celebrate--and wouldn't ye know it, they've already started their own traditions! Rolling barrels through the city? That's no way to treat a good brew! Mind lending a hand to bring those barrels down here? And try not to break 'em!", ["objectivesText"] = "Deliver barrels to the Artisan's Market in Valdrakken. Progress: Careful with the barrels! Ye shouldn't jostle a good ale.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 37829 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 207496, ["x"] = 0.298, ["y"] = 0.565 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 207496, ["x"] = 0.298, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.298, ["y"] = 0.565 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2751 } },
[77209] = { ["id"] = 77209, ["name"] = "Seed Legacy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77209 }, ["description"] = "For years I worked with Denalan in Teldrassil. His research will be the foundation of how we will restore these seeds. The first step: we must coax them back to life, allowing them to grow into vibrant blossoming plants. I have located suitable patches of soil where the plants can take root and grow, revealing their true potential. We will plant one small, one plump, and one gigantic seed to observe how the quality of the seed can sprout different growth.", ["objectivesText"] = "Plant a seed at each of the Dreamsoil patches. Progress: Have you planted the seeds?", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 210014, 210050 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 211265, ["x"] = 0.596, ["y"] = 0.168 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 211265, ["x"] = 0.596, ["y"] = 0.168 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.168 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 78172 }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
[77231] = { ["id"] = 77231, ["name"] = "Technoscrying 101", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "Through a near-perfect blend of technology and arcane enchantment, I have developed a way to analyze the psychometric properties of objects. Wearing these goggles, you can see the data as dynamic simulacra! Simple, yes? I call it... the Psychometric Visuo-Auditory Discrete Waveform Analysis and Viewing Device! For the layperson, we're calling them \" Technoscryers .\" Trademark and patent pending. Here, try them on!", ["objectivesText"] = "Learn to use the Technoscryers . Progress: I have given you the Technoscryers . Please! Put them on!", ["rewardGold"] = 210675, ["rewardXP"] = 7135, ["rewardItems"] = { 208084 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 208355, ["x"] = 0.616, ["y"] = 0.305333 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 208355, ["x"] = 0.616, ["y"] = 0.305333 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.305333 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 77325 }, ["questLines"] = { { ["id"] = 5466, ["name"] = "Azerothian Archives - Tutorial", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2LabelIDs"] = { 3079 }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[77236] = { ["id"] = 77236, ["name"] = "When Time Needs Mending", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 77236 }, ["description"] = "We need to close rifts. We need to fix timeways. Honestly, we need all the help we can get. There's always more work to do. Are you ready for the next challenge?", ["objectivesText"] = "Close a Time Rift by defeating a Fractured Causality. Progress: Come now, these rifts aren't going to close themselves.", ["rewardItems"] = { 204076, 207002, 207030, 207582, 207583, 207584, 208090, 208945, 208951, 208952, 215363, 224298 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 204450, ["x"] = 0.51, ["y"] = 0.57 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 204450, ["x"] = 0.51, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 77679 } },
