[77242] = { ["id"] = 77242, ["name"] = "Many Invader's Scourgestones", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 139, ["mapID"] = 23, ["storyline"] = { 77242 }, ["objectivesText"] = "Progress: An Invader's Scourgestone was the insignia of the Scourge's elite troops. These were sometimes found on the stronger of the troops positioned in Stratholme and Scholomance. I formerly exchanged valor tokens for these. While I doubt you will ever find more, please bring any others back to me immediately so I can see to their destruction.", ["rewardItems"] = { 12844, 206374, 206576 }, ["starts"] = { { ["mapID"] = 23, ["npcID"] = 11039, ["x"] = 0.756, ["y"] = 0.536667 } }, ["ends"] = { { ["mapID"] = 23, ["npcID"] = 11039, ["x"] = 0.756, ["y"] = 0.536667 } }, ["coords"] = { ["mapID"] = 23, ["source"] = "quest_giver", ["x"] = 0.756, ["y"] = 0.536667 }, ["mapCandidates"] = { ["npc"] = { 23 }, ["zone"] = { 139 } }, ["questType"] = "standard" },
[77243] = { ["id"] = 77243, ["name"] = "Many Corruptor's Scourgestones", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 139, ["mapID"] = 23, ["storyline"] = { 77243 }, ["objectivesText"] = "Progress: A Corruptor's Scourgestone was the insignia of the Scourge's overlords. Powerful beings that once held a position of authority over the Scourge always possessed one. I formerly exchanged valor tokens for these. While I doubt you will ever find more, please bring any others back to me immediately so I can see to their destruction.", ["rewardItems"] = { 12844, 206375, 206576 }, ["starts"] = { { ["mapID"] = 23, ["npcID"] = 11039, ["x"] = 0.756, ["y"] = 0.536667 } }, ["ends"] = { { ["mapID"] = 23, ["npcID"] = 11039, ["x"] = 0.756, ["y"] = 0.536667 } }, ["coords"] = { ["mapID"] = 23, ["source"] = "quest_giver", ["x"] = 0.756, ["y"] = 0.536667 }, ["mapCandidates"] = { ["npc"] = { 23 }, ["zone"] = { 139 } }, ["questType"] = "standard" },
[77244] = { ["id"] = 77244, ["name"] = "Many Corruptor's Scourgestones", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 3456, ["storyline"] = { 77244 }, ["objectivesText"] = "Progress: I doubt I need to give you the entire spiel about scourgestones, <name>, so I will cut to the chase. I am VERY interested in growing my collection, and you are VERY interested in what I have to offer. Corruptor's Scourgestones are by far the most powerful, so we can talk business if you only have a few. And don't tell the Argent Dawn about this! It's our little secret, right pal?", ["rewardItems"] = { 12844, 206375, 206576 }, ["starts"] = { { ["npcID"] = 206572 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3456 } }, ["questGiverID"] = 206572, ["questType"] = "standard", ["sourceQuests"] = { 76390 } },
