[77251] = { ["id"] = 77251, ["name"] = "Shaping the Dreamsurge", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2022, ["storyline"] = { 77251 }, ["description"] = "The Emerald Dream is thrumming with energies not felt in ages. Some of that energy is even slipping through the barrier between the dream and Azeroth, coalescing into a glimmering, pollen-like powder. Gather as much as you can. This is not like any event we have seen before!", ["objectivesText"] = "Gather Dreamsurge Coalescence from around the Dreamsurge. Progress: The winds sparkle with motes of dreaming essence, spreading it over the land.", ["rewardItems"] = { 204076, 207026, 208153, 210254, 215364, 224297 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 208649, ["x"] = 0.584, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 208649, ["x"] = 0.584, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[77254] = { ["id"] = 77254, ["name"] = "Aiding the Accord: Time Rift", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13644, ["mapID"] = 2112, ["storyline"] = { 70750, 71232, 72068, 72373, 72374, 72375, 72585, 75259, 75859, 75860, 75861, 77254, 77976, 78446, 78447, 78861, 80385, 80386, 80388, 80389 }, ["description"] = "The Bronze Dragonflight have long labored in secret, dealing with temporal anomalies nearly as quickly as they're able to manifest. It would appear, however, that the anomalies have gotten a bit too big as of late. That's where you come in. You can find Soridormi leading an effort against a particularly nasty set of Time Rifts just to the east of Valdrakken . Aid her in whatever way she deems necessary.", ["objectivesText"] = "Travel to the Tyrhold Reservoir and assist Soridormi in dispelling a Time Rift. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles. Progress: Do you bring news of your success?", ["rewardXP"] = 14275, ["rewardItems"] = { 200073, 201921, 201922, 201923, 201924, 204076, 207002, 207030, 207582, 207583, 207584, 208090, 208945, 208951, 208952 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 }, { ["mapID"] = 2022, ["npcID"] = 199336, ["x"] = 0.765, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.5605 }, ["mapCandidates"] = { ["npc"] = { 2022, 2112 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 71232, 72366 }, ["questLines"] = { { ["id"] = 1367, ["name"] = "Dragon Isles Emissary", ["orderIndex"] = 11, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 201, ["title"] = "Dragonflight", ["questLineID"] = 1367, ["questLineOrder"] = 0 } }, ["db2L