[77263] = { ["id"] = 77263, ["name"] = "The Torch of Pyrreth", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2025, ["storyline"] = { 77263 }, ["description"] = "Let's begin with a simple test. I have hidden an artifact somewhere in the Ruby Enclave. If you have the torch out, it should illuminate when you get close to the target. And if my theory is correct, it should interact with a lock I put on the artifact. Bring me back what's inside. Got it?", ["objectivesText"] = "Use the Torch of Opening to unlock Kathos' artifact, hidden somewhere in The Ruby Enclave. Progress: Return when you have retrieved what I ask.", ["rewardItems"] = { 208092, 208107 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 206864, ["x"] = 0.604, ["y"] = 0.59 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 206864, ["x"] = 0.604, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 77282 } },
