[77266] = { ["id"] = 77266, ["name"] = "Auchindoun Coaster - Reverse", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 77266 }, ["description"] = "Fly through the checkpoint rings marking the course.", ["objectivesText"] = "Glide through the rings.", ["rewardItems"] = { 188134, 191140, 211877, 211881, 211882, 211883, 211884, 211885, 211886, 211887, 211888, 211926, 212518 }, ["starts"] = { { ["x"] = 0.422, ["y"] = 0.679, ["mapID"] = 108, ["npcID"] = 208596 } }, ["ends"] = { { ["x"] = 0.422, ["y"] = 0.679, ["mapID"] = 108, ["npcID"] = 208596 } }, ["coords"] = { ["mapID"] = 108, ["x"] = 0.422, ["y"] = 0.679 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 208596, ["questTurnInID"] = 208596, ["questType"] = "standard" },
[77267] = { ["id"] = 77267, ["name"] = "Excavation 101", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "So, you want to learn how to excavate artifacts? You came to the right orc! Turns out being able to shape the earth is useful when you're trying to get stuff out of the ground. And given how much the elements affect our work, it helps having an elemental to lend a hand. But you don't have to be a shaman to master excavation. I've got the elements covered. I'll just walk you through the detail work.", ["objectivesText"] = "Meet with Roska outside to learn about excavation. Progress: What do you think? Having fun yet?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 210956 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 208614, ["x"] = 0.615, ["y"] = 0.306 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 208614, ["x"] = 0.615, ["y"] = 0.306 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 77325 }, ["questLines"] = { { ["id"] = 5466, ["name"] = "Azerothian Archives - Tutorial", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[77268] = { ["id"] = 77268, ["name"] = "Hands-On Experience", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "Great job on that small find! Now, are you ready for something big? More often than not, shaking up the small stuff will shake up something even BIGGER just below the surface. Another little rumble, and we'll have a major find on our hands, I can feel it. A major find works almost the same as the smaller ones with a couple extra steps. Why don't you tackle this one too? It'll be good practice for ya. Don't worry! I can guide you through it.", ["objectivesText"] = "Unearth the major find, then speak to Roska to begin excavating it. Progress: Rare to find big stuff like that up here! Zenata might be up to her tricks again.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 210956 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 208614, ["x"] = 0.615, ["y"] = 0.306 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 208614, ["x"] = 0.615, ["y"] = 0.306 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 78762 }, ["questLines"] = { { ["id"] = 5466, ["name"] = "Azerothian Archives - Tutorial", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[77276] = { ["id"] = 77276, ["name"] = "An Inside Job?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 77276 }, ["description"] = "Fangli Hoot says they have a theory on who might be stealing the artifacts. Seek her out again near the Barber Shop.", ["objectivesText"] = "Speak with Fangli Hoot near the Valdrakken Barber Shop.", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 208092, 208128, 208129 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 207696, ["x"] = 0.476, ["y"] = 0.470667 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 207697, ["x"] = 0.2656, ["y"] = 0.5432 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.470667 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 76504 } },
[77277] = { ["id"] = 77277, ["name"] = "Preservationist Cleared", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 77277 }, ["description"] = "Ya better return the item before the Preservationist notices it's missing. Then let Fangli know that her theory didn't pan out.", ["objectivesText"] = "Return the Burial Banner to the Preservationist's Locker in the Roasted Ram. Progress: What did you discover?", ["rewardItems"] = { 208129, 208130 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 208620, ["x"] = 0.624667, ["y"] = 0.733333 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 207697, ["x"] = 0.2656, ["y"] = 0.5432 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.624667, ["y"] = 0.733333 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 77397 } },
