[77283] = { ["id"] = 77283, ["name"] = "A Multi-Front Battle", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76317, 76318, 76319, 76320, 76321, 76322, 76323, 76324, 76325, 76326, 77283, 77818 }, ["series"] = { 76323, 76324, 76325, 76326, 77818 }, ["description"] = "The kaldorei have set up a temporary base beneath the boughs of Amirdrassil. With hope and hard work, this encampment will become permanent when the tree enters our world. Feel free to acquaint yourself with the provisions available. Then return to me.", ["objectivesText"] = "Meet Saelienne in the Central Encampment. Progress: Have you found what you needed here in camp?", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 208067, 210050, 257352 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206896, ["x"] = 0.508, ["y"] = 0.628 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206896, ["x"] = 0.508, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 76326 }, ["questLines"] = { { ["id"] = 5456, ["name"] = "Enter the Dream", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 17, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5456, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
