[77304] = { ["id"] = 77304, ["name"] = "An Idol in Hand", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 77304 }, ["description"] = "<The idol appears to be a figure of Ohn'ahra carved from serevite, an ore used in many titan temples. Preservationist Kathos would surely be interested in this.>", ["objectivesText"] = "Return the Idol of Ohn'ahra to Preservationist Kathos in Valdrakken . Progress: What have you found?", ["rewardItems"] = { 207730, 208145, 208149 }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 206864, ["x"] = 0.604, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[77305] = { ["id"] = 77305, ["name"] = "Out of the Sands", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 77305 }, ["description"] = "<The Time-Lost fragments are now joined to form a stone tablet, but many of its inscriptions are worn and incomplete. Preservationist Kathos will want to see this.>", ["objectivesText"] = "Return the Incomplete Tablet to Preservationist Kathos . Progress: XENO! How was your luck in the Shifting Sands? Did you find the tablet fragments?", ["rewardGold"] = 619600, ["rewardXP"] = 2615, ["rewardItems"] = { 20646, 20647, 56887, 56888, 56889, 56890, 65930, 65955, 65979, 157014, 206948, 208146, 208191, 237934, 237935 }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 206864, ["x"] = 0.604, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["startItems"] = { 208146 } },
[77310] = { ["id"] = 77310, ["name"] = "Memory of the Dreamer", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77310 }, ["description"] = "In the Dream, memories can live on in unusual ways. Memories are not always linear. And memories that are not of your own can become yours. Perhaps you were drawn to this place by the presence of the once-Dreamer. Or perhaps you were drawn to this place because of my great friend. Come, won't you see? Rest here and let the magic of the Dream wash over you.", ["objectivesText"] = "Rest at the Eye of Ysera.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 210954, 211370 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 210022, ["x"] = 0.586, ["y"] = 0.238 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208713, ["x"] = 0.586, ["y"] = 0.24 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.238 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 78904 } },
[77311] = { ["id"] = 77311, ["name"] = "Healing Helper", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77311 }, ["description"] = "Gracus sent word for Ysera to come and see him. We arrived and found him in a dire condition. Our efforts to heal him so far have proved fruitless. But now that you are here, you can assist. Gracus is of the Dream. Perhaps infusing his roots with something grown here will be the final thing we need to restore him.", ["objectivesText"] = "Use the Root Restoration Fruit to help heal Gracus. Progress: Gracus' condition is dire. We must do what we can to try to help.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 208884 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208713, ["x"] = 0.586, ["y"] = 0.24 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208713, ["x"] = 0.586, ["y"] = 0.24 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.24 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 77310 } },
[77312] = { ["id"] = 77312, ["name"] = "Nature Persists", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77312 }, ["description"] = "Admittedly, I do not know what to do next. If he is to rest here... flowers would be lovely. The podlings in this area have been hiding among the flowers. Retrieve seeds from them, Champion, and I will make them bloom. I think Gracus will like the flowers.", ["objectivesText"] = "Collect 6 Sprouted Seedlings from Sneaky Podlings. Progress: There must be something more that we... No. Ysera seems certain.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 208676 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208713, ["x"] = 0.586, ["y"] = 0.24 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208713, ["x"] = 0.586, ["y"] = 0.24 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.24 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 77311 } },
[77313] = { ["id"] = 77313, ["name"] = "A Solemn Summons", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77313 }, ["description"] = "It is as I feared. It is Gracus' time. Healing him would never have worked. The world beyond already calls to him. Although he has such peace, those that care for him will still grieve. He will still be dearly missed. Not everyone is granted a chance to say goodbye. We must ensure that in this case, they are.", ["objectivesText"] = "Inform Gracus' loved ones. Progress: I am grateful we can give them this opportunity to say goodbye.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208714, ["x"] = 0.586, ["y"] = 0.238 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208714, ["x"] = 0.586, ["y"] = 0.238 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.238 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 77311 } },
[77314] = { ["id"] = 77314, ["name"] = "Requiem in a Dream", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77314 }, ["description"] = "As one life ends so too will a life begin. We must remind those that love Gracus of this, <name>. Plant seeds around Gracus. My sister can handle the rest. This place will not only represent an end but also a beginning of new life.", ["objectivesText"] = "Plant 6 flowers around Gracus. Progress: These flowers will bloom around Gracus and serve as a reminder of all he helped to grow during his life.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 210954 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208714, ["x"] = 0.586, ["y"] = 0.238 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208714, ["x"] = 0.586, ["y"] = 0.238 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.238 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 77312, 77313 } },
[77315] = { ["id"] = 77315, ["name"] = "Ancient Memories", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77315 }, ["description"] = "Those dark memories cannot be allowed to fester in the Dream. Unleashing them was necessary. Gracus needed to let go. But if they linger, they may become malevolent. Defeat the memory that haunts him most so that Gracus can slumber at last.", ["objectivesText"] = "Kill the Lingering Torment .", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 208067, 211370 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208714, ["x"] = 0.586, ["y"] = 0.238 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208714, ["x"] = 0.586, ["y"] = 0.238 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.238 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 77314 } },
[77316] = { ["id"] = 77316, ["name"] = "Trouble at the Tree", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77316 }, ["description"] = "<name>! Merithra needs your help. Some nasty trickster spriggans followed us into the Dream and now they're causing all sorts of havoc! Like the most important thing of all, stealing top secret super important supplies. It's urgent you stop them and get the supplies back.", ["objectivesText"] = "Retrieve 6 Very Important Tree Supplies from Spriggans. Progress: If we don't get those supplies back from those pesky spriggans, we'll be so behind schedule!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 208977 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208669, ["x"] = 0.498, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208669, ["x"] = 0.498, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 78904 } },
[77317] = { ["id"] = 77317, ["name"] = "Hatted Hibernation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77317 }, ["description"] = "I'll let you in on a secret, these crates? They're prank supplies! People are so serious around here. What's better than a little prank to lift everyone's spirits? You could put some of these fun hats on some of the sleeping druids because what's more fun than a surprise hat? Be careful though, their connection to the dream could make anything happen!", ["objectivesText"] = "Put 6 silly hats on Dreaming Druids . Progress: Napping in the Dream... I wonder what they're dreaming about!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 208985, 210755 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208669, ["x"] = 0.498, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208669, ["x"] = 0.498, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 77316 } },
[77318] = { ["id"] = 77318, ["name"] = "Merithra Says", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77318 }, ["description"] = "Some druids are volunteering to help tend to the tree and set up camp. But they're so sad! < Lady Moonberry grows a mischievous grin.> We have to give them a reason to smile. You can give them some orders that remind them to have fun. But there's no way they'll take orders from you. That's why I got this costume for you. With this and a little spell they'll for sure listen to you!", ["objectivesText"] = "Give instructions to 5 druids while disguised as Merithra. Progress: You're clearly a master prankster but you'll have to be a master actor as well. A costume and a spell can only do so much.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 208067, 210996, 210997 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208669, ["x"] = 0.498, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208669, ["x"] = 0.498, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 77317 } },
[77322] = { ["id"] = 77322, ["name"] = "Shattrath City Sashay", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 77322 }, ["description"] = "Fly through the checkpoint rings marking the course.", ["objectivesText"] = "Glide through the rings.", ["rewardItems"] = { 188134, 191140, 211877, 211881, 211882, 211883, 211884, 211885, 211886, 211887, 211888, 211926, 212518 }, ["starts"] = { { ["x"] = 0.716, ["y"] = 0.701, ["mapID"] = 111, ["npcID"] = 208673 } }, ["ends"] = { { ["x"] = 0.716, ["y"] = 0.701, ["mapID"] = 111, ["npcID"] = 208673 } }, ["coords"] = { ["mapID"] = 111, ["x"] = 0.716, ["y"] = 0.701 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 208673, ["questTurnInID"] = 208673, ["questType"] = "standard" },
