[77324] = { ["id"] = 77324, ["name"] = "Shattrath City Sashay - Reverse", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 77324 }, ["description"] = "Fly through the checkpoint rings marking the course.", ["objectivesText"] = "Glide through the rings.", ["rewardItems"] = { 188134, 191140, 211877, 211881, 211882, 211883, 211884, 211885, 211886, 211887, 211888, 211926, 212518 }, ["starts"] = { { ["x"] = 0.716, ["y"] = 0.701, ["mapID"] = 111, ["npcID"] = 208673 } }, ["ends"] = { { ["x"] = 0.716, ["y"] = 0.701, ["mapID"] = 111, ["npcID"] = 208673 } }, ["coords"] = { ["mapID"] = 111, ["x"] = 0.716, ["y"] = 0.701 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 208673, ["questTurnInID"] = 208673, ["questType"] = "standard" },
[77325] = { ["id"] = 77325, ["name"] = "To the Archives!", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "Are you a scholar, historian, or a high-minded intellectual? Do you enjoy heavy, mindless labor in exchange for gold? Then take hold of your future, and join the newly budding ranks of the Azerothian Archives!* <Your eyes move to the fine print near the parchment's edge.> *Temporary offices are located at the Algeth'ar Academy in northern Thaldraszus.", ["objectivesText"] = "Speak with Lead Archivist Eadweard Dalyngrigge at Algeth'ar Academy.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 204076, 224784, 229354, 239118, 244865, 248651 }, ["starts"] = { { ["x"] = 0.466, ["y"] = 0.475, ["mapID"] = 2112, ["objectID"] = 405593 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 206107, ["x"] = 0.615, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5466, ["name"] = "Azerothian Archives - Tutorial", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[77327] = { ["id"] = 77327, ["name"] = "Nirobin and the Office", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13644, ["mapID"] = 2023, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "Perhaps there is more to investigate, but I need time to go over our findings here first. Our colleague, Nirobin , the one arcane projecting himself into the headquarters, should be ready for your assistance by now. He's got his own office at the Academy in Thaldraszus that he tends to squirrel himself away in. I'm positive he'll be there... Mostly because he never leaves it.", ["objectivesText"] = "Speak with Nirobin at his office in Thaldraszus.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 204643, ["x"] = 0.664, ["y"] = 0.46 }, { ["mapID"] = 2022, ["npcID"] = 204835, ["x"] = 0.564, ["y"] = 0.44 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 205967, ["x"] = 0.585, ["y"] = 0.368 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.46 }, ["mapCandidates"] = { ["npc"] = { 2022, 2023, 2025 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 75603, 75868 }, ["questLines"] = { { ["id"] = 5470, ["name"] = "Azerothian Archives - Research Site & Wrap Up", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 15, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[77328] = { ["id"] = 77328, ["name"] = "Back to Headquarters!", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "Eadweard called for your return to the main office after I'd finished with you... er, this experiment, I mean. I'm sure it has to do with pomp, circumstance, reward, and what have you. If any of that entices you, then best hurry before his bag of goodies runs dry to all the other recent recruits.", ["objectivesText"] = "Meet with Eadweard Dalyngrigge at Algeth'ar Academy in Thaldraszus.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 205967, ["x"] = 0.585, ["y"] = 0.368 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 206107, ["x"] = 0.615, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.585, ["y"] = 0.368 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 76242 }, ["questLines"] = { { ["id"] = 5470, ["name"] = "Azerothian Archives - Research Site & Wrap Up", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 19, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[77329] = { ["id"] = 77329, ["name"] = "Auspicious Gathering", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 76276, 76280, 76281, 76282, 76283, 77200, 77201, 77329, 77780, 77781 }, ["description"] = "As you know, Amirdrassil is no ordinary tree. Tyrande Whisperwind and the rest of the kaldorei have been preparing to properly welcome it with a ceremony of their own, and establish a new moonwell. I am certain that Tyrande would want you there for the dedication. Let us join them at the Central Encampment.", ["objectivesText"] = "Speak with Tyrande Whisperwind in the Central Encampment.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 206397, ["x"] = 0.148, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 2239, ["npcID"] = 208537, ["x"] = 0.508, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.148, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 2023, 2239 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 76276 }, ["questLines"] = { { ["id"] = 5473, ["name"] = "New Beginnings", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 60, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5473, ["questLineOrder"] = 6 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2239 },
[77331] = { ["id"] = 77331, ["name"] = "Graduation Day", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "You've turned out to be quite a fine member of our high-skilled crew of rag tags and diggers of dirt. Between the sites you've broken ground on with Roska, Zenata, and Nirobin, as well as the larger one in Traitor's Rest, the varied histories collected by these Dragon Isles have never been more ripe for the harvest. There will always be work and companionship here when you desire it. We hope you'll join us on other continents as well. ...When we receive appropriate funding, that is.", ["objectivesText"] = "Receive congratulations from your Azerothian Archivist peers. Progress: Worry not. I've already written to our benefactors of your efforts.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 206107, ["x"] = 0.615, ["y"] = 0.312 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 206107, ["x"] = 0.615, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 79231 }, ["questLines"] = { { ["id"] = 5470, ["name"] = "Azerothian Archives - Research Site & Wrap Up", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 43, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[77339] = { ["id"] = 77339, ["name"] = "Data Recovery", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 77339, 77340, 77341, 77342, 77343, 77344, 77377 }, ["description"] = "After a lot of rigorous training, the time has come! Travard believes the Tyr's Guard is ready to recover the disc of Tyr from the Nighthold. Meet us at Tyr's Rest, the new Tyr's Guard headquarters. It's just south of Tyrhold. We will finally make Tyr whole again!", ["objectivesText"] = "Meet Travard at the Tyr's Guard headquarters.", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["rewardItems"] = { 210255, 210321 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 208703, ["x"] = 0.608, ["y"] = 0.636 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 208701, ["x"] = 0.605, ["y"] = 0.636 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.636 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 75638 }, ["questLines"] = { { ["id"] = 5476, ["name"] = "Tyr's Return", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 5476, ["questLineOrder"] = 3 }, { ["id"] = 241, ["title"] = "Catching Up!", ["questLineID"] = 5476, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[77340] = { ["id"] = 77340, ["name"] = "Infiltrating the Nighthold", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 77339, 77340, 77341, 77342, 77343, 77344, 77377 }, ["description"] = "The information from our beacons suggests that Elisande has locked the disc away in Astromancer's Rise. It is a place of learning, and the inside will have minimal protection. I have opened a portal where you and the Tyr's Guard will have the least resistance... except for Elisande and whatever guards are under her employ. All of you are on your own once you get there, so try not to muck it up.", ["objectivesText"] = "Retrieve the Disc of Tyr from Elisande in the Nighthold. Progress: I wonder what Tyr is like? I bet he's super nice!", ["rewardGold"] = 842700, ["rewardXP"] = 2125, ["rewardItems"] = { 210255, 210321 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 208832, ["x"] = 0.604, ["y"] = 0.59 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 208835, ["x"] = 0.604, ["y"] = 0.588 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 77377 }, ["questLines"] = { { ["id"] = 5476, ["name"] = "Tyr's Return", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 5476, ["questLineOrder"] = 3 }, { ["id"] = 241, ["title"] = "Catching Up!", ["questLineID"] = 5476, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[77341] = { ["id"] = 77341, ["name"] = "Logotyrapy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 77339, 77340, 77341, 77342, 77343, 77344, 77377 }, ["description"] = "Dear $p, It seems wrong to say this of someone as mighty as Tyr, but I am worried about him. When he arrived at Tyr's Rest, he spent many days talking with us. We all asked him many questions, learning about the titans, ancient history, and his philosophy. But recently, Tyr has been speaking less, and the answers he does give are shorter and some have an edge to them. I'm not sure what's wrong, but something is different. Will you come speak with him? For Tyr, Valunei", ["objectivesText"] = "Speak with Tyr at Tyr's Rest. Progress: Tyr seems restless. Perhaps you could talk to him, <name>?", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 208199, 208826, 210255, 210321 }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 208839, ["x"] = 0.608, ["y"] = 0.638 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.638 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 77344 }, ["questLines"] = { { ["id"] = 5476, ["name"] = "Tyr's Return", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 5476, ["questLineOrder"] = 3 }, { ["id"] = 241, ["title"] = "Catching Up!", ["questLineID"] = 5476, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["startItems"] = { 208826 } },
[77342] = { ["id"] = 77342, ["name"] = "Disc Delivery", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 77339, 77340, 77341, 77342, 77343, 77344, 77377 }, ["description"] = "You have recovered the disc? Good. At last, we can awake Tyr. The disc must be placed in the console so it can attune to the Silver Scale and pass on to Tyr. I believe you should do the honors, $p.", ["objectivesText"] = "Insert the Disc of Tyr into the titan console. Progress: Did you place the disc in the titan console?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 208798 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 208834, ["x"] = 0.604, ["y"] = 0.588 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 208834, ["x"] = 0.604, ["y"] = 0.588 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.588 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 77340 }, ["questLines"] = { { ["id"] = 5476, ["name"] = "Tyr's Return", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 5476, ["questLineOrder"] = 3 }, { ["id"] = 241, ["title"] = "Catching Up!", ["questLineID"] = 5476, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[77343] = { ["id"] = 77343, ["name"] = "A Tyrful Reunion", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 77339, 77340, 77341, 77342, 77343, 77344, 77377 }, ["description"] = "This is incredible, seeing our friend back after so many thousands of years. So much has happened since we last spoke. The world has changed. Our loss of Tyr was before even the Sundering. But there will be time to discuss all those things later. For now, it's simply good to be with our friend. Stay with us, will you, $p, while we reconnect?", ["objectivesText"] = "Listen to the Aspects' conversation with Tyr. Progress: One moment, <name>--I want to hear what Tyr and the aspects are saying!", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 208833, ["x"] = 0.604, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 208800, ["x"] = 0.604, ["y"] = 0.588 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 77342 }, ["questLines"] = { { ["id"] = 5476, ["name"] = "Tyr's Return", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 5476, ["questLineOrder"] = 3 }, { ["id"] = 241, ["title"] = "Catching Up!", ["questLineID"] = 5476, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[77344] = { ["id"] = 77344, ["name"] = "Time to Process", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 77339, 77340, 77341, 77342, 77343, 77344, 77377 }, ["description"] = "Tyr is back after thousands of years. I don't even know how many thousands. His world has changed more than we can even imagine. He's going to have many questions and need answers. Meanwhile, there's nothing any of the Tyr's Guard would rather do than talk with Tyr. Tyr's Rest seems like the perfect place to give him time, answer questions, and process those answers. Would you ask him to join us there?", ["objectivesText"] = "Invite Tyr to join the Tyr's Guard at Tyr's Rest. Progress: We certainly live in interesting times, <name>...", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 208550, 208826 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 208800, ["x"] = 0.604, ["y"] = 0.588 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 208839, ["x"] = 0.608, ["y"] = 0.638 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.588 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 77343 }, ["questLines"] = { { ["id"] = 5476, ["name"] = "Tyr's Return", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 192, ["title"] = "The Silver Purpose", ["questLineID"] = 5476, ["questLineOrder"] = 3 }, { ["id"] = 241, ["title"] = "Catching Up!", ["questLineID"] = 5476, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[77345] = { ["id"] = 77345, ["name"] = "The Need For Higher Velocities", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65118, 65120, 65133, 66114, 66115, 66116, 66118, 66121, 66122, 66123, 66124, 66931, 68795, 68796, 68798, 68799, 70061, 77345 }, ["description"] = "Sometimes you'll need to travel longer distances. If you don't need to travel up and over any obstacles using Surge Forward is the easiest way to maintain a good forward speed to prevent yourself from plummeting out of the sky. Follow the rings again to your destination and use Surge Forward when prompted to maintain your speed. If you find yourself stuck, use the Bronze Timepiece and Celormu will reset you.", ["objectivesText"] = "Fly through the rings and land in the target area. Progress: Well done, <name>.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 208182 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193287, ["x"] = 0.576, ["y"] = 0.668 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 183141, ["x"] = 0.575, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 65133 }, ["questLines"] = { { ["id"] = 1300, ["name"] = "In Defense of Life", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5568, ["name"] = "The Waking Shores", ["orderIndex"] = 18, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 169, ["title"] = "The Waking Shores", ["questLineID"] = 1300, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5568, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
