[77697] = { ["id"] = 77697, ["name"] = "The Right Food...", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77677, 77697, 77711, 77762, 78398 }, ["description"] = "<The plant is now a promising sapling and has thrived with the attention you've given. Peering closely at the plant's leaves, you see its exterior brimming with dew. Perhaps the right food will help the plant even further.>", ["objectivesText"] = "Bring some fertilizer for the plant. Progress: <The plant is hydrated, but remains severely underfed.>", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 4537, 208644, 208646, 208647, 208757, 209416, 210774 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 209458, ["x"] = 0.486, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 209458, ["x"] = 0.486, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.486, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 78398 }, ["questLines"] = { { ["id"] = 5477, ["name"] = "A Mix of Hope, Care, and Patience", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
