[77739] = { ["id"] = 77739, ["name"] = "Smother the Flames", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77739 }, ["description"] = "Lilian and I have been shadowing Raelas Firewind and have uncovered his plan. He has manipulated the Sisters of the Flame to bind spirits from the Dream to magical spirit stones. With Raelas's blessing, these stones became powerful tools of corruption, allowing these fallen dryads to twist the Dream and its denizens. We will start our purge with the dryads--they have the stones. Then we will end Raelas. The hunt begins, $p.", ["objectivesText"] = "Help Shandris and Lilian retrieve the spirit stones from the Sisters of Flame dryads. Progress: Bring me all four spirit stones. We must keep them close so they do not fall into the wrong hands.", ["rewardGold"] = 232300, ["rewardXP"] = 1060, ["rewardItems"] = { 208770, 208937, 209428, 209429, 209430 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 209083, ["x"] = 0.496, ["y"] = 0.462 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 209083, ["x"] = 0.496, ["y"] = 0.462 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.496, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questTurnInID"] = 209083, ["questType"] = "standard", ["sourceQuests"] = { 77662 } },
