[77760] = { ["id"] = 77760, ["name"] = "Curious Find: Dragonhorn Flute", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13646, ["mapID"] = 2025, ["storyline"] = { 77760 }, ["description"] = "<This flute is inexpertly hewn out of the horn of a dragon. The cracking around the base suggests the dragon was long gone by the time the flute was made. The mouthpiece is strange. It's almost like it isn't designed to be played with the mouth at all but the nose. Could this flute have been crafted by the niffen? Eadweard would know how to preserve this find and figure out whom it might belong to.>", ["objectivesText"] = "Bring the Dragonhorn Flute to Eadweard Dalyngrigge at the Algeth'ar Academy in Thaldraszus.", ["rewardGold"] = 140450, ["rewardXP"] = 4760, ["rewardItems"] = { 208733 }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 206107, ["x"] = 0.615, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["startItems"] = { 208733 } },
