[77779] = { ["id"] = 77779, ["name"] = "The Tale of Sir Thomas", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Hallow's End", ["expansion"] = 10, ["zoneID"] = 6109, ["mapID"] = 18, ["storyline"] = { 77779 }, ["description"] = "Suzannah... I never thought I would find her. Now we can return to our children, and rest at last. All thanks to you, <name>. Do you still have my tome? My story has reached its end, and I would see it penned by my own hand. <Thomas glides his finger across a blank page, spectral ink marking his words.> Please return this to the Orphan Matron. And... please apologize on my behalf for frightening her, would you?", ["objectivesText"] = "Return to the Orphan Matron. Provided item:", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 208769 }, ["starts"] = { { ["x"] = 0.43, ["y"] = 0.53, ["mapID"] = 435, ["npcID"] = 209609 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 53865, ["x"] = 0.624, ["y"] = 0.665 }, { ["mapID"] = 37, ["npcID"] = 53869, ["x"] = 0.32, ["y"] = 0.502 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.624, ["y"] = 0.665 }, ["mapCandidates"] = { ["npc"] = { 18, 37 }, ["zone"] = { 6109 } }, ["questGiverID"] = 209609, ["questType"] = "standard", ["sourceQuests"] = { 76074 } },
[77780] = { ["id"] = 77780, ["name"] = "A Blossom Witnessed", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76276, 76280, 76281, 76282, 76283, 77200, 77201, 77329, 77780, 77781 }, ["description"] = "Amirdrassil has bloomed beyond the confines of the Dream. Let us venture to the Dragon Isles and see where this new World Tree has taken root.", ["objectivesText"] = "Speak with Merithra at the Ancient Bough in the Ohn'ahran Plains. Progress: It is magnificent!", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 208067 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 211634, ["x"] = 0.276, ["y"] = 0.314 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 206397, ["x"] = 0.148, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.276, ["y"] = 0.314 }, ["mapCandidates"] = { ["npc"] = { 2023, 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 76401 }, ["questLines"] = { { ["id"] = 5473, ["name"] = "New Beginnings", ["orderIndex"] = 0, ["flags"] = 1 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 58, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5473, ["questLineOrder"] = 6 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
[77781] = { ["id"] = 77781, ["name"] = "A Different Enthusiasm", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15105, ["mapID"] = 2239, ["storyline"] = { 76276, 76280, 76281, 76282, 76283, 77200, 77201, 77329, 77780, 77781 }, ["description"] = "I noticed the festivities have drawn the attention of a few spriggans from Ardenweald. They are curious creatures with... interesting tastes. Their pranks have been more than disruptive. Please root them out so the celebration may continue in peace.", ["objectivesText"] = "Reveal 6 Spriggan Pranksters in Bel'ameth. Progress: Have you discovered all of them? I have already heard a middling rumor that I suspect they spun up.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2239, ["npcID"] = 206849, ["x"] = 0.542, ["y"] = 0.578 } }, ["ends"] = { { ["mapID"] = 2239, ["npcID"] = 206849, ["x"] = 0.542, ["y"] = 0.578 } }, ["coords"] = { ["mapID"] = 2239, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.578 }, ["mapCandidates"] = { ["npc"] = { 2239 }, ["zone"] = { 15105 } }, ["questType"] = "standard", ["sourceQuests"] = { 76280 }, ["questLines"] = { { ["id"] = 5473, ["name"] = "New Beginnings", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 65, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5473, ["questLineOrder"] = 6 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2239 },
