[77789] = { ["id"] = 77789, ["name"] = "Severing Ties", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 77408, 77409, 77410, 77411, 77412, 77789, 77795 }, ["description"] = "Nalridun has recruited a small army of cultists. They believe he speaks for Sargeras through the relic, clinging to every word he says. The same way we clung to our leaders when Sargeras came to Argus. It was a comfort. A hope. And, in the end, empty deception. But his followers do not believe they are deceived. They have constructed their own conduits in the area to try to tap into the relic's power. To hear the voice themselves. They will try to stop us. We must cut a path through them.", ["objectivesText"] = "Slay 10 man'ari cultists and overload 5 Sargerei Conduits. Progress: May their delusions die with them. We cannot risk any power they might be adding to Nalridun's rituals.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 208858, ["x"] = 0.635, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 208858, ["x"] = 0.635, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.635, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questTurnInID"] = 208858, ["questType"] = "standard", ["sourceQuests"] = { 77410 }, ["questLines"] = { { ["id"] = 5482, ["name"] = "Seeing Red", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830 },
[77791] = { ["id"] = 77791, ["name"] = "Handling It: Symbiotic Glowspore Grip", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["requiredClasses"] = { 1, 2, 6 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 77791, 77886, 78159, 78160, 78655 }, ["description"] = "I know a crafter who could help temper Fyr'alath. Erden of Clan Shikaar is extremely resourceful. He's performed many experiments with various reagents throughout the Dragon Isles. Hunters are only as good as their weapons. Erden is known for crafting exquisite weaponry with exotic materials. His expertise in various flora and fauna should prove quite informative.", ["objectivesText"] = "Seek out Erden in the Ohn'ahran Plains.", ["rewardGold"] = 140450, ["rewardXP"] = 4760, ["rewardItems"] = { 208781 }, ["starts"] = { { ["x"] = 0.616, ["y"] = 0.312, ["mapID"] = 2025, ["npcID"] = 209601 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 194842, ["x"] = 0.824, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.824, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questGiverID"] = 209601, ["questType"] = "standard", ["sourceQuests"] = { 77191 }, ["questLines"] = { { ["id"] = 5483, ["name"] = "Symbiotic Glowspore Grip", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["startItems"] = { 208781 } },
