[77802] = { ["id"] = 77802, ["name"] = "What Do I Call You?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77802 }, ["description"] = "Guardian! Or... teacher! Parent? I want you to tell me what to call you. The other dryads will ask me who my druid is now that I am working in the garden on my own. I want to tell them that I do not have a druid. I have you! Tell me what title you prefer.", ["objectivesText"] = "Speak with Dionaessa to choose a title in the Root-Bound Sanctuary. Progress: I have heard so many titles from the druid Creekward. I am certain we can come up with something far more interesting.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 210958 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 209788, ["x"] = 0.538, ["y"] = 0.745 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 209788, ["x"] = 0.538, ["y"] = 0.745 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.745 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 76572 } },
[77813] = { ["id"] = 77813, ["name"] = "Lightning Strikes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 77813, 77815 }, ["description"] = "<Flaps does a spin and deposits a drool-soaked note into your hand.> Ah, <name>. I am told you have acquired a fine new mount. A gryphon that soars upon the very storm itself! I would very much like to see how this wondrous creature flies. I will await you at Skytop Observatory.", ["objectivesText"] = "Meet Lord Andestrasz at the Skytop Observatory.", ["rewardGold"] = 70225, ["rewardXP"] = 355, ["rewardItems"] = { 39347, 39400, 39437, 39457, 209417 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 197478, ["x"] = 0.455, ["y"] = 0.5545 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193359, ["x"] = 0.752, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.5545 }, ["mapCandidates"] = { ["npc"] = { 2022, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["nextQuests"] = { 77815 }, ["questLines"] = { { ["id"] = 5480, ["name"] = "11.0 Preorder", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022 },
[77815] = { ["id"] = 77815, ["name"] = "The Storm Race Tour", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13644, ["mapID"] = 2022, ["description"] = "This storm gryphon is intriguing! Whatever land gave rise to such a creature merits further exploration. But since you are here, let us test its training--and your riding skills. My colleagues in the bronze flight have laid out new courses to put the mount through its paces. When a timekeeper sees you upon your gryphon, they will offer you the chance to fly these \"storm races\". Fortune favors the bold, $p. Good luck!", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 209417 }, ["starts"] = { { ["npcID"] = 193359, ["x"] = 0.752, ["y"] = 0.55, ["mapID"] = 2022 } }, ["ends"] = { { ["npcID"] = 193359, ["x"] = 0.752, ["y"] = 0.55, ["mapID"] = 2022 } }, ["coords"] = { ["x"] = 0.752, ["y"] = 0.55, ["source"] = "quest_giver", ["mapID"] = 2022 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard", ["sourceQuests"] = { 77813 }, ["questLines"] = { { ["id"] = 5480, ["name"] = "11.0 Preorder", ["orderIndex"] = 1, ["flags"] = 0 } } },
[77818] = { ["id"] = 77818, ["name"] = "The Cruel", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76317, 76318, 76319, 76320, 76321, 76322, 76323, 76324, 76325, 76326, 77283, 77818 }, ["series"] = { 76323, 76324, 76325, 76326, 77283 }, ["description"] = "Primalists, djaradin, and Druids of the Flame all work together against us. But I can sense that this is not the last of them. Something powerful is trying to come through this portal. Let us try to seal them out for as long as we can.", ["objectivesText"] = "Help Merithra close the flaming portal.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 26007, 26021, 26033, 28040, 28041, 28042, 37209, 37419, 37523, 37541, 131272 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206688, ["x"] = 0.628, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206806, ["x"] = 0.589333, ["y"] = 0.615333 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 76321, 76322 }, ["questLines"] = { { ["id"] = 5456, ["name"] = "Enter the Dream", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5456, ["questLineOrder"] = 1 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
[77822] = { ["id"] = 77822, ["name"] = "A Titanic Mold", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 77822 }, ["description"] = "<The Titan Key Mold was at the location referenced in the story. Weaponsmith Koref will be so excited to see the mold!>", ["objectivesText"] = "Return the Titan Key Mold to Weaponsmith Koref in Valdrakken . Progress: By the forge, did you actually do it? Did you find the Titan Key mold ?", ["rewardItems"] = { 208092, 208486, 208827 }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 195769, ["x"] = 0.365, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[77829] = { ["id"] = 77829, ["name"] = "Reforging a Legend", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 77829 }, ["description"] = "There you are! Weaponsmith Koref was just looking for you. Left me with a note asking you to meet him in the Obsidian Conclave. Sounds like you're helping him reforge an ancient titan key? Let me know how it goes! That's headline news if I ever heard it.", ["objectivesText"] = "Seek out Weaponsmith Koref in the Obsidian Enclave.", ["rewardItems"] = { 207730, 208829, 208831, 208835, 208836 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 207696, ["x"] = 0.476, ["y"] = 0.470667 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 195769, ["x"] = 0.365, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.470667 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 77822 } },
[77831] = { ["id"] = 77831, ["name"] = "A Key To Reforg(ing)", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 77831 }, ["description"] = "You have the final materials! Perfect. I prepared the forge and the mold. I just need you to add the ingredients when I say. Oh, and be ready to use that Torch of Pyrreth. Seems the relic is crucial to the forging process. I'll tell you when!", ["objectivesText"] = "Assist Weaponsmith Koref in reforging the Titan Key. Progress: The Titan Key. By the forge... Let me have a look.", ["rewardItems"] = { 191251, 191264, 193201, 207730, 208092, 208829, 208830, 208831, 208835, 208836 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 210837, ["x"] = 0.245, ["y"] = 0.608 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 210837, ["x"] = 0.245, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.245, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
