[77835] = { ["id"] = 77835, ["name"] = "Handling It: Rune of Shadowbinding", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["requiredClasses"] = { 1, 2, 6 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 77835, 78003, 78153, 78154 }, ["description"] = "Lydiara Whisperfeather is an academic who recognizes the rigidity of the rules that govern our world. She also likes bending them. If there is anyone who can assist in binding Fyr'alath's power, it's her.", ["objectivesText"] = "Seek out Lydiara Whisperfeather in the Azure Span.", ["rewardGold"] = 140450, ["rewardXP"] = 4760, ["rewardItems"] = { 208781 }, ["starts"] = { { ["x"] = 0.616, ["y"] = 0.312, ["mapID"] = 2025, ["npcID"] = 209601 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 194840, ["x"] = 0.402, ["y"] = 0.644 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.402, ["y"] = 0.644 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questGiverID"] = 209601, ["questType"] = "standard", ["sourceQuests"] = { 77191 }, ["questLines"] = { { ["id"] = 5485, ["name"] = "Rune of Shadowbinding", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["startItems"] = { 208839 } },
