[78002] = { ["id"] = 78002, ["name"] = "To The Test: Concentrated Sophic Vellum", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["requiredClasses"] = { 1, 2, 6 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 77833, 78002, 78155, 78156 }, ["description"] = "The Order and shadowflame magics are competing with each other. The enchantment will never be able to funnel Fyr'alath's power if we can't channel the excess Order magic being forced away from it. If you can channel the enchantment, your allies can catch any excess Order magic.", ["objectivesText"] = "Return the excess Order magic to Shalasar's Sophic Vellum . Progress: Don't give up. I know this is tough, but keep your goal in mind.", ["rewardGold"] = 140450, ["rewardXP"] = 4760, ["rewardItems"] = { 190316, 190321, 190327, 190329, 210003, 210048, 210222, 210240, 211398 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 194837, ["x"] = 0.624, ["y"] = 0.186 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 194837, ["x"] = 0.624, ["y"] = 0.186 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.624, ["y"] = 0.186 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 78156 }, ["questLines"] = { { ["id"] = 5484, ["name"] = "Concentrated Sophic Vellum", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[78003] = { ["id"] = 78003, ["name"] = "Handling It: Taut Tethercoil", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["requiredClasses"] = { 1, 2, 6 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 77835, 78003, 78153, 78154 }, ["description"] = "I've read of a root in the Emerald Dream known for its defensive qualities. It binds its tendrils to powerful foes as a way to protect surrounding flora and fauna. A friendly scribe might be able to help you adapt its properties. If I could just get my hands on some of that root, I'm sure I could dissect its properties and mold it into something capable of harnessing Fyr'alath's power. Here are my notes. You should be able to find powerful creatures guarding patches of wild tethercoil. Good hunting.", ["objectivesText"] = "Collect Taut Tethercoil from powerful foes throughout the Emerald Dream. Progress: Ah, thank you for bringing these to me.", ["rewardGold"] = 140450, ["rewardXP"] = 4760, ["rewardItems"] = { 194308, 208595, 209352, 209996 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 194840, ["x"] = 0.402, ["y"] = 0.644 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 194840, ["x"] = 0.402, ["y"] = 0.644 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.402, ["y"] = 0.644 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 77835 }, ["questLines"] = { { ["id"] = 5485, ["name"] = "Rune of Shadowbinding", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["startItems"] = { 209348 } },
