[78113] = { ["id"] = 78113, ["name"] = "The Challenge Tour", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["description"] = "Hello again adventurer! Do you like a challenge? I hope so as my bronze colleagues have a new set of challenge courses for you to fly. Make no mistake, these will be more difficult than the previous courses. All the obstacles remain but there none of the boons waiting for you along the route. Are you up to the challenge?", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["starts"] = { { ["npcID"] = 193411, ["x"] = 0.732, ["y"] = 0.52, ["mapID"] = 2022 }, { ["npcID"] = 199118, ["x"] = 0.88, ["y"] = 0.362, ["mapID"] = 2023 }, { ["npcID"] = 199119, ["x"] = 0.632, ["y"] = 0.136, ["mapID"] = 2024 }, { ["npcID"] = 199120, ["x"] = 0.46, ["y"] = 0.63, ["mapID"] = 2025 } }, ["ends"] = { { ["npcID"] = 193411, ["x"] = 0.732, ["y"] = 0.52, ["mapID"] = 2022 }, { ["npcID"] = 199118, ["x"] = 0.88, ["y"] = 0.362, ["mapID"] = 2023 }, { ["npcID"] = 199119, ["x"] = 0.632, ["y"] = 0.136, ["mapID"] = 2024 }, { ["npcID"] = 199120, ["x"] = 0.46, ["y"] = 0.63, ["mapID"] = 2025 } }, ["coords"] = { ["x"] = 0.732, ["y"] = 0.52, ["source"] = "quest_giver", ["mapID"] = 2025 }, ["mapCandidates"] = { ["npc"] = { 2022, 2023, 2024, 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
