[78153] = { ["id"] = 78153, ["name"] = "Handling It: Prototype Rune", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["requiredClasses"] = { 1, 2, 6 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 77835, 78003, 78153, 78154 }, ["description"] = "Ah, I see! We're in uncharted territory here, but I've got a plan. You'll need some Cosmic Ink, Runed Writhebark, and Shadowflame Essence. Sharing this recipe with a friendly scribe should allow them to complete a Crafting Order for you. Let me update my notes with a recipe for the Rune of Shadowbinding.", ["objectivesText"] = "Craft or obtain Lydiara's Binding Rune . Progress: Is it ready? Shall we proceed?", ["rewardGold"] = 140450, ["rewardXP"] = 4760, ["rewardItems"] = { 194754, 194862, 204464, 209349, 209998 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 194840, ["x"] = 0.402, ["y"] = 0.644 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 194840, ["x"] = 0.402, ["y"] = 0.644 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.402, ["y"] = 0.644 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 78003 }, ["questLines"] = { { ["id"] = 5485, ["name"] = "Rune of Shadowbinding", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[78154] = { ["id"] = 78154, ["name"] = "To the Test: Rune of Shadowbinding", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["requiredClasses"] = { 1, 2, 6 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 77835, 78003, 78153, 78154 }, ["description"] = "We need to finalize the binding. We can attune the components properly by testing them in combat against Fyrakk's most powerful lieutenants. Then we can bind the attuned materials to Fyr'alath. If you can defeat Gnarlroot, Igira the Cruel, and Volcoross while this rune is bound to them, you'll be ready to fully attune the Rune of Shadowbinding.", ["objectivesText"] = "Defeat Gnarlroot, Igira the Cruel, and Volocross in Amirdrassil, the Dream's Hope. Progress: A hero never backs down from a challenge. You've got this.", ["rewardGold"] = 140450, ["rewardXP"] = 4760, ["rewardItems"] = { 209999, 211397 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 194840, ["x"] = 0.402, ["y"] = 0.644 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 194840, ["x"] = 0.402, ["y"] = 0.644 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.402, ["y"] = 0.644 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 78153 }, ["questLines"] = { { ["id"] = 5485, ["name"] = "Rune of Shadowbinding", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024 },
[78155] = { ["id"] = 78155, ["name"] = "Handling It: Radiant Fleck of Ash", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["requiredClasses"] = { 1, 2, 6 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 77833, 78002, 78155, 78156 }, ["description"] = "I've heard that in the Emerald Dream, a coarse ash with strong properties of shadowflame tends to cling to powerful pieces of equipment. The only way to harvest that powerful dust is by disassembling the equipment. Here, use this rod I've enchanted. It should allow you to siphon off the dust you need.", ["objectivesText"] = "Collect Radiant Flecks of Ash from powerful pieces of gear throughout the Emerald Dream. Progress: Don't give up! This process doesn't just help with crafting. It builds character! Remember that!", ["rewardGold"] = 140450, ["rewardXP"] = 4760, ["rewardItems"] = { 208581, 210001, 210002 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 194837, ["x"] = 0.624, ["y"] = 0.186 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 194837, ["x"] = 0.624, ["y"] = 0.186 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.624, ["y"] = 0.186 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 77833 }, ["questLines"] = { { ["id"] = 5484, ["name"] = "Concentrated Sophic Vellum", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[78156] = { ["id"] = 78156, ["name"] = "Handling It: Radiant Vellum", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["requiredClasses"] = { 1, 2, 6 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 77833, 78002, 78155, 78156 }, ["description"] = "We can refine my creation by embedding the enchantment with Order magic. Here are my notes on Concentrated Sophic Vellum. Sharing this with another friendly enchanter should give them enough info to complete a Crafting Order for you.", ["objectivesText"] = "Craft or obtain Shalasar's Sophic Vellum . Progress: I've seen students become... disenchanted... with this type of task, but I know you're made of sterner stuff. Sorry. I've been in isolation for a long time, and I don't get to use that \"joke\" very often.", ["rewardGold"] = 140450, ["rewardXP"] = 4760, ["rewardItems"] = { 109599, 158380, 208846, 210003, 210011 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 194837, ["x"] = 0.624, ["y"] = 0.186 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 194837, ["x"] = 0.624, ["y"] = 0.186 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.624, ["y"] = 0.186 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 78155 }, ["questLines"] = { { ["id"] = 5484, ["name"] = "Concentrated Sophic Vellum", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[78159] = { ["id"] = 78159, ["name"] = "Handling It: Glowspore Grip", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["requiredClasses"] = { 1, 2, 6 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 77791, 77886, 78159, 78160, 78655 }, ["description"] = "To craft something workable, we'll need a substantial amount of Zaralek Glowspores and some leather. Here are my notes on the Symbiotic Glowspore Grip. Sharing this with a friendly leatherworker should give them enough info to complete a Crafting Order for you.", ["objectivesText"] = "Craft or obtain Erden 's Glowspore Grip. Progress: Tracking this down is a lot of work, but the quarry is worth the hunt.", ["rewardGold"] = 140450, ["rewardXP"] = 4760, ["rewardItems"] = { 209351, 210010 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 194842, ["x"] = 0.824, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 194842, ["x"] = 0.824, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.824, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 77886 }, ["questLines"] = { { ["id"] = 5483, ["name"] = "Symbiotic Glowspore Grip", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[78160] = { ["id"] = 78160, ["name"] = "To the Test: Symbiotic Glowspore Grip", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["requiredClasses"] = { 1, 2, 6 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 77791, 77886, 78159, 78160, 78655 }, ["description"] = "You will have to trust me. We need to activate the reagents embedded in the grip. Wrapping the grip around Fyr'alath's haft should work, as long as you can survive the onslaught that follows. You're going to need to make adjustments as you go, and you won't get it the first time. The spores need to adapt to the axe.", ["objectivesText"] = "Empower the grip while surviving its union with Fyr'alath. Progress: Keep at it. All this hard work is going to pay off.", ["rewardGold"] = 140450, ["rewardXP"] = 4760, ["rewardItems"] = { 205025, 207174, 207528, 210012, 210207, 211396 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 194842, ["x"] = 0.824, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 194842, ["x"] = 0.824, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.824, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 78159 }, ["questLines"] = { { ["id"] = 5483, ["name"] = "Symbiotic Glowspore Grip", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[78162] = { ["id"] = 78162, ["name"] = "Q'onzu's Distraction", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78162 }, ["description"] = "Truly your questions are important to me. Alas, I am simply too distracted. These podlings--nasty little ones. I'm sure you've seen them. They're encroaching upon my nest and just a total nuisance. Bothering myself and my friends? The nerve! Here's my feather. Why don't you go change these nuisances into something less bothersome.", ["objectivesText"] = "Weaken 8 podlings, then use Q'onzu's Faerie Feather to change them into Faerie Dragons. Progress: I can still hear the annoying sounds of those podlings. It's torture.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 137663, 208775, 210227, 210645 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 210524, ["x"] = 0.346, ["y"] = 0.692 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 210524, ["x"] = 0.346, ["y"] = 0.692 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.346, ["y"] = 0.692 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 78064 } },
[78163] = { ["id"] = 78163, ["name"] = "Q'onzu's Qualification", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78163 }, ["description"] = "You seek an audience with Q'onzu but bring no offerings? One does not just walk up and speak to the loa of Change, I'm afraid. You must first prove you are worth their time. The friends of Q'onzu have been granted one hundred questions by the loa themself! You must prove your wit and answer each of them true. Return to me if you answer all one hundred. Then perhaps you'll earn an audience.", ["objectivesText"] = "Answer Q'onzu 's 100 questions.", ["rewardGold"] = 286500, ["rewardXP"] = 1415, ["rewardItems"] = { 137663, 208775, 210645, 211373 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 210646, ["x"] = 0.348, ["y"] = 0.69 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 210524, ["x"] = 0.346, ["y"] = 0.692 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.348, ["y"] = 0.69 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 78065 } },
[78169] = { ["id"] = 78169, ["name"] = "LFGDungeons - Timewalking \"Heroic\" Random - 1st", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 78169 }, ["rewardXP"] = 400, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 25 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[78170] = { ["id"] = 78170, ["name"] = "Nurturing Ageless Seeds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78170 }, ["description"] = "The growth of these seeds is a delicate balance, requiring constant nurturing. I've found that Ageless Dewdrops , gathered from around this area, hold a special energy that can awaken the dormant potential within these seeds. If you could collect some dewdrops and apply them to the plants, we can unlock their full potential.", ["objectivesText"] = "Nurture each of the seed we planted with Ageless Dewdrops . Progress: Have you given the Ageless Dewdrops to the blossoming seeds?", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 210050, 211406, 211410 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 211265, ["x"] = 0.596, ["y"] = 0.168 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 211265, ["x"] = 0.596, ["y"] = 0.168 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.168 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 77209 }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
[78171] = { ["id"] = 78171, ["name"] = "Blossoms of the Past", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78171 }, ["description"] = "With your help, these seeds have grown into magnificent plants. However, the most exciting part is yet to come. Each of these plant's blossoms contain a treasure trove of information about their history and the magic that binds them to the world tree. By studying these blossoms, we can better understand the lineage of each plant. Gently collect the blossoms that have fallen and return them to me.", ["objectivesText"] = "Collect 3 Dreamseed Blossoms. Progress: Have you collected the three blossoms?", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 208066, 210050, 210052 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 211265, ["x"] = 0.596, ["y"] = 0.168 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 211265, ["x"] = 0.596, ["y"] = 0.168 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.168 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 78170 } },
[78172] = { ["id"] = 78172, ["name"] = "Mysterious Seeds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78172 }, ["description"] = "<These mysterious seeds might be of interest to Sylvia Whisperbloom .>", ["objectivesText"] = "Deliver the seeds to Sylvia Whisperbloom at the Wildling Garden. Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 210050 }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 211265, ["x"] = 0.596, ["y"] = 0.168 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.168 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["startItems"] = { 210050 } },
[78177] = { ["id"] = 78177, ["name"] = "To Gilneas", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 4706, ["mapID"] = 84, ["storyline"] = { 78177, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78190, 78596 }, ["description"] = "The time has come to reclaim my kingdom, champion. The Forsaken have left the land, as promised. However, in their absence it seems the Scarlet Crusade have decided to move in and use the city as their own personal stronghold. I mean to move them out. Join me in retaking Gilneas.", ["objectivesText"] = "Travel to Keel Harbor in the Ruins of Gilneas. Progress: Gilneas will be ours once more.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 54987, 54988, 54989, 54990, 55011, 62837, 62838, 62839 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 214538, ["x"] = 0.339, ["y"] = 0.155667 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 210905, ["x"] = 0.416, ["y"] = 0.722 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.339, ["y"] = 0.155667 }, ["mapCandidates"] = { ["npc"] = { 21, 84 }, ["zone"] = { 4706 } }, ["questType"] = "standard", ["sourceQuests"] = { 78596 }, ["questLines"] = { { ["id"] = 5511, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 217 },
[78178] = { ["id"] = 78178, ["name"] = "To Gilneas", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 4706, ["mapID"] = 21, ["storyline"] = { 78178, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78597, 79137 }, ["description"] = "<name>, we've received word of an offensive occurring soon in Gilneas. We have been working with the Alliance to return Gilneas to the Gilneans. Unfortunately, the Scarlet Crusade have taken up residence in the city. We wish to provide assistance in purging the Scarlet's and return the Gilneans lands to them. Lilian and I want you to join us in this operation.", ["objectivesText"] = "Travel to Gilneas in Eastern Kingdoms to assist with retaking Gilneas City for the Gilneans. Progress: Thank you for coming to help, <name>.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 54987, 54988, 54989, 54990, 55011, 62837, 62838, 62839 }, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 210965, ["x"] = 0.428, ["y"] = 0.726 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 210905, ["x"] = 0.416, ["y"] = 0.722 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.726 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 4706 } }, ["questType"] = "standard", ["sourceQuests"] = { 78597 }, ["questLines"] = { { ["id"] = 5538, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 217 },
[78180] = { ["id"] = 78180, ["name"] = "A Crusade of Red", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 4706, ["mapID"] = 21, ["storyline"] = { 78177, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78190, 78596 }, ["description"] = "Calia will lead the Forsaken army in a distracting assault to the North. I'd like you to meet up with Lilian and me in the city. There's a secret tunnel that will give us access to the south. From there, we can open the south gate and let our forces in while the Scarlets are distracted with Calia's troops. There's a group of Scarlet Crusade currently skulking about the entrance to that secret tunnel. Care to take them out?", ["objectivesText"] = "Kill 10 Scarlet Crusade Members in Aderic's Repose. Progress: These Scarlets are a blight upon the land.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 210905, ["x"] = 0.416, ["y"] = 0.722 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 210905, ["x"] = 0.416, ["y"] = 0.722 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.416, ["y"] = 0.722 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 4706 } }, ["questTurnInID"] = 210905, ["questType"] = "standard", ["sourceQuests"] = { 78177, 78178 }, ["questLines"] = { { ["id"] = 5511, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5538, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 217 },
[78181] = { ["id"] = 78181, ["name"] = "Aderic's Retort", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 4706, ["mapID"] = 217, ["storyline"] = { 78177, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78190, 78596 }, ["description"] = "The scouts report that the Scarlet Crusade at Aderic's Repose are being encouraged to tamper with the graves of my people by one Scarlet in particular. Too many Gilneans gave their lives defending this land. I will not let their sacrifice be... defiled in this manner! Take out their leader, and send them a message they won't soon forget.", ["objectivesText"] = "Slay Consecrator Hennas in Aderic's Repose. Progress: Is she dead, <name>?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 217, ["npcID"] = 210904, ["x"] = 0.5, ["y"] = 0.4424 } }, ["ends"] = { { ["mapID"] = 217, ["npcID"] = 212187, ["x"] = 0.495, ["y"] = 0.569 } }, ["coords"] = { ["mapID"] = 217, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.4424 }, ["mapCandidates"] = { ["npc"] = { 217 }, ["zone"] = { 4706 } }, ["questType"] = "standard", ["sourceQuests"] = { 78177, 78178 }, ["questLines"] = { { ["id"] = 5511, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5538, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 217 },
[78182] = { ["id"] = 78182, ["name"] = "Knee-High", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 4706, ["mapID"] = 217, ["storyline"] = { 78177, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78190, 78596 }, ["description"] = "Tess and Voss are waiting for you at the end of the tunnel. Once you arrive, the three of you will open the south gate from the inside, and let our forces into the city. Head through the tunnel to meet them. Take this torch, the way is infested with vermin. I'll ready our forces to storm the gate the moment it is opened.", ["objectivesText"] = "Make your way through the secret tunnel in Aderic's Repose to Gilneas City.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 217, ["npcID"] = 212187, ["x"] = 0.495, ["y"] = 0.569 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 210905, ["x"] = 0.416, ["y"] = 0.722 } }, ["coords"] = { ["mapID"] = 217, ["source"] = "quest_giver", ["x"] = 0.495, ["y"] = 0.569 }, ["mapCandidates"] = { ["npc"] = { 21, 217 }, ["zone"] = { 4706 } }, ["questType"] = "standard", ["sourceQuests"] = { 78180, 78181 }, ["questLines"] = { { ["id"] = 5511, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5538, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 217 },
[78183] = { ["id"] = 78183, ["name"] = "Scarlet Blood", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 4706, ["mapID"] = 21, ["storyline"] = { 78177, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78190, 78596 }, ["description"] = "Looks like they've filled the city with their most experienced forces. Don't worry, I have plenty of experience taking them down... personally. We'll whittle their numbers down one by one.", ["objectivesText"] = "Kill 12 Scarlet forces. Progress: Are you done?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 210964, ["x"] = 0.426, ["y"] = 0.727 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 210964, ["x"] = 0.426, ["y"] = 0.727 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.727 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 4706 } }, ["questTurnInID"] = 210964, ["questType"] = "standard", ["sourceQuests"] = { 78182 }, ["questLines"] = { { ["id"] = 5511, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5538, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 217 },
[78184] = { ["id"] = 78184, ["name"] = "Smokepowder and Mirrors", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 4706, ["mapID"] = 21, ["storyline"] = { 78177, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78190, 78596 }, ["description"] = "Opening the gate is all well and good, but we'll need to clear a way for our forces to advance first. Our scouts reported that the Crusade has explosives that they've stashed in the area. Surely they won't mind if we borrow some?", ["objectivesText"] = "Collect 8 Scarlet Explosives . Progress: Hmm?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 211248 }, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 210905, ["x"] = 0.416, ["y"] = 0.722 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 210905, ["x"] = 0.416, ["y"] = 0.722 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.416, ["y"] = 0.722 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 4706 } }, ["questTurnInID"] = 210905, ["questType"] = "standard", ["sourceQuests"] = { 78182 }, ["questLines"] = { { ["id"] = 5511, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5538, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 217 },
[78185] = { ["id"] = 78185, ["name"] = "Hounds of War", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 4706, ["mapID"] = 217, ["storyline"] = { 78177, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78190, 78596 }, ["description"] = "I think we've had enough fun on our own, yes? The Scarlets stationed near the city's chapel seem to be the most elite of their forces. I believe we'll find whoever is leading them there, but going alone is unnecessarily dangerous. Time to bring the true might of Gilneas and take our city back. My forces stand ready to charge!", ["objectivesText"] = "Open the gates to Gilneas City. Progress: My people stand ready.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["npcID"] = 210905 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4706 } }, ["questGiverID"] = 210905, ["questType"] = "standard", ["sourceQuests"] = { 78183, 78184 }, ["questLines"] = { { ["id"] = 5511, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5538, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 217 },
[78186] = { ["id"] = 78186, ["name"] = "Crushing the Crusade", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 4706, ["mapID"] = 21, ["storyline"] = { 78177, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78190, 78596 }, ["description"] = "The most powerful members of the Scarlet Crusade will be defending the nest of their leader, <name>. That's where I come in. Nothing like a little distraction to take an enemy down swiftly. Just let me know where and when to strike.", ["objectivesText"] = "Kill 12 Scarlet Crusade members in the Gilneas City chapel courtyard.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 210964, ["x"] = 0.426, ["y"] = 0.727 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 210905, ["x"] = 0.416, ["y"] = 0.722 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.727 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 4706 } }, ["questType"] = "standard", ["sourceQuests"] = { 78185 }, ["questLines"] = { { ["id"] = 5511, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5538, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 217 },
[78187] = { ["id"] = 78187, ["name"] = "Artillerist Arsonist", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 4706, ["mapID"] = 21, ["storyline"] = { 78177, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78190, 78596 }, ["description"] = "The chapel seems to be their base, and it is well defended--they've set up multiple defenses throughout the courtyard. The troops would have an easier time sieging if we could get some of them out of the way. Remember those explosives we gathered? Now is when they come in handy.", ["objectivesText"] = "Plant 6 explosives.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["x"] = 0.558, ["y"] = 0.587, ["mapID"] = 217, ["npcID"] = 213995 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 210905, ["x"] = 0.416, ["y"] = 0.722 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.416, ["y"] = 0.722 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 4706 } }, ["questGiverID"] = 213995, ["questType"] = "standard", ["sourceQuests"] = { 78185 }, ["questLines"] = { { ["id"] = 5511, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5538, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 217 },
[78188] = { ["id"] = 78188, ["name"] = "Righteous Fire, Righteous Fury", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 4706, ["mapID"] = 21, ["storyline"] = { 78177, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78190, 78596 }, ["description"] = "Only one person remains standing between us and our city. Ready yourself--this won't be an easy fight.", ["objectivesText"] = "Slay the leader of the Scarlet Crusade. Progress: Is she dead?", ["rewardGold"] = 561800, ["rewardXP"] = 11895, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 210905, ["x"] = 0.416, ["y"] = 0.722 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 210905, ["x"] = 0.416, ["y"] = 0.722 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.416, ["y"] = 0.722 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 4706 } }, ["questType"] = "standard", ["sourceQuests"] = { 78186, 78187 }, ["questLines"] = { { ["id"] = 5511, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5538, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 217 },
[78189] = { ["id"] = 78189, ["name"] = "Beginning a New Dawn", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 4706, ["mapID"] = 217, ["storyline"] = { 78177, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78190, 78596 }, ["description"] = "Much has changed since we had to leave this city. Both the land, and my people. Bear witness, <name>, to the future of Gilneas.", ["objectivesText"] = "Listen to Genn Greymane 's conversation with Tess.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 211788, 211873 }, ["starts"] = { { ["mapID"] = 217, ["npcID"] = 210904, ["x"] = 0.5, ["y"] = 0.4424 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 210905, ["x"] = 0.416, ["y"] = 0.722 } }, ["coords"] = { ["mapID"] = 217, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.4424 }, ["mapCandidates"] = { ["npc"] = { 21, 217 }, ["zone"] = { 4706 } }, ["questType"] = "standard", ["sourceQuests"] = { 78188 }, ["questLines"] = { { ["id"] = 5511, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5538, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 217 },
[78190] = { ["id"] = 78190, ["name"] = "What We Left Behind", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 4706, ["mapID"] = 21, ["storyline"] = { 78177, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78190, 78596 }, ["description"] = "He just... handed me the kingdom. Me! This is going to take a bit to process. But... look, <name>. I know my father's a strong man, but there are times he holds himself so rigid that I fear he'll break. I'm not about to coddle him, but if you could just follow along, make sure he's all right? Soothe a daughter's heart? A queen's heart?", ["objectivesText"] = "Follow King Greymane and keep an eye on him.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 211788, 211873 }, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 210905, ["x"] = 0.416, ["y"] = 0.722 } }, ["ends"] = { { ["mapID"] = 217, ["npcID"] = 210904, ["x"] = 0.5, ["y"] = 0.4424 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.416, ["y"] = 0.722 }, ["mapCandidates"] = { ["npc"] = { 21, 217 }, ["zone"] = { 4706 } }, ["questType"] = "standard", ["sourceQuests"] = { 78189 }, ["questLines"] = { { ["id"] = 5511, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 12, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 217 },
[78203] = { ["id"] = 78203, ["name"] = "Superbloom", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 78203 }, ["rewardXP"] = 2125, ["rewardItems"] = { 200073, 201921, 201922, 201923, 201924, 211389, 211411, 211413, 211414 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2VignetteID"] = 5813, ["db2VignetteName"] = "Superbloom" },
[78206] = { ["id"] = 78206, ["name"] = "Emerald Bounty", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78206 }, ["description"] = "There are so many more species to locate and study. As you explore the Dream, you will find more seeds known as Dreamseeds. Please, nurture them to continue our studies, and enjoy the bounty they share with you! You will find Dreamseeds all over, but many are hoarded by powerful creatures around the Dream. Additionally, you should keep an eye out for the surge of life energy we call an Emerald Frenzy. It will be a source of many Emerald Dewdrops, which will help in nurturing Dreamseeds.", ["objectivesText"] = "Partake in the Emerald Frenzy to earn Emerald Dewdrops and contribute a Dreamseed to sprout new growths. Progress: Have you helped further our research?", ["rewardGold"] = 77400, ["rewardXP"] = 355, ["rewardItems"] = { 200073, 201921, 201922, 201923, 201924, 208047, 208066, 208067, 210050 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 211265, ["x"] = 0.596, ["y"] = 0.168 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 211265, ["x"] = 0.596, ["y"] = 0.168 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.168 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 78171 } },
[78215] = { ["id"] = 78215, ["name"] = "Rooted in Danger", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78215 }, ["objectivesText"] = "Kill creatures or Players Creatures Killed Creatures Killed Creatures Killed Creatures Killed Creatures Killed", ["rewardXP"] = 1770, ["starts"] = { { ["x"] = 0.448, ["y"] = 0.419, ["mapID"] = 2200 } }, ["ends"] = { { ["x"] = 0.448, ["y"] = 0.419, ["mapID"] = 2200 } }, ["coords"] = { ["mapID"] = 2200, ["x"] = 0.448, ["y"] = 0.419 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14529 } }, ["questType"] = "pvp", ["db2Objectives"] = { { ["text"] = "Kill creatures or Players", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Creatures Killed", ["amount"] = 13, ["type"] = 0, ["objectID"] = 211345, ["orderIndex"] = 2 }, { ["text"] = "Creatures Killed", ["amount"] = 13, ["type"] = 0, ["objectID"] = 211343, ["orderIndex"] = 3 }, { ["text"] = "Creatures Killed", ["amount"] = 13, ["type"] = 0, ["objectID"] = 211347, ["orderIndex"] = 4 }, { ["text"] = "Creatures Killed", ["amount"] = 10, ["type"] = 0, ["objectID"] = 211342, ["orderIndex"] = 5 }, { ["text"] = "Creatures Killed", ["amount"] = 20, ["type"] = 0, ["objectID"] = 211344, ["orderIndex"] = 6 } }, ["db2LabelIDs"] = { 2762 }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["db2QuestInfoID"] = 113, ["db2QuestInfoName"] = "PvP World Quest" },
[78226] = { ["id"] = 78226, ["name"] = "A Most Intriguing Invitation", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78226, 78228, 78244, 78348, 78352, 78353, 78620, 78621, 78624, 78630, 78658, 78659, 78671, 78948, 79156, 83503, 91868 }, ["description"] = "We've received an invitation. Or rather, you have, <name>. It's a request to meet with the Vizier. That name rattles even the most wealthy and powerful figures in the City of Threads. Gaining this individual as an ally could seal our victory against Ansurek's horrid little shadow for good. You're to meet them in the Burrows. Use the pheromone dispenser here in my lair to mask yourself enough to enter safely.", ["objectivesText"] = "Meet the 'Vizier' in the Burrows of Azj-Kahet 's City of Threads.", ["rewardGold"] = 154900, ["rewardXP"] = 5300, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 207471, ["x"] = 0.556, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 207471, ["x"] = 0.556, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questTurnInID"] = 207471, ["questType"] = "standard", ["sourceQuests"] = { 78256 }, ["questLines"] = { { ["id"] = 5506, ["name"] = "Plans within Plans", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 6006, ["name"] = "Catch Up: War Within: Wrapper 3", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5506, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5506, ["questLineOrder"] = 13 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6006, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2216, ["db2QuestHubAreaPoiID"] = 7940 },
[78228] = { ["id"] = 78228, ["name"] = "Into a Skittering City", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 78226, 78228, 78244, 78348, 78352, 78353, 78620, 78621, 78624, 78630, 78658, 78659, 78671, 78948, 79156, 83503, 91868 }, ["description"] = "I sent these 'invitations' to you and Alleria, both. I'd have bet my father's sword you wouldn't let such a unique opportunity pass you by--it's what sets you apart from us all. Alleria, however... Nevermind. She's as cautious as she is assertive. I suppose I was hoping for the latter, but it's the former that's kept her alive. Perhaps she'll find us later on. For now, it's time you and my new acquaintance properly meet.", ["objectivesText"] = "Tell the Vizier of the Weaver's plan, and apply Pheromones for access to the Umbral Bazaar. Progress: For being so young, I find Master Anduin is practically bursting with the grand experiences of a much more traveled sort. Impressive. At least from the perspective of a humble Kaheti.", ["rewardGold"] = 154900, ["rewardXP"] = 5300, ["starts"] = { { ["x"] = 0.671, ["y"] = 0.315, ["mapID"] = 2216, ["npcID"] = 211351 } }, ["ends"] = { { ["x"] = 0.671, ["y"] = 0.315, ["mapID"] = 2216, ["npcID"] = 211351 } }, ["coords"] = { ["mapID"] = 2216, ["x"] = 0.671, ["y"] = 0.315 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14753 } }, ["questGiverID"] = 211351, ["questTurnInID"] = 211351, ["questType"] = "standard", ["sourceQuests"] = { 78226 }, ["questLines"] = { { ["id"] = 5506, ["name"] = "Plans within Plans", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 6006, ["name"] = "Catch Up: War Within: Wrapper 3", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5506, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5506, ["questLineOrder"] = 13 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6006, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2216 },
[78231] = { ["id"] = 78231, ["name"] = "Like a Spider on the Wall", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2255, ["storyline"] = { 78226, 78228, 78231, 78232, 78244, 78248, 84022 }, ["description"] = "Inviting Alleria was a risk... but even at this moment, I feel it was worth taking. I know it was. I will speak with her on my own. In the meantime, I'd like you to venture into the city above. The pheromones Nizrek gifted you will allow access into the Umbral Bazaar. Observe the merchants, listen to the conversations, purchase their goods. This city is as vibrant as Stormwind. And its people are as worthy of freeing from abuse as our own. Experience for yourself how similar we all are.", ["objectivesText"] = "Explore the Umbral Bazaar. Progress: Enjoy yourself? And no trouble with the pheromones, I hope.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["starts"] = { { ["x"] = 0.669, ["y"] = 0.319, ["mapID"] = 2216, ["npcID"] = 211351 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 217386, ["x"] = 0.605, ["y"] = 0.688 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.688 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14753 } }, ["questGiverID"] = 211351, ["questType"] = "standard", ["sourceQuests"] = { 78228 }, ["questLines"] = { { ["id"] = 5506, ["name"] = "Plans within Plans", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5506, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5506, ["questLineOrder"] = 13 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2213 },
[78232] = { ["id"] = 78232, ["name"] = "Rewriting the Rewritten", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 78226, 78228, 78231, 78232, 78244, 78248, 84022 }, ["description"] = "We called you here today because it is \"Ascendance Day\". Queen Ansurek has deigned declare it a day to revel in our newfound, void-infused evolution--our \"Ascendance\". Please note my satirical nuance. While the streets are alive with festivity and joyous citizens, the Shadecasters planted through the Bazaar will be drowning the air with Ansurek's vile propaganda. Take this invention of mine. Use it to overwrite them with more... illuminating information for the public.", ["objectivesText"] = "Overwrite 3 Shadecasters. Progress: Anduin has me worried. I've always known him to lean towards diplomacy, but does he have the conviction to draw his sword? If he does not, he may never be able to end this war.", ["rewardGold"] = 292100, ["rewardXP"] = 10595, ["rewardItems"] = { 225970 }, ["starts"] = { { ["x"] = 0.675, ["y"] = 0.325, ["mapID"] = 2216, ["npcID"] = 211499 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 211375, ["x"] = 0.549, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.549, ["y"] = 0.456 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questGiverID"] = 211499, ["questType"] = "standard", ["sourceQuests"] = { 78228 }, ["questLines"] = { { ["id"] = 5506, ["name"] = "Plans within Plans", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5506, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5506, ["questLineOrder"] = 13 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2213 },
[78233] = { ["id"] = 78233, ["name"] = "The Weaver's Gift", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78233, 78234, 78236, 78237, 78249, 78250, 78251, 78254, 78255, 78256, 78383, 79175, 79625, 80399 }, ["description"] = "A little weave-rat tells me that an intriguing series of events are playing out to the north. It seems there has been a remarkably coincidental waterfall of failures marring the military efforts there. I want to know who is responsible. Look into it for me, and see if your curiously binary eyes can pluck out any potential allies. Some of your little friends are among the escapees drawing the ire of one \"Zev'kall.\" Do go catch up. Tell them the Weaver bids them... greetings.", ["objectivesText"] = "Find the friends the Weaver has revealed to you as a gift.", ["rewardGold"] = 30900, ["rewardXP"] = 1325, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 207471, ["x"] = 0.556, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 211409, ["x"] = 0.592, ["y"] = 0.194 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 78352, 78393 }, ["questLines"] = { { ["id"] = 5521, ["name"] = "Unraveling the Trapped", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5521, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5521, ["questLineOrder"] = 12 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[78234] = { ["id"] = 78234, ["name"] = "Force Your Way", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78233, 78234, 78236, 78237, 78249, 78250, 78251, 78254, 78255, 78256, 78383, 79175, 79625, 80399 }, ["description"] = "Even with the general gone, it's not going to be easy getting out of here. This place is infested. I know I'm hiding it well, but I'm not exactly feeling my best. I'm not sure I'll be much help in this state. You're going to have to clear a path for us.", ["objectivesText"] = "Kill 8 Kaheti forces in Rak-Zakaz. Progress: Say what you will, but you do meet the most interesting company while imprisoned.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 220051, ["x"] = 0.63, ["y"] = 0.27 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 220051, ["x"] = 0.63, ["y"] = 0.27 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questTurnInID"] = 220051, ["questType"] = "standard", ["sourceQuests"] = { 78236 }, ["questLines"] = { { ["id"] = 5521, ["name"] = "Unraveling the Trapped", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5521, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5521, ["questLineOrder"] = 12 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[78236] = { ["id"] = 78236, ["name"] = "Scrappy Straggler", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78233, 78234, 78236, 78237, 78249, 78250, 78251, 78254, 78255, 78256, 78383, 79175, 79625, 80399 }, ["description"] = "If someone got left behind, we need to do something about that. I hate to say it, but these people need someone to protect them here. I have to stay. Find this straggler. And while you're at it, take a peek behind enemy lines. See if you can find anything useful.", ["objectivesText"] = "Rescue the straggler in Rak-Zakaz. Progress: The others all made it to safety, right?", ["rewardGold"] = 292100, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 211409, ["x"] = 0.592, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 220051, ["x"] = 0.63, ["y"] = 0.27 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 80399 }, ["questLines"] = { { ["id"] = 5521, ["name"] = "Unraveling the Trapped", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5521, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5521, ["questLineOrder"] = 12 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[78237] = { ["id"] = 78237, ["name"] = "Let Fly!", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78233, 78234, 78236, 78237, 78249, 78250, 78251, 78254, 78255, 78256, 78383, 79175, 79625, 80399 }, ["description"] = "Hm. This Anub'azal gave the orders that led to the prisoners' escape. Zev'kall here didn't seem very pleased with that. So how about this--you sneak into Siegehold, and make best friends with Anub'azal . Easy. I've noticed a lot of cargo being ferried over, I'm sure no one would notice if we just swapped out the contents of a particular crate. In the meantime, I'll share our discoveries with the Weaver. I'd love to come with you, but I'd rather not tempt more Flynn stabbings today.", ["objectivesText"] = "Stow away into a box to be carried into Siegehold.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["starts"] = { { ["npcID"] = 211444 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 217330, ["x"] = 0.454, ["y"] = 0.198 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.198 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questGiverID"] = 211444, ["questType"] = "standard", ["sourceQuests"] = { 78234, 78383 }, ["questLines"] = { { ["id"] = 5521, ["name"] = "Unraveling the Trapped", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5521, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5521, ["questLineOrder"] = 12 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[78244] = { ["id"] = 78244, ["name"] = "Kaheti Hospitality", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 78226, 78228, 78244, 78348, 78352, 78353, 78620, 78621, 78624, 78630, 78658, 78659, 78671, 78948, 79156, 83503, 91868 }, ["description"] = "That stage in the distance is where Ansurek will give her Ascendance Day speech. You, Alleria, and I shall make our way up one of the nearby towers and observe. If we are to turn her own citizens against her, then we must also gain as much first hand experience with her tactics as we can manage. I've already told Alleria as much, but we cannot make our presence known. If we do run into any trouble, the Vizier has arranged for a set of getaway fliers at the edge of the Burrows where we first met.", ["objectivesText"] = "Speak to Anduin when you're ready to observe the Ascendance Day speech, and exit the city quietly after. Progress: The Vizier has made special accommodations for us to reach the tower we'll be observing from. Sticking to the plan will mean we all get out safely.", ["rewardGold"] = 619600, ["rewardXP"] = 13245, ["rewardItems"] = { 225561, 225562, 225563 }, ["rewardChoices"] = { 225561, 225562, 225563 }, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 217386, ["x"] = 0.552, ["y"] = 0.46 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 217386, ["x"] = 0.552, ["y"] = 0.46 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.46 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["sourceQuests"] = { 78231, 78232 }, ["questLines"] = { { ["id"] = 5506, ["name"] = "Plans within Plans", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 6006, ["name"] = "Catch Up: War Within: Wrapper 3", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5506, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5506, ["questLineOrder"] = 13 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6006, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[78248] = { ["id"] = 78248, ["name"] = "What We Still Have", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2255, ["storyline"] = { 78226, 78228, 78231, 78232, 78244, 78248, 84022 }, ["description"] = "I went into the city prepared--prepared to end this war even if I was ended with it. But I am alive. As are you. As is Anduin. We have new allies and a new way forward. I realize at this moment that my vision may have been obscured by my guilt. Part of me feels those words are Anduin's, not mine. Perhaps he's rubbing off on me. Let us return to your Weaver's Lair. I wish to see yours and Anduin's efforts to save these people as well as our own through.", ["objectivesText"] = "Return to the Weaver's Lair. Progress: I do believe my suggestion was to stay quiet while in the city, was it not?", ["rewardGold"] = 147500, ["rewardXP"] = 5300, ["rewardCurrencies"] = { { ["id"] = 3004, ["amount"] = 2500 } }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 217385, ["x"] = 0.606, ["y"] = 0.688 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 207471, ["x"] = 0.556, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.606, ["y"] = 0.688 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 78244 }, ["questLines"] = { { ["id"] = 5506, ["name"] = "Plans within Plans", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5506, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5506, ["questLineOrder"] = 13 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[78249] = { ["id"] = 78249, ["name"] = "Specific Personages", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78233, 78234, 78236, 78237, 78249, 78250, 78251, 78254, 78255, 78256, 78383, 79175, 79625, 80399 }, ["description"] = "Zev'kall has recently placed his own loyal lackeys in key positions around Siegehold. Killing them will force replacements, which will cause chaos and re-training. All of which will make Zev'kall struggle. Get rid of all three.", ["objectivesText"] = "Kill Zev'kall's minions for General Anub'azal . Progress: All three must be removed from office.", ["rewardGold"] = 280900, ["rewardXP"] = 10595, ["rewardItems"] = { 225549, 225550, 225551, 225552 }, ["rewardChoices"] = { 225549, 225550, 225551, 225552 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 217330, ["x"] = 0.454, ["y"] = 0.198 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 217330, ["x"] = 0.454, ["y"] = 0.198 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.198 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 79175 }, ["questLines"] = { { ["id"] = 5521, ["name"] = "Unraveling the Trapped", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5521, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5521, ["questLineOrder"] = 12 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[78250] = { ["id"] = 78250, ["name"] = "General Admission", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78233, 78234, 78236, 78237, 78249, 78250, 78251, 78254, 78255, 78256, 78383, 79175, 79625, 80399 }, ["description"] = "It isn't enough to inconvenience Zev'kall. He should be humiliated. I already have some information, but I need more. He stores military logs in a room that is too tiny for me to access. See what information he's hiding. I'm sure there's potential blackmail material in there somewhere.", ["objectivesText"] = "Find some useful blackmail material for the General. Progress: There should be something I can use.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["rewardItems"] = { 217165 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 217330, ["x"] = 0.454, ["y"] = 0.198 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 217330, ["x"] = 0.454, ["y"] = 0.198 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.198 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 79175 }, ["questLines"] = { { ["id"] = 5521, ["name"] = "Unraveling the Trapped", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5521, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5521, ["questLineOrder"] = 12 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[78251] = { ["id"] = 78251, ["name"] = "Dalaran's Most Distressed", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78233, 78234, 78236, 78237, 78249, 78250, 78251, 78254, 78255, 78256, 78383, 79175, 79625, 80399 }, ["description"] = "I don't trust this big bug at all. He let me lay there ages without saying anything! But if he wants to give us access to Siegehold, let's use it. I saw some other people dragged away into other parts of the base. I don't think they're eating them. It looks more like they're transporting them somewhere. Let's gather them up, make a prisoner convoy, and roll on out. Find me outside!", ["objectivesText"] = "Free prisoners for the fake prisoner convoy.", ["rewardGold"] = 280900, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 211399, ["x"] = 0.452, ["y"] = 0.2 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 215413, ["x"] = 0.476, ["y"] = 0.245 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.2 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 78249, 78250 }, ["questLines"] = { { ["id"] = 5521, ["name"] = "Unraveling the Trapped", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5521, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5521, ["questLineOrder"] = 12 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[78254] = { ["id"] = 78254, ["name"] = "Stolen Influence", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78233, 78234, 78236, 78237, 78249, 78250, 78251, 78254, 78255, 78256, 78383, 79175, 79625, 80399 }, ["description"] = "These logs of Zev'kall's... he is wasting numerous nerubian lives. Throwing them away like some rabid mantid. We must act. As I said, Zev'kall doesn't produce his own pheromone marks anymore due to this 'Ascension' process. He's been forced to use mine. His alchemist is trying to concoct some for him... but once they do, what of me? Take those false pheromones and sneak them out of Siegehold. Expose Zev'kall, use them... you're creative, aren't you? Just make it messy.", ["objectivesText"] = "Steal the pheromones and prepare to sneak them out of Siegehold. Progress: What did the General ask you to do?", ["rewardGold"] = 567400, ["rewardXP"] = 13245, ["rewardItems"] = { 212528 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 217330, ["x"] = 0.454, ["y"] = 0.198 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 215413, ["x"] = 0.476, ["y"] = 0.245 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.198 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 78249, 78250 }, ["questLines"] = { { ["id"] = 5521, ["name"] = "Unraveling the Trapped", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5521, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5521, ["questLineOrder"] = 12 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[78255] = { ["id"] = 78255, ["name"] = "Just Act Casual", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78233, 78234, 78236, 78237, 78249, 78250, 78251, 78254, 78255, 78256, 78383, 79175, 79625, 80399 }, ["description"] = "It's time to get outta here with the prisoners and those pheromones. I've found some convincing chains, since we have such a big group. Long as everybody stays in character, our chances look good. We've only got General Anub'azal's marker scent goop for you and I, so we'll be the drones with permission. You do all the talkin', while I mind the cart. I hope this works. Lead us through the gate, <name>!", ["objectivesText"] = "Help the convoy to exit Siegehold by speaking to the gatekeeper. Progress: We just need to make it out of the entrance. I'll figure it out from there.", ["rewardGold"] = 280900, ["rewardXP"] = 10595, ["rewardItems"] = { 225513, 225520, 225523, 225537 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 215413, ["x"] = 0.476, ["y"] = 0.245 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 215845, ["x"] = 0.518, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.245 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 78251, 78254 }, ["questLines"] = { { ["id"] = 5521, ["name"] = "Unraveling the Trapped", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5521, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5521, ["questLineOrder"] = 12 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[78256] = { ["id"] = 78256, ["name"] = "The General's Consensus", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78233, 78234, 78236, 78237, 78249, 78250, 78251, 78254, 78255, 78256, 78383, 79175, 79625, 80399 }, ["description"] = "We got lucky here. That General Anub'azal is so interested in sabotaging Zev'kall that it's an \"enemy of our enemy is our friend\" situation for today. I feel like this is gonna be a theme: spiders tryin' to use us against each other. Ah, well. You're gonna want to take those pheromones somewhere useful, huh? You do that. I'll take these folks safely out of harm's way.", ["objectivesText"] = "Take Zev'kall's pheromones to someone that has a use for them. Progress: What do you have for me?", ["rewardGold"] = 29200, ["rewardXP"] = 1325, ["rewardItems"] = { 217042 }, ["rewardCurrencies"] = { { ["id"] = 3003, ["amount"] = 2500 } }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 215845, ["x"] = 0.518, ["y"] = 0.258 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 207471, ["x"] = 0.556, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.258 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 78255 }, ["questLines"] = { { ["id"] = 5521, ["name"] = "Unraveling the Trapped", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5521, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5521, ["questLineOrder"] = 12 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[78262] = { ["id"] = 78262, ["name"] = "It Starts With a Stone", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78262 }, ["description"] = "This land holds so many secrets. And even more power! And you... we both know you enjoy unraveling secrets and collecting marvelous gear. And when you're ready to unlock the power of gear you find in this new land, come visit Cuzolth and me. We are experimenting and will be able to upgrade your gear by the time you come back. Please bring me some Flightstones and a new item so I can show you how these upgrades work.", ["objectivesText"] = "Acquire 50 Flightstones by defeating unique creatures, conquering dungeons and raids, completing world activities, or by looting caches. Then speak to Cuzolth and upgrade a piece of Season 3 equipment using Flightstones . Progress: Can you feel the power? The excitement of knowing you can now take on even more daring adventures?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 211328, ["x"] = 0.498, ["y"] = 0.628 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 211328, ["x"] = 0.498, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5505, ["name"] = "10.2 Upgrade System Tutorial", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
[78271] = { ["id"] = 78271, ["name"] = "Dreaming of Crests", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78271 }, ["description"] = "Now that you've learned the fundamentals, you can easily upgrade lower-level gear. Sooner than later, though, you will find better gear that requires various types of Dreaming Crests to upgrade. Much like Flightstones, these Crests are rewarded through many different activities. Dreaming Crests have four tiers, and more dangerous tasks reward you with higher-tier crests. Go and help with tasks, down formidable foes, find treasures, and bring me a few handfuls of Whelpling's Dreaming Crests!", ["objectivesText"] = "Acquire 15 Whelpling's Dreaming Crests by defeating unique creatures, conquering dungeons and raids, completing world activities, or by looting caches. Then speak to Vaskarn . Progress: I foresee great results with these Dreaming Crests.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 210180, 210917 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 211328, ["x"] = 0.498, ["y"] = 0.628 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 211328, ["x"] = 0.498, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 78262 } },
[78272] = { ["id"] = 78272, ["name"] = "Interrupting Duck", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["event"] = "Noblegarden", ["expansion"] = 10, ["storyline"] = { 78272 }, ["description"] = "There are so many bunches of baby bunnies bouncing all about! Ducks have been swarming us and we haven't been able to feed the newborns. You look like you could handle the situation--care to help?", ["objectivesText"] = "Feed carrots to 10 baby bunnies.", ["rewardItems"] = { 45072 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[78274] = { ["id"] = 78274, ["name"] = "Quacking Down", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["event"] = "Noblegarden", ["expansion"] = 10, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 78274 }, ["series"] = { 79134 }, ["description"] = "Here they go again. Do you mind scaring off those ducks again? I need to stay here and keep an eye on my golden egg.", ["objectivesText"] = "Scare off 10 ducks using the Horn of Honking . Progress: Show those ducks who's boss!", ["rewardItems"] = { 45072, 210558 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 211646, ["x"] = 0.42, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 211646, ["x"] = 0.42, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["sourceQuests"] = { 79331 }, ["db2LabelIDs"] = { 3250 } },
[78289] = { ["id"] = 78289, ["name"] = "To Rambleshire", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 78289, 78290, 78291, 78292, 78293, 78294 }, ["series"] = { 78291 }, ["description"] = "There's word of troubles in the village of Rambleshire, at the base of Thunderhead Peak. Can't abide the place myself. Always wet and rumbling. But Rooktender Lufsela thought it worth a look, however, seeing as how the birds fancy the moss that the village produces. She's still green though, and might just need a hand.", ["objectivesText"] = "Meet Lufsela in Rambleshire.", ["rewardGold"] = 77400, ["rewardXP"] = 2380, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 214352, ["x"] = 0.328, ["y"] = 0.338 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 211740, ["x"] = 0.599333, ["y"] = 0.302 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.328, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = { 2248, 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 78536 }, ["questLines"] = { { ["id"] = 5509, ["name"] = "Rambleshire", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[78290] = { ["id"] = 78290, ["name"] = "Sleepy Sheep", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14784, ["mapID"] = 2248, ["storyline"] = { 78289, 78290, 78291, 78292, 78293, 78294 }, ["description"] = "The energized moss that these flocks produce is a favorite treat for the storm rooks. But with the storm gone, the rams are lethargic, vulnerable, and no longer producing. We may not be able to conjure a storm, but we could offer the mosswools a motivating zap. See if you can find a lodestone that will hold a charge. Then bring it here to Shraubendre so she can get it loaded up.", ["objectivesText"] = "Use an Energized Lodestone to rouse 8 Lethargic Mosswools near Rambleshire. Progress: The lodestone should hold just enough of a charge to give the mosswools the motivation they need to return to their corrals. It won't hurt them.", ["rewardGold"] = 289300, ["rewardXP"] = 9515, ["rewardItems"] = { 210489, 211459 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 211740, ["x"] = 0.599333, ["y"] = 0.302 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 211740, ["x"] = 0.599333, ["y"] = 0.302 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.599333, ["y"] = 0.302 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78289 }, ["questLines"] = { { ["id"] = 5509, ["name"] = "Rambleshire", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[78291] = { ["id"] = 78291, ["name"] = "Power Predators", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14784, ["mapID"] = 2248, ["storyline"] = { 78289, 78290, 78291, 78292, 78293, 78294 }, ["series"] = { 78289 }, ["description"] = "Thunderhead Peak normally boasts a perpetual storm from which the local mosswools draw energy. Without it, the poor dears look to be listless and near dead on their feet. That makes them easy pickings for predators. To get moss production back on track, we'll need to get to the bottom of the missing storm. But first we need to beat back these predators before they turn the mosswools to gravel.", ["objectivesText"] = "Cull 10 predators around Rambleshire. Progress: Please do what you can for the poor mosswools.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 211740, ["x"] = 0.599333, ["y"] = 0.302 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 211740, ["x"] = 0.599333, ["y"] = 0.302 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.599333, ["y"] = 0.302 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78289 }, ["questLines"] = { { ["id"] = 5509, ["name"] = "Rambleshire", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[78292] = { ["id"] = 78292, ["name"] = "Lost Lord of the Storm", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14784, ["mapID"] = 2248, ["storyline"] = { 78289, 78290, 78291, 78292, 78293, 78294 }, ["description"] = "Listen well, stranger. Once a year, the great ram Durzan , Lord of the Southern Storm, crosses the isle to meet his brother Belzt on Thunderhead Peak. The clash of their horns heralds the storm and brings prosperity for another year. But something is wrong. Durzan has not come and the skies have cleared. The Stormrider may not believe, but I sense you have seen wilder things. Ask around if you still have doubts. Just please help us find Durzan .", ["objectivesText"] = "Find Durzan near Rambleshire. Progress: Pray Durzan is still with us. If the brothers don't meet at the summit, the storm and our livelihoods will be lost.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 209918, ["x"] = 0.592, ["y"] = 0.296 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 209918, ["x"] = 0.592, ["y"] = 0.296 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78290, 78291 }, ["questLines"] = { { ["id"] = 5509, ["name"] = "Rambleshire", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[78293] = { ["id"] = 78293, ["name"] = "Their Moss, Our Gain", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14784, ["mapID"] = 2248, ["storyline"] = { 78289, 78290, 78291, 78292, 78293, 78294 }, ["description"] = "You say nerubians had him? Not sure what they wanted with old Durzan, but he looks weakened by the ordeal. We can't have that if he's to challenge his brother Belzt on the mountain. The moss harvested from our flocks gives the storm rooks a kick, so Durzan might benefit from it as well. Collect a bushel's worth and make an offering. And if the mosswools get ornery, be sure to put them in their place.", ["objectivesText"] = "Harvest moss from Rambleshire Mosswools and feed it to Durzan. Progress: That moss captures and contains the power of the storm. It ought to give Durzan the boost he needs to get back up on that mountain.", ["rewardGold"] = 232300, ["rewardXP"] = 7135, ["rewardItems"] = { 211858 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 209918, ["x"] = 0.592, ["y"] = 0.296 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 209918, ["x"] = 0.592, ["y"] = 0.296 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78292 }, ["questLines"] = { { ["id"] = 5509, ["name"] = "Rambleshire", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[78294] = { ["id"] = 78294, ["name"] = "Thunderhead Butt", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14784, ["mapID"] = 2248, ["storyline"] = { 78289, 78290, 78291, 78292, 78293, 78294 }, ["description"] = "Durzan looks hale and hearty again. That moss packs a real punch. I have a sense that he's ready to go. I just wish we had more time. I have so many questions. But the greatest of those questions will be answered when he reaches the peak. We shouldn't send him up there alone. But I think he trusts you to take him.", ["objectivesText"] = "Accompany Durzan to Belzt on Thunderhead Peak. Progress: We'll be watching from here. I truly hope Belzt is up there waiting.", ["rewardGold"] = 289300, ["rewardXP"] = 9515, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 180 }, { ["id"] = 2815, ["amount"] = 205 }, { ["id"] = 2897, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 211740, ["x"] = 0.599333, ["y"] = 0.302 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 211740, ["x"] = 0.599333, ["y"] = 0.302 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.599333, ["y"] = 0.302 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78293 }, ["questLines"] = { { ["id"] = 5509, ["name"] = "Rambleshire", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
