[78319] = { ["id"] = 78319, ["name"] = "The Superbloom", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78319 }, ["description"] = "Amirdrassil is growing and needs nourishment. Dear old Sprucecrown has a ritual to bloom life around the tree, but our enemies have taken note. We need all the help we can get. During the ritual, Sprucecrown will draw on the magic of the Dream to grow Dreamfruit. Consuming these will grant you amazing powers. Only a few of these powerful and delicious fruits can appear. Keep an eye out for them! Pray lend a hand, hero, and the dream will reward you aplenty.", ["objectivesText"] = "Participate in the Superbloom and consume the Dreamfruit that appear. Progress: Even the tallest of us needs a little help around the roots, now and then.", ["rewardXP"] = 2125, ["rewardItems"] = { 200073, 201921, 201922, 201923, 201924, 211389, 211411, 211413, 211414 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208474, ["x"] = 0.491333, ["y"] = 0.636667 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208474, ["x"] = 0.491333, ["y"] = 0.636667 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.491333, ["y"] = 0.636667 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
