[78348] = { ["id"] = 78348, ["name"] = "Friends in Low Places", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78226, 78228, 78244, 78348, 78352, 78353, 78620, 78621, 78624, 78630, 78658, 78659, 78671, 78948, 79156, 83503, 91868 }, ["description"] = "When we crashed, the nerubians were upon us in an instant. We would have lost nearly everyone we brought with us, had someone not intervened. I do not know who--or what--stepped in on our behalf. But if there is even a shred of hope that we have allies in this place then we must seize upon it and refuse to let go.", ["objectivesText"] = "Search the Breathing Pit for your mysterious protector.", ["rewardGold"] = 30900, ["rewardXP"] = 1325, ["rewardItems"] = { 109076 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 211699, ["x"] = 0.309, ["y"] = 0.446 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 215944, ["x"] = 0.33, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.309, ["y"] = 0.446 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 78350, 78384 }, ["questLines"] = { { ["id"] = 5520, ["name"] = "Friends in the Dark", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 6006, ["name"] = "Catch Up: War Within: Wrapper 3", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5520, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5520, ["questLineOrder"] = 11 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6006, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[78349] = { ["id"] = 78349, ["name"] = "Zul'Drak Zephyr - Reverse", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 78349 }, ["description"] = "Fly through the checkpoint rings marking the course.", ["objectivesText"] = "Glide through the rings.", ["rewardItems"] = { 188134, 191140 }, ["starts"] = { { ["x"] = 0.401, ["y"] = 0.395, ["mapID"] = 121, ["npcID"] = 212003 } }, ["ends"] = { { ["x"] = 0.401, ["y"] = 0.395, ["mapID"] = 121, ["npcID"] = 212003 } }, ["coords"] = { ["mapID"] = 121, ["x"] = 0.401, ["y"] = 0.395 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 212003, ["questTurnInID"] = 212003, ["questType"] = "standard" },
[78350] = { ["id"] = 78350, ["name"] = "Heroes Never Die", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78348, 78350, 78352, 78353, 78354, 78384, 78392, 78393, 79139, 83552 }, ["series"] = { 83552 }, ["description"] = "Damn it all! We were too hasty, and now my people are paying the price. We were fools to think the nerubians wouldn't be prepared for an incursion. Arathi soldiers are made of stern stuff, but even they will struggle to walk off an airship crash. I will keep everyone here safe. Please, go into the field and rescue as many people as you can.", ["objectivesText"] = "Aid twelve Wounded Aeroknights . Progress: Make haste, <class>. Time is of the essence.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["rewardItems"] = { 225521, 225524, 225530, 225540 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 211699, ["x"] = 0.309, ["y"] = 0.446 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 211699, ["x"] = 0.309, ["y"] = 0.446 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.309, ["y"] = 0.446 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 78630, 79573 }, ["questLines"] = { { ["id"] = 5520, ["name"] = "Friends in the Dark", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5520, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5520, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[78352] = { ["id"] = 78352, ["name"] = "For Naught, So Vial", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78226, 78228, 78244, 78348, 78352, 78353, 78620, 78621, 78624, 78630, 78658, 78659, 78671, 78948, 79156, 83503, 91868 }, ["description"] = "Truthfully, I don't care what the nerubians are plotting. They are not the first upstart people seeking power, and they certainly won't be the last. The problem is how they're going about it. I fear that tampering with this Black Blood will threaten far more than the delicate ecosystems of Khaz Algar. We must make sure that they never return to this pit again. Their equipment is still strewn throughout the pit. Destroy as much of it as you can manage.", ["objectivesText"] = "Destroy 8 pieces of nerubian extracting equipment throughout the Breathing Pit. Progress: The nerubians fled when those aberrations began appearing en masse, but I imagine they will try to come back for their ill-advised treasures. We need to make sure they have nothing to come back for.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 215944, ["x"] = 0.33, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 215113, ["x"] = 0.358, ["y"] = 0.582 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.33, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 78348 }, ["questLines"] = { { ["id"] = 5520, ["name"] = "Friends in the Dark", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 6006, ["name"] = "Catch Up: War Within: Wrapper 3", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5520, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5520, ["questLineOrder"] = 11 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6006, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[78353] = { ["id"] = 78353, ["name"] = "Fear the Old Blood", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78226, 78228, 78244, 78348, 78352, 78353, 78620, 78621, 78624, 78630, 78658, 78659, 78671, 78948, 79156, 83503, 91868 }, ["description"] = "This is not exactly the place for a long talk, so I will be brief. These roots you see are part of something much greater than you know, and it is my job to protect them. If it isn't obvious to you already, this place is teeming with writhing Black Blood. If we do not act, it will spread deeper and further still. You want allies? Fine. Help me cleanse this place and protect these roots, and I will at least hear you out.", ["objectivesText"] = "Work to cleanse the Breathing Pit.", ["rewardGold"] = 292100, ["rewardXP"] = 10595, ["rewardItems"] = { 225545, 225546 }, ["rewardChoices"] = { 225545, 225546 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 215944, ["x"] = 0.33, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 215113, ["x"] = 0.358, ["y"] = 0.582 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.33, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 78348 }, ["questLines"] = { { ["id"] = 5520, ["name"] = "Friends in the Dark", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 6006, ["name"] = "Catch Up: War Within: Wrapper 3", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5520, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5520, ["questLineOrder"] = 11 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6006, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[78354] = { ["id"] = 78354, ["name"] = "A Guiding Thread", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78348, 78350, 78352, 78353, 78354, 78384, 78392, 78393, 79139, 83552 }, ["description"] = "<The words on the parchment appear burned, not written. A venomous tang singes your nose.> Blind and alone, you stumble in the dark. I offer you a thread to cling to. Follow it, should you wish to find your allies.", ["objectivesText"] = "Follow Spindle . Progress: State your business, lest I get peckish.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["rewardItems"] = { 225514, 225516, 225529, 225533 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 216213, ["x"] = 0.4888, ["y"] = 0.5104 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 207471, ["x"] = 0.556, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.4888, ["y"] = 0.5104 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 79139 }, ["questLines"] = { { ["id"] = 5520, ["name"] = "Friends in the Dark", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5520, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5520, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
