[78373] = { ["id"] = 78373, ["name"] = "The Dream Thanks You", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78373 }, ["description"] = "< Melsysra drops a slightly damp note into your hand.> <name>, your contributions to the dream are immeasurable. Please meet me at the Central Encampment, we have a reward we're excited to give you. - Amrymn", ["objectivesText"] = "Talk to Amrymn in the Central Encampment.", ["rewardItems"] = { 206960 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 211962, ["x"] = 0.496, ["y"] = 0.622 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208143, ["x"] = 0.502, ["y"] = 0.616 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.496, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
