[78379] = { ["id"] = 78379, ["name"] = "The Stench of Revenge", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Love is in the Air", ["expansion"] = 10, ["zoneID"] = 1519, ["mapID"] = 21, ["storyline"] = { 78379 }, ["series"] = { 78369, 78729 }, ["description"] = "We're never gonna see an end to this unless we take on the boss himself. Look, Apothecary Hummel is holed up in Shadowfang Keep with his cronies. He's working on a new batch of poisonous perfumes, and they'll knock out all of Stormwind if we let him finish his research. You go do what you do best, pal. Get in there and foil his schemes before we're all lavender-scented corpses.", ["objectivesText"] = "Speak to Snagglebolt to enter the Crown Chemical Co. battle and defeat Apothecary Hummel . Progress: You ready to see what Hummel is cooking? I guarantee you it's not as pretty as it smells.", ["rewardGold"] = 1123600, ["rewardXP"] = 400, ["rewardItems"] = { 49927 }, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 38066, ["x"] = 0.458, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 38066, ["x"] = 0.458, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 1519 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 78369 }, ["db2LabelIDs"] = { 3027 } },
[78381] = { ["id"] = 78381, ["name"] = "Dreams Unified", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78381 }, ["description"] = "Another incredible find, <name>! This half of a Spark of Dreams could prove useful in your crafting endeavors if you could unite it with a sister piece. Set out in search of another Splintered Spark of Dreams and combine them.", ["objectivesText"] = "Find another Splintered Spark of Dreams . Progress: Have you located another Splintered Spark of Dreams ?", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 206271, 208396, 210872 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208669, ["x"] = 0.498, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208669, ["x"] = 0.498, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 77283, 77887 }, ["questLines"] = { { ["id"] = 5510, ["name"] = "Spark of Dreams", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
[78383] = { ["id"] = 78383, ["name"] = "Strategic Edge", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78233, 78234, 78236, 78237, 78249, 78250, 78251, 78254, 78255, 78256, 78383, 79175, 79625, 80399 }, ["description"] = "To add insult to injury, they disarmed me. I'm not leaving without those blades! While we're looking, keep an eye out for any evidence of what's going on here. Anything that could give us an advantage against the nerubians. Something strange happened that provided us the opening to escape. I have a feeling that could be something we can exploit.", ["objectivesText"] = "Find Flynn's Blades and 3 nerubian intel from Kaheti forces in Rak-Zakaz. Progress: There must be something around here of value to the Weaver...", ["rewardGold"] = 292100, ["rewardXP"] = 10595, ["rewardItems"] = { 211870, 221031, 225363 }, ["rewardChoices"] = { 225357, 225362, 225363 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 220051, ["x"] = 0.63, ["y"] = 0.27 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 220051, ["x"] = 0.63, ["y"] = 0.27 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questTurnInID"] = 220051, ["questType"] = "standard", ["sourceQuests"] = { 78236 }, ["questLines"] = { { ["id"] = 5521, ["name"] = "Unraveling the Trapped", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5521, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5521, ["questLineOrder"] = 12 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[78384] = { ["id"] = 78384, ["name"] = "Chasing the Light", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78348, 78350, 78352, 78353, 78354, 78384, 78392, 78393, 79139, 83552 }, ["description"] = "Anduin survived that swarm. I do not doubt that for a moment. Even so, the nerubians are everywhere and he is just one man. Wherever he goes, wherever he is taken, I will find him. Find me any sign that he yet lives. That is all I need to follow him to Azeroth's end.", ["objectivesText"] = "Search for clues of Anduin's survival. Progress: You've returned. I trust you have news.", ["rewardGold"] = 292100, ["rewardXP"] = 10595, ["rewardItems"] = { 211774, 211775, 211783 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 211752, ["x"] = 0.302667, ["y"] = 0.44 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 211752, ["x"] = 0.302667, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.302667, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 78630, 79573 }, ["questLines"] = { { ["id"] = 5520, ["name"] = "Friends in the Dark", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5520, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5520, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[78385] = { ["id"] = 78385, ["name"] = "Small Dreamseeds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["description"] = ", we've noticed an increase of fertile dirt within the Dream. It's the perfect opportunity for new plants! Come talk to me so we can start planting some seeds. -", ["rewardItems"] = { 208066 }, ["starts"] = { { ["x"] = 0.597, ["y"] = 0.169, ["mapID"] = 2200, ["npcID"] = 211265 } }, ["ends"] = { { ["npcID"] = 211265, ["x"] = 0.596, ["y"] = 0.168, ["mapID"] = 2200 } }, ["coords"] = { ["mapID"] = 2200, ["x"] = 0.597, ["y"] = 0.169 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questGiverID"] = 211265, ["questType"] = "standard" },
[78386] = { ["id"] = 78386, ["name"] = "Emerald Reawakening", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78386 }, ["description"] = "< Melsysra drops a slightly damp note into your hand.> <name>, we found a way to bring creatures into the dream. Speak to me if you'd like to know more! - Elianna", ["objectivesText"] = "Talk to Elianna in the Central Encampment.", ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 211962, ["x"] = 0.496, ["y"] = 0.622 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 211209, ["x"] = 0.502, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.496, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
