[78392] = { ["id"] = 78392, ["name"] = "The Tangled Web", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78348, 78350, 78352, 78353, 78354, 78384, 78392, 78393, 79139, 83552 }, ["description"] = "Make no mistake--I have no intention of sending you off to skitter about in the dark like a freshly-hatched beetle. It wouldn't do to have my little morsel snatched up by a starving cave borer. You must educate yourself, my dear. Your allies have found themselves ensconced in a torrid tapestry. Only by familiarizing yourself with its erstwhile architects can you hope to reclaim them. Luckily for you, I have made some of my personal resources available to you.", ["objectivesText"] = "Peruse the Weaver's archives. Progress: Haven't you finished yet? Really, the archives' design is quite elegant. Just tap and listen. Even a spindly thing like you can figure it out, I am sure.", ["rewardGold"] = 225600, ["rewardXP"] = 7945, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 207471, ["x"] = 0.556, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 207471, ["x"] = 0.556, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 78354 }, ["questLines"] = { { ["id"] = 5520, ["name"] = "Friends in the Dark", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5520, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5520, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[78393] = { ["id"] = 78393, ["name"] = "A Seeming Respite", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78348, 78350, 78352, 78353, 78354, 78384, 78392, 78393, 79139, 83552 }, ["description"] = "You have endured quite the evening since your ill-fated little ship ride, haven't you? Worry not, little morsel. You will find that my friends here are most accommodating, even to someone with your predilections--as strange as they may be. Please, take a moment to explore. Avail yourself of my many amenities. With luck, you will find some sorely-needed rest. ...Oh, but do take care not to move about too quickly. Sudden movements, I'm sure you understand.", ["objectivesText"] = "Explore the Lair of the Weaver. Progress: There is no need to be afraid! I am almost certain my companions will not eat you.", ["rewardGold"] = 232300, ["rewardXP"] = 7945, ["rewardCurrencies"] = { { ["id"] = 3002, ["amount"] = 2500 } }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 207471, ["x"] = 0.556, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 207471, ["x"] = 0.556, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 78354 }, ["questLines"] = { { ["id"] = 5520, ["name"] = "Friends in the Dark", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5520, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5520, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[78398] = { ["id"] = 78398, ["name"] = "A Dash of Minerals...", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77677, 77697, 77711, 77762, 78398 }, ["description"] = "I think we have a chance with this one, <name>. But we'll need to begin revitalizing the soil if we want to see this plant flourish. Head to the Eye of Ysera and harvest fish bones from the Fathomless Lurkers in the depths of the water. They're rich in minerals and degrade easily. It won't replenish the soil on its own, but it's a great start.", ["objectivesText"] = "Collect Fish Bones from Fathomless Lurkers. Progress: Did you have a chance to pick up what I asked for? This plant won't thrive without it.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 210457, 210774 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208337, ["x"] = 0.496, ["y"] = 0.628 }, { ["mapID"] = 2200, ["npcID"] = 209571, ["x"] = 0.486, ["y"] = 0.68 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 209571, ["x"] = 0.486, ["y"] = 0.68 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.496, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 77677 }, ["questLines"] = { { ["id"] = 5477, ["name"] = "A Mix of Hope, Care, and Patience", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
[78421] = { ["id"] = 78421, ["name"] = "The Power of Dreams", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14643, ["storyline"] = { 78421 }, ["description"] = "It seems that the fabric of the Emerald Dream itself is rejecting the invaders, leaving behind shadows of their dreams in the form of these Essences. So close to Amirdrassil, even your own actions are leaving behind ephemeral echoes of power. With enough time, perhaps we can use these echoes to awaken their strength and turn it against Fyrakk himself. Defeat the invaders wherever you find them and return to me when you have gathered enough of the Dream's power.", ["objectivesText"] = "Gather Echoed Ephemera and the Dreams of the Invaders of Amirdrassil. Progress: The Dream has many layers, some quite fragile. I worry that even the defenders' presence will change the unchanging land.", ["rewardGold"] = 929400, ["rewardItems"] = { 210470, 210472, 210473, 210474, 210475, 210494 }, ["starts"] = { { ["npcID"] = 210039 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14643 } }, ["questGiverID"] = 210039, ["questType"] = "raid", ["sourceQuests"] = { 78355 } },
[78427] = { ["id"] = 78427, ["name"] = "Great Crates!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78427 }, ["description"] = "The assault on the Dream grows ever stronger. We are in desperate need of trade goods and supplies to support the defense effort. Even just one crate could make the difference on the front line. Vashonir can assist you with packing the shipments. Then bring the shipment to me. Elune watch over you, defender of the Dream.", ["objectivesText"] = "Pack 1 Shipment of Goods with Vashonir in the Central Encampment. Progress: Vashonir will assist in preparing the shipments for you.", ["rewardItems"] = { 188658, 189143, 190311, 190312, 190313, 190314, 190316, 190321, 190327, 190329, 190394, 190395, 190396, 191460, 191461, 191462, 191464, 191465, 191466, 191467, 191468, 191469, 191470, 191471, 191472, 192852, 192853, 192855, 192856, 192857, 192858, 192859, 192860, 192861, 192862, 192863, 192865, 192866, 192867, 192868, 192869, 192870, 192871, 193050, 193208, 193210, 193211, 193213, 193214, 193215, 193216, 193217, 193218, 193222, 193223, 193224, 193251, 193255, 193258, 193259, 193922, 194123, 194124, 194730, 194966, 194967, 194968, 194969, 194970, 197742, 197745, 197746, 197747, 197748, 197756, 197757, 208067, 210041, 210050 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 211240, ["x"] = 0.525333, ["y"] = 0.624667 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 211240, ["x"] = 0.525333, ["y"] = 0.624667 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.525333, ["y"] = 0.624667 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 77283, 77887 } },
[78428] = { ["id"] = 78428, ["name"] = "Crate of the Art", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78428 }, ["description"] = "Our stockpiles have taken a grave hit, $p. We need to replenish our reserves as soon as possible, lest the enemy gain the upper hand. We will need far more supplies than we previously envisioned. Once again, Vashonir can assist you with packing the shipments. Please return to me with five crates of goods. Elune, watch over you.", ["objectivesText"] = "Pack 5 Shipments of Goods with Vashonir in the Central Encampment. Progress: Be sure to ask Vashonir to help you prepare the shipments!", ["rewardItems"] = { 188658, 190313, 190316, 190321, 190327, 190329, 190396, 191461, 191465, 191468, 191471, 192853, 192857, 192860, 192863, 192867, 192869, 193050, 193210, 193214, 193217, 193223, 193251, 193255, 193258, 193259, 193922, 194123, 194124, 194730, 194966, 194967, 194968, 194969, 194970, 197742, 197745, 197746, 197747, 197748, 197756, 197757, 208047, 210041 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 211240, ["x"] = 0.525333, ["y"] = 0.624667 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 211240, ["x"] = 0.525333, ["y"] = 0.624667 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.525333, ["y"] = 0.624667 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 78427 } },
[78429] = { ["id"] = 78429, ["name"] = "The Power of Dreams, Awoken", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14643, ["storyline"] = { 78429 }, ["description"] = "Are you ready, <name>? I will fuse the essences of their fiery dreams together for you. Focus the Echoed Ephemera you have collected to awaken the latent power within. Show Fyrakk that even he should fear the power of the Dream!", ["objectivesText"] = "Awaken the power within the Fused Essence .", ["rewardGold"] = 4647000, ["rewardItems"] = { 210494, 210498 }, ["starts"] = { { ["npcID"] = 210039 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14643 } }, ["questGiverID"] = 210039, ["questType"] = "raid", ["sourceQuests"] = { 78421 } },
[78430] = { ["id"] = 78430, ["name"] = "Mean Green Infusion Machine", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78430 }, ["description"] = "Pleased to meet you. I am Elianna , a Dream Researcher. A strange phenomenon has recently been detected in the Dream. Fragments of dream magic are being left behind by the creatures here. I'm curious to know the effects of such magic in concentrated doses. But I need someone to extract it for me. There are some problematic lashers and podlings to the south of here. Several of them should be enough for a lesser infusion.", ["objectivesText"] = "Kill 6 podlings and lashers in the Emerald Dream . Progress: Have you brought me enough Dream energy?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 205160 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 211209, ["x"] = 0.502, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 211209, ["x"] = 0.502, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 78386 } },
[78431] = { ["id"] = 78431, ["name"] = "Green Dream Team", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78431 }, ["description"] = "Most interesting! I was able to concentrate the Dream energy you brought me. With this, we can perform the infusion! Go ahead, I'll watch.", ["objectivesText"] = "Perform a Lesser Dream Infusion . Progress: Go on! I want to see you infuse Rithro.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 205160, 210776 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 211209, ["x"] = 0.502, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 211209, ["x"] = 0.502, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 78430 } },
