[78444] = { ["id"] = 78444, ["name"] = "A Worthy Ally: Dream Wardens", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78444 }, ["description"] = "So much change to that which should be unchanging... Rarely has the Dream seen such turmoil. It is meant to be a place of peace. Of life. Champion, we need all the help we can get. I bid you go forth and bring aid to the expanse of the Dream. I have no doubt the Dream will share its plenty with you in return.", ["objectivesText"] = "Aid the Dream Wardens and their allies throughout the Emerald Dream . Progress: Do take some time to stop and smell all that blooms throughout the Dream. It will enrich your life.", ["rewardItems"] = { 208396, 210225, 210421, 210872, 211416 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208143, ["x"] = 0.502, ["y"] = 0.616 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208143, ["x"] = 0.502, ["y"] = 0.616 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.616 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 77283, 77887 }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
[78446] = { ["id"] = 78446, ["name"] = "Aiding the Accord: Superbloom", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70750, 71232, 72068, 72373, 72374, 72375, 72585, 75259, 75859, 75860, 75861, 77254, 77976, 78446, 78447, 78861, 80385, 80386, 80388, 80389 }, ["description"] = "As life blooms within the Emerald Dream, the budding World Tree Amirdrassil blooms with it. The Ancient Sprucecrown's ritual empowers mighty life energies all around the tree, encouraging its growth. The more hands there to help protect and nourish Amirdrassil, the better its bloom will be! Please lend your aid to Sprucecrown on his journey.", ["objectivesText"] = "Travel to the Emerald Dream and assist Sprucecrown in creating a Superbloom. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles. Progress: I do hope you don't suffer from allergies.", ["rewardXP"] = 2125, ["rewardItems"] = { 200073, 201921, 201922, 201923, 201924, 206353, 208181, 210412, 211389, 211411, 211413, 211414 }, ["starts"] = { { ["x"] = 0.507, ["y"] = 0.58, ["mapID"] = 2112, ["npcID"] = 196499 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.5605 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questGiverID"] = 196499, ["questType"] = "standard", ["sourceQuests"] = { 71232, 72366 }, ["questLines"] = { { ["id"] = 1367, ["name"] = "Dragon Isles Emissary", ["orderIndex"] = 13, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 201, ["title"] = "Dragonflight", ["questLineID"] = 1367, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 3026 }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
[78447] = { ["id"] = 78447, ["name"] = "Aiding the Accord: Emerald Bounty", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70750, 71232, 72068, 72373, 72374, 72375, 72585, 75259, 75859, 75860, 75861, 77254, 77976, 78446, 78447, 78861, 80385, 80386, 80388, 80389 }, ["description"] = "The Emerald Dream suffers at the forces of the Incarnate Fyrakk. In its turmoil, some of its seeds have trouble taking root. In exploring the Dream, I am certain you shall collect some special seeds. Plant them in soil and nourish them into a bloom, and I hear they will share bountiful gifts with you. Go forth and help life blossom in the Emerald Dream!", ["objectivesText"] = "Travel to the Emerald Dream and plant 3 Dreamseeds of any quality in Emerald Bounty soil. Dreamseeds can be acquired from most activities in the Dream. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles. Progress: I wonder what gifts a flower can bestow?", ["rewardXP"] = 2125, ["rewardItems"] = { 200073, 201921, 201922, 201923, 201924, 208181 }, ["starts"] = { { ["x"] = 0.507, ["y"] = 0.58, ["mapID"] = 2112, ["npcID"] = 196499 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.5605 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questGiverID"] = 196499, ["questType"] = "standard", ["sourceQuests"] = { 71232, 72366 }, ["questLines"] = { { ["id"] = 1367, ["name"] = "Dragon Isles Emissary", ["orderIndex"] = 14, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 201, ["title"] = "Dragonflight", ["questLineID"] = 1367, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 3026 }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
