[78457] = { ["id"] = 78457, ["name"] = "Stones of Dornogal", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 78457, 78459, 78460, 78461, 78462, 78463, 78464, 78468, 78470, 78471, 79553, 79701, 79721 }, ["description"] = "I am Merrix , Councilward of Dornogal. I appreciate your aid--especially in light of the fraught nature of your arrival. You must forgive Stormward Baelgrim. Being suspicious is part of his directive. A formal discussion of our situation is warranted. If you wish to strike back at the nerubians, as we do, meet us at the Foundation Hall. Baelgrim and I need to review the data so far. In the meantime, you are my guest. Take my ring. It will allow you to access Dornogal's amenities.", ["objectivesText"] = "Meet with various earthen citizens in Dornogal. Progress: The attack seems concentrated on the Coreway. The rest of the city is secure, but we should ready ourselves for anything.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 216697 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 217854, ["x"] = 0.295, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 217861, ["x"] = 0.4, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.295, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 78460 }, ["questLines"] = { { ["id"] = 5525, ["name"] = "Earthen Fissures", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5525, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5525, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[78459] = { ["id"] = 78459, ["name"] = "State of the Union", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 78459, 78461, 78462, 78529, 78530, 78531, 78532, 78533, 78544, 78545, 78546, 78704, 78705, 78706, 78761, 78837, 79105, 79106, 80022, 80321, 80334, 80434, 91864 }, ["description"] = "I hate to admit it, but we have been caught unprepared by the nerubians. Our processes focused on sustaining Dornogal and our declining population. Stormward Baelgrim's stalwart pride has kept him and the Stormriders capable fighters, but they are already stretched thin, and they are not builders. The Coreway's damage surpasses our ability to fix it. But... that was not always so. I suppose if you wish to understand, you must learn more about us.", ["objectivesText"] = "Learn from Merrix about the Council of Dornogal. Progress: So much has been lost.", ["rewardGold"] = 30900, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 217861, ["x"] = 0.4, ["y"] = 0.258 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 217861, ["x"] = 0.4, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.258 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 78457, 78468 }, ["questLines"] = { { ["id"] = 5525, ["name"] = "Earthen Fissures", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 6008, ["name"] = "Catch Up: War Within: Wrapper 2", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5525, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5525, ["questLineOrder"] = 3 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6008, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339, ["db2QuestHubAreaPoiID"] = 7898 },
[78460] = { ["id"] = 78460, ["name"] = "Hypocenter", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 78457, 78459, 78460, 78461, 78462, 78463, 78464, 78468, 78470, 78471, 79553, 79701, 79721 }, ["description"] = "I have failed my people. The Coreway is impassible. Dornogal's lifeline to the Ringing Deeps has been severed as has the path beyond. The nerubians will get their comeuppance. It is my edict as it is my will. I will ascertain if the Councilward yet functions and bring him to the Archive. Speaker Brinthe should be there, titans willing. But Oathsworn citizens are still in peril. If you wish to ally with us, clear the debris here and help our survivors. I will meet you at the Archive.", ["objectivesText"] = "Clear debris and rescue earthen on the way to the Archive. Progress: The Archive looks intact, fortunately. We must keep it that way at all costs.", ["rewardGold"] = 154900, ["rewardXP"] = 4760, ["rewardItems"] = { 217610 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 217852, ["x"] = 0.362, ["y"] = 0.645 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 217853, ["x"] = 0.296, ["y"] = 0.595333 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.362, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 78536 }, ["questLines"] = { { ["id"] = 5525, ["name"] = "Earthen Fissures", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5525, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5525, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[78461] = { ["id"] = 78461, ["name"] = "The Fourth Seat", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 78459, 78461, 78462, 78529, 78530, 78531, 78532, 78533, 78544, 78545, 78546, 78704, 78705, 78706, 78761, 78837, 79105, 79106, 80022, 80321, 80334, 80434, 91864 }, ["description"] = "With me da' and Anduin weakened and Alleria nowhere to be found, it's up to us, <name>, to clear the way for Thrall an' Jaina's army if we hope tae strike back at the nerubians an' Xal'atath. But we cannae get to the nerubians without the Coreway. An' we cannae repair the Coreway without the earthen's help. If Merrix thinks this Adelgonn an' her \"Unbound\" are the only ones that can fix the Coreway, then we need tae find her. Time tae sharpen me smile an' put on me diplomat hat. Are ye with me, <name>?", ["objectivesText"] = "Find Adelgonn in Freywold Village in the Isle of Dorn . Progress: If you are with Baelgrim, then the Council and Oathsworn must have accepted you onto our land.", ["rewardGold"] = 30900, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 217864, ["x"] = 0.405, ["y"] = 0.259 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 217879, ["x"] = 0.418, ["y"] = 0.726 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.405, ["y"] = 0.259 }, ["mapCandidates"] = { ["npc"] = { 2248, 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 78459 }, ["questLines"] = { { ["id"] = 5525, ["name"] = "Earthen Fissures", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 6008, ["name"] = "Catch Up: War Within: Wrapper 2", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5525, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5525, ["questLineOrder"] = 3 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6008, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248, ["db2QuestHubAreaPoiID"] = 7898 },
[78462] = { ["id"] = 78462, ["name"] = "Echoes of Compassion", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78459, 78461, 78462, 78529, 78530, 78531, 78532, 78533, 78544, 78545, 78546, 78704, 78705, 78706, 78761, 78837, 79105, 79106, 80022, 80321, 80334, 80434, 91864 }, ["description"] = "The last thing I expected today was to see Baelgrim--much less receive his help. But I guess since the Coreway was damaged, he has no choice. I... do not know how to compute this. It is only logical to accept it. < Adelgonn begins crushing the fungarian flesh roughly in her stone hands. It becomes a masticated pulp disturbingly quickly.> Here. Mix this with mud and apply it to the injured.", ["objectivesText"] = "Heal 5 Earthen denizens in Freywold Village. Progress: We've fought off animals and elementals before, but nerubians? My people are artisans and miners--not warriors.", ["rewardGold"] = 154900, ["rewardXP"] = 4760, ["rewardItems"] = { 219796 }, ["rewardChoices"] = { 219796, 219797 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 217879, ["x"] = 0.418, ["y"] = 0.726 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 217879, ["x"] = 0.418, ["y"] = 0.726 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.726 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78463, 79553 }, ["questLines"] = { { ["id"] = 5525, ["name"] = "Earthen Fissures", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 6008, ["name"] = "Catch Up: War Within: Wrapper 2", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5525, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5525, ["questLineOrder"] = 3 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6008, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[78463] = { ["id"] = 78463, ["name"] = "Building Blocks", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78457, 78459, 78460, 78461, 78462, 78463, 78464, 78468, 78470, 78471, 79553, 79701, 79721 }, ["description"] = "The quarry is overrun with fungarians, all of the mining tunnels are collapsed, and we do not have time to clear them out and rebuild! However, I did spy a good amount of ore on the ground on the way here. It would be a start at repairing the Coreway but... < Baelgrim sighs and grimly looks at the injured Unbound earthen.> I am needed here. With Adelgonn's people. My people. Will you gather the ore in my stead?", ["objectivesText"] = "Collect 20 Glittering Ore in The Orecreg. Progress: Collect as much ore as you can. The Coreway is still my priority, but these injured need immediate help.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 211962 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 217881, ["x"] = 0.418, ["y"] = 0.728 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 217881, ["x"] = 0.418, ["y"] = 0.728 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.728 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78464 }, ["questLines"] = { { ["id"] = 5525, ["name"] = "Earthen Fissures", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5525, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5525, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[78464] = { ["id"] = 78464, ["name"] = "Delve into the Earth", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78457, 78459, 78460, 78461, 78462, 78463, 78464, 78468, 78470, 78471, 79553, 79701, 79721 }, ["description"] = "The nerubian attack, your meteoric fall... And now Baelgrim is here? Baelgrim needs more hands for his Coreway, but I couldn't help even if I wanted to. My people are dying as we speak. Some were abducted by the nerubians during the attack. You're not the first outlander I've met. A small fellow, like Moira, arrived here earlier and wasted no time following the nerubians. He took the path west to a nearby cave. I would be in your debt if you found my people.", ["objectivesText"] = "Complete the Earthcrawl Mines delve near Freywold Village. Progress: The mines were always dangerous even when the Stonebound worked them. Be careful.", ["rewardGold"] = 619600, ["rewardXP"] = 11895, ["rewardItems"] = { 219783, 219784, 219785, 219786, 219787, 219788, 219789, 219790, 219792 }, ["rewardChoices"] = { 219783, 219784, 219785, 219786, 219787, 219788, 219789, 219790, 219792 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 217879, ["x"] = 0.418, ["y"] = 0.726 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 217879, ["x"] = 0.418, ["y"] = 0.726 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.726 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78461 }, ["questLines"] = { { ["id"] = 5525, ["name"] = "Earthen Fissures", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5525, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5525, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[78465] = { ["id"] = 78465, ["name"] = "Golgrin's Reach", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78465, 78467, 79213, 79716, 83081, 83082, 83083, 83084, 83087 }, ["description"] = "Now that we have the opals, we can meet Brinthe in Golgrin's Reach. She said there's a project she's workin' on there she wants me tae help with. I wonder what it is?", ["objectivesText"] = "Meet Dagran at Golgrin's Reach in the Isle of Dorn .", ["rewardGold"] = 30300, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 225451, ["x"] = 0.448, ["y"] = 0.644 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 225453, ["x"] = 0.616, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.644 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 83081, 83082 }, ["questLines"] = { { ["id"] = 5634, ["name"] = "Hidden Edicts", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[78467] = { ["id"] = 78467, ["name"] = "Charge for a Charge", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78465, 78467, 79213, 79716, 83081, 83082, 83083, 83084, 83087 }, ["description"] = "I am pleased Dagran has brought you here. I need help with a dangerous task. I used Dagran's opals to repair the titan console we recently recovered from this site. The Oathsworn have long wanted to learn more about the titans and restore records unreachable in the Archive--or from before its construction. This console may hold some answers if we can bring it back online. Take this device I have made. It will lead you to titan power cells we can use to power it on now that it is restored.", ["objectivesText"] = "Collect 3 Power Cells in Golgrin's Reach. Progress: Without power, we will not be able to bring the console online.", ["rewardGold"] = 292100, ["rewardXP"] = 9515, ["rewardItems"] = { 11566, 65918, 65944, 65968, 65991, 66007, 131617, 174292, 175474, 175475, 175476, 175477, 177053, 178156, 179942, 182180, 184948, 184949, 184950, 184951, 184952, 184953, 184954, 184955, 184956, 186201, 186205, 186206, 187329, 187330, 187331, 187467, 194347, 194348, 194349, 194380, 198048, 198059, 200453, 204075, 204673, 204732, 204735, 204736, 204744, 204745, 204760, 204762, 204765, 204766, 204768, 204770, 204773, 204774, 204776, 204780, 204782, 204783, 204787, 204789, 204896, 204898, 204901, 215177, 215179, 215180, 239607 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 225478, ["x"] = 0.616, ["y"] = 0.702 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 225478, ["x"] = 0.616, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.702 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78465 }, ["questLines"] = { { ["id"] = 5634, ["name"] = "Hidden Edicts", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[78468] = { ["id"] = 78468, ["name"] = "The Archive", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 78457, 78459, 78460, 78461, 78462, 78463, 78464, 78468, 78470, 78471, 79553, 79701, 79721 }, ["description"] = "The memory gem you recovered is what its name suggests. It contains an earthen's memories, directives, and a hard coding of our Edicts. This building, the Archive, is the nexus of our civilization. Here, memories are cycled, catalogued, and stored at the end of an earthen's scheduled rotation. With the codex I have invented, we can access one or two memories from a memory gem. Take it, and read the memory gem you found.", ["objectivesText"] = "Use the Prismatic Codex to view the Memory Gem. Then, return the Memory Gem to the Archival Repository in The Archive. Progress: The operating instructions are simple: insert the gem into the device, and a memory will play.", ["rewardGold"] = 153400, ["rewardXP"] = 4760, ["rewardItems"] = { 204076, 221751, 224784, 229354, 239118, 244865, 248651 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 217857, ["x"] = 0.295, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 217857, ["x"] = 0.295, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.295, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 78460 }, ["questLines"] = { { ["id"] = 5525, ["name"] = "Earthen Fissures", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5525, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5525, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[78469] = { ["id"] = 78469, ["name"] = "Prairie Fever", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78469, 79691, 79692, 79703 }, ["description"] = "I was supposed to see Kodun earlier, but I'm as petrified as unliving stone. The attack on the village was... paralyzing. < Hreka takes a deep breath and focuses on the shape of another jar.> Could you do me a favor and deliver those jars to Kodun ? He's a stone's throw away in the village pottery shop. I must finish this piece before the clay dries.", ["objectivesText"] = "Examine and then deliver Hreka 's pottery jars to Kodun in Freywold Village. Progress: Are you one of the newcomers from the beach crash?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 217961, ["x"] = 0.42, ["y"] = 0.72 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 216094, ["x"] = 0.422, ["y"] = 0.732 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.72 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78536 }, ["questLines"] = { { ["id"] = 5601, ["name"] = "Hope, An Anomaly", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[78470] = { ["id"] = 78470, ["name"] = "The Proscenium", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78457, 78459, 78460, 78461, 78462, 78463, 78464, 78468, 78470, 78471, 79553, 79701, 79721 }, ["description"] = "The nerubians are attackin' the earthen again. We must follow that swarm! I fear we are outnumbered, but if the earthen can come together and stand with us... We may just have a chance.", ["objectivesText"] = "Journey to the Proscenium in the Isle of Dorn .", ["rewardGold"] = 30900, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 217878, ["x"] = 0.418, ["y"] = 0.726 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 217898, ["x"] = 0.564667, ["y"] = 0.506667 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.726 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78462 }, ["questLines"] = { { ["id"] = 5525, ["name"] = "Earthen Fissures", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5525, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5525, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[78471] = { ["id"] = 78471, ["name"] = "Convergence", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78457, 78459, 78460, 78461, 78462, 78463, 78464, 78468, 78470, 78471, 79553, 79701, 79721 }, ["description"] = "We know the nerubians are in league with Xal'atath. An' we have a fair idea why they attacked us--and Dalaran. They seem bent on destroying the earthen--even kickin' 'em when they're down. But why? Is it because the Coreway is the key an' destroyin' it was nae enough? Maybe what we're doin' here, repairin' the Coreway, is just what they dunnae want us to do. We should go back to Dornogal an try to piece this together.", ["objectivesText"] = "Return to Foundation Hall in Dornogal.", ["rewardGold"] = 29200, ["rewardXP"] = 1190, ["rewardItems"] = { 219750, 219751, 219752, 219753 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 125 }, { ["id"] = 2897, ["amount"] = 2500 } }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 217898, ["x"] = 0.564667, ["y"] = 0.506667 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 217905, ["x"] = 0.402, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.564667, ["y"] = 0.506667 }, ["mapCandidates"] = { ["npc"] = { 2248, 2339 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 79701, 79721 }, ["questLines"] = { { ["id"] = 5525, ["name"] = "Earthen Fissures", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5525, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5525, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[78473] = { ["id"] = 78473, ["name"] = "The Power of Dreams, Lost", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14643, ["storyline"] = { 78473 }, ["description"] = "You lost the Incandescent Essence ? To be so careless with such a precious thing... I can grant you another.", ["objectivesText"] = "Awaken the power within the Fused Essence .", ["rewardItems"] = { 210494, 210498 }, ["starts"] = { { ["npcID"] = 210039 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14643 } }, ["questGiverID"] = 210039, ["questType"] = "raid", ["sourceQuests"] = { 78429 } },
