[78529] = { ["id"] = 78529, ["name"] = "Violent Impact", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78529, 78530, 78531, 78532, 78533, 78534, 78535, 78536, 80334, 83548 }, ["description"] = "<Your vision swims as you slowly regain consciousness. Distant shouts and screams echo in your ringing ears. The last thing you remember is Dalaran, the great, floating city of magic, plummeting to the earth--then nothing but darkness. Mixed in with sounds of shouting and battle, you hear a strange, insectoid chittering. The nerubians were waiting for you. You must rejoin the fight, but first you need to free yourself from the crushing weight of the rubble piled atop you.>", ["objectivesText"] = "Climb out of the rubble and find your surviving leaders.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["x"] = 0.288, ["y"] = 0.545, ["mapID"] = 2248, ["npcID"] = 217930 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 211993, ["x"] = 0.294, ["y"] = 0.55 }, { ["mapID"] = 2248, ["npcID"] = 211994, ["x"] = 0.294, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.294, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questGiverID"] = 217930, ["questType"] = "standard", ["sourceQuests"] = { 80321 }, ["questLines"] = { { ["id"] = 5539, ["name"] = "Breaking Point", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5638, ["name"] = "Dalaran Intro", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 6008, ["name"] = "Catch Up: War Within: Wrapper 2", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5539, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5539, ["questLineOrder"] = 2 }, { ["id"] = 261, ["title"] = "Expansion Intro Skip", ["questLineID"] = 5638, ["questLineOrder"] = 0 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6008, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[78530] = { ["id"] = 78530, ["name"] = "Slay the Saboteurs", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78529, 78530, 78531, 78532, 78533, 78534, 78535, 78536, 80334, 83548 }, ["series"] = { 83548 }, ["description"] = "The nerubians are everywhere, <name>. There are too many for all of them to be solely crash survivors. I've seen others burrowing up from the ground. This Queensguard Zirix was laying in wait here to overwhelm us. Let them know we are not easy prey. Cut them down!", ["objectivesText"] = "Kill 12 nerubians. Progress: We need to thin their numbers if we are to survive this.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 211994, ["x"] = 0.294, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 211994, ["x"] = 0.294, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.294, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78529 }, ["questLines"] = { { ["id"] = 5539, ["name"] = "Breaking Point", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 6008, ["name"] = "Catch Up: War Within: Wrapper 2", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5539, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5539, ["questLineOrder"] = 2 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6008, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[78531] = { ["id"] = 78531, ["name"] = "Urgent Recovery", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78529, 78530, 78531, 78532, 78533, 78534, 78535, 78536, 80334, 83548 }, ["description"] = "We survived mostly unharmed. Not everyone was so lucky. Many who were in Dalaran when it went down are unaccounted for. They will need our help. Search the battlefield for survivors. Help them in any way you can. We need everyone up and fighting!", ["objectivesText"] = "Aid 7 survivors of the Dalaran crash. Progress: We must save everyone we can.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 211993, ["x"] = 0.294, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 211993, ["x"] = 0.294, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.294, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78529 }, ["questLines"] = { { ["id"] = 5539, ["name"] = "Breaking Point", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 6008, ["name"] = "Catch Up: War Within: Wrapper 2", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5539, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5539, ["questLineOrder"] = 2 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6008, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[78532] = { ["id"] = 78532, ["name"] = "Erratic Artifacts", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78529, 78530, 78531, 78532, 78533, 78534, 78535, 78536, 80334, 83548 }, ["series"] = { 80334 }, ["description"] = "Dalaran housed many precious and powerful relics. Many of them were damaged in the crash and are now malfunctioning. They must be destroyed! Take this scroll. I have stored a shattering spell within it. Read the words aloud and its magic will be unleashed. Report what you have done to Jaina when you are through. She will understand.", ["objectivesText"] = "Destroy 5 Damaged Arcane Relics. Progress: It pains me, but we have to destroy the malfunctioning relics!", ["rewardGold"] = 292100, ["rewardXP"] = 9515, ["rewardItems"] = { 211535 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 223166, ["x"] = 0.308, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 211994, ["x"] = 0.294, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.308, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78529 }, ["questLines"] = { { ["id"] = 5539, ["name"] = "Breaking Point", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 6008, ["name"] = "Catch Up: War Within: Wrapper 2", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5539, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5539, ["questLineOrder"] = 2 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6008, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[78533] = { ["id"] = 78533, ["name"] = "Secure the Beach", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78529, 78530, 78531, 78532, 78533, 78534, 78535, 78536, 80334, 83548 }, ["description"] = "Queensguard Zirix emerged from the ground and surprised Magni. He's near the farthest edge of the wreckage fighting off his swarm. Moira and I were trying to help, but we couldn't draw them away. Come with me. Magni needs our help!", ["objectivesText"] = "Find Magni and defeat Queensguard Zirix.", ["rewardGold"] = 292100, ["rewardXP"] = 9515, ["rewardItems"] = { 219754 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 212450, ["x"] = 0.295, ["y"] = 0.549 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 211859, ["x"] = 0.304, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.295, ["y"] = 0.549 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78530, 78531, 78532 }, ["questLines"] = { { ["id"] = 5539, ["name"] = "Breaking Point", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 6008, ["name"] = "Catch Up: War Within: Wrapper 2", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5539, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5539, ["questLineOrder"] = 2 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6008, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[78534] = { ["id"] = 78534, ["name"] = "To Dornogal", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78529, 78530, 78531, 78532, 78533, 78534, 78535, 78536, 80334, 83548 }, ["description"] = "You have brought death and destruction to our shores the likes of which has not been seen in millennia. But you have nerubian blood on your hands and a thraegar at your side. This is enough to earn my trust--for now. My Stormriders and I must return to our capital, Dornogal, and investigate what is likely an ongoing attack there. Fly with us. Our slipstream will allow you to soar through the skies with ease. I will send other Stormriders to collect your allies once it is safe for them to land.", ["objectivesText"] = "Meet Baelgrim in Dornogal by following the Stormrider's Slipstream. Most services in Dornogal will be unavailable during this quest. Progress: We need answers.", ["rewardGold"] = 292100, ["rewardXP"] = 9515, ["rewardItems"] = { 225239 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 211859, ["x"] = 0.304, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 216628, ["x"] = 0.335, ["y"] = 0.755 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.304, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 2248, 2339 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78533 }, ["questLines"] = { { ["id"] = 5539, ["name"] = "Breaking Point", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5539, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5539, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[78535] = { ["id"] = 78535, ["name"] = "They Come from Below", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 78529, 78530, 78531, 78532, 78533, 78534, 78535, 78536, 80334, 83548 }, ["description"] = "I do not yet know why you have come here, outlander. But you seem... efficient in killing nerubians. As are we, the Stormriders, vanguards of this isle. The nerubians are an ancient enemy. I would not be surprised if this Zirix knows and fears me, the Stormward. Even so, we could use your skill to help us protect Dornogal. I have a stormrook for you to ride. Mount up and help us rid our city of these insects!", ["objectivesText"] = "Mount the stormrook Lokren and slay nerubians in Dornogal. Most services in Dornogal will be unavailable during this quest.", ["rewardGold"] = 619600, ["rewardXP"] = 11895, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 216628, ["x"] = 0.335, ["y"] = 0.755 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 217852, ["x"] = 0.362, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.335, ["y"] = 0.755 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 78534 }, ["questLines"] = { { ["id"] = 5539, ["name"] = "Breaking Point", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5539, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5539, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[78536] = { ["id"] = 78536, ["name"] = "Impossible Odds", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 78529, 78530, 78531, 78532, 78533, 78534, 78535, 78536, 80334, 83548 }, ["description"] = "By the titans... The Coreway appears completely destroyed! It will take years, perhaps centuries, to remove the rubble and repair the damage the nerubians did to its inner structure, much less traverse to the world's core. More than that with the Stonebound gone... I must take a moment to decide what to do. Your friends have safely arrived. Speak to them, and stay out of my way. If we need you, I will let you know.", ["objectivesText"] = "Speak to Thrall. Progress: The Council must be appraised. There will be much to do...", ["rewardGold"] = 30900, ["rewardXP"] = 1190, ["rewardItems"] = { 219746, 219747, 219748, 219749 }, ["rewardCurrencies"] = { { ["id"] = 2897, ["amount"] = 2500 } }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 217852, ["x"] = 0.362, ["y"] = 0.645 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 217852, ["x"] = 0.362, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.362, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 78535 }, ["questLines"] = { { ["id"] = 5539, ["name"] = "Breaking Point", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5539, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5539, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[78538] = { ["id"] = 78538, ["name"] = "Group Effort", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 78538, 78539, 78540, 78541, 78542, 78543, 78544, 78545, 78546, 80022 }, ["description"] = "The Unbound have arrived with the equipment and resources needed to begin repairing the Coreway. This is a momentous occasion. One for the Archive! I would not say this to Adelgonn, but I see the titans' hands in it... And now it is time for me to exercise my directive! I have devised a plan for how to organize our workers most efficiently--and have also allocated supplies to welcome them. Take these orders to Adelgonn's workers so that they can begin in earnest. We will meet you there shortly.", ["objectivesText"] = "Distribute Merrix 's orders to 10 Unbound Workers around the Coreway. Progress: We must begin work at once.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 213271 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 217904, ["x"] = 0.4, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 212746, ["x"] = 0.36, ["y"] = 0.525 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 78471 }, ["questLines"] = { { ["id"] = 5540, ["name"] = "The First Blow", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5540, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5540, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[78539] = { ["id"] = 78539, ["name"] = "Lasting Repairs", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 78538, 78539, 78540, 78541, 78542, 78543, 78544, 78545, 78546, 80022 }, ["description"] = "With my Stormriders... inactive, Dornogal is undefended, save a handful of lay peacekeepers. If the nerubians attack us here again, Dornogal will fall--and all of us with it. It is imperative we draw them away from the city and take out their commander. We can and will make our own web and capture Zirix in it. I have a plan.", ["objectivesText"] = "Discuss the plan to attack the nerubians with Baelgrim . Progress: We cannot remain on the defense.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 222555, ["x"] = 0.359, ["y"] = 0.525 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 222555, ["x"] = 0.359, ["y"] = 0.525 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.359, ["y"] = 0.525 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 80022 }, ["questLines"] = { { ["id"] = 5540, ["name"] = "The First Blow", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5540, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5540, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[78540] = { ["id"] = 78540, ["name"] = "To the Meadery", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 78538, 78539, 78540, 78541, 78542, 78543, 78544, 78545, 78546, 80022 }, ["description"] = "Your archer friend is right. We must eliminate Zirix and his forces if the Coreway is to remain safe. Let us head to the Cinderbrew Meadery at once.", ["objectivesText"] = "Meet Baelgrim at the Cinderbrew Meadery.", ["rewardGold"] = 30900, ["rewardXP"] = 1190, ["rewardItems"] = { 2815, 2899, 2902, 3056, 224784, 229354, 237014 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 222555, ["x"] = 0.359, ["y"] = 0.525 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 212749, ["x"] = 0.752, ["y"] = 0.432 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.359, ["y"] = 0.525 }, ["mapCandidates"] = { ["npc"] = { 2248, 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 78539 }, ["questLines"] = { { ["id"] = 5540, ["name"] = "The First Blow", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5540, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5540, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[78541] = { ["id"] = 78541, ["name"] = "Lay the Trap", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78538, 78539, 78540, 78541, 78542, 78543, 78544, 78545, 78546, 80022 }, ["description"] = "With all these cinderbrew kegs here, this meadery would burn hotter than the Forgegrounds if they were all ignited. I surmise that's why Wenbrandt's kegs are made out of stout and strong ironwood--they do not break or catch fire easily. Luckily, we can start a reaction from the inside if we lead fuses into each of them. Those ropes the workers left around should work in a pinch.", ["objectivesText"] = "Connect 4 Rope Fuses to Sizzling Kegs. Progress: We need to get the cinderbrew kegs prepared.", ["rewardGold"] = 292100, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 212749, ["x"] = 0.752, ["y"] = 0.432 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 212749, ["x"] = 0.752, ["y"] = 0.432 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.752, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78540 }, ["questLines"] = { { ["id"] = 5540, ["name"] = "The First Blow", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5540, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5540, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[78542] = { ["id"] = 78542, ["name"] = "Evacuation Area", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78538, 78539, 78540, 78541, 78542, 78543, 78544, 78545, 78546, 80022 }, ["description"] = "Look, you can blow up my life's work if it is our only choice, but I will not put my workers in danger. This was the path we all chose, but I won't have them sacrifice themselves to fire or nerubians for it. Tell them that I said they need to get out of here immediately. And if a single one of them gets so much as chipped, the Council will have a lot to answer for!", ["objectivesText"] = "Evacuate 8 Unbound Meadworkers. Progress: If my workers cannot be kept safe, I am putting a stop to this plan.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 212750, ["x"] = 0.752, ["y"] = 0.432 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 212750, ["x"] = 0.752, ["y"] = 0.432 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.752, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78540 }, ["questLines"] = { { ["id"] = 5540, ["name"] = "The First Blow", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5540, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5540, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[78543] = { ["id"] = 78543, ["name"] = "Poking the Spider Nest", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78538, 78539, 78540, 78541, 78542, 78543, 78544, 78545, 78546, 80022 }, ["description"] = "The meadery is evacuated and the explosives are primed. It is time to bait the nerubians into our trap. Your compatriot is by the nerubian burrow north of here. She told me her directive is to keep watch over it in case the nerubians make a move before we are ready. So far they have not made a move and may now need... coaxing. Take a keg of cinderbrew to the burrow. Tossing it in should stir their \"nest.\" Rendezvous with us back at the Meadyard--quickly--after.", ["objectivesText"] = "Throw a Keg of Cinderbrew Mead into the nerubian burrow and then return to the Meadyard.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 212749, ["x"] = 0.752, ["y"] = 0.432 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 212756, ["x"] = 0.748, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.752, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78541, 78542 }, ["questLines"] = { { ["id"] = 5540, ["name"] = "The First Blow", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5540, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5540, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[78544] = { ["id"] = 78544, ["name"] = "Bring the Thunder", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78459, 78461, 78462, 78529, 78530, 78531, 78532, 78533, 78544, 78545, 78546, 78704, 78705, 78706, 78761, 78837, 79105, 79106, 80022, 80321, 80334, 80434, 91864 }, ["description"] = "The nerubians will strike out in anger and pride--which is exactly what we want. They will swarm the meadery soon, seeking to punish us for attacking their burrow. We will hold them here on the ground while you take to the skies. When Zirix appears to command his army, we will light the fuses. Wenbrandt scrounged together some supplies we can use to corral the nerubians. Set them up quickly, and then we will get you on a stormrook. Go!", ["objectivesText"] = "Hold off the nerubians at the Cinderbrew Meadery until Queensguard Zirix appears.", ["rewardGold"] = 619600, ["rewardXP"] = 11895, ["rewardItems"] = { 219755, 219756, 219757, 219758 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 212756, ["x"] = 0.748, ["y"] = 0.422 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 217849, ["x"] = 0.75, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.748, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78543 }, ["questLines"] = { { ["id"] = 5540, ["name"] = "The First Blow", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 6008, ["name"] = "Catch Up: War Within: Wrapper 2", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5540, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5540, ["questLineOrder"] = 4 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6008, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[78545] = { ["id"] = 78545, ["name"] = "Return to the Coreway", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78459, 78461, 78462, 78529, 78530, 78531, 78532, 78533, 78544, 78545, 78546, 78704, 78705, 78706, 78761, 78837, 79105, 79106, 80022, 80321, 80334, 80434, 91864 }, ["description"] = "We dealt a heavy blow to the nerubians. But Baelgrim... < Adelgonn pauses to compose herself.> He was infuriatingly rigid and we argued ceaselessly, but in the end... he was a defender of our people--all of them. Baelgrim sacrificed himself to vouchsafe the Isle of Dorn from the nerubians. Everyone needs to know that--and we can't let the nerubians force our hand like that again. Go back to Merrix in Dornogal. Tell him we will come soon. We just... need a moment here.", ["objectivesText"] = "Return to Merrix in Dornogal. Progress: How fares your sortie at the meadery?", ["rewardGold"] = 292100, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 217849, ["x"] = 0.75, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 217880, ["x"] = 0.32, ["y"] = 0.595 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.75, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 2248, 2339 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78544 }, ["questLines"] = { { ["id"] = 5540, ["name"] = "The First Blow", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 6008, ["name"] = "Catch Up: War Within: Wrapper 2", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5540, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5540, ["questLineOrder"] = 4 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6008, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[78546] = { ["id"] = 78546, ["name"] = "Recompense", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 78459, 78461, 78462, 78529, 78530, 78531, 78532, 78533, 78544, 78545, 78546, 78704, 78705, 78706, 78761, 78837, 79105, 79106, 80022, 80321, 80334, 80434, 91864 }, ["description"] = "We heard the echo of the explosion from here. I presume you have found victory, but your solitary arrival suggests not all is well. What happened?", ["objectivesText"] = "Speak to Adelgonn to inform Merrix of Baelgrim's fate. Progress: Tell me what happened.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 219760, 219761, 219762, 219763 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 125 }, { ["id"] = 2897, ["amount"] = 2500 } }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 217880, ["x"] = 0.32, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 217880, ["x"] = 0.32, ["y"] = 0.595 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.32, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 78545 }, ["questLines"] = { { ["id"] = 5540, ["name"] = "The First Blow", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 6008, ["name"] = "Catch Up: War Within: Wrapper 2", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5540, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5540, ["questLineOrder"] = 4 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6008, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[78555] = { ["id"] = 78555, ["name"] = "Underground and Overwhelmed", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78555, 78557, 78631, 78634, 78635, 78636, 78637, 78638, 78639, 78640, 78641, 78642, 78837, 78838, 78839, 79205, 79267, 80082, 80434, 83550 }, ["series"] = { 80434, 83550 }, ["description"] = "I've been away too long. The Machine Speakers are clearly not faring well here. Does the High Speaker know about this? Nerubian sabotage and gross negligence are a devastating combination. We need to get Ironhaul Station up and running as soon as possible. It's a vital link between the Ringing Deeps and the city up above. Please, $p, help our injured workers, collect any salvageable cargo, and restore safety to Ironhaul Station.", ["objectivesText"] = "Help Machine Speakers secure Ironhaul Station. Progress: Dead nerubian skitterlings, unexploded bombs, injured workers... what a mess.", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["rewardItems"] = { 216720 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212592, ["x"] = 0.4, ["y"] = 0.284 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212592, ["x"] = 0.4, ["y"] = 0.284 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.284 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 80434 }, ["questLines"] = { { ["id"] = 5533, ["name"] = "By Candlelight", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5533, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5533, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[78557] = { ["id"] = 78557, ["name"] = "Getting Off Track", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78555, 78557, 78631, 78634, 78635, 78636, 78637, 78638, 78639, 78640, 78641, 78642, 78837, 78838, 78839, 79205, 79267, 80082, 80434, 83550 }, ["description"] = "Speaker Brinthe acknowledged. Outlanders, there is work to do. One of our larger mine carts has derailed. It's blocking the station's main junction. My workers' productivity is impaired, and their functioning is suboptimal. The titans put us here to work, but my workers aren't all working. Could you go and get us back on track? Be careful. I can see you're made of flesh and bone. I don't want you to be crushed.", ["objectivesText"] = "Investigate the derailed mine cart in Ironhaul Station. Progress: As long as we stay loyal, hit our deadlines, and meet our quotas, everything will be fine. The gears keep grinding, and we keep working. Praise the Machine.", ["rewardGold"] = 292100, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 218290, ["x"] = 0.4, ["y"] = 0.282 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 218290, ["x"] = 0.4, ["y"] = 0.282 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.282 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 80434 }, ["questLines"] = { { ["id"] = 5533, ["name"] = "By Candlelight", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5533, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5533, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[78558] = { ["id"] = 78558, ["name"] = "Sholazar Spree", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 78558 }, ["description"] = "Fly through the checkpoint rings marking the course.", ["objectivesText"] = "Glide through the rings.", ["rewardItems"] = { 188134, 191140 }, ["starts"] = { { ["x"] = 0.794, ["y"] = 0.545, ["mapID"] = 119, ["npcID"] = 212666 } }, ["ends"] = { { ["x"] = 0.794, ["y"] = 0.545, ["mapID"] = 119, ["npcID"] = 212666 } }, ["coords"] = { ["mapID"] = 119, ["x"] = 0.794, ["y"] = 0.545 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 212666, ["questTurnInID"] = 212666, ["questType"] = "standard" },
