[78562] = { ["id"] = 78562, ["name"] = "Discarded and Broken", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78562, 78563, 78564 }, ["description"] = "You there! You're here to help, aren't you? The humming melody of the machines is changing, and I... I admit I am not ready. For so many years I served faithfully, and then... Well the important thing is that I'm ready to get to work again. But you see, my tools have all been broken and scattered about. If you could keep an eye out for them and bring them back to me, I would be in your debt.", ["objectivesText"] = "Collect Machinist Kittrin 's lost tools. Progress: A machinist is nothing without the tools of office.", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["rewardItems"] = { 210732, 210733, 210734 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212695, ["x"] = 0.461, ["y"] = 0.334 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212695, ["x"] = 0.461, ["y"] = 0.334 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.461, ["y"] = 0.334 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 78838, 79573 }, ["questLines"] = { { ["id"] = 5597, ["name"] = "Broken Tools", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214, ["db2QuestHubAreaPoiID"] = 7911 },
[78563] = { ["id"] = 78563, ["name"] = "The Weight of a World", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78562, 78563, 78564 }, ["series"] = { 78564 }, ["description"] = "My tools didn't randomly end up where you found them. They were placed there. By me. I had reached a point so low that I saw no alternative. The machines, the great work of my people, were never going to sing again. So why should I bother to keep them repaired? But now I see, and now, I understand! The last tool I need, I dropped it into the water, and it was eaten by a giant creature. I think that one might need a bit more force to return it to me.", ["objectivesText"] = "Collect Machinist Kittrin 's Calibrated Weight. Progress: Once I have all my tools back, I know that things will be right again.", ["rewardGold"] = 292100, ["rewardXP"] = 9920, ["rewardItems"] = { 210740 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212695, ["x"] = 0.461, ["y"] = 0.334 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212695, ["x"] = 0.461, ["y"] = 0.334 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.461, ["y"] = 0.334 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 78562 }, ["questLines"] = { { ["id"] = 5597, ["name"] = "Broken Tools", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[78564] = { ["id"] = 78564, ["name"] = "Reforged Purpose", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78562, 78563, 78564 }, ["series"] = { 78563 }, ["description"] = "That's all of them! Now, it's time to do my duty and recast these tools. Reforge them, and myself, into what I was meant to be: a proud machinist of the Ringing Deeps .", ["objectivesText"] = "Help Machinist Kittrin reforge and rededicate the tools. Progress: I'm ready to do my part once again. I just need to reforge these old tools.", ["rewardGold"] = 292100, ["rewardXP"] = 9920, ["rewardItems"] = { 223572 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 180 }, { ["id"] = 2902, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212695, ["x"] = 0.461, ["y"] = 0.334 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212695, ["x"] = 0.461, ["y"] = 0.334 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.461, ["y"] = 0.334 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 78563 }, ["questLines"] = { { ["id"] = 5597, ["name"] = "Broken Tools", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[78565] = { ["id"] = 78565, ["name"] = "Getaway to Scenic Grizzly Hills!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Love is in the Air", ["expansion"] = 10, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 78565 }, ["description"] = "Today's special is a magical getaway to the majestic forests of Northrend! Say, you're one of those adventurers, right? Listen, I need a favor. Could you pick me a few flowers from Grizzly Hills? I've got my hands full here, but there's someone I'd really like to give a bouquet to.", ["objectivesText"] = "Take the Scenic Getaway Portal to Grizzly Hills to pick a bouquet of flowers for Gabbo. Progress: My partner would really appreciate these flowers.", ["rewardGold"] = 319000, ["rewardXP"] = 1415, ["rewardItems"] = { 49927, 210719 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 212677, ["x"] = 0.342, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 212677, ["x"] = 0.342, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3027 } },
[78570] = { ["id"] = 78570, ["name"] = "Frayed Legacy", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78570, 78571, 78572, 78573, 78574 }, ["series"] = { 78571 }, ["description"] = "Keep true, <race>t. We of the Woldguard uphold an ancient promise to Freya to tend to these lands. Our edict is older than those wielded by the demagogues in Dornogal. Older than Dornogal itself. However, not all lands have been tended equally. The leader of our order was to care for the basin nearby but we've not heard from them in many cycles. I have sent a novice to investigate. Aid them and my order will be in your favor.", ["objectivesText"] = "Meet Igris at the Boskroot Basin on the Isle of Dorn .", ["rewardGold"] = 30000, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 212708, ["x"] = 0.416, ["y"] = 0.714 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 212700, ["x"] = 0.535, ["y"] = 0.698 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.416, ["y"] = 0.714 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78536 }, ["nextQuests"] = { 78571 }, ["questLines"] = { { ["id"] = 5512, ["name"] = "Boskroot of the Problem", ["orderIndex"] = 0, ["flags"] = 1 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[78571] = { ["id"] = 78571, ["name"] = "Mycomayhem", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78570, 78571, 78572, 78573, 78574 }, ["series"] = { 78570 }, ["description"] = "Freydrin was the leader of my order. I was sent here to assist them. I was too late. There is a darkness that haunts these woods, <race>s. These woods were Freydrin's home. It was her charge to tend to them, so given by the Keeper herself. And now she is gone and her woods run amok. Bring me the spores of these mayhemic menaces. Perhaps there is a way to cleanse this land yet.", ["objectivesText"] = "Collect 30 Boskroot Spores from fungarians in Boskroot Basin. Progress: Do you have them all?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 210845 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 212700, ["x"] = 0.535, ["y"] = 0.698 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 212700, ["x"] = 0.535, ["y"] = 0.698 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.698 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78570 }, ["questLines"] = { { ["id"] = 5512, ["name"] = "Boskroot of the Problem", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[78572] = { ["id"] = 78572, ["name"] = "Wold Memories", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78570, 78571, 78572, 78573, 78574 }, ["description"] = "Freydrin must have had some way of fending off the fungarians. Although there are few left in the countryside who still follow the Edicts, Freydrin was long a true believer. She would never have allowed these woods to reach this state while she held faith. We should take a look at her home in the woods. Perhaps there is something that may prove useful inside.", ["objectivesText"] = "Search Freydrin's home for help against the fungarians in Boskroot Basin. Progress: Looking through the Woldkeeper's things unnerves me. So many untold stories.", ["rewardGold"] = 30900, ["rewardXP"] = 1190, ["rewardItems"] = { 154874, 154875, 154894, 216858 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 212700, ["x"] = 0.535, ["y"] = 0.698 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 218333, ["x"] = 0.542, ["y"] = 0.652 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.698 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78571 }, ["questLines"] = { { ["id"] = 5512, ["name"] = "Boskroot of the Problem", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[78573] = { ["id"] = 78573, ["name"] = "Keeper's Aid", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78570, 78571, 78572, 78573, 78574 }, ["description"] = "Magical staff? Wards? What were you doing, Freydrin? <Igris ruminates briefly, her brow crinkling and eyes aglow. After a moment, she turns to you with a smile carved into her face.> I've got it! The life energy in this staff should overcome any mycotic corruptions in the wildlife here. Then you return them to the natural cycle and the land will heal on its own in time. And if you see any wards, take them down. Take her memory gem just in case. It may yield more information yet.", ["objectivesText"] = "Use Freydrin's Shilelagh to purify Boskroot Basin. Progress: There is much latent magic buried within this staff. It may be our only hope to bring these fungarians to heel.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 215158 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 218333, ["x"] = 0.542, ["y"] = 0.652 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 218333, ["x"] = 0.542, ["y"] = 0.652 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.652 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78572 }, ["questLines"] = { { ["id"] = 5512, ["name"] = "Boskroot of the Problem", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[78574] = { ["id"] = 78574, ["name"] = "Boss of the Bosk", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78570, 78571, 78572, 78573, 78574 }, ["description"] = "There is one final thing I must ask of you. There is a great monster that roams these woods. I am certain you've sensed it. It must be felled. Rotbark was Freydrin's final means to control this basin, but even this was too great for any individual earthen. Ours is not to control, but to tend to its needs. Use the staff once more and bring an end to Rotbark's reign.", ["objectivesText"] = "Defeat Rotbark the Unfelled in Boskroot Basin. Progress: If we are to restore this place, we must do so a different way. We must carve a new path.", ["rewardGold"] = 619600, ["rewardXP"] = 11895, ["rewardItems"] = { 215142, 219766, 219767, 219768, 219769 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 25 }, { ["id"] = 2897, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 218333, ["x"] = 0.542, ["y"] = 0.652 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 218333, ["x"] = 0.542, ["y"] = 0.652 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.652 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78573 }, ["questLines"] = { { ["id"] = 5512, ["name"] = "Boskroot of the Problem", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
