[78589] = { ["id"] = 78589, ["name"] = "Invasive Cuisine", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78589 }, ["description"] = "<This rarely seen plant may be of use to Chef Dinaire .>", ["objectivesText"] = "Deliver the Umbral Eggplant to Chef Dinaire at the Fungal Fields. Provided item:", ["rewardGold"] = 280900, ["rewardXP"] = 11765, ["rewardItems"] = { 206670, 211861 }, ["rewardCurrencies"] = { { ["id"] = 2899, ["amount"] = 75 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 206533, ["x"] = 0.644, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.644, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["startItems"] = { 211861 } },
