[78591] = { ["id"] = 78591, ["name"] = "Getaway to Scenic Nagrand!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Love is in the Air", ["expansion"] = 10, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 78591 }, ["description"] = "Today's special is a magical getaway to the great plains of Nagrand! If you're headed there, would you mind shooting a few animals? Oh, not like that! Here, borrow my camera. My friend Beatrice has been roaming around there lately. She would really appreciate some photographs, but I've got portals to attend to.", ["objectivesText"] = "Take the Scenic Getaway Portal to Nagrand, then take pictures of wildlife for Beatrice. Progress: There are so many places in Azeroth to escape to! Everywhere you look, there's something new to discover.", ["rewardGold"] = 286500, ["rewardXP"] = 1415, ["rewardItems"] = { 49927, 122637, 210743 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 212677, ["x"] = 0.342, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 212677, ["x"] = 0.342, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3027 } },
[78594] = { ["id"] = 78594, ["name"] = "Getaway to Scenic Feralas!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Love is in the Air", ["expansion"] = 10, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 78594 }, ["description"] = "Today's special is a magical getaway to the sunny beaches of Feralas! The Steam Pools resort is having a lovely celebration and all are invited! Unfortunately, some of the partygoers who took this portal earlier left their gifts here at the gala. Could you help me return them? Meet me at the beach and we'll figure out which gifts belong to whom.", ["objectivesText"] = "Take the Scenic Getaway Portal to Feralas, then deliver the lost gifts to the correct recipients. Progress: There are so many places in Azeroth to escape to! Everywhere you look, there's something new to discover.", ["rewardGold"] = 89550, ["rewardXP"] = 1415, ["rewardItems"] = { 49927, 211922, 211923 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 212677, ["x"] = 0.342, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 212677, ["x"] = 0.342, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3027 } },
[78595] = { ["id"] = 78595, ["name"] = "Dream Infused", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78595 }, ["description"] = "< Melsysra drops a slightly damp note into your hand.> <name>, your deeds have helped garner enough strength for a dream infusion ! Meet me at the Central Encampment so I can get it to you. - Elianna", ["objectivesText"] = "Talk to Elianna in the Central Encampment.", ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 211962, ["x"] = 0.496, ["y"] = 0.622 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 211209, ["x"] = 0.502, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.496, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard" },
[78596] = { ["id"] = 78596, ["name"] = "Summons to Lord Greymane", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 78177, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78190, 78596 }, ["description"] = "Greetings, Lord Greymane has requested your presence at Stormwind Harbor to assist him with a matter regarding Gilneas. That is all I am able to say. Good luck, <name>.", ["objectivesText"] = "Meet with Genn Greymane at Stormwind Harbor.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 211788, 211873 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 212899, ["x"] = 0.6248, ["y"] = 0.7212 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 214538, ["x"] = 0.339, ["y"] = 0.155667 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.6248, ["y"] = 0.7212 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["nextQuests"] = { 78177 }, ["questLines"] = { { ["id"] = 5511, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 84 },
[78597] = { ["id"] = 78597, ["name"] = "Clandestine Movements", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 130, ["mapID"] = 85, ["storyline"] = { 78178, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78597, 79137 }, ["description"] = "<name>, Lilian Voss and Calia Menethil have requested your presence for a clandestine operation involving Gilneas. They will brief you in full when you arrive.", ["objectivesText"] = "Meet with Lilian and Calia in Pyrewood Village in Silverpine Forest. Progress: Excellent, we've been waiting for you.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 211788, 211873 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 212916, ["x"] = 0.523333, ["y"] = 0.886 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 210964, ["x"] = 0.426, ["y"] = 0.727 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.523333, ["y"] = 0.886 }, ["mapCandidates"] = { ["npc"] = { 21, 85 }, ["zone"] = { 130 } }, ["questType"] = "standard", ["nextQuests"] = { 78178 }, ["questLines"] = { { ["id"] = 5538, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 11, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 21 },
