[78600] = { ["id"] = 78600, ["name"] = "Amirdrassil, the Dream's Hope: Up in Smoke", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14643, ["storyline"] = { 78600 }, ["description"] = "Smolderon appears to be aiding Fyrakk's assault on the Dream! If you collect some fragments of Emberscar, his legendary weapon, we may be able to attune with his energy and assault his throne directly.", ["objectivesText"] = "Collect 3 Fragments of Emberscar from Smolderon within Amirdrassil, the Dream's Hope on Normal difficulty. Progress: The energy found within these fragments will allow us to quickly access the Throne of the Firelord.", ["rewardGold"] = 561800, ["rewardXP"] = 11895, ["rewardItems"] = { 210791 }, ["starts"] = { { ["npcID"] = 210016 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14643 } }, ["questGiverID"] = 210016, ["questType"] = "raid" },
