[78620] = { ["id"] = 78620, ["name"] = "Crossroads of Twilight", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78226, 78228, 78244, 78348, 78352, 78353, 78620, 78621, 78624, 78630, 78658, 78659, 78671, 78948, 79156, 83503, 91868 }, ["description"] = "We need to take the Veneration Grounds back from the kobyss. Push them back and pave a bloody path through them. We need to stop whatever is happening at the Eternal Flame! If they manage to corrupt it like they did at the tower... I don't even want to imagine what will happen.", ["objectivesText"] = "Kill 15 kobyss attackers in the Veneration Grounds in Hallowfall . Progress: Flames, they just keep coming.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213108, ["x"] = 0.396, ["y"] = 0.589667 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213108, ["x"] = 0.396, ["y"] = 0.589667 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.396, ["y"] = 0.589667 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78615 }, ["questLines"] = { { ["id"] = 5526, ["name"] = "Hope in Solidarity", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 6006, ["name"] = "Catch Up: War Within: Wrapper 3", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5526, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5526, ["questLineOrder"] = 10 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6006, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[78621] = { ["id"] = 78621, ["name"] = "The Shadow Rising", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78226, 78228, 78244, 78348, 78352, 78353, 78620, 78621, 78624, 78630, 78658, 78659, 78671, 78948, 79156, 83503, 91868 }, ["description"] = "I can sense three beacons of void ahead, all funneling their power into one massive font of darkness. You will need to kill them. With them dead, I can bring down the shield.", ["objectivesText"] = "Kill the kobyss deepspeakers in the Veneration Grounds in Hallowfall . Progress: I'm ready to end this.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 214402, ["x"] = 0.394667, ["y"] = 0.526 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 214402, ["x"] = 0.394667, ["y"] = 0.526 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.394667, ["y"] = 0.526 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78615 }, ["questLines"] = { { ["id"] = 5526, ["name"] = "Hope in Solidarity", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 6006, ["name"] = "Catch Up: War Within: Wrapper 3", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5526, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5526, ["questLineOrder"] = 10 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6006, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[78624] = { ["id"] = 78624, ["name"] = "A Candle in the Dark", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78226, 78228, 78244, 78348, 78352, 78353, 78620, 78621, 78624, 78630, 78658, 78659, 78671, 78948, 79156, 83503, 91868 }, ["description"] = "Beledar has turned to Shadow, we must retreat back to Mereldar! <Vaelisia looks towards Aelric Leid .> I-- No. We need to destroy Aelric first. Take him down, then we retreat.", ["objectivesText"] = "Kill Aelric Leid in the Veneration Grounds in Hallowfall .", ["rewardGold"] = 619600, ["rewardXP"] = 12740, ["rewardItems"] = { 220133 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213108, ["x"] = 0.396, ["y"] = 0.589667 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 225188, ["x"] = 0.336, ["y"] = 0.546 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.396, ["y"] = 0.589667 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78620, 78621 }, ["questLines"] = { { ["id"] = 5526, ["name"] = "Hope in Solidarity", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 6006, ["name"] = "Catch Up: War Within: Wrapper 3", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5526, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5526, ["questLineOrder"] = 10 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6006, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[78626] = { ["id"] = 78626, ["name"] = "Spar Day", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78607, 78613, 78614, 78615, 78620, 78621, 78624, 78626, 78627, 78628, 78629, 78630, 79089, 79297, 80049 }, ["description"] = "Your skills in combat are impressive, <name>. We are rotating our next round of reserves into active duty, and they need to sharpen their skills. While Alleria fills me in on Xal'atath, I would appreciate it if you could help with their training.", ["objectivesText"] = "Duel 8 Arathi Recruits in Mereldar. Progress: The tricks they learn from you today will help them survive a difficult encounter later.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213108, ["x"] = 0.396, ["y"] = 0.589667 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213108, ["x"] = 0.396, ["y"] = 0.589667 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.396, ["y"] = 0.589667 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 79297 }, ["questLines"] = { { ["id"] = 5526, ["name"] = "Hope in Solidarity", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5526, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5526, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[78627] = { ["id"] = 78627, ["name"] = "The Final Front", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78607, 78613, 78614, 78615, 78620, 78621, 78624, 78626, 78627, 78628, 78629, 78630, 79089, 79297, 80049 }, ["description"] = "Just before the kobyss attacked, we received word of a disturbance near Livia's Patience. Now we know the cause. We... Light... We can't survive fighting on two fronts, <name>. We have to stop this, now.", ["objectivesText"] = "Travel to Light's Redoubt in Hallowfall .", ["rewardGold"] = 77400, ["rewardXP"] = 2550, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 225188, ["x"] = 0.336, ["y"] = 0.546 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213108, ["x"] = 0.396, ["y"] = 0.589667 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.336, ["y"] = 0.546 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 79089, 80049 }, ["questLines"] = { { ["id"] = 5526, ["name"] = "Hope in Solidarity", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5526, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5526, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[78628] = { ["id"] = 78628, ["name"] = "Trapdoor Sprung", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78607, 78613, 78614, 78615, 78620, 78621, 78624, 78626, 78627, 78628, 78629, 78630, 79089, 79297, 80049 }, ["description"] = "We need time to get the Reckoning ready. Take your friends and hold back the nerubians for as long as you can. They deserve nothing but death for what they have done to our people.", ["objectivesText"] = "Kill 15 nerubians in Livia's Patience in Hallowfall . Progress: How goes the hunt?", ["rewardGold"] = 280900, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213108, ["x"] = 0.396, ["y"] = 0.589667 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213107, ["x"] = 0.383667, ["y"] = 0.692333 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.396, ["y"] = 0.589667 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78627 }, ["questLines"] = { { ["id"] = 5526, ["name"] = "Hope in Solidarity", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5526, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5526, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[78629] = { ["id"] = 78629, ["name"] = "Running on Reserves", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78607, 78613, 78614, 78615, 78620, 78621, 78624, 78626, 78627, 78628, 78629, 78630, 79089, 79297, 80049 }, ["description"] = "We have to try to save any of our people left alive in Livia's Patience. Every Arathi is or was a member of the military. If you can help them, they'll be able to help themselves.", ["objectivesText"] = "Assist 5 Arathi Reserves in Livia's Patience in Hallowfall . Progress: I managed to rescue a few, did you find people to rescue?", ["rewardGold"] = 292100, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213107, ["x"] = 0.383667, ["y"] = 0.692333 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213107, ["x"] = 0.383667, ["y"] = 0.692333 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.383667, ["y"] = 0.692333 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78627 }, ["questLines"] = { { ["id"] = 5526, ["name"] = "Hope in Solidarity", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5526, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5526, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[78630] = { ["id"] = 78630, ["name"] = "The Rise of the Reckoning", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78226, 78228, 78244, 78348, 78352, 78353, 78620, 78621, 78624, 78630, 78658, 78659, 78671, 78948, 79156, 83503, 91868 }, ["description"] = "The Reckoning is ready! Let's make these spiders pay. Blood for blood.", ["objectivesText"] = "Board The Reckoning and slay 150 nerubian forces. Progress: We will make the nerubians regret ever thinking they could push into our home!", ["rewardGold"] = 876300, ["rewardXP"] = 15285, ["rewardItems"] = { 220128, 220129, 220131, 220132 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 125 }, { ["id"] = 2899, ["amount"] = 2500 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213107, ["x"] = 0.383667, ["y"] = 0.692333 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 211699, ["x"] = 0.309, ["y"] = 0.446 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.383667, ["y"] = 0.692333 }, ["mapCandidates"] = { ["npc"] = { 2215, 2255 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78628, 78629 }, ["questLines"] = { { ["id"] = 5526, ["name"] = "Hope in Solidarity", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 6006, ["name"] = "Catch Up: War Within: Wrapper 3", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5526, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5526, ["questLineOrder"] = 10 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6006, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[78631] = { ["id"] = 78631, ["name"] = "Speaking to the Speakers", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78555, 78557, 78631, 78634, 78635, 78636, 78637, 78638, 78639, 78640, 78641, 78642, 78837, 78838, 78839, 79205, 79267, 80082, 80434, 83550 }, ["series"] = { 78837, 78838 }, ["description"] = "I've heard about a problem nearby, and I think I know what's wrong. We used to have a mining operation northeast of Gundargaz. When we moved out, kobolds moved in. We haven't heard from those kobolds in a long time, but it sounds like they're raiding us now! And the High Speaker is doing nothing about it. Someone has to do something. If we can solve this, more Machine Speakers will listen to us. If the High Speaker doesn't get results, we will.", ["objectivesText"] = "Reassure Gundargaz' defenders on the way to the Lost Mines.", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212741, ["x"] = 0.4452, ["y"] = 0.2896 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212519, ["x"] = 0.555, ["y"] = 0.292 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.4452, ["y"] = 0.2896 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 78838 }, ["questLines"] = { { ["id"] = 5533, ["name"] = "By Candlelight", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5533, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5533, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214, ["db2QuestHubAreaPoiID"] = 7911 },
[78634] = { ["id"] = 78634, ["name"] = "Leave No Stone Behind", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78555, 78557, 78631, 78634, 78635, 78636, 78637, 78638, 78639, 78640, 78641, 78642, 78837, 78838, 78839, 79205, 79267, 80082, 80434, 83550 }, ["description"] = "Many earthen fell when the kobolds took this mine. Worse, those who fell were left to crumble where they dropped. There was no attempt to recover them. We couldn't provide closure or respect their memories. Why? Why did we forsake the fallen? We will not fail them again, <name>. Gather the identification plaques of those we lost, so we may commemorate them properly.", ["objectivesText"] = "Recover Identification Plaques from fallen earthen in the Lost Mines. Progress: Have you found them?", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["rewardItems"] = { 210873, 217694, 217695, 217696, 217699 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212519, ["x"] = 0.555, ["y"] = 0.292 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212519, ["x"] = 0.555, ["y"] = 0.292 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.292 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 78631 }, ["questLines"] = { { ["id"] = 5533, ["name"] = "By Candlelight", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5533, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5533, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[78635] = { ["id"] = 78635, ["name"] = "Death and Waxes", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78555, 78557, 78631, 78634, 78635, 78636, 78637, 78638, 78639, 78640, 78641, 78642, 78837, 78838, 78839, 79205, 79267, 80082, 80434, 83550 }, ["description"] = "Kobolds take candles seriously. Wax, even more. More important than gold. More important than freedom! We steal candles from Candle King. We make him look weak. Bully that looks weak loses control. Gets dead! Also means we not have to wait out here in dark until get eaten. Hurry!", ["objectivesText"] = "Recover Flickerflame Candles from around the Lost Mines. Progress: Did you take candle?", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["rewardItems"] = { 210878, 219361, 219363, 219368, 219375 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212269, ["x"] = 0.555, ["y"] = 0.292 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212269, ["x"] = 0.555, ["y"] = 0.292 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.292 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 78631 }, ["questLines"] = { { ["id"] = 5533, ["name"] = "By Candlelight", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5533, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5533, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[78636] = { ["id"] = 78636, ["name"] = "Retaking the Mines", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78555, 78557, 78631, 78634, 78635, 78636, 78637, 78638, 78639, 78640, 78641, 78642, 78837, 78838, 78839, 79205, 79267, 80082, 80434, 83550 }, ["description"] = "Now that we have the keys, it is time to take the fight to the Candle King. Get that gate open. Once we're inside, we'll move on to the next step.", ["objectivesText"] = "Unlock the gate to the Lost Mines.", ["rewardGold"] = 619600, ["rewardXP"] = 12400, ["rewardItems"] = { 218307, 219014 }, ["rewardChoices"] = { 218307, 219014 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212519, ["x"] = 0.555, ["y"] = 0.292 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 215671, ["x"] = 0.580667, ["y"] = 0.218 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.292 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 78637, 78638 }, ["questLines"] = { { ["id"] = 5533, ["name"] = "By Candlelight", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5533, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5533, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[78637] = { ["id"] = 78637, ["name"] = "Cracking Cogchewer", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78555, 78557, 78631, 78634, 78635, 78636, 78637, 78638, 78639, 78640, 78641, 78642, 78837, 78838, 78839, 79205, 79267, 80082, 80434, 83550 }, ["description"] = "Cogchewer is muscle for Candle King. So mean! Rebuilds earthen gears for wars. Also in charge of mine's defenses. Need his keys to get in the mines... and get me out of this thing!", ["objectivesText"] = "Kill Cogchewer in the Lost Mines and recover his keys. Progress: Did you find keys?", ["rewardGold"] = 561800, ["rewardXP"] = 12400, ["rewardItems"] = { 211865 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212269, ["x"] = 0.555, ["y"] = 0.292 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212269, ["x"] = 0.555, ["y"] = 0.292 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.292 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 78634, 78635 }, ["questLines"] = { { ["id"] = 5533, ["name"] = "By Candlelight", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5533, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5533, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[78638] = { ["id"] = 78638, ["name"] = "Engineering Destruction", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78555, 78557, 78631, 78634, 78635, 78636, 78637, 78638, 78639, 78640, 78641, 78642, 78837, 78838, 78839, 79205, 79267, 80082, 80434, 83550 }, ["description"] = "Some of the kobolds are retrofitting equipment left behind when the mines fell. Please, destroy the rigs before they're used against us. I'd rather they be scrap than in the hands of an enemy. There was a storage depot on the western edge of the lowest level of the mine. Start there.", ["objectivesText"] = "Destroy mining rigs in the Lost Mines. Progress: Are any still operable, <name>?", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212519, ["x"] = 0.555, ["y"] = 0.292 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212519, ["x"] = 0.555, ["y"] = 0.292 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.292 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 78634, 78635 }, ["questLines"] = { { ["id"] = 5533, ["name"] = "By Candlelight", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5533, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5533, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[78639] = { ["id"] = 78639, ["name"] = "Ko-boldening", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78555, 78557, 78631, 78634, 78635, 78636, 78637, 78638, 78639, 78640, 78641, 78642, 78837, 78838, 78839, 79205, 79267, 80082, 80434, 83550 }, ["description"] = "Bullies everywhere! Innocent kobolds kept down by Candle King's thugs all across Warrens. Give bullies taste of own medicine! Once bullies beaten, innocent have chance to run. Be free!", ["objectivesText"] = "Free oppressed kobolds in the Warrens by defeating their captors. Progress: Now they will see what it feels like!", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["rewardItems"] = { 219365, 219367, 219374, 219378 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212991, ["x"] = 0.601333, ["y"] = 0.32 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212991, ["x"] = 0.601333, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.601333, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 78640 }, ["questLines"] = { { ["id"] = 5533, ["name"] = "By Candlelight", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5533, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5533, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[78640] = { ["id"] = 78640, ["name"] = "Manifesto Destiny", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78555, 78557, 78631, 78634, 78635, 78636, 78637, 78638, 78639, 78640, 78641, 78642, 78837, 78838, 78839, 79205, 79267, 80082, 80434, 83550 }, ["description"] = "Before take mines, my people live in great city. Stoneheads call it the Warrens. Candle King's bullies run it now. We need see what we are fighting. Let kobolds know we here to help! Better choices than Candle King. What better way than pamphlets? Everyone love pamphlet! We draw real good! Brinthe say you have some sort of flying dragon-bird-thing? Perfect for scout! Perfect for dropping pamphlets! < Skitter looks at you expectantly, making small flapping motions as she waits.>", ["objectivesText"] = "Scout out and distribute pamphlets across the Warrens from the air. Progress: Never flown before. Is fun?", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 215672, ["x"] = 0.581333, ["y"] = 0.218 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212991, ["x"] = 0.601333, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.581333, ["y"] = 0.218 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 78636 }, ["questLines"] = { { ["id"] = 5533, ["name"] = "By Candlelight", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5533, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5533, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[78641] = { ["id"] = 78641, ["name"] = "Tackling Torchsnarl", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78555, 78557, 78631, 78634, 78635, 78636, 78637, 78638, 78639, 78640, 78641, 78642, 78837, 78838, 78839, 79205, 79267, 80082, 80434, 83550 }, ["description"] = "Torchsnarl runs Warrens for Candle King. Nothing but big bully! Very, very big bully. We show everyone. Bullies can be beaten!", ["objectivesText"] = "Defeat Torchsnarl in the Warrens. Progress: Torchsnarl is big one. Don't know why hiding behind flunkies. Still, can't miss him!", ["rewardGold"] = 619600, ["rewardXP"] = 12400, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212991, ["x"] = 0.601333, ["y"] = 0.32 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212991, ["x"] = 0.601333, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.601333, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 78639, 79205 }, ["questLines"] = { { ["id"] = 5533, ["name"] = "By Candlelight", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5533, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5533, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[78642] = { ["id"] = 78642, ["name"] = "New Candle, New Hope", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78555, 78557, 78631, 78634, 78635, 78636, 78637, 78638, 78639, 78640, 78641, 78642, 78837, 78838, 78839, 79205, 79267, 80082, 80434, 83550 }, ["description"] = "We weaken Candle King's grasp. Still need symbol, rally my people. King has ancient relic: symbol of hope. Called Candle Crown . Heart of my people. Candle King threw away! Found new prize: Darkflame Candle. That crown? Still in hoard. Candle King should come out now. See what we did here! While he looks, we sneak in! Use old tunnels! Take what's ours! We smart.", ["objectivesText"] = "Recover the Candle Crown from the Darkflame Cleft. Progress: We take hope from darkness, <name>.", ["rewardGold"] = 929400, ["rewardXP"] = 19840, ["rewardItems"] = { 210882, 212575, 217171, 219459, 220737, 258264 }, ["rewardChoices"] = { 219459 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212991, ["x"] = 0.601333, ["y"] = 0.32 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212991, ["x"] = 0.601333, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.601333, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 78641, 79267 }, ["questLines"] = { { ["id"] = 5533, ["name"] = "By Candlelight", ["orderIndex"] = 17, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5533, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5533, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[78643] = { ["id"] = 78643, ["name"] = "Fair Skies and Strong Winds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15105, ["mapID"] = 2112, ["storyline"] = { 75918, 75919, 75920, 75921, 75922, 75923, 76276, 76280, 76281, 76282, 76283, 76317, 76318, 76319, 76320, 76321, 76322, 76323, 76324, 76325, 76326, 76327, 76328, 76329, 76330, 76331, 76332, 76333, 76334, 76335, 76336, 76337, 76342, 76343, 76344, 76345, 76347, 76348, 76384, 76385, 76386, 76387, 76388, 76389, 76398, 76401, 76402, 76403, 76416, 76433, 76434, 76435, 76436, 76437, 76441, 76442, 76443, 76532, 77178, 77200, 77201, 77283, 77329, 77436, 77780, 77781, 77818, 78643, 78646, 78865, 92875 }, ["series"] = { 78865, 92875 }, ["description"] = "It has been a long road for us all, $p. But after persevering through hardship and strife, dragonkind stands poised to enter a new age. Before you leave for your next adventure, my fellow Aspects and I wish to thank you for all you have done for us.", ["objectivesText"] = "Speak with Alexstrasza at the Seat of the Aspects in Valdrakken . Progress: The Dragon Isles stand in your debt.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 212981, 213003, 213004, 213005, 213006, 213007, 213008, 213009, 213010, 213011, 213012, 213013, 213160 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 187678, ["x"] = 0.583778, ["y"] = 0.357111 }, { ["mapID"] = 2239, ["npcID"] = 216309, ["x"] = 0.51, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 187678, ["x"] = 0.583778, ["y"] = 0.357111 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.583778, ["y"] = 0.357111 }, ["mapCandidates"] = { ["npc"] = { 2112, 2239 }, ["zone"] = { 15105 } }, ["questType"] = "standard", ["sourceQuests"] = { 76283 }, ["questLines"] = { { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 68, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
[78646] = { ["id"] = 78646, ["name"] = "Fire Watch", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76327, 76328, 76329, 76330, 76331, 76332, 76333, 76334, 76335, 76336, 76337, 78646 }, ["description"] = "My mother seems unable to fully attune with the Eye. Perhaps it senses her ties to Ardenweald... Her shield is but a fraction of the Eye's power. If she was fully attuned, she could completely quench our foes' flames. But we cannot idly wait. We still need more information about Galok and his plan of attack. Bodwin indicates there is new flurry of activity in Igira's base of operations. With Bodwin's help, we can investigate without being seen.", ["objectivesText"] = "Regroup with Merithra at the edge of Eye of Ysera, overlooking Slagfell Hold.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 206406, ["x"] = 0.5225, ["y"] = 0.2785 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 206406, ["x"] = 0.5225, ["y"] = 0.2785 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.5225, ["y"] = 0.2785 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["sourceQuests"] = { 76328 }, ["questLines"] = { { ["id"] = 5460, ["name"] = "Eye of Ysera", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 37, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 231, ["title"] = "Guardians of the Dream", ["questLineID"] = 5460, ["questLineOrder"] = 4 }, { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
[78655] = { ["id"] = 78655, ["name"] = "Adaptive Cooling Salve", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["requiredClasses"] = { 1, 2, 6 }, ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 77791, 77886, 78159, 78160, 78655 }, ["description"] = "Should you need my assistance, I can craft you an ointment that should prove helpful in your attunement with Fyr'alath. Bring me the materials I don't have, and I'm sure I can put something together.", ["objectivesText"] = "Bring Erden Zaralek Glowspores , Awakened Frost , and a Dreaming Essence for the Adaptive Cooling Salve . Progress: Keep at it. All this hard work is going to pay off.", ["rewardGold"] = 140450, ["rewardXP"] = 4760, ["rewardItems"] = { 190329, 204460, 208212, 210918 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 194842, ["x"] = 0.824, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 194842, ["x"] = 0.824, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.824, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["sourceQuests"] = { 78159 }, ["questLines"] = { { ["id"] = 5483, ["name"] = "Symbiotic Glowspore Grip", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[78656] = { ["id"] = 78656, ["name"] = "Hose It Down", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78656 }, ["description"] = "With the flame restored, you can see the extent of contamination to the fishing hole. Kobyss and frogs have left heaps of strange goo that pollutes the shoreline. We need your help to clean up this gooey blight! I have a specially modified harvester equipped with a water barrel. Use this device to spray water on the goo piles and clean the shore of this contamination.", ["objectivesText"] = "Activate Baeny the Barrel and use the hose to wash away 40 Contaminating Goo. Progress: Have you cleaned up the shoreline?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 211942 }, ["rewardCurrencies"] = { { ["id"] = 2899, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 215956, ["x"] = 0.658, ["y"] = 0.244 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 215956, ["x"] = 0.658, ["y"] = 0.244 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.244 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 79295 } },
[78657] = { ["id"] = 78657, ["name"] = "The Midnight Sentry", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78657 }, ["objectivesText"] = "Enemy revealed using Sentry Flare", ["rewardItems"] = { 211073 }, ["starts"] = { { ["x"] = 0.639, ["y"] = 0.196, ["mapID"] = 2215 } }, ["ends"] = { { ["x"] = 0.639, ["y"] = 0.196, ["mapID"] = 2215 } }, ["coords"] = { ["mapID"] = 2215, ["x"] = 0.639, ["y"] = 0.196 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14838 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Enemy revealed using Sentry Flare", ["amount"] = 1, ["type"] = 0, ["objectID"] = 217065, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215, ["db2WidgetSetID"] = 1058 },
[78658] = { ["id"] = 78658, ["name"] = "The Hallowed Path", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2214, ["storyline"] = { 78226, 78228, 78244, 78348, 78352, 78353, 78620, 78621, 78624, 78630, 78658, 78659, 78671, 78948, 79156, 83503, 91868 }, ["description"] = "$p, I'm glad our paths have crossed. Adelgonn has been telling me about a cavern called Hallowfall . She's told me the people there are called the Arathi. I cannot imagine that they are related to the ancient human kingdom, but it can't be a coincidence. Adelgonn's people had fruitful contact with them some time ago. Whatever happened, I hope to repair that relationship and gain their aid. Please meet me at the Hallowfall Gate.", ["objectivesText"] = "Meet with the denizens of Hallowfall . Progress: Who are you?", ["rewardGold"] = 30900, ["rewardXP"] = 1275, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 213983, ["x"] = 0.449, ["y"] = 0.322 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213116, ["x"] = 0.6712, ["y"] = 0.5712 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.449, ["y"] = 0.322 }, ["mapCandidates"] = { ["npc"] = { 2214, 2215 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 81689 }, ["questLines"] = { { ["id"] = 5529, ["name"] = "The Guiding Star", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 6006, ["name"] = "Catch Up: War Within: Wrapper 3", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5529, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5529, ["questLineOrder"] = 8 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6006, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215, ["db2QuestHubAreaPoiID"] = 7911 },
[78659] = { ["id"] = 78659, ["name"] = "Where the Light Touches", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78226, 78228, 78244, 78348, 78352, 78353, 78620, 78621, 78624, 78630, 78658, 78659, 78671, 78948, 79156, 83503, 91868 }, ["series"] = { 83551 }, ["description"] = "Many in Hallowfall will call you \"outsider\". I would call you friend. I would also ask for your help, if you are no stranger to combat. Desperate times forge strong friendships. General Steelstrike ordered the army to fall back from the nerubian onslaught. In doing so, she abandoned a Lamplighter and many troops to the darkness. I may not be able to save them on my own, but with your help I may succeed. If you're willing, ride with me or meet me there.", ["objectivesText"] = "Meet with Faerin's ally near the Aegis Wall.", ["rewardGold"] = 30900, ["rewardXP"] = 1275, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213116, ["x"] = 0.6712, ["y"] = 0.5712 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 224310, ["x"] = 0.710667, ["y"] = 0.587333 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.6712, ["y"] = 0.5712 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78658 }, ["questLines"] = { { ["id"] = 5529, ["name"] = "The Guiding Star", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 6006, ["name"] = "Catch Up: War Within: Wrapper 3", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5529, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5529, ["questLineOrder"] = 8 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6006, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[78664] = { ["id"] = 78664, ["name"] = "The Gift of Self-Care", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Love is in the Air", ["expansion"] = 10, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 78664 }, ["description"] = "The eyes of a tired adventurer. A <class> that does many great deeds for many people. When was the last time you did a kind gesture for yourself? Perhaps now is the time. Look into your heart. What do YOU desire?", ["objectivesText"] = "Speak with Ying to discover your heart's desire. Progress: Love is a blessing, especially if it comes from within.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 213262, ["x"] = 0.35, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 213262, ["x"] = 0.35, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard" },
[78665] = { ["id"] = 78665, ["name"] = "Tunnel Trouble", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78658, 78659, 78665, 78666, 78667, 78668, 78669, 78670, 78671, 79999, 82836, 83551 }, ["description"] = "It's good to have new allies here. Together, we have much better chances of protecting this tower. The nerubians have overwhelmed us. If we're going to have any chance against them, we need to destroy the burrows they're using to come under the Wall. If you can handle that, we will survey the field from the top of the wall and meet you there.", ["objectivesText"] = "Destroy 6 Nerubian Burrows . Progress: Were you able to stop the nerubians from coming under the ground?", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 224310, ["x"] = 0.710667, ["y"] = 0.587333 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 224310, ["x"] = 0.710667, ["y"] = 0.587333 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.710667, ["y"] = 0.587333 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78659 }, ["questLines"] = { { ["id"] = 5529, ["name"] = "The Guiding Star", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5529, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5529, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[78666] = { ["id"] = 78666, ["name"] = "The Only Good Spider", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78658, 78659, 78665, 78666, 78667, 78668, 78669, 78670, 78671, 79999, 82836, 83551 }, ["description"] = "$p, if we don't stem the tide of nerubians climbing up to us, nothing else will matter. Their numbers are just too great. We need to delay their onslaught to buy the people of Hallowfall time to prepare. The wall still serves as a very effective chokepoint. Do what you can to thin their numbers.", ["objectivesText"] = "Kill 12 Nerubian attackers. Progress: <name>, every nerubian you kill here could mean a life saved in Hallowfall , and aids the chances of our own success.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 224310, ["x"] = 0.710667, ["y"] = 0.587333 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 224310, ["x"] = 0.710667, ["y"] = 0.587333 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.710667, ["y"] = 0.587333 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78665 }, ["questLines"] = { { ["id"] = 5529, ["name"] = "The Guiding Star", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5529, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5529, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[78667] = { ["id"] = 78667, ["name"] = "Rekindled Memories", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78658, 78659, 78665, 78666, 78667, 78668, 78669, 78670, 78671, 79999, 82836, 83551 }, ["description"] = "Good people died here today, $p--a lot of them. Every Arathi soldier carries a tinderbox. It represents their devotion to the Sacred Flame. Many use it as a focus to bring forth the Flame's light. In the dark places beyond the light of Beledar, the Sacred Flame brings hope. With the nerubian attack, we can't recover their bodies. So we must retrieve these symbols, to venerate their sacrifice. Then use this torch to burn their bodies. It's the best funeral we can offer.", ["objectivesText"] = "Recover 6 Arathi tinderboxes from fallen soldiers and burn their bodies. Progress: Have you recovered their tinderboxes? Every life deserves to be remembered in the Sacred Flame.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["rewardItems"] = { 213191, 220119, 220125, 220126, 220127 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213116, ["x"] = 0.6712, ["y"] = 0.5712 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213116, ["x"] = 0.6712, ["y"] = 0.5712 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.6712, ["y"] = 0.5712 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 79999 }, ["questLines"] = { { ["id"] = 5529, ["name"] = "The Guiding Star", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5529, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5529, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[78668] = { ["id"] = 78668, ["name"] = "Rally on the Dawnbreaker", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78658, 78659, 78665, 78666, 78667, 78668, 78669, 78670, 78671, 79999, 82836, 83551 }, ["description"] = "It's critical, with so many nerubians pouring through the Aegis Wall, that we defend our airships docked at Tenir's Ascent. The nerubians have always outnumbered us, but our fleet allows us to concentrate our defenders where they are attacking, as well as allowing us to bombard them from the safety of the skies. If we lose our armada, our hopes fade dramatically. Meet us there when you can.", ["objectivesText"] = "Meet Faerin at Tenir's Ascent aboard the Dawnbreaker.", ["rewardGold"] = 30900, ["rewardXP"] = 1275, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213116, ["x"] = 0.6712, ["y"] = 0.5712 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 224945, ["x"] = 0.575, ["y"] = 0.644 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.6712, ["y"] = 0.5712 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78666, 78667 }, ["questLines"] = { { ["id"] = 5529, ["name"] = "The Guiding Star", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5529, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5529, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[78669] = { ["id"] = 78669, ["name"] = "For Their Eyes Only", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78658, 78659, 78665, 78666, 78667, 78668, 78669, 78670, 78671, 79999, 82836, 83551 }, ["description"] = "We've fought the nerubians since we arrived, $p. Their attacks have not risen to this level in a long time. These airship docks are clearly a target, but do they have any others? Is there a larger goal? The nerubians carry shadecasters with orders from their queen. We need to learn what we can of their plans and intentions, and recovering a few of those shadecasters is the best way we can do so.", ["objectivesText"] = "Gather 3 nerubian Shadecasters to learn their plans. Progress: Have you found any of those shadecasters yet, <name>?", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["rewardItems"] = { 216658, 216659, 216660 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 224946, ["x"] = 0.574, ["y"] = 0.644 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213120, ["x"] = 0.645667, ["y"] = 0.576333 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.574, ["y"] = 0.644 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78668 }, ["questLines"] = { { ["id"] = 5529, ["name"] = "The Guiding Star", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5529, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5529, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[78670] = { ["id"] = 78670, ["name"] = "Siege Weapon Sabotage", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78658, 78659, 78665, 78666, 78667, 78668, 78669, 78670, 78671, 79999, 82836, 83551 }, ["description"] = "$p, if we're going to hold the nerubians back, we have to deal with their siege weapons. Around Tenir's Ascent, there are kegs of black powder to supply our ships for combat. Since the nerubians have caught these ships on the ground, let's put that powder to work. Gather some barrels, and take them down to the nerubian siege weapons.", ["objectivesText"] = "Destroy 4 siege weapons below Tenir's Ascent. Progress: Were you able to destroy their siege weapons, <name>?", ["rewardGold"] = 584200, ["rewardXP"] = 12740, ["rewardItems"] = { 213630, 220118 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 224945, ["x"] = 0.575, ["y"] = 0.644 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213120, ["x"] = 0.645667, ["y"] = 0.576333 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.575, ["y"] = 0.644 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78668 }, ["questLines"] = { { ["id"] = 5529, ["name"] = "The Guiding Star", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5529, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5529, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[78671] = { ["id"] = 78671, ["name"] = "The Light of the Dawntower", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78226, 78228, 78244, 78348, 78352, 78353, 78620, 78621, 78624, 78630, 78658, 78659, 78671, 78948, 79156, 83503, 91868 }, ["description"] = "$p, Faerin went to light the dawntower. She said it keeps the light of the Sacred Flame shining upon Hallowfall . Kyron is there as well. It's hard to imagine that any beacon could outshine their star Beledar, but I am eager to see this new expression of the Light. Meet me by the dawntower and we can see how the Sacred Flame of the Arathi helps to safeguard these long-lost cousins of mine.", ["objectivesText"] = "Assist the Lamplighters in lighting the dawntower.", ["rewardGold"] = 154900, ["rewardXP"] = 5095, ["rewardItems"] = { 220107, 220111, 220113, 220114 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 125 }, { ["id"] = 2899, ["amount"] = 2500 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213120, ["x"] = 0.645667, ["y"] = 0.576333 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213116, ["x"] = 0.6712, ["y"] = 0.5712 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.645667, ["y"] = 0.576333 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 82836 }, ["questLines"] = { { ["id"] = 5529, ["name"] = "The Guiding Star", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 6006, ["name"] = "Catch Up: War Within: Wrapper 3", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5529, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5529, ["questLineOrder"] = 8 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6006, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215, ["db2QuestHubAreaPoiID"] = 7911 },
[78672] = { ["id"] = 78672, ["name"] = "A Lamplighter's Duty", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78672, 78929, 78932, 78934, 78936, 78937, 78939, 78951, 78952, 78954, 81690 }, ["description"] = "Darkness has fallen. We can't rest yet. < Faerin gives you a weary smile, but there is a light in her eyes.> The light from the tower will hold the worst dangers in the darkness at bay. It's my duty, as a Lamplighter, to keep all the towers blazing. My patrol takes me to Lorel's Crossing by air next. I would welcome you and Anduin at my side, for all our sakes.", ["objectivesText"] = "Take the Lamplighter Skiff to Lorel's Crossing.", ["rewardGold"] = 619600, ["rewardXP"] = 12740, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213116, ["x"] = 0.6712, ["y"] = 0.5712 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 214378, ["x"] = 0.538, ["y"] = 0.314 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.6712, ["y"] = 0.5712 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78671 }, ["questLines"] = { { ["id"] = 5530, ["name"] = "Gathering Shadows", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5530, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5530, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[78674] = { ["id"] = 78674, ["name"] = "The Gift of Relief", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Love is in the Air", ["expansion"] = 10, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 78674 }, ["description"] = "You adventurers are known to carry heavy burdens. There will be no better time to confront them than now. I saw a veteran somewhere around here. There is a chance he may know what it means to cope with stress. Perhaps he has insight to teach you.", ["objectivesText"] = "Speak to Simeon Griswold at the Gala of Gifts, then relieve your stress in Old Town. Progress: I've seen men die of stress. You don't want to bottle it up every day.", ["rewardGold"] = 331700, ["rewardXP"] = 1415, ["rewardItems"] = { 49927, 207793 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 213262, ["x"] = 0.35, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 213294, ["x"] = 0.338, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3027 } },
[78685] = { ["id"] = 78685, ["name"] = "The Tunnel's End", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78685, 78696, 78697, 78700, 78701, 78703, 78704, 78705, 78706, 80079 }, ["description"] = "So we're hearing more rumors about Taelloch. The town and its mine are responsible for ore production. Apparently, we haven't received shipments in weeks, and the town's foreman has disappeared. Now the High Speaker is discouraging anyone from traveling there. That tells me we should investigate. And of course, if people are hurting, then we should help them.", ["objectivesText"] = "Investigate the rumors about Taelloch. Progress: We have to find out what happened here.", ["rewardGold"] = 232300, ["rewardXP"] = 7440, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 218715, ["x"] = 0.45, ["y"] = 0.332 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 213612, ["x"] = 0.583, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.332 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 80079 }, ["questLines"] = { { ["id"] = 5534, ["name"] = "Dark Revelations", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5534, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5534, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214, ["db2QuestHubAreaPoiID"] = 7911 },
[78686] = { ["id"] = 78686, ["name"] = "Lights Out", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78686, 78687, 78688, 78689, 78690, 78691, 78692, 78693, 78694, 78695 }, ["description"] = "Name's Aegor. I try to keep tabs on Lamplighters in the field and assess what areas of Hallowfall may be in need of their aid. The dawntower fell dark at Velhan's Claim a few weeks ago. Based on what's been happening around Hallowfall , it's probably because of the rising tide of kobyss. Lamplighters Taenar and Aemyra are heading there, but this might be more than even two Lamplighters together can handle. Will you meet them there and help them restore the light at Velhan's Claim?", ["objectivesText"] = "Meet Taenar and Aemyra near Velhan's Claim.", ["rewardGold"] = 30900, ["rewardXP"] = 1275, ["rewardItems"] = { 38666, 223432, 246936, 249400, 251257, 254267, 254579, 260854, 260855, 260856, 260857 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 214019, ["x"] = 0.492, ["y"] = 0.41 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213614, ["x"] = 0.472, ["y"] = 0.147333 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78658 }, ["questLines"] = { { ["id"] = 5522, ["name"] = "Bringing Light to Velhan's Claim", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[78687] = { ["id"] = 78687, ["name"] = "Crash Recovery", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78686, 78687, 78688, 78689, 78690, 78691, 78692, 78693, 78694, 78695 }, ["description"] = "A lot of things went wrong when the Indomitable crashed, $p. But the most upsetting one is that--when the order was finally given to make our way back to Mereldar, we couldn't honor our fallen comrades. It seems the kobyss reanimated our fallen stalwarts, who now wander the Indomitable in a ghastly skeletal form. Take back their tinderboxes. If we can deliver those to the Sacred Flame, they'll finally be free after all these years.", ["objectivesText"] = "Retrieve 4 Recovered Tinderboxes from the Indomitable's stalwarts. Progress: Did you find those tinderboxes, <name>?", ["rewardGold"] = 292100, ["rewardXP"] = 10190, ["rewardItems"] = { 212317 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213614, ["x"] = 0.472, ["y"] = 0.147333 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213614, ["x"] = 0.472, ["y"] = 0.147333 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.147333 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78692 }, ["questLines"] = { { ["id"] = 5522, ["name"] = "Bringing Light to Velhan's Claim", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[78688] = { ["id"] = 78688, ["name"] = "Cage, Match", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78686, 78687, 78688, 78689, 78690, 78691, 78692, 78693, 78694, 78695 }, ["description"] = "When we were scouting before you arrived, we saw a lot of cages set up around Velhan's Claim. Typically, the kobyss use these to hold their victims until they're needed for a ritual sacrifice. Those sacrifices lead to... lots of other dark activities. Not the least of which is eating the victims. Let's get ahead of all that. Take my torch, and destroy the cages, so we don't have to see that happen to anyone from Velhan's Claim.", ["objectivesText"] = "Burn 10 kobyss cages with Aemyra's Holy Flame. Progress: Have you dealt with those cages yet? The citizens of Velhan's Claim won't be safe until you do.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["rewardItems"] = { 211945 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213613, ["x"] = 0.472667, ["y"] = 0.147333 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213613, ["x"] = 0.472667, ["y"] = 0.147333 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.472667, ["y"] = 0.147333 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78686 }, ["questLines"] = { { ["id"] = 5522, ["name"] = "Bringing Light to Velhan's Claim", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[78689] = { ["id"] = 78689, ["name"] = "If It Leads, It Bleeds", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78686, 78687, 78688, 78689, 78690, 78691, 78692, 78693, 78694, 78695 }, ["description"] = "Everything rises and falls on leadership, $p. With a good leader, a unit can achieve almost anything. With a bad leader, chaos ensues and success moves out of reach. I've seen that first-hand. Without leaders, the kobyss siege will break like a wave and everything else we do here becomes easier. I've seen three kobyss who seem to be leading the others--let me mark their locations on your map. Deal with them, and we'll be much more able to help Velhan's Claim.", ["objectivesText"] = "Defeat the kobyss leaders besieging Velhan's Claim. Progress: Did you find their leaders? They look strong, but I'm sure you're up to the task.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213614, ["x"] = 0.472, ["y"] = 0.147333 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213614, ["x"] = 0.472, ["y"] = 0.147333 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.147333 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78686 }, ["questLines"] = { { ["id"] = 5522, ["name"] = "Bringing Light to Velhan's Claim", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[78690] = { ["id"] = 78690, ["name"] = "Situational Awareness", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78686, 78687, 78688, 78689, 78690, 78691, 78692, 78693, 78694, 78695 }, ["description"] = "Regardless of what history Taenar and Velhan have between them, we need to take care of the people here at Velhan's Claim. $p, will you please check in with the families here? Let them know we're here to help. See if they're worried or need anything. And reassure them that the Lamplighters will drive back the kobyss.", ["objectivesText"] = "Speak with 10 citizens of Velhan's Claim. Progress: It's so important to reassure the citizens of Velhan's Claim, <name>, that they'll get through this. Hope is everything in dark times.", ["rewardGold"] = 292100, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213613, ["x"] = 0.472667, ["y"] = 0.147333 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213613, ["x"] = 0.472667, ["y"] = 0.147333 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.472667, ["y"] = 0.147333 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78688, 78689 }, ["questLines"] = { { ["id"] = 5522, ["name"] = "Bringing Light to Velhan's Claim", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[78691] = { ["id"] = 78691, ["name"] = "The One That Got Away", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78686, 78687, 78688, 78689, 78690, 78691, 78692, 78693, 78694, 78695 }, ["description"] = "$p, my son is out with the kobyss. He convinced the other kids they should sneak out with him to fight. Said they should, \"be brave like my dad\". When they met a kobyss, the others all ran back here, while he ran toward the crashed ship, to lead it away. I have not handled myself bravely, $p. The story of the Indomitable says I was a hero; those lies were my report. If there was ever a time to step up, it's now. But I'm no match for the kobyss alone. Come with me, $p--help me save Maximillian.", ["objectivesText"] = "Rescue Maximillian at the crash of the Indomitable. Progress: Stay focused, <name>--we have to find my son.", ["rewardGold"] = 584200, ["rewardXP"] = 12740, ["rewardItems"] = { 34863 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213787, ["x"] = 0.471333, ["y"] = 0.133333 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213787, ["x"] = 0.471333, ["y"] = 0.133333 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.471333, ["y"] = 0.133333 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78692 }, ["questLines"] = { { ["id"] = 5522, ["name"] = "Bringing Light to Velhan's Claim", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[78692] = { ["id"] = 78692, ["name"] = "Teach a Man to Fish", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78686, 78687, 78688, 78689, 78690, 78691, 78692, 78693, 78694, 78695 }, ["description"] = "$p, the people of Velhan's Claim have been locked up inside, afraid of the dark, for too long. And there's plenty to fear out there, but these are capable, strong people. They should be driving the kobyss away, not hiding behind their walls. Get these spears to the people of Velhan's Claim. They've learned to hide from their problems, but we'll give them the means to take their lives back!", ["objectivesText"] = "Distribute 8 spears to the residents of Velhan's Claim. Progress: Have you handed out those spears yet? The people need them to remind them what they're capable of.", ["rewardGold"] = 292100, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213613, ["x"] = 0.472667, ["y"] = 0.147333 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213613, ["x"] = 0.472667, ["y"] = 0.147333 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.472667, ["y"] = 0.147333 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78693, 78694 }, ["questLines"] = { { ["id"] = 5522, ["name"] = "Bringing Light to Velhan's Claim", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[78693] = { ["id"] = 78693, ["name"] = "Spears for Fears", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78686, 78687, 78688, 78689, 78690, 78691, 78692, 78693, 78694, 78695 }, ["description"] = "It seems Velhan and his followers hoped they could live in peace here. They were so sure they could, in fact, that they didn't bring any weapons with them. This is a problem, with the kobyss attacking now, but the kobyss can actually solve it for us. They've brought plenty of spears for their siege on Velhan's Claim, and a spear will skewer a kobyss just as well as a human. Head out there and gather some spears for the people, $p, and they won't have to be so afraid.", ["objectivesText"] = "Gather 8 Kobyss Spears for the people of Velhan's Claim. Progress: Kobyss giving you trouble? Soon, the people of Velhan's Claim will be the ones giving them trouble.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["rewardItems"] = { 211948 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213613, ["x"] = 0.472667, ["y"] = 0.147333 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213613, ["x"] = 0.472667, ["y"] = 0.147333 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.472667, ["y"] = 0.147333 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78690 }, ["questLines"] = { { ["id"] = 5522, ["name"] = "Bringing Light to Velhan's Claim", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[78694] = { ["id"] = 78694, ["name"] = "Reclaiming Velhan's Claim", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78686, 78687, 78688, 78689, 78690, 78691, 78692, 78693, 78694, 78695 }, ["description"] = "The problem I see, $p, is the kobyss. There's just so many of them. Everyone here was serving in the Empire's military when we arrived in Hallowfall . They may be rusty now, but they've all trained before, and know how to be dangerous. But we need to eliminate every disadvantage, including the kobyss numbers. So head out there and even up the numbers. Aemyra and I will keep everyone safe here.", ["objectivesText"] = "Kill 12 Kobyss warriors around Velhan's Claim. Progress: How's it going out there, <name>? You sending those creatures of darkness back to the deeps?", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213614, ["x"] = 0.472, ["y"] = 0.147333 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213614, ["x"] = 0.472, ["y"] = 0.147333 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.147333 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78690 }, ["questLines"] = { { ["id"] = 5522, ["name"] = "Bringing Light to Velhan's Claim", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[78695] = { ["id"] = 78695, ["name"] = "Lamp Lit", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78686, 78687, 78688, 78689, 78690, 78691, 78692, 78693, 78694, 78695 }, ["description"] = "The kobyss normally live deep underwater, $p. When Beledar is at its brightest, they don't bother us. Other sources of bright light will usually keep them away, but definitely weaken them. As Lamplighters, we not only go into the dark to protect those in need, but we provide them the light that will keep them safe. Go set up these torches along the perimeter, then meet us up at the dawntower behind Velhan's Claim.", ["objectivesText"] = "Place 8 torches around the perimeter of Velhan's Claim, then observe the re-lighting of the dawntower. Progress: Did you get those torches set, <name>? The people will be able to quickly light them whenever Beledar fades.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["rewardItems"] = { 225944 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 25 }, { ["id"] = 2899, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213614, ["x"] = 0.472, ["y"] = 0.147333 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213787, ["x"] = 0.471333, ["y"] = 0.133333 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.147333 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78687, 78691 }, ["questLines"] = { { ["id"] = 5522, ["name"] = "Bringing Light to Velhan's Claim", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[78696] = { ["id"] = 78696, ["name"] = "We Don't Go to Taelloch", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78685, 78696, 78697, 78700, 78701, 78703, 78704, 78705, 78706, 80079 }, ["description"] = "This troubled Machine Speaker was here to do something. But what? It looks like something really did some damage to him. We shouldn't dally. We need to head into Taelloch and look for the foreman. Can you clear the entryway into the town? Someone could get hurt!", ["objectivesText"] = "Clear the entrance to Taelloch of encroaching beasts.", ["rewardGold"] = 292100, ["rewardXP"] = 9920, ["rewardItems"] = { 219359, 219364, 219369, 219373 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 213612, ["x"] = 0.583, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 213634, ["x"] = 0.602, ["y"] = 0.582 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.583, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 78685 }, ["questLines"] = { { ["id"] = 5534, ["name"] = "Dark Revelations", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5534, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5534, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[78697] = { ["id"] = 78697, ["name"] = "Ghost of a Company Town", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78685, 78696, 78697, 78700, 78701, 78703, 78704, 78705, 78706, 80079 }, ["description"] = "The foreman isn't here. Obviously. But the evidence points to her being here recently. So perhaps she's still nearby! We should go further into town and see if anyone has any idea where she might be. Or maybe someone else can give us the answers we need. Maybe we'll find out on our own! Maybe it was some sort of attack or some kind of... sorry. I'm getting ahead of myself. Let's go investigate!", ["objectivesText"] = "Use the Investigate ability to find clues about what happened in Taelloch.", ["rewardGold"] = 292100, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 213634, ["x"] = 0.602, ["y"] = 0.582 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 216479, ["x"] = 0.64, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.582 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 78696 }, ["questLines"] = { { ["id"] = 5534, ["name"] = "Dark Revelations", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5534, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5534, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[78700] = { ["id"] = 78700, ["name"] = "Controlled Demolition", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78685, 78696, 78697, 78700, 78701, 78703, 78704, 78705, 78706, 80079 }, ["description"] = "I know we've fought skardyn before, champion, but this... this is worse. I knew that skardyn were turning earthen into more skardyn, but I didn't expect... the crystals... the spikes... the roiling blue energy... that smell! Anyway, not what I expected at all. If we must venture out there, I'm taking down some of those abominations along the way.", ["objectivesText"] = "Kill 18 skardyn in Taelloch Progress: There's more to be done. We can't let this corruption spread.", ["rewardGold"] = 280900, ["rewardXP"] = 9920, ["rewardItems"] = { 219380, 219383 }, ["rewardChoices"] = { 219380, 219383 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 216479, ["x"] = 0.64, ["y"] = 0.584 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 216479, ["x"] = 0.64, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questTurnInID"] = 216479, ["questType"] = "standard", ["sourceQuests"] = { 78697 }, ["questLines"] = { { ["id"] = 5534, ["name"] = "Dark Revelations", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5534, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5534, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[78701] = { ["id"] = 78701, ["name"] = "The Truth in Chalk", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78685, 78696, 78697, 78700, 78701, 78703, 78704, 78705, 78706, 80079 }, ["description"] = "So the people of Taelloch use chalk on slate to leave messages to each other. So many clues! But what does it all mean.... I'm seeing a pattern, and I think it points to the mines. If the workers haven't already been lost, I'd expect them to be in the mines. And I know the foreman is the key. She has to be.", ["objectivesText"] = "Search for messages in Taelloch Mine. Progress: There's more to learn here. I'm sure of it.", ["rewardGold"] = 292100, ["rewardXP"] = 9920, ["starts"] = { { ["x"] = 0.619, ["y"] = 0.583, ["mapID"] = 2214, ["npcID"] = 214892 } }, ["ends"] = { { ["x"] = 0.619, ["y"] = 0.583, ["mapID"] = 2214, ["npcID"] = 214892 } }, ["coords"] = { ["mapID"] = 2214, ["x"] = 0.619, ["y"] = 0.583 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14795 } }, ["questGiverID"] = 214892, ["questTurnInID"] = 214892, ["questType"] = "standard", ["sourceQuests"] = { 78697 }, ["questLines"] = { { ["id"] = 5534, ["name"] = "Dark Revelations", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5534, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5534, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[78703] = { ["id"] = 78703, ["name"] = "Buried in Stone", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78685, 78696, 78697, 78700, 78701, 78703, 78704, 78705, 78706, 80079 }, ["description"] = "We need to go into the cave, the one mentioned near the last slate. It's not signed, but I think that's the foreman's handwriting... and we've looked everywhere else. We have to investigate.", ["objectivesText"] = "Investigate the cave at the back of the Taelloch Mine Progress: We're missing something... There must be something in that cave!", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["starts"] = { { ["npcID"] = 214892 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14795 } }, ["questGiverID"] = 214892, ["questType"] = "standard", ["sourceQuests"] = { 78700, 78701 }, ["questLines"] = { { ["id"] = 5534, ["name"] = "Dark Revelations", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5534, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5534, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[78704] = { ["id"] = 78704, ["name"] = "Find the Foreman", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78459, 78461, 78462, 78529, 78530, 78531, 78532, 78533, 78544, 78545, 78546, 78704, 78705, 78706, 78761, 78837, 79105, 79106, 80022, 80321, 80334, 80434, 91864 }, ["description"] = "Dagran was right. I suppose I shouldn't be surprised by that any longer. All the signs suggest there's something in this cave. Maybe the foreman is hiding here. Maybe she can give us some answers. We've come this far. Let's see what's inside.", ["objectivesText"] = "Find the foreman. Progress: There must be answers deeper within the cave.", ["rewardGold"] = 292100, ["rewardXP"] = 9920, ["rewardItems"] = { 219362, 219366, 219371, 219376 }, ["starts"] = { { ["npcID"] = 214890 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14795 } }, ["questGiverID"] = 214890, ["questType"] = "standard", ["sourceQuests"] = { 78703 }, ["questLines"] = { { ["id"] = 5534, ["name"] = "Dark Revelations", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 6008, ["name"] = "Catch Up: War Within: Wrapper 2", ["orderIndex"] = 19, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5534, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5534, ["questLineOrder"] = 6 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6008, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[78705] = { ["id"] = 78705, ["name"] = "What She Saw", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78459, 78461, 78462, 78529, 78530, 78531, 78532, 78533, 78544, 78545, 78546, 78704, 78705, 78706, 78761, 78837, 79105, 79106, 80022, 80321, 80334, 80434, 91864 }, ["description"] = "What is that? That thing the skardyn dropped before we... before it died. I think I've seen something like that before.", ["objectivesText"] = "Investigate the gem left by the skardyn. Progress: I think I know what that gem is...", ["rewardGold"] = 584200, ["rewardXP"] = 12400, ["starts"] = { { ["npcID"] = 214892 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 219453, ["x"] = 0.671333, ["y"] = 0.643333 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.671333, ["y"] = 0.643333 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questGiverID"] = 214892, ["questType"] = "standard", ["sourceQuests"] = { 78704 }, ["questLines"] = { { ["id"] = 5534, ["name"] = "Dark Revelations", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 6008, ["name"] = "Catch Up: War Within: Wrapper 2", ["orderIndex"] = 20, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5534, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5534, ["questLineOrder"] = 6 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6008, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[78706] = { ["id"] = 78706, ["name"] = "The High Speaker's Secret", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78459, 78461, 78462, 78529, 78530, 78531, 78532, 78533, 78544, 78545, 78546, 78704, 78705, 78706, 78761, 78837, 79105, 79106, 80022, 80321, 80334, 80434, 91864 }, ["description"] = "We got what we came for. We need to return to Gundargaz. Brinthe has to know what happened here. We'll go on ahead, $p. Meet us in Gundargaz.", ["objectivesText"] = "Return to Brinthe in Gundargaz.", ["rewardGold"] = 28300, ["rewardXP"] = 1240, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 125 }, { ["id"] = 2902, ["amount"] = 2500 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 219452, ["x"] = 0.671333, ["y"] = 0.643333 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212741, ["x"] = 0.4452, ["y"] = 0.2896 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.671333, ["y"] = 0.643333 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 78705 }, ["questLines"] = { { ["id"] = 5534, ["name"] = "Dark Revelations", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 6008, ["name"] = "Catch Up: War Within: Wrapper 2", ["orderIndex"] = 21, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5534, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5534, ["questLineOrder"] = 6 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6008, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[78713] = { ["id"] = 78713, ["name"] = "The War Within", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 9310, ["mapID"] = 85, ["storyline"] = { 78529, 78713, 78714, 78715, 78716, 78717, 78718, 78719, 78721, 78722, 79105, 79106, 80321, 80500, 81966 }, ["description"] = "There is a vision being seen across Azeroth. A \"Radiant Song.\" We believe it's a warning, but we are unsure of its meaning. Meet me in Silithus. We must ask Azeroth's Speaker what this vision means.", ["objectivesText"] = "Go to Silithus to talk with Thrall about the visions spreading across Azeroth.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 135539, 227669 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 221949, ["x"] = 0.495333, ["y"] = 0.773333 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 213620, ["x"] = 0.418, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.495333, ["y"] = 0.773333 }, ["mapCandidates"] = { ["npc"] = { 81, 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5513, ["name"] = "Visions of Azeroth", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5638, ["name"] = "Dalaran Intro", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 235, ["title"] = "Visions of Azeroth", ["questLineID"] = 5513, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5513, ["questLineOrder"] = 1 }, { ["id"] = 261, ["title"] = "Expansion Intro Skip", ["questLineID"] = 5638, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 5967 }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 81 },
[78714] = { ["id"] = 78714, ["name"] = "A Poor Reception", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 9310, ["mapID"] = 81, ["storyline"] = { 78529, 78713, 78714, 78715, 78716, 78717, 78718, 78719, 78721, 78722, 79105, 79106, 80321, 80500, 81930, 81966 }, ["description"] = "There's strong evidence that the Radiant Song is a warning from Azeroth herself. A cry for help. That's why we're here. If this vision truly is Azeroth's message, Magni will know what she's trying to tell us. He should be in the Chamber of the Heart. Let's go.", ["objectivesText"] = "Go to the Heart Chamber to ask Magni for help deciphering the Radiant Song.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 213620, ["x"] = 0.418, ["y"] = 0.45 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 213620, ["x"] = 0.418, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.45 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questTurnInID"] = 213620, ["questType"] = "standard", ["sourceQuests"] = { 78713, 81930 }, ["questLines"] = { { ["id"] = 5513, ["name"] = "Visions of Azeroth", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5638, ["name"] = "Dalaran Intro", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 235, ["title"] = "Visions of Azeroth", ["questLineID"] = 5513, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5513, ["questLineOrder"] = 1 }, { ["id"] = 261, ["title"] = "Expansion Intro Skip", ["questLineID"] = 5638, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2698, ["db2PoiUiMapID"] = 2321 },
[78715] = { ["id"] = 78715, ["name"] = "Azeroth's Voice", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 9310, ["mapID"] = 81, ["storyline"] = { 78529, 78713, 78714, 78715, 78716, 78717, 78718, 78719, 78721, 78722, 79105, 79106, 80321, 80500, 81930, 81966 }, ["description"] = "I haven't spoken with Azeroth for years. At first I just didn't feel the need. Then I realized I had started to resent her. For leaving me like... this. And now I'm not sure if I can. But I know the stakes. This Radiant Song of hers foretells something dire. And we need to know what. First, we need to prepare the Heart Chamber. Can ye start up the consoles nearby?", ["objectivesText"] = "Help Magni perform his ritual. Progress: I understand Magni's concerns, but we have no other choice. The future of our world is at stake. We must try everything we can to understand what Azeroth is trying to warn us of.", ["rewardGold"] = 140450, ["rewardXP"] = 4760, ["starts"] = { { ["x"] = 0.501, ["y"] = 0.644, ["mapID"] = 2321, ["npcID"] = 213624 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 213625, ["x"] = 0.418, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.45 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 7502 } }, ["questGiverID"] = 213624, ["questType"] = "standard", ["sourceQuests"] = { 78714 }, ["questLines"] = { { ["id"] = 5513, ["name"] = "Visions of Azeroth", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5638, ["name"] = "Dalaran Intro", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 235, ["title"] = "Visions of Azeroth", ["questLineID"] = 5513, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5513, ["questLineOrder"] = 1 }, { ["id"] = 261, ["title"] = "Expansion Intro Skip", ["questLineID"] = 5638, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2698, ["db2PoiUiMapID"] = 2321 },
[78716] = { ["id"] = 78716, ["name"] = "Painful Lessons", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 7502, ["mapID"] = 81, ["storyline"] = { 78529, 78713, 78714, 78715, 78716, 78717, 78718, 78719, 78721, 78722, 79105, 79106, 80321, 80500, 81930, 81966 }, ["description"] = "Magni appears stable for now, but he's still not responsive. We need to get him treatment quickly. I'll open a portal to Dalaran . Follow us when you can.", ["objectivesText"] = "Take the portal to Dalaran .", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 213625, ["x"] = 0.418, ["y"] = 0.45 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 213625, ["x"] = 0.418, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.45 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questTurnInID"] = 213625, ["questType"] = "standard", ["sourceQuests"] = { 78715 }, ["questLines"] = { { ["id"] = 5513, ["name"] = "Visions of Azeroth", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5638, ["name"] = "Dalaran Intro", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 235, ["title"] = "Visions of Azeroth", ["questLineID"] = 5513, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5513, ["questLineOrder"] = 1 }, { ["id"] = 261, ["title"] = "Expansion Intro Skip", ["questLineID"] = 5638, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 629 },
[78717] = { ["id"] = 78717, ["name"] = "A Mysterious Warning", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 78529, 78713, 78714, 78715, 78716, 78717, 78718, 78719, 78721, 78722, 79105, 79106, 80321, 80500, 81930, 81966 }, ["description"] = "Well, that was quite the nap. I wasn't expecting Azeroth to be so... loud. To normal folk, she's gently calling out. But with our connection, it felt like she was screaming. Directly into my crystal noggin. I saw it though. Khaz Algar, an island of earthen, bathed in fire and smoke. That's where Azeroth is trying to lead us. That's what we need to protect.", ["objectivesText"] = "Discuss the next steps, then follow up with Khadgar. Progress: Khaz Algar...", ["rewardGold"] = 28300, ["rewardXP"] = 1190, ["starts"] = { { ["x"] = 0.453, ["y"] = 0.574, ["mapID"] = 627, ["npcID"] = 213624 } }, ["ends"] = { { ["x"] = 0.453, ["y"] = 0.574, ["mapID"] = 627, ["npcID"] = 213624 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.453, ["y"] = 0.574 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 213624, ["questTurnInID"] = 213624, ["questType"] = "standard", ["sourceQuests"] = { 81966 }, ["questLines"] = { { ["id"] = 5513, ["name"] = "Visions of Azeroth", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5638, ["name"] = "Dalaran Intro", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 235, ["title"] = "Visions of Azeroth", ["questLineID"] = 5513, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5513, ["questLineOrder"] = 1 }, { ["id"] = 261, ["title"] = "Expansion Intro Skip", ["questLineID"] = 5638, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 629 },
[78718] = { ["id"] = 78718, ["name"] = "Strengthen the Wards", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 78529, 78713, 78714, 78715, 78716, 78717, 78718, 78719, 78721, 78722, 79105, 79106, 80321, 80500, 81930, 81966 }, ["description"] = "Magni's vision foretells that Khaz Algar may be enduring some... turbulent times. And so it is best to ensure that Dalaran is ready for the worst. Here, take this wand. It's been attuned with Dalaran 's defense magics. Just wave it near strategic parts of the city to strengthen our magical defenses.", ["objectivesText"] = "Strengthen Dalaran 's defenses. Progress: We will be hard pressed to save Khaz Algar if our own defenses aren't strong enough to withstand attack.", ["rewardGold"] = 216900, ["rewardXP"] = 7135, ["rewardItems"] = { 220483 }, ["starts"] = { { ["x"] = 0.564, ["y"] = 0.332, ["mapID"] = 627, ["npcID"] = 214665 } }, ["ends"] = { { ["x"] = 0.564, ["y"] = 0.332, ["mapID"] = 627, ["npcID"] = 214665 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.564, ["y"] = 0.332 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 214665, ["questTurnInID"] = 214665, ["questType"] = "standard", ["sourceQuests"] = { 78717 }, ["questLines"] = { { ["id"] = 5513, ["name"] = "Visions of Azeroth", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5638, ["name"] = "Dalaran Intro", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 235, ["title"] = "Visions of Azeroth", ["questLineID"] = 5513, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5513, ["questLineOrder"] = 1 }, { ["id"] = 261, ["title"] = "Expansion Intro Skip", ["questLineID"] = 5638, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 629 },
[78719] = { ["id"] = 78719, ["name"] = "Citizens of Dalaran", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 78529, 78713, 78714, 78715, 78716, 78717, 78718, 78719, 78721, 78722, 79105, 79106, 80321, 80500, 81930, 81966 }, ["description"] = "Our citizens must be prepared for Dalaran 's departure. Can you ask around the city and see if anyone requires aid? I'd also like for you to speak with Brann and Archmage Drenden. They both had concerns that would be best to address before we depart for Khaz Algar.", ["objectivesText"] = "Help the citizens of Dalaran prepare for the teleportation. Progress: Dalaran is always ready to defend the world, but that doesn't mean we can do so on a whim. Preparations are key to a smooth transportation.", ["rewardGold"] = 232300, ["rewardXP"] = 7135, ["starts"] = { { ["x"] = 0.412, ["y"] = 0.623, ["mapID"] = 627, ["npcID"] = 213627 } }, ["ends"] = { { ["x"] = 0.412, ["y"] = 0.623, ["mapID"] = 627, ["npcID"] = 213627 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.412, ["y"] = 0.623 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 213627, ["questTurnInID"] = 213627, ["questType"] = "standard", ["sourceQuests"] = { 78717 }, ["questLines"] = { { ["id"] = 5513, ["name"] = "Visions of Azeroth", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5638, ["name"] = "Dalaran Intro", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 235, ["title"] = "Visions of Azeroth", ["questLineID"] = 5513, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5513, ["questLineOrder"] = 1 }, { ["id"] = 261, ["title"] = "Expansion Intro Skip", ["questLineID"] = 5638, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 629 },
[78721] = { ["id"] = 78721, ["name"] = "Meet the Team", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 78529, 78713, 78714, 78715, 78716, 78717, 78718, 78719, 78721, 78722, 79105, 79106, 80321, 80500, 81930, 81966 }, ["description"] = "If we're going tae be exploring new lands in Khaz Algar, then we'll be needing help from the Explorers' League. But they won't be alone in this adventure. The League is teaming up with the Reliquary again, just like on the Dragon Isles. They're calling themselves the Algari Expedition this time around. I'm just a wee bit worried if they're still getting along. Exploring can tear folks apart just as easily as it binds them together. Can you check in on the lot?", ["objectivesText"] = "Check in on the Algari Expedition. Progress: A league and an expedition walk into a tavern... Nope, nothing's coming to me.", ["rewardGold"] = 144600, ["rewardXP"] = 4760, ["starts"] = { { ["x"] = 0.47, ["y"] = 0.491, ["mapID"] = 627, ["npcID"] = 214669 } }, ["ends"] = { { ["x"] = 0.47, ["y"] = 0.491, ["mapID"] = 627, ["npcID"] = 214669 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.47, ["y"] = 0.491 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 214669, ["questTurnInID"] = 214669, ["questType"] = "standard", ["sourceQuests"] = { 78717 }, ["questLines"] = { { ["id"] = 5513, ["name"] = "Visions of Azeroth", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5638, ["name"] = "Dalaran Intro", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 235, ["title"] = "Visions of Azeroth", ["questLineID"] = 5513, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5513, ["questLineOrder"] = 1 }, { ["id"] = 261, ["title"] = "Expansion Intro Skip", ["questLineID"] = 5638, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 629 },
[78722] = { ["id"] = 78722, ["name"] = "To Khaz Algar!", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15177, ["mapID"] = 2305, ["storyline"] = { 78529, 78713, 78714, 78715, 78716, 78717, 78718, 78719, 78721, 78722, 79105, 79106, 80321, 80500, 81930, 81966 }, ["description"] = "From what Magni has seen, Khaz Algar may not be the safest of destinations. We'll be relying on your aid, should a fight break out. Let me know when you're ready to depart.", ["objectivesText"] = "Tell Khadgar you're ready to depart.", ["rewardGold"] = 28300, ["rewardXP"] = 1190, ["starts"] = { { ["x"] = 0.412, ["y"] = 0.623, ["mapID"] = 627, ["npcID"] = 213627 } }, ["ends"] = { { ["npcID"] = 214908, ["x"] = 0.502, ["y"] = 0.504, ["mapID"] = 2305 } }, ["coords"] = { ["mapID"] = 627, ["x"] = 0.412, ["y"] = 0.623 }, ["mapCandidates"] = { ["npc"] = { 2305 }, ["zone"] = { 15177 } }, ["questGiverID"] = 213627, ["questType"] = "standard", ["sourceQuests"] = { 78718, 78719, 78721 }, ["questLines"] = { { ["id"] = 5513, ["name"] = "Visions of Azeroth", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5638, ["name"] = "Dalaran Intro", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 235, ["title"] = "Visions of Azeroth", ["questLineID"] = 5513, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5513, ["questLineOrder"] = 1 }, { ["id"] = 261, ["title"] = "Expansion Intro Skip", ["questLineID"] = 5638, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2731, ["db2PoiUiMapID"] = 2305 },
[78724] = { ["id"] = 78724, ["name"] = "Loving Yourself, Your Way", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Love is in the Air", ["expansion"] = 10, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 78724 }, ["description"] = "If it's a challenge you're after, I think I have an idea. I saw a boastful champion heading toward Goldshire. You could challenge him to a duel. This would satisfy your desire and perhaps teach him a valuable lesson in humility.", ["objectivesText"] = "Defeat Matley Graston in a duel near Goldshire. Progress: How fares your challenge?", ["rewardGold"] = 89550, ["rewardXP"] = 1415, ["rewardItems"] = { 49927 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 213262, ["x"] = 0.35, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 213262, ["x"] = 0.35, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["sourceQuests"] = { 78664 }, ["db2LabelIDs"] = { 3027 } },
[78726] = { ["id"] = 78726, ["name"] = "Loving Yourself, Your Way", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Love is in the Air", ["expansion"] = 10, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 78726 }, ["description"] = "A full belly is a happy belly! There is plenty of good food and drink right here at the gala. Why don't you buy yourself something nice?", ["objectivesText"] = "Consume treat packages from vendors at the Gala of Gifts. Progress: Have you had your fill of treats? I love the fruits, myself.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 49927, 210926, 210928, 210929, 239015 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 213262, ["x"] = 0.35, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 213262, ["x"] = 0.35, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["sourceQuests"] = { 78664 }, ["db2LabelIDs"] = { 3027 } },
[78727] = { ["id"] = 78727, ["name"] = "Loving Yourself, Your Way", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Love is in the Air", ["expansion"] = 10, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 78727 }, ["description"] = "While visiting this gala, I am staying at the Lion's Pride Inn at Goldshire. I hear they have some extra beds upstairs. Why not see if you can sleep there for a while? I think I will have a bit of a rest too... Right... here...", ["objectivesText"] = "Take a nap in the upstairs guest room at the Lion's Pride Inn. Progress: < Ying is quietly snoring.>", ["rewardGold"] = 79250, ["rewardXP"] = 1415, ["rewardItems"] = { 49927 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 213262, ["x"] = 0.35, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 213262, ["x"] = 0.35, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["sourceQuests"] = { 78664 }, ["db2LabelIDs"] = { 3027 } },
[78729] = { ["id"] = 78729, ["name"] = "Raising a Stink", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Love is in the Air", ["expansion"] = 10, ["zoneID"] = 12, ["mapID"] = 21, ["storyline"] = { 78729 }, ["series"] = { 78369, 78379 }, ["description"] = "Those clues add up to an ugly story, <name>. That map shows the Crown's got a heavily guarded base of operations in Silverpine Forest. And between that memo and formula, it looks like they're cooking up something intoxicatingly toxic. I've got a guy that can get us some... artisanal goods... to deal with the Crown. I'll go talk to him and meet you outside Shadowfang Keep.", ["objectivesText"] = "Meet Inspector Snagglebolt at the entrance to Shadowfang Keep in Silverpine Forest.", ["rewardGold"] = 28090, ["rewardXP"] = 25, ["rewardItems"] = { 139590, 140192, 211788 }, ["starts"] = { { ["npcID"] = 213560 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 38066, ["x"] = 0.458, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 12 } }, ["questGiverID"] = 213560, ["questType"] = "standard", ["sourceQuests"] = { 78337 }, ["db2LabelIDs"] = { 3027 } },
[78738] = { ["id"] = 78738, ["name"] = "Absent Speaker", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78738, 78741, 78742, 78760, 78761, 79354, 81689, 81798 }, ["description"] = "It is a dark day for the Ringing Deeps , $p. I always knew there was something about the High Speaker that wasn't quite right. Now we have proof. And we need justice. If he has plans for the Awakening Machine, then we've got to stop him.", ["objectivesText"] = "Meet Speaker Brinthe in the Earthenworks.", ["rewardGold"] = 283700, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212741, ["x"] = 0.4452, ["y"] = 0.2896 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 213569, ["x"] = 0.45, ["y"] = 0.206 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.4452, ["y"] = 0.2896 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 78706 }, ["questLines"] = { { ["id"] = 5535, ["name"] = "The Monster and the Machine", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5535, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5535, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214, ["db2QuestHubAreaPoiID"] = 7911 },
[78741] = { ["id"] = 78741, ["name"] = "Sympathetic Speakers", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78738, 78741, 78742, 78760, 78761, 79354, 81689, 81798 }, ["description"] = "I have to stop the High Speaker from making more skardyn. Machine Speaker protocol dictates that one of the foremen in this area should have a key to the Hall of Awakening. Come with me, and we'll track it down!", ["objectivesText"] = "Look for Machine Speaker Foremen in the Earthenworks with Speaker Brinthe .", ["rewardGold"] = 292100, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 213569, ["x"] = 0.45, ["y"] = 0.206 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 219428, ["x"] = 0.469, ["y"] = 0.172 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.206 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 78738 }, ["questLines"] = { { ["id"] = 5535, ["name"] = "The Monster and the Machine", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5535, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5535, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[78742] = { ["id"] = 78742, ["name"] = "Battle of the Earthenworks", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78738, 78741, 78742, 78760, 78761, 79354, 81689, 81798 }, ["description"] = "$p! There's a battle afoot! We need to assist Machine Speakers loyal to our cause and move against anyone defending the High Speaker. I'm going to remain and make plans with Adelgonn. I need you to lead our forces while we're containing consequences of the High Speaker's actions in the Earthenworks. This is our first step in deposing him. We're putting a stop to his horrendous crimes once and for all. What do you say, $p? Up for a scrap?", ["objectivesText"] = "Defeat enemy Machine Speakers, constructs, and help frightened workers in the Earthenworks! Progress: I'll admit: the ability to acquire an army at the drop of a hat has gotten me fairly far in life.", ["rewardGold"] = 292100, ["rewardXP"] = 9920, ["rewardItems"] = { 219360, 219370, 219372, 219377 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 213763, ["x"] = 0.464667, ["y"] = 0.188667 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 213763, ["x"] = 0.464667, ["y"] = 0.188667 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.464667, ["y"] = 0.188667 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 78738 }, ["questLines"] = { { ["id"] = 5535, ["name"] = "The Monster and the Machine", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5535, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5535, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[78743] = { ["id"] = 78743, ["name"] = "Before I Depart", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78743, 78744, 78745, 78746, 78747, 78748, 78749, 79335, 79336, 79337, 79338, 79339, 79340, 79341, 79342, 81661, 82895 }, ["series"] = { 78744 }, ["description"] = "I can feel my energy reserves depleting. I will soon not be able to execute my duties. That is why I have Urtago here to take over. Before my systems grind to a halt, I must make sure Mourning Rise is free of kobolds. They have invaded the memorial site I tend and plunder the Unbound shrines and bodies that are there. Maybe it is good you are here. You may have the strength to help us. Please, help Urtago rid the site of kobolds.", ["objectivesText"] = "Meet Urtago at the Mourning Rise memorial site.", ["rewardGold"] = 30900, ["rewardXP"] = 1190, ["rewardItems"] = { 219413 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 213184, ["x"] = 0.574, ["y"] = 0.43 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 213687, ["x"] = 0.616, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.574, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 81661 }, ["questLines"] = { { ["id"] = 5606, ["name"] = "Mourning Rise", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[78744] = { ["id"] = 78744, ["name"] = "Honor Their Memories", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78743, 78744, 78745, 78746, 78747, 78748, 78749, 79335, 79336, 79337, 79338, 79339, 79340, 79341, 79342, 81661, 82895 }, ["series"] = { 78743 }, ["description"] = "Take these gifts and place them by the past caretakers. Each is a gift honoring their memory. I'd also like us to perform some light groundskeeping to at least maintain the site. Unfortunately, what these kobolds are doing to the memorials will take us weeks to fix. Please do what you can about the kobolds. It would be unwise to leave the gifts unguarded while they are still roaming the area.", ["objectivesText"] = "Eliminate the kobold infestation and place gifts near the shut-down, past caretakers. Progress: The kobolds cannot be left to desecrate Mourning Rise. The Unbound that rest here are here because they do not want to be disturbed or moved. While they do not wish to be revived, taking their armor and possessions is an insult to earthen culture. We must do something.", ["rewardGold"] = 292100, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 213687, ["x"] = 0.616, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 213687, ["x"] = 0.616, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78743 }, ["questLines"] = { { ["id"] = 5606, ["name"] = "Mourning Rise", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[78745] = { ["id"] = 78745, ["name"] = "You No Take Plunder!", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78743, 78744, 78745, 78746, 78747, 78748, 78749, 79335, 79336, 79337, 79338, 79339, 79340, 79341, 79342, 81661, 82895 }, ["description"] = "It looks like the kobolds have taken gems and other... body parts off these shutdown earthen. Abominable. Find where the kobolds are holding their plunder, and bring it back to me so I can return it to its rightful place later. This vandalism will not go unchecked!", ["objectivesText"] = "Recover earthen belongings from piles of plunder. Progress: Were you able to find their plunder?", ["rewardGold"] = 289300, ["rewardXP"] = 9515, ["rewardItems"] = { 211428 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 213687, ["x"] = 0.616, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 213688, ["x"] = 0.632, ["y"] = 0.426 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78744 }, ["questLines"] = { { ["id"] = 5606, ["name"] = "Mourning Rise", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[78746] = { ["id"] = 78746, ["name"] = "Laws Apply to All", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78743, 78744, 78745, 78746, 78747, 78748, 78749, 79335, 79336, 79337, 79338, 79339, 79340, 79341, 79342, 81661, 82895 }, ["description"] = "Desecrating a memorial site is one of our greatest taboos in earthen society. This site is a window to our past, into our memories, and a place of self-reflection where we can commune with those who are no longer here. Still, so many of these kobolds infest Mourning Rise. For their crimes, the kobolds deserve the harshest punishment. They must be culled even further.", ["objectivesText"] = "Slay kobold invaders in Mourning Rise. Progress: So many of them still infest Mourning Rise.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 213687, ["x"] = 0.616, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 213688, ["x"] = 0.632, ["y"] = 0.426 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78744 }, ["questLines"] = { { ["id"] = 5606, ["name"] = "Mourning Rise", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[78747] = { ["id"] = 78747, ["name"] = "The Great Collapse", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78743, 78744, 78745, 78746, 78747, 78748, 78749, 79335, 79336, 79337, 79338, 79339, 79340, 79341, 79342, 81661, 82895 }, ["description"] = "Now that we landed a mighty blow, it is time to make sure that we block their tunnels so they cannot come back. Remember the stuff that Korgran asked about? Explosive sticks --his recipe. I have brought enough to shake a mountain! More than enough for the kobolds. Help me show these kobolds that we will fight for what is ours so they will never come back!", ["objectivesText"] = "Use the Explosive sticks to destroy Kobold tunnels . Progress: Is it done? Were the tunnels dealt with?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 211435 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 213688, ["x"] = 0.632, ["y"] = 0.426 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 213688, ["x"] = 0.632, ["y"] = 0.426 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.632, ["y"] = 0.426 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78745, 78746 }, ["questLines"] = { { ["id"] = 5606, ["name"] = "Mourning Rise", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[78748] = { ["id"] = 78748, ["name"] = "Cutting the Wick", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78743, 78744, 78745, 78746, 78747, 78748, 78749, 79335, 79336, 79337, 79338, 79339, 79340, 79341, 79342, 81661, 82895 }, ["description"] = "Knowing kobolds, they will have several workmasters, or leaders, running this raid. Find and eliminate these so-called \"workmasters.\" The rest of them will get disorganized, forget why they are here, and hopefully leave us alone.", ["objectivesText"] = "Find and slay the kobold workmasters. Progress: Were you able to slay all three of them? Their deaths will strike a significant blow to this kobold operation.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 213688, ["x"] = 0.632, ["y"] = 0.426 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 213688, ["x"] = 0.632, ["y"] = 0.426 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.632, ["y"] = 0.426 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78745, 78746 }, ["questLines"] = { { ["id"] = 5606, ["name"] = "Mourning Rise", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[78749] = { ["id"] = 78749, ["name"] = "Who Runs This Fine Establishment?", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78743, 78744, 78745, 78746, 78747, 78748, 78749, 79335, 79336, 79337, 79338, 79339, 79340, 79341, 79342, 81661, 82895 }, ["description"] = "While you were dealing with the tunnels and the workmasters, I saw a peculiar kobold go into a cave to the northwest. The kobolds seemed to respect him more than the others, calling him Grand-Heister Bokk and offering him the food you call \"cheese.\" This makes me think he is the real mastermind. If that kobold is in fact the real Ward of this operation, then we should take the opportunity to strike him down. I will meet you at this cave.", ["objectivesText"] = "Slay Grand-Heister Bokk .", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 213688, ["x"] = 0.632, ["y"] = 0.426 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 213187, ["x"] = 0.574, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.632, ["y"] = 0.426 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78747, 78748 }, ["questLines"] = { { ["id"] = 5606, ["name"] = "Mourning Rise", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[78754] = { ["id"] = 78754, ["name"] = "Lost Delivery", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78754, 78755, 78756, 78757, 78758, 78759 }, ["description"] = "<You find a small yet heavy leather-bound package on the road with an attached label.> Gundargaz Courier Express EXPEDITED To: Harvester Farnee Durgaz Cabin OPEN WITH CARE: Contains volatile elemental minerals.", ["objectivesText"] = "Deliver the Abandoned Package to Harvester Farnee at Durgaz Cabin.", ["rewardGold"] = 29500, ["rewardXP"] = 1190, ["starts"] = { { ["x"] = 0.551, ["y"] = 0.593, ["mapID"] = 2248, ["objectID"] = 423987 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 214640, ["x"] = 0.67, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78536 }, ["questLines"] = { { ["id"] = 5596, ["name"] = "Elemental Healing", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[78755] = { ["id"] = 78755, ["name"] = "Playing in the Mud", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78754, 78755, 78756, 78757, 78758, 78759 }, ["description"] = "Remember when we used that clay and the fire honey to patch up Shalehoof? Let's do that again but bigger! Problem is we've run out of clay. But fortunately, with all the recent seismic activity, a whole avalanche of elementals has been roused out of torpor and are clashing on the eastern beach! Bring me wet, elementally charged silt to use as our restorative substrate!", ["objectivesText"] = "Gather 20 handfuls of Elementally Charged Silt . Progress: By combining living sand and water, we can create an elemental silt that mimics the underclay's healing properties. Or at least something that comes close to it! Isn't elemental fusion fascinating?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 211483, 211484, 211485 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 214921, ["x"] = 0.67, ["y"] = 0.474 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 214921, ["x"] = 0.67, ["y"] = 0.474 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.474 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78758 }, ["questLines"] = { { ["id"] = 5596, ["name"] = "Elemental Healing", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[78756] = { ["id"] = 78756, ["name"] = "Lots and Lots of Fire Honey", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78754, 78755, 78756, 78757, 78758, 78759 }, ["description"] = "If Harmot wants to patch this sleeping boulder up and get him out of my pond, I'm all for it. Unfortunately, we used the last of my store of fire honey on Shalehoof's wound. I haven't had time to harvest any from the Cinderwold with all these elementals running amok. Head on down to the wold's edge and bring us some honey. You're going to need a lot.", ["objectivesText"] = "Find a lot of Fire Honey. Progress: Mind yourself in my forest. Cinderbees are dangerous, but we rely on them for the honey they produce for our mead.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 211489 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 214922, ["x"] = 0.67, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 214922, ["x"] = 0.67, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78758 }, ["questLines"] = { { ["id"] = 5596, ["name"] = "Elemental Healing", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[78757] = { ["id"] = 78757, ["name"] = "Honey and Clay the Pain Away", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78754, 78755, 78756, 78757, 78758, 78759 }, ["description"] = "Ramoliths! Magnificent, aren't they? One of the finest elemental beasts on the isle. The bad news is they're not immune to injury. Poor Shalehoof here was attacked by awakened elementals in Farnee's pond. The good news is that we have all we need to tend to him. We just have to mix that clay you found with some fire honey and slap it up on ol' Shalehoof's hock! Ready?", ["objectivesText"] = "Help Harmot prepare Shalehoof's salve. Progress: Much like us earthen, healing something made from rock and stone is no easy task. But the unique properties of the clay you've brought, combined with the fusing properties of the honey makes for an excellent restorative!", ["rewardGold"] = 292100, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 213691, ["x"] = 0.67, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 213691, ["x"] = 0.67, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78754 }, ["questLines"] = { { ["id"] = 5596, ["name"] = "Elemental Healing", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[78758] = { ["id"] = 78758, ["name"] = "Pulse Within the Earth", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78754, 78755, 78756, 78757, 78758, 78759 }, ["description"] = "Before we go and wake up a slumbering mountain giant, it's probably best we get an idea for how deeply asleep he is. Though, if the nerubians burrowing up didn't wake him up, I'm not sure what will. Take these earth shards and plant them on the waterfalls and hills around the lake. Once we've got them set up, I'll be able to get a reading on the giant's health.", ["objectivesText"] = "Place 4 Tremor Stones around the pond. Progress: Once you've got the shards set up, I can drop the final one here to get a proper read.", ["rewardGold"] = 292100, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 213691, ["x"] = 0.67, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 214921, ["x"] = 0.67, ["y"] = 0.474 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78757 }, ["questLines"] = { { ["id"] = 5596, ["name"] = "Elemental Healing", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[78759] = { ["id"] = 78759, ["name"] = "To Wake a Giant", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78754, 78755, 78756, 78757, 78758, 78759 }, ["description"] = "By the Coreway, this stuff packs a punch! Combining healing silt with the molten fusion properties of fire honey has given us a salve that could wake a whole mountain! Which is exactly what you'll do. Take the mixture over to our wounded friend in Farnee's pond, and slap it on his hide! It should be enough to wake him up and alleviate any soreness. Hopefully, anyways.", ["objectivesText"] = "Apply elemental salve to the mountain giant for Harmot . Progress: This will either wake the giant and patch him up good as new or... Well, let's not talk about the other possibility. Have some faith in the process!", ["rewardGold"] = 292100, ["rewardXP"] = 9515, ["rewardItems"] = { 228380, 253166 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 25 }, { ["id"] = 2897, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 214921, ["x"] = 0.67, ["y"] = 0.474 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 214921, ["x"] = 0.67, ["y"] = 0.474 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.474 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78755, 78756 }, ["questLines"] = { { ["id"] = 5596, ["name"] = "Elemental Healing", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[78760] = { ["id"] = 78760, ["name"] = "Dark Iron from Above", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78738, 78741, 78742, 78760, 78761, 79354, 81689, 81798 }, ["series"] = { 78761 }, ["description"] = "We've done our best to contain the High Speaker's followers. We've hampered their efforts at destroying or looting anything they can take with them into Hall of Awakening. Now, we just need to deal with the leader of their forces before they can coordinate a more unified resistance. Are you ready to do this, <name>?", ["objectivesText"] = "Defeat Supervisor Varric and his forces within the Earthenworks.", ["rewardGold"] = 619600, ["rewardXP"] = 12400, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 213763, ["x"] = 0.464667, ["y"] = 0.188667 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 213796, ["x"] = 0.452, ["y"] = 0.097333 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.464667, ["y"] = 0.188667 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 78741, 78742, 81798 }, ["questLines"] = { { ["id"] = 5535, ["name"] = "The Monster and the Machine", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5535, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5535, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[78761] = { ["id"] = 78761, ["name"] = "Into the Machine", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78459, 78461, 78462, 78529, 78530, 78531, 78532, 78533, 78544, 78545, 78546, 78704, 78705, 78706, 78761, 78837, 79105, 79106, 80022, 80321, 80334, 80434, 91864 }, ["series"] = { 78760 }, ["description"] = "No time to catch our breath! The High Speaker is fleeing to the earthen's most sacred machine. We need to follow him. Remember, we're doing this for the earthen! For justice! For all the brothers and sisters and comrades who've fallen to the High Speaker's hubris!", ["objectivesText"] = "Confront the High Speaker inside the Hall of Awakening.", ["rewardGold"] = 876300, ["rewardXP"] = 14880, ["rewardItems"] = { 219018, 253020 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 213796, ["x"] = 0.452, ["y"] = 0.097333 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212742, ["x"] = 0.45, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.097333 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 78760 }, ["questLines"] = { { ["id"] = 5535, ["name"] = "The Monster and the Machine", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 6008, ["name"] = "Catch Up: War Within: Wrapper 2", ["orderIndex"] = 22, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5535, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5535, ["questLineOrder"] = 7 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6008, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[78762] = { ["id"] = 78762, ["name"] = "Your First Find", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "We've got a find on our hands! Looks like this might be one of my books from undergrad. Hah! Now, your job is to get all that dirt off of it, but you have to be careful. The artifacts we handle are very fragile, and the only thing worse than them staying in the ground is them breaking on the way out. Empowering your elemental will only get you halfway. You'll need to use your environment to keep things in balance so that it's safe to excavate.", ["objectivesText"] = "Practice excavating on the Outdated Geology Textbook . Progress: What do you think? Having fun yet?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 210956 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 208614, ["x"] = 0.615, ["y"] = 0.306 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 208614, ["x"] = 0.615, ["y"] = 0.306 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 77267 }, ["questLines"] = { { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
