[78821] = { ["id"] = 78821, ["name"] = "Blooming Dreamseeds", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78821 }, ["description"] = "The Emerald Dream is about the harmony and balance of nature. For Amirdrassil to bloom, we need a rich variety of plants growing alongside the world tree. Plant seeds wherever you find fertile soil.", ["objectivesText"] = "Plant dreamseeds in the Emerald Dream . Progress: How's the planting going?", ["rewardItems"] = { 211376, 211394 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 212797, ["x"] = 0.498, ["y"] = 0.62 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 212797, ["x"] = 0.498, ["y"] = 0.62 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200 },
[78827] = { ["id"] = 78827, ["name"] = "Go Take Candle!", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78827, 78860, 78879, 78900, 78918, 83326 }, ["description"] = "Ksk, ksk! You there! Yes, you! We, er, I have job for you! You look sharp. Look quick. Fast hands, just like us--me! Quick hands just like me. Bring us, me, bring me candles ! Yes! No ask question, just go get candles . We are, er, I am professional, yes. Professionals do not ask questions. Only get candles .", ["objectivesText"] = "Steal candles for the suspicious vent in the Gundargaz Inn. Progress: You have candles ?", ["rewardGold"] = 154900, ["rewardXP"] = 4960, ["rewardItems"] = { 58902, 58903, 58904, 58905, 156935, 226155, 226156, 228711, 248797 }, ["starts"] = { { ["npcID"] = 413694, ["x"] = 0.481, ["y"] = 0.32, ["mapID"] = 2214 } }, ["ends"] = { { ["npcID"] = 413694, ["x"] = 0.481, ["y"] = 0.32, ["mapID"] = 2214 } }, ["coords"] = { ["x"] = 0.481, ["y"] = 0.32, ["source"] = "quest_giver", ["mapID"] = 2214 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5656, ["name"] = "Exploring Gundargaz", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[78837] = { ["id"] = 78837, ["name"] = "Pomp and Dire Circumstance", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78555, 78557, 78631, 78634, 78635, 78636, 78637, 78638, 78639, 78640, 78641, 78642, 78837, 78838, 78839, 79205, 79267, 80082, 80434, 83550 }, ["series"] = { 78631, 78838 }, ["description"] = "I'm seeing legitimate concerns. We have to do something about the nerubians... even if the High Speaker won't. If he won't do something, I will. The High Speaker sent me to the surface because I wasn't \"reasonable.\" I think we should have a chance to... reason... with him. We'll need to go to Gundargaz.", ["objectivesText"] = "Meet Speaker Brinthe in Gundargaz. Progress: That is... never pleasant.", ["rewardGold"] = 77400, ["rewardXP"] = 2480, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212592, ["x"] = 0.4, ["y"] = 0.284 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212741, ["x"] = 0.4452, ["y"] = 0.2896 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.284 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 78555, 78557 }, ["questLines"] = { { ["id"] = 5533, ["name"] = "By Candlelight", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 6008, ["name"] = "Catch Up: War Within: Wrapper 2", ["orderIndex"] = 18, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5533, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5533, ["questLineOrder"] = 5 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6008, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[78838] = { ["id"] = 78838, ["name"] = "Cogs in the Machine", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78555, 78557, 78631, 78634, 78635, 78636, 78637, 78638, 78639, 78640, 78641, 78642, 78837, 78838, 78839, 79205, 79267, 80082, 80434, 83550 }, ["series"] = { 78631, 78837 }, ["description"] = "Gundargaz is my home. Or at least, it was before the High Speaker saw fit to reassign me above ground. I've missed my home, but it's... changed. As the number of Machine Speakers decreases, we're in a race against time. Lately, we've been especially weary of our assigned tasks, but as always, we must bear our burdens. Let me show you around the area. There are some earthen I would like you to meet.", ["objectivesText"] = "Accompany Brinthe as they talk to earthen in Gundargaz. Progress: This is not how I remember my home.", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212741, ["x"] = 0.4452, ["y"] = 0.2896 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212741, ["x"] = 0.4452, ["y"] = 0.2896 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.4452, ["y"] = 0.2896 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 78837 }, ["questLines"] = { { ["id"] = 5533, ["name"] = "By Candlelight", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5533, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5533, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214, ["db2QuestHubAreaPoiID"] = 7911 },
[78839] = { ["id"] = 78839, ["name"] = "Kobold Shoulder", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78555, 78557, 78631, 78634, 78635, 78636, 78637, 78638, 78639, 78640, 78641, 78642, 78837, 78838, 78839, 79205, 79267, 80082, 80434, 83550 }, ["description"] = "The first step to stemming our losses and retaking the mines is straightforward, if unpleasant. Without minions, this Candle King will be less of a threat to Gundargaz. See if you can reduce the swarm, <name>, before hostilities escalate further.", ["objectivesText"] = "Kill invading kobolds in the Lost Mines. Progress: This should never have happened.", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212519, ["x"] = 0.555, ["y"] = 0.292 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212519, ["x"] = 0.555, ["y"] = 0.292 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.292 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 78631 }, ["questLines"] = { { ["id"] = 5533, ["name"] = "By Candlelight", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5533, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5533, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[78860] = { ["id"] = 78860, ["name"] = "More Candles!", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78827, 78860, 78879, 78900, 78918, 83326 }, ["description"] = "I, er, we...no, no, I! I have new deal for you, oh shadowy one. More candles ! In return, you get... er... You get more candles ! Then you give to us! To me! candles ! candles ! candles !", ["objectivesText"] = "Steal more candles for the suspicious vent in the Gundargaz Inn. Progress: You have candles ? More candles ?", ["rewardGold"] = 154900, ["rewardXP"] = 4960, ["starts"] = { { ["npcID"] = 413694, ["x"] = 0.481, ["y"] = 0.32, ["mapID"] = 2214 } }, ["ends"] = { { ["npcID"] = 413694, ["x"] = 0.481, ["y"] = 0.32, ["mapID"] = 2214 } }, ["coords"] = { ["x"] = 0.481, ["y"] = 0.32, ["source"] = "quest_giver", ["mapID"] = 2214 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 78827 }, ["questLines"] = { { ["id"] = 5656, ["name"] = "Exploring Gundargaz", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
