[78863] = { ["id"] = 78863, ["name"] = "A Place Beneath the Boughs", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 78863 }, ["description"] = "Thanks to you and all the mortals who defended the Emerald Dream, a new World Tree now grows in the Dragon Isles. Amirdrassil 's boughs will be a haven of peace and tranquility, and a place of respite for the kaldorei souls lost at Teldrassil. Tyrande Whisperwind and Shandris Feathermoon are at the tree now. They would share words with you.", ["objectivesText"] = "Meet Tyrande and Shandris in Amirdrassil .", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 212981, 213003, 213004, 213005, 213006, 213007, 213008, 213009, 213010, 213011, 213012, 213013, 213160 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 187678, ["x"] = 0.583778, ["y"] = 0.357111 } }, ["ends"] = { { ["mapID"] = 2239, ["npcID"] = 216067, ["x"] = 0.512667, ["y"] = 0.606667 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.583778, ["y"] = 0.357111 }, ["mapCandidates"] = { ["npc"] = { 2112, 2239 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 78643 } },
[78864] = { ["id"] = 78864, ["name"] = "The Returning", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15105, ["mapID"] = 2239, ["storyline"] = { 78864 }, ["description"] = "It is a time of reflection and change, $p. For the world, and for my people. My mother and I have been discussing the roads that led us here... and where those roads will lead in the years to come. Come, let us speak.", ["objectivesText"] = "Speak with Shandris Feathermoon .", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 212981, 213003, 213004, 213005, 213006, 213007, 213008, 213009, 213010, 213011, 213012, 213013, 213160, 251022 }, ["starts"] = { { ["mapID"] = 2239, ["npcID"] = 216067, ["x"] = 0.512667, ["y"] = 0.606667 } }, ["ends"] = { { ["mapID"] = 2239, ["npcID"] = 216067, ["x"] = 0.512667, ["y"] = 0.606667 } }, ["coords"] = { ["mapID"] = 2239, ["source"] = "quest_giver", ["x"] = 0.512667, ["y"] = 0.606667 }, ["mapCandidates"] = { ["npc"] = { 2239 }, ["zone"] = { 15105 } }, ["questType"] = "standard", ["sourceQuests"] = { 78863 } },
[78865] = { ["id"] = 78865, ["name"] = "Siblings Until the End", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 75918, 75919, 75920, 75921, 75922, 75923, 76276, 76280, 76281, 76282, 76283, 76317, 76318, 76319, 76320, 76321, 76322, 76323, 76324, 76325, 76326, 76327, 76328, 76329, 76330, 76331, 76332, 76333, 76334, 76335, 76336, 76337, 76342, 76343, 76344, 76345, 76347, 76348, 76384, 76385, 76386, 76387, 76388, 76389, 76398, 76401, 76402, 76403, 76416, 76433, 76434, 76435, 76436, 76437, 76441, 76442, 76443, 76532, 77178, 77200, 77201, 77283, 77329, 77436, 77780, 77781, 77818, 78643, 78646, 78865, 92875 }, ["series"] = { 78643, 92875 }, ["description"] = "Some time ago, Vyranoth received an unexpected summons... from Iridikron. You will want to hear what he had to say.", ["objectivesText"] = "Speak with Vyranoth to hear about her meeting with Iridikron. Progress: Iridikron had much to say...", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 212981, 213003, 213004, 213005, 213006, 213007, 213008, 213009, 213010, 213011, 213012, 213013, 213160 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 214051, ["x"] = 0.5576, ["y"] = 0.3684 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 214051, ["x"] = 0.5576, ["y"] = 0.3684 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.5576, ["y"] = 0.3684 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 78643 }, ["questLines"] = { { ["id"] = 5965, ["name"] = "The Emerald Dream", ["orderIndex"] = 69, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 256, ["title"] = "Dragonflight", ["questLineID"] = 5965, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
[78874] = { ["id"] = 78874, ["name"] = "Conjured Help", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78874, 78879, 78900, 78918 }, ["description"] = "If you're looking for food--softy food--I'm afraid we're clean out. Nothing but good ol' rocks and gems here at the moment. It's starting to become a problem, actually. Say... you wouldn't be able to do anything about that, would you? Rustle us up some victuals for the fleshy folk?", ["objectivesText"] = "Summon food for Innkeeper Brax in the Gundargaz Inn. Progress: You don't want to try a nibble of cobalt?", ["rewardGold"] = 146000, ["rewardXP"] = 4960, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 213840, ["x"] = 0.459, ["y"] = 0.322 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 213840, ["x"] = 0.459, ["y"] = 0.322 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.459, ["y"] = 0.322 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5656, ["name"] = "Exploring Gundargaz", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214, ["db2QuestHubAreaPoiID"] = 7911 },
[78875] = { ["id"] = 78875, ["name"] = "The Unkillable", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 8 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 33, ["mapID"] = 50, ["storyline"] = { 77869, 77871, 77874, 77877, 77879, 77880, 77881, 77882, 77894, 77898, 77899, 77900, 77901, 77902, 77903, 77905, 77906, 78875 }, ["description"] = "I'm bettin' dat ogre Mai'Zoth is behind all dis. He should have died long ago, but his magics still be strong. He be using the altar's centerpiece as a conduit to drain Lukou's power. Recover the centerpiece and prove he's not so unkillable when he doesn't have a loa hostage.", ["objectivesText"] = "Recover the altar centerpiece from Mai'Zoth. Progress: Did you prove Mai'Zoth isn't unkillable?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 210593 }, ["starts"] = { { ["mapID"] = 50, ["npcID"] = 210091, ["x"] = 0.663333, ["y"] = 0.459 } }, ["ends"] = { { ["mapID"] = 50, ["npcID"] = 210091, ["x"] = 0.663333, ["y"] = 0.459 } }, ["coords"] = { ["mapID"] = 50, ["source"] = "quest_giver", ["x"] = 0.663333, ["y"] = 0.459 }, ["mapCandidates"] = { ["npc"] = { 50 }, ["zone"] = { 33 } }, ["questType"] = "standard", ["sourceQuests"] = { 77877 }, ["questLines"] = { { ["id"] = 5504, ["name"] = "Darkspear Troll Heritage Armor", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 50 },
[78876] = { ["id"] = 78876, ["name"] = "A Glowing Memento", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 78876 }, ["description"] = "<An unusually persistent ember draws your eye. It glows with a pure, primal heat.> < Vyranoth would be interested in this.>", ["objectivesText"] = "Bring the Everglowing Ember to Vyranoth in Amirdrassil or the Central Encampment in the Emerald Dream. Provided item:", ["rewardGold"] = 3370800, ["rewardItems"] = { 210537, 211375 }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208506, ["x"] = 0.508, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "raid", ["startItems"] = { 211375 } },
[78877] = { ["id"] = 78877, ["name"] = "Bless These Homes", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["requiredClasses"] = { 2, 5 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78877, 78879, 78900, 78918 }, ["description"] = "Divine presence acknowledged. Every day for as long as my memory serves me, I have walked the routes and lit the incense around our homes. It has ground my joints to dust, but is it an important task. A sacred task. These are dark times we live in--perhaps you could add your own beatitudes to our little rituals?", ["objectivesText"] = "Bless the incense around Gundargaz. Progress: You do us an honor, bringing your faith into these caverns. Let it bless these machines and those who work with them, just as they bless us in turn.", ["rewardGold"] = 154900, ["rewardXP"] = 4960, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 213875, ["x"] = 0.449, ["y"] = 0.324 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 213875, ["x"] = 0.449, ["y"] = 0.324 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.449, ["y"] = 0.324 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5656, ["name"] = "Exploring Gundargaz", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214, ["db2QuestHubAreaPoiID"] = 7911 },
[78879] = { ["id"] = 78879, ["name"] = "Evoking the Forge", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["requiredRaces"] = { 52, 70 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78827, 78860, 78874, 78877, 78879, 78895, 78900, 78918, 83326 }, ["description"] = "Harumph! This blasted forge is on its last legs. We'd repair it, but Stonemason Itsak picked up a shift at Ironhaul Station when the Coreway collapsed, and well... There's no one to fix it anymore. If you can figure out a way of getting it running hot again, Gundargaz would be in your debt!", ["objectivesText"] = "Find a way to stoke the forge outside of Gundargaz. Progress: I'm going to miss Itsak. He made the best end-of-shift rock roasts...", ["rewardGold"] = 154900, ["rewardXP"] = 4960, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 213841, ["x"] = 0.453, ["y"] = 0.284 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 213841, ["x"] = 0.453, ["y"] = 0.284 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.453, ["y"] = 0.284 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5656, ["name"] = "Exploring Gundargaz", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214, ["db2QuestHubAreaPoiID"] = 7911 },
