[78893] = { ["id"] = 78893, ["name"] = "A Scrap of Bronze", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = { "campaign" }, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 78893 }, ["description"] = "The vendors of Pandaria do not want the equipment you will find in this timeline. You can convert unwanted equipment into Bronze using the magic of the infinite dragonflight. Use the Unraveling Sands ability and scrap the Unraveling Tunic .", ["objectivesText"] = "Use the Unraveling Sands ability to summon Unraveling Sands, then place the Unraveling Tunic in the Unraveling Sands to scrap it into Bronze . Progress: You can place unwanted equipment into the Unraveling Sands to obtain additional Bronze for your journey.", ["rewardItems"] = { 210526, 217174 }, ["rewardCurrencies"] = { { ["id"] = 2778, ["amount"] = 20 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["sourceQuests"] = { 79440 }, ["startItems"] = { 210526 } },
