[78895] = { ["id"] = 78895, ["name"] = "A Shadow Over Gundargaz", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["requiredClasses"] = { 9, 12 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78879, 78895, 78900, 78918 }, ["description"] = "You look dangerous. <Toki spits on the ground.> That's good. We need dangerous. Something is stalking Gundargaz. Something mean. Something... recent. Just before the Coreway collapsed I started getting reports of workers going missing mid-shift. Only thing we've been able to find have been the odd chunk of rock. Fingers, mostly. If you could sniff out what's stalking my town, I'd be in your debt.", ["objectivesText"] = "Track down whatever is hunting the earthen in Gundargaz. Progress: Life didn't always used to be this exciting.", ["rewardGold"] = 154900, ["rewardXP"] = 4960, ["rewardItems"] = { 219919, 219923 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 213869, ["x"] = 0.459, ["y"] = 0.348 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 213869, ["x"] = 0.459, ["y"] = 0.348 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.459, ["y"] = 0.348 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 78838 }, ["questLines"] = { { ["id"] = 5656, ["name"] = "Exploring Gundargaz", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214, ["db2QuestHubAreaPoiID"] = 7911 },
[78897] = { ["id"] = 78897, ["name"] = "Boom or Blight", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78897, 78898, 78901, 78902, 79349 }, ["description"] = "This place is infested with cave borers. They pose a threat to the great roots that stretch through this place. Yes, the tree provides sustenance for many living things, but this is not some small band of bugs nibbling on a leaf. This is a blight. Their numbers must be culled for the good of the whole. By my oath I am unable to raise a hand to interfere. However... you have sworn no such oath. Will you do what must be done?", ["objectivesText"] = "Cull 10 worms of the Wormlands. Progress: How fares the blight?", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 211652, ["x"] = 0.422, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 211652, ["x"] = 0.422, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 83321 }, ["questLines"] = { { ["id"] = 5565, ["name"] = "The Wormlands", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[78898] = { ["id"] = 78898, ["name"] = "Intention vs Instinct", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78897, 78898, 78901, 78902, 79349 }, ["description"] = "Cave borers are not social creatures as a rule. Seeing this many gather in one place speaks to intention. A wormcaller of the nerubians must be present. Find them and recover the tool they use to call these worms here. With it we can lead them away in time.", ["objectivesText"] = "Collect a Singing Stone from Wormcaller Iz'tikrine. Progress: I can sense more worms coming. As if they are drawn to this place.", ["rewardGold"] = 619600, ["rewardXP"] = 13245, ["rewardItems"] = { 211412 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 211652, ["x"] = 0.422, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 211652, ["x"] = 0.422, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 83321 }, ["questLines"] = { { ["id"] = 5565, ["name"] = "The Wormlands", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[78900] = { ["id"] = 78900, ["name"] = "On Cold, Dark Wings", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78827, 78860, 78874, 78877, 78879, 78895, 78900, 78918, 83326 }, ["description"] = "You came down the Coreway, right? From up top? <Toki chuckles.> They have it easy, those city earthen. Down here, death comes for you from all around. From below. From above. You look like you've killed a fair few beasts in your time. Care to add another to the list?", ["objectivesText"] = "Track down the Ringing Death in Gundargaz. Progress: Keep quiet, that's my advice.", ["rewardGold"] = 154900, ["rewardXP"] = 4960, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 213869, ["x"] = 0.459, ["y"] = 0.348 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 213869, ["x"] = 0.459, ["y"] = 0.348 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.459, ["y"] = 0.348 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 78838, 79573 }, ["questLines"] = { { ["id"] = 5656, ["name"] = "Exploring Gundargaz", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214, ["db2QuestHubAreaPoiID"] = 7911 },
[78901] = { ["id"] = 78901, ["name"] = "Heeeelllp!!!", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78897, 78898, 78901, 78902, 79349 }, ["description"] = "Hey! You! Get me down! Away from these worms! Please! I'll pay you! I'll even owe you one! Heck, I'll gladly sell out any cartel member you need dirt on! Just get me down! Also, don't walk too much. They can hear your footsteps. Move from rock to rock if you don't want a swarm coming after you.", ["objectivesText"] = "Rescue Skedgit Cinderbangs .", ["rewardGold"] = 154900, ["rewardXP"] = 5300, ["starts"] = { { ["x"] = 0.416, ["y"] = 0.421, ["mapID"] = 2255 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 214168, ["x"] = 0.408, ["y"] = 0.398 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.398 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 83321 }, ["questLines"] = { { ["id"] = 5565, ["name"] = "The Wormlands", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[78902] = { ["id"] = 78902, ["name"] = "Delegated Dig", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78897, 78898, 78901, 78902, 79349 }, ["description"] = "Okay, I know when I'm beat. So I want to hire you as my Champion of Coin... or coinchamp. This is all a part of my brilliant enterprising venture. See, these worms here are great at rooting out rich minerals like a niffen sniffing out high-quality mushrooms. I'm willing to bet all of my money--and your life--that they found a vein of sivstone. Great stuff, though I doubt a <class> would know how to use it. Tell you what, you bring me a shipment's worth and I'll go halfsies on the profits with ya!", ["objectivesText"] = "Acquire 25 Chunks of Sivstone. Progress: You get the goods?", ["rewardGold"] = 292100, ["rewardXP"] = 10595, ["rewardItems"] = { 211415 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 214168, ["x"] = 0.408, ["y"] = 0.398 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 214168, ["x"] = 0.408, ["y"] = 0.398 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.398 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 78901 }, ["questLines"] = { { ["id"] = 5565, ["name"] = "The Wormlands", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[78915] = { ["id"] = 78915, ["name"] = "Squashing the Threat", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78915 }, ["description"] = "I need your help! The massive Shadow-Soured squash have begun to grow all over the place. They're stinky and crawling with nasty mites. Mom and Dad brought in some airships to help us yank them out, but it's risky business with all those bugs. Can you attach ropes to these Shadow-Soured Squash, and the airships can then haul them away without making a mess?", ["objectivesText"] = "Remove 8 Shadow-Sour Squash and slay 10 Shadow-Sour Mites . Progress: Have you removed all the Squash?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 2899, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 214428, ["x"] = 0.636, ["y"] = 0.338 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 214428, ["x"] = 0.636, ["y"] = 0.338 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.636, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78458 } },
[78918] = { ["id"] = 78918, ["name"] = "Brax's Brass Knuckles", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78827, 78860, 78874, 78877, 78879, 78895, 78900, 78918, 83326 }, ["description"] = "I have a proposition for you. We get some rowdy patrons here from time to time. Nothing sinister, but our folk work hard and things can get out of hand faster than a dropped hammer. Usually I'd give 'em a considerate knock upside the head to remind them what's what, but I lost my brass knuckles while helping Watcher Toki clear monsters on the town's skirts. Mind fetching my knuckles and administering some love taps?", ["objectivesText"] = "Kill creatures around Gundargaz to find Brax's Brass Knuckles . Progress: Now which beasts did I punch with those knuckles last...", ["rewardGold"] = 154900, ["rewardXP"] = 4960, ["rewardItems"] = { 211493, 219379, 225709, 225710, 225715, 225716, 225718 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 213840, ["x"] = 0.459, ["y"] = 0.322 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 213840, ["x"] = 0.459, ["y"] = 0.322 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.459, ["y"] = 0.322 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79573, 80434 }, ["questLines"] = { { ["id"] = 5656, ["name"] = "Exploring Gundargaz", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214, ["db2QuestHubAreaPoiID"] = 7911 },
[78929] = { ["id"] = 78929, ["name"] = "Tricks of the Dark", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78672, 78929, 78932, 78934, 78936, 78937, 78939, 78951, 78952, 78954, 81690 }, ["description"] = "Kobyss lurk in the shallows of murky water and snatch any who come near, faster than a viper! And that's just when they hunt alone. In numbers, they are a swarm to be reckoned with. They've been a plague on our outskirt villages since the day we arrived. They eat victims alive, given the chance. We must rescue the villagers that have already been dragged to the water!", ["objectivesText"] = "Rescue 5 Arathi captives .", ["rewardGold"] = 292100, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 214378, ["x"] = 0.538, ["y"] = 0.314 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 214377, ["x"] = 0.5516, ["y"] = 0.3632 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.314 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78672 }, ["questLines"] = { { ["id"] = 5530, ["name"] = "Gathering Shadows", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5530, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5530, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[78932] = { ["id"] = 78932, ["name"] = "Fickle Fiendish Fish", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78672, 78929, 78932, 78934, 78936, 78937, 78939, 78951, 78952, 78954, 81690 }, ["description"] = "Judging by the glint in your eye, you wish to join Faerin in this madness? To push into the kobyss waters? In the darkness? You are a fool with a death wish. Take as many of those damnable fish out as you can, before they drag you into the depths for their dinner.", ["objectivesText"] = "Kill 13 kobyss invaders. Progress: We can't abandon the villagers here!", ["rewardGold"] = 283700, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 214376, ["x"] = 0.545, ["y"] = 0.32 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 214377, ["x"] = 0.5516, ["y"] = 0.3632 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.545, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78672 }, ["questLines"] = { { ["id"] = 5530, ["name"] = "Gathering Shadows", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5530, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5530, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[78933] = { ["id"] = 78933, ["name"] = "The Sweet Eclipse", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78933 }, ["description"] = "I've set out to create a dessert that transcends the ordinary, one that even the most devout followers of the light would savor! To balance the flavors of the desert, between light and shadow, I require ingredients from several areas within the darkness. Please assist me in harvesting the following ingredients: Frog-Kissed Caviar , Darkroot Persimmon and Ethereal Sugar .", ["objectivesText"] = "Collect 8 Darkroot Persimmon , 30 Frog-Kissed Caviar , and 1 Ethereal Sugar . Progress: Have you found all of the ingredients?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 211478, 211479, 212491, 219808, 228741 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 40 }, { ["id"] = 2899, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 206533, ["x"] = 0.644, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 206533, ["x"] = 0.644, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.644, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78466 } },
[78934] = { ["id"] = 78934, ["name"] = "Blades of the Arathi", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78672, 78929, 78932, 78934, 78936, 78937, 78939, 78951, 78952, 78954, 81690 }, ["description"] = "I trust in your strength. I must ask you to go ahead to reinforce Sina's Yearning. Anduin and I can see my people to safety in Lorel's Crossing. With the darkness and the kobyss, the hearts of my people in Sina's Yearning will be faltering to fear. We can't let them wallow. Light a torch with the Sacred Flame in the center of town and use it to inspire my people's valor. Remind them of their strength. We will catch up with you. May the Flame guide you, my friend.", ["objectivesText"] = "Light a torch with the Sacred Flame, then rally 6 groups of Arathi in Sina's Yearning.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["rewardItems"] = { 220507, 220508 }, ["rewardChoices"] = { 220507, 220508 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 214378, ["x"] = 0.538, ["y"] = 0.314 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 221100, ["x"] = 0.552, ["y"] = 0.326 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.314 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78929, 78932 }, ["questLines"] = { { ["id"] = 5530, ["name"] = "Gathering Shadows", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5530, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5530, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[78936] = { ["id"] = 78936, ["name"] = "Something's Fishy", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78672, 78929, 78932, 78934, 78936, 78937, 78939, 78951, 78952, 78954, 81690 }, ["description"] = "So you outsiders and Faerin managed to both survive and save the villagers at the beach? <Steelstrike breathes a quick prayer in relief.> We're in trouble, here. The kobyss brought some of their strongest forces to the doorsteps of villagers. We have our hands full just holding the line. If you can take out those monsters, we might be able to turn the tide.", ["objectivesText"] = "Slay Deepsludger , The Abominable Wavecrasher , and Tidelord Teethwretch in Sina's Yearning. Progress: When we first encountered the kobyss, there were those among us who tried to establish peace with them. But it quickly became apparent that they only see us as food.", ["rewardGold"] = 561800, ["rewardXP"] = 12740, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 214376, ["x"] = 0.545, ["y"] = 0.32 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 214376, ["x"] = 0.545, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.545, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78929, 78932 }, ["questLines"] = { { ["id"] = 5530, ["name"] = "Gathering Shadows", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5530, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5530, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[78937] = { ["id"] = 78937, ["name"] = "Shadow upon Shadow", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78672, 78929, 78932, 78934, 78936, 78937, 78939, 78951, 78952, 78954, 81690 }, ["description"] = "< Faerin 's wide eyes dart around in surprise.> What just happened? Did you see that shadow? And the oil well... it's gone dark? I've never seen anything like this before. Could it be the nearby dawntower? Hurry!", ["objectivesText"] = "Investigate the nearby dawntower.", ["rewardGold"] = 29200, ["rewardXP"] = 1275, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 221100, ["x"] = 0.552, ["y"] = 0.326 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 214405, ["x"] = 0.561333, ["y"] = 0.419333 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.326 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78934, 78936 }, ["questLines"] = { { ["id"] = 5530, ["name"] = "Gathering Shadows", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5530, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5530, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[78938] = { ["id"] = 78938, ["name"] = "Champion of the Waterlords", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 51, ["mapID"] = 32, ["storyline"] = { 78938 }, ["description"] = "I regret to inform you that a horrific threat awaits your kind within this mortal realm. An Elemental Lord of Fire, Ragnaros, bides his time waiting to strike and burn your Azeroth to its core. We, the elements of water, have waged war eternal with those beings of the lesser elementals. Trust that our warning is no small thing. Prove your conviction! Slay Ragnaros, once and for all!", ["objectivesText"] = "Defeat Remembered Ragnaros during a Radiant Echoes event. Progress: Ragnaros yet remains, mortal. His foul heat emanates from nearby.", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 32, ["npcID"] = 214399, ["x"] = 0.435, ["y"] = 0.672 } }, ["ends"] = { { ["mapID"] = 32, ["npcID"] = 214399, ["x"] = 0.435, ["y"] = 0.672 } }, ["coords"] = { ["mapID"] = 32, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.672 }, ["mapCandidates"] = { ["npc"] = { 32 }, ["zone"] = { 51 } }, ["questType"] = "standard" },
[78939] = { ["id"] = 78939, ["name"] = "The Darkened Flame", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78672, 78929, 78932, 78934, 78936, 78937, 78939, 78951, 78952, 78954, 81690 }, ["description"] = "This... Order of Night, as they call themselves, did some foul ritual to turn the tower's flame to darkness. I know not what. We should investigate.", ["objectivesText"] = "Investigate the darkened dawntower. Progress: My own people... how could they? <Faerin shakes her head in disbelief.>", ["rewardGold"] = 146000, ["rewardXP"] = 5095, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 214405, ["x"] = 0.561333, ["y"] = 0.419333 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 214404, ["x"] = 0.559, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.561333, ["y"] = 0.419333 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78937 }, ["questLines"] = { { ["id"] = 5530, ["name"] = "Gathering Shadows", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5530, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5530, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[78941] = { ["id"] = 78941, ["name"] = "A Tide Needing Turned", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2339, ["storyline"] = { 78941, 78942, 78943, 78948, 78950, 83503 }, ["description"] = "Xal'atath's army has been capable of striking at us for a while now. So what caused her to choose this moment? Something is wrong here. She waited for us to build an army in response, and then attacks openly. We're playing into her hands. Report to the Arathi general. I'll head to the battlefield directly.", ["objectivesText"] = "Meet with General Steelstrike in Hallowfall .", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 223944, ["x"] = 0.315, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 214271, ["x"] = 0.716, ["y"] = 0.592 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.315, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 2215, 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 79030 }, ["questLines"] = { { ["id"] = 5550, ["name"] = "A Light in the Dark", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5550, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[78942] = { ["id"] = 78942, ["name"] = "The Might of Khaz Algar", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78941, 78942, 78943, 78948, 78950, 83503 }, ["description"] = "The Harbinger thinks she can catch us off guard, but she's a fool if she expects to win this fight. The Algari Offensive stands at your back, <name>. Spare no enemy.", ["objectivesText"] = "Fight back against the nerubians.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 214271, ["x"] = 0.716, ["y"] = 0.592 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 214274, ["x"] = 0.645, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.716, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78941 }, ["questLines"] = { { ["id"] = 5550, ["name"] = "A Light in the Dark", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5550, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[78943] = { ["id"] = 78943, ["name"] = "Steel and Flames", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78941, 78942, 78943, 78948, 78950, 83503 }, ["description"] = "Our forces may be able to hold their own, but seeing you in the fray may help their spirits. Take this warhorn. Let it ring out and fill our foes with terror. Once you're done rallying our troops, make your way to your commanders.", ["objectivesText"] = "Rally 20 Algari Offensive troops.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 217309, 223438, 223443, 223454, 223461 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 214271, ["x"] = 0.716, ["y"] = 0.592 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 214275, ["x"] = 0.685, ["y"] = 0.642 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.716, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78941 }, ["questLines"] = { { ["id"] = 5550, ["name"] = "A Light in the Dark", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5550, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[78948] = { ["id"] = 78948, ["name"] = "A Light in the Dark", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78941, 78942, 78943, 78948, 78950, 83503 }, ["description"] = "Something is very wrong. As the battle continues, each side has become more aggressive. Alleria seems to know something - she ran off at one point during the battle. We've been giving chase, but I cannot leave these soldiers to die. She's just ahead, we can reconvene with her together.", ["objectivesText"] = "Speak with Anduin and chase down Xal'atath.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 44018, 44039, 44041, 44042, 44043, 220161, 223472, 257143, 265106, 265631 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 214273, ["x"] = 0.645, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 220688, ["x"] = 0.36, ["y"] = 0.354 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.645, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78942, 78950 }, ["questLines"] = { { ["id"] = 5550, ["name"] = "A Light in the Dark", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 6006, ["name"] = "Catch Up: War Within: Wrapper 3", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5550, ["questLineOrder"] = 4 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6006, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[78950] = { ["id"] = 78950, ["name"] = "Cutting Off the Legs", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78941, 78942, 78943, 78948, 78950, 83503 }, ["description"] = "While we've yet to locate Xal'atath, we've received reports from deeper in the field of certain nerubians giving orders. It won't buy us too much but every action is critical. Take them out. Hopefully that will allow us some breathing room. Speak with Anduin after you are done. He and the Arathi girl went after Alleria.", ["objectivesText"] = "Slay the nerubian lieutenants. Progress: Speak with Anduin within the Sanguine Grasps.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 214276, ["x"] = 0.685, ["y"] = 0.642 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 214273, ["x"] = 0.645, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.685, ["y"] = 0.642 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78943 }, ["questLines"] = { { ["id"] = 5550, ["name"] = "A Light in the Dark", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5550, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[78951] = { ["id"] = 78951, ["name"] = "Ever Deeper Shadow", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78672, 78929, 78932, 78934, 78936, 78937, 78939, 78951, 78952, 78954, 81690 }, ["description"] = "When I reached for the Flame, I felt the overwhelming hopelessness and despair that had been poured into it. It pains me, but... my light alone is not enough to banish these shadows. And so, we take a more direct path. If the remaining cultists have withdrawn to Gloomcrag Bower, their combined power must be what's keeping the Flame dark. We must stop them before this darkness spreads.", ["objectivesText"] = "Slay 10 Order of Night cultists in the cave beneath the Cliffside Beacon. Progress: These were once my people. My allies. My mentors. I once tried to reason with them. Tried to make them see the Light... see that the Light is still within us all. <Faerin's face flickers between sadness and anger.> They wouldn't listen. And they're killing innocents. I can't hesitate. Not anymore.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 214404, ["x"] = 0.559, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 214413, ["x"] = 0.558, ["y"] = 0.405 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.559, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78939 }, ["questLines"] = { { ["id"] = 5530, ["name"] = "Gathering Shadows", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5530, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5530, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[78952] = { ["id"] = 78952, ["name"] = "The Final Resistance", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78672, 78929, 78932, 78934, 78936, 78937, 78939, 78951, 78952, 78954, 81690 }, ["description"] = "<Faerin speaks in a hushed, furious whisper.> Good work. But before we can leave, there's something else. Down this way are some powerful priests. I think they are summoning something-- something big. No doubt to strike at us above and drive us from the tower itself. It will be dangerous, but we must stop them. Are you with me?", ["objectivesText"] = "Destroy the Shadow Rift .", ["rewardGold"] = 619600, ["rewardXP"] = 12740, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 214413, ["x"] = 0.558, ["y"] = 0.405 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 221733, ["x"] = 0.554, ["y"] = 0.418 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78951 }, ["questLines"] = { { ["id"] = 5530, ["name"] = "Gathering Shadows", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5530, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5530, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[78954] = { ["id"] = 78954, ["name"] = "Restore the Flame", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78672, 78929, 78932, 78934, 78936, 78937, 78939, 78951, 78952, 78954, 81690 }, ["description"] = "Do you feel it? Hope, returning? Thank you for your help, <name>. The dawntower's flame remains dark. But this time, I think we'll be able to restore it. Let's meet at the tower.", ["objectivesText"] = "Help Faerin restore the Holy Flame at the Cliffside Beacon. Progress: I only hope that together, we can kindle a little more light in our little world.", ["rewardGold"] = 70900, ["rewardXP"] = 2550, ["rewardItems"] = { 220108, 220109, 220110, 220112 }, ["rewardCurrencies"] = { { ["id"] = 2899, ["amount"] = 2500 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 221733, ["x"] = 0.554, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 214404, ["x"] = 0.559, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.554, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 81690 }, ["questLines"] = { { ["id"] = 5530, ["name"] = "Gathering Shadows", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5530, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5530, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[78972] = { ["id"] = 78972, ["name"] = "Harvest Havoc", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78972 }, ["description"] = "Our parents went off to fight the monsters that invaded our farm. While they are gone, we try to keep the farm running. We have a harvestbot to help with chores, but I keep crashing it into the river. We could finish our chores if you could help us drive the harvestbot!", ["objectivesText"] = "Control Harvestbot Remy to load 4 Cabbage and 4 Carrots into carts. In addition slay 12 Invasive Beetles. Progress: Have you completed the chores?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 228741 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 40 }, { ["id"] = 2899, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 214428, ["x"] = 0.636, ["y"] = 0.338 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 214428, ["x"] = 0.636, ["y"] = 0.338 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.636, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78458 } },
[78974] = { ["id"] = 78974, ["name"] = "Beetle-Minded", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78974, 78995, 79116, 79722, 79958, 79959, 79960, 80409, 80457, 82266, 82295, 82297, 82324, 82332, 82363, 82364, 82387, 82414, 82468, 82481, 82521, 82524, 82526, 82531, 82533, 82536, 83536, 83718 }, ["objectivesText"] = "Water Trough filled Food Trough filled", ["rewardXP"] = 11765, ["starts"] = { { ["x"] = 0.719, ["y"] = 0.798, ["mapID"] = 2255 } }, ["ends"] = { { ["x"] = 0.719, ["y"] = 0.798, ["mapID"] = 2255 } }, ["coords"] = { ["mapID"] = 2255, ["x"] = 0.719, ["y"] = 0.798 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14752 } }, ["questType"] = "world", ["questLines"] = { { ["id"] = 5564, ["name"] = "Azj-Kahet - World Quests/Repeatables", ["orderIndex"] = 13, ["flags"] = 0 } }, ["db2Objectives"] = { { ["text"] = "Water Trough filled", ["amount"] = 4, ["type"] = 0, ["objectID"] = 214452, ["orderIndex"] = 0 }, { ["text"] = "Food Trough filled", ["amount"] = 4, ["type"] = 0, ["objectID"] = 214455, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[78978] = { ["id"] = 78978, ["name"] = "Raising a Stink", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Love is in the Air", ["expansion"] = 10, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 78978 }, ["series"] = { 78984, 78985 }, ["description"] = "Those clues add up to an ugly story, <name>. That map shows the Crown's got a heavily guarded base of operations in Silverpine Forest. And between that memo and formula, it looks like they're cooking up something intoxicatingly toxic. I've got a gal that can get us some... artisanal goods... to deal with the Crown. I'll go talk to him and meet you outside Shadowfang Keep.", ["objectivesText"] = "Meet Detective Snagglebolt at the entrance to Shadowfang Keep in Silverpine Forest.", ["rewardGold"] = 34100, ["rewardXP"] = 25, ["starts"] = { { ["npcID"] = 214707 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 37172, ["x"] = 0.5, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questGiverID"] = 214707, ["questType"] = "standard", ["sourceQuests"] = { 78983 }, ["db2LabelIDs"] = { 3027 } },
[78979] = { ["id"] = 78979, ["name"] = "Loving Yourself, Your Way", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Love is in the Air", ["expansion"] = 10, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 78979 }, ["description"] = "While visiting this gala, I am staying at the Razor Hill inn. It may not look like much, but it is surprisingly comfortable! Why don't you see if they have any extra beds you could use? I think I will have a bit of a rest too... Right... here...", ["objectivesText"] = "Take a nap in the inn at Razor Hill. Progress: < Ning is quietly snoring.>", ["rewardGold"] = 58650, ["rewardXP"] = 1415, ["rewardItems"] = { 49927 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 214591, ["x"] = 0.418, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 214591, ["x"] = 0.418, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["sourceQuests"] = { 78989 }, ["db2LabelIDs"] = { 3027 } },
[78980] = { ["id"] = 78980, ["name"] = "Take a Look Around", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Love is in the Air", ["expansion"] = 10, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 78980 }, ["description"] = "Here at the Gala of Gifts, we have many wonderful artisans crafting gifts just for you and your loved ones. But don't take my word for it--there are plenty of attendees enjoying the festivities as well! Go, speak to the visitors, and see what the artisans have to offer. Maybe you will find the perfect gift!", ["objectivesText"] = "Meet the vendors and visitors at the Gala of Gifts. Progress: Are you having a good time?", ["rewardGold"] = 28090, ["rewardXP"] = 25, ["rewardItems"] = { 49927 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 214477, ["x"] = 0.418, ["y"] = 0.18 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 214477, ["x"] = 0.418, ["y"] = 0.18 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.18 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["sourceQuests"] = { 78981 }, ["db2LabelIDs"] = { 3027 } },
[78981] = { ["id"] = 78981, ["name"] = "Love is in the Air", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Love is in the Air", ["expansion"] = 10, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 78981 }, ["series"] = { 78328, 78329 }, ["description"] = "Smell these roses! My partner got them for me at the Gala of Gifts. Interested in seeing things yourself? Head to Durotar. There are gifts, and food, and you should taste the chocolate, it's delicious!", ["objectivesText"] = "Visit the Gala of Gifts in Durotar, near Rocktusk Farm.", ["rewardGold"] = 16980, ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 19175, ["x"] = 0.545667, ["y"] = 0.709667 }, { ["mapID"] = 85, ["npcID"] = 19177, ["x"] = 0.440857, ["y"] = 0.667714 }, { ["mapID"] = 18, ["npcID"] = 215196, ["x"] = 0.614, ["y"] = 0.668 }, { ["mapID"] = 2339, ["npcID"] = 220307, ["x"] = 0.46, ["y"] = 0.546 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 214477, ["x"] = 0.418, ["y"] = 0.18 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.545667, ["y"] = 0.709667 }, ["mapCandidates"] = { ["npc"] = { 1, 18, 85, 2339 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["nextQuests"] = { 78980 }, ["db2LabelIDs"] = { 3027 } },
[78982] = { ["id"] = 78982, ["name"] = "I Smell Trouble", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Love is in the Air", ["expansion"] = 10, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 78982 }, ["description"] = "You smell that funny odor too? Smells like smoke, cheap cologne, and alchemical nonsense. You ask me, I think the Crown Chemical Co. is up to something. Want to help me get to the bottom of it? Well, take a look at my pal here. Sure, he looks like a pooch, but this is O.D.I.E.! The Olfactory Detection and Inspection Engine! With this little fella, you and I can sniff out whatever the Crown is plotting from a mile away! Are you in? I could use a good partner to solve this.", ["objectivesText"] = "Use O.D.I.E.'s Remote Control to find clues around Orgrimmar. Progress: Sure, O.D.I.E. can sniff out the clues, but you still gotta piece 'em together.", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 49927, 210413, 210416, 210417, 211778 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 37172, ["x"] = 0.5, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 37172, ["x"] = 0.5, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questTurnInID"] = 37172, ["questType"] = "standard", ["db2LabelIDs"] = { 3027 } },
[78983] = { ["id"] = 78983, ["name"] = "An Unwelcome Gift", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Love is in the Air", ["expansion"] = 10, ["zoneID"] = 1519, ["storyline"] = { 78983 }, ["description"] = "I have a sinking suspicion there are spies from the Crown Chemical Co. among us. But I know that you know that O.D.I.E. here knows how to latch onto their scent! But let's not bother anybody just here to have a good time, all right? Keep your nose peeled for chemicals, and make sure we're hitting the right targets.", ["objectivesText"] = "Kill 8 Crown Chemical Co. members around Orgrimmar. Progress: Follow your nose, pal! Anyone who stinks could be a suspect.", ["rewardGold"] = 341600, ["rewardXP"] = 200, ["rewardItems"] = { 49927, 211781 }, ["starts"] = { { ["npcID"] = 214707 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1519 } }, ["questGiverID"] = 214707, ["questType"] = "standard", ["sourceQuests"] = { 78982 }, ["db2LabelIDs"] = { 3027 } },
[78984] = { ["id"] = 78984, ["name"] = "Crushing the Crown", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Love is in the Air", ["expansion"] = 10, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 78984 }, ["series"] = { 78978, 78985 }, ["description"] = "Looks like Hummel's got some security. But don't worry, I came with some special gifts to deliver. <Snagglebolt points to the unmarked box.> Bombs. I got bombs. Playtime's over. Take those bombs and toss 'em at the Crown and their supplies. Let's give them a look at what genuine craftsmanship can do. Once we've cleared out their operations, we can move in on Hummel.", ["objectivesText"] = "Use the Artisanal Bon-Bombs to destroy Crown supplies and kill Crown members. Progress: We need to put a stop to this before the Crown pulls off their smelly sabotage.", ["rewardGold"] = 1024800, ["rewardXP"] = 300, ["rewardItems"] = { 49927, 210431 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 37172, ["x"] = 0.5, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 37172, ["x"] = 0.5, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["sourceQuests"] = { 78978 }, ["db2LabelIDs"] = { 3027 } },
[78985] = { ["id"] = 78985, ["name"] = "The Stench of Revenge", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Love is in the Air", ["expansion"] = 10, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 78985 }, ["series"] = { 78978, 78984 }, ["description"] = "We're never gonna see an end to this unless we take on the boss himself. Look, Apothecary Hummel is holed up in Shadowfang Keep with his cronies. He's working on a new batch of poisonous perfumes, and they'll knock out all of Orgrimmar if we let him finish his research. You go do what you do best, pal. Get in there and foil his schemes before we're all lavender-scented corpses.", ["objectivesText"] = "Speak to Snagglebolt to enter the Crown Chemical Co. battle and defeat Apothecary Hummel . Progress: You ready to see what Hummel is cooking? I guarantee you it's not as pretty as it smells.", ["rewardGold"] = 1123600, ["rewardXP"] = 400, ["rewardItems"] = { 49927 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 37172, ["x"] = 0.5, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 37172, ["x"] = 0.5, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 78984 }, ["db2LabelIDs"] = { 3027 } },
[78986] = { ["id"] = 78986, ["name"] = "Getaway to Scenic Grizzly Hills!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Love is in the Air", ["expansion"] = 10, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 78986 }, ["description"] = "Good morrow! Today's special portal is a magical getaway to the majestic forests of Northrend! Although perhaps I could beg you for a favor. You seem the adventurous type. I could use your help in delivering some flowers from Grizzly hills to a beautiful woman named Laverne. I would do it myself but... Well, you see, she is rather intimidating in her beauty.", ["objectivesText"] = "Take the Scenic Getaway Portal to Grizzly Hills to pick a bouquet of flowers for Laverne. Progress: The mage conjuring portals? <Laverne giggles.> Let me see.", ["rewardGold"] = 335000, ["rewardXP"] = 1415, ["rewardItems"] = { 49927, 210719 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 214497, ["x"] = 0.414, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 214496, ["x"] = 0.406, ["y"] = 0.168 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.414, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3027 } },
[78987] = { ["id"] = 78987, ["name"] = "Getaway to Scenic Nagrand!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Love is in the Air", ["expansion"] = 10, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 78987 }, ["description"] = "Good morrow! Today's special portal is a magical getaway to the great plains of Nagrand! Would you, perchance, be interested in a proposition? I will lend you my camera if you could deliver any photographs you take to my dear friend Karn. He has been adrift in Nagrand as of late, lost in his own thoughts. As stubborn as he is, I'm sure he will appreciate the company. I would do it myself, but I must maintain the portals here.", ["objectivesText"] = "Take the Scenic Getaway Portal to Nagrand, then take pictures of wildlife for Karn. Progress: How is Karn? When last I saw him, he seemed drowned in regrets and loneliness.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 49927, 210743 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 214497, ["x"] = 0.414, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 214497, ["x"] = 0.414, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.414, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3027 } },
[78988] = { ["id"] = 78988, ["name"] = "Getaway to Scenic Feralas!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Love is in the Air", ["expansion"] = 10, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 78988 }, ["description"] = "Good morrow! Today's special portal is a magical getaway to the sunny beaches of Feralas! The Steam Pools resort is having a lovely celebration and all are invited! Unfortunately, some of our festival attendees who took this portal earlier left their gifts here at the gala. Could you perchance help me return them? I will meet you at the beach and together we shall be able to determine which gifts belong to whom.", ["objectivesText"] = "Take the Scenic Getaway Portal to Feralas, then deliver the lost gifts to the correct recipients. Progress: There are so many places in Azeroth to escape to! Everywhere you look, there's something new to discover.", ["rewardGold"] = 312800, ["rewardXP"] = 1415, ["rewardItems"] = { 49927, 211922, 211923 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 214497, ["x"] = 0.414, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 214497, ["x"] = 0.414, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.414, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3027 } },
[78989] = { ["id"] = 78989, ["name"] = "The Gift of Self-Care", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Love is in the Air", ["expansion"] = 10, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 78989 }, ["description"] = "The eyes of a tired adventurer. A <class> that does many great deeds for many people. When was the last time you did a kind gesture for yourself? Perhaps now is the time. Look into your heart. What do YOU desire?", ["objectivesText"] = "Speak with Ning to discover your heart's desire. Progress: Love is a blessing, especially if it comes from within.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 214591, ["x"] = 0.418, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 214591, ["x"] = 0.418, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3027 } },
[78990] = { ["id"] = 78990, ["name"] = "The Gift of Relief", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Love is in the Air", ["expansion"] = 10, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 78990 }, ["description"] = "You adventurers are known to carry heavy burdens. There will be no better time to confront them than now. I saw a veteran somewhere around here. There is a chance he may know what it means to cope with stress. Perhaps he has insight to teach you.", ["objectivesText"] = "Speak to Tokag Bonebreaker at the Gala of Gifts, then relieve your stress in Orgrimmar. Progress: I've seen men die of stress, you don't want to bottle it up every day.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 49927 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 214591, ["x"] = 0.418, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 214602, ["x"] = 0.412, ["y"] = 0.175 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3027 } },
[78991] = { ["id"] = 78991, ["name"] = "The Gift of Relaxation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Love is in the Air", ["expansion"] = 10, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 78991 }, ["description"] = "Love is a gift, yes. But it is also a gift that you can give yourself. Sometimes, the best way to love yourself is simply to relax. I met a troll across the Southfury River who seems particularly wise in this regard. Perhaps you could ask her for insights in the art of relaxation.", ["objectivesText"] = "Speak with Jaz the Reborn about relaxation, then relax by Southfury River in the Northern Barrens. Progress: True love is letting ya guard down. Let yourself relax, you'll see what I mean.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 49927, 210929 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 214591, ["x"] = 0.418, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 10, ["npcID"] = 214592, ["x"] = 0.71, ["y"] = 0.14 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 1, 10 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3027 } },
[78992] = { ["id"] = 78992, ["name"] = "Loving Yourself, Your Way", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Love is in the Air", ["expansion"] = 10, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 78992 }, ["description"] = "If it's a challenge you're after, I think I have an idea. I saw a boastful champion heading toward Razor Hill. You could challenge him to a duel. This would satisfy your desire and perhaps teach him a valuable lesson in humility.", ["objectivesText"] = "Defeat Poggchug Ragethrower in a duel near the road to Razor Hill. Progress: How fares your challenge?", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 49927 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 214591, ["x"] = 0.418, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 214591, ["x"] = 0.418, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["sourceQuests"] = { 78989 }, ["db2LabelIDs"] = { 3027 } },
[78993] = { ["id"] = 78993, ["name"] = "Loving Yourself, Your Way", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Love is in the Air", ["expansion"] = 10, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 78993 }, ["description"] = "A full belly is a happy belly! There is plenty of good food and drink right here at the gala. Why don't you buy yourself something nice?", ["objectivesText"] = "Consume Packages of treats from vendors at the Gala of Gifts. Progress: Have you had your fill of treats? I love the fruits, myself.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 49927 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 214591, ["x"] = 0.418, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 214591, ["x"] = 0.418, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["sourceQuests"] = { 78989 }, ["db2LabelIDs"] = { 3027 } },
[78995] = { ["id"] = 78995, ["name"] = "Truffle Shuffle", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78974, 78995, 79116, 79722, 79958, 79959, 79960, 80409, 80457, 82266, 82295, 82297, 82324, 82332, 82363, 82364, 82387, 82414, 82468, 82481, 82521, 82524, 82526, 82531, 82533, 82536, 83536, 83718 }, ["objectivesText"] = "Kaheti Truffles", ["rewardGold"] = 137400, ["rewardXP"] = 11765, ["starts"] = { { ["x"] = 0.731, ["y"] = 0.714, ["mapID"] = 2255 } }, ["ends"] = { { ["x"] = 0.731, ["y"] = 0.714, ["mapID"] = 2255 } }, ["coords"] = { ["mapID"] = 2255, ["x"] = 0.731, ["y"] = 0.714 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14752 } }, ["questType"] = "world", ["questLines"] = { { ["id"] = 5564, ["name"] = "Azj-Kahet - World Quests/Repeatables", ["orderIndex"] = 14, ["flags"] = 0 } }, ["db2Objectives"] = { { ["text"] = "Kaheti Truffles", ["amount"] = 5, ["type"] = 0, ["objectID"] = 219220, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[78996] = { ["id"] = 78996, ["name"] = "Weapons and Warriors", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78996, 78997, 78998, 78999 }, ["description"] = "Gorloc raiders have been slaughtering these farmers and stealing their pearls. They seek our protection, but we may not be enough. I know of others nearby who can help. Seek them out and request their aid. If they are hesitant, offer them the promise of pearls as payment. We will also need to arm these farmers so they can defend themselves. Search for spare weapons and equipment that they might be able to use. I will go with the farmers and train them as best I can.", ["objectivesText"] = "Collect 3 weapon crates and recruit 5 warriors from Freywold Village and Dhar Durgaz.", ["rewardGold"] = 154900, ["rewardXP"] = 4760, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 214444, ["x"] = 0.426, ["y"] = 0.716 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 215201, ["x"] = 0.498, ["y"] = 0.766 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.716 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78536 }, ["questLines"] = { { ["id"] = 5524, ["name"] = "Seven Soldiers", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[78997] = { ["id"] = 78997, ["name"] = "Pilfered Pearls", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78996, 78997, 78998, 78999 }, ["description"] = "The pearls that these farmers harvest are their only source of livelihood. Some of these earthen even look at pearl farming as their primary reason for existing. The gorlocs continue to pilfer pearls at every opportunity. As you eliminate the gorlocs, search them for stolen pearls. Let us recover as many as we can.", ["objectivesText"] = "Retrieve 8 Pilfered Pearls from gorlocs at the Glimmering Shore. Progress: We need to return these pearls to the farmers.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 212176 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 215201, ["x"] = 0.498, ["y"] = 0.766 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 215201, ["x"] = 0.498, ["y"] = 0.766 }, { ["mapID"] = 2248, ["npcID"] = 215327, ["x"] = 0.495, ["y"] = 0.765 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.766 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78996 }, ["questLines"] = { { ["id"] = 5524, ["name"] = "Seven Soldiers", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[78998] = { ["id"] = 78998, ["name"] = "Frontline Farmers", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78996, 78997, 78998, 78999 }, ["description"] = "Most of the farmers are already out in the field, defending their positions. I have trained them as best I could given the circumstances, but they are still wielding farming tools. I need you to distribute the weapons you gathered to those on the frontlines. While it may not markedly improve their combat ability, at least it will boost their confidence that they are not alone in this fight.", ["objectivesText"] = "Distribute 3 weapon crates to the pearl farmers at Glimmering Shore.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 215201, ["x"] = 0.498, ["y"] = 0.766 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 215327, ["x"] = 0.495, ["y"] = 0.765 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.766 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78996 }, ["questLines"] = { { ["id"] = 5524, ["name"] = "Seven Soldiers", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[78999] = { ["id"] = 78999, ["name"] = "Heart of a Hero", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78996, 78997, 78998, 78999 }, ["description"] = "It seems the gorlocs have been bolstering their forces with summoned elementals. That explains how they were able to overrun the farmers so easily. It will take all of our strength to hold off the colossi already in the field. I need you to stop any new elementals from being created. Elementals of this size and power can only be created by the most powerful of gorloc shaman. Seek them out behind enemy lines and eliminate them. This should end the gorloc threat to the farmers once and for all.", ["objectivesText"] = "Defeat the three gorloc shaman leaders.", ["rewardGold"] = 561800, ["rewardXP"] = 11895, ["rewardItems"] = { 219764, 219765, 253021 }, ["rewardChoices"] = { 219764, 219765 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 25 }, { ["id"] = 2897, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 215327, ["x"] = 0.495, ["y"] = 0.765 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 215420, ["x"] = 0.504, ["y"] = 0.786 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.495, ["y"] = 0.765 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78997, 78998 }, ["questLines"] = { { ["id"] = 5524, ["name"] = "Seven Soldiers", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79006] = { ["id"] = 79006, ["name"] = "Faction Switch", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14663, ["storyline"] = { 79006 }, ["description"] = "Default", ["objectivesText"] = "Default", ["rewardGold"] = 292100, ["rewardXP"] = 1415, ["rewardItems"] = { 204255 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14663 } }, ["questType"] = "standard" },
[79009] = { ["id"] = 79009, ["name"] = "The Harbinger", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 79009, 79010, 79011, 79012, 79013, 79014, 79015, 79016, 79017, 79018, 79019, 79020, 79021, 81654 }, ["description"] = "We are in need of your aid once more, champion. A mysterious figure moves within the shadows. The Harbinger... Let us speak in the Chamber of the Guardian. I've asked Alleria to meet us there as well.", ["objectivesText"] = "Meet Khadgar and Alleria in the Chamber of the Guardian in Dalaran. Progress: A Radiant Song, a Dark Heart, and this mysterious Harbinger... What could it all mean?", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["rewardItems"] = { 223988, 225547 }, ["rewardCurrencies"] = { { ["id"] = 2245, ["amount"] = 5 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5519, ["name"] = "Hunt for the Harbinger", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 242, ["title"] = "Hunt for the Harbinger", ["questLineID"] = 5519, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5519, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 629 },
[79010] = { ["id"] = 79010, ["name"] = "Door to the Ren'dorei", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 7502, ["mapID"] = 971, ["storyline"] = { 79009, 79010, 79011, 79012, 79013, 79014, 79015, 79016, 79017, 79018, 79019, 79020, 79021, 81654 }, ["description"] = "If this investigation involves the Void, it would be wise to consult the void elves. We must head to Telogrus Rift and report the situation. I'll speak with Umbric. He'll be able to mobilize the Riftwalkers to our cause.", ["objectivesText"] = "Follow Alleria to Telogrus Rift.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 140192 }, ["starts"] = { { ["x"] = 0.314, ["y"] = 0.418, ["mapID"] = 629, ["npcID"] = 215013 } }, ["ends"] = { { ["x"] = 0.314, ["y"] = 0.418, ["mapID"] = 629, ["npcID"] = 215013 } }, ["coords"] = { ["mapID"] = 629, ["x"] = 0.314, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 215013, ["questTurnInID"] = 215013, ["questType"] = "standard", ["sourceQuests"] = { 79009, 81654 }, ["questLines"] = { { ["id"] = 5519, ["name"] = "Hunt for the Harbinger", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 242, ["title"] = "Hunt for the Harbinger", ["questLineID"] = 5519, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5519, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1865, ["db2PoiUiMapID"] = 971 },
[79011] = { ["id"] = 79011, ["name"] = "Riftwalker Reports", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 9415, ["mapID"] = 971, ["storyline"] = { 79009, 79010, 79011, 79012, 79013, 79014, 79015, 79016, 79017, 79018, 79019, 79020, 79021, 81654 }, ["description"] = "The Riftwalkers are tasked with investigating all void activity that appears on Azeroth. A most vital duty, given how dangerous this dark force can be. And I speak from experience. Many of them were sent out on assignment to investigate recent fluctuations. I've been told they just arrived back, but have yet to hear their reports. Would you check in on them while I speak with Alleria?", ["objectivesText"] = "Gather reports from Riftwalkers in Telogrus Rift. Progress: Let me know when you have those Riftwalker reports.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["x"] = 0.272, ["y"] = 0.278, ["mapID"] = 971, ["npcID"] = 214702 } }, ["ends"] = { { ["x"] = 0.272, ["y"] = 0.278, ["mapID"] = 971, ["npcID"] = 214702 } }, ["coords"] = { ["mapID"] = 971, ["x"] = 0.272, ["y"] = 0.278 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9415 } }, ["questGiverID"] = 214702, ["questTurnInID"] = 214702, ["questType"] = "standard", ["sourceQuests"] = { 79010 }, ["questLines"] = { { ["id"] = 5519, ["name"] = "Hunt for the Harbinger", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 242, ["title"] = "Hunt for the Harbinger", ["questLineID"] = 5519, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5519, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1865, ["db2PoiUiMapID"] = 971 },
[79012] = { ["id"] = 79012, ["name"] = "Cracks in the Void", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 9415, ["mapID"] = 971, ["storyline"] = { 79009, 79010, 79011, 79012, 79013, 79014, 79015, 79016, 79017, 79018, 79019, 79020, 79021, 81654 }, ["description"] = "Telogrus Rift has always been extremely sensitive to cosmic shifts. It makes for a rather precarious homestead, but the void elves have... few options available to us. The recent influx in void energies has resulted in unstable rifts opening sporadically. And with so many investigating Azeroth, I'm having trouble finding Riftwalkers to deal with them. Could you close any unstable void rifts you find along your path?", ["objectivesText"] = "Close 5 Unstable Void Rifts in Telogrus Rift. Progress: Normally the Riftwalkers would be the ones to mend these sort of anomalies. But I wouldn't want to distract from their current investigations.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["x"] = 0.272, ["y"] = 0.278, ["mapID"] = 971, ["npcID"] = 214702 } }, ["ends"] = { { ["x"] = 0.272, ["y"] = 0.278, ["mapID"] = 971, ["npcID"] = 214702 } }, ["coords"] = { ["mapID"] = 971, ["x"] = 0.272, ["y"] = 0.278 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9415 } }, ["questGiverID"] = 214702, ["questTurnInID"] = 214702, ["questType"] = "standard", ["sourceQuests"] = { 79010 }, ["questLines"] = { { ["id"] = 5519, ["name"] = "Hunt for the Harbinger", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 242, ["title"] = "Hunt for the Harbinger", ["questLineID"] = 5519, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5519, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1865, ["db2PoiUiMapID"] = 971 },
[79013] = { ["id"] = 79013, ["name"] = "Galakrond's Unrest", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 9415, ["mapID"] = 115, ["storyline"] = { 79009, 79010, 79011, 79012, 79013, 79014, 79015, 79016, 79017, 79018, 79019, 79020, 79021, 81654 }, ["description"] = "Galakrond's Rest. Where the Dark Heart was first empowered by Iridikron. We don't know what power the relic holds, but we do know that the Harbinger now wields it. And now one of our Riftwalkers is missing, right where it all began. I don't believe this is a coincidence, <name>. Let's travel to Northrend and search the area.", ["objectivesText"] = "Meet Alleria at Galakrond's Rest in Dragonblight.", ["rewardGold"] = 30900, ["rewardXP"] = 1190, ["starts"] = { { ["x"] = 0.407, ["y"] = 0.607, ["mapID"] = 971, ["npcID"] = 214698 } }, ["ends"] = { { ["mapID"] = 115, ["npcID"] = 214634, ["x"] = 0.566, ["y"] = 0.39 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 9415 } }, ["questGiverID"] = 214698, ["questType"] = "standard", ["sourceQuests"] = { 79011, 79012 }, ["questLines"] = { { ["id"] = 5519, ["name"] = "Hunt for the Harbinger", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 242, ["title"] = "Hunt for the Harbinger", ["questLineID"] = 5519, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5519, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 115 },
[79014] = { ["id"] = 79014, ["name"] = "Walk a Mile in Her Shadows", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 65, ["mapID"] = 115, ["storyline"] = { 79009, 79010, 79011, 79012, 79013, 79014, 79015, 79016, 79017, 79018, 79019, 79020, 79021, 81654 }, ["description"] = "I don't often work with the Riftwalkers. I prefer to handle missions alone. Still, I will not abandon one of them. I cannot yet sense the Riftwalker's presence. Our best path forward is to retrace her steps. Which means following the shadows.", ["objectivesText"] = "Uncover the void presence at Galakrond's Rest in Dragonblight.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 187898 }, ["starts"] = { { ["mapID"] = 115, ["npcID"] = 214634, ["x"] = 0.566, ["y"] = 0.39 } }, ["ends"] = { { ["mapID"] = 120, ["npcID"] = 214759, ["x"] = 0.415, ["y"] = 0.226 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = { 115, 120 }, ["zone"] = { 65 } }, ["questType"] = "standard", ["sourceQuests"] = { 79013 }, ["questLines"] = { { ["id"] = 5519, ["name"] = "Hunt for the Harbinger", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 242, ["title"] = "Hunt for the Harbinger", ["questLineID"] = 5519, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5519, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 120 },
[79015] = { ["id"] = 79015, ["name"] = "Dark Descension", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 67, ["mapID"] = 120, ["storyline"] = { 79009, 79010, 79011, 79012, 79013, 79014, 79015, 79016, 79017, 79018, 79019, 79020, 79021, 81654 }, ["description"] = "What are these void spawn doing here? Could it be the Harbinger's doing? Some power of the Dark Heart? Well. I do not mean to stand idly by. We must confront the Riftwalker. I don't think she will see reason now, but perhaps she can tell us something.", ["objectivesText"] = "Confront the missing Riftwalker. Progress: What would the Harbinger want with Ulduar?", ["rewardGold"] = 561800, ["rewardXP"] = 11895, ["starts"] = { { ["mapID"] = 120, ["npcID"] = 214759, ["x"] = 0.415, ["y"] = 0.226 } }, ["ends"] = { { ["mapID"] = 120, ["npcID"] = 214759, ["x"] = 0.415, ["y"] = 0.226 } }, ["coords"] = { ["mapID"] = 120, ["source"] = "quest_giver", ["x"] = 0.415, ["y"] = 0.226 }, ["mapCandidates"] = { ["npc"] = { 120 }, ["zone"] = { 67 } }, ["questTurnInID"] = 214759, ["questType"] = "standard", ["sourceQuests"] = { 79014 }, ["questLines"] = { { ["id"] = 5519, ["name"] = "Hunt for the Harbinger", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 242, ["title"] = "Hunt for the Harbinger", ["questLineID"] = 5519, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5519, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 120 },
[79016] = { ["id"] = 79016, ["name"] = "Legacy of the Void", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 67, ["mapID"] = 882, ["storyline"] = { 79009, 79010, 79011, 79012, 79013, 79014, 79015, 79016, 79017, 79018, 79019, 79020, 79021, 81654 }, ["description"] = "Make no mistake, <name>. I know this is a trap. But if there's any chance this leads us to the Harbinger, we must take that risk. Be at the ready. We venture forth.", ["objectivesText"] = "Travel to the Triad's Conservatory in Eredath.", ["rewardGold"] = 30900, ["rewardXP"] = 1190, ["starts"] = { { ["x"] = 0.44, ["y"] = 0.21, ["mapID"] = 120, ["npcID"] = 221539 } }, ["ends"] = { { ["mapID"] = 882, ["npcID"] = 214645, ["x"] = 0.225, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.225, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 67 } }, ["questGiverID"] = 221539, ["questType"] = "standard", ["sourceQuests"] = { 79015 }, ["questLines"] = { { ["id"] = 5519, ["name"] = "Hunt for the Harbinger", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 242, ["title"] = "Hunt for the Harbinger", ["questLineID"] = 5519, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5519, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 882 },
[79017] = { ["id"] = 79017, ["name"] = "The Path Taken", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 79009, 79010, 79011, 79012, 79013, 79014, 79015, 79016, 79017, 79018, 79019, 79020, 79021, 81654 }, ["description"] = "These apparitions before us. I believe they're... memories. My memories. Is this the Harbinger's doing? Or mine? We need to explore. Discover why we were led here.", ["objectivesText"] = "Witness Alleria's memories in Eredath. Progress: Suddenly, this all feels rather personal. The Harbinger must have a grievance against me. Or at least an... interest. Hm.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 882, ["npcID"] = 214645, ["x"] = 0.225, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 882, ["npcID"] = 214645, ["x"] = 0.225, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.225, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questTurnInID"] = 214645, ["questType"] = "standard", ["sourceQuests"] = { 79016 }, ["questLines"] = { { ["id"] = 5519, ["name"] = "Hunt for the Harbinger", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 242, ["title"] = "Hunt for the Harbinger", ["questLineID"] = 5519, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5519, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 882 },
[79018] = { ["id"] = 79018, ["name"] = "And Be One Traveler, Long I Stood", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 8701, ["mapID"] = 971, ["storyline"] = { 79009, 79010, 79011, 79012, 79013, 79014, 79015, 79016, 79017, 79018, 79019, 79020, 79021, 81654 }, ["description"] = "I sense another memory ahead. While I'm loath to play along with the Harbinger's game, it's the only path forward for us. Still, we have faced just as many dangerous memories as peaceful ones. Prepare yourself.", ["objectivesText"] = "Investigate the final memory at the Triad's Conservatory in Eredath.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["starts"] = { { ["x"] = 0.225, ["y"] = 0.534, ["mapID"] = 882, ["npcID"] = 215597 } }, ["ends"] = { { ["x"] = 0.225, ["y"] = 0.534, ["mapID"] = 882, ["npcID"] = 215597 } }, ["coords"] = { ["mapID"] = 882, ["x"] = 0.225, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8701 } }, ["questGiverID"] = 215597, ["questTurnInID"] = 215597, ["questType"] = "standard", ["sourceQuests"] = { 79017 }, ["questLines"] = { { ["id"] = 5519, ["name"] = "Hunt for the Harbinger", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 242, ["title"] = "Hunt for the Harbinger", ["questLineID"] = 5519, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5519, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1865, ["db2PoiUiMapID"] = 971 },
[79019] = { ["id"] = 79019, ["name"] = "Defend Telogrus Rift", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 9415, ["mapID"] = 971, ["storyline"] = { 79009, 79010, 79011, 79012, 79013, 79014, 79015, 79016, 79017, 79018, 79019, 79020, 79021, 81654 }, ["description"] = "No. Not the ren'dorei. Not Telogrus Rift. Not today. <Alleria tightens her grip on her bow.> These ethereal forces are the same we encountered in Ulduar. The Harbinger must command them. I'll go ahead. Engage the enemies here.", ["objectivesText"] = "Defend Telogrus Rift. Progress: My people can defend themselves, but even they will struggle against such an overwhelming force. We must aid them.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 128827 }, ["starts"] = { { ["x"] = 0.286, ["y"] = 0.238, ["mapID"] = 971, ["npcID"] = 214660 } }, ["ends"] = { { ["x"] = 0.286, ["y"] = 0.238, ["mapID"] = 971, ["npcID"] = 214660 } }, ["coords"] = { ["mapID"] = 971, ["x"] = 0.286, ["y"] = 0.238 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9415 } }, ["questGiverID"] = 214660, ["questTurnInID"] = 214660, ["questType"] = "standard", ["sourceQuests"] = { 79018 }, ["questLines"] = { { ["id"] = 5519, ["name"] = "Hunt for the Harbinger", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 242, ["title"] = "Hunt for the Harbinger", ["questLineID"] = 5519, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5519, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1865, ["db2PoiUiMapID"] = 971 },
[79020] = { ["id"] = 79020, ["name"] = "Null and Void", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 9415, ["mapID"] = 971, ["storyline"] = { 79009, 79010, 79011, 79012, 79013, 79014, 79015, 79016, 79017, 79018, 79019, 79020, 79021, 81654 }, ["description"] = "We must defeat that loathsome apparition of Turalyon. The abomination's presence is intolerable. If left unchecked, it may destroy what remains of Telogrus Rift. I will end it with my own hands.", ["objectivesText"] = "Defeat the Corrupted Memory of Turalyon in Telogrus Rift.", ["rewardGold"] = 561800, ["rewardXP"] = 11895, ["rewardItems"] = { 213269, 213561, 217711, 217712, 217713, 217714 }, ["starts"] = { { ["x"] = 0.436, ["y"] = 0.638, ["mapID"] = 971, ["npcID"] = 216264 } }, ["ends"] = { { ["x"] = 0.436, ["y"] = 0.638, ["mapID"] = 971, ["npcID"] = 216264 } }, ["coords"] = { ["mapID"] = 971, ["x"] = 0.436, ["y"] = 0.638 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9415 } }, ["questGiverID"] = 216264, ["questTurnInID"] = 216264, ["questType"] = "standard", ["sourceQuests"] = { 79019 }, ["questLines"] = { { ["id"] = 5519, ["name"] = "Hunt for the Harbinger", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 242, ["title"] = "Hunt for the Harbinger", ["questLineID"] = 5519, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5519, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1865, ["db2PoiUiMapID"] = 971 },
[79021] = { ["id"] = 79021, ["name"] = "Radiant Warnings", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 9415, ["mapID"] = 629, ["storyline"] = { 79009, 79010, 79011, 79012, 79013, 79014, 79015, 79016, 79017, 79018, 79019, 79020, 79021, 81654 }, ["description"] = "So she goes by Harbinger now, does she? How fitting. I no longer feel her presence, but make no mistake. Xal'atath's nefarious games continue. And Alleria is now a pawn upon her board. As are you, champion of fate.", ["objectivesText"] = "Deliver Locus-Walker 's warning to Khadgar in Dalaran. Progress: Telogrus Rift should no longer tempt Xal'atath. For now.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 213561 }, ["starts"] = { { ["x"] = 0.502, ["y"] = 0.752, ["mapID"] = 971, ["npcID"] = 214657 } }, ["ends"] = { { ["x"] = 0.502, ["y"] = 0.752, ["mapID"] = 971, ["npcID"] = 214657 } }, ["coords"] = { ["mapID"] = 971, ["x"] = 0.502, ["y"] = 0.752 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9415 } }, ["questGiverID"] = 214657, ["questTurnInID"] = 214657, ["questType"] = "standard", ["sourceQuests"] = { 79020 }, ["questLines"] = { { ["id"] = 5519, ["name"] = "Hunt for the Harbinger", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 242, ["title"] = "Hunt for the Harbinger", ["questLineID"] = 5519, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5519, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 629 },
[79022] = { ["id"] = 79022, ["name"] = "A Mysterious Signal", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2339, ["storyline"] = { 79022, 79023, 79024, 79025, 79026, 79027, 79028, 79029, 79030, 79217, 79324, 79325, 80145, 80517 }, ["description"] = "High Speaker Brinthe has sent an urgent missive for you, <name>. She is eager to assist in the coming war effort, and is investigating a mysterious signal in the Deepforge Golemworks, a defunct golem manufacturing facility in the Ringing Deeps . Can you meet her there and provide your expertise?", ["objectivesText"] = "Meet Brinthe at the Deepforge Golemworks in the Ringing Deeps .", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 223944, ["x"] = 0.315, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 214663, ["x"] = 0.541, ["y"] = 0.748 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.315, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 2214, 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 79244 }, ["questLines"] = { { ["id"] = 5531, ["name"] = "The Machines March to War", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5531, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[79023] = { ["id"] = 79023, ["name"] = "Small Friend, Big Plans", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79022, 79023, 79024, 79025, 79026, 79027, 79028, 79029, 79030, 79217, 79324, 79325, 80145, 80517 }, ["description"] = "I tracked down a distress signal that led me to this little maintenance machine. A curious find, but the real treasure is the defunct war golem facility to the southeast. If we can start producing war golems again we'll be able to contribute to the war effort. Unfortunately, it's been overrun by a goblin salvage group. And we'll need to investigate and assess if the facility is functional. Fortunately, I have a plan, and it involves our little friend here. Why don't you introduce yourself?", ["objectivesText"] = "Introduce yourself to the maintenance machine. Progress: With your assistance, I think we can find a way to clear this place out.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 214663, ["x"] = 0.541, ["y"] = 0.748 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 214663, ["x"] = 0.541, ["y"] = 0.748 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.541, ["y"] = 0.748 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79022 }, ["questLines"] = { { ["id"] = 5531, ["name"] = "The Machines March to War", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5531, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[79024] = { ["id"] = 79024, ["name"] = "Factory Recon", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79022, 79023, 79024, 79025, 79026, 79027, 79028, 79029, 79030, 79217, 79324, 79325, 80145, 80517 }, ["description"] = "ZZ-01-47 should be able to make its way in there without drawing too much attention. But be careful! These goblins are hungry for raw materials. If they spot our bot, they won't show it mercy.", ["objectivesText"] = "Employ ZZ-01-47 to scout the Golem Factory. Progress: Zee-Zee shouldn't be in much danger, as long as she stays away from the big mechs.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 223436, 223448, 223452, 223463 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 214663, ["x"] = 0.541, ["y"] = 0.748 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 214663, ["x"] = 0.541, ["y"] = 0.748 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.541, ["y"] = 0.748 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79023 }, ["questLines"] = { { ["id"] = 5531, ["name"] = "The Machines March to War", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5531, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[79025] = { ["id"] = 79025, ["name"] = "A Plan Comes Together", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79022, 79023, 79024, 79025, 79026, 79027, 79028, 79029, 79030, 79217, 79324, 79325, 80145, 80517 }, ["description"] = "We have our work cut out for us, <name>. But I think, with Dagran's help, we can break this down and tackle it piece by piece. Why don't you take us through what we've learned so far.", ["objectivesText"] = "Go over the plan with Brinthe and Dagran. Progress: We're some of the greatest minds in... well Gundargaz, at least. We can figure this out.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 217245, ["x"] = 0.449, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 217245, ["x"] = 0.449, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.449, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79217 }, ["questLines"] = { { ["id"] = 5531, ["name"] = "The Machines March to War", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5531, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214, ["db2QuestHubAreaPoiID"] = 7911 },
[79026] = { ["id"] = 79026, ["name"] = "Putting the Works in Waterworks", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79022, 79023, 79024, 79025, 79026, 79027, 79028, 79029, 79030, 79217, 79324, 79325, 80145, 80517 }, ["description"] = "Overly enthusiastic kobolds, angry elementals, and a broken-down power plant. This place is in shambles! Do you spot those large wheels on each side? They should be moving, but they're not. We'll need to get those moving again if we want this place to come back to life.", ["objectivesText"] = "Get the Waterworks running again. Progress: I wonder if we could use this technology to rebuild the Stonewrought Dam? Wouldn't that be something.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 217331, ["x"] = 0.451, ["y"] = 0.422 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 217331, ["x"] = 0.451, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.451, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79324 }, ["questLines"] = { { ["id"] = 5531, ["name"] = "The Machines March to War", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5531, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[79027] = { ["id"] = 79027, ["name"] = "Elemental Trepidation", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79022, 79023, 79024, 79025, 79026, 79027, 79028, 79029, 79030, 79217, 79324, 79325, 80145, 80517 }, ["description"] = "< ZZ-01-47 twitches back and forth, sensors scanning unceasingly. They seem afraid of this area, if they're even capable of feeling fear. Maybe clearing out some of the elementals will set them at ease.>", ["objectivesText"] = "Defeat elementals. Progress: I appreciate what you're doing for Zee-Zee. And they appreciate it, too.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 223435 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 216137, ["x"] = 0.451, ["y"] = 0.422 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 217331, ["x"] = 0.451, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.451, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79324 }, ["questLines"] = { { ["id"] = 5531, ["name"] = "The Machines March to War", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5531, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[79028] = { ["id"] = 79028, ["name"] = "We Require More Minerals", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79022, 79023, 79024, 79025, 79026, 79027, 79028, 79029, 79030, 79217, 79324, 79325, 80145, 80517 }, ["description"] = "Zee-Zee is ready to help you get the Shadowvein site up and running again.", ["objectivesText"] = "Get the Shadowvein site up and running. Progress: <Zee-Zee emits an inquisitive beep.>", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 216140, ["x"] = 0.535, ["y"] = 0.41 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 216140, ["x"] = 0.535, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questTurnInID"] = 216140, ["questType"] = "standard", ["sourceQuests"] = { 79325 }, ["questLines"] = { { ["id"] = 5531, ["name"] = "The Machines March to War", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5531, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[79029] = { ["id"] = 79029, ["name"] = "It's Sabotage", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79022, 79023, 79024, 79025, 79026, 79027, 79028, 79029, 79030, 79217, 79324, 79325, 80145, 80517 }, ["description"] = "We're back, and we're ready. You and ZZ-01-47 head in and cause some mayhem. Blow stuff up and make a mess that will draw them out of the manufacturing bay. I'll use the commotion to sneak inside. Join me when you're able, and we should have a chance at reactivating the facility and driving them out. We don't need to defeat them all. Defeating the Darkfuse leader supervising this operation should break their resolve. The Darkfuse lackeys will clear out when the coin stops flowing.", ["objectivesText"] = "Wreak havoc, gain access to the manufacturing bay, and restart the facility.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 29978, 29979, 29980, 39811, 39873, 39875, 39877, 53225, 53253, 53255, 57451, 57452, 57453, 131384, 131454, 140255, 220118, 223440, 223442, 223451, 223467 }, ["rewardCurrencies"] = { { ["id"] = 2902, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 214663, ["x"] = 0.541, ["y"] = 0.748 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 220928, ["x"] = 0.539, ["y"] = 0.776 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.541, ["y"] = 0.748 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 80517 }, ["questLines"] = { { ["id"] = 5531, ["name"] = "The Machines March to War", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5531, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214, ["db2QuestHubAreaPoiID"] = 7911 },
[79030] = { ["id"] = 79030, ["name"] = "The Voice of the Speakers", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79022, 79023, 79024, 79025, 79026, 79027, 79028, 79029, 79030, 79217, 79324, 79325, 80145, 80517 }, ["description"] = "Please take word of our victory to Alleria in Dornogal. I'm sure our allies will be pleased to hear what we can provide for the war effort.", ["objectivesText"] = "Return to Alleria in Dornogal.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 220928, ["x"] = 0.539, ["y"] = 0.776 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223944, ["x"] = 0.315, ["y"] = 0.595 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.539, ["y"] = 0.776 }, ["mapCandidates"] = { ["npc"] = { 2214, 2339 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79029 }, ["questLines"] = { { ["id"] = 5531, ["name"] = "The Machines March to War", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5531, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339, ["db2QuestHubAreaPoiID"] = 7911 },
[79074] = { ["id"] = 79074, ["name"] = "Summoning All Soldiers!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 79074 }, ["description"] = "The Artisan's Consortium has struck one final deal with the quartermasters of the Gladiator's Refuge! In addition to the usual selection of powerful combat equipment they offer, worthy combatants can purchase tokens that can be used in Crafting Orders or one's own crafts to certify the equipment for use in battlegrounds and arenas! Present this brochure to Calderax to receive two complimentary Trophies of Conquest, on us! - Rabul", ["objectivesText"] = "Deliver the brochure to Calderax in the Gladiator's Refuge of Valdrakken .", ["rewardItems"] = { 211685, 211686, 211690 }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 199599, ["x"] = 0.444667, ["y"] = 0.366667 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.444667, ["y"] = 0.366667 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["startItems"] = { 211690 } },
