[79089] = { ["id"] = 79089, ["name"] = "Consecrated Cleanup", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78607, 78613, 78614, 78615, 78620, 78621, 78624, 78626, 78627, 78628, 78629, 78630, 79089, 79297, 80049 }, ["description"] = "Our Veneration Grounds have been desecrated. Its beauty marred. It's going to take a bigger effort, but I would appreciate anything you can do to cleanup our grounds.", ["objectivesText"] = "Restore the Veneration Grounds in Hallowfall . Progress: I wish you could have seen this place before the Kobyss arrived.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 225188, ["x"] = 0.336, ["y"] = 0.546 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 225188, ["x"] = 0.336, ["y"] = 0.546 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.336, ["y"] = 0.546 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78624 }, ["questLines"] = { { ["id"] = 5526, ["name"] = "Hope in Solidarity", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5526, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5526, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[79105] = { ["id"] = 79105, ["name"] = "Breach", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15177, ["mapID"] = 2305, ["storyline"] = { 78459, 78461, 78462, 78529, 78530, 78531, 78532, 78533, 78544, 78545, 78546, 78704, 78705, 78706, 78761, 78837, 79105, 79106, 80022, 80321, 80334, 80434, 91864 }, ["description"] = "As much as I'd love to hunt Xal'atath down, our first priority must be securing civilians. Rescue whoever you can and tell them to head to the landing nearby. I'll find mages to teleport everyone to safety.", ["objectivesText"] = "Send civilians to the landing for safety.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 38669, 38715, 39019, 39048, 39080, 60854, 63775, 63780, 143488, 143747, 165871, 166792, 229371, 232049, 232371, 246936, 248575, 248576, 249400, 249783, 254267, 254579 }, ["starts"] = { { ["npcID"] = 214908, ["x"] = 0.502, ["y"] = 0.504, ["mapID"] = 2305 } }, ["ends"] = { { ["npcID"] = 214908, ["x"] = 0.502, ["y"] = 0.504, ["mapID"] = 2305 } }, ["coords"] = { ["x"] = 0.502, ["y"] = 0.504, ["source"] = "quest_giver", ["mapID"] = 2305 }, ["mapCandidates"] = { ["npc"] = { 2305 }, ["zone"] = { 15177 } }, ["questType"] = "standard", ["sourceQuests"] = { 78722 }, ["questLines"] = { { ["id"] = 5513, ["name"] = "Visions of Azeroth", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5638, ["name"] = "Dalaran Intro", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 6008, ["name"] = "Catch Up: War Within: Wrapper 2", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 235, ["title"] = "Visions of Azeroth", ["questLineID"] = 5513, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5513, ["questLineOrder"] = 1 }, { ["id"] = 261, ["title"] = "Expansion Intro Skip", ["questLineID"] = 5638, ["questLineOrder"] = 0 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6008, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2731, ["db2PoiUiMapID"] = 2305 },
[79106] = { ["id"] = 79106, ["name"] = "Rupture", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15177, ["mapID"] = 2305, ["storyline"] = { 78459, 78461, 78462, 78529, 78530, 78531, 78532, 78533, 78544, 78545, 78546, 78704, 78705, 78706, 78761, 78837, 79105, 79106, 80022, 80321, 80334, 80434, 91864 }, ["description"] = "Follow me. We'll work together to find any others in need of rescuing.", ["objectivesText"] = "Save Dalaran . Progress: The nerubians are capturing anyone they can and stringing them up in webs. Make sure to free whoever you find before moving on.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["x"] = 0.357, ["y"] = 0.713, ["mapID"] = 2305, ["npcID"] = 214908 } }, ["ends"] = { { ["x"] = 0.357, ["y"] = 0.713, ["mapID"] = 2305, ["npcID"] = 214908 } }, ["coords"] = { ["mapID"] = 2305, ["x"] = 0.357, ["y"] = 0.713 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15177 } }, ["questGiverID"] = 214908, ["questTurnInID"] = 214908, ["questType"] = "standard", ["sourceQuests"] = { 79105 }, ["questLines"] = { { ["id"] = 5513, ["name"] = "Visions of Azeroth", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 5638, ["name"] = "Dalaran Intro", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 6008, ["name"] = "Catch Up: War Within: Wrapper 2", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 235, ["title"] = "Visions of Azeroth", ["questLineID"] = 5513, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5513, ["questLineOrder"] = 1 }, { ["id"] = 261, ["title"] = "Expansion Intro Skip", ["questLineID"] = 5638, ["questLineOrder"] = 0 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6008, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2731, ["db2PoiUiMapID"] = 2307 },
[79107] = { ["id"] = 79107, ["name"] = "After the Storm", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 79107, 79124, 79129, 79140, 79145, 79146, 79147, 79156, 79157, 79475, 79476, 79477, 79480, 81912, 81913, 81914, 81915 }, ["description"] = "Turalyon and Geya'rah are training our new earthen allies as ground forces. But we will need more than that. We will need the Stormriders. Many were lost in the infiltration of the Stormperch and more to the nerubians. Their leader, Stormward Baelgrim, died valiantly. The surviving Stormriders are being cared for at a triage station nearby. We need to do whatever is necessary to get them and their rooks back in the air. They will be the earthen's most potent weapon in the battles to come.", ["objectivesText"] = "Check on the Stormriders.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 147475 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 223944, ["x"] = 0.315, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 215039, ["x"] = 0.266, ["y"] = 0.594667 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.315, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 2248, 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 79344 }, ["questLines"] = { { ["id"] = 5523, ["name"] = "Ties That Bind", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5523, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79108] = { ["id"] = 79108, ["name"] = "Seeds of Evil", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79108, 79109, 79110 }, ["description"] = "<class>, some of the shadowleaf plants are more... wrong than the rest. I don't know how to describe it better. My idiot brother, Tomothy, was supposed to help me get rid of these, but I haven't seen him and I can't wait. Clearly we don't want these to reproduce so I want you to cull as many as you can find, and then take their seeds. We'll burn those in holy fire to make sure we've cut off the infestation.", ["objectivesText"] = "Collect Corrupted Shadowleaf Seeds . Progress: Did you cull those plants?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 212153, 221849 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 206528, ["x"] = 0.612, ["y"] = 0.305 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 206528, ["x"] = 0.612, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78658, 79573 }, ["questLines"] = { { ["id"] = 5608, ["name"] = "Lost in the Darkness", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[79109] = { ["id"] = 79109, ["name"] = "Follow Miral", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79108, 79109, 79110 }, ["description"] = "Tomothy's lynx, Miral, has been bugging me. I don't know what she wants but it is unusual to see her without my brother. She's a great farm cat, but she's still a cat, so maybe she's just bored with Tomothy today? I don't know. Maybe Tomothy got into some sort of trouble. Can you find out what is bothering her for me?", ["objectivesText"] = "Discover what is bothering Miral Murder-Mittens . Progress: <Miral looks at you as if expecting something. You are being judged.>", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 221849 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 206528, ["x"] = 0.612, ["y"] = 0.305 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 215041, ["x"] = 0.606, ["y"] = 0.257 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 79108, 80382 }, ["questLines"] = { { ["id"] = 5608, ["name"] = "Lost in the Darkness", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[79110] = { ["id"] = 79110, ["name"] = "Save Tomothy", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79108, 79109, 79110 }, ["description"] = "<Miral looks at you expectantly then looks at the ruins, then back to you, then to the ruins. You get the sense she wants you to go over there. Perhaps this is where Tomothy got lost?>", ["objectivesText"] = "Save Tomothy Hillhelm from The Grasping Darkness .", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 221849 }, ["rewardCurrencies"] = { { ["id"] = 2899, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 215041, ["x"] = 0.606, ["y"] = 0.257 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 206528, ["x"] = 0.612, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.606, ["y"] = 0.257 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 79109 }, ["questLines"] = { { ["id"] = 5608, ["name"] = "Lost in the Darkness", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[79111] = { ["id"] = 79111, ["name"] = "Missing Lynx", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 79111 }, ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[79114] = { ["id"] = 79114, ["name"] = "Beautification Project", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79114, 79115, 79117, 79118, 79119, 79120, 79121, 79122, 79123, 83325 }, ["description"] = "A fine enough job, for one of your... ilk. If you wish to keep breathing, I suggest you continue to assist us. It may even prove lucrative for you, if you comply. Rak-Ush's former master allowed the stagshells to run feral, and abandoned the hollows to decay. Over time, invasive plants have infested the old stagshell hollows. Find a way to clear them. I don't care how.", ["objectivesText"] = "Clear the Stagshell Hollow of Overgrown Plants. Progress: It would be unwise to return to me with an unfinished job.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 214359, ["x"] = 0.755, ["y"] = 0.815 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 214359, ["x"] = 0.755, ["y"] = 0.815 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.755, ["y"] = 0.815 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 79119 }, ["questLines"] = { { ["id"] = 5648, ["name"] = "Rak-Ush", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[79115] = { ["id"] = 79115, ["name"] = "Expert Consultant", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["description"] = "You alone are no longer sufficient. We require additional assistance, and the jawcrawlers and threadlings also need oversight. The niffen settlement, Mmarl, is not far. However, past forced conscription attempts have failed. Nerubians are now forbidden within the settlement. We need someone to communicate in our stead. Go and barter with the rats. Come back with able bodies.", ["rewardGold"] = 29200, ["rewardXP"] = 1325, ["starts"] = { { ["npcID"] = 214356, ["x"] = 0.75, ["y"] = 0.808, ["mapID"] = 2255 } }, ["ends"] = { { ["npcID"] = 215037, ["x"] = 0.772, ["y"] = 0.644, ["mapID"] = 2255 } }, ["coords"] = { ["x"] = 0.75, ["y"] = 0.808, ["source"] = "quest_giver", ["mapID"] = 2255 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 79114 }, ["questLines"] = { { ["id"] = 5648, ["name"] = "Rak-Ush", ["orderIndex"] = 2, ["flags"] = 0 } } },
[79116] = { ["id"] = 79116, ["name"] = "Spider Optics", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78974, 78995, 79116, 79722, 79958, 79959, 79960, 80409, 80457, 82266, 82295, 82297, 82324, 82332, 82363, 82364, 82387, 82414, 82468, 82481, 82521, 82524, 82526, 82531, 82533, 82536, 83536, 83718 }, ["objectivesText"] = "Rescue Spiderlings Protect Egg Sacs", ["rewardXP"] = 11765, ["starts"] = { { ["x"] = 0.694, ["y"] = 0.766, ["mapID"] = 2255 } }, ["ends"] = { { ["x"] = 0.694, ["y"] = 0.766, ["mapID"] = 2255 } }, ["coords"] = { ["mapID"] = 2255, ["x"] = 0.694, ["y"] = 0.766 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14752 } }, ["questType"] = "world", ["questLines"] = { { ["id"] = 5564, ["name"] = "Azj-Kahet - World Quests/Repeatables", ["orderIndex"] = 15, ["flags"] = 0 } }, ["db2Objectives"] = { { ["text"] = "Rescue Spiderlings", ["amount"] = 6, ["type"] = 0, ["objectID"] = 223682, ["orderIndex"] = 1 }, { ["text"] = "Protect Egg Sacs", ["amount"] = 5, ["type"] = 0, ["objectID"] = 223683, ["orderIndex"] = 2 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[79117] = { ["id"] = 79117, ["name"] = "Bright Young Niffen", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79114, 79115, 79117, 79118, 79119, 79120, 79121, 79122, 79123, 83325 }, ["description"] = "You need swarmhands, huh? Last time the nerubians wanted our help, they tried to force us. They're terrible negotiators! All we wanted was a little quid pro quo. We've got several arachnologists, but most of them are busy keeping the flyers at bay. I'm sure they won't refuse an opportunity to study some swarmbeasts up close and personal! Maybe if you lighten their workload, they'll take you up on your offer.", ["objectivesText"] = "Find 6 Niffen Arachnologists outside Mmarl to join Rak-Ush. Progress: Have you found anyone yet?", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 215037, ["x"] = 0.772, ["y"] = 0.644 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 215037, ["x"] = 0.772, ["y"] = 0.644 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.772, ["y"] = 0.644 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 79115 }, ["questLines"] = { { ["id"] = 5648, ["name"] = "Rak-Ush", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[79118] = { ["id"] = 79118, ["name"] = "Rak-Ush Under New Management", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79114, 79115, 79117, 79118, 79119, 79120, 79121, 79122, 79123, 83325 }, ["description"] = "Well, you got your swarmhands. What are you still doing here? Go on then, you don't need my permission! Make sure the nerubians treat them fairly, now.", ["objectivesText"] = "Return to Vix'aron in Rak-Ush.", ["rewardGold"] = 30900, ["rewardXP"] = 1325, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 215037, ["x"] = 0.772, ["y"] = 0.644 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 214356, ["x"] = 0.755, ["y"] = 0.816 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.772, ["y"] = 0.644 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 79117 }, ["questLines"] = { { ["id"] = 5648, ["name"] = "Rak-Ush", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[79119] = { ["id"] = 79119, ["name"] = "It's Rough to Be a Bug!", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79114, 79115, 79117, 79118, 79119, 79120, 79121, 79122, 79123, 83325 }, ["description"] = "Anub'azal gave his orders! We are the new masters of Rak-Ush! Yet Vix'aron decided to throw a tantrum and destroy our barn instead. Since this imbecile refuses to follow orders, perhaps you will, overcrawler. Maybe then we will decide not to kill you for eavesdropping. And recompense, I suppose. Go. We are to restore the stagshell hollows and fill them with swarmbeasts.", ["objectivesText"] = "Clean up the barn in Rak-Ush. Progress: We need this barn in an operational state!", ["rewardGold"] = 292100, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 214359, ["x"] = 0.755, ["y"] = 0.815 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 214359, ["x"] = 0.755, ["y"] = 0.815 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.755, ["y"] = 0.815 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 83325 }, ["questLines"] = { { ["id"] = 5648, ["name"] = "Rak-Ush", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[79120] = { ["id"] = 79120, ["name"] = "Beetle in a Haystack", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79114, 79115, 79117, 79118, 79119, 79120, 79121, 79122, 79123, 83325 }, ["description"] = "There are still feral stagshells on the outskirts of Rak-Ush. This scent grenade should be sufficient in stunning the beasts and alerting the niffen to their location. Once they are stunned, one of the rats will take them back to their hollow. Capture them and bring them back. We will be waiting.", ["objectivesText"] = "Capture and return six Feral Stagshells to Rak-Ush. Progress: We still require more stagshells.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["rewardItems"] = { 213392 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 214356, ["x"] = 0.755, ["y"] = 0.816 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 214356, ["x"] = 0.755, ["y"] = 0.816 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.755, ["y"] = 0.816 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 79118 }, ["questLines"] = { { ["id"] = 5648, ["name"] = "Rak-Ush", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[79121] = { ["id"] = 79121, ["name"] = "Bug Test", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79114, 79115, 79117, 79118, 79119, 79120, 79121, 79122, 79123, 83325 }, ["description"] = "Oh, I'm sorry, did you think this was a one and done assignment? If you did, Vix'aron would gladly \"show you the door\", as it were. The stagshells will require constant maintenance. Food. Water. Those sorts of things. Loathe as I am to admit it, the niffen are much more skilled at caring for swarmbeasts than Vix'aron or I. They can enlighten you on your duties, if this was not explanation enough.", ["objectivesText"] = "Speak to Aromash and care for the stagshells in Rak-Ush. Progress: Do not return to me until you have finished your lessons with the niffen.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 214359, ["x"] = 0.755, ["y"] = 0.815 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 214359, ["x"] = 0.755, ["y"] = 0.815 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.755, ["y"] = 0.815 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 79120 }, ["questLines"] = { { ["id"] = 5648, ["name"] = "Rak-Ush", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[79122] = { ["id"] = 79122, ["name"] = "Scarab Scouting", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79114, 79115, 79117, 79118, 79119, 79120, 79121, 79122, 79123, 83325 }, ["description"] = "The stagshells are of the utmost importance to Anub'azal's war campaign. We have a keen sense of smell, but only the stagshells are able to seek out valuable Kaheti truffles. The truffles are a key ingredient in several... explosive elixirs, as it were. If you desire details, Aromash can give you more.", ["objectivesText"] = "Use a Rak-Ush Stagshell to find 5 Kaheti truffles. Progress: We need an abundance of truffles to ensure we are properly prepared.", ["rewardGold"] = 292100, ["rewardXP"] = 10595, ["rewardItems"] = { 228439, 228440, 228441, 228442 }, ["rewardChoices"] = { 228439, 228440, 228441, 228442 }, ["rewardCurrencies"] = { { ["id"] = 3003, ["amount"] = 500 }, { ["id"] = 3056, ["amount"] = 35 } }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 214359, ["x"] = 0.755, ["y"] = 0.815 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 214359, ["x"] = 0.755, ["y"] = 0.815 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.755, ["y"] = 0.815 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 79121 }, ["questLines"] = { { ["id"] = 5648, ["name"] = "Rak-Ush", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[79123] = { ["id"] = 79123, ["name"] = "Permanent Hire", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79114, 79115, 79117, 79118, 79119, 79120, 79121, 79122, 79123, 83325 }, ["description"] = "Rak-Ush is beginning to look like a functioning swarmery. The role of delegation has suited me and Vix'aron well. You will continue to aid the niffen. In return, you may keep a portion of the wealth the swarmbeasts produce. Saffrin has more detailed plans around the development of the swarmery. Go speak to him, I have nothing else to say to you.", ["objectivesText"] = "Speak with Saffrin in Rak-Ush. Progress: You have not spoken to Saffrin yet, have you? Otherwise you would not be here.", ["rewardGold"] = 29200, ["rewardXP"] = 1325, ["rewardItems"] = { 225935 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 214359, ["x"] = 0.755, ["y"] = 0.815 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 217250, ["x"] = 0.748, ["y"] = 0.81 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.755, ["y"] = 0.815 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 79122 }, ["questLines"] = { { ["id"] = 5648, ["name"] = "Rak-Ush", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[79124] = { ["id"] = 79124, ["name"] = "Conduit of the Southern Storm", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 79107, 79124, 79129, 79140, 79145, 79146, 79147, 79156, 79157, 79475, 79476, 79477, 79480, 81912, 81913, 81914, 81915 }, ["series"] = { 81914 }, ["description"] = "I'll tell you what I told Baelgrim when we last spoke. The binding of stormrooks is wrong. These creatures are as smart as any earthen. Some I'd say are smarter. But... Lufsela seems to be different. If her stormrook follows her willingly, then perhaps others will make that choice as well if she summons them. To summon rooks, we need Baelgrim's conduit. It's tucked away here somewhere. Have a look around, and maybe ask these pilgrims if they have seen it.", ["objectivesText"] = "Find the Conduit of the Southern Storm . Progress: Have you found the conduit?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 218455 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 214995, ["x"] = 0.522667, ["y"] = 0.489 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 215039, ["x"] = 0.266, ["y"] = 0.594667 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.522667, ["y"] = 0.489 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 81914 }, ["questLines"] = { { ["id"] = 5523, ["name"] = "Ties That Bind", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5523, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79125] = { ["id"] = 79125, ["name"] = "The Kalimdor Cup Begins", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 84, ["storyline"] = { 79125 }, ["series"] = { 78040, 78047, 79126, 79127, 79128 }, ["description"] = "Skyrider! Lord Andestrasz has left the Dragon Isles and is visiting Stormwind. He's looking for capable skyriders like yourself to compete in new races!", ["objectivesText"] = "Visit Lord Andestrasz in Stormwind.", ["rewardGold"] = 29200, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 214031, ["x"] = 0.618, ["y"] = 0.7505 }, { ["mapID"] = 2339, ["npcID"] = 220307, ["x"] = 0.46, ["y"] = 0.546 }, { ["mapID"] = 2339, ["npcID"] = 220865, ["x"] = 0.566667, ["y"] = 0.286 }, { ["mapID"] = 2339, ["npcID"] = 220870, ["x"] = 0.41, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 214111, ["x"] = 0.6, ["y"] = 0.663 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.7505 }, ["mapCandidates"] = { ["npc"] = { 84, 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["nextQuests"] = { 76426 } },
