[79127] = { ["id"] = 79127, ["name"] = "The Outland Cup Begins", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 1519, ["mapID"] = 87, ["storyline"] = { 79127 }, ["series"] = { 78040, 78047, 79125, 79126, 79128 }, ["description"] = "Skyrider! Lord Andestrasz has left the Dragon Isles and is visiting Stormwind. He's looking for capable skyriders like yourself to compete in new races!", ["objectivesText"] = "Visit Lord Andestrasz in Stormwind.", ["rewardGold"] = 34100, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 87, ["npcID"] = 214022, ["x"] = 0.285, ["y"] = 0.67925 }, { ["mapID"] = 84, ["npcID"] = 214031, ["x"] = 0.618, ["y"] = 0.7505 }, { ["mapID"] = 1161, ["npcID"] = 214095, ["x"] = 0.678, ["y"] = 0.182 }, { ["mapID"] = 2339, ["npcID"] = 220307, ["x"] = 0.46, ["y"] = 0.546 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 214111, ["x"] = 0.6, ["y"] = 0.663 } }, ["coords"] = { ["mapID"] = 87, ["source"] = "quest_giver", ["x"] = 0.285, ["y"] = 0.67925 }, ["mapCandidates"] = { ["npc"] = { 84, 87, 1161, 2339 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["nextQuests"] = { 78047 } },
[79128] = { ["id"] = 79128, ["name"] = "The Outland Cup Begins", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 79128 }, ["series"] = { 78040, 78047, 79125, 79126, 79127 }, ["description"] = "Skyrider! Lord Andestrasz has left the Dragon Isles and is visiting Orgrimmar. He's looking for capable skyriders like yourself to compete in new races!", ["objectivesText"] = "Visit Lord Andestrasz in Orgrimmar.", ["rewardGold"] = 34100, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 213769, ["x"] = 0.5255, ["y"] = 0.795 }, { ["mapID"] = 1165, ["npcID"] = 214097, ["x"] = 0.512, ["y"] = 0.408 }, { ["mapID"] = 2339, ["npcID"] = 220307, ["x"] = 0.46, ["y"] = 0.546 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 214112, ["x"] = 0.524, ["y"] = 0.599 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.5255, ["y"] = 0.795 }, ["mapCandidates"] = { ["npc"] = { 85, 1165, 2339 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["nextQuests"] = { 78047 } },
[79129] = { ["id"] = 79129, ["name"] = "Rook Rally", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 79107, 79124, 79129, 79140, 79145, 79146, 79147, 79156, 79157, 79475, 79476, 79477, 79480, 81912, 81913, 81914, 81915 }, ["series"] = { 79475, 79476 }, ["description"] = "Now that we've got the conduit all charged, I suppose it's time we joined everyone on the peak. Thrall talked me through what to expect, but also said summoning the stormrooks will require me to trust my feelings and instincts. An earthen trusting their feelings and instincts. That's... a challenge. You will help me, right? I'm not a fighter, and it looks dangerous up there. If anything happens to me, make sure Shraubendre makes it out safe. Please.", ["objectivesText"] = "Safeguard the summoning ritual.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 223427, 223447, 223453, 223465 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 215039, ["x"] = 0.266, ["y"] = 0.594667 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 214919, ["x"] = 0.3565, ["y"] = 0.5845 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.266, ["y"] = 0.594667 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 79475, 79476 }, ["questLines"] = { { ["id"] = 5523, ["name"] = "Ties That Bind", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5523, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79130] = { ["id"] = 79130, ["name"] = "The Northrend Cup Circuit", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 495, ["mapID"] = 2112, ["storyline"] = { 79130 }, ["series"] = { 79131, 79132, 79133 }, ["description"] = "It is time once again to test your mettle. My bronze colleagues have traveled to Northrend to create more new challenges. We would like to see if any daring skyriders will complete the entire circuit! Are you up to the task?", ["objectivesText"] = "Fly through Northrend Cup courses. Progress: Have you taken wing today?", ["rewardGold"] = 77400, ["rewardXP"] = 1030, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 206737, ["x"] = 0.27, ["y"] = 0.474 }, { ["mapID"] = 84, ["npcID"] = 214111, ["x"] = 0.6, ["y"] = 0.663 }, { ["mapID"] = 85, ["npcID"] = 214112, ["x"] = 0.524, ["y"] = 0.599 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 206737, ["x"] = 0.27, ["y"] = 0.474 }, { ["mapID"] = 84, ["npcID"] = 214111, ["x"] = 0.6, ["y"] = 0.663 }, { ["mapID"] = 85, ["npcID"] = 214112, ["x"] = 0.524, ["y"] = 0.599 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.27, ["y"] = 0.474 }, ["mapCandidates"] = { ["npc"] = { 84, 85, 2112 }, ["zone"] = { 495 } }, ["questType"] = "standard", ["sourceQuests"] = { 79131, 79132, 79133 } },
[79131] = { ["id"] = 79131, ["name"] = "The Northrend Cup Begins", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 79131 }, ["series"] = { 79130, 79132, 79133 }, ["description"] = "Skyrider! You just missed Lord Andestrasz . He's looking for capable skyriders like yourself to compete in new races!", ["objectivesText"] = "Visit Lord Andestrasz in Valdrakken.", ["rewardGold"] = 10500, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199261, ["x"] = 0.390667, ["y"] = 0.61 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 206737, ["x"] = 0.27, ["y"] = 0.474 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.390667, ["y"] = 0.61 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["nextQuests"] = { 79130 } },
