[79134] = { ["id"] = 79134, ["name"] = "A Spring Awakening", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Noblegarden", ["expansion"] = 10, ["zoneID"] = 15969, ["mapID"] = 2112, ["storyline"] = { 79134 }, ["series"] = { 78274 }, ["description"] = "The citizens of Goldshire have reported frequent interruptions to their recent festivities. Something about being overrun by angry... ducks? Perhaps you could look further into this conundrum.", ["objectivesText"] = "Speak with Zinnia Brooks at Goldshire in Elwynn Forest.", ["rewardGold"] = 28090, ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199261, ["x"] = 0.390667, ["y"] = 0.61 }, { ["mapID"] = 2339, ["npcID"] = 220307, ["x"] = 0.46, ["y"] = 0.546 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 211646, ["x"] = 0.42, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.390667, ["y"] = 0.61 }, ["mapCandidates"] = { ["npc"] = { 37, 2112, 2339 }, ["zone"] = { 15969 } }, ["questType"] = "standard" },
[79135] = { ["id"] = 79135, ["name"] = "Quacking Down", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["event"] = "Noblegarden", ["expansion"] = 10, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 79135 }, ["series"] = { 79136 }, ["description"] = "Those dratted ducks! Do you mind scaring them off again? I simply cannot leave my golden egg unattended!", ["objectivesText"] = "Scare off 10 ducks using the Horn of Honking . Progress: Have you sufficiently shooed those ducks yet?", ["rewardItems"] = { 45072, 216487 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 217125, ["x"] = 0.525, ["y"] = 0.412 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 217125, ["x"] = 0.525, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["sourceQuests"] = { 79578 }, ["db2LabelIDs"] = { 3250 } },
[79136] = { ["id"] = 79136, ["name"] = "A Spring Awakening", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Noblegarden", ["expansion"] = 10, ["zoneID"] = 15969, ["mapID"] = 2112, ["storyline"] = { 79136 }, ["series"] = { 79135 }, ["description"] = "The citizens of Razor Hill have reported frequent interruptions to their recent festivities due to a duck infestation, of all things. Perhaps you could look further into this conundrum.", ["objectivesText"] = "Talk to Sylnaria Fareflame in Razor Hill.", ["rewardGold"] = 34100, ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199261, ["x"] = 0.390667, ["y"] = 0.61 }, { ["mapID"] = 2339, ["npcID"] = 220307, ["x"] = 0.46, ["y"] = 0.546 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 217125, ["x"] = 0.525, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.390667, ["y"] = 0.61 }, ["mapCandidates"] = { ["npc"] = { 1, 2112, 2339 }, ["zone"] = { 15969 } }, ["questType"] = "standard" },
[79137] = { ["id"] = 79137, ["name"] = "The Wall Between Us", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 4706, ["mapID"] = 21, ["storyline"] = { 78178, 78180, 78181, 78182, 78183, 78184, 78185, 78186, 78187, 78188, 78189, 78597, 79137 }, ["description"] = "I know this fight was not ours, <name>. But I thank you for your assistance. It was with the Alliance's assistance that Lordaeron was cleansed and the favor has now been returned. I do not think I can hope for peace. Instead, I will hope that these efforts have led to at least an understanding of the plights of both Gilneans and the Forsaken. Let us meet with Lilian in Pyrewood Village. This celebration is not for us.", ["objectivesText"] = "Speak with Lilian and Calia in Pyrewood Village.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 211788, 211873 }, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 210965, ["x"] = 0.428, ["y"] = 0.726 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 210964, ["x"] = 0.426, ["y"] = 0.727 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.726 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 4706 } }, ["questType"] = "standard", ["sourceQuests"] = { 78189 }, ["questLines"] = { { ["id"] = 5538, ["name"] = "The Gilneas Reclamation", ["orderIndex"] = 12, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 21 },
[79139] = { ["id"] = 79139, ["name"] = "Alone in the Dark", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78348, 78350, 78352, 78353, 78354, 78384, 78392, 78393, 79139, 83552 }, ["description"] = "My people do not think that this Black Blood is a threat to our world. It has sat dormant for ages, after all. Why should that change now? But the world is changing more quickly than my people realize. The nerubians' decision to extract the Blood for their own ends is proof of that. The nerubians hold a watchtower not far from here. The ones who survived the pit could not have gotten too far. We should give chase immediately.", ["objectivesText"] = "Investigate the Eye of Ansurek. Progress: <The spider looks at you expectantly.>", ["rewardGold"] = 210675, ["rewardXP"] = 7945, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 215113, ["x"] = 0.358, ["y"] = 0.582 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 216213, ["x"] = 0.4888, ["y"] = 0.5104 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.358, ["y"] = 0.582 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 78352, 78353 }, ["questLines"] = { { ["id"] = 5520, ["name"] = "Friends in the Dark", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5520, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5520, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[79140] = { ["id"] = 79140, ["name"] = "Goldbricking", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 79107, 79124, 79129, 79140, 79145, 79146, 79147, 79156, 79157, 79475, 79476, 79477, 79480, 81912, 81913, 81914, 81915 }, ["description"] = "Is this what we are to rely on to help us defeat Xal'atath? The Unbound define themselves by their desertion. And the Oathsworn, for being made of stone, are pretty soft. City life hasn't done them any favors. We've got a lot of work to do. Get down there and give these earthen a taste of what it's like to face a real threat. Try not to knock any \"offline,\" but a maiming here or there would send a strong message to the rest.", ["objectivesText"] = "Spar with undisciplined earthen trainees. Progress: Don't go easy on them. They're made of stone after all.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 215187, ["x"] = 0.452, ["y"] = 0.569 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 215187, ["x"] = 0.452, ["y"] = 0.569 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.569 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 79146 }, ["questLines"] = { { ["id"] = 5523, ["name"] = "Ties That Bind", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5523, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79145] = { ["id"] = 79145, ["name"] = "Metal and Stone", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 79107, 79124, 79129, 79140, 79145, 79146, 79147, 79156, 79157, 79475, 79476, 79477, 79480, 81912, 81913, 81914, 81915 }, ["description"] = "While some of these recruits struggle with discipline, most have a strong work ethic. They only need training and the equipment to make the most of it. Earthen weaponsmiths and armorers have been working around the clock to equip this fledgling army. But we could use some help getting the new armaments into the hands of these trainees.", ["objectivesText"] = "Equip earthen trainees for battle. Progress: Check in with Vindicator Jaelaana. She is in charge of distributing the weapons though she can be rather stingy. Be sure she doesn't send too many off for hand-to-hand training.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 223871, 223872, 223873, 223874, 223875, 223876, 223877 }, ["rewardChoices"] = { 223871, 223872, 223873, 223874, 223875, 223876, 223877 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 223205, ["x"] = 0.453, ["y"] = 0.569 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 223205, ["x"] = 0.453, ["y"] = 0.569 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.453, ["y"] = 0.569 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 79146 }, ["questLines"] = { { ["id"] = 5523, ["name"] = "Ties That Bind", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5523, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79146] = { ["id"] = 79146, ["name"] = "Ground Pounders", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 79107, 79124, 79129, 79140, 79145, 79146, 79147, 79156, 79157, 79475, 79476, 79477, 79480, 81912, 81913, 81914, 81915 }, ["description"] = "The rooks and their chosen riders will need time to bond. Perhaps you should use this time to check in on our other trainees. The Stormriders are the traditional army of the earthen, but many Unbound and Oathsworn have expressed willingness to fight at our side due to help in restoring their machines. Adelgonn , Geya'rah, and Turalyon are busy training them. Go and see if they need any assistance.", ["objectivesText"] = "Meet with Adelgonn , Geya'rah, and Turalyon.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 214919, ["x"] = 0.3565, ["y"] = 0.5845 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 215277, ["x"] = 0.451, ["y"] = 0.569 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.3565, ["y"] = 0.5845 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 79129 }, ["questLines"] = { { ["id"] = 5523, ["name"] = "Ties That Bind", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5523, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79147] = { ["id"] = 79147, ["name"] = "Flight Training 101", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 79107, 79124, 79129, 79140, 79145, 79146, 79147, 79156, 79157, 79475, 79476, 79477, 79480, 81912, 81913, 81914, 81915 }, ["series"] = { 79477, 81912, 81913, 81915 }, ["description"] = "Now that all of our recruits are present, it's high time we took to the air. See what I did there? High time? No? Right then. We'll be puttin' these rookies through their paces. Startin' with the basics of aerial maneuverin' at speed, we'll do our best to simulate the kind of precision flyin' we might expect below ground. After that, we'll see what these rooks can really do--an I think Thrall and Lufsela have somethin' special cookin'.", ["objectivesText"] = "Help Kurdran train recruits in aerial maneuvering. Progress: Let's set a good example for these new riders. Lead them through the course as quick as ye can.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 215211, ["x"] = 0.4685, ["y"] = 0.662 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 215211, ["x"] = 0.4685, ["y"] = 0.662 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.4685, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 79477 }, ["questLines"] = { { ["id"] = 5523, ["name"] = "Ties That Bind", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5523, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79148] = { ["id"] = 79148, ["name"] = "The Nibelgaz Refinery", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79148, 79149, 79193, 79194, 79327, 79679, 79944 }, ["series"] = { 79679 }, ["description"] = "Quickly! Elementals have overrun the Nibelgaz Mine and the refinery crew are trapped down there with them. I am especially worried about my fused, Munderut. His memory is not the best these days. If you are a friend, rescue him and the refinery workers. Here, take this healing clay . It only helps a little, but it should be enough for any injured to make their way back. I wish we had a rejuvenating crystal, but that is the stuff of legends.", ["objectivesText"] = "Rescue 6 Refinery Workers and look for Munderut.", ["rewardGold"] = 295000, ["rewardXP"] = 9920, ["rewardItems"] = { 218356 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 215208, ["x"] = 0.489, ["y"] = 0.148 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 215208, ["x"] = 0.489, ["y"] = 0.148 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.489, ["y"] = 0.148 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79573, 80434 }, ["questLines"] = { { ["id"] = 5619, ["name"] = "Rampage at Nibelgaz Mine", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[79149] = { ["id"] = 79149, ["name"] = "Rampage in the Refinery", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79148, 79149, 79193, 79194, 79327, 79679, 79944 }, ["description"] = "Catastrophe! Oh, this is awful. Awful! Those accursed slag heap elementals are keeping my refinery workers from being able to do their jobs. Duty demands we carry on our work. These delays will not be tolerated. You look competent enough. Go on, get down there and get to work destroying elementals. Production must not be slowed!", ["objectivesText"] = "Kill 10 Rampaging Elementals . Progress: Well? Did you destroy them? I need my crew back to work immediately!", ["rewardGold"] = 295000, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 215234, ["x"] = 0.493, ["y"] = 0.144 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 215234, ["x"] = 0.493, ["y"] = 0.144 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.493, ["y"] = 0.144 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79573, 80434 }, ["questLines"] = { { ["id"] = 5619, ["name"] = "Rampage at Nibelgaz Mine", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[79150] = { ["id"] = 79150, ["name"] = "Thespians at the Proscenium", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 79150 }, ["description"] = "When I wanted the Unbound to bring their plays to Dornogal, I didn't know what I would be up against. Or that my \"help\" would get in the way. My old friend Brokfor keeps interrupting us with his perfectionism. We try to build a set, but he stops everyone to inspect each nail. We try to paint, he complains the colors do not exactly match... you get the idea. I think Brokfor needs his own project. Maybe... cleaning up the Proscenium? Go ask him to help and keep him occupied.", ["objectivesText"] = "Help Architect Brokfor clean up the Proscenium. Progress: Have you helped Brokfor straighten up?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 214296, ["x"] = 0.564, ["y"] = 0.514 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 214296, ["x"] = 0.564, ["y"] = 0.514 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.514 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14776 } }, ["questType"] = "standard" },
[79151] = { ["id"] = 79151, ["name"] = "An Orphan's Request", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79151, 79152, 79153, 79154, 83182 }, ["description"] = "Wow, you look really strong! Would you be able to help me? My parents were killed by the mean kobyss. When I came here, I left my favorite, most well loved teddy ever behind. Could you go get it for me?", ["objectivesText"] = "Retrieve Alyza's Much Loved Teddy Bear from the Hungering Pool in Hallowfall . Progress: I will make the kobyss regret ever setting foot in these lands.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["rewardItems"] = { 216604 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 215237, ["x"] = 0.416, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 218062, ["x"] = 0.524, ["y"] = 0.502 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.416, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78658 }, ["questLines"] = { { ["id"] = 5527, ["name"] = "An Orphan's Dilemma", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[79152] = { ["id"] = 79152, ["name"] = "Gutting the Pool", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79151, 79152, 79153, 79154, 83182 }, ["description"] = "The kobyss are... a bit larger than I expected, and I might--might, you understand?--have more trouble with them than I originally anticipated. Kill any stupid fish-faces you see.", ["objectivesText"] = "Kill 10 kobyss in The Hungering Pool in Hallowfall . Progress: Yes, make them bleed. Make them pay!", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 218062, ["x"] = 0.524, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 215254, ["x"] = 0.50519, ["y"] = 0.501 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.524, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 79151 }, ["questLines"] = { { ["id"] = 5527, ["name"] = "An Orphan's Dilemma", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[79153] = { ["id"] = 79153, ["name"] = "Vae Victis", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79151, 79152, 79153, 79154, 83182 }, ["description"] = "Ah it's time. Kill their leader. Salt his bones, take his head, and laugh as his tribe crumbles! Sharpscale's last moments are upon him, and he doesn't even realize it yet. Stupid fish-face.", ["objectivesText"] = "Kill Sharpscale the Devourer and retrieve its head in the Hungering Pool in Hallowfall . Progress: His skull would make a good cup I think? Perhaps a mantle ornament?", ["rewardGold"] = 561800, ["rewardXP"] = 12740, ["rewardItems"] = { 217175 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 215254, ["x"] = 0.50519, ["y"] = 0.501 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 215254, ["x"] = 0.50519, ["y"] = 0.501 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.50519, ["y"] = 0.501 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 79152, 83182 }, ["questLines"] = { { ["id"] = 5527, ["name"] = "An Orphan's Dilemma", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[79154] = { ["id"] = 79154, ["name"] = "A Final Goodbye", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79151, 79152, 79153, 79154, 83182 }, ["description"] = "Well, parents avenged, fish killed, more fish killed, biggest fish killed. Pretty good day. I guess I should go burn stuff.", ["objectivesText"] = "Help Alyza say goodbye in the Hungering Pool in Hallowfall .", ["rewardGold"] = 292100, ["rewardXP"] = 10190, ["rewardItems"] = { 225949 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 25 }, { ["id"] = 2899, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 215254, ["x"] = 0.50519, ["y"] = 0.501 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 219368, ["x"] = 0.418, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.50519, ["y"] = 0.501 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 79153 }, ["questLines"] = { { ["id"] = 5527, ["name"] = "An Orphan's Dilemma", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[79156] = { ["id"] = 79156, ["name"] = "The Edicts", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78226, 78228, 78244, 78348, 78352, 78353, 78620, 78621, 78624, 78630, 78658, 78659, 78671, 78948, 79156, 83503, 91868 }, ["description"] = "Merrix and Adelgonn will be expecting an update. On my way here, I heard that they're all heading to the Proscenium to commit to the war officially. You should go and brief them on the readiness of the Stormriders. I'd like a moment with Zarein here. But we'll be along soon. And we'll be bringing Baelgrim's spirit with us.", ["objectivesText"] = "Report to Merrix and Adelgonn. Progress: This is a critical moment for all earthen.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 79869, 87399 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 214916, ["x"] = 0.57, ["y"] = 0.505 }, { ["mapID"] = 2248, ["npcID"] = 214995, ["x"] = 0.522667, ["y"] = 0.489 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 214916, ["x"] = 0.57, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 79480 }, ["questLines"] = { { ["id"] = 5523, ["name"] = "Ties That Bind", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 6006, ["name"] = "Catch Up: War Within: Wrapper 3", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5523, ["questLineOrder"] = 1 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6006, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79157] = { ["id"] = 79157, ["name"] = "Titanic Failsafe", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 79107, 79124, 79129, 79140, 79145, 79146, 79147, 79156, 79157, 79475, 79476, 79477, 79480, 81912, 81913, 81914, 81915 }, ["description"] = "So, the titans sent their ancient machines against their disobedient children. Would our creators have us protect the Coreway at the expense of all else? At the expense of Azeroth herself? Are we meant to preside over a road untraveled, leading to the world's dead heart? No, today we are all Unbound, and we will fight for our freedom. For Azeroth!", ["objectivesText"] = "Defeat the colossal titan construct . Progress: None on this isle will be safe until that titan construct is dealt with. Go!", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 223428, 223446, 223457, 223468 }, ["rewardCurrencies"] = { { ["id"] = 2897, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 214916, ["x"] = 0.57, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223944, ["x"] = 0.315, ["y"] = 0.595 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 2248, 2339 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 79156 }, ["questLines"] = { { ["id"] = 5523, ["name"] = "Ties That Bind", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5523, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79158] = { ["id"] = 79158, ["name"] = "Seeds of Salvation", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79158 }, ["description"] = "These once obedient harvestbots have run amok and are wreaking havoc in our fields. The success of our community depends on getting our seeds in the ground, but most of the seeds are in the hands of those harvesters! Would you venture into the fields, eliminate any rogue machines, gather the seeds, and finish the planting?", ["objectivesText"] = "Recover Harvest Seeds and plant 8 seeds in Seed-Ready Soil . Progress: Have you planted the seeds?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 211947 }, ["rewardCurrencies"] = { { ["id"] = 2899, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 206441, ["x"] = 0.652, ["y"] = 0.28 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 206441, ["x"] = 0.652, ["y"] = 0.28 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.28 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 76599 } },
[79159] = { ["id"] = 79159, ["name"] = "Dereliction of Duty", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79159, 79160, 79162 }, ["description"] = "A moment, if you have one. One of my lieutenants, Shinda Creedpike , did not report in at first bonfire. That may not seem like a large issue to you, but the Arathi in Hallowfall survive only because we follow orders and stand for our brethren. I am not cruel. I do not want to punish a man for his weakness in this terrible environment. Can you find him and bring him back? Take all the time you need.", ["objectivesText"] = "Find Shinda Creedpike at Mereldar in Hallowfall . Progress: Dawnsurge must have sent you. It seems like my respite is over.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 215306, ["x"] = 0.414, ["y"] = 0.524 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 215301, ["x"] = 0.4, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.414, ["y"] = 0.524 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5607, ["name"] = "The Weight of Duty", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[79160] = { ["id"] = 79160, ["name"] = "Fishing is Good for the Soul", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79159, 79160, 79162 }, ["description"] = "I used to fish with my mother at the local pond when I was a child. It wasn't the fish that made the experience--my mother was famously terrible at cooking--but the tranquility and bonding time. Perhaps I could find a portion of that peace again here. There's a spot south of Mereldar that the others use to fish. I'll meet you there!", ["objectivesText"] = "Meet Shinda at the fishing hole. Progress: Maybe I can find peace in the act of fishing.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["rewardItems"] = { 228362, 228363, 228364, 228365, 228366, 228367 }, ["rewardChoices"] = { 228362, 228363, 228364, 228365, 228366, 228367 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 25 }, { ["id"] = 2899, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 215301, ["x"] = 0.4, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 215301, ["x"] = 0.4, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 79159 }, ["questLines"] = { { ["id"] = 5607, ["name"] = "The Weight of Duty", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[79162] = { ["id"] = 79162, ["name"] = "Burnout", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79159, 79160, 79162 }, ["description"] = "Please return to Commander Dawnsurge and give them my sincere apologies for my absence. I will submit myself for punishment for my trespass after my shift.", ["objectivesText"] = "Return to Endiri Dawnsurge in Mereldar.", ["rewardGold"] = 154900, ["rewardXP"] = 5095, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 215301, ["x"] = 0.4, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 215306, ["x"] = 0.414, ["y"] = 0.524 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 79160 }, ["questLines"] = { { ["id"] = 5607, ["name"] = "The Weight of Duty", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[79165] = { ["id"] = 79165, ["name"] = "A Moment to Rest", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79165, 79166, 79167, 79168, 83497 }, ["description"] = "Good, you're both here. I have a favor to ask. Faerin's wandered off. I think it might help if you and your... disheveled friend here find her. She'll be in Light's Redoubt.", ["objectivesText"] = "Find Faerin near Light's Redoubt.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 215341, ["x"] = 0.43, ["y"] = 0.524 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 218541, ["x"] = 0.422, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.524 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 83497 }, ["questLines"] = { { ["id"] = 5542, ["name"] = "Rest at Last", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[79166] = { ["id"] = 79166, ["name"] = "Lost Pieces", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79165, 79166, 79167, 79168, 83497 }, ["description"] = "There was a time when I would have known what words to say to help her. But now... they are as lost to me as everything else. <Anduin sighs.> There must be something we can do. Her old Lamplighter companion, this Andari... would have had one of those tinderboxes, right? They seem important for funeral rites. I'll accompany Faerin back to Mereldar and meet you there. If you think there's hope of finding Andari's lost belongings ... could you try to look?", ["objectivesText"] = "Collect 8 Lost Personal Effects from enemies in the Harrowing Depths. Progress: There's no time to mourn. Not when there's fighting to be done. If you have time to mourn, you have time to train. To make sure we don't lose anyone else.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 211959 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 218541, ["x"] = 0.422, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 215331, ["x"] = 0.422, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 79165 }, ["questLines"] = { { ["id"] = 5542, ["name"] = "Rest at Last", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[79167] = { ["id"] = 79167, ["name"] = "Crowdsourcing", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["description"] = "Light's Gambit is an old and honored game. There's a reason so many Arathi play it! It can teach you a lot about strategy. And it can tell you a lot about your opponents. But we're still missing a few pieces that we need in order to play. Sometimes, folks around Mereldar lend us pieces for a game. Could you ask around?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["npcID"] = 215331, ["x"] = 0.406, ["y"] = 0.708, ["mapID"] = 2215 } }, ["ends"] = { { ["npcID"] = 218267, ["x"] = 0.432, ["y"] = 0.524, ["mapID"] = 2215 } }, ["coords"] = { ["x"] = 0.406, ["y"] = 0.708, ["source"] = "quest_giver", ["mapID"] = 2215 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 79166 }, ["questLines"] = { { ["id"] = 5542, ["name"] = "Rest at Last", ["orderIndex"] = 3, ["flags"] = 0 } } },
[79168] = { ["id"] = 79168, ["name"] = "Light's Gambit", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79165, 79166, 79167, 79168, 83497 }, ["description"] = "It's fine! We can catch you up on the rest of the rules later! Resolving combat is the most fun, anyway! You and Anduin can team up against me. Perhaps with the both of you together, you'll stand a chance! <Faerin laughs.>", ["objectivesText"] = "Grab the castle piece to start a game of Light's Gambit with Faerin and Anduin.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 223432 }, ["rewardCurrencies"] = { { ["id"] = 2899, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 218267, ["x"] = 0.431, ["y"] = 0.525 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 217909, ["x"] = 0.432, ["y"] = 0.524 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.431, ["y"] = 0.525 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 79167 }, ["questLines"] = { { ["id"] = 5542, ["name"] = "Rest at Last", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[79173] = { ["id"] = 79173, ["name"] = "Supply the Effort", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79173 }, ["description"] = "When shadow fell upon our town, many necessary supplies were taken in the cover of darkness. With the light returning, it is time to rebuild, but first, we must retrieve what was lost. Search the surrounding areas, recover any supplies that might be useful.", ["objectivesText"] = "Recover various stolen items from the surrounding area to satisfy our needs. Progress: Have you recovered the stolen items?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 211964, 211966, 211967, 211968, 211969, 211970, 211971, 211972, 211973, 211974, 211975, 228741 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 40 }, { ["id"] = 2899, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 206150, ["x"] = 0.632, ["y"] = 0.294 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 206150, ["x"] = 0.632, ["y"] = 0.294 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.632, ["y"] = 0.294 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 79383 } },
[79174] = { ["id"] = 79174, ["name"] = "Infested Infestation", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79174, 79355, 79356, 79357 }, ["description"] = "These spore-afflicted beasts at Pillar-nest Vosh been a thorn in our side since setting up Faerin's Advance. They be spreading thick clouds of spores. I never be seeing anything like it! They already attacked once. Won't be long till they attack again. If we got any hope of survivin', we need to cull dere numbers. Go to Pillar-nest Vosh and take some of those spore-afflicted beasts out!", ["objectivesText"] = "Kill 12 spore-afflicted beasts at Pillar-nest Vosh.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 215349, ["x"] = 0.578, ["y"] = 0.196 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 215349, ["x"] = 0.578, ["y"] = 0.196 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.196 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 78384 }, ["questLines"] = { { ["id"] = 5647, ["name"] = "Pillar-nest Vosh", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[79175] = { ["id"] = 79175, ["name"] = "I Think I'm a Drone Now", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78233, 78234, 78236, 78237, 78249, 78250, 78251, 78254, 78255, 78256, 78383, 79175, 79625, 80399 }, ["description"] = "There, I have extended some goodwill. You have a little goblin friend. I know how much your kind clings to each other for warmth. And now you both will do things for me. First, I will provide you with my pheromone scent mark. It will keep my loyal soldiers from attacking you. It marks you as mine.", ["objectivesText"] = "Allow Anub'azal to mark you with his pheromones. Progress: Don't waste my time. Are you ready to accept my mark? Step into the pheromone cloud with your <race> friend, and rub it on.", ["rewardGold"] = 70900, ["rewardXP"] = 2650, ["rewardItems"] = { 225515, 225526, 225535, 225538 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 217330, ["x"] = 0.454, ["y"] = 0.198 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 217330, ["x"] = 0.454, ["y"] = 0.198 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.198 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 79625 }, ["questLines"] = { { ["id"] = 5521, ["name"] = "Unraveling the Trapped", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5521, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5521, ["questLineOrder"] = 12 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[79176] = { ["id"] = 79176, ["name"] = "Opals and Runes", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 79176, 79521, 79522, 79523, 79525, 79526, 79527, 79528, 79529, 79530, 79542, 79543, 79544, 79545, 79546, 80207 }, ["series"] = { 79544, 79545 }, ["description"] = "You have certainly made my disaster of a day far less stressful, <name>. For that, you have the thanks of the entire Forgegrounds and those who keep it running. < Vokgret winks as she gives you a knowing smile.> Bevrusi was right to send you to me. Do tell her not to be a stranger now. I could use more friends from the Deeps. Here is her liquid opal. Give it to her with my compliments.", ["objectivesText"] = "Trade the Vial of Liquid Opal for the Speakeasy Passrune from Bevrusi. Progress: Everyone in the city is in need of something, and there is always someone with the means to acquire it.", ["rewardGold"] = 154900, ["rewardXP"] = 4760, ["rewardItems"] = { 217414, 218085 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 217091, ["x"] = 0.452, ["y"] = 0.488 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 217097, ["x"] = 0.605, ["y"] = 0.332 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.488 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 79544 }, ["questLines"] = { { ["id"] = 5605, ["name"] = "Merrix and Steelvein", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79178] = { ["id"] = 79178, ["name"] = "Play Hearthstone!", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 1, ["storyline"] = { 79178 }, ["description"] = "It's time to play Hearthstone! Here's a starter pack -- open it up and add those cards to you collection. Then, if you can find a seat at the game table, then sit down with someone else and play! Or if you can't find a seat, then you'll want some Wild cards.... I didn't tell you this but there's a shady card dealer lurking around here somewhere.", ["objectivesText"] = "Play 5 Hearthstone cards at a Hearthstone Game Table, or Wild Cards NEAR a Hearthstone Game Table. Progress: Like the game so far? Give it a chance and play those cards!", ["rewardGold"] = 31500, ["rewardItems"] = { 211965, 212979 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 215409, ["x"] = 0.53, ["y"] = 0.152 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 215409, ["x"] = 0.53, ["y"] = 0.152 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.152 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 79184 } },
[79184] = { ["id"] = 79184, ["name"] = "It's Hearthstone's Anniversary!", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 79184 }, ["description"] = "\"Hearthstone's been played for ten years, can you believe it? I'm hosting Hearthstone games in Valdrakken, way up in the Seat of the Aspects. Come join us! -Farala, Master of Ceremonies\"", ["objectivesText"] = "Speak with M.C. Farala in Valdrakken, in the Seat of the Aspects.", ["rewardGold"] = 33500, ["rewardItems"] = { 212154 }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 215409, ["x"] = 0.53, ["y"] = 0.152 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.152 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard" },
[79186] = { ["id"] = 79186, ["name"] = "It's Hearthstone's Anniversary!", ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 79186 }, ["description"] = "Hearthstone's been played for ten years, can you believe it? Farala, Master of Ceremonies, is hosting Hearthstone games at the Stormwind Harbor. Come join in the celebration!", ["objectivesText"] = "Speak with M.C. Farala in Stormwind.", ["rewardGold"] = 29200, ["rewardItems"] = { 212155 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 212154, 212155 } },
[79189] = { ["id"] = 79189, ["name"] = "It's Hearthstone's Anniversary!", ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 79189 }, ["description"] = "\"Hearthstone's been played for ten years, can you believe it? Farala, Master of Ceremonies, is hosting Hearthstone games in Durotar, between Orgrimmar and the docks. Come join in the celebration!", ["objectivesText"] = "Speak with M.C. Farala in Durotar.", ["rewardGold"] = 29200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 231019 } },
[79193] = { ["id"] = 79193, ["name"] = "Spinning Spore Spines", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14801, ["mapID"] = 2214, ["storyline"] = { 79148, 79149, 79193, 79194, 79327, 79679, 79944 }, ["description"] = "Orsenth sent you? And we are supposedly fused? Why... so I am wearing a medallion. But I have no memory... Well, no time for that. Did you see the spinning spores on your way here? I need the spines that they grow for... I need them for... now what was it again? Oh yes! There is no better instrument for carving out the fine detail that my work as a gem carver requires than those spines. Will you collect some? I will make my way back to the refinery. I am eager to get back and meet this Orsenth.", ["objectivesText"] = "Collect 150 Spore Spines for Munderut . Progress: Why, what is this now? You're a stranger to these depths, are you not? What are you doing here? <You remind him of all you've spoken of.> Well, what are you waiting for? Go and get me those spines!", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["rewardItems"] = { 212529 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 215209, ["x"] = 0.4985, ["y"] = 0.118 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 215209, ["x"] = 0.4985, ["y"] = 0.118 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.4985, ["y"] = 0.118 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79679 }, ["questLines"] = { { ["id"] = 5619, ["name"] = "Rampage at Nibelgaz Mine", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[79194] = { ["id"] = 79194, ["name"] = "To the Source", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79148, 79149, 79193, 79194, 79327, 79679, 79944 }, ["series"] = { 79944 }, ["description"] = "Orsenth told me you have been instrumental in dealing with the elemental problem here at the mine. I am Keldaz , supervisor for the militia. We came as soon as word of the attack reached us in Gundargaz. The miners you rescued said that the elementals poured out of the northeast mine shaft. I will leave some of my guards here to lend their support and have sent for reinforcements. If you are still willing to help, meet me outside the cave and let us see what we can do to staunch the flow of elementals.", ["objectivesText"] = "Meet Keldaz outside of the northeastern mine.", ["rewardGold"] = 77400, ["rewardXP"] = 2480, ["rewardItems"] = { 25913, 25914, 25915, 36878, 36879, 36880, 36881, 36882, 36883, 52595, 52621, 52633, 66908, 66909, 66910, 131282, 142054, 155392, 155393, 155394, 155395, 155448, 159975, 193666, 193671, 198606, 245616 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 217474, ["x"] = 0.49, ["y"] = 0.148 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 223000, ["x"] = 0.532, ["y"] = 0.11 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.148 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79193 }, ["questLines"] = { { ["id"] = 5619, ["name"] = "Rampage at Nibelgaz Mine", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[79196] = { ["id"] = 79196, ["name"] = "Renowned with The Severed Threads", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79196 }, ["description"] = "The Weaver has been keeping an eye on you. She has determined you would be a better asset with more resources at your disposal. Come to the Weaver's Lair. I have a parcel waiting for you.", ["objectivesText"] = "Speak with Lady Vinazian in the Weaver's Lair.", ["rewardItems"] = { 225247 }, ["starts"] = { { ["x"] = 0.553, ["y"] = 0.412, ["mapID"] = 2255, ["npcID"] = 220867 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 220867, ["x"] = 0.552, ["y"] = 0.412 }, { ["mapID"] = 2255, ["npcID"] = 223750, ["x"] = 0.552, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questGiverID"] = 220867, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2596, ["threshold"] = 7500 } } } },
[79197] = { ["id"] = 79197, ["name"] = "Surface Bound", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2255, ["storyline"] = { 79197, 79328, 79333, 79344, 82153, 83271, 83286, 83315 }, ["series"] = { 79333, 84365, 84367 }, ["description"] = "<name>, the moment is upon us. We must make haste to the city of Dornogal, where our allies await. Only together do we stand a chance against Harbinger's machinations.", ["objectivesText"] = "Meet with Moira Thaurissan and your allies in Dornogal in the Isle of Dorn .", ["rewardGold"] = 154900, ["rewardXP"] = 5300, ["rewardItems"] = { 206350 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 219252, ["x"] = 0.556, ["y"] = 0.44 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 216149, ["x"] = 0.36, ["y"] = 0.804 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = { 2255, 2339 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 84022 }, ["questLines"] = { { ["id"] = 5551, ["name"] = "Against the Current", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5551, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79199] = { ["id"] = 79199, ["name"] = "Renowned with Keg Leg's Crew", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = { "emissary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 79199 }, ["description"] = "Your deeds have not gone unnoticed, and you continue to show that you are a renowned explorer! Return to the Dragonscale Basecamp as I have prepared more supplies to help you continue in your endeavours.", ["objectivesText"] = "Speak with Cataloger Jakes at the Dragonscale Basecamp.", ["rewardItems"] = { 204378 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[79200] = { ["id"] = 79200, ["name"] = "Who am I?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredRaces"] = { 85 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["mapID"] = 2322, ["storyline"] = { 79200, 79201, 79202, 79203, 79204, 81886, 81887, 81888, 81889, 83328 }, ["description"] = "It's good to see you're awake. I know you must have many questions and we are here to answer them. I am Dawn , and this is Foreman Uzjax. Many things have changed since your last slumber began, including our Awakening Protocol. We are both here to guide you through it. Like many other newly awakened, you have heard a distant yet powerful song thrumming within you. A radiant surge of change. Embrace it.", ["objectivesText"] = "Complete the first stage in the Awakening Protocol.", ["rewardGold"] = 292100, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.894, ["y"] = 0.48, ["mapID"] = 2322, ["npcID"] = 221839 } }, ["ends"] = { { ["x"] = 0.894, ["y"] = 0.48, ["mapID"] = 2322, ["npcID"] = 221839 } }, ["coords"] = { ["mapID"] = 2322, ["x"] = 0.894, ["y"] = 0.48 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 221839, ["questTurnInID"] = 221839, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5593, ["name"] = "New Awakenings", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2739, ["db2PoiUiMapID"] = 2322 },
[79201] = { ["id"] = 79201, ["name"] = "The Analysis Interface", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredRaces"] = { 85 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["mapID"] = 2322, ["storyline"] = { 79200, 79201, 79202, 79203, 79204, 81886, 81887, 81888, 81889, 83328 }, ["description"] = "This is the Analysis Interface. In order to ensure our primary programming remained intact, these consoles were installed with a series of inquiries to assess the memory matrix of the newly awakened. Although Dawn will encourage you to answer in any way that you please--I... well, I hope you'll answer truthfully. Proceed when ready.", ["objectivesText"] = "Complete the Analyzing Sequence in the Analysis Interface.", ["rewardGold"] = 292100, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.626, ["y"] = 0.492, ["mapID"] = 2322, ["npcID"] = 221891 } }, ["ends"] = { { ["x"] = 0.626, ["y"] = 0.492, ["mapID"] = 2322, ["npcID"] = 221891 } }, ["coords"] = { ["mapID"] = 2322, ["x"] = 0.626, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 221891, ["questTurnInID"] = 221891, ["questType"] = "standard", ["sourceQuests"] = { 79200 }, ["questLines"] = { { ["id"] = 5593, ["name"] = "New Awakenings", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2739, ["db2PoiUiMapID"] = 2322 },
[79202] = { ["id"] = 79202, ["name"] = "Rock Beats Rock", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredRaces"] = { 85 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["mapID"] = 2322, ["storyline"] = { 79200, 79201, 79202, 79203, 79204, 81886, 81887, 81888, 81889, 83328 }, ["description"] = "Welcome to the Procedural Forum. Foreman Uzjax informs me that this chamber once served as our assignment testing facility. With his guidance, we've repurposed this chamber. Earthen are not combat trained by design, so this room serves to prepare newly awakened earthen for the challenges of the unexplored world that lies ahead.", ["objectivesText"] = "Spar with 6 newly Awakened Earthen. Progress: Whether they were once Storm Riders or Peacekeepers or craftsman and laborers, martial prowess takes time to hone and refine.", ["rewardGold"] = 292100, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.477, ["y"] = 0.547, ["mapID"] = 2322, ["npcID"] = 221888 } }, ["ends"] = { { ["x"] = 0.477, ["y"] = 0.547, ["mapID"] = 2322, ["npcID"] = 221888 } }, ["coords"] = { ["mapID"] = 2322, ["x"] = 0.477, ["y"] = 0.547 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 221888, ["questTurnInID"] = 221888, ["questType"] = "standard", ["sourceQuests"] = { 79201, 83328 }, ["questLines"] = { { ["id"] = 5593, ["name"] = "New Awakenings", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2739, ["db2PoiUiMapID"] = 2322 },
[79203] = { ["id"] = 79203, ["name"] = "Authorization: Negated", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredRaces"] = { 85 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["mapID"] = 2322, ["storyline"] = { 79200, 79201, 79202, 79203, 79204, 81886, 81887, 81888, 81889, 83328 }, ["description"] = "The Bulwark of Authorization! That's what this chamber was once called. I had been working tirelessly to reconfigure it to its original state, when suddenly the whole blasted chamber started rumbling. A golem manifested out of nowhere and started attacking my machinists! We managed to escape, but the Golem locked down the chambers. Dawn seems to think you've got what it takes to deal with it. Up to the challenge?", ["objectivesText"] = "Defeat the Phalanx of Authorization within the Bulwark of Authorization.", ["rewardGold"] = 625600, ["rewardXP"] = 1770, ["starts"] = { { ["x"] = 0.309, ["y"] = 0.485, ["mapID"] = 2322, ["npcID"] = 221898 } }, ["ends"] = { { ["x"] = 0.309, ["y"] = 0.485, ["mapID"] = 2322, ["npcID"] = 221898 } }, ["coords"] = { ["mapID"] = 2322, ["x"] = 0.309, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 221898, ["questTurnInID"] = 221898, ["questType"] = "standard", ["sourceQuests"] = { 79202 }, ["questLines"] = { { ["id"] = 5593, ["name"] = "New Awakenings", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2739, ["db2PoiUiMapID"] = 2322 },
[79204] = { ["id"] = 79204, ["name"] = "Whoever You Want to Be", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredRaces"] = { 85 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["mapID"] = 2322, ["storyline"] = { 79200, 79201, 79202, 79203, 79204, 81886, 81887, 81888, 81889, 83328 }, ["description"] = "After an awakening protocol like that, I can see why Dawn says you're special. The world is not prepared for an earthen like you. Dawn and the Foreman are waiting for you in the Awakening Vestibule. Go on, then! Complete your Awakening Protocol and get out of here!", ["objectivesText"] = "Speak with Dawn to complete your Awakening Protocol.", ["rewardGold"] = 315900, ["rewardXP"] = 1415, ["rewardItems"] = { 224166 }, ["starts"] = { { ["x"] = 0.163, ["y"] = 0.481, ["mapID"] = 2322, ["npcID"] = 221900 } }, ["ends"] = { { ["x"] = 0.163, ["y"] = 0.481, ["mapID"] = 2322, ["npcID"] = 221900 } }, ["coords"] = { ["mapID"] = 2322, ["x"] = 0.163, ["y"] = 0.481 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 221900, ["questTurnInID"] = 221900, ["questType"] = "standard", ["sourceQuests"] = { 79203 }, ["questLines"] = { { ["id"] = 5593, ["name"] = "New Awakenings", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2739, ["db2PoiUiMapID"] = 2322 },
[79205] = { ["id"] = 79205, ["name"] = "Not Waste, Not Want", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78555, 78557, 78631, 78634, 78635, 78636, 78637, 78638, 78639, 78640, 78641, 78642, 78837, 78838, 78839, 79205, 79267, 80082, 80434, 83550 }, ["description"] = "Everything have use, friend. Even things stoneheads throw away and think worthless. Kobolds know better. Go and see what you can find. Need to scavenge lots of scrap. Enough for kobold crafting of new homes!", ["objectivesText"] = "Collect potentially useful scrap from around the Warrens. Progress: You will be surprised. Kobold crafting is amazing!", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["rewardItems"] = { 29931, 29938, 29943, 29945, 212177, 217015 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212991, ["x"] = 0.601333, ["y"] = 0.32 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212991, ["x"] = 0.601333, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.601333, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 78640 }, ["questLines"] = { { ["id"] = 5533, ["name"] = "By Candlelight", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5533, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5533, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[79206] = { ["id"] = 79206, ["name"] = "Broken Memories", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79206 }, ["description"] = "Something about this particular gemstone feels important. Perhaps it would be worthwhile to bring it to Speaker Brinthe .", ["objectivesText"] = "Bring the Faded Memory Gem to Brinthe. Provided item:", ["rewardGold"] = 232300, ["rewardXP"] = 7440, ["rewardItems"] = { 212178 }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212519, ["x"] = 0.555, ["y"] = 0.292 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.292 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 78634 } },
[79213] = { ["id"] = 79213, ["name"] = "The Anachronism", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78465, 78467, 79213, 79716, 83081, 83082, 83083, 83084, 83087 }, ["description"] = "Insert the batteries into the cylindrical holes on the console. Then, titans willing, we will see what it holds.", ["objectivesText"] = "Activate the Excavated Console and use the device to defeat the Sargassum Guardian in Golgrin's Reach. Progress: To obtain the power necessary, find an elemental of sufficient size to charge the artifact. If I am right, the titan artifact will do the rest.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 212602 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 225478, ["x"] = 0.616, ["y"] = 0.702 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 225478, ["x"] = 0.616, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.702 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78467, 79716 }, ["questLines"] = { { ["id"] = 5634, ["name"] = "Hidden Edicts", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79216] = { ["id"] = 79216, ["name"] = "Web of Manipulation", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79216 }, ["description"] = "This town has been under siege, overrun by spiders! Even when we clear them out, they always return. Something is behind these attacks! A small ledge northeast of Light's Bloom harbors these spiders. Scout out the ledge. Find out what is driving these spiders to attack us, and put an end to it!", ["objectivesText"] = "Explore the nearby ledge and deal with any threats within. Progress: Have you solved our spider problem?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 228741 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 40 }, { ["id"] = 2899, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 206150, ["x"] = 0.632, ["y"] = 0.294 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 206150, ["x"] = 0.632, ["y"] = 0.294 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.632, ["y"] = 0.294 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 79383 } },
[79217] = { ["id"] = 79217, ["name"] = "Back to Base", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79022, 79023, 79024, 79025, 79026, 79027, 79028, 79029, 79030, 79217, 79324, 79325, 80145, 80517 }, ["description"] = "Getting this factory up and running will be a challenge, but I think we'll figure out something. Let's head back to Gundargaz and consult with a friend of ours. His mind will be a big help to us here.", ["objectivesText"] = "Meet Brinthe back in Gundargaz.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 214663, ["x"] = 0.541, ["y"] = 0.748 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 217245, ["x"] = 0.449, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.541, ["y"] = 0.748 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79024 }, ["questLines"] = { { ["id"] = 5531, ["name"] = "The Machines March to War", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5531, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214, ["db2QuestHubAreaPoiID"] = 7911 },
[79218] = { ["id"] = 79218, ["name"] = "Renowned with the Hallowfall Arathi", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79218 }, ["description"] = "Your labors on behalf of our people have not gone unnoticed. Nor will they go unrewarded. Find me in Mereldar.", ["objectivesText"] = "Speak with Auralia Steelstrike in Mereldar.", ["rewardItems"] = { 225246 }, ["starts"] = { { ["x"] = 0.413, ["y"] = 0.531, ["mapID"] = 2215, ["npcID"] = 213145 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213145, ["x"] = 0.418, ["y"] = 0.54 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questGiverID"] = 213145, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2611, ["threshold"] = 7500 } } } },
[79219] = { ["id"] = 79219, ["name"] = "Renowned with the Council of Dornogal", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 79219 }, ["description"] = "The Council continues to be in your debt, friend. If you visit me in Dornogal, I will give you supplies to reduce that debt.", ["objectivesText"] = "Speak with Auditor Balwurz in Dornogal.", ["rewardItems"] = { 225239 }, ["starts"] = { { ["x"] = 0.391, ["y"] = 0.24, ["mapID"] = 2339, ["npcID"] = 223728 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223728, ["x"] = 0.393, ["y"] = 0.244 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.393, ["y"] = 0.244 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questGiverID"] = 223728, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2612, ["threshold"] = 7500 } } } },
[79220] = { ["id"] = 79220, ["name"] = "Renowned with the Assembly of the Deeps", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79220 }, ["description"] = "Good work deserves good reward, yes? Assembly is grateful. Waxmonger Squick is grateful. Show gratefulness with many supplies. Come see Waxmonger Squick in Gundargaz.", ["objectivesText"] = "Speak with Waxmonger Squick in Gundargaz.", ["rewardItems"] = { 225245 }, ["starts"] = { { ["x"] = 0.433, ["y"] = 0.328, ["mapID"] = 2214, ["npcID"] = 221390 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 221390, ["x"] = 0.452, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questGiverID"] = 221390, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2613, ["threshold"] = 7500 } } } },
[79221] = { ["id"] = 79221, ["name"] = "The Unusual Bug", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2255, ["storyline"] = { 79221 }, ["description"] = "Nerubians in Rak-Ush may find this strange little spider of interest.", ["objectivesText"] = "Deliver this Unusual Bug to Widow Arak'nai in Rak-Ush. Provided item:", ["rewardGold"] = 29200, ["rewardXP"] = 1470, ["rewardItems"] = { 212331 }, ["starts"] = { { ["x"] = 0.672, ["y"] = 0.218, ["mapID"] = 2215 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 207471, ["x"] = 0.556, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["startItems"] = { 212331 } },
[79222] = { ["id"] = 79222, ["name"] = "Shadow-Hardened Mainspring", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2214, ["storyline"] = { 79222 }, ["description"] = "<Maybe it was the effects of prolonged darkness or tinkering by Ezgi Irongear, but the strength of this spring would be of interest to Speaker Kuldas in Gundargaz.>", ["objectivesText"] = "Deliver this item to Kuldas in Gundargaz. Provided item:", ["rewardGold"] = 29200, ["rewardXP"] = 1470, ["rewardItems"] = { 212330 }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 217128, ["x"] = 0.453, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.453, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["startItems"] = { 212330 } },
[79223] = { ["id"] = 79223, ["name"] = "Finally, An Archivist!", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75493, 75518, 75603, 75604, 75729, 75867, 75868, 76026, 76032, 76217, 76241, 76242, 76448, 76557, 76564, 76576, 77100, 77151, 77154, 77166, 77176, 77231, 77267, 77268, 77325, 77327, 77328, 77331, 77415, 77425, 77433, 77434, 77483, 77484, 77486, 77487, 78762, 79223, 79231 }, ["description"] = "So you've got your bearings now? You've felt the dirt? You've smelled the history? Why not celebrate this glorious moment of above average success with... a cap! That's right! Take this token to our beloved provisioner, Aristta. She'll be happy to provide you with one of our all-purpose caps to signify your elevation to Archivist from naive passerby.", ["objectivesText"] = "Purchase an Archivist's Buckled Cap from Provisioner Aristta. Progress: The cap suits you quite well!", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 212371 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 206107, ["x"] = 0.615, ["y"] = 0.312 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 206107, ["x"] = 0.615, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 77328 }, ["questLines"] = { { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 20, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025 },
[79224] = { ["id"] = 79224, ["name"] = "Gathering Intel", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2339, ["storyline"] = { 79224, 79227, 79230, 79233, 79237, 79239, 79240, 79241, 79243, 79244 }, ["series"] = { 79227, 79230 }, ["description"] = "The Widow Arak'nai sent word via one of those \"weave-rats\" of hers. She has a lead that may be relevant to our cause, and has invited us to investigate. All the training in the world is useless without knowledge of our enemy. My own reconnaissance efforts in Azj-Kahet were met with... mixed results, as you may recall. I admit I am not keen on venturing down there again so soon. Fortunately, reinforcements have arrived with a capable spymaster. Unfortunately, she is... well. You'll see.", ["objectivesText"] = "Speak with Widow Arak'nai at the Weaver's Lair in Azj-Kahet .", ["rewardGold"] = 29200, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 223944, ["x"] = 0.315, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 207471, ["x"] = 0.556, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.315, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 2255, 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 79157 }, ["questLines"] = { { ["id"] = 5544, ["name"] = "News from Below", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5544, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[79225] = { ["id"] = 79225, ["name"] = "The Lost Flame", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79225 }, ["description"] = "<A tinderbox of a Hallowfall Expedition member, its return would help honor the memory of those who bravely gave their lives.> An expedition scout might possess knowledge about this item.>", ["objectivesText"] = "Deliver the Expedition Tinderbox to Keyrra Flamestonge at the Shadowgrove Vineyards. Provided item:", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 209924, 209938, 212333 }, ["starts"] = { { ["x"] = 0.611, ["y"] = 0.096, ["mapID"] = 2215 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 215527, ["x"] = 0.654, ["y"] = 0.322 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.654, ["y"] = 0.322 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["startItems"] = { 212333 } },
[79226] = { ["id"] = 79226, ["name"] = "The Big Dig: Traitor's Rest", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13844, ["mapID"] = 2025, ["storyline"] = { 79226 }, ["description"] = "Don your cap, put on a pair of sturdy gloves, and grab a snack because Traitor's Rest is ready for Archivists everywhere to sink their history-craving teeth into!", ["objectivesText"] = "Aid Eadweard Dalyngrigge and the Azerothian Archivists at The Big Dig in Traitor's Rest. Progress: Not every day you unearth ancient dragon mysteries... or even a dragon themselves!", ["rewardGold"] = 561800, ["rewardXP"] = 11895, ["rewardItems"] = { 213134, 213177, 213190, 213429 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 206107, ["x"] = 0.615, ["y"] = 0.312 }, { ["mapID"] = 2024, ["npcID"] = 209134, ["x"] = 0.27, ["y"] = 0.464 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 206107, ["x"] = 0.615, ["y"] = 0.312 }, { ["mapID"] = 2024, ["npcID"] = 209134, ["x"] = 0.27, ["y"] = 0.464 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = { 2024, 2025 }, ["zone"] = { 13844 } }, ["questType"] = "standard" },
[79227] = { ["id"] = 79227, ["name"] = "A Spider's-Eye View", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79224, 79227, 79230, 79233, 79237, 79239, 79240, 79241, 79243, 79244 }, ["series"] = { 79224, 79230 }, ["description"] = "I have eyes in every crevice of the city save for one that has... eluded me. The Transformatory is the grounds of Ansurek's most precocious minions and treasured pets. It is where the Ascension process was developed. I've only gotten my claws on it recently, thanks to dear Y'tekhi. Much of it remains uncomfortably shrouded. A more legs-on approach is in order. Place shadecasters to collect intel from my scouts, then meet Y'tekhi and your own spymaster Voss in a discreet corner of the district.", ["objectivesText"] = "Place shadecasters to rendezvous with the Weaver's scouts in the Umbral Bazaar, the Eastern Span, and the Twitching Gorge.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 207471, ["x"] = 0.556, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 215626, ["x"] = 0.695333, ["y"] = 0.716 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 2213, 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 79224 }, ["questLines"] = { { ["id"] = 5544, ["name"] = "News from Below", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5544, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2213 },
[79230] = { ["id"] = 79230, ["name"] = "Creeping Through Corridors", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2213, ["storyline"] = { 79224, 79227, 79230, 79233, 79237, 79239, 79240, 79241, 79243, 79244 }, ["series"] = { 79224, 79227 }, ["description"] = "I've identified three sites of interest to investigate. A stockpile on the east side of the complex, a warehouse in the center, and lastly, that big storehouse with royal Sureki flags outside it. We'll rendezvous there. There's less chance of discovery if we move separately through the area. You may be hidden from most nerubians, but the Ascended will sniff you out. Chuck some of these anger pheromones at them if you get heat, it'll distract them. Stay sharp, stay quiet.", ["objectivesText"] = "Investigate the western stockpile, central warehouse, and royal stores of the Transformatory, using anger pheromones to distract guards and avoid detection. Progress: Don't let your guard down. Not here.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 215626, ["x"] = 0.695333, ["y"] = 0.716 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 215628, ["x"] = 0.568, ["y"] = 0.905 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.695333, ["y"] = 0.716 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["sourceQuests"] = { 79227 }, ["questLines"] = { { ["id"] = 5544, ["name"] = "News from Below", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5544, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2213 },
[79231] = { ["id"] = 79231, ["name"] = "Back to Headquarters! Again!", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13647, ["mapID"] = 2025, ["description"] = "You've done truly incredible work! The proof is obvious: you are, in fact, a proper Azerothian Archivist. Meet us all back at our headquarters in Thaldraszus. Eadweard would like codify all your helpful labors and achievements for our group.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["starts"] = { { ["npcID"] = 207311, ["x"] = 0.77, ["y"] = 0.384, ["zoneID"] = 14433 }, { ["npcID"] = 208362, ["x"] = 0.172, ["y"] = 0.164, ["zoneID"] = 14433 }, { ["npcID"] = 207763, ["x"] = 0.382, ["y"] = 0.498, ["mapID"] = 2133 }, { ["npcID"] = 208055, ["x"] = 0.476, ["y"] = 0.486, ["mapID"] = 2133 } }, ["ends"] = { { ["npcID"] = 206107, ["x"] = 0.614, ["y"] = 0.312, ["mapID"] = 2025 } }, ["coords"] = { ["x"] = 0.77, ["y"] = 0.384, ["source"] = "quest_giver", ["mapID"] = 2025 }, ["mapCandidates"] = { ["npc"] = { 2025, 2133 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["sourceQuests"] = { 75604 }, ["questLines"] = { { ["id"] = 5528, ["name"] = "Azerothian Archives", ["orderIndex"] = 42, ["flags"] = 0 } } },
[79232] = { ["id"] = 79232, ["name"] = "Those Who Fell", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79232, 81673 }, ["description"] = "Since the Day of Shadows these lands have been a dangerous place. The kobyss are emboldened, the nerubians probe our lands, creatures of pure shadow have begun to manifest themselves. The memory of those who have fallen is etched in our everyday lives. We must locate their remains to bring closure. Search for the Tinderboxes of these missing expedition members and return them to me.", ["objectivesText"] = "Locate the remains of Oskaer Daleclash, Dalian Ironlink, and Idona Seerstone, and recover their tinderboxes. Progress: Have you located the tinderboxes?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 219451, 219453, 219499, 219503, 220157 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 215527, ["x"] = 0.654, ["y"] = 0.322 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 215527, ["x"] = 0.654, ["y"] = 0.322 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.654, ["y"] = 0.322 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 81990 }, ["questLines"] = { { ["id"] = 5670, ["name"] = "Zone 3 Neck 1", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[79233] = { ["id"] = 79233, ["name"] = "Lab Access", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2213, ["storyline"] = { 79224, 79227, 79230, 79233, 79237, 79239, 79240, 79241, 79243, 79244 }, ["description"] = "As much as I adore skulking in the shadows, the juiciest intel is going to be inside the laboratory of the Grand Splicer. Of course you'll need the proper pheromones once you're in, but we can take care of that with a little biological forgery. The nerubian loyalists here are surely on the invite list. Six of their secretions should be enough to disguise the three of us.", ["objectivesText"] = "Collect 6 Loyalist Secretions from nerubian loyalists in the Transformatory area. Progress: If you saw me? No you didn't.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 215457 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 215637, ["x"] = 0.695, ["y"] = 0.72 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 215659, ["x"] = 0.5712, ["y"] = 0.9244 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.695, ["y"] = 0.72 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["sourceQuests"] = { 79227 }, ["questLines"] = { { ["id"] = 5544, ["name"] = "News from Below", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5544, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2213 },
[79234] = { ["id"] = 79234, ["name"] = "A Small Bag of Seeds", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79234 }, ["description"] = "<This small bag of seeds seems forgotten, perhaps Aliya Hillhelm could make use of them.>", ["objectivesText"] = "Deliver this small bag of seeds to Aliya Hillhelm at the Hillhelm Stead. Provided item:", ["rewardGold"] = 280900, ["rewardXP"] = 11765, ["rewardItems"] = { 212339, 217344, 220756 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 15 }, { ["id"] = 2899, ["amount"] = 75 }, { ["id"] = 3008, ["amount"] = 10 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 206528, ["x"] = 0.612, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["startItems"] = { 212339 } },
[79237] = { ["id"] = 79237, ["name"] = "Making of a Monster", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2213, ["storyline"] = { 79224, 79227, 79230, 79233, 79237, 79239, 79240, 79241, 79243, 79244 }, ["description"] = "We've got a new objective: Figure out what Ansurek's plans are for this... thing. We'll find our answers inside the laboratory of the Grand Splicer. I'd bet my blades on it. I scouted a maintenance hatch on the roof that you can grapple up to. Y'tekhi brewed up some weird concoction that they claim will get us the proper clearance once inside. Yuck. Meet you in there.", ["objectivesText"] = "Access the Laboratory of the Grand Splicer via roof hatch, then investigate clues as to the purpose of the First Ascended. Progress: I don't like this. There's something we're still missing here.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 223431 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 215628, ["x"] = 0.568, ["y"] = 0.905 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 215628, ["x"] = 0.568, ["y"] = 0.905 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.905 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["sourceQuests"] = { 79230, 79233 }, ["questLines"] = { { ["id"] = 5544, ["name"] = "News from Below", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5544, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2213 },
[79239] = { ["id"] = 79239, ["name"] = "The Queen's Chains", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2213, ["storyline"] = { 79224, 79227, 79230, 79233, 79237, 79239, 79240, 79241, 79243, 79244 }, ["description"] = "Ansurek... that worm, that witless, gutless little-- < Y'tekhi growls under their breath, struggling to maintain their composure.> If this is what's become of Neferess, we must free her. She is still our queen. My mistress will know what to do. When the Weaver discovers what they've all done, there will not be a crevice deep enough to escape her wrath.", ["objectivesText"] = "Destroy Neferess's shackles.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 215659, ["x"] = 0.5712, ["y"] = 0.9244 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 215661, ["x"] = 0.784, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.5712, ["y"] = 0.9244 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["sourceQuests"] = { 79237 }, ["questLines"] = { { ["id"] = 5544, ["name"] = "News from Below", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5544, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2213 },
[79240] = { ["id"] = 79240, ["name"] = "Rogue Agent", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2213, ["storyline"] = { 79224, 79227, 79230, 79233, 79237, 79239, 79240, 79241, 79243, 79244 }, ["description"] = "We lost Y'tekhi . We can worry about the how of it later. Right now, we need to worry about taking them down before they make things worse. <Lilian snorts.> I guess we came down here to find out what Xal'atath had up her sleeve. ...I wish we'd minded our own business.", ["objectivesText"] = "Subdue Y'tekhi . Progress: Hard to think of how this could have gone any worse.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 215661, ["x"] = 0.784, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 215662, ["x"] = 0.785, ["y"] = 0.3955 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.784, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["sourceQuests"] = { 79239 }, ["questLines"] = { { ["id"] = 5544, ["name"] = "News from Below", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5544, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2213 },
[79241] = { ["id"] = 79241, ["name"] = "Go Loud", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2213, ["storyline"] = { 79224, 79227, 79230, 79233, 79237, 79239, 79240, 79241, 79243, 79244 }, ["series"] = { 79243, 79244 }, ["description"] = "So much for keeping this operation quiet. At least now that our cover's blown, we can really mess things up. They're hauling weapons across the south bridge. If we turn those weapons against them, they'll have to resupply their whole army. That'll buy us time, at least. I've identified six weak spots across the convoy. Rig up bombs to all six, then get out of there and watch the fireworks.", ["objectivesText"] = "Plant 6 Commandeered Nerubian Charges at specified points across the convoy, then remotely detonate them. Progress: They know we're here. May as well make the most of it.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 215662, ["x"] = 0.785, ["y"] = 0.3955 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 215625, ["x"] = 0.556, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.785, ["y"] = 0.3955 }, ["mapCandidates"] = { ["npc"] = { 2213, 2255 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["sourceQuests"] = { 79240 }, ["questLines"] = { { ["id"] = 5544, ["name"] = "News from Below", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5544, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[79243] = { ["id"] = 79243, ["name"] = "Manufactured Mutiny", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2213, ["storyline"] = { 79224, 79227, 79230, 79233, 79237, 79239, 79240, 79241, 79243, 79244 }, ["series"] = { 79241, 79244 }, ["description"] = "We don't have the firepower to dismantle their whole manufacturing operation, but what we do have is two leftover vials of anger pheromones. Let's make them count. There's a siege marshal and a quartermaster overseeing the preparations and giving everyone orders. Logistics types, but they still pack a punch. That's where those pheromones come in. Hit them with a vial, and their own armies will turn against them. Take out both, and we watch the operation crumble.", ["objectivesText"] = "Slay Siege Marshal Tekhzok and Royal Quartermaster Ze'erik . Progress: Those aggression pheromones came in handy... let's make sure not to waste them.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 215662, ["x"] = 0.785, ["y"] = 0.3955 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 215625, ["x"] = 0.556, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.785, ["y"] = 0.3955 }, ["mapCandidates"] = { ["npc"] = { 2213, 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 79240 }, ["questLines"] = { { ["id"] = 5544, ["name"] = "News from Below", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5544, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[79244] = { ["id"] = 79244, ["name"] = "News From Below", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79224, 79227, 79230, 79233, 79237, 79239, 79240, 79241, 79243, 79244 }, ["series"] = { 79241, 79243 }, ["description"] = "I could hear the explosions from here. That'll buy us some time. Maybe I'd even be relieved, if this had gone less poorly. Y'tekhi is secured in the back, where they can't overhear anything. Whatever Xal'atath did... it hasn't worn off yet. The Weaver has people looking into it, but the outlook is grim. Alleria is going to want a status report. Good luck.", ["objectivesText"] = "Inform Widow Arak'nai about what was found in the Transformatory. Then, return to Alleria at Dornogal on the Isle of Dorn. Progress: Nothing to do but keep going.", ["rewardGold"] = 929400, ["rewardXP"] = 17650, ["rewardItems"] = { 223437, 223445, 223455, 223466 }, ["rewardCurrencies"] = { { ["id"] = 3002, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 215625, ["x"] = 0.556, ["y"] = 0.44 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223944, ["x"] = 0.315, ["y"] = 0.595 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = { 2255, 2339 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 79241, 79243 }, ["questLines"] = { { ["id"] = 5544, ["name"] = "News from Below", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5544, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79256] = { ["id"] = 79256, ["name"] = "A Hint of Fear", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79256, 79257, 79258, 79259, 79260, 79261, 79262, 79263, 79264, 79265, 79266 }, ["description"] = "My father thinks that while he and Dagran were dealing with the skardyn tae the south, he caught a sensation o' his old hammer, Fearbreaker. He said it slipped out o' his fingers when Dalaran crashed, and it's been bothering him mightily. That hammer belongs tae the Bronzebeard clan, and has for generations. But he hasn't been himself lately, either. I'm willing tae have a look, so he doesn't worry that he might've missed it. Meet me down at Camp Murroch, and we'll have a quick look around.", ["objectivesText"] = "Meet Moira Thaurissan outside Camp Murroch.", ["rewardGold"] = 30900, ["rewardXP"] = 1240, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212742, ["x"] = 0.45, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 215781, ["x"] = 0.529, ["y"] = 0.632 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 78761 }, ["questLines"] = { { ["id"] = 5598, ["name"] = "Fearbreaker", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214, ["db2QuestHubAreaPoiID"] = 7911 },
[79257] = { ["id"] = 79257, ["name"] = "Grotto Grievances", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79256, 79257, 79258, 79259, 79260, 79261, 79262, 79263, 79264, 79265, 79266 }, ["objectivesText"] = "Living Grotto contained", ["rewardGold"] = 1123600, ["rewardXP"] = 19030, ["starts"] = { { ["x"] = 0.504, ["y"] = 0.712, ["mapID"] = 2214 } }, ["ends"] = { { ["x"] = 0.504, ["y"] = 0.712, ["mapID"] = 2214 } }, ["coords"] = { ["mapID"] = 2214, ["x"] = 0.504, ["y"] = 0.712 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14795 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5598, ["name"] = "Fearbreaker", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2Objectives"] = { { ["text"] = "Living Grotto contained", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[79258] = { ["id"] = 79258, ["name"] = "Mineral Water Woes", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79256, 79257, 79258, 79259, 79260, 79261, 79262, 79263, 79264, 79265, 79266 }, ["description"] = "When that magic hammer fell into the Deeps, I knew it could be a formidable weapon against the skardyn menace. Your friend has told me that it's 'particular' about its wielder. Fortunately, I am a hero! And as a hero, I know how to get close to it. We need to have a good mix of pollen and water plastered onto us. That way, the beast standing over it will think we're just like it. That mineral water has to be the exact right temperature to mix with the lashroom dust and blend in.", ["objectivesText"] = "Acquire the proper-temperature mineral water from the Living Grotto springs.", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 215788, ["x"] = 0.526, ["y"] = 0.681 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 215821, ["x"] = 0.521, ["y"] = 0.6595 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.681 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79256 }, ["questLines"] = { { ["id"] = 5598, ["name"] = "Fearbreaker", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[79259] = { ["id"] = 79259, ["name"] = "Put On a Good Face", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79256, 79257, 79258, 79259, 79260, 79261, 79262, 79263, 79264, 79265, 79266 }, ["description"] = "Berrund here says that the massive beast standing over Fearbreaker is very particular about what kinds of creatures it allows near it. If we blend in, he says, we can get close enough tae nab the hammer. But tae blend in, he says we have tae get covered by the dust an' pollen in the grotto. Those Lashrooms look like they're a good place to start. It all seems suspicious tae me, but fer now, we'll play along until I can recover Fearbreaker and bring it back to my father.", ["objectivesText"] = "Collect Lashroom Dust from Lashrooms in the Living Grotto. Progress: Have you gathered up that dust? It's the only way you're going to get near that hammer, especially with that creature wandering around.", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["rewardItems"] = { 212490 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 215781, ["x"] = 0.529, ["y"] = 0.632 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 215788, ["x"] = 0.526, ["y"] = 0.681 }, { ["mapID"] = 2214, ["npcID"] = 215822, ["x"] = 0.519, ["y"] = 0.666 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.529, ["y"] = 0.632 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79256 }, ["questLines"] = { { ["id"] = 5598, ["name"] = "Fearbreaker", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[79260] = { ["id"] = 79260, ["name"] = "Epicenter", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79256, 79257, 79258, 79259, 79260, 79261, 79262, 79263, 79264, 79265, 79266 }, ["series"] = { 79261, 79263 }, ["description"] = "There is the creature standing between us and that magic hammer. It certainly made an impact when it landed here in the Ringing Deeps , didn't it? Look at the size of that crater! With the pollen and water splashed on you like this, you should be able to approach that beast and, theoretically, not be harmed. You'll blend right in with it! But if it does turn aggressive, don't worry, I'll be right behind you. We'll get that hammer out of here safely!", ["objectivesText"] = "Approach the Verdant Hulk .", ["rewardGold"] = 619600, ["rewardXP"] = 12400, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 215822, ["x"] = 0.519, ["y"] = 0.666 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 215821, ["x"] = 0.521, ["y"] = 0.6595 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.519, ["y"] = 0.666 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79258, 79259 }, ["questLines"] = { { ["id"] = 5598, ["name"] = "Fearbreaker", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[79261] = { ["id"] = 79261, ["name"] = "Boiling Mad", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79256, 79257, 79258, 79259, 79260, 79261, 79262, 79263, 79264, 79265, 79266 }, ["series"] = { 79260, 79263 }, ["description"] = "That gravel-brained ingrate! He took Fearbreaker and ran off to the north! It's not that I want that hammer for myself. I don't. But it belongs to the Bronzebeard clan. It should be in the hands of someone who respects its power! We need to track him down before he hurts himself or someone else with that hammer!", ["objectivesText"] = "Track Berrund and Fearbreaker through the Ringing Deeps .", ["rewardGold"] = 30900, ["rewardXP"] = 1240, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 215821, ["x"] = 0.521, ["y"] = 0.6595 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 215824, ["x"] = 0.539, ["y"] = 0.5 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.521, ["y"] = 0.6595 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79260 }, ["questLines"] = { { ["id"] = 5598, ["name"] = "Fearbreaker", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[79262] = { ["id"] = 79262, ["name"] = "Clean Up House", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79256, 79257, 79258, 79259, 79260, 79261, 79262, 79263, 79264, 79265, 79266 }, ["description"] = "It looks like the destruction around the Coreway rattled loose more than just a few stones down here. It's stirred up all sorts o' dark things. If this was a thriving mining operation, it ain't anymore. We need to help the earthen get it under control again, and that means thinning out these beasts.", ["objectivesText"] = "Slay agitated creatures in the Rumbling Wastes. Progress: I want to get Fearbreaker back, but we need to clear out some of these agitated beasts first.", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["rewardItems"] = { 81742, 81743, 81744, 81745, 81746, 81747, 81748, 81749, 81750, 119001 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 215824, ["x"] = 0.539, ["y"] = 0.5 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 215837, ["x"] = 0.551, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.539, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79261 }, ["questLines"] = { { ["id"] = 5598, ["name"] = "Fearbreaker", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[79263] = { ["id"] = 79263, ["name"] = "Fault Lines", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79256, 79257, 79258, 79259, 79260, 79261, 79262, 79263, 79264, 79265, 79266 }, ["series"] = { 79260, 79261 }, ["description"] = "Berrund took Fearbreaker for himself. I suppose he thought he could save these people. Be the hero. But ye can't go about doing the wrong thing for the right reasons. I know from experience. If a rock is hollow tae begin with, it never can be solid again, no matter how hard ye try. He's likely tae need saving himself now. Let's find him in this blasted place.", ["objectivesText"] = "Find Berrund the Gleaming within the Rumbling Wastes. Progress: You found me?", ["rewardGold"] = 292100, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 215824, ["x"] = 0.539, ["y"] = 0.5 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 215836, ["x"] = 0.551, ["y"] = 0.455 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.539, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79261 }, ["questLines"] = { { ["id"] = 5598, ["name"] = "Fearbreaker", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[79264] = { ["id"] = 79264, ["name"] = "These Strong Hands", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79256, 79257, 79258, 79259, 79260, 79261, 79262, 79263, 79264, 79265, 79266 }, ["series"] = { 79265 }, ["description"] = "< Berrund the Gleaming coughs dustily.> I knew I couldn't take the skardyn without some help. I thought, if I just had that magic hammer, then nothing would stop me. I had to have it, you see, or else, maybe I wasn't who I was made to be. But it kept slipping out of my fingers. Like it didn't want anything to do with me. It fell out of my hands at the worst moment and now... <He coughs again.> It's clearly not mine. It never was. I'm... I'm... sorry.", ["objectivesText"] = "Witness Moira Thaurissan .", ["rewardGold"] = 29200, ["rewardXP"] = 1240, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 215836, ["x"] = 0.551, ["y"] = 0.455 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 217598, ["x"] = 0.557333, ["y"] = 0.455333 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.551, ["y"] = 0.455 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79262, 79263 }, ["questLines"] = { { ["id"] = 5598, ["name"] = "Fearbreaker", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[79265] = { ["id"] = 79265, ["name"] = "Fearbreaker", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79256, 79257, 79258, 79259, 79260, 79261, 79262, 79263, 79264, 79265, 79266 }, ["series"] = { 79264 }, ["description"] = "The skardyn have taken over the operations here in the Rumbling Wastes. That's why Berrund thought he needed Fearbreaker . We're going to finish that job before I take the hammer back to Magni. What kind of a queen would I be if I wasn't willing tae put myself in danger for the good of others? Let's get in there and save as many as we can.", ["objectivesText"] = "Slay skardyn and save earthen in the Rumbling Wastes with Moira Thaurissan .", ["rewardGold"] = 619600, ["rewardXP"] = 12400, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 217598, ["x"] = 0.557333, ["y"] = 0.455333 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 216085, ["x"] = 0.604, ["y"] = 0.465333 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.557333, ["y"] = 0.455333 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79264 }, ["questLines"] = { { ["id"] = 5598, ["name"] = "Fearbreaker", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[79266] = { ["id"] = 79266, ["name"] = "The Bronzebeard Legacy", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79256, 79257, 79258, 79259, 79260, 79261, 79262, 79263, 79264, 79265, 79266 }, ["description"] = "Well, we did what we set out tae do... and more. We found Fearbreaker and did some good with it. Now it's time tae bring it back tae Magni. Let's hope Berrund learned a lesson here, but I suspect he'll manage tae get himself in trouble again soon. Hopefully, it'll be fer the right reasons an' with the right support.", ["objectivesText"] = "Meet Moira Thaurissan in Gundargaz.", ["rewardGold"] = 30900, ["rewardXP"] = 1240, ["rewardItems"] = { 224449 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 180 }, { ["id"] = 2902, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 216085, ["x"] = 0.604, ["y"] = 0.465333 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 217827, ["x"] = 0.451, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79265 }, ["questLines"] = { { ["id"] = 5598, ["name"] = "Fearbreaker", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[79267] = { ["id"] = 79267, ["name"] = "Wax On, Pot Off", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78555, 78557, 78631, 78634, 78635, 78636, 78637, 78638, 78639, 78640, 78641, 78642, 78837, 78838, 78839, 79205, 79267, 80082, 80434, 83550 }, ["description"] = "If candles are important to kobold society, I have an idea that might disrupt their production... or at least make sure there's an unpleasant surprise waiting for our enemy. Take that cinderbrew. Drop some in those large vats of wax the kobolds are prepping at the top of that hill. It's a powerful explosive. It burns aggressively, so try not to drop any. It should certainly make any candles made with that wax quite feisty, once they're lit.", ["objectivesText"] = "Sabotage the pots of wax in the Warrens. Progress: Try not to breathe too many of the fumes.", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212992, ["x"] = 0.601333, ["y"] = 0.32 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212992, ["x"] = 0.601333, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.601333, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 78639, 79205 }, ["questLines"] = { { ["id"] = 5533, ["name"] = "By Candlelight", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5533, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5533, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
