[79282] = { ["id"] = 79282, ["name"] = "The Grand Debut", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 79282 }, ["description"] = "The Proscenium is looking amazing! Are you ready to get on stage? Give us a hand as part of the crew, and we'll give you a chance to act. Will you accept this directive?", ["objectivesText"] = "Complete one Theater Troupe event in The Proscenium. Progress: I haven't seen you on stage yet, <name>. You won't win any fans by standing around!", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 25 }, { ["id"] = 2897, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 214296, ["x"] = 0.564, ["y"] = 0.514 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 214296, ["x"] = 0.564, ["y"] = 0.514 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.514 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14776 } }, ["questType"] = "standard", ["sourceQuests"] = { 79150 } },
[79297] = { ["id"] = 79297, ["name"] = "Nightwatch", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78607, 78613, 78614, 78615, 78620, 78621, 78624, 78626, 78627, 78628, 78629, 78630, 79089, 79297, 80049 }, ["description"] = "Xal'atath is using the Order of Night to serve her whims. I overheard some of the Arathi complaining about a new wave of propaganda that has been put up around Mereldar. Find what you can and deliver it to General Steelstrike . I'll be there as soon as I can. We need to convince her of the severity of this threat.", ["objectivesText"] = "Collect 8 Order of Night Propaganda . Progress: Anything I can help you with, <name>?", ["rewardGold"] = 292100, ["rewardXP"] = 10190, ["rewardItems"] = { 217988, 217990, 217993, 217995 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 218182, ["x"] = 0.426, ["y"] = 0.556 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213108, ["x"] = 0.396, ["y"] = 0.589667 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78613 }, ["questLines"] = { { ["id"] = 5526, ["name"] = "Hope in Solidarity", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5526, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5526, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[79300] = { ["id"] = 79300, ["name"] = "The Notebook", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79300, 79301, 79302, 79303, 79304 }, ["series"] = { 79304 }, ["description"] = "$p, I need your help. My whole future is on the line! I came to Lightspark to be an airship captain, and I've put in a ton of work to excel here. But my notebook is missing, with my final report! I'm top in the class, but if I don't turn it in soon, I won't be our next airship captain. Please help me find it. I thought I left it out by the canyon where we review each other's skiff piloting, but it wasn't there when I checked. Can you help me look for it?", ["objectivesText"] = "Help Sophietta look for her notebook.", ["rewardGold"] = 232300, ["rewardXP"] = 7645, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 216001, ["x"] = 0.526, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 225925, ["x"] = 0.534, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 79304 }, ["questLines"] = { { ["id"] = 5532, ["name"] = "The Sky's the Limit", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[79301] = { ["id"] = 79301, ["name"] = "Height Club", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79300, 79301, 79302, 79303, 79304 }, ["description"] = "I'm so tired of Edwyn. From the day we all arrived, he's been telling everyone he'll be selected as captain. He's a great flyer--very talented, and he knows his stuff. But his ego gets in the way of treating people as he should. And he knows my grades and flight review scores are higher. But if I can't turn in my report, he'll be the next captain. Take it back from him!", ["objectivesText"] = "Confront Edwyn about the notebook. Progress: Did you get it back? I'd love to see the look on Edwyn's face...", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 225925, ["x"] = 0.534, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 225925, ["x"] = 0.534, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.534, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 79300 }, ["questLines"] = { { ["id"] = 5532, ["name"] = "The Sky's the Limit", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[79302] = { ["id"] = 79302, ["name"] = "Gone with the Wind", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79300, 79301, 79302, 79303, 79304 }, ["description"] = "I can't believe Edwyn threw my report out into the wind. Can you please track down what papers you can find? I'll look for any around the school grounds, you check the valley. This report is already late... But I had some really good insights around airship capabilities. When Headmaster Fynch sees them, maybe he'll still allow me to turn it in. Bring me whatever pages you find!", ["objectivesText"] = "Recover 10 pages from Sophietta's report. Progress: I hope you found all the pages, <name>!", ["rewardGold"] = 292100, ["rewardXP"] = 10190, ["rewardItems"] = { 225180 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 225925, ["x"] = 0.534, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 225926, ["x"] = 0.534, ["y"] = 0.605 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.534, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 79301 }, ["questLines"] = { { ["id"] = 5532, ["name"] = "The Sky's the Limit", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[79303] = { ["id"] = 79303, ["name"] = "A Principled Principal", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79300, 79301, 79302, 79303, 79304 }, ["description"] = "Great work gathering these up. I found a few blowing around up here, so I think we've got all the pages. Let's get this to Headmaster Fynch ! He's probably in the classroom. I sure hope he accepts it. He says he doesn't accept late work, but there were a lot of extenuating circumstances at play here. And if he doesn't, I'll be reporting to Edwyn as my captain. I'm not sure I could do that, after what's happened.", ["objectivesText"] = "Get Sophietta's report to Headmaster Fynch .", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["rewardItems"] = { 225945, 228457 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 25 }, { ["id"] = 2899, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 225926, ["x"] = 0.534, ["y"] = 0.605 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 226074, ["x"] = 0.528, ["y"] = 0.592 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.534, ["y"] = 0.605 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 79302 }, ["questLines"] = { { ["id"] = 5532, ["name"] = "The Sky's the Limit", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[79304] = { ["id"] = 79304, ["name"] = "Care Package", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79300, 79301, 79302, 79303, 79304 }, ["series"] = { 79300 }, ["description"] = "My cousin Sophietta and I came to Hallowfall together as stalwarts. Since arriving, we both lived here in Dunelle's Kindness for years. But she left last year to follow her dream of being one of our airship captains, or at least joining an airship crew. She's a strong person, but I don't know how she's doing. Especially without Innkeeper Valrin's sweetrolls ! She can't get them at Lightspark, the Sky Academy. Will you take these to her, and make sure she's doing alright?", ["objectivesText"] = "Take the care package to Sophietta Lynflayme at Lightspark Sky Academy. Progress: What's this? Are these for me?", ["rewardGold"] = 30900, ["rewardXP"] = 1275, ["rewardItems"] = { 19150, 19151, 19152, 19153, 19154, 19155, 20228, 20229, 20230, 20231, 20233, 20236, 228409 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 217609, ["x"] = 0.692, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 216001, ["x"] = 0.526, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.692, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["nextQuests"] = { 79300 }, ["questLines"] = { { ["id"] = 5532, ["name"] = "The Sky's the Limit", ["orderIndex"] = 0, ["flags"] = 1 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[79309] = { ["id"] = 79309, ["name"] = "Status Report", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79309, 79310, 79311, 79312, 79313 }, ["description"] = "Airships give the Arathi Army command of the skies. But roads are the lifeblood of empires. My scouts protect and light the passageways of Hallowfall for our citizens. One such patrol has been late to report their walk of the eastern road. Seek my missing scouts by the sight of smoke or flame. Arathi soldiers know better than to linger in the dark.", ["objectivesText"] = "Locate the missing Arathi Army scouting party.", ["rewardGold"] = 30900, ["rewardXP"] = 1275, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 216061, ["x"] = 0.704, ["y"] = 0.45 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 216063, ["x"] = 0.754667, ["y"] = 0.510667 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.704, ["y"] = 0.45 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78658 }, ["questLines"] = { { ["id"] = 5603, ["name"] = "What Grows in the Dark", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[79310] = { ["id"] = 79310, ["name"] = "Seek the Lost", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79309, 79310, 79311, 79312, 79313 }, ["description"] = "Guard our ways, repel the dark. Civilize this twisted land. All in the name of our empire. This is the mission of the Arathi Army. A mission I can heed no longer. I am afraid. I won't go back into the dark. Not after what I've seen. If Maevest or any of my other companions survived, they must crave the mercy of a swift death. And I left them to that terror. Tell Captain Trueflame her scouts died in darkness, one and all.", ["objectivesText"] = "Look for a member of Wayshelm's party. Progress: < Scout Wayshelm gazes into the flames of his campfire.>", ["rewardGold"] = 232300, ["rewardXP"] = 7645, ["rewardItems"] = { 213519 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 216063, ["x"] = 0.754667, ["y"] = 0.510667 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 216063, ["x"] = 0.754667, ["y"] = 0.510667 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.754667, ["y"] = 0.510667 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 79309 }, ["questLines"] = { { ["id"] = 5603, ["name"] = "What Grows in the Dark", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[79311] = { ["id"] = 79311, ["name"] = "Stem the Flow", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79309, 79310, 79311, 79312, 79313 }, ["description"] = "The roads were meant to be lit. But the path was overgrown, the lanterns dark. Swarming, frothing, and reeking with rot. It all happened so fast. By the time we realized the danger, the beasts were upon us. The largest of them was huge and black as night. It is our duty to slay monsters and push back the darkness. But the thought of going back fills with me fear. I've lost my nerve. But you, outsider, can still make this right.", ["objectivesText"] = "Slay 12 Bloatrot Stingers or Fungal Infestors . Progress: <Scout Maevest's compass gleams in the firelight. Wayshelm has bound it with twine and now wears it around his neck.>", ["rewardGold"] = 292100, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 216063, ["x"] = 0.754667, ["y"] = 0.510667 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 216063, ["x"] = 0.754667, ["y"] = 0.510667 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.754667, ["y"] = 0.510667 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 79310 }, ["questLines"] = { { ["id"] = 5603, ["name"] = "What Grows in the Dark", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[79312] = { ["id"] = 79312, ["name"] = "Mow the Masses", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79309, 79310, 79311, 79312, 79313 }, ["description"] = "Maevest and I broke away from the others and fled, their screams left in our wake. Foul muck smothered our lanterns and we stumbled in the dark through knee-high waters. I heard a splash like she had tripped and fallen in, but I couldn't bring myself to look back. Only later did I find the tiny bite marks on my ankles. Be warned, there's something in the water. I took notice of fronds growing from the pools. Swarming insects feast on their sickly nectar. Destroy those plants and starve the beasts.", ["objectivesText"] = "Cut down 8 Foulnectar Fronds .", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 216063, ["x"] = 0.754667, ["y"] = 0.510667 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 216063, ["x"] = 0.754667, ["y"] = 0.510667 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.754667, ["y"] = 0.510667 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 79310 }, ["questLines"] = { { ["id"] = 5603, ["name"] = "What Grows in the Dark", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[79313] = { ["id"] = 79313, ["name"] = "What Grows in the Dark", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79309, 79310, 79311, 79312, 79313 }, ["description"] = "We are told never to walk in the darkness. To carry light wherever we go. The thought of returning this way filled me with dread. But your courage shines with splendor, <name>. At your side, my way is lit. No more hiding. The beast clad in black chitin, the one that killed my friends, dies in that cave. I am with you.", ["objectivesText"] = "Slay Fallowbarb .", ["rewardGold"] = 584200, ["rewardXP"] = 12740, ["rewardItems"] = { 226140 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 25 }, { ["id"] = 2899, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 216063, ["x"] = 0.754667, ["y"] = 0.510667 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 216061, ["x"] = 0.704, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.754667, ["y"] = 0.510667 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 79311, 79312 }, ["questLines"] = { { ["id"] = 5603, ["name"] = "What Grows in the Dark", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[79321] = { ["id"] = 79321, ["name"] = "The Catalyst's Gift", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2022, ["storyline"] = { 79321 }, ["description"] = "I have an urgent message for you, adventurer. The Revival Catalyst seems to be responding to the land's rumblings--perhaps even your feats! Miraculously, it now shares its power for nothing in return except one's mere presence. Antuka will know more. Go with haste, $p. This is wondrous news.", ["objectivesText"] = "Speak to Antuka in Tyrhold.", ["rewardGold"] = 30900, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 199336, ["x"] = 0.765, ["y"] = 0.342 }, { ["mapID"] = 2112, ["npcID"] = 213930, ["x"] = 0.48, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 198695, ["x"] = 0.606, ["y"] = 0.538 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.765, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2022, 2025, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
[79322] = { ["id"] = 79322, ["name"] = "What the Duck?", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Noblegarden", ["expansion"] = 10, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 79322 }, ["description"] = "What the--why are all these ducks here? Something has them agitated. They almost knocked over my beautiful golden egg heirloom! We need to clear out these chaotic quackers so we can continue our festivities. I'll keep them from entering the inn, but can you help clear out the rest?", ["objectivesText"] = "Scare off 10 ducks using the Horn of Honking . Progress: Show those ducks who's boss!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 45072, 210558, 210594, 212599, 212608, 212643, 213428, 216874, 216881 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 211646, ["x"] = 0.42, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 211646, ["x"] = 0.42, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard" },
[79323] = { ["id"] = 79323, ["name"] = "A Fowl Concoction", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Noblegarden", ["expansion"] = 10, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 79323 }, ["description"] = "We need to put an end to this duck invasion. While I was shooing some stragglers away from the inn, a flock showed up and made off with some of our decorations and eggs. My precious heirloom was among the items stolen! Please, <name>. I won't stand for these pilfering poultry. I know a mage in Stormwind who might have some ideas on how to handle this.", ["objectivesText"] = "Speak with Emmery Fiske at the Wizard's Sanctum in Stormwind. Progress: Have you spoken with Emmery yet?", ["rewardItems"] = { 45072 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 211646, ["x"] = 0.42, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 211646, ["x"] = 0.42, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["sourceQuests"] = { 79322 } },
[79324] = { ["id"] = 79324, ["name"] = "To the Waterworks", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79022, 79023, 79024, 79025, 79026, 79027, 79028, 79029, 79030, 79217, 79324, 79325, 80145, 80517 }, ["description"] = "Getting the Waterworks up and running is our first objective. Nothing else we do matters if we can't get power to the facility. Meet up with Dagran and ZZ-01-47 once you get there. And try to keep them on the sidelines. I don't want to explain to Moira that her son was injured, or worse, under my care.", ["objectivesText"] = "Meet up with Dagran and ZZ-01-47 at the Waterworks.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 229371, 232049, 232371 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 217245, ["x"] = 0.449, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 217331, ["x"] = 0.451, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.449, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79025 }, ["questLines"] = { { ["id"] = 5531, ["name"] = "The Machines March to War", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5531, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214, ["db2QuestHubAreaPoiID"] = 7911 },
[79325] = { ["id"] = 79325, ["name"] = "Shadowvein Extraction", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79022, 79023, 79024, 79025, 79026, 79027, 79028, 79029, 79030, 79217, 79324, 79325, 80145, 80517 }, ["description"] = "I sent Zee-Zee ahead to the Shadowvein extraction site. From what they transmitted back it looks like the area is swarming with rock worms and covered in this... discharge. I gave them an upgrade while we were waiting for you. I don't know how effective it'll be in battle but the results should be shocking for anyone that tries to threaten them.", ["objectivesText"] = "Meet up with ZZ-01-47 at the Shadowvein Extraction Site.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 217331, ["x"] = 0.451, ["y"] = 0.422 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 216140, ["x"] = 0.535, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.451, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79026, 79027 }, ["questLines"] = { { ["id"] = 5531, ["name"] = "The Machines March to War", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5531, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[79327] = { ["id"] = 79327, ["name"] = "The Glittering Shard", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79148, 79149, 79193, 79194, 79327, 79679, 79944 }, ["description"] = "<Glistening with an inner light, this shard of crystal feels warm to the touch.. Orsenth may be interested in examining this piece of ore.>", ["objectivesText"] = "Bring the glistening clay to Orsenth near Nibelgaz Mine. Provided item:", ["rewardGold"] = 146000, ["rewardXP"] = 4960, ["rewardItems"] = { 212595 }, ["starts"] = { { ["x"] = 0.528, ["y"] = 0.16, ["mapID"] = 2214 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 219042, ["x"] = 0.49, ["y"] = 0.148 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.148 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79944 }, ["questLines"] = { { ["id"] = 5619, ["name"] = "Rampage at Nibelgaz Mine", ["orderIndex"] = 6, ["flags"] = 1 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214, ["startItems"] = { 212595 } },
[79328] = { ["id"] = 79328, ["name"] = "Embassies and Envoys", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 79197, 79328, 79333, 79344, 83271, 83286, 83315 }, ["description"] = "I feared what we would find when we returned here, but I am proud to see that though we were forced to leave, you were able to forge a friendship with the earthen and stand against the nerubians. With your strength, we will win this. But first we need a plan, and for that we need space here in Dornogal for discussion.", ["objectivesText"] = "Set up your faction's embassy in Dornogal.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 223546, 223547, 223548, 223549, 223564, 223569, 223584, 223588 }, ["rewardChoices"] = { 223546, 223547, 223548, 223549, 223564, 223569, 223584, 223588 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 216167, ["x"] = 0.36, ["y"] = 0.814 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 214917, ["x"] = 0.316667, ["y"] = 0.600667 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.36, ["y"] = 0.814 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 79333 }, ["questLines"] = { { ["id"] = 5551, ["name"] = "Against the Current", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5551, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79329] = { ["id"] = 79329, ["name"] = "Glowing Harvest", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79329 }, ["objectivesText"] = "Remnants Satchels collected", ["rewardItems"] = { 212755 }, ["starts"] = { { ["x"] = 0.634, ["y"] = 0.285, ["mapID"] = 2215 } }, ["ends"] = { { ["x"] = 0.634, ["y"] = 0.285, ["mapID"] = 2215 } }, ["coords"] = { ["mapID"] = 2215, ["x"] = 0.634, ["y"] = 0.285 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14838 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Remnants Satchels collected", ["amount"] = 12, ["type"] = 1, ["objectID"] = 212755, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215, ["db2WidgetSetID"] = 1054 },
[79330] = { ["id"] = 79330, ["name"] = "Duck Tales", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Noblegarden", ["expansion"] = 10, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 79330 }, ["description"] = "Take this potion, <name>. You should be able to communicate with your feathery friends with it. But don't blame me for any unintended side effects you may experience.", ["objectivesText"] = "Use the potion to get information from 5 ducks. Progress: Go on now, have a chat with those ducks!", ["rewardItems"] = { 45072, 212608 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 216129, ["x"] = 0.42, ["y"] = 0.648 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 211646, ["x"] = 0.42, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.648 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["sourceQuests"] = { 79323 } },
[79331] = { ["id"] = 79331, ["name"] = "Just a Waddle Away", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Noblegarden", ["expansion"] = 10, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 79331 }, ["description"] = "We need to find out where those ducks are hiding our stolen goods! And who this mysterious Daetan is, while we're at it. I convinced Emmery to give me more of that potion. Take it and find my heirloom!", ["objectivesText"] = "Discover the duck's hiding spot. Progress: Where would those ducks be hiding...", ["rewardGold"] = 309800, ["rewardItems"] = { 45072, 210594, 212599, 212608, 212643, 213428, 216874, 216881, 216890, 216897, 216898, 216900, 216901, 216902 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 211646, ["x"] = 0.42, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 211646, ["x"] = 0.42, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["sourceQuests"] = { 79330 } },
[79333] = { ["id"] = 79333, ["name"] = "The Fleet Arrives", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 79197, 79328, 79333, 79344, 82153, 83271, 83286, 83315 }, ["series"] = { 79197, 84365, 84367 }, ["description"] = "From the moment we crashed on this isle, it were clear as crystal we'd be needin' allies if we hoped to face Xal'atath. Jaina and Thrall took off tae muster reinforcements, an' you and I set tae work seein' what could be done here with the earthen. An' I have to say we've done well on our own, haven't we? <Moira smiles at you proudly.> But it looks like our reinforcements may have finally arrived. Peacekeepers spied ships comin' this way. Go take a look an' confirm the good news!", ["objectivesText"] = "Scout the harbor for ships arriving from the Horde and Alliance fleet.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 216149, ["x"] = 0.36, ["y"] = 0.804 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 216167, ["x"] = 0.36, ["y"] = 0.814 }, { ["mapID"] = 2339, ["npcID"] = 216168, ["x"] = 0.358, ["y"] = 0.814 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.36, ["y"] = 0.804 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 79197 }, ["questLines"] = { { ["id"] = 5551, ["name"] = "Against the Current", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5551, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79335] = { ["id"] = 79335, ["name"] = "One More Tradition", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78743, 78744, 78745, 78746, 78747, 78748, 78749, 79335, 79336, 79337, 79338, 79339, 79340, 79341, 79342, 81661, 82895 }, ["description"] = "Before I shut down, I must craft an item that is meaningful to me. As a Stonebound, I worked the mines. I had a lantern I made and used until I lost it in a collapse. I became Unbound shortly after. I wish to forge a new lantern to guide my way through these final moments. The lantern was made of an ore found in small amounts around this area. I used a charged core in the lantern. You can find them in the stormfangs that roam these hills. Gather the materials, and I will forge the lantern.", ["objectivesText"] = "Gather 5 ore and 5 Charged Cores near Fallside Outpost. Progress: Have you gotten the materials I asked for?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 213001, 213002 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 213184, ["x"] = 0.574, ["y"] = 0.43 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 216169, ["x"] = 0.571, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.574, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78749 }, ["questLines"] = { { ["id"] = 5606, ["name"] = "Mourning Rise", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79336] = { ["id"] = 79336, ["name"] = "The Forging of Memories", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78743, 78744, 78745, 78746, 78747, 78748, 78749, 79335, 79336, 79337, 79338, 79339, 79340, 79341, 79342, 81661, 82895 }, ["description"] = "Before its shutdown, we earthen would descend to the Awakening Machine below and renew our cycle. But now, even if it was still working, I would see my cycle broken and be remembered as I am. < Korgran lets out a deep sigh.> These hands look strong, but they become heavier with each passing moment. The stiffness in my wrists and elbows will not let me carry the items to the forge. Please, add the right material to the forge as I call them out.", ["objectivesText"] = "Help Korgran forge his lantern. Progress: Oh, I almost forget. I did ask you to help with forging the lantern, didn't I?", ["rewardGold"] = 292100, ["rewardXP"] = 9515, ["rewardItems"] = { 219413 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 216169, ["x"] = 0.571, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 216169, ["x"] = 0.571, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.571, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 79335 }, ["questLines"] = { { ["id"] = 5606, ["name"] = "Mourning Rise", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79337] = { ["id"] = 79337, ["name"] = "The Last Journey", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78743, 78744, 78745, 78746, 78747, 78748, 78749, 79335, 79336, 79337, 79338, 79339, 79340, 79341, 79342, 81661, 82895 }, ["series"] = { 79338 }, ["description"] = "This lantern is perfect. Enough of this. It is time! I can feel my memory clouding. We have to get going. Urtago is waiting for us. They will join us on my final journey to Mourning Rise, where we will conduct a ceremony. < Korgran forces a smile.> It is nothing fancy, I promise. As I said, it is more symbolic than anything else. My head feels heavy. What was I doing again? Hmm, oh, right! Meeting Urtago !", ["objectivesText"] = "Wait for Korgran and then regroup with Urtago outside at Fallside Outpost.", ["rewardGold"] = 232300, ["rewardXP"] = 7135, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 216169, ["x"] = 0.571, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 213187, ["x"] = 0.574, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.571, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 79336 }, ["questLines"] = { { ["id"] = 5606, ["name"] = "Mourning Rise", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79338] = { ["id"] = 79338, ["name"] = "The Lost Earthen", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78743, 78744, 78745, 78746, 78747, 78748, 78749, 79335, 79336, 79337, 79338, 79339, 79340, 79341, 79342, 81661, 82895 }, ["series"] = { 79337 }, ["description"] = "This is horrible! I knew I should have been keeping a closer eye on him. Confusion is the last symptom before a shutdown. Our memory is finite and starts overwriting. The more an earthen exert themselves, the faster their energy depletes and they lose memories. Korgran must be scared not knowing where he is--maybe not even who he is. I am such a boulder head! <name>, please, I think I saw him go east into the trees. Meet me there up the road!", ["objectivesText"] = "Help Urtago find Korgran. Progress: Were you able to find any sign of Korgran?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 216677 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 213187, ["x"] = 0.574, ["y"] = 0.43 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 216878, ["x"] = 0.61, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.574, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 79337 }, ["questLines"] = { { ["id"] = 5606, ["name"] = "Mourning Rise", ["orderIndex"] = 11, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79339] = { ["id"] = 79339, ["name"] = "A Change of Tradition", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78743, 78744, 78745, 78746, 78747, 78748, 78749, 79335, 79336, 79337, 79338, 79339, 79340, 79341, 79342, 81661, 82895 }, ["description"] = "An Unbound earthen can't return to the Coreway, so we have Mourning Rise. But looking at Korgran, remembering our last conversation before... I may not be the Mourning Rise caretaker just yet, but with Korgran's condition, it falls to me to be in charge. As Unbound, we made our own rules and traditions. So what if he doesn't want to stand at Mourning Rise? If a seaside memorial is what Caretaker Korgran wants, that's what he gets. <name>, meet me at the shore to the southeast of here.", ["objectivesText"] = "Meet Urtago and Korgran by the shore.", ["rewardGold"] = 30900, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 216878, ["x"] = 0.61, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 216173, ["x"] = 0.698, ["y"] = 0.568 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.61, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 79338 }, ["questLines"] = { { ["id"] = 5606, ["name"] = "Mourning Rise", ["orderIndex"] = 12, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79340] = { ["id"] = 79340, ["name"] = "Tools of Declaration", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78743, 78744, 78745, 78746, 78747, 78748, 78749, 79335, 79336, 79337, 79338, 79339, 79340, 79341, 79342, 81661, 82895 }, ["description"] = "As Unbound caretakers, we have a tradition for when a master bequeaths their mantle to their apprentice. Figuratively, of course. To do that, Korgran will need a horn. He would then face me, blow the horn, and the sound signifies his passing the mantle of the Mourning Rise caretaker to me. I saw shalehorns to the west of here. I would be thankful if you could bring me several of their horns. I will choose one that is suitable.", ["objectivesText"] = "Collect 4 Pristine Horns near Restless Estuary. Progress: Remember, the horns must be in pristine condition.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 213171 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 216173, ["x"] = 0.698, ["y"] = 0.568 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 216173, ["x"] = 0.698, ["y"] = 0.568 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.568 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 79339 }, ["questLines"] = { { ["id"] = 5606, ["name"] = "Mourning Rise", ["orderIndex"] = 13, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79341] = { ["id"] = 79341, ["name"] = "Cleansing Ashes", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78743, 78744, 78745, 78746, 78747, 78748, 78749, 79335, 79336, 79337, 79338, 79339, 79340, 79341, 79342, 81661, 82895 }, ["description"] = "The Unbound have a symbolic ceremony of cleansing. We perform it before a shutdown. It is a symbolic process of purification. For it, we need to gather ashenfold , a flower that grows around the isle. We waft the smoke of the burned flowers through the fissures and cracks in our bodies to symbolically remove impurities. We are then ready to embrace our final moments. < Urtago looks at Korgran with a hand on her chest. Her face falls.>", ["objectivesText"] = "Collect 6 ashenfold flowers near Restless Estuary. Progress: Do you have the flowers, <name>?", ["rewardGold"] = 292100, ["rewardXP"] = 9515, ["rewardItems"] = { 213157 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 216173, ["x"] = 0.698, ["y"] = 0.568 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 216173, ["x"] = 0.698, ["y"] = 0.568 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.568 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 79339 }, ["questLines"] = { { ["id"] = 5606, ["name"] = "Mourning Rise", ["orderIndex"] = 14, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79342] = { ["id"] = 79342, ["name"] = "As He Departs", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78743, 78744, 78745, 78746, 78747, 78748, 78749, 79335, 79336, 79337, 79338, 79339, 79340, 79341, 79342, 81661, 82895 }, ["description"] = "It is time for the ceremony, <name>. Please place the bowl of ashenfolds by Korgran and then hand him the horn. Once the ceremony concludes, I will be the new caretaker. Then I will have to say a final farewell to my friend. Korgran will shutdown peacefully, knowing we were here by his side in the place he loved most--something I wish and hope to have when it is my time. My core is mud, but it is a great honor to stand here with him... and with you.", ["objectivesText"] = "Help Urtago and Korgran perform the ceremony. Progress: It is a bittersweet moment.", ["rewardGold"] = 292100, ["rewardXP"] = 9515, ["rewardItems"] = { 217041 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 216173, ["x"] = 0.698, ["y"] = 0.568 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 216173, ["x"] = 0.698, ["y"] = 0.568 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.568 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 79340, 79341 }, ["questLines"] = { { ["id"] = 5606, ["name"] = "Mourning Rise", ["orderIndex"] = 15, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79343] = { ["id"] = 79343, ["name"] = "Everyday I'm Snufflin'", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79343 }, ["description"] = "Perhaps the kobolds of Gundargaz would be interested in this Odd Glob of Wax.", ["objectivesText"] = "Bring the Odd Glob of Wax to Gnawbles in Gundargaz. Progress: You snuffle something good?", ["rewardGold"] = 232300, ["rewardXP"] = 7440, ["rewardItems"] = { 228228 }, ["starts"] = { { ["x"] = 0.435, ["y"] = 0.353, ["mapID"] = 2214 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 216164, ["x"] = 0.448667, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.448667, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79573, 80082 }, ["questLines"] = { { ["id"] = 5710, ["name"] = "Everyday I'm Snufflin'", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214, ["db2QuestHubAreaPoiID"] = 7911 },
[79344] = { ["id"] = 79344, ["name"] = "Urban Odyssey", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 79197, 79328, 79333, 79344, 82153, 83271, 83286, 83315 }, ["description"] = "Did ye hear, <name>? A lot of folks from the city are eager to lend a hand an' support our attack on the nerubians and Xal'atath. I think it's worth reachin' out tae them tae see how they could pitch in. The more support we gather, the better.", ["objectivesText"] = "Ask around Dornogal for pledges of support in the coming conflict. Progress: I am glad to see you return, <name>.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 214917, ["x"] = 0.316667, ["y"] = 0.600667 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 214917, ["x"] = 0.316667, ["y"] = 0.600667 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.316667, ["y"] = 0.600667 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 83315 }, ["questLines"] = { { ["id"] = 5551, ["name"] = "Against the Current", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5551, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[79346] = { ["id"] = 79346, ["name"] = "Chew On That", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79346 }, ["description"] = "Fishing out here is not easy, especially when the spooky sounds of the darkness start to wear on the nerves. I've taken to chewing on the Duskstem from the tall plants nearby. It's sweet and chewy, keeps the jaw busy, and helps me pass the time! If you could lend a hand by gathering some Duskstem with your flying mount, I would be most appreciative.", ["objectivesText"] = "Collect 20 Duskstem from the tallest plants that grow in the darkness. Progress: Have you collected enough?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 215447, 228741 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 40 }, { ["id"] = 2899, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 215956, ["x"] = 0.658, ["y"] = 0.244 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 215956, ["x"] = 0.658, ["y"] = 0.244 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.244 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 79295 } },
[79349] = { ["id"] = 79349, ["name"] = "Entrepreneur, Inc.", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78897, 78898, 78901, 78902, 79349 }, ["description"] = "Okay, color me impressed. You are officially my Coinchamp! It's like a champion, only I pay you to do things. A mercenary, only with better branding. You should meet my business partner, Ripsnoodle . He's working out some deals with his own coinchamps with the niffin over at Mmarl. He might have more work for you--though I recommend not buying anything he tries to sell you. You can find Mmarl east of here. Just follow your nose, you can smell it from a mile away.", ["objectivesText"] = "Find Ripsnoodle in Mmarl.", ["rewardGold"] = 29200, ["rewardXP"] = 1325, ["rewardItems"] = { 226172 }, ["rewardCurrencies"] = { { ["id"] = 3002, ["amount"] = 500 }, { ["id"] = 3056, ["amount"] = 35 } }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 214168, ["x"] = 0.408, ["y"] = 0.398 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 216308, ["x"] = 0.782, ["y"] = 0.616 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.398 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 78902 }, ["questLines"] = { { ["id"] = 5565, ["name"] = "The Wormlands", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[79350] = { ["id"] = 79350, ["name"] = "Intro Dummy Quest Week 1 (Text Only)", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 79350 }, ["description"] = "I am chuffed you are helping us with this venture that is so close to my heart. As a lad, I loved dragons--as young children do--and was smitten with Sindragosa. I read all I could about her. When the Dragon Isles opened, I begged the Algeth'ar Academy to let me study the many volumes of Sindragosa's memoirs. In them found a brief mention of a battle at Traitor's Rest. The Blue Dragons are staying mum, but clues to an epic story are all about here! I must know what happened here. For Sindragosa See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(79350)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(79350))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[79354] = { ["id"] = 79354, ["name"] = "The Machine Speakers", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78738, 78741, 78742, 78760, 78761, 79354, 81689, 81798 }, ["description"] = "Ah, $p! The <race> of the hour... We were just discussing you. <Moira nods towards Speaker Brinthe.> There is some unfinished business for us to attend to, now that the High Speaker's transgressions have been corrected and the Awakening Machine restored once more. Care to stick around?", ["objectivesText"] = "Watch the conversation between Moira and Speaker Brinthe in Gundargaz.", ["rewardGold"] = 154900, ["rewardXP"] = 4960, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212742, ["x"] = 0.45, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212742, ["x"] = 0.45, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 78761 }, ["questLines"] = { { ["id"] = 5535, ["name"] = "The Monster and the Machine", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5535, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5535, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214, ["db2QuestHubAreaPoiID"] = 7911 },
[79355] = { ["id"] = 79355, ["name"] = "Prisoner Preservation", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79174, 79355, 79356, 79357 }, ["description"] = "The beasts took our people! Dragged them away when we were gettin' our first rest since our escape! We only just escaped those nerubians. We can't afford ta lose more people. Search Pillar-nest Vosh. It's where all those beasts came from. If we're lucky our people are still alive.", ["objectivesText"] = "Find 4 Expedition Members. Progress: Survivin' ain't easy, but we gotta keep pushin' on.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 215349, ["x"] = 0.578, ["y"] = 0.196 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 215349, ["x"] = 0.578, ["y"] = 0.196 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.196 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 78384 }, ["questLines"] = { { ["id"] = 5647, ["name"] = "Pillar-nest Vosh", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[79356] = { ["id"] = 79356, ["name"] = "Antifungal Firestarter", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79174, 79355, 79356, 79357 }, ["description"] = "Consider it a professional hunch, but those spores comin' out of those fungal pods and the ones afflictin' all da beasts are connected. Maybe if we destroy da fungal spore pods it'll slow whatever control those fungarians have on da beasts. Take these antifungal firebombs and torch as many fungal spore pods as you can!", ["objectivesText"] = "Burn 8 Fungal Spore Pods. Progress: Too many strange tings occur this far underground. Watch yourself.", ["rewardGold"] = 292100, ["rewardXP"] = 10595, ["rewardItems"] = { 212334 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 215349, ["x"] = 0.578, ["y"] = 0.196 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 215349, ["x"] = 0.578, ["y"] = 0.196 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.196 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 79174, 79355 }, ["questLines"] = { { ["id"] = 5647, ["name"] = "Pillar-nest Vosh", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[79357] = { ["id"] = 79357, ["name"] = "Removing the Cap", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79174, 79355, 79356, 79357 }, ["description"] = "Aemara's mention of a large fungarian planting fungal pods worries me. Gotta be someting down in dat cave. We can't just be waitin' for the fungarians to attack with a nest of mind-controlled beasts. We gotta prune dat plan before it has a chance to bloom. Get to Pillar-nest Vosh and kill that fungarian leader!", ["objectivesText"] = "Kill Agaricus Festerbloom .", ["rewardGold"] = 584200, ["rewardXP"] = 13245, ["rewardItems"] = { 213420 }, ["rewardCurrencies"] = { { ["id"] = 3002, ["amount"] = 500 }, { ["id"] = 3056, ["amount"] = 250 }, { ["id"] = 3056, ["amount"] = 285 } }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 215349, ["x"] = 0.578, ["y"] = 0.196 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 215349, ["x"] = 0.578, ["y"] = 0.196 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.196 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 79174, 79355 }, ["questLines"] = { { ["id"] = 5647, ["name"] = "Pillar-nest Vosh", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[79367] = { ["id"] = 79367, ["name"] = "A Nebb in Need", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79367, 79368, 79369, 79370, 79371, 79372, 79481 }, ["description"] = "You! You no spider. Please, must help before spiders come again. Nebb know Chittering Den. Never seen spiders here before. Eat grubs, eat kobolds. But spiders dark things from dark places. Hate light. Can't leave post. You take candles, yes? Light up barricade. Keep spiders away.", ["objectivesText"] = "Collect the Bundle of Candles and place candles along the barricade. Progress: Keep away dark. Keep away spiders.", ["rewardGold"] = 146000, ["rewardXP"] = 4960, ["rewardItems"] = { 217116 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 215737, ["x"] = 0.637, ["y"] = 0.426 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 215737, ["x"] = 0.637, ["y"] = 0.426 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.637, ["y"] = 0.426 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79573, 80434 }, ["questLines"] = { { ["id"] = 5625, ["name"] = "Envenomed Invasion", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[79368] = { ["id"] = 79368, ["name"] = "Hair of the Spider", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79367, 79368, 79369, 79370, 79371, 79372, 79481 }, ["description"] = "Light good, but more to do. Spiders came from everywhere. Nebb quick, Nebb heard them. But friend Snubjaw... he bit. Sick now. Nebb might know a way, yes, turn venom into cure. Use bite to cure bite. Bring venom. Hurry now!", ["objectivesText"] = "Collect 12 Undercrawler Venom . Progress: You have venom?", ["rewardGold"] = 292100, ["rewardXP"] = 9920, ["rewardItems"] = { 213178 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 215737, ["x"] = 0.637, ["y"] = 0.426 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 215737, ["x"] = 0.637, ["y"] = 0.426 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.637, ["y"] = 0.426 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79367 }, ["questLines"] = { { ["id"] = 5625, ["name"] = "Envenomed Invasion", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[79369] = { ["id"] = 79369, ["name"] = "Protecting the Harvest", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79367, 79368, 79369, 79370, 79371, 79372, 79481 }, ["description"] = "Nebb young, no see past own snout. If harvest lost, many kobolds lost. Not just Snubjaw . Can no waste time. Kobolds starve if spiders gobble grubs and eggs. Save them, gather eggs. As many as can carry before spiders snatch all.", ["objectivesText"] = "Collect 20 Grub Eggs . Progress: Bring eggs, we save harvest.", ["rewardGold"] = 292100, ["rewardXP"] = 9920, ["rewardItems"] = { 213209 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 217152, ["x"] = 0.637, ["y"] = 0.426 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 217152, ["x"] = 0.637, ["y"] = 0.426 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.637, ["y"] = 0.426 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79367 }, ["questLines"] = { { ["id"] = 5625, ["name"] = "Envenomed Invasion", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[79370] = { ["id"] = 79370, ["name"] = "A Poultice for Poison", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79367, 79368, 79369, 79370, 79371, 79372, 79481 }, ["description"] = "Little venom, little wax... < Nebb reaches into his pouch and gives you a handful of thick, pungent wax.> Yes, yes, should work. Finest poultice, family recipe. Hurry now, give to Snubjaw . He feel right better.", ["objectivesText"] = "Use Nebb's Poultice on Snubjaw . Progress: Poultice fix him right up.", ["rewardGold"] = 154900, ["rewardXP"] = 4960, ["rewardItems"] = { 213539 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 215737, ["x"] = 0.637, ["y"] = 0.426 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 215737, ["x"] = 0.637, ["y"] = 0.426 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.637, ["y"] = 0.426 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79368, 79369, 79481 }, ["questLines"] = { { ["id"] = 5625, ["name"] = "Envenomed Invasion", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[79371] = { ["id"] = 79371, ["name"] = "A Royal Cure", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79367, 79368, 79369, 79370, 79371, 79372, 79481 }, ["description"] = "Poultice no work! Wax right, venom wrong? Yes... yes! Strongest cure need strongest venom. Nebb saw crawler. She queen in red and black, too big to bother with kobolds. Queen smelled juicy grubs and skittered for cave. Now you must follow. Collect royal venom. Please, Snubjaw have little time.", ["objectivesText"] = "Collect Queen Rickiticka's Venom to make a new poultice for Snubjaw . Progress: Queen venom must work.", ["rewardGold"] = 619600, ["rewardXP"] = 12400, ["rewardItems"] = { 213218, 217159 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 180 }, { ["id"] = 2902, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 215737, ["x"] = 0.637, ["y"] = 0.426 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 215737, ["x"] = 0.637, ["y"] = 0.426 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.637, ["y"] = 0.426 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79370 }, ["questLines"] = { { ["id"] = 5625, ["name"] = "Envenomed Invasion", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[79372] = { ["id"] = 79372, ["name"] = "A Clutch of Hope", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79367, 79368, 79369, 79370, 79371, 79372, 79481 }, ["description"] = "<The broodmother lies dead, coiled around a single egg. She gave her life to keep it from the spiders. You should take it to Nebb . He and the other Grubtenders would know what to do with it.>", ["objectivesText"] = "Bring the egg to Nebb . Progress: What this, another egg?", ["rewardGold"] = 292100, ["rewardXP"] = 9920, ["rewardItems"] = { 215164 }, ["starts"] = { { ["x"] = 0.639, ["y"] = 0.39, ["mapID"] = 2214, ["objectID"] = 423581 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 215737, ["x"] = 0.637, ["y"] = 0.426 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.637, ["y"] = 0.426 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79371 }, ["questLines"] = { { ["id"] = 5625, ["name"] = "Envenomed Invasion", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214, ["startItems"] = { 213425 } },
[79440] = { ["id"] = 79440, ["name"] = "Recalling the War", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 6757, ["mapID"] = 554, ["storyline"] = { 79440 }, ["description"] = "Our operations here are secure. For now, anyway! It is time for you to begin your journey to the past so that we may observe how history unfolded. Speak with Eternus if you have any final questions about our mission. She can show you how these events began.", ["objectivesText"] = "Ask Eternus to show you the events of the past.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 554, ["npcID"] = 218129, ["x"] = 0.257667, ["y"] = 0.525 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 216591, ["x"] = 0.364, ["y"] = 0.518 } }, ["coords"] = { ["mapID"] = 554, ["source"] = "quest_giver", ["x"] = 0.257667, ["y"] = 0.525 }, ["mapCandidates"] = { ["npc"] = { 371, 554 }, ["zone"] = { 6757 } }, ["questType"] = "standard" },
[79448] = { ["id"] = 79448, ["name"] = "Leave No Flightstone Unturned", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 79448, 79453 }, ["description"] = "It's so exciting to be in Valdrakken! Cuzolth and I have never been here before. And it's everything we hoped it would be. Some of the others have even introduced themselves. They actually thanked us for our work studying Flightstones and Crests. That's every researcher's dream! So I need your help again. Could you find some Flightstones and a new piece of adventuring gear? Then come back to Cuzolth for an upgrade? It would really help us solidify our new position here.", ["objectivesText"] = "Acquire 50 Flightstones by defeating unique creatures, conquering dungeons and raids, completing world activities, or by looting caches. Then speak to Cuzolth and upgrade a piece of Season 4 equipment using Flightstones . Progress: There's no need to hurry. But if you wouldn't mind hurrying anyway...", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 216449, ["x"] = 0.455, ["y"] = 0.5565 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 216449, ["x"] = 0.455, ["y"] = 0.5565 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.5565 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5537, ["name"] = "10.2.6 Upgrade System Tutorial", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
[79453] = { ["id"] = 79453, ["name"] = "Awakened Crests, Unlimited Possibilities", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 79448, 79453 }, ["description"] = "Your help is always appreciated, and now you know you can easily upgrade lower-level gear right here. Of course, I'm sure you know that Flightstones can only go so far. You need Awakened Crests to upgrade powerful adventuring gear. Much like Flightstones, these Crests are rewarded through many different activities. Awakened Crests have four tiers, and more dangerous tasks reward you with higher-tier crests. Bring me fifteen Whelpling's Awakened Crests, and we can help you upgrade some gear further.", ["objectivesText"] = "Acquire 15 Whelpling's Awakened Crests by defeating unique creatures, conquering dungeons and raids, completing world activities, or by looting caches. Then return to Vaskarn in Valdrakken. Progress: If you're having a hard time finding Whelpling's Awakened Crests, you can search for hidden treasures around the Dragon Isles. There's no shortage of those!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 211951, 212458 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 216449, ["x"] = 0.455, ["y"] = 0.5565 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 216449, ["x"] = 0.455, ["y"] = 0.5565 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.5565 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 79448 }, ["questLines"] = { { ["id"] = 5537, ["name"] = "10.2.6 Upgrade System Tutorial", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
[79469] = { ["id"] = 79469, ["name"] = "Lurking Below", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79469 }, ["objectivesText"] = "Dirt-Cracker Pick used", ["rewardItems"] = { 215467 }, ["starts"] = { { ["x"] = 0.619, ["y"] = 0.32, ["mapID"] = 2215 } }, ["ends"] = { { ["x"] = 0.619, ["y"] = 0.32, ["mapID"] = 2215 } }, ["coords"] = { ["mapID"] = 2215, ["x"] = 0.619, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14838 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Dirt-Cracker Pick used", ["amount"] = 1, ["type"] = 0, ["objectID"] = 217993, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215, ["db2WidgetSetID"] = 1061 },
