[79471] = { ["id"] = 79471, ["name"] = "Bleak Sand", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79471 }, ["objectivesText"] = "Keyflame at the Bleak Shore protected", ["rewardItems"] = { 211073, 215448, 216851, 217344, 224256, 224813, 224815 }, ["starts"] = { { ["x"] = 0.616, ["y"] = 0.128, ["mapID"] = 2215 } }, ["ends"] = { { ["x"] = 0.616, ["y"] = 0.128, ["mapID"] = 2215 } }, ["coords"] = { ["mapID"] = 2215, ["x"] = 0.616, ["y"] = 0.128 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14838 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Keyflame at the Bleak Shore protected", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215, ["db2WidgetSetID"] = 1063 },
[79475] = { ["id"] = 79475, ["name"] = "Charging Up That Hill", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 79107, 79124, 79129, 79140, 79145, 79146, 79147, 79156, 79157, 79475, 79476, 79477, 79480, 81912, 81913, 81914, 81915 }, ["series"] = { 79129, 79476 }, ["description"] = "Before we use the conduit to summon the stormrooks, we need to recharge it. There are other, gentler ways to do this but... we have to work with what's on hand. The way to the peak is overrun with hostile elementals cast off from the storm. If we send them back to their plane, we can capture their residual energy and re-energize the conduit. While you work on recharging the conduit, we will go ahead and prepare for the ritual at the peak.", ["objectivesText"] = "Charge the conduit with elemental energy. Progress: Have you finished charging the conduit?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 214995, ["x"] = 0.522667, ["y"] = 0.489 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 215039, ["x"] = 0.266, ["y"] = 0.594667 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.522667, ["y"] = 0.489 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 79124 }, ["questLines"] = { { ["id"] = 5523, ["name"] = "Ties That Bind", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5523, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79476] = { ["id"] = 79476, ["name"] = "Heeding the Call", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 79107, 79124, 79129, 79140, 79145, 79146, 79147, 79156, 79157, 79475, 79476, 79477, 79480, 81912, 81913, 81914, 81915 }, ["series"] = { 79129, 79475 }, ["description"] = "Earthen from across the island have been drawn to this place. Kind of a strange coincidence you'd show up now too. Maybe it's because Baelgrim's gone or... a new Stormward's coming. Or it could just be barometric pressure... Bah! There's time enough to spin wild theories later. Right now, we need to assist the pilgrims that have foolishly attempted the summit unprepared. We can't be worrying about them while we try to summon the stormrooks.", ["objectivesText"] = "Help 8 Stranded Pilgrims on the mountain. Progress: These earthen pilgrims seem intent on reaching the peak. I hope we can keep them safe.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 214995, ["x"] = 0.522667, ["y"] = 0.489 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 215039, ["x"] = 0.266, ["y"] = 0.594667 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.522667, ["y"] = 0.489 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 79124 }, ["questLines"] = { { ["id"] = 5523, ["name"] = "Ties That Bind", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5523, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79477] = { ["id"] = 79477, ["name"] = "Strays", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 79107, 79124, 79129, 79140, 79145, 79146, 79147, 79156, 79157, 79475, 79476, 79477, 79480, 81912, 81913, 81914, 81915 }, ["series"] = { 79147, 81912, 81913, 81915 }, ["description"] = "Kurdran Wildhammer has come to train the new Stormriders in aerial maneuvers. Thrall says his clan rides gryphons--much like the Stormriders ride stormrooks--so he should be of great help to us. Unfortunately, a few of our new recruits seem to have, uh, wandered off with their stormrooks. I wanted them to have a chance to bond, but it's time to come home. Would you mind rounding them up? Thrall and I are putting together something special for these \"rookies\" lessons.", ["objectivesText"] = "Round up the stray recruits. Progress: You found those stray rookies yet?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 215039, ["x"] = 0.266, ["y"] = 0.594667 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 215211, ["x"] = 0.4685, ["y"] = 0.662 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.266, ["y"] = 0.594667 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 81915 }, ["questLines"] = { { ["id"] = 5523, ["name"] = "Ties That Bind", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5523, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79480] = { ["id"] = 79480, ["name"] = "Paying Respects", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 79107, 79124, 79129, 79140, 79145, 79146, 79147, 79156, 79157, 79475, 79476, 79477, 79480, 81912, 81913, 81914, 81915 }, ["description"] = "Please excuse my absence. It was never my intention to turn my back on the Stormriders, then or now. But I needed to come here and pay my respects to Baelgrim. Unfortunately, these blasted nerubians are still lingering. I think they're searching for something, but I don't know what. Whatever their reasons, I cannot abide them lurking where Baelgrim fell.", ["objectivesText"] = "Clear out nerubian stragglers. Progress: I don't know who or what these nerubians are searching for, but they defile this place with their presence. Clear them out.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 214995, ["x"] = 0.522667, ["y"] = 0.489 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 214995, ["x"] = 0.522667, ["y"] = 0.489 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.522667, ["y"] = 0.489 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 81913 }, ["questLines"] = { { ["id"] = 5523, ["name"] = "Ties That Bind", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5523, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79481] = { ["id"] = 79481, ["name"] = "Tending to the Terrified", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79367, 79368, 79369, 79370, 79371, 79372, 79481 }, ["description"] = "All happen so fast. One moment, we gathering eggs and grubs. Next, spiders swarming. Nebb drag me here, many others trapped. Caught in webs, soon to be feasts. Must save the Grubtenders. We tenders, not fighters. Do not let friends become meals.", ["objectivesText"] = "Rescue 6 Terrified Grubtenders .", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 217152, ["x"] = 0.637, ["y"] = 0.426 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 217152, ["x"] = 0.637, ["y"] = 0.426 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.637, ["y"] = 0.426 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79367 }, ["questLines"] = { { ["id"] = 5625, ["name"] = "Envenomed Invasion", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[79504] = { ["id"] = 79504, ["name"] = "Dripsy Forgot Her Candle", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79504, 79505, 79507, 79508, 79510, 79552, 79554, 79555, 79556, 79565, 79680, 79681, 79682, 79683, 79998, 80000, 80058, 80202, 80378, 81999 }, ["description"] = "Gather round, tenderfoots, and Granny Scribbles tell you story. Story of what happen when Dripsy forgot her candle. Dripsy little tenderfoot, like you, who wander away from tribe...", ["objectivesText"] = "Relive Granny Scribbles ' story. Progress: You listen too. Maybe learn something.", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["rewardItems"] = { 224294 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 216438, ["x"] = 0.458, ["y"] = 0.358 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 216438, ["x"] = 0.458, ["y"] = 0.358 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.358 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79573, 80434 }, ["questLines"] = { { ["id"] = 5627, ["name"] = "Kobold Culture and Integration", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214, ["db2QuestHubAreaPoiID"] = 7911 },
[79505] = { ["id"] = 79505, ["name"] = "Chomps and the Cave-In", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79504, 79505, 79507, 79508, 79510, 79552, 79554, 79555, 79556, 79565, 79680, 79681, 79682, 79683, 79998, 80000, 80058, 80202, 80378, 81999 }, ["description"] = "Sit down, stop talk, and Granny Scribbles tell you story. Story that maybe save life one day. About what happen when not listen to old, wise kobold. Like me! Story of Chomps and the cave-in...", ["objectivesText"] = "Relive Granny Scribbles ' story. Progress: Important pay attention. Following along?", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 216438, ["x"] = 0.458, ["y"] = 0.358 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 216438, ["x"] = 0.458, ["y"] = 0.358 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.358 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79504 }, ["questLines"] = { { ["id"] = 5627, ["name"] = "Kobold Culture and Integration", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214, ["db2QuestHubAreaPoiID"] = 7911 },
[79507] = { ["id"] = 79507, ["name"] = "The Day the Stoneheads Came", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79504, 79505, 79507, 79508, 79510, 79552, 79554, 79555, 79556, 79565, 79680, 79681, 79682, 79683, 79998, 80000, 80058, 80202, 80378, 81999 }, ["description"] = "What? Want scary story? You ask. Granny Scribbles give what want. Maybe then sit still like good tenderfoots. Scariest story Granny know, yes. Story about the day the stoneheads came...", ["objectivesText"] = "Relive Granny Scribbles ' story. Progress: Hope story not too scary for you.", ["rewardGold"] = 292100, ["rewardXP"] = 9920, ["rewardItems"] = { 218249, 224400, 224403 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 216438, ["x"] = 0.458, ["y"] = 0.358 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 216438, ["x"] = 0.458, ["y"] = 0.358 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.358 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79505 }, ["questLines"] = { { ["id"] = 5627, ["name"] = "Kobold Culture and Integration", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214, ["db2QuestHubAreaPoiID"] = 7911 },
[79508] = { ["id"] = 79508, ["name"] = "Mipsy Mole-Rider", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79504, 79505, 79507, 79508, 79510, 79552, 79554, 79555, 79556, 79565, 79680, 79681, 79682, 79683, 79998, 80000, 80058, 80202, 80378, 81999 }, ["description"] = "Time for happy story. Not all days bad. < Granny Scribbles gently scratches Ol' Snorler behind his ears.> Tell story of how be friends with moles. Story of Mipsy mole-rider...", ["objectivesText"] = "Relive Granny Scribbles ' story. Progress: You listening?", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 216438, ["x"] = 0.458, ["y"] = 0.358 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 216438, ["x"] = 0.458, ["y"] = 0.358 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.358 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79507 }, ["questLines"] = { { ["id"] = 5627, ["name"] = "Kobold Culture and Integration", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214, ["db2QuestHubAreaPoiID"] = 7911 },
[79510] = { ["id"] = 79510, ["name"] = "The Wickless Candle", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79504, 79505, 79507, 79508, 79510, 79552, 79554, 79555, 79556, 79565, 79680, 79681, 79682, 79683, 79998, 80000, 80058, 80202, 80378, 81999 }, ["description"] = "Now tell story of very far place called \"surface\". New friend from there, yes, so they know what Granny Scribbles talk about. < Granny Scribbles nods sagely as she points you out.> Story of how kobold discover it long go, and what find when do. Story of the wickless candle...", ["objectivesText"] = "Relive Granny Scribbles ' story. Progress: Sound like place you know?", ["rewardGold"] = 619600, ["rewardXP"] = 12400, ["rewardItems"] = { 219224, 258262 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 180 }, { ["id"] = 2902, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 216438, ["x"] = 0.458, ["y"] = 0.358 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 216438, ["x"] = 0.458, ["y"] = 0.358 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.358 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79508 }, ["questLines"] = { { ["id"] = 5627, ["name"] = "Kobold Culture and Integration", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214, ["db2QuestHubAreaPoiID"] = 7911 },
[79511] = { ["id"] = 79511, ["name"] = "Identity Crisis", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 79511 }, ["description"] = "Hey $p, over here! I just finished speaking with Emberthal. I'm not sure what, but something is bothering her! She had lots of odd questions about visage forms. Could she be ready to choose one? How exciting! I think I saw her head over to the Victorious Visage. You should check on her, I bet you could get her to spill the secret!", ["objectivesText"] = "Speak with Emberthal in the Victorious Visage.", ["rewardGold"] = 29500, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 216946, ["x"] = 0.403714, ["y"] = 0.557429 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 216945, ["x"] = 0.295, ["y"] = 0.4965 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.403714, ["y"] = 0.557429 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[79512] = { ["id"] = 79512, ["name"] = "Who Are You?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 79512 }, ["description"] = "Perhaps Cindrethresh is right. Still, if I'm to pick a visage, I should at least give it some thought. I just do not fully understand the concept of visage forms. I have heard that visage is supposed to be ones own expression of self. How does one discover what that is? Maybe some of the individuals here in Valdrakken hold the answers. $p, I need you to gather intel. I will remain here. Report back your findings when you are finished.", ["objectivesText"] = "Speak with 9 Valdrakken Visitors in Valdrakken. Progress: Have you completed your reconnaissance yet?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 216945, ["x"] = 0.295, ["y"] = 0.4965 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 216945, ["x"] = 0.295, ["y"] = 0.4965 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.295, ["y"] = 0.4965 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 79511 } },
[79513] = { ["id"] = 79513, ["name"] = "Dragon Isles Adventuring: Being Yourself", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 79513 }, ["description"] = "I worry about Emberthal. Her mood has grown increasingly dark. By sticking to citizens of the city, she is looking for ways she is similar to them, instead of what makes her unique. Perhaps a broader sample size is in order? She needs stories to guide her. There are many such individuals with stories to tell in the Dragon Isles . Go, and speak with them. Would that I could go myself, but the duties of a Scalecommander never rest.", ["objectivesText"] = "Speak with 8 residents of the Dragon Isles and listen to their stories. Progress: Have you spoken with everyone?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 210469 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 216950, ["x"] = 0.295, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 216950, ["x"] = 0.295, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.295, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 65920, 79514, 79515 } },
[79514] = { ["id"] = 79514, ["name"] = "Don't Threaten Me With a Good Time", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 79514 }, ["description"] = "Emberthal seems worried, but I'm sure she'll come back. And when she does, she'll pick a visage form! Chromie told us all about the celebrations dragons used to have for Visage Day. So, Kalecgos and I are going to blow stuff up! Fireworks, mostly. We'll need some arcane residue to make them, though. Conveniently, there are some arcane elementals just outside the Gardens of Unity that are ripe for the harvest. The three of us have some other preparations to make here in Valdrakken.", ["objectivesText"] = "Collect 100 Arcane Residue from Volatile Arcana in The Cascades. Progress: These volatile elementals make the perfect base for fireworks!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 217348 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 216967, ["x"] = 0.295, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 216967, ["x"] = 0.295, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.295, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 79512 } },
[79515] = { ["id"] = 79515, ["name"] = "Gather Your Rosebuds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 79515 }, ["description"] = "Emberthal is quite troubled. It reminds me of a certain bronze dragon when she chose her visage form. Not to worry! Once Emberthal has returned, we shall throw a proper Visage Day celebration. The fireworks are to match the colors of the dragonflights. Each enclave of the city grows special flowers in accordance with that enclave's flight. Three of each color should be enough for the first batch of fireworks.", ["objectivesText"] = "Collect 3 of each color of Flight Flower in Valdrakken. Progress: We still require more flowers if we are to provide a celebration worthy of dragons.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 224296 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 216951, ["x"] = 0.3032, ["y"] = 0.4644 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 216951, ["x"] = 0.3032, ["y"] = 0.4644 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.3032, ["y"] = 0.4644 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 79512 } },
[79521] = { ["id"] = 79521, ["name"] = "Seizing Evidence", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 79176, 79521, 79522, 79523, 79525, 79526, 79527, 79528, 79529, 79530, 79542, 79543, 79544, 79545, 79546, 80207 }, ["description"] = "Councilward Merrix has authorized trade goods from the Deeps to be transported through this depot. However, we have received a tip that more than crafting materials are being sent and received here. Dornogal observes strict rules about what we trade and with whom. All commerce must serve the Edicts, not the interests of individuals. We do not abide unsanctioned trading. We have started going through the crates here to find smuggled goods, but we haven't found anything--yet. Help us take a look.", ["objectivesText"] = "Collect 3 Seized Shipments . Progress: The tip we received was from a highly reliable source. There must be something here.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 217498, 217499, 217500, 217501 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219394, ["x"] = 0.498, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219394, ["x"] = 0.498, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 80207 }, ["questLines"] = { { ["id"] = 5605, ["name"] = "Merrix and Steelvein", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79522] = { ["id"] = 79522, ["name"] = "Withheld Information", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 79176, 79521, 79522, 79523, 79525, 79526, 79527, 79528, 79529, 79530, 79542, 79543, 79544, 79545, 79546, 80207 }, ["description"] = "There has to be something we're missing. The tip we received was from a very reliable source. We have no reason to believe we were being misled. The Councilward will want us to get to the bottom of this, and I refuse to disappoint him. We haven't been able to get any additional information out of the workers, but maybe you'll have more luck. Speak to the ones we have detained here, and see if you can learn anything.", ["objectivesText"] = "Interrogate 5 Line Workers to gather information on the shipments. Progress: Someone here has to know something.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219394, ["x"] = 0.498, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219394, ["x"] = 0.498, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 79521 }, ["questLines"] = { { ["id"] = 5605, ["name"] = "Merrix and Steelvein", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79523] = { ["id"] = 79523, ["name"] = "Something Hidden", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["description"] = "So, they have built extra compartments in the crates to hide extra items, eh? That explains how they have been smuggling goods into and out of Dornogal without our auditors knowing. Excellent work, ! But now the fun part of our job: those crates will have to be broken open and the smuggled goods taken into evidence. Smash the bottoms out of the crates and bring anything you find back to me.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["npcID"] = 219394, ["x"] = 0.498, ["y"] = 0.494, ["mapID"] = 2339 } }, ["ends"] = { { ["npcID"] = 219394, ["x"] = 0.498, ["y"] = 0.494, ["mapID"] = 2339 } }, ["coords"] = { ["x"] = 0.498, ["y"] = 0.494, ["source"] = "quest_giver", ["mapID"] = 2339 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 79522 }, ["questLines"] = { { ["id"] = 5605, ["name"] = "Merrix and Steelvein", ["orderIndex"] = 3, ["flags"] = 0 } } },
[79525] = { ["id"] = 79525, ["name"] = "Report to the Councilward", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 79176, 79521, 79522, 79523, 79525, 79526, 79527, 79528, 79529, 79530, 79542, 79543, 79544, 79545, 79546, 80207 }, ["description"] = "Those receipts you found... Steelvein is a known smuggler that we've been chasing for a long time. The Councilward will be pleased to finally have solid evidence on his activities, and maybe even on his whereabouts. Bring these receipts to Merrix immediately. He will want to study them in detail. He said he was heading back to his office, so you should be able to find him at the Councilward's Rise. I'll package up the rest of the evidence to be brought to him later. Good work today.", ["objectivesText"] = "Take Steelvein's receipts to Merrix at the Councilward's Rise in Dornogal.", ["rewardGold"] = 29200, ["rewardXP"] = 1190, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 180 }, { ["id"] = 2897, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219394, ["x"] = 0.498, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219394, ["x"] = 0.498, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questTurnInID"] = 219394, ["questType"] = "standard", ["sourceQuests"] = { 79523 }, ["questLines"] = { { ["id"] = 5605, ["name"] = "Merrix and Steelvein", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79526] = { ["id"] = 79526, ["name"] = "Sedition", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 79176, 79521, 79522, 79523, 79525, 79526, 79527, 79528, 79529, 79530, 79542, 79543, 79544, 79545, 79546, 80207 }, ["description"] = "<The poster reads:> MERRIX is CORRUPT! STEELVEIN is WEAK! They cannot protect the earthen! They do not care about them! They spit upon the Edicts! MERRIX was BRIBED to reopen Steelvein's smuggling operation! Steelvein HIDES behind MERRIX 's authority! They are taking from YOUR pockets to line THEIRS! DO NOT TRUST THEIR LIES!", ["objectivesText"] = "Speak to Merrix at the Councilward's Rise in Dornogal. Provided item:", ["rewardGold"] = 30900, ["rewardXP"] = 1190, ["rewardItems"] = { 223954 }, ["starts"] = { { ["x"] = 0.459, ["y"] = 0.472, ["mapID"] = 2339, ["objectID"] = 429303 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219400, ["x"] = 0.555, ["y"] = 0.058 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.058 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 79546 }, ["questLines"] = { { ["id"] = 5605, ["name"] = "Merrix and Steelvein", ["orderIndex"] = 11, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79527] = { ["id"] = 79527, ["name"] = "Damage Mitigation", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 79176, 79521, 79522, 79523, 79525, 79526, 79527, 79528, 79529, 79530, 79542, 79543, 79544, 79545, 79546, 80207 }, ["description"] = "Obstorn has confirmed that Ardgrin, the overseer in charge of my supply line that runs from the Deeps into Dornogal, is the one who tipped off my peacekeepers. It is therefore also my opinion that Ardgrin is the one who penned this sedition. He must have sent his workers upstairs to post them around the city. It is imperative that we remove them before these rumors spread further. Tear them down for me.", ["objectivesText"] = "Tear down 8 Seditious Posters in Dornogal. Progress: I would not have these rumors spreading any farther than they already have.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219400, ["x"] = 0.555, ["y"] = 0.058 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219400, ["x"] = 0.555, ["y"] = 0.058 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.058 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 79526 }, ["questLines"] = { { ["id"] = 5605, ["name"] = "Merrix and Steelvein", ["orderIndex"] = 12, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79528] = { ["id"] = 79528, ["name"] = "Dispelling Rumors", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 79176, 79521, 79522, 79523, 79525, 79526, 79527, 79528, 79529, 79530, 79542, 79543, 79544, 79545, 79546, 80207 }, ["description"] = "Many of my peacekeepers have already caught wind of Ardgrin's sedition. I am told some are losing faith in my integrity as Councilward, believing that I have been taking bribes from smugglers to bolster my own coffers. I can provide proof that no such transactions have taken place--clearly--but we need to stop them from murmuring amongst themselves and giving the rumors power. Lies become truths through repetition. If you find any discussing the matter, kindly disperse them.", ["objectivesText"] = "Disperse 6 Murmuring Peacekeepers in Dornogal. Progress: I can assuage their fears later. For now, we just need to prevent the situation from worsening.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219400, ["x"] = 0.555, ["y"] = 0.058 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219400, ["x"] = 0.555, ["y"] = 0.058 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.058 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 79526 }, ["questLines"] = { { ["id"] = 5605, ["name"] = "Merrix and Steelvein", ["orderIndex"] = 13, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79529] = { ["id"] = 79529, ["name"] = "Forcing My Hand", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 79176, 79521, 79522, 79523, 79525, 79526, 79527, 79528, 79529, 79530, 79542, 79543, 79544, 79545, 79546, 80207 }, ["description"] = "I do not know if Ardgrin merely intended to sabotage me or if he wanted to force a confrontation. Either way, a confrontation he will have. I believe this situation can be rectified peacefully, but I cannot do it as the Councilward. Steelvein has never appeared in the stone, but he must now. I will parlay with Ardgrin in the Deeps and this situation will be concluded. I would have you accompany me, but there are some things I want you to know before that. Help me prepare and I will speak with you.", ["objectivesText"] = "Help Merrix disguise himself as Steelvein .", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219400, ["x"] = 0.555, ["y"] = 0.058 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219475, ["x"] = 0.555333, ["y"] = 0.066 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.058 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 79527, 79528 }, ["questLines"] = { { ["id"] = 5605, ["name"] = "Merrix and Steelvein", ["orderIndex"] = 14, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79530] = { ["id"] = 79530, ["name"] = "Bad Business", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 79176, 79521, 79522, 79523, 79525, 79526, 79527, 79528, 79529, 79530, 79542, 79543, 79544, 79545, 79546, 80207 }, ["description"] = "I have not been to the Deeps since their machines shut down. Obstorn will have to guide us to Ardgrin's depot. Once there, I will attempt a conversation. If Ardgrin is not amenable, which I suspect will be the case, we will respond with equal force. Our goal is to bring him back into the fold, not to beat him into submission. Ruling by fear only breeds resentment. We will meet you in the Deeps. Come swiftly--and, of course, speak of this to no one.", ["objectivesText"] = "Meet Steelvein in the Ringing Deeps near Hallowfall Gate, then confront Overseer Ardgrin.", ["rewardGold"] = 561800, ["rewardXP"] = 11895, ["rewardItems"] = { 223572, 252756 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 180 }, { ["id"] = 2897, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219475, ["x"] = 0.555333, ["y"] = 0.066 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 220192, ["x"] = 0.411333, ["y"] = 0.24 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.555333, ["y"] = 0.066 }, ["mapCandidates"] = { ["npc"] = { 2214, 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 79529 }, ["questLines"] = { { ["id"] = 5605, ["name"] = "Merrix and Steelvein", ["orderIndex"] = 15, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[79532] = { ["id"] = 79532, ["name"] = "Tinker, Tailor, Soldier, Spider", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79532 }, ["description"] = "I must thank you again for rescuing little Spindle from her predicament, my morsel. As a reward for your work, I would like to let you take loom and direct the weave of my newest tapestry. Meesk the Venomtongue threatens my weave-rats. He slanders my Queen. And he lends creedence to Ansurek's campaign of misinformation without a single thought to the consequences. I believe it is time that I sent Meesk and his ilk a message. Go into the city and find out as much as you can about our 'Venomtongue.'", ["objectivesText"] = "Gather rumors about Meesk the Venomtongue from the denizens of the Umbral Bazaar. Progress: Mm... Do hurry, my little morsel. I do not want little Meesk to run off before he has the chance to sample the fruits of his labor.", ["rewardGold"] = 146000, ["rewardXP"] = 5885, ["rewardItems"] = { 226103 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 207471, ["x"] = 0.556, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 227428, ["x"] = 0.534, ["y"] = 0.692 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 83277 } },
[79538] = { ["id"] = 79538, ["name"] = "Smelly Shrubberies", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79538, 79539, 79540, 79541, 80558 }, ["description"] = "Jenni here says she's got some creepers attackin' the goblins. I haven't seen any myself, but I do smell opportunity! We've got our own anti-creeper perfume. It's the same recipe we use for the incense around town. Rub it on, and everything stays away! I'm sure we can sell some to the goblins. But I'm out of materials--smellsage branches, specifically. If you gather some for me, I'll cut you in on the profits!", ["objectivesText"] = "Collect Smellsage bush branches for Rhubarn . Progress: If you smell feet, you're in the right spot.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["rewardItems"] = { 213514 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 216996, ["x"] = 0.776667, ["y"] = 0.606 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 216996, ["x"] = 0.776667, ["y"] = 0.606 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.776667, ["y"] = 0.606 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 80558 }, ["questLines"] = { { ["id"] = 5541, ["name"] = "Haggling with Mmarl", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[79539] = { ["id"] = 79539, ["name"] = "Electrifying!", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79538, 79539, 79540, 79541, 80558 }, ["description"] = "You wanna help the Venture Company? And you don't mind being disposable? Okay, listen up. When we moved in here, there were no monsters in town. But now we're finding dead workers, chewed up. It's bad for business. Fortunately, I've got a way to make money off this: an electrocution helmet. I call it my Debugger Hat . Take the latest model for a test run outside town. Kill the bugs. The niffen will see you, see that Debugger Hat at work, and know it's got good reviews.", ["objectivesText"] = "\"Advertise\" the Debugger Hat by hitting Noth swarmites with it outside of Mmarl. Progress: It oughta just kill 'em, but who knows? You might see other results, too.", ["rewardGold"] = 292100, ["rewardXP"] = 10595, ["rewardItems"] = { 213629 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 216994, ["x"] = 0.776667, ["y"] = 0.606 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 216994, ["x"] = 0.776667, ["y"] = 0.606 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.776667, ["y"] = 0.606 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 80558 }, ["questLines"] = { { ["id"] = 5541, ["name"] = "Haggling with Mmarl", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[79540] = { ["id"] = 79540, ["name"] = "The Party's Over", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79538, 79539, 79540, 79541, 80558 }, ["description"] = "Nope, nope, nope! Look, I'm used to dealing with the additives in our swimming hole and keeping things at \"marginally safe\" levels, but spiders emerging to chew us to death? That's a hard pass from me. This is OUR place, why are they buggin' us?", ["objectivesText"] = "Investigate the pool area in Mmarl.", ["rewardGold"] = 77400, ["rewardXP"] = 2650, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 217402, ["x"] = 0.776667, ["y"] = 0.606 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 216996, ["x"] = 0.776667, ["y"] = 0.606 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.776667, ["y"] = 0.606 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 79538, 79539 }, ["questLines"] = { { ["id"] = 5541, ["name"] = "Haggling with Mmarl", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[79541] = { ["id"] = 79541, ["name"] = "Burn It With Fire", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79538, 79539, 79540, 79541, 80558 }, ["description"] = "So the goblins removed the incense the niffen used to keep those creepy pests out... because it smelled bad? Honestly, I'm not surprised. Maybe we can show them that they need to work together. Leading by example! Here, I'll lend you a flamethrower. I know mine works, without weird... chicken-like effects. Head in, clear out the nests, and put the right incense back in there!", ["objectivesText"] = "Burn the Pillar-nest Hearts and replace the incense in the Mmarl cave. Progress: The cave is just up ahead.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["rewardItems"] = { 219392 }, ["rewardCurrencies"] = { { ["id"] = 3004, ["amount"] = 500 }, { ["id"] = 3056, ["amount"] = 250 }, { ["id"] = 3056, ["amount"] = 285 } }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 217029, ["x"] = 0.775, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 216994, ["x"] = 0.776667, ["y"] = 0.606 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.775, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 79540 }, ["questLines"] = { { ["id"] = 5541, ["name"] = "Haggling with Mmarl", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[79542] = { ["id"] = 79542, ["name"] = "The Councilward's Summons", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 79176, 79521, 79522, 79523, 79525, 79526, 79527, 79528, 79529, 79530, 79542, 79543, 79544, 79545, 79546, 80207 }, ["series"] = { 79543 }, ["description"] = "Councilward Merrix requests your presence in his office. He received the documents you left and would like to discuss the Steelvein situation with you further. < Saradi regards you as if she is unimpressed. She also seems to be an earthen of few words.>", ["objectivesText"] = "Meet Merrix at the Councilward's Rise in Dornogal. Progress: I am pleased you made it. The suspense was eroding me away.", ["rewardGold"] = 30900, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 225426, ["x"] = 0.46, ["y"] = 0.475 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 217069, ["x"] = 0.552, ["y"] = 0.062 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.475 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 78838, 79525 }, ["questLines"] = { { ["id"] = 5605, ["name"] = "Merrix and Steelvein", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248, ["db2QuestHubAreaPoiID"] = 7911 },
[79543] = { ["id"] = 79543, ["name"] = "Dornogal's Benefactor", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 79176, 79521, 79522, 79523, 79525, 79526, 79527, 79528, 79529, 79530, 79542, 79543, 79544, 79545, 79546, 80207 }, ["series"] = { 79542 }, ["description"] = "You are in a unique position, <name>. A position to learn. You met those who would bring this \"Bender of Edicts\" to justice, but what of the people of Dornogal? What do the earthen think of this Steelvein fellow? Humor me. Take the smuggled goods you intercepted and bring them to their intended recipients. Tell them the items are a gift from a \"mutual friend.\" You might be surprised to learn who benefits from these... illicit deeds.", ["objectivesText"] = "Distribute smuggled goods around Dornogal.", ["rewardGold"] = 306800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 217069, ["x"] = 0.552, ["y"] = 0.062 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 217095, ["x"] = 0.492, ["y"] = 0.264 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.062 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 79542 }, ["questLines"] = { { ["id"] = 5605, ["name"] = "Merrix and Steelvein", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79544] = { ["id"] = 79544, ["name"] = "Security Through Trade", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 79176, 79521, 79522, 79523, 79525, 79526, 79527, 79528, 79529, 79530, 79542, 79543, 79544, 79545, 79546, 80207 }, ["series"] = { 79176, 79545 }, ["description"] = "If we're to solve this quarrel between Steelvein and Ardgrin amicably, then we'll need to make some new friends. One of Ardgrin's employees, Obstorn, frequents a cinderbrew speakeasy here in Dornogal. Only Machine Speakers may enter it. Even as Councilward, I am not able to access it. However, there are others in the city who can. Bevrusi , a Gundargaz trader, should be able to give you access. If you can grease her palm, she may be able to supply you access.", ["objectivesText"] = "Convince Bevrusi to give you access to the cinderbrew speakeasy. Progress: Do I know you?", ["rewardGold"] = 154900, ["rewardXP"] = 4760, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 217095, ["x"] = 0.492, ["y"] = 0.264 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 217072, ["x"] = 0.555, ["y"] = 0.502 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.264 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 79543 }, ["questLines"] = { { ["id"] = 5605, ["name"] = "Merrix and Steelvein", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79545] = { ["id"] = 79545, ["name"] = "The Market Reeve of the Forgegrounds", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 79176, 79521, 79522, 79523, 79525, 79526, 79527, 79528, 79529, 79530, 79542, 79543, 79544, 79545, 79546, 80207 }, ["series"] = { 79176, 79544 }, ["description"] = "I've heard liquid opal tastes remarkable but no matter how often I peruse the auctions here, it's never for sale. It's quite rare. Luckily for you, there is one person who can find the stuff. Vokgret , the market reeve of the Forgegrounds. Nothing circulates in the city's flow of trade without her knowledge. I don't often try to do business with one as... connected as her. But you'll have no qualms about it, I'm sure! At this hour, you'll find her over by the inn.", ["objectivesText"] = "Acquire a Vial of Liquid Opal from Vokgret . Progress: < Vokgret speaks without looking up from her paperwork.> The city certainly is a busy place.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 211863, 219961, 220115, 220116, 228608, 228609 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 217072, ["x"] = 0.555, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 217091, ["x"] = 0.452, ["y"] = 0.488 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 79544 }, ["questLines"] = { { ["id"] = 5605, ["name"] = "Merrix and Steelvein", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79546] = { ["id"] = 79546, ["name"] = "The Machine Speakeasy", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 79176, 79521, 79522, 79523, 79525, 79526, 79527, 79528, 79529, 79530, 79542, 79543, 79544, 79545, 79546, 80207 }, ["description"] = "Machine Speakers are odd and secretive units, some prone to paranoia. Even so, the grievance they have against Steelvein must be smoothed over. As you have seen in the Forgegrounds, their quarrel with a single smuggler has put the entire city at risk. As Councilward, I will not stand for it. Let us go talk to Ardgrin's employee, Obstorn, and see if he can deliver a diplomatic message to his overseer in the Deeps. I will meet you in the tunnels.", ["objectivesText"] = "Enter the speakeasy in the tunnels below Dornogal then confront Obstorn. Progress: I would have us exchange words, not blows.", ["rewardGold"] = 619600, ["rewardXP"] = 11895, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 180 }, { ["id"] = 2897, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 217097, ["x"] = 0.605, ["y"] = 0.332 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219566, ["x"] = 0.62, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.332 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 79176 }, ["questLines"] = { { ["id"] = 5605, ["name"] = "Merrix and Steelvein", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79552] = { ["id"] = 79552, ["name"] = "Hot Wax", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2248, ["storyline"] = { 79504, 79505, 79507, 79508, 79510, 79552, 79554, 79555, 79556, 79565, 79680, 79681, 79682, 79683, 79998, 80000, 80058, 80202, 80378, 81999 }, ["description"] = "Oh. Fire bees bit bigger than Janky expect. Look mean. Other hives meaner, though. This best spot. You go grab wax. Janky stay here to...supervise. Yes!", ["objectivesText"] = "Collect 12 Fire Bee Wax from the Cinderwold. Progress: Is fire bee wax hot enough to melt self?", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["rewardItems"] = { 216670 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 219674, ["x"] = 0.72, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 219674, ["x"] = 0.72, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.72, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 81999 }, ["questLines"] = { { ["id"] = 5627, ["name"] = "Kobold Culture and Integration", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79553] = { ["id"] = 79553, ["name"] = "A Natural Remedy", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78457, 78459, 78460, 78461, 78462, 78463, 78464, 78468, 78470, 78471, 79553, 79701, 79721 }, ["description"] = "We stabilized most of the injured. But many of the earthen you saved need more help. Nerubians often fight with corrosive poisons that eats away even our stone bodies. Fungarian flesh has long been used by our healers for its medicinal powers. The fungarian takeover of the quarry is one unexpected boon to our situation, one we will adapt to. < Adelgonn looks grimly proud.> One we will adapt to. As the Unbound always do. But I can't leave Ebona's side. Will you help me?", ["objectivesText"] = "Collect 10 Fungarian Chunks in the Orecreg. Progress: Please, hurry. The nerubian poison will deal irreversible damage given enough time. If it erodes enough of their frame or seeps into their memory gem... Then we may not be able to save them.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 213233 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 217879, ["x"] = 0.418, ["y"] = 0.726 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 217879, ["x"] = 0.418, ["y"] = 0.726 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.726 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78464 }, ["questLines"] = { { ["id"] = 5525, ["name"] = "Earthen Fissures", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5525, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5525, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79554] = { ["id"] = 79554, ["name"] = "Holy Hydrocarbons", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79504, 79505, 79507, 79508, 79510, 79552, 79554, 79555, 79556, 79565, 79680, 79681, 79682, 79683, 79998, 80000, 80058, 80202, 80378, 81999 }, ["description"] = "These devotional candles might be of interest to Janky the kobold candlesmith in Gundargaz.", ["objectivesText"] = "Collect Devotional Candles for Janky in Gundargaz. Progress: What smell like new candle?", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["rewardItems"] = { 217388, 217389, 228407 }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 216598, ["x"] = 0.455, ["y"] = 0.332 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.332 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5627, ["name"] = "Kobold Culture and Integration", ["orderIndex"] = 11, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[79555] = { ["id"] = 79555, ["name"] = "Deep Wax Galactic", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79504, 79505, 79507, 79508, 79510, 79552, 79554, 79555, 79556, 79565, 79680, 79681, 79682, 79683, 79998, 80000, 80058, 80202, 80378, 81999 }, ["description"] = "While sourcing it may not be pleasant, this waxy substance seems like it might make a fine candle. Janky the candlesmith in Gundargaz might be interested in this.", ["objectivesText"] = "Collect Waxy Excretions and bring them to Janky in Gundargaz. Progress: What bring Janky ?", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["rewardItems"] = { 212980, 217385, 228408 }, ["starts"] = { { ["x"] = 0.794, ["y"] = 0.765, ["mapID"] = 2255 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 216598, ["x"] = 0.455, ["y"] = 0.332 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.332 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5627, ["name"] = "Kobold Culture and Integration", ["orderIndex"] = 12, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[79556] = { ["id"] = 79556, ["name"] = "On the Job Training", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79504, 79505, 79507, 79508, 79510, 79552, 79554, 79555, 79556, 79565, 79680, 79681, 79682, 79683, 79998, 80000, 80058, 80202, 80378, 81999 }, ["description"] = "Stoneheads use steam to run whole place. Have lava, have water, make sense. Repairs not going well, we hear. No new parts from factory. \"Against rules\" to use scrap, been told. A lot. Help get old machines work. We watch, learn. Maybe not get yelled at for helping.", ["objectivesText"] = "Help Steamwarden Hurlt repair the steamworks. Progress: How go?", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["rewardItems"] = { 158149, 197986 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 217131, ["x"] = 0.451, ["y"] = 0.318 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 217131, ["x"] = 0.451, ["y"] = 0.318 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.451, ["y"] = 0.318 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 80058 }, ["questLines"] = { { ["id"] = 5627, ["name"] = "Kobold Culture and Integration", ["orderIndex"] = 15, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214, ["db2QuestHubAreaPoiID"] = 7911 },
[79558] = { ["id"] = 79558, ["name"] = "Feathered Fiend", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["event"] = "Noblegarden", ["expansion"] = 10, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 79558 }, ["description"] = "The trinket appears to be a Noblegarden decoration of sorts. You should return this to the festivities at Razor Hill.", ["objectivesText"] = "Bring the Noblegarden Trinket to Sylnaria Fareflame at Razor Hill.", ["rewardItems"] = { 210594, 212599, 212698, 212699, 212701, 212711, 212715, 212985, 213428, 216874, 216932 }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 217125, ["x"] = 0.525, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3250 }, ["startItems"] = { 216932 } },
[79559] = { ["id"] = 79559, ["name"] = "The Verdigrease Knight", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79559, 79561, 79563, 79564, 80096, 80144, 84621, 84821 }, ["description"] = "Think you brave? Been looking for brave, but not find much. Not sure you count, look like tenderfoot who run home to granny if scrape knee. How about way to prove it? You hit me as hard as can. Try kill me. If I not dead, then I get kill you, later. Not look like it take more than one chop for you. Deal?", ["objectivesText"] = "Slay the Verdigrease Knight . Progress: Going to run away?", ["rewardGold"] = 77400, ["rewardXP"] = 2940, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 230841, ["x"] = 0.68, ["y"] = 0.804 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 218864, ["x"] = 0.668, ["y"] = 0.786 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.68, ["y"] = 0.804 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 83139 }, ["questLines"] = { { ["id"] = 5678, ["name"] = "The Verdigrease Knight", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[79561] = { ["id"] = 79561, ["name"] = "Lord of the Giants", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79559, 79561, 79563, 79564, 80096, 80144, 84621, 84821 }, ["description"] = "Can tell you not new to questing. Fell many beasts in your time, am sure, like good knight must. Greasebaddaden , king of giant slimes, lair nearby. Perfect chance to prove valor to court! Has giant fork jammed in head, can't miss. You know what do.", ["objectivesText"] = "Slay Greasebaddaden , King of the Giants. Progress: Big, have fork in head. Know him when see him.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 232743, 232745, 232754, 232759 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 218866, ["x"] = 0.668, ["y"] = 0.785 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 218866, ["x"] = 0.668, ["y"] = 0.785 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.785 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 84621 }, ["questLines"] = { { ["id"] = 5678, ["name"] = "The Verdigrease Knight", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[79563] = { ["id"] = 79563, ["name"] = "Lady of the Lake", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79559, 79561, 79563, 79564, 80096, 80144, 84621, 84821 }, ["description"] = "Shown great bravery. Humbility. Honor. Would make good Knight of Brown Table. Only task left now is most sacred. Beseech Lady of Lake for blessing. She will judge whether worthy or not. Lake in back of cave. More pond, really, but no tell her that. Puddle Lady not have same ring.", ["objectivesText"] = "Gain the Lady of the Lake 's blessing. Progress: Not far, just in back of cave.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 232738, 232744, 232753, 232757 }, ["rewardCurrencies"] = { { ["id"] = 3118, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 218837, ["x"] = 0.668, ["y"] = 0.785 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 218837, ["x"] = 0.668, ["y"] = 0.785 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.785 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79564 }, ["questLines"] = { { ["id"] = 5678, ["name"] = "The Verdigrease Knight", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[79564] = { ["id"] = 79564, ["name"] = "The Verdigrease Knight Returns", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79559, 79561, 79563, 79564, 80096, 80144, 84621, 84821 }, ["description"] = "Am back, as promise. Hear you now brave knight. Ready fulfill your end of oath? My turn strike YOU down. Kneel.", ["objectivesText"] = "Kneel before the Verdigrease Knight and accept his reprisal. Progress: Make choice.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 216566, ["x"] = 0.668, ["y"] = 0.785 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 216566, ["x"] = 0.668, ["y"] = 0.785 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.785 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 80096, 80144 }, ["questLines"] = { { ["id"] = 5678, ["name"] = "The Verdigrease Knight", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[79565] = { ["id"] = 79565, ["name"] = "Janky Candles", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2248, ["storyline"] = { 79504, 79505, 79507, 79508, 79510, 79552, 79554, 79555, 79556, 79565, 79680, 79681, 79682, 79683, 79998, 80000, 80058, 80202, 80378, 81999 }, ["description"] = "With new candle almost ready, now all need is to set up stall! Bring quality candle at good price to people! That Janky guarantee. Only problem is not have stall. You talk to Bosh in Gun-dar-ghaz for me? He have everything we need. May need barter, but you talk good! Make him give parts. Meet you down there!", ["objectivesText"] = "Acquire the parts Janky needs to build his stall in Gundargaz. Progress: Got parts?", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["rewardItems"] = { 216681, 217395, 224070, 224071, 224253, 224262, 227660, 258267 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 180 }, { ["id"] = 2815, ["amount"] = 205 }, { ["id"] = 2902, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 219674, ["x"] = 0.72, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 216598, ["x"] = 0.455, ["y"] = 0.332 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.72, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 2214, 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 80000, 80202 }, ["questLines"] = { { ["id"] = 5627, ["name"] = "Kobold Culture and Integration", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[79574] = { ["id"] = 79574, ["name"] = "The Second Front", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79574, 79579, 79580 }, ["description"] = "Our reinforcements are already inbound. These spiders just decided where our next wall will go. Clear a landing zone for General Steelstrike .", ["objectivesText"] = "Signal the landing zone.", ["rewardGold"] = 154900, ["rewardXP"] = 5300, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 217133, ["x"] = 0.294, ["y"] = 0.415 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 212076, ["x"] = 0.275, ["y"] = 0.451 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.294, ["y"] = 0.415 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 78630 }, ["nextQuests"] = { 79579, 79580 }, ["questLines"] = { { ["id"] = 5559, ["name"] = "The Second Front", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[79575] = { ["id"] = 79575, ["name"] = "What the Duck?", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Noblegarden", ["expansion"] = 10, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 79575 }, ["description"] = "I cannot work under these conditions! Something has all these silly ducks in an uproar--they nearly upended my precious golden egg! These chaotic quackers simply must be dealt with! I can keep them from entering the inn, but will you please help clear out the rest?", ["objectivesText"] = "Scare off 10 ducks using the Horn of Honking . Progress: Shoo! Shoo! ...have you shooed them all yet?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 45072, 216487 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 217125, ["x"] = 0.525, ["y"] = 0.412 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 217125, ["x"] = 0.525, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard" },
[79576] = { ["id"] = 79576, ["name"] = "A Fowl Concoction", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Noblegarden", ["expansion"] = 10, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 79576 }, ["description"] = "My egg! My precious egg! While I was shooing some stragglers away from the inn, a flock showed up and made off with some of our decorations and eggs. My beautiful golden heirloom was among the items stolen! Enough is enough. We simply must put an end to this duck invasion. Please, <name>. These pilfering poultry must be stopped! Fortunately, I know a mage in Orgrimmar who might just have a solution for us.", ["objectivesText"] = "Speak with Tethris Dewgazer at the Pathfinder's Den in Orgrimmar. Progress: Have you spoken with Tethris yet?", ["rewardItems"] = { 45072, 216881 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 217125, ["x"] = 0.525, ["y"] = 0.412 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 217125, ["x"] = 0.525, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["sourceQuests"] = { 79575 } },
[79577] = { ["id"] = 79577, ["name"] = "Duck Tales", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Noblegarden", ["expansion"] = 10, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 79577 }, ["description"] = "Take this potion, <name>. Drink it, and you should be able to chit chat with those feathery fiends. Oh, but if you happen to experience any... unintended side effects, don't blame me.", ["objectivesText"] = "Use the potion to get information from 5 ducks. Progress: Have they said anything interesting?", ["rewardItems"] = { 45072, 216488, 216881 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 217147, ["x"] = 0.525, ["y"] = 0.41 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 217125, ["x"] = 0.525, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["sourceQuests"] = { 79576 } },
[79578] = { ["id"] = 79578, ["name"] = "Just a Waddle Away", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Noblegarden", ["expansion"] = 10, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 79578 }, ["description"] = "We simply must find out where those ducks are hiding our stolen goods--and my precious egg! Oh, and who this mysterious Daetan is, of course. I convinced Tethris to give me more of that potion. Take it and bring back my golden heirloom!", ["objectivesText"] = "Discover the duck's hiding spot. Progress: Where would those ducks be hiding...", ["rewardGold"] = 309800, ["rewardItems"] = { 45072, 212599, 212608, 212643, 213428, 216488, 216489, 216874, 216881, 216890, 216897, 216898, 216900, 216901, 216902, 216932 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 217125, ["x"] = 0.525, ["y"] = 0.412 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 217125, ["x"] = 0.525, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["sourceQuests"] = { 79577 } },
[79579] = { ["id"] = 79579, ["name"] = "That Airspace is Mine(d)!", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79574, 79579, 79580 }, ["description"] = "Our advantage is air superiority. The nerubians are threatening that with their mines. Your mount is more maneuverable than our skiffs. Get in the air and take those mines out. I will deploy what resources I can to provide you some blessings to improve your capabilities.", ["objectivesText"] = "Fly through 5 nerubian mines while under the effects of Holy Lance. Progress: Our priests are powerful with the Light but lack the air speed you and your resources can achieve.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 212076, ["x"] = 0.275, ["y"] = 0.451 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 212076, ["x"] = 0.275, ["y"] = 0.451 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.275, ["y"] = 0.451 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 79574 }, ["questLines"] = { { ["id"] = 5559, ["name"] = "The Second Front", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[79580] = { ["id"] = 79580, ["name"] = "Offensive Counter", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79574, 79579, 79580 }, ["description"] = "I will not yield this ground. Get out there and kill anything with more than two legs!", ["objectivesText"] = "Slay 12 nerubians.", ["rewardGold"] = 292100, ["rewardXP"] = 10595, ["rewardCurrencies"] = { { ["id"] = 3003, ["amount"] = 500 }, { ["id"] = 3056, ["amount"] = 250 }, { ["id"] = 3056, ["amount"] = 285 } }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 212076, ["x"] = 0.275, ["y"] = 0.451 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 212076, ["x"] = 0.275, ["y"] = 0.451 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.275, ["y"] = 0.451 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 79574 }, ["questLines"] = { { ["id"] = 5559, ["name"] = "The Second Front", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[79625] = { ["id"] = 79625, ["name"] = "Not Quite Dead", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78233, 78234, 78236, 78237, 78249, 78250, 78251, 78254, 78255, 78256, 78383, 79175, 79625, 80399 }, ["description"] = "I am General Anub'azal . I loathe having little bipeds like you in the Siegehold. However, that is no longer up to me. Zev'kall is pushing me out of my own military stronghold, and collecting overcrawlers to boot! The Queen has deemed him High General, but he is unnatural, warped, and unfit. This will not stand! I have decided to use you and your kind against Zev'kall. And yes, you will get something out of it. Search that rubbish pile there. You will see.", ["objectivesText"] = "Examine the spoils pile in Siegehold. Progress: Go on, check the pile of rubbish.", ["rewardGold"] = 77400, ["rewardXP"] = 2650, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 217330, ["x"] = 0.454, ["y"] = 0.198 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 217330, ["x"] = 0.454, ["y"] = 0.198 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.198 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 78237 }, ["questLines"] = { { ["id"] = 5521, ["name"] = "Unraveling the Trapped", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5521, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5521, ["questLineOrder"] = 12 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[79627] = { ["id"] = 79627, ["name"] = "Wine and Die", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79627 }, ["description"] = "I can see it now, morsel. The pattern of our newest weave is laid bare before my mind. Meesk is well-guarded. He believes himself to be safe. That is where his weakness lies. Go to the city. Procure a bottle of his favorite drink and present it to him as a gift from your benefactor. Once he is sufficiently wooed by your affable charms, bring him to the High Hollows for his well-earned reward. I trust you, <name>. And if you lay our threads out properly, I can guarantee you quite the show.", ["objectivesText"] = "Find a way to charm Meesk the Venomtongue .", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 213538 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 227428, ["x"] = 0.534, ["y"] = 0.692 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 216298, ["x"] = 0.628, ["y"] = 0.225 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.534, ["y"] = 0.692 }, ["mapCandidates"] = { ["npc"] = { 2213, 2255 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["sourceQuests"] = { 79532 } },
[79630] = { ["id"] = 79630, ["name"] = "Searching the Web", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2213, ["storyline"] = { 79630, 79631, 80502 }, ["description"] = "Oh, thank the hollows! You look like someone that can help. <The nerubian dabs at her many eyes with a silken handkerchief.> It's just horrible! Terrible! A tragedy! My husband has gone missing! We were just wedded yesterday! It was such a wonderful ceremony... But when we were to retire for the evening, he disappeared. <She sniffles dramatically.> Please, could you find him and bring him home to me?", ["objectivesText"] = "Locate Arax'ne 's husband, Klaskin in the Umbral Bazaar. Progress: Please, I need help!", ["rewardGold"] = 30900, ["rewardXP"] = 1325, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 217356, ["x"] = 0.64, ["y"] = 0.16 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 217355, ["x"] = 0.478, ["y"] = 0.134 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["sourceQuests"] = { 78384 }, ["questLines"] = { { ["id"] = 5649, ["name"] = "Grieve & Weave", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[79631] = { ["id"] = 79631, ["name"] = "Klaskin's Great Escape", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2213, ["storyline"] = { 79630, 79631, 80502 }, ["description"] = "Silken threads, I'm saved! It's incredibly important that I make it back home without my wife seeing me. I took off after our wedding last night, and if she sees me, she's going to kill me! If the guards catch me, they'll surely alert Arax'ne . Will you help me avoid the guards and get back home?", ["objectivesText"] = "Return Klaskin to Arax'ne in the Umbral Bazaar. Progress: Please hurry!", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 217355, ["x"] = 0.478, ["y"] = 0.134 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 217356, ["x"] = 0.64, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.134 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["sourceQuests"] = { 79630 }, ["questLines"] = { { ["id"] = 5649, ["name"] = "Grieve & Weave", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2213 },
[79633] = { ["id"] = 79633, ["name"] = "The Weaver's Legacy", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2213, ["storyline"] = { 79633 }, ["description"] = "Oh, this is exciting! A meeting with someone who commands even overcrawlers to do their bidding. I have been waiting for a moment like this. Ah, I won't have to go too far though, will I? I am meant to host some up-and-coming Sureki socialites for dinner later tonight.", ["objectivesText"] = "Bring Meesk the Venomtongue to meet the Weaver.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 226103 }, ["rewardCurrencies"] = { { ["id"] = 3056, ["amount"] = 35 } }, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 216298, ["x"] = 0.628, ["y"] = 0.225 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 207471, ["x"] = 0.556, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.225 }, ["mapCandidates"] = { ["npc"] = { 2213, 2255 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["sourceQuests"] = { 79627 } },
[79641] = { ["id"] = 79641, ["name"] = "Wipe Away Their Smiles", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79641, 79642, 79643, 79644, 79645, 79646, 79647, 79648, 79649, 79650, 82628 }, ["description"] = "The kobyss grow bold if they feel they can defile our Veneration Grounds. I think we should collect their teeth to wipe the smiles off their faces. Come! My brother and I will cleanse our lands from this filth. Try to keep up!", ["objectivesText"] = "Collect kobyss teeth from slain kobyss. Progress: Let's see them smile now!", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["rewardItems"] = { 219211 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 217424, ["x"] = 0.3475, ["y"] = 0.4805 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 217424, ["x"] = 0.3475, ["y"] = 0.4805 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.3475, ["y"] = 0.4805 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questTurnInID"] = 217424, ["questType"] = "standard", ["sourceQuests"] = { 82628 }, ["questLines"] = { { ["id"] = 5610, ["name"] = "The Priory", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[79642] = { ["id"] = 79642, ["name"] = "Stave Them Off", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79641, 79642, 79643, 79644, 79645, 79646, 79647, 79648, 79649, 79650, 82628 }, ["description"] = "Without their magical weapons, the kobyss casters won't be able to use their foul necromancy. Steal their staves so we might toss them into the Sacred Flame and be done with them.", ["objectivesText"] = "Collect 5 Darkwater staves. Progress: Did you find any Darkwater Staves?", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 217426, ["x"] = 0.303333, ["y"] = 0.576 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 217426, ["x"] = 0.303333, ["y"] = 0.576 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.303333, ["y"] = 0.576 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questTurnInID"] = 217426, ["questType"] = "standard", ["sourceQuests"] = { 82628 }, ["questLines"] = { { ["id"] = 5610, ["name"] = "The Priory", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[79643] = { ["id"] = 79643, ["name"] = "Dreaded Dreadfang", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79641, 79642, 79643, 79644, 79645, 79646, 79647, 79648, 79649, 79650, 82628 }, ["description"] = "My brother and I have dealt heavy blows to the kobyss, <name>, but you could have done more. The most foul kobyss of them all has yet to taste my blade. If we take out their leader, the rest will flee back into the waters from which they came. Let's take the head of Dreadfang!", ["objectivesText"] = "Kill Dreadfang the Merciless . Progress: Ready to kill some kobyss?", ["rewardGold"] = 584200, ["rewardXP"] = 12740, ["starts"] = { { ["npcID"] = 221492 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 217424, ["x"] = 0.3475, ["y"] = 0.4805 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.3475, ["y"] = 0.4805 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questGiverID"] = 221492, ["questType"] = "standard", ["sourceQuests"] = { 79641, 79642 }, ["questLines"] = { { ["id"] = 5610, ["name"] = "The Priory", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[79644] = { ["id"] = 79644, ["name"] = "Go to the Priory", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79641, 79642, 79643, 79644, 79645, 79646, 79647, 79648, 79649, 79650, 82628 }, ["description"] = "I... I do not have the words. Theleon... I will take h-his body. They will know what to do at the priory. Oh, brother... It was not supposed to end like this...", ["objectivesText"] = "Meet Sister Etna Blayze at the Priory of the Sacred Flame.", ["rewardGold"] = 29200, ["rewardXP"] = 1275, ["rewardItems"] = { 2815, 2899, 2902, 3056, 226134, 226137, 226138, 226139, 237014 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 217424, ["x"] = 0.3475, ["y"] = 0.4805 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 217398, ["x"] = 0.4, ["y"] = 0.361 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.3475, ["y"] = 0.4805 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 79643 }, ["questLines"] = { { ["id"] = 5610, ["name"] = "The Priory", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[79645] = { ["id"] = 79645, ["name"] = "Sweet-Sting Infestation", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79641, 79642, 79643, 79644, 79645, 79646, 79647, 79648, 79649, 79650, 82628 }, ["description"] = "Poor Theleon. I gave him some of his first lessons in combat. I'll see him to his final pyre. But first, you. I've been trying to fight back an infestation of sweet-stings harassing our wine-making operations. I need someone else to finish them off while I tend to Theleon's remains. Be fast and clever and bring me some of their venom as you take care of things. We'll turn that into a poison for the nesting sites and be done with the nuisance.", ["objectivesText"] = "Collect 10 vials of Wasp Venom. Progress: Did you kill those things?", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["rewardItems"] = { 218113 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 217398, ["x"] = 0.4, ["y"] = 0.361 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 217398, ["x"] = 0.4, ["y"] = 0.361 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.361 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 79644 }, ["questLines"] = { { ["id"] = 5610, ["name"] = "The Priory", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[79646] = { ["id"] = 79646, ["name"] = "Memorial Wine", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79641, 79642, 79643, 79644, 79645, 79646, 79647, 79648, 79649, 79650, 82628 }, ["description"] = "Oh, Theleon. He always did follow his big brother into anything. While we prepare Theleon for his final rest, would you please help Brother Abealard with a batch of Memorial Wine for the service?", ["objectivesText"] = "Make Memorial Wine with Brother Abealard. Progress: Did you help Brother Abealard?", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 217398, ["x"] = 0.4, ["y"] = 0.361 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 217398, ["x"] = 0.4, ["y"] = 0.361 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.361 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 79644 }, ["questLines"] = { { ["id"] = 5610, ["name"] = "The Priory", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[79647] = { ["id"] = 79647, ["name"] = "Burning Reflections", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79641, 79642, 79643, 79644, 79645, 79646, 79647, 79648, 79649, 79650, 82628 }, ["description"] = "Sybaestan could use your support now. His little brother was his best friend. Only death could separate them... and it has. He is not taking it well. It is customary to burn written memories of the deceased. By committing them to the flames, we let go our heartache and let the warmth of memory heal us. It is a bittersweet time. You were with Theleon at the end, too. That might help Sybaestan.", ["objectivesText"] = "Help Sybaestan mourn his brother. Progress: The ritual helps ease the hearts of many.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 217398, ["x"] = 0.4, ["y"] = 0.361 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 217398, ["x"] = 0.4, ["y"] = 0.361 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.361 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 79645, 79646 }, ["questLines"] = { { ["id"] = 5610, ["name"] = "The Priory", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[79648] = { ["id"] = 79648, ["name"] = "Missing Somebody", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79641, 79642, 79643, 79644, 79645, 79646, 79647, 79648, 79649, 79650, 82628 }, ["description"] = "Theleon was a good one, but now we must commit his body to the Flames. Sybaestan is in no shape to bear his brother. Would you collect his remains from among those others awaiting their final rest?", ["objectivesText"] = "Collect Theleon's remains. Progress: You're strong and you have the distance Sybaestan lacks right now.", ["rewardGold"] = 292100, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 217398, ["x"] = 0.4, ["y"] = 0.361 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 217398, ["x"] = 0.4, ["y"] = 0.361 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.361 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 79647 }, ["questLines"] = { { ["id"] = 5610, ["name"] = "The Priory", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[79649] = { ["id"] = 79649, ["name"] = "Sacred Flame Inquisition", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79641, 79642, 79643, 79644, 79645, 79646, 79647, 79648, 79649, 79650, 82628 }, ["description"] = "All the dead are missing? How can that be? They were all laid out in preparation for their pyres. Who would want to move them? Someone must have seen something. Go ask anyone in the area who might have seen something and I'll go talk to some of the upper clergy. We'll get to the bottom of this and return our dead so they can be properly tended to.", ["objectivesText"] = "Interrogate the local clergy. Progress: Did you find anything out?", ["rewardGold"] = 292100, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 217398, ["x"] = 0.4, ["y"] = 0.361 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 217398, ["x"] = 0.4, ["y"] = 0.361 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.361 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 79648 }, ["questLines"] = { { ["id"] = 5610, ["name"] = "The Priory", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[79650] = { ["id"] = 79650, ["name"] = "Priory of the Sacred Flame: A Brother's Grief", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79641, 79642, 79643, 79644, 79645, 79646, 79647, 79648, 79649, 79650, 82628 }, ["description"] = "I fear that the Prioress may be behind our missing dead-- and our missing baron. Sybaestan has disappeared as well and I don't believe in coincidences. She and Sybaestan have taken our recent losses hard. I fear what their overwhelming grief might be doing to their souls. We must confront them and bring them back to sanity... If we can. Tell General Steelstrike what you have learned. We might need her backup. I'll be waiting for you here.", ["objectivesText"] = "Confront Prioress Haelsey Murrpray inside the Priory of the Sacred Flame. Progress: We must confront the prioress.", ["rewardGold"] = 1239200, ["rewardXP"] = 20380, ["rewardItems"] = { 226134, 226137, 226138, 226139 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 25 }, { ["id"] = 2899, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 217398, ["x"] = 0.4, ["y"] = 0.361 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 217398, ["x"] = 0.4, ["y"] = 0.361 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.361 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 79649 }, ["questLines"] = { { ["id"] = 5610, ["name"] = "The Priory", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[79651] = { ["id"] = 79651, ["name"] = "Trade Partners", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79651 }, ["description"] = "Have you visited Mmarl? It's a trade town to the southeast of here. Try some of Corby's barbeque while you're over there!", ["objectivesText"] = "Check out Mmarl.", ["rewardGold"] = 30900, ["rewardXP"] = 1325, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 223754, ["x"] = 0.558, ["y"] = 0.436 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 217029, ["x"] = 0.775, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.436 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 78256 }, ["nextQuests"] = { 80558 } },
