[79679] = { ["id"] = 79679, ["name"] = "Muddled Mind in the Mine", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14801, ["mapID"] = 2214, ["storyline"] = { 79148, 79149, 79193, 79194, 79327, 79679, 79944 }, ["series"] = { 79148 }, ["description"] = "The workers said they saw Munderut near the back of the mining area. Please find him and tell him that I said he needs to report back in. He might not remember me, or that I am his fused. Tell him to look down at his chest, at the medallion he wears. His memory of our time together fades in and out these days, but the medallion tells of our story and bond forever.", ["objectivesText"] = "Look for Munderut in Nibelgaz Mine.", ["rewardGold"] = 146000, ["rewardXP"] = 4960, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 215208, ["x"] = 0.489, ["y"] = 0.148 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 215209, ["x"] = 0.4985, ["y"] = 0.118 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.489, ["y"] = 0.148 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79148, 79149 }, ["questLines"] = { { ["id"] = 5619, ["name"] = "Rampage at Nibelgaz Mine", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[79680] = { ["id"] = 79680, ["name"] = "Pipe Patching", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79504, 79505, 79507, 79508, 79510, 79552, 79554, 79555, 79556, 79565, 79680, 79681, 79682, 79683, 79998, 80000, 80058, 80202, 80378, 81999 }, ["description"] = "Earthquake do number on old pipes. Many start leaking steam everywhere. Especially ones too tall to reach. < Fourman Grimes points up to the pipes stretching from Gundargaz to the surface.> Stoneheads not have \"approved replacements,\" but we not have time wait. Take glue and seal leaks with flappy-flying thing. Made of only best bugs, boiled myself. Will do for today.", ["objectivesText"] = "Fly near the leaks in steam pipes above Gundargaz to seal them with kobold-provided glue. Progress: Try not glue self to pipe, yes?", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 217131, ["x"] = 0.451, ["y"] = 0.318 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 217131, ["x"] = 0.451, ["y"] = 0.318 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.451, ["y"] = 0.318 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79556 }, ["questLines"] = { { ["id"] = 5627, ["name"] = "Kobold Culture and Integration", ["orderIndex"] = 16, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214, ["db2QuestHubAreaPoiID"] = 7911 },
[79681] = { ["id"] = 79681, ["name"] = "Plumber Power", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79504, 79505, 79507, 79508, 79510, 79552, 79554, 79555, 79556, 79565, 79680, 79681, 79682, 79683, 79998, 80000, 80058, 80202, 80378, 81999 }, ["description"] = "Not all leaky pipes accessible from outside. Some inside tunnels run all under Gundargaz. Tunnels small for stoneheads, but kobolds love tunnel! Just need someone to show layout. You, someone. Check with crew boss if have problems. He help go over maps.", ["objectivesText"] = "Use the Tunnel Access to plot the steam pipe routes through Gundargaz. Progress: Get lost?", ["rewardGold"] = 292100, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 217131, ["x"] = 0.451, ["y"] = 0.318 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 217131, ["x"] = 0.451, ["y"] = 0.318 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.451, ["y"] = 0.318 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79556 }, ["questLines"] = { { ["id"] = 5627, ["name"] = "Kobold Culture and Integration", ["orderIndex"] = 17, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214, ["db2QuestHubAreaPoiID"] = 7911 },
[79682] = { ["id"] = 79682, ["name"] = "Critical Pressure!", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79504, 79505, 79507, 79508, 79510, 79552, 79554, 79555, 79556, 79565, 79680, 79681, 79682, 79683, 79998, 80000, 80058, 80202, 80378, 81999 }, ["description"] = "Pressure still too high! Something else wrong, not just old pipes. Open main release before something burst. Not have time for manuals. Consequences for deal with later!", ["objectivesText"] = "Open the main release valve and deal with whatever happens. Progress: Find problem?", ["rewardGold"] = 619600, ["rewardXP"] = 12400, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 180 }, { ["id"] = 2815, ["amount"] = 205 }, { ["id"] = 2902, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 217131, ["x"] = 0.451, ["y"] = 0.318 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 217131, ["x"] = 0.451, ["y"] = 0.318 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.451, ["y"] = 0.318 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79680, 79681 }, ["questLines"] = { { ["id"] = 5627, ["name"] = "Kobold Culture and Integration", ["orderIndex"] = 18, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214, ["db2QuestHubAreaPoiID"] = 7911 },
[79683] = { ["id"] = 79683, ["name"] = "Home Is Where the Candle Is", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79504, 79505, 79507, 79508, 79510, 79552, 79554, 79555, 79556, 79565, 79680, 79681, 79682, 79683, 79998, 80000, 80058, 80202, 80378, 81999 }, ["description"] = "Exciting to have new place call home, <name>. Not quite settled, though. We not know Gundargaz. Gundargaz not know us. Time to fix both! Find out how help here. Teach new friends about us. Kobolds clever and friendly, so should be easy! Start with help three kobolds. Fourman Grimes want get to work right away. She very task oriented. Granny Scribbles tell you lot about kobold culture. And Janky want set up new business in town, sell candle to Gundargaz.", ["objectivesText"] = "Assist Fourman Grimes, Janky, and Granny Scribbles.", ["rewardGold"] = 154900, ["rewardXP"] = 4960, ["rewardItems"] = { 223625 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 25 }, { ["id"] = 2902, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 213152, ["x"] = 0.456667, ["y"] = 0.337333 }, { ["mapID"] = 2214, ["npcID"] = 222803, ["x"] = 0.45, ["y"] = 0.332 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 213152, ["x"] = 0.456667, ["y"] = 0.337333 }, { ["mapID"] = 2214, ["npcID"] = 222803, ["x"] = 0.45, ["y"] = 0.332 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.456667, ["y"] = 0.337333 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79573, 80082 }, ["questLines"] = { { ["id"] = 5627, ["name"] = "Kobold Culture and Integration", ["orderIndex"] = 19, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214, ["db2QuestHubAreaPoiID"] = 7911 },
[79686] = { ["id"] = 79686, ["name"] = "Concerning Fungarians", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 79686 }, ["description"] = "<Abandoned in the dim candlelit chamber, the parchment, wrinkled and worn, bears the traces of hastily scribbled research notes.> Log Entry: 235-18-7 Date: Fabrication Quarter Cycle Observation: Fungarians exhibit accelerated growth and increased territorial aggression. Spore dispersal seems to have quadrupled compared to previous recorded rates.", ["objectivesText"] = "Collect the remaining research notes and return them to their owner in the Freywold Village. Progress: Did you find something interesting?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 216882, 216888, 216889 }, ["starts"] = { { ["x"] = 0.358, ["y"] = 0.771, ["mapID"] = 2248, ["objectID"] = 428135 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 218729, ["x"] = 0.414, ["y"] = 0.714 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.414, ["y"] = 0.714 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5653, ["name"] = "Concerning Fungarians", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248, ["startItems"] = { 213557 } },
[79691] = { ["id"] = 79691, ["name"] = "Monsters in the Dark", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78469, 79691, 79692, 79703 }, ["description"] = "The local quarry was an active source of clay and ore for us until the fungarians took over some time ago. We were worried about the fungarians encroaching upon the village, but there's something more. Multiple sightings of a creature much larger than our native wildlife have been reported at night. Combined with villager Modhina's disappearance, I fear this is no coincidence. She visited the quarry recently and hasn't returned. We would be in your debt if you searched the tunnels.", ["objectivesText"] = "Slay the Ashen Stonestalker in Gemvein Tunnels. Progress: You do us a great service by making our lands safe.", ["rewardGold"] = 619600, ["rewardXP"] = 11895, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 216094, ["x"] = 0.422, ["y"] = 0.732 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 216094, ["x"] = 0.422, ["y"] = 0.732 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.732 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78469 }, ["questLines"] = { { ["id"] = 5601, ["name"] = "Hope, An Anomaly", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79692] = { ["id"] = 79692, ["name"] = "Buried, Not Forgotten", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78469, 79691, 79692, 79703 }, ["description"] = "Several suns ago, my friend Modhina ventured into the quarry cave. She wanted to find rare ore for Hreka, to help her craftsmanship. Modhina was excited, I remember. A rare feeling for earthen. She hasn't returned. The fungarians prevent us from searching the area. It would mean a great deal to us if you could look for her. I didn't know it was possible to spend so much of the day thinking about what if's.", ["objectivesText"] = "Find Modhina and her belongings in Gemvein Tunnels. Progress: Be careful. I fear more sinister things lurk in these tunnels.", ["rewardGold"] = 303800, ["rewardXP"] = 9515, ["rewardItems"] = { 215464, 217107, 217108 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 216094, ["x"] = 0.422, ["y"] = 0.732 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 216094, ["x"] = 0.422, ["y"] = 0.732 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.732 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78469 }, ["questLines"] = { { ["id"] = 5601, ["name"] = "Hope, An Anomaly", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79693] = { ["id"] = 79693, ["name"] = "Play Hearthstone!", ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 1, ["storyline"] = { 79693 }, ["description"] = "It's time to play Hearthstone! Here's a starter pack -- open it up and add those cards to you collection. Then, if you can find a seat at the game table, then sit down with someone else and play! Or if you can't find a seat, then you'll want some Wild cards.... I didn't tell you this but there's a shady card dealer lurking around here somewhere.", ["objectivesText"] = "Play 5 Hearthstone cards at a Hearthstone Game Table, or Wild Cards NEAR a Hearthstone Game Table. Progress: Like the game so far? Give it a chance and play those cards!", ["rewardGold"] = 31500, ["rewardItems"] = { 212979 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 215409, ["x"] = 0.53, ["y"] = 0.152 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 215409, ["x"] = 0.53, ["y"] = 0.152 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.152 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 79184 } },
[79694] = { ["id"] = 79694, ["name"] = "Play Hearthstone!", ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 1, ["storyline"] = { 79694 }, ["description"] = "It's time to play Hearthstone! Here's a starter pack -- open it up and add those cards to you collection. Then, if you can find a seat at the game table, then sit down with someone else and play! Or if you can't find a seat, then you'll want some Wild cards.... I didn't tell you this but there's a shady card dealer lurking around here somewhere.", ["objectivesText"] = "Play 5 Hearthstone cards at a Hearthstone Game Table, or Wild Cards NEAR a Hearthstone Game Table. Progress: Like the game so far? Give it a chance and play those cards!", ["rewardGold"] = 31500, ["rewardItems"] = { 212979 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 215409, ["x"] = 0.53, ["y"] = 0.152 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 215409, ["x"] = 0.53, ["y"] = 0.152 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.152 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 79184 } },
[79701] = { ["id"] = 79701, ["name"] = "The Cavalry is Here", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78457, 78459, 78460, 78461, 78462, 78463, 78464, 78468, 78470, 78471, 79553, 79701, 79721 }, ["description"] = "< Baelgrim quakes with fury.> These cursed nerubians. Attacking a triage site! So many wounded and defenseless... and yet, it looks like you outlanders are putting up a fight! Let's grind every last one of the bugs back into the ground.", ["objectivesText"] = "Repel the nerubian attack at the Proscenium.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 217766, ["x"] = 0.564667, ["y"] = 0.506667 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 217766, ["x"] = 0.564667, ["y"] = 0.506667 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.564667, ["y"] = 0.506667 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78470 }, ["questLines"] = { { ["id"] = 5525, ["name"] = "Earthen Fissures", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5525, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5525, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79703] = { ["id"] = 79703, ["name"] = "Hope, An Anomaly", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78469, 79691, 79692, 79703 }, ["description"] = "< Hreka looks through the things you retrieved, one by one.> So you risked your life to find our friend. Modhina is gone, then. Her notes are about the rare ore from the cave. Melted down, it becomes a beautiful glaze for pottery. What can I do? I'm no fighter. I can't avenge her. Besides, her body has already been reclaimed by the earth. That much is certain by the state of her memory gem fragment. What can I do now, but make a pot? Will you help me?", ["objectivesText"] = "Make a piece of pottery with Hreka . Progress: A lifetime spent making pottery. Is this my titan given fate? Then why do I still wonder?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 219920, 253035 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 25 }, { ["id"] = 2897, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 217961, ["x"] = 0.42, ["y"] = 0.72 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 217961, ["x"] = 0.42, ["y"] = 0.72 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.72 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 79691, 79692 }, ["questLines"] = { { ["id"] = 5601, ["name"] = "Hope, An Anomaly", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79710] = { ["id"] = 79710, ["name"] = "A Fin of Every Kind", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79710, 79711, 79713, 79714, 79715 }, ["description"] = "Oh! My! LEGS! You're perfect! Yes! You're a perfect, little, unassuming biped for my work. Alchemy is my trade, and an alchemist is only as good as their ingredients. See these kobyss below? I've been camped out here for weeks observing them. They seem tougher than average kobyss. My conclusion? They must be made of stronger stuff! And I want that stuff! Here's a sack. Fill it up! Fill it up with their innards! As much as you can carry!", ["objectivesText"] = "Fill up the Kobyss Innards Sack. Progress: Is that really as much as you can carry?", ["rewardGold"] = 280900, ["rewardXP"] = 10595, ["rewardItems"] = { 214504, 222921, 224102, 224103, 224232 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 217565, ["x"] = 0.6, ["y"] = 0.662 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 217565, ["x"] = 0.6, ["y"] = 0.662 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 78384, 79573 }, ["questLines"] = { { ["id"] = 5543, ["name"] = "Gutter Work", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[79711] = { ["id"] = 79711, ["name"] = "That's Pretty Gross", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79710, 79711, 79713, 79714, 79715 }, ["description"] = "<You dislodge a familiar-looking appendage from the silt. It doesn't seem particularly kobyss, but perhaps a unique specimen will earn you an increased reward from Al'kubian .>", ["objectivesText"] = "Bring the Familiar-Looking Appendage back to Al'kubian . Progress: Ooooh! What is this?", ["rewardGold"] = 154900, ["rewardXP"] = 5300, ["rewardItems"] = { 214504 }, ["starts"] = { { ["x"] = 0.556, ["y"] = 0.708, ["mapID"] = 2255, ["objectID"] = 443995 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 217565, ["x"] = 0.6, ["y"] = 0.662 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 78384, 79573 }, ["questLines"] = { { ["id"] = 5543, ["name"] = "Gutter Work", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255, ["startItems"] = { 214504 } },
[79713] = { ["id"] = 79713, ["name"] = "Moonlight Gutter Swim", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79710, 79711, 79713, 79714, 79715 }, ["description"] = "An Ascended's leg... A kobyss tribe feasting one or two dozen trueborns or skitterlings, perhaps even a sageform such as myself... But an Ascended is a different story. Let us approach this as intellectuals, and use the tools at our disposal to collect more data. What tools do we have? You. You are the tool. An intellectual tool of kobyss disposal. Dive into the lake's depths. Slay the largest of these creatures or their pets. And of course, bring me their innards.", ["objectivesText"] = "Collect Liverseeker's Intestines and Leg Chewer's Stomach . Progress: Any profits I gain from my work goes directly to scientific and alchemical research. As in, I use the profits for myself, and I am an alchemical scientist.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["rewardItems"] = { 222924, 222926 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 217565, ["x"] = 0.6, ["y"] = 0.662 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 217565, ["x"] = 0.6, ["y"] = 0.662 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 79710, 79711 }, ["questLines"] = { { ["id"] = 5543, ["name"] = "Gutter Work", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[79714] = { ["id"] = 79714, ["name"] = "Rescuing the Food", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79710, 79711, 79713, 79714, 79715 }, ["description"] = "While awaiting your innards-bestowing return, I observed some fascinating activity below. A consistent train of kobyss are dragging the limp bodies of my kin from the lake's waters and westerly into their cavern. My conclusion? Nerubians are being hunted and stored in the lake for consumption by these beasts. It's not so much for research than it is for civic duty, but I would reward you might be able to save from their fate.", ["objectivesText"] = "Rescue 5 Captive Kaheti.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["rewardItems"] = { 223287 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 217565, ["x"] = 0.6, ["y"] = 0.662 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 217565, ["x"] = 0.6, ["y"] = 0.662 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 79710, 79711 }, ["questLines"] = { { ["id"] = 5543, ["name"] = "Gutter Work", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[79715] = { ["id"] = 79715, ["name"] = "Grand, Gutsy Solutions", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79710, 79711, 79713, 79714, 79715 }, ["description"] = "I require one final piece of data. These beasts think. They organize. They coordinate. To be characteristically honest, there's nothing worse than an amphibian with an abacus. My final task for you: Bring me the brain of the biggest beast. I need it fresh, and preferably non-liquified. And, you know, perhaps it will slow them down as well.", ["objectivesText"] = "Collect the Brain of Grand Gluttony. Progress: Have you got it? Is it leaking?", ["rewardGold"] = 619600, ["rewardXP"] = 13245, ["rewardItems"] = { 222944, 222980 }, ["rewardCurrencies"] = { { ["id"] = 3004, ["amount"] = 500 }, { ["id"] = 3056, ["amount"] = 35 } }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 217565, ["x"] = 0.6, ["y"] = 0.662 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 217565, ["x"] = 0.6, ["y"] = 0.662 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 79713, 79714 }, ["questLines"] = { { ["id"] = 5543, ["name"] = "Gutter Work", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[79716] = { ["id"] = 79716, ["name"] = "The History Beneath Us", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78465, 78467, 79213, 79716, 83081, 83082, 83083, 83084, 83087 }, ["description"] = "The titan console is a huge find. And look at these ruins! There has tae be more here! But goin' out into the site is dangerous. Accordin' to Brinthe, now that the titan vault has been unearthed, elementals have come. Elementals dunnae like order magic, an' titan relics just ooze the stuff. They're on a rampage! Can ye go out there an' get some relics back from the elementals? We need tae preserve what we can!", ["objectivesText"] = "Collect 20 Shattered Relic Fragments from elementals in Golgrin's Reach. Progress: Have ye found anythin' yet?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 225886 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 225453, ["x"] = 0.616, ["y"] = 0.702 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 225453, ["x"] = 0.616, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.702 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78465 }, ["questLines"] = { { ["id"] = 5634, ["name"] = "Hidden Edicts", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79717] = { ["id"] = 79717, ["name"] = "Means of Ingress", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14793, ["mapID"] = 2213, ["storyline"] = { 79717 }, ["description"] = "Ah, look at you! Just the sort of rogue element I need. My name is Ar'syn , and I am something of a connoisseur for the fine arts and histories of our people. It is my intent to enter the Royal Preservatory--that's that large enclave just over there-- and rob it blind. But gracious, the guards will never let me get close enough to survey their security! If only I had someone to help me find a somewhat more subtle way into the building. < Ar'syn looks at you meaningfully.>", ["objectivesText"] = "Survey three potential entryways into the Royal Preservatory. Progress: Well, what do you think? I think you'll find that even the Preservatory itself is quite the work of art in its own right... Though that does mean it will prove rather vexing to infiltrate.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 217692, ["x"] = 0.3136, ["y"] = 0.2248 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 217692, ["x"] = 0.3136, ["y"] = 0.2248 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.3136, ["y"] = 0.2248 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["sourceQuests"] = { 78384 } },
[79718] = { ["id"] = 79718, ["name"] = "Skeins Street Irregulars", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14793, ["mapID"] = 2213, ["storyline"] = { 79718 }, ["description"] = "I would like nothing more than to go in and take a few of these pompous Sureki royalists out. It would make our infiltration that much easier, and it would serve them right for trampling upon our history. But I cannot get close without bringing a whole host of guards down upon the Skeins. You, though? No one will bat an eye at wanton violence if it comes from an overcrawler. Why not get in there and thin them out a bit? Oh, don't give me that look. You were going to do it anyway.", ["objectivesText"] = "Slay Sureki agents around the Royal Preservatory. Progress: You needn't worry about any moral quandaries here. The craven Sureki would do the same to you thrice over.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 217692, ["x"] = 0.3136, ["y"] = 0.2248 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 217692, ["x"] = 0.3136, ["y"] = 0.2248 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.3136, ["y"] = 0.2248 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["sourceQuests"] = { 78384 } },
[79721] = { ["id"] = 79721, ["name"] = "Fire in the Hole", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78457, 78459, 78460, 78461, 78462, 78463, 78464, 78468, 78470, 78471, 79553, 79701, 79721 }, ["description"] = "Who are you? But of course, another outlander! I'm Wenbrandt , tamer of cinderbees and creator of cinderbrew. < Wenbrandt squares himself up as if you should be impressed.> I had brought barrels of cinderbrew to help the injured. I thought drinking it would ease their pain, but for most it just caused more... burning... pain... I refuse to let my brew go to waste. Maybe it can be weaponized. The nerubians are just bugs after all--organic and flammable. This burrow here is a perfect test subject.", ["objectivesText"] = "Use cinderbrew to repel the nerubian attack in the Proscenium. Progress: Go drop a few on the nerubians. Let's see what happens.", ["rewardGold"] = 292100, ["rewardXP"] = 9515, ["rewardItems"] = { 65346, 65349, 65352 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 212295, ["x"] = 0.565, ["y"] = 0.5 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 212295, ["x"] = 0.565, ["y"] = 0.5 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.565, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78470 }, ["questLines"] = { { ["id"] = 5525, ["name"] = "Earthen Fissures", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5525, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5525, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79722] = { ["id"] = 79722, ["name"] = "Gutter Work", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78974, 78995, 79116, 79722, 79958, 79959, 79960, 80409, 80457, 82266, 82295, 82297, 82324, 82332, 82363, 82364, 82387, 82414, 82468, 82481, 82521, 82524, 82526, 82531, 82533, 82536, 83536, 83718 }, ["objectivesText"] = "Salien Gutters scavenged", ["rewardXP"] = 11765, ["rewardItems"] = { 222921, 224102, 224103, 224232, 257353, 258188 }, ["starts"] = { { ["x"] = 0.575, ["y"] = 0.711, ["mapID"] = 2255 } }, ["ends"] = { { ["x"] = 0.575, ["y"] = 0.711, ["mapID"] = 2255 } }, ["coords"] = { ["mapID"] = 2255, ["x"] = 0.575, ["y"] = 0.711 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14752 } }, ["questType"] = "world", ["questLines"] = { { ["id"] = 5564, ["name"] = "Azj-Kahet - World Quests/Repeatables", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5564, ["name"] = "Azj-Kahet - World Quests/Repeatables", ["orderIndex"] = 16, ["flags"] = 0 } }, ["db2Objectives"] = { { ["text"] = "Salien Gutters scavenged", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[79723] = { ["id"] = 79723, ["name"] = "Repatriation by Subtraction", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14793, ["mapID"] = 2213, ["storyline"] = { 79723 }, ["description"] = "Ansurek and her ilk are so short-sighted. They think that by filling our museum with trophies of their recent conquests instead of relics of our own history, we will be less inclined to remember where we came from. Well, they are probably right--in the long term, at least. History has a habit of bending towards the voice of its teller. But that is where we come in, <name>. Those relics that the Sureki forces stole? It's time to steal them back.", ["objectivesText"] = "Loot six Pillaged Trophies from the Royal Repository. Progress: Well, <name>? I'm sure the place is filled with a queen's ransom.", ["rewardGold"] = 280900, ["rewardXP"] = 10595, ["rewardItems"] = { 215159 }, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 217692, ["x"] = 0.3136, ["y"] = 0.2248 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 217692, ["x"] = 0.3136, ["y"] = 0.2248 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.3136, ["y"] = 0.2248 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["sourceQuests"] = { 79717, 79718 } },
[79724] = { ["id"] = 79724, ["name"] = "A Titanic Expedition!", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 79724, 79725, 79726, 79727, 79728 }, ["description"] = "Our merchant friend told us about some small islands off the northeast coast called \"The Three Shields.\" Apparently, there was a lot of titan activity there long ago. To me, the \"activity\" sounded like titan research and development. Exciting stuff! Tuberros and I are going there to check it out. Tharessa, my new Algari Expedition trainee, is coming along to see true professionals at work. Care to join us?", ["objectivesText"] = "Meet Rannan at The Three Shields.", ["rewardGold"] = 30900, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 217763, ["x"] = 0.588, ["y"] = 0.282 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 217657, ["x"] = 0.778, ["y"] = 0.302 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.282 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78536 }, ["questLines"] = { { ["id"] = 5652, ["name"] = "A Titanic Adventure", ["orderIndex"] = 0, ["flags"] = 1 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79725] = { ["id"] = 79725, ["name"] = "Not a Heating Pack", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 79724, 79725, 79726, 79727, 79728 }, ["description"] = "Tharessa has done some reconnaissance for us and found the gorlocs are digging up artifacts and... cuddling with them. I think it means that the artifacts emit heat? Maybe that means some artifacts are still functioning? Imagine--the titans created technology to shape worlds, and now a fish uses it to warm their fins. Hah! The gorlocs won't give them up, and I don't want to be a Rannan-kabob either. I hate to ask because they just want to be warm, but could you do something about them?", ["objectivesText"] = "Rannan wants you to kill 12 gorlocs. Progress: Did you get them? I thought I saw one sneak by a moment ago...", ["rewardGold"] = 292100, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 217657, ["x"] = 0.778, ["y"] = 0.302 }, { ["mapID"] = 2248, ["npcID"] = 217828, ["x"] = 0.78, ["y"] = 0.302 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 217828, ["x"] = 0.78, ["y"] = 0.302 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.778, ["y"] = 0.302 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 79724 }, ["questLines"] = { { ["id"] = 5652, ["name"] = "A Titanic Adventure", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79726] = { ["id"] = 79726, ["name"] = "\"Cataloguing\"", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 79724, 79725, 79726, 79727, 79728 }, ["description"] = "As ya know, we are here to collect some titan shinies, artifacts, whatever! And Rannan thinks the more shinies--er, you know what I mean--the better chance we have figurin' out something about the titans. That'll make Rannan happy, but it'll also ensure I have some extras to take to my store back home. My wife, Perisimona, is waiting for 'em back in Loamm. I can't go back empty handed!", ["objectivesText"] = "Recover 7 titan artifacts . Progress: You get some good shinies yet?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 215233 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 217656, ["x"] = 0.778, ["y"] = 0.302 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 217656, ["x"] = 0.778, ["y"] = 0.302 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.778, ["y"] = 0.302 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 79724 }, ["questLines"] = { { ["id"] = 5652, ["name"] = "A Titanic Adventure", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79727] = { ["id"] = 79727, ["name"] = "Because It's Shiny", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 79724, 79725, 79726, 79727, 79728 }, ["description"] = "While these two were ordering you around, I thought I would do something useful and make sure the gorlocs were not going to surprise us here on the beach. None of them seemed interested in us, but then I saw one huge gorloc. It killed off some smaller gorlocs then took off. It had something glowing in its claw though! It had to be an artifact. And it looked like it was working! We've got to get it back. By \"we\" I mean \"you.\" Larger-than-average gorlocs are above my Dragonscale pay grade.", ["objectivesText"] = "Retrieve the artifact from the huge gorloc. Progress: Were you able to get the artifact?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 215234 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 217659, ["x"] = 0.78, ["y"] = 0.302 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 217659, ["x"] = 0.78, ["y"] = 0.302 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.78, ["y"] = 0.302 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 79725, 79726 }, ["questLines"] = { { ["id"] = 5652, ["name"] = "A Titanic Adventure", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79728] = { ["id"] = 79728, ["name"] = "It's Probably Nothing", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 79724, 79725, 79726, 79727, 79728 }, ["description"] = "You found a buzz orb! ...Er, that's what the niffen call it. I just kind of went with it. It's still in a good condition. Still buzzing, humming, and warm to the touch! I haven't seen one since we were in Zaralek Cavern! <name>, you should see if we can get it to work. I will stand back here, just in case it is, um, not friendly. Nothing to worry about, I'm sure.", ["objectivesText"] = "Interact with the titan orb. Progress: Yes, yes! It will be very exciting to hear what you have discovered.", ["rewardGold"] = 292100, ["rewardXP"] = 9515, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 180 }, { ["id"] = 2815, ["amount"] = 205 }, { ["id"] = 2897, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 217828, ["x"] = 0.78, ["y"] = 0.302 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 217828, ["x"] = 0.78, ["y"] = 0.302 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.78, ["y"] = 0.302 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 79727 }, ["questLines"] = { { ["id"] = 5652, ["name"] = "A Titanic Adventure", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79729] = { ["id"] = 79729, ["name"] = "Educate Yourself", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14793, ["mapID"] = 2213, ["storyline"] = { 79729 }, ["description"] = "The Relics of Founding have always been the centerpieces of the Preservatory's collection. Together, those four artifacts tell our most reverent tale--that of the founding of Azj-Kahet, and of our people's rejection of our Old Masters. With luck, they will still be inside the Preservatory. Once you are inside, I want you to tamper with the shadecasters in front of each of the relics. Make sure that their messages are heard by anyone nearby--whether they wish to listen or not.", ["objectivesText"] = "Tamper with the shadecasters in front of each of the four Founding Relics.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 217692, ["x"] = 0.3136, ["y"] = 0.2248 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 217692, ["x"] = 0.3136, ["y"] = 0.2248 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.3136, ["y"] = 0.2248 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["sourceQuests"] = { 79717, 79718 } },
[79730] = { ["id"] = 79730, ["name"] = "Dogged Pursuit", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14793, ["mapID"] = 2213, ["storyline"] = { 79730 }, ["description"] = "But of course, simply stealing the relics isn't enough. We need to teach the Queen's pet burrow-worms a lesson in futility, or they will simply start the whole process again! That shouting buffoon near the central passage is Rez'kal, a member of Ansurek's personal academic entourage. He's... not very bright, but he makes up for it with enough strength to send either of us through a wall. I'm not inclined to go toe to toe with the big oaf today. Would you mind overmuch doing one last favor for me?", ["objectivesText"] = "Defeat Royal Broker Rez'kal . Progress: Be careful, <name>. What Rez'kal lacks in acuity he makes up for in scarab-headed stubbornness.", ["rewardGold"] = 619600, ["rewardXP"] = 10595, ["rewardCurrencies"] = { { ["id"] = 3002, ["amount"] = 500 }, { ["id"] = 3003, ["amount"] = 500 }, { ["id"] = 3004, ["amount"] = 500 }, { ["id"] = 3056, ["amount"] = 35 } }, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 217692, ["x"] = 0.3136, ["y"] = 0.2248 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 217692, ["x"] = 0.3136, ["y"] = 0.2248 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.3136, ["y"] = 0.2248 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["sourceQuests"] = { 79723, 79729 } },
[79944] = { ["id"] = 79944, ["name"] = "Raging Rifts", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79148, 79149, 79193, 79194, 79327, 79679, 79944 }, ["series"] = { 79194 }, ["description"] = "The elementals are coming from inside that cave. We only made it part of the way in before needing to retreat. I could see some flickering within, some strange glowing thing that looked almost like a tear in space from which the elementals poured forth! We managed to close one of these portals, but there are more. I need to stay with Nanthaz. It is up to you now, if you can manage. Destroy the rifts and find their source. I suspect it lies deeper within the cave.", ["objectivesText"] = "Destroy 4 rifts and find their source within the cave. Progress: Destroy what rifts you come across, but above all, find their source! I suspect you will find it deep inside the nearby cave. The miners you rescued spoke of breaking through to a crystal-filled room, and of the elementals pouring forth from within.", ["rewardGold"] = 584200, ["rewardXP"] = 12400, ["rewardItems"] = { 226672 }, ["rewardCurrencies"] = { { ["id"] = 2902, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 223000, ["x"] = 0.532, ["y"] = 0.11 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 223000, ["x"] = 0.532, ["y"] = 0.11 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.11 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79194 }, ["questLines"] = { { ["id"] = 5619, ["name"] = "Rampage at Nibelgaz Mine", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[79954] = { ["id"] = 79954, ["name"] = "Spiders!", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2213, ["storyline"] = { 79954, 79955, 79956, 79957 }, ["description"] = "Why, hello there, little $pr. You seem like you might be able to assist me. You see, my dear mate Ami'thax fell onto a sharp dagger. Her body was taken to Pillar-nest Xesh, just below where we stand. Xesh is used to dispose of all sorts of bodies that we never speak of again. Unfortunately I have need to speak of Ami'thax, because she had the key to my new High Hollows burrow on her when she died. Dreadful timing, really. Would you go and fetch it? Do beware of the spiders, I need my key.", ["objectivesText"] = "Find Ag'thax 's missing key in Pillar-nest Xesh. Progress: Don't let the spiders eat you before you escape with my key.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["rewardItems"] = { 146671, 181501, 181502, 181638, 181645, 181646, 181647, 181648, 181649, 181650, 181656, 181658, 181671, 181672, 181673, 181674, 181679, 181681, 184305, 184772, 184773, 184774, 184775, 184776, 216688 }, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 217255, ["x"] = 0.774667, ["y"] = 0.685333 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 217255, ["x"] = 0.774667, ["y"] = 0.685333 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.774667, ["y"] = 0.685333 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["sourceQuests"] = { 78384 }, ["questLines"] = { { ["id"] = 5545, ["name"] = "Pillar-nest of Horrors", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2213 },
[79955] = { ["id"] = 79955, ["name"] = "...And Now I'm Arachnophobic", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 79954, 79955, 79956, 79957 }, ["description"] = "Who is there? Someone? Did I imagine you? I am Albert . I was a Pathfinder once. Now that I'm blind, I see no path. It seems wrong to call myself Pathfinder Henson. I can hear, though. I can hear them eating. They eat the fresh parts. My eyes. My insides. It hurts all the time. They do not want my rotten pieces. The decayed parts are all I have left. The worst of me. I wasn't alone here, I had fellow Pathfinders. I keep hearing sobbing from the walls. Do you hear them too?", ["objectivesText"] = "Locate Albert 's friends in the walls.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["starts"] = { { ["x"] = 0.668, ["y"] = 0.549, ["mapID"] = 2216, ["npcID"] = 217640 } }, ["ends"] = { { ["x"] = 0.668, ["y"] = 0.549, ["mapID"] = 2216, ["npcID"] = 217640 } }, ["coords"] = { ["mapID"] = 2216, ["x"] = 0.668, ["y"] = 0.549 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14753 } }, ["questGiverID"] = 217640, ["questTurnInID"] = 217640, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5545, ["name"] = "Pillar-nest of Horrors", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2216 },
[79956] = { ["id"] = 79956, ["name"] = "Legs in the Ceiling", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 79954, 79955, 79956, 79957 }, ["description"] = "I don't require vengeance on my behalf, but I would like vengeance for all of my friends that were eaten. I didn't think the Horror of Xesh was real, but she is. Xishirra. A shadow of a nightmare, making a brood of monsters while she stays out of reach. The horror is ancient, and beyond us, but we can still make her pay! Pull hard on a web strand if you need to, and deal with whatever comes. We'll escape after some justice is had!", ["objectivesText"] = "Pull on the spider thread if the spiders are not already attacking, and kill whatever comes.", ["rewardGold"] = 584200, ["rewardXP"] = 13245, ["starts"] = { { ["x"] = 0.699, ["y"] = 0.633, ["mapID"] = 2216, ["npcID"] = 217640 } }, ["ends"] = { { ["x"] = 0.699, ["y"] = 0.633, ["mapID"] = 2216, ["npcID"] = 217640 } }, ["coords"] = { ["mapID"] = 2216, ["x"] = 0.699, ["y"] = 0.633 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14753 } }, ["questGiverID"] = 217640, ["questTurnInID"] = 217640, ["questType"] = "standard", ["sourceQuests"] = { 79955 }, ["questLines"] = { { ["id"] = 5545, ["name"] = "Pillar-nest of Horrors", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2216 },
[79957] = { ["id"] = 79957, ["name"] = "Maggots in your Eyes", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79954, 79955, 79956, 79957 }, ["description"] = "< Albert is no longer alive. All that remains is his head, still full of maggots. Taking him back to the Pathfinders seems like the right thing to do.>", ["objectivesText"] = "Take Albert's head to the Pathfinders in Faerin's Advance. Progress: Whose head is that?", ["rewardGold"] = 146000, ["rewardXP"] = 5300, ["rewardItems"] = { 216689, 228445, 228446, 228447, 228448 }, ["rewardChoices"] = { 228445, 228446, 228447, 228448 }, ["rewardCurrencies"] = { { ["id"] = 3004, ["amount"] = 500 }, { ["id"] = 3056, ["amount"] = 35 } }, ["starts"] = { { ["x"] = 0.687, ["y"] = 0.623, ["mapID"] = 2216, ["npcID"] = 217994 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 211708, ["x"] = 0.592, ["y"] = 0.192 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.192 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14753 } }, ["questGiverID"] = 217994, ["questType"] = "standard", ["sourceQuests"] = { 79956 }, ["questLines"] = { { ["id"] = 5545, ["name"] = "Pillar-nest of Horrors", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255, ["startItems"] = { 216689 } },
[79958] = { ["id"] = 79958, ["name"] = "Worm Sign, Sealed, Delivered", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78974, 78995, 79116, 79722, 79958, 79959, 79960, 80409, 80457, 82266, 82295, 82297, 82324, 82332, 82363, 82364, 82387, 82414, 82468, 82481, 82521, 82524, 82526, 82531, 82533, 82536, 83536, 83718 }, ["objectivesText"] = "Food placed", ["rewardXP"] = 11765, ["starts"] = { { ["x"] = 0.726, ["y"] = 0.771, ["mapID"] = 2255 } }, ["ends"] = { { ["x"] = 0.726, ["y"] = 0.771, ["mapID"] = 2255 } }, ["coords"] = { ["mapID"] = 2255, ["x"] = 0.726, ["y"] = 0.771 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14752 } }, ["questType"] = "world", ["questLines"] = { { ["id"] = 5564, ["name"] = "Azj-Kahet - World Quests/Repeatables", ["orderIndex"] = 17, ["flags"] = 0 } }, ["db2Objectives"] = { { ["text"] = "Food placed", ["amount"] = 4, ["type"] = 0, ["objectID"] = 223752, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[79959] = { ["id"] = 79959, ["name"] = "Wormcraft Rumble", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78974, 78995, 79116, 79722, 79958, 79959, 79960, 80409, 80457, 82266, 82295, 82297, 82324, 82332, 82363, 82364, 82387, 82414, 82468, 82481, 82521, 82524, 82526, 82531, 82533, 82536, 83536, 83718 }, ["rewardXP"] = 11765, ["starts"] = { { ["x"] = 0.73, ["y"] = 0.836, ["mapID"] = 2255 } }, ["ends"] = { { ["x"] = 0.73, ["y"] = 0.836, ["mapID"] = 2255 } }, ["coords"] = { ["mapID"] = 2255, ["x"] = 0.73, ["y"] = 0.836 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14752 } }, ["questType"] = "world", ["questLines"] = { { ["id"] = 5564, ["name"] = "Azj-Kahet - World Quests/Repeatables", ["orderIndex"] = 18, ["flags"] = 0 } }, ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 1, ["objectID"] = 223834 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[79960] = { ["id"] = 79960, ["name"] = "Taking it To Go", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78974, 78995, 79116, 79722, 79958, 79959, 79960, 80409, 80457, 82266, 82295, 82297, 82324, 82332, 82363, 82364, 82387, 82414, 82468, 82481, 82521, 82524, 82526, 82531, 82533, 82536, 83536, 83718 }, ["objectivesText"] = "Vigilant Nestguard corpses collected", ["rewardGold"] = 280900, ["rewardXP"] = 11765, ["rewardItems"] = { 42868, 42879, 42890, 43204, 45724, 46114, 64515, 64516, 64517, 64518, 64519, 64520, 81796, 81797, 81798, 81799, 81800, 81801, 81802, 81803, 81804, 83721, 83722, 83723, 83724, 83725, 166846, 216664, 239440 }, ["starts"] = { { ["x"] = 0.75, ["y"] = 0.774, ["mapID"] = 2255 } }, ["ends"] = { { ["x"] = 0.75, ["y"] = 0.774, ["mapID"] = 2255 } }, ["coords"] = { ["mapID"] = 2255, ["x"] = 0.75, ["y"] = 0.774 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14752 } }, ["questType"] = "world", ["questLines"] = { { ["id"] = 5564, ["name"] = "Azj-Kahet - World Quests/Repeatables", ["orderIndex"] = 19, ["flags"] = 0 } }, ["db2Objectives"] = { { ["text"] = "Vigilant Nestguard corpses collected", ["amount"] = 5, ["type"] = 0, ["objectID"] = 218379, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[79989] = { ["id"] = 79989, ["name"] = "An Ancient Awakening", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 79989 }, ["description"] = "The waygate sits just behind me. There is no way to tell how long we have until the waning enchantment on this vessel fades, or even worse, breaks. That amount of unstable energy being released could be catastrophic. Shall we continue?", ["objectivesText"] = "Empower the Waygate.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 198858 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189764, ["x"] = 0.4968, ["y"] = 0.344 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189066, ["x"] = 0.472, ["y"] = 0.902 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.4968, ["y"] = 0.344 }, ["mapCandidates"] = { ["npc"] = { 2022, 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["sourceQuests"] = { 70154 } },
[79998] = { ["id"] = 79998, ["name"] = "Mite Not Right", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2248, ["storyline"] = { 79504, 79505, 79507, 79508, 79510, 79552, 79554, 79555, 79556, 79565, 79680, 79681, 79682, 79683, 79998, 80000, 80058, 80202, 80378, 81999 }, ["description"] = "This not good. Fancy fire bees have mites! Janky seen this before. Hive get infested, good bugs get sucked dry. End bad. Need do something! Blast bees with smoke. Makes bees sleepy but mites hate! When jump off, you squish before they bite bees again.", ["objectivesText"] = "Cleanse fire bees of their infestation with Janky 's scented smoke and kill the offending mites. Progress: Many mites left?", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 219674, ["x"] = 0.72, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 219674, ["x"] = 0.72, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.72, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 81999 }, ["questLines"] = { { ["id"] = 5627, ["name"] = "Kobold Culture and Integration", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[79999] = { ["id"] = 79999, ["name"] = "Igniting Hope", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["description"] = "One dawntower has fallen, but a faint glimmer of hope remains with the smaller keyflame atop the wall. The shattered remnants needed to sustain that light were taken by the nerubians. Gather the remnants from nerubians you slay, and help ignite a beacon of hope!", ["rewardGold"] = 292100, ["rewardXP"] = 10190, ["starts"] = { { ["npcID"] = 213116, ["x"] = 0.684, ["y"] = 0.45, ["mapID"] = 2215 } }, ["ends"] = { { ["npcID"] = 213116, ["x"] = 0.684, ["y"] = 0.45, ["mapID"] = 2215 } }, ["coords"] = { ["x"] = 0.684, ["y"] = 0.45, ["source"] = "quest_giver", ["mapID"] = 2215 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78659 }, ["questLines"] = { { ["id"] = 5529, ["name"] = "The Guiding Star", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5529, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5529, ["questLineOrder"] = 8 } } },
[80000] = { ["id"] = 80000, ["name"] = "Beebiter", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2248, ["storyline"] = { 79504, 79505, 79507, 79508, 79510, 79552, 79554, 79555, 79556, 79565, 79680, 79681, 79682, 79683, 79998, 80000, 80058, 80202, 80378, 81999 }, ["description"] = "Mites kill fire bees. No good! Janky hate mites. Bite you when not even stealing wax. Not even make wax! Give bees chance. Kill biggest, bite-iest mite before eats more bees.", ["objectivesText"] = "Slay Beebiter . Progress: How feel about being on fire? Good?", ["rewardGold"] = 619600, ["rewardXP"] = 12400, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 219674, ["x"] = 0.72, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 219674, ["x"] = 0.72, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.72, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 79552, 79998 }, ["questLines"] = { { ["id"] = 5627, ["name"] = "Kobold Culture and Integration", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[80004] = { ["id"] = 80004, ["name"] = "Crab Grab", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 80004 }, ["description"] = "<The arrival of the kobyss has kept the Arathi from working these shores. Delivering a cage full of fresh crabs could aid citizens in need of food.>", ["objectivesText"] = "Collect 12 Shadowtide crabs from the waters off the Faded Shore.", ["rewardGold"] = 292100, ["rewardXP"] = 11765, ["rewardItems"] = { 216693, 228741 }, ["rewardCurrencies"] = { { ["id"] = 2899, ["amount"] = 200 } }, ["starts"] = { { ["x"] = 0.615, ["y"] = 0.174, ["mapID"] = 2215, ["objectID"] = 424347 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 206150, ["x"] = 0.632, ["y"] = 0.294 }, { ["mapID"] = 2215, ["npcID"] = 206441, ["x"] = 0.652, ["y"] = 0.28 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.632, ["y"] = 0.294 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 80005 } },
[80012] = { ["id"] = 80012, ["name"] = "Skyriding", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 80012, 80013, 80015, 80016, 80017, 80018, 90754 }, ["description"] = "This land is more vast than I remember. However, a good scholar always prepares for contingencies. Two of the most airborne dragons have agreed to aid our cause. They will provide a winged mount so you may cover more ground. I will send you to Lord Andestrasz . He shall instruct you further.", ["objectivesText"] = "Take Moratari 's portal to Lord Andestrasz . Progress: All things come with practice.", ["rewardGold"] = 34100, ["rewardXP"] = 175, ["rewardItems"] = { 194034 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 218468, ["x"] = 0.342667, ["y"] = 0.375333 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 218469, ["x"] = 0.652, ["y"] = 0.372 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.342667, ["y"] = 0.375333 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["sourceQuests"] = { 79440 }, ["questLines"] = { { ["id"] = 5546, ["name"] = "Introduction to Skyriding", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371 },
[80013] = { ["id"] = 80013, ["name"] = "How to Glide with Your Dragon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 80012, 80013, 80015, 80016, 80017, 80018, 90754 }, ["description"] = "Let us start with the basics. If you fly straight you will wear yourself out right now. Use gravity as an aid and aim slightly down to fly a long distance. The rings will give you the general angle that you should use for basic gliding. First, call upon your drake, or our Red Drake friend here can give you a lift. Then, fly through the rings and land at the target location. If you find yourself stuck, use the Bronze Timepiece and Celormu will reset you.", ["objectivesText"] = "Summon your dragonriding mount, or mount the Red Drake . Then glide through the rings and land in the target area. Progress: Well done, <name>.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 216712 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 218469, ["x"] = 0.652, ["y"] = 0.372 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 218470, ["x"] = 0.6508, ["y"] = 0.3456 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["sourceQuests"] = { 80012, 90754 }, ["questLines"] = { { ["id"] = 5546, ["name"] = "Introduction to Skyriding", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371 },
[80015] = { ["id"] = 80015, ["name"] = "How to Dive with Your Dragon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 80012, 80013, 80015, 80016, 80017, 80018, 90754 }, ["description"] = "Gliding will get you to where you want to go. But what if you want to get there faster? Diving after jumping from somewhere high will give you a speed boost. As long as you fly well, you can conserve your momentum and gain some height after a dive. Fly through the rings to the target location. If you find yourself stuck, use the Bronze Timepiece and Celormu will reset you.", ["objectivesText"] = "Dive then glide through the rings and land in the target area. Progress: Well done, <name>.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 216712 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 218469, ["x"] = 0.652, ["y"] = 0.372 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 218470, ["x"] = 0.6508, ["y"] = 0.3456 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["sourceQuests"] = { 80013 }, ["questLines"] = { { ["id"] = 5546, ["name"] = "Introduction to Skyriding", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371 },
[80016] = { ["id"] = 80016, ["name"] = "The Need For Higher Velocities", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 80012, 80013, 80015, 80016, 80017, 80018, 90754 }, ["description"] = "Sometimes you'll need to travel longer distances. If you don't need to travel up and over any obstacles, using Surge Forward is the easiest way to maintain a good forward speed to prevent yourself from plummeting out of the sky. Follow the rings again to your destination and use Surge Forward when prompted to maintain your speed. If you find yourself stuck, use the Bronze Timepiece and Celormu will reset you.", ["objectivesText"] = "Fly through the rings and land in the target area. Progress: Well done, <name>.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 216712 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 218469, ["x"] = 0.652, ["y"] = 0.372 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 218470, ["x"] = 0.6508, ["y"] = 0.3456 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["sourceQuests"] = { 80015 }, ["questLines"] = { { ["id"] = 5546, ["name"] = "Introduction to Skyriding", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371 },
[80017] = { ["id"] = 80017, ["name"] = "The Need For Higher Altitudes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 80012, 80013, 80015, 80016, 80017, 80018, 90754 }, ["description"] = "To gain height, use Skyward Ascent. Follow the rings again to your destination, using Skyward Ascent when you need upward momentum. If you find yourself stuck, use the Bronze Timepiece and Celormu will reset you.", ["objectivesText"] = "Fly through the rings and land in the target area. Progress: Well done, <name>.", ["rewardItems"] = { 216712 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 218469, ["x"] = 0.652, ["y"] = 0.372 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 218470, ["x"] = 0.6508, ["y"] = 0.3456 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["sourceQuests"] = { 80016 }, ["questLines"] = { { ["id"] = 5546, ["name"] = "Introduction to Skyriding", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371 },
[80018] = { ["id"] = 80018, ["name"] = "Fashionable Flying", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 80012, 80013, 80015, 80016, 80017, 80018, 90754 }, ["series"] = { 80349 }, ["description"] = "You have learned all I can teach you. But flying isn't just about getting to your destination--it's about getting there in style! Use the Rostrum of Transformation behind you to customize your drake's appearance.", ["objectivesText"] = "Use the Rostrum of Transformation. Progress: How do you like your look?", ["rewardItems"] = { 2778 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 218469, ["x"] = 0.652, ["y"] = 0.372 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 218469, ["x"] = 0.652, ["y"] = 0.372 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["sourceQuests"] = { 80017 }, ["questLines"] = { { ["id"] = 5546, ["name"] = "Introduction to Skyriding", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371 },
[80022] = { ["id"] = 80022, ["name"] = "Calling the Stormriders", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 78459, 78461, 78462, 78529, 78530, 78531, 78532, 78533, 78544, 78545, 78546, 78704, 78705, 78706, 78761, 78837, 79105, 79106, 80022, 80321, 80334, 80434, 91864 }, ["description"] = "I know the Unbound can repair and unblock the Coreway expediently--but I also know the nerubians. If they see an opportunity for an ambush, they will take it. With our backs turned and our focus on the Coreway, we are prime targets. I need to rally my Stormriders and form a perimeter around Dornogal in case of an attack from within or from without. Meet me outside of the Stormperch. I will call upon my troops there.", ["objectivesText"] = "Meet Baelgrim outside the Stormperch, then speak with him to follow him into The Rookery. This challenge may be completed solo or with up to 3 party members. Progress: Baelgrim is right. We need to defend the Unbound while they work on the Coreway.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 212747, ["x"] = 0.359, ["y"] = 0.525 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 212746, ["x"] = 0.36, ["y"] = 0.525 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.359, ["y"] = 0.525 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 78538 }, ["questLines"] = { { ["id"] = 5540, ["name"] = "The First Blow", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 6008, ["name"] = "Catch Up: War Within: Wrapper 2", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5540, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5540, ["questLineOrder"] = 4 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6008, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[80049] = { ["id"] = 80049, ["name"] = "The Flame Still Burns", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78607, 78613, 78614, 78615, 78620, 78621, 78624, 78626, 78627, 78628, 78629, 78630, 79089, 79297, 80049 }, ["description"] = "That was too close. This attack took a toll on all of us. We have many injured, and many shaken. Can you check in with people? See how they are doing?", ["objectivesText"] = "Check in with Arathi Survivors in the Veneration Grounds in Hallowfall . Progress: How's it looking out there?", ["rewardGold"] = 292100, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213107, ["x"] = 0.383667, ["y"] = 0.692333 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 225188, ["x"] = 0.336, ["y"] = 0.546 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.383667, ["y"] = 0.692333 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78624 }, ["questLines"] = { { ["id"] = 5526, ["name"] = "Hope in Solidarity", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5526, ["questLineOrder"] = 2 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5526, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[80058] = { ["id"] = 80058, ["name"] = "Kobold Kleanup", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79504, 79505, 79507, 79508, 79510, 79552, 79554, 79555, 79556, 79565, 79680, 79681, 79682, 79683, 79998, 80000, 80058, 80202, 80378, 81999 }, ["description"] = "New home little shabby. Not good, full of fun stuff and good bits shabby. Old, everybody died and now it fall apart shabby. We help! Lots of kobolds, now, so we make place presentable for stonehead friends. Make feel like home. You help, too. Grab broom, get going!", ["objectivesText"] = "Clean up Gundargaz. Progress: How go?", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 216568, ["x"] = 0.457, ["y"] = 0.354 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 217131, ["x"] = 0.451, ["y"] = 0.318 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.457, ["y"] = 0.354 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5627, ["name"] = "Kobold Culture and Integration", ["orderIndex"] = 14, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214, ["db2QuestHubAreaPoiID"] = 7911 },
[80069] = { ["id"] = 80069, ["name"] = "Tears of Teldrassil", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15105, ["mapID"] = 2239, ["storyline"] = { 80069, 80071, 80072, 80073, 80075, 80077, 82229 }, ["description"] = "I have carried this weight long enough. It has finally come time to put my family to rest. Even if I never found my sister... < Kelestra wipes away tears and takes a deep breath.> I must gather barrowstones to place at their final resting place. But I simply cannot carry that many stones. Maybe I ask too much of a stranger, but would you assist me? I know having someone beside me will make this more endurable.", ["objectivesText"] = "Follow Kelestra and collect barrowstones to help her memorialize her family. Progress: < Kelestra looks distraught, and her hands are shaking.> I can not parse my feelings. My sister is alive, but a traitor. And what did he mean she deserved her fate? Please Koroleth, let this finally be our time to reunite.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2239, ["npcID"] = 218623, ["x"] = 0.7255, ["y"] = 0.7305 } }, ["ends"] = { { ["mapID"] = 2239, ["npcID"] = 218697, ["x"] = 0.728, ["y"] = 0.795 } }, ["coords"] = { ["mapID"] = 2239, ["source"] = "quest_giver", ["x"] = 0.7255, ["y"] = 0.7305 }, ["mapCandidates"] = { ["npc"] = { 2239 }, ["zone"] = { 15105 } }, ["questType"] = "standard", ["sourceQuests"] = { 82229 }, ["questLines"] = { { ["id"] = 5547, ["name"] = "Sins of the Sister", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2239 },
[80071] = { ["id"] = 80071, ["name"] = "Fact Finding", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15105, ["mapID"] = 2239, ["storyline"] = { 80069, 80071, 80072, 80073, 80075, 80077, 82229 }, ["description"] = "I must speak with the Primalists. I don't understand why she would turn her back on us. Koroleth saved my life at Teldrassil. I owe it to her to find out the truth. <name>, I realize this might be awkward, but will you help me? I can no longer bear this alone.", ["objectivesText"] = "Meet Kelestra at the Twilight Watchtower.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2239, ["npcID"] = 218697, ["x"] = 0.728, ["y"] = 0.795 } }, ["ends"] = { { ["mapID"] = 2239, ["npcID"] = 218698, ["x"] = 0.336, ["y"] = 0.188 } }, ["coords"] = { ["mapID"] = 2239, ["source"] = "quest_giver", ["x"] = 0.728, ["y"] = 0.795 }, ["mapCandidates"] = { ["npc"] = { 2239 }, ["zone"] = { 15105 } }, ["questType"] = "standard", ["sourceQuests"] = { 80069 }, ["questLines"] = { { ["id"] = 5547, ["name"] = "Sins of the Sister", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2239 },
[80072] = { ["id"] = 80072, ["name"] = "A Primalist Point of View", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15105, ["mapID"] = 2239, ["storyline"] = { 80069, 80071, 80072, 80073, 80075, 80077, 82229 }, ["description"] = "Warden Malathra has granted us permission to speak with the Primalists. They might have switched sides, but the wardens are keeping a close eye on them. < Kelestra begins to look distressed.> I'm going to talk to the Warden more. Could you handle the Primalists? All of this about Koroleth is just happening so suddenly. I feel we should gather as much information as we can.", ["objectivesText"] = "Speak to the reformed Primalists about Koroleth. Progress: I want to talk to them, but I don't even know where to begin.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2239, ["npcID"] = 218698, ["x"] = 0.336, ["y"] = 0.188 } }, ["ends"] = { { ["mapID"] = 2239, ["npcID"] = 218698, ["x"] = 0.336, ["y"] = 0.188 } }, ["coords"] = { ["mapID"] = 2239, ["source"] = "quest_giver", ["x"] = 0.336, ["y"] = 0.188 }, ["mapCandidates"] = { ["npc"] = { 2239 }, ["zone"] = { 15105 } }, ["questType"] = "standard", ["sourceQuests"] = { 80071 }, ["questLines"] = { { ["id"] = 5547, ["name"] = "Sins of the Sister", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2239 },
[80073] = { ["id"] = 80073, ["name"] = "Bones of a Bygone Battle", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15105, ["mapID"] = 2239, ["storyline"] = { 80069, 80071, 80072, 80073, 80075, 80077, 82229 }, ["description"] = "After speaking with the warden, I learned the Battle of the Barrier where my sister fell took place east of here, on the shores of the Ohn'ahran Plains. I understand her body was washed out to sea and never recovered. It's possible the tide brought her remains back to shore at some point. Will you help me look for her? Each member of my family has a necklace with this distinct design. It will identify Koroleth's body. I would like to lay her to rest with the family she loved.", ["objectivesText"] = "Search the shoreline of the Ancient Bough for Koroleth's remains. Progress: Is this the necklace you found?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 217003 }, ["starts"] = { { ["mapID"] = 2239, ["npcID"] = 218698, ["x"] = 0.336, ["y"] = 0.188 } }, ["ends"] = { { ["mapID"] = 2239, ["npcID"] = 218701, ["x"] = 0.888, ["y"] = 0.208 } }, ["coords"] = { ["mapID"] = 2239, ["source"] = "quest_giver", ["x"] = 0.336, ["y"] = 0.188 }, ["mapCandidates"] = { ["npc"] = { 2239 }, ["zone"] = { 15105 } }, ["questType"] = "standard", ["sourceQuests"] = { 80072 }, ["questLines"] = { { ["id"] = 5547, ["name"] = "Sins of the Sister", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023 },
[80075] = { ["id"] = 80075, ["name"] = "A Barrow Den Burial", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15105, ["mapID"] = 2239, ["storyline"] = { 80069, 80071, 80072, 80073, 80075, 80077, 82229 }, ["description"] = "All that is left to do is to gather my sister's remains and bring them to the barrow den. Please meet me there, <name>. I could use a friend.", ["objectivesText"] = "Meet Kelestra outside the barrow den at the Fields of Reverie.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2239, ["npcID"] = 218701, ["x"] = 0.888, ["y"] = 0.208 } }, ["ends"] = { { ["mapID"] = 2239, ["npcID"] = 218785, ["x"] = 0.722, ["y"] = 0.72 } }, ["coords"] = { ["mapID"] = 2239, ["source"] = "quest_giver", ["x"] = 0.888, ["y"] = 0.208 }, ["mapCandidates"] = { ["npc"] = { 2239 }, ["zone"] = { 15105 } }, ["questType"] = "standard", ["sourceQuests"] = { 80073 }, ["questLines"] = { { ["id"] = 5547, ["name"] = "Sins of the Sister", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2239 },
[80077] = { ["id"] = 80077, ["name"] = "Sins of the Sister", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15105, ["mapID"] = 2239, ["storyline"] = { 80069, 80071, 80072, 80073, 80075, 80077, 82229 }, ["description"] = "This druid is trying to convince Malfurion not to let me bury my sister here with the rest of my family. He won't even let me get a word in. < Kelestra tightly clutches the straps of her backpack holding her sister's remains.> I know I have asked a lot of you already. Could you talk to them? Perhaps they might listen to you?", ["objectivesText"] = "Speak with Malfurion Stormrage about Koroleth's remains. Progress: <Malfurion is deep in thought.>", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 223146 }, ["starts"] = { { ["mapID"] = 2239, ["npcID"] = 218785, ["x"] = 0.722, ["y"] = 0.72 } }, ["ends"] = { { ["mapID"] = 2239, ["npcID"] = 218629, ["x"] = 0.722, ["y"] = 0.72 } }, ["coords"] = { ["mapID"] = 2239, ["source"] = "quest_giver", ["x"] = 0.722, ["y"] = 0.72 }, ["mapCandidates"] = { ["npc"] = { 2239 }, ["zone"] = { 15105 } }, ["questType"] = "standard", ["sourceQuests"] = { 80075 }, ["questLines"] = { { ["id"] = 5547, ["name"] = "Sins of the Sister", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2239 },
[80079] = { ["id"] = 80079, ["name"] = "A Wrench in the Works", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78685, 78696, 78697, 78700, 78701, 78703, 78704, 78705, 78706, 80079 }, ["description"] = "Looks like the High Speaker is addressing his workers. It seems something has finally shaken them from their complacency, and their time away from the Awakening Machine is affecting them. <Moira pauses to brush a bit of dust off her robe.> Perhaps this would be a good opportunity for everyone to hear what they have to say? We should convince a few of these Machine Speakers to speak up.", ["objectivesText"] = "Encourage members of the crowd to air their grievances. Progress: Recalcitrant lot, aren't they?", ["rewardGold"] = 292100, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 218714, ["x"] = 0.45, ["y"] = 0.332 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 218714, ["x"] = 0.45, ["y"] = 0.332 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.332 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 80082 }, ["questLines"] = { { ["id"] = 5534, ["name"] = "Dark Revelations", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5534, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5534, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214, ["db2QuestHubAreaPoiID"] = 7911 },
[80082] = { ["id"] = 80082, ["name"] = "Back to Gundargaz", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78555, 78557, 78631, 78634, 78635, 78636, 78637, 78638, 78639, 78640, 78641, 78642, 78837, 78838, 78839, 79205, 79267, 80082, 80434, 83550 }, ["description"] = "We may not have overthrown the Candle King, but our work here has surely relieved some of the pressure facing Gundargaz. And it's made us more than a few new allies, as well. Our new friends will not be forgotten, on my word as Speaker. There is a...regrettable amount of available housing in Gundargaz as of late. It will be nice to feel the city come to life again, and we can certainly use the manpower. Shall we bring them home, <name>?", ["objectivesText"] = "Return to Gundargaz.", ["rewardGold"] = 29200, ["rewardXP"] = 1240, ["rewardCurrencies"] = { { ["id"] = 2902, ["amount"] = 2500 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 212992, ["x"] = 0.601333, ["y"] = 0.32 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 218715, ["x"] = 0.45, ["y"] = 0.332 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.601333, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 78642 }, ["questLines"] = { { ["id"] = 5533, ["name"] = "By Candlelight", ["orderIndex"] = 18, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5533, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5533, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[80096] = { ["id"] = 80096, ["name"] = "The Shovel in the Stone", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79559, 79561, 79563, 79564, 80096, 80144, 84621, 84821 }, ["description"] = "Now, friend, we quest for blade of legend! Whoever pull from stone it stuck in destined for greatness. Only problem is that it very stuck. In very big rock. No idea how even get there, really. Come! We try you hand at fate!", ["objectivesText"] = "Recover the legendary kobold shovel Excavator . Progress: Pull with knees, not with back.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 216915 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 218878, ["x"] = 0.668, ["y"] = 0.785 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 218878, ["x"] = 0.668, ["y"] = 0.785 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.785 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79561, 84821 }, ["questLines"] = { { ["id"] = 5678, ["name"] = "The Verdigrease Knight", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[80144] = { ["id"] = 80144, ["name"] = "The Holey Grail", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79559, 79561, 79563, 79564, 80096, 80144, 84621, 84821 }, ["description"] = "Holey Grail , one of very best relics, lost for long time, <name>. Very old, very powerful. Would mean a lot if could find. Set you grand quest for to search for Holey Grail ! Try start with Fishcan . He old as dirt, might know something. Seek him by pools to north-east.", ["objectivesText"] = "Find the Holey Grail . Progress: Got Grail?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 228771 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 218878, ["x"] = 0.668, ["y"] = 0.785 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 218878, ["x"] = 0.668, ["y"] = 0.785 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.785 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79561, 84821 }, ["questLines"] = { { ["id"] = 5678, ["name"] = "The Verdigrease Knight", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[80145] = { ["id"] = 80145, ["name"] = "The Motherlode", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79022, 79023, 79024, 79025, 79026, 79027, 79028, 79029, 79030, 79217, 79324, 79325, 80145, 80517 }, ["description"] = "<Zee-Zee's internals begin to hum softly as their projector reaches the appropriate operating temperature.>", ["objectivesText"] = "Activate the remaining crushers in the Shadowvein cave. Progress: <Zee-Zee looks up at you.>", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 29813, 29814, 29815, 143559 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["npcID"] = 230643, ["x"] = 0.048, ["y"] = 0.796, ["mapID"] = 2214 } }, ["ends"] = { { ["npcID"] = 230643, ["x"] = 0.048, ["y"] = 0.796, ["mapID"] = 2214 } }, ["coords"] = { ["x"] = 0.048, ["y"] = 0.796, ["source"] = "quest_giver", ["mapID"] = 2214 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79028 }, ["questLines"] = { { ["id"] = 5531, ["name"] = "The Machines March to War", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5531, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[80175] = { ["id"] = 80175, ["name"] = "The Last Mage", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 80175, 80176, 80177, 80178, 80179 }, ["description"] = "I want you to check in on someone. He's a mage... the only one of us who is. All the others died in the crash. He's trying to make a portal to the Empire, so we can get reinforcements and have a way to and from home. We all know it's a lost cause, but he still hasn't given up. Maybe meeting a seasoned traveler like you will give him the reality check he needs. Check on him, will you?", ["objectivesText"] = "Find Wenren Althal in Beledar's Bounty.", ["rewardGold"] = 29500, ["rewardXP"] = 1275, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 215335, ["x"] = 0.405, ["y"] = 0.508 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 219135, ["x"] = 0.488, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.405, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78658 }, ["nextQuests"] = { 80176 }, ["questLines"] = { { ["id"] = 5552, ["name"] = "The Last Mage of Hallowfall", ["orderIndex"] = 0, ["flags"] = 1 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[80176] = { ["id"] = 80176, ["name"] = "Arcane Trickles", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 80175, 80176, 80177, 80178, 80179 }, ["description"] = "I've almost got it! I'm making a new kind of teleportation spell to get us back home to the Empire. These crabs might just be the key. They're practically radiating arcane teleportation magic! I need more samples to study. Take this focus, it will let you see traces of the arcane. There aren't many other arcane sources around here, so any you see should lead you straight to the affected crabs!", ["objectivesText"] = "Obtain 5 Arcane-Suffused Organs from Shore Crawlers near Mereldar. Progress: Have you found the crabs? They'll be near water. That focus should let you see the trails of arcane dust they leave behind.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["rewardItems"] = { 217269 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 219135, ["x"] = 0.488, ["y"] = 0.645 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 219135, ["x"] = 0.488, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 80175 }, ["questLines"] = { { ["id"] = 5552, ["name"] = "The Last Mage of Hallowfall", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[80177] = { ["id"] = 80177, ["name"] = "Arcane Experiments", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 80175, 80176, 80177, 80178, 80179 }, ["description"] = "This is it! The energy crackling from these crabs is charged with teleportation magic! I just need to extract it and adjust the formula-- I can do this, my new friend! I just need another hand. Help me test this?", ["objectivesText"] = "Help Wenren with his experiments.", ["rewardGold"] = 292100, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 219135, ["x"] = 0.488, ["y"] = 0.645 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 219173, ["x"] = 0.486, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 80176 }, ["questLines"] = { { ["id"] = 5552, ["name"] = "The Last Mage of Hallowfall", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[80178] = { ["id"] = 80178, ["name"] = "A Murder Most Foul", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 80175, 80176, 80177, 80178, 80179 }, ["description"] = "<Somebody didn't want Wenren to finish his spell. Find out who.>", ["objectivesText"] = "Investigate Wenren's murder. Progress: <The body is still warm.>", ["rewardGold"] = 292100, ["rewardXP"] = 10190, ["rewardItems"] = { 221190 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 219173, ["x"] = 0.486, ["y"] = 0.645 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 219173, ["x"] = 0.486, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.486, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 80177 }, ["questLines"] = { { ["id"] = 5552, ["name"] = "The Last Mage of Hallowfall", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[80179] = { ["id"] = 80179, ["name"] = "Finding Justice", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 80175, 80176, 80177, 80178, 80179 }, ["description"] = "<The pieces fit together to form a simple, but dark picture. The Order of Night did not want Wenren to create a portal back to the Empire. No doubt reinforcements and supplies would hinder their mission. So, someone stabbed him, burned his research, and smashed his tools. But with this arcane focus in hand, you can see a faint trail of arcane residue. Did some arcane dust get on the perpetrator? Follow the trail and find out.>", ["objectivesText"] = "Track down Wenren's killer.", ["rewardGold"] = 584200, ["rewardXP"] = 12740, ["rewardItems"] = { 225946 }, ["rewardCurrencies"] = { { ["id"] = 2899, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 219173, ["x"] = 0.486, ["y"] = 0.645 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 215335, ["x"] = 0.405, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.486, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 80178 }, ["questLines"] = { { ["id"] = 5552, ["name"] = "The Last Mage of Hallowfall", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[80184] = { ["id"] = 80184, ["name"] = "Preserving in Battle", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 80184 }, ["description"] = "There is much to learn on the battlefield, even in lesser coordinated environments. Go ahead and give it a try.", ["objectivesText"] = "Obtain Honor in Random Battlegrounds. Progress: You haven't finished quite yet.", ["rewardItems"] = { 2815, 2899, 3056, 244848 }, ["rewardChoices"] = { 2815, 2899, 3056, 244848 }, ["rewardCurrencies"] = { { ["id"] = 1792, ["amount"] = 500 }, { ["id"] = 1602, ["amount"] = 175 }, { ["id"] = 3100, ["amount"] = 8 } }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219260, ["x"] = 0.588, ["y"] = 0.754 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219260, ["x"] = 0.588, ["y"] = 0.754 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.754 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "pvp" },
[80185] = { ["id"] = 80185, ["name"] = "Preserving Solo", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 80185 }, ["description"] = "Battling on your own will build strength and courage. Display your solo capabilities in small battles, then return to me.", ["objectivesText"] = "Complete 12 rounds of Solo Shuffle. Progress: Finish off what you set to do then return.", ["rewardItems"] = { 2899, 244848 }, ["rewardChoices"] = { 2899, 244848 }, ["rewardCurrencies"] = { { ["id"] = 1792, ["amount"] = 500 }, { ["id"] = 1602, ["amount"] = 175 }, { ["id"] = 2815, ["amount"] = 35 }, { ["id"] = 2897, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219260, ["x"] = 0.588, ["y"] = 0.754 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219260, ["x"] = 0.588, ["y"] = 0.754 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.754 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "pvp" },
[80186] = { ["id"] = 80186, ["name"] = "Preserving in War", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 80186 }, ["description"] = "Partaking in large-scale conflicts will hone your ability to look at the larger picture. Go off and garner that experience, then come back to see me.", ["objectivesText"] = "Obtain Honor in Epic Battlegrounds. Progress: Complete what you have set off to do.", ["rewardItems"] = { 2815, 2899, 3056, 244848 }, ["rewardChoices"] = { 2815, 2899, 3056, 244848 }, ["rewardCurrencies"] = { { ["id"] = 1792, ["amount"] = 500 }, { ["id"] = 1602, ["amount"] = 175 }, { ["id"] = 2815, ["amount"] = 35 }, { ["id"] = 2897, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219260, ["x"] = 0.588, ["y"] = 0.754 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219260, ["x"] = 0.588, ["y"] = 0.754 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.754 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "pvp" },
[80187] = { ["id"] = 80187, ["name"] = "Preserving in Skirmishes", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 80187 }, ["description"] = "Part of training is repetition. I am told there are others out there like yourself that partake in small-scale skirmishes. Go off and find training partners to battle against, then return to me. Let us see what you can prove, then return to me.", ["objectivesText"] = "Obtain Honor from Arena Skirmishes. Progress: Practice makes perfect. Finish off the tasks then return.", ["rewardItems"] = { 2899, 244848 }, ["rewardChoices"] = { 2899, 244848 }, ["rewardCurrencies"] = { { ["id"] = 1792, ["amount"] = 350 }, { ["id"] = 1602, ["amount"] = 125 }, { ["id"] = 2815, ["amount"] = 35 }, { ["id"] = 2897, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219260, ["x"] = 0.588, ["y"] = 0.754 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219260, ["x"] = 0.588, ["y"] = 0.754 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.754 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "pvp" },
[80188] = { ["id"] = 80188, ["name"] = "Preserving in Arenas", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 80188 }, ["description"] = "Fast paced and coordinated combat is a mighty test for the strongest combatants. Find others to battle alongside you to fight worthy opponents in the arena.", ["objectivesText"] = "Obtain Honor in Rated Arenas while in a Party. Progress: You have not finished what you set off to do yet.", ["rewardItems"] = { 2815, 2899, 3056, 244848 }, ["rewardChoices"] = { 2815, 2899, 3056, 244848 }, ["rewardCurrencies"] = { { ["id"] = 1792, ["amount"] = 500 }, { ["id"] = 1602, ["amount"] = 175 }, { ["id"] = 3100, ["amount"] = 1 } }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219260, ["x"] = 0.588, ["y"] = 0.754 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219260, ["x"] = 0.588, ["y"] = 0.754 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.754 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "pvp" },
[80189] = { ["id"] = 80189, ["name"] = "Preserving Teamwork", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 80189 }, ["description"] = "The ability to strategize with others to take objectives is key to becoming a strong warrior. Go onto the battlefield, then return to me.", ["objectivesText"] = "Obtain Honor in Rated Battleground Blitz or in Rated Battlegrounds. Progress: Finish off what you set to do then come back.", ["rewardItems"] = { 2815, 2899, 3056, 244848 }, ["rewardChoices"] = { 2815, 2899, 3056, 244848 }, ["rewardCurrencies"] = { { ["id"] = 1792, ["amount"] = 750 }, { ["id"] = 1602, ["amount"] = 175 }, { ["id"] = 3100, ["amount"] = 15 } }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219260, ["x"] = 0.588, ["y"] = 0.754 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219260, ["x"] = 0.588, ["y"] = 0.754 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.754 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "pvp" },
[80196] = { ["id"] = 80196, ["name"] = "Extract a Gem", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = { "campaign" }, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 80196 }, ["series"] = { 79489, 80197 }, ["description"] = "Any gem can be removed from your equipment using the Extract Gem ability. The gem will not be destroyed. Extract a gem now.", ["objectivesText"] = "Extract the Chipped Deadly Sapphire from your equipment.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 210714 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["sourceQuests"] = { 79489 } },
[80197] = { ["id"] = 80197, ["name"] = "Combine Gems", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = { "campaign" }, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 80197 }, ["series"] = { 79489, 80196 }, ["description"] = "Prismatic gems can be combined to create a more powerful gem. Combine three Deadly Chipped Sapphires to create a Flawed Deadly Sapphire that grants additional Critical Strike when socketed.", ["objectivesText"] = "Use three Deadly Chipped Sapphires to combine them into a Flawed Deadly Sapphire.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["sourceQuests"] = { 80196 } },
[80202] = { ["id"] = 80202, ["name"] = "Hot Pollenate-o", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2248, ["storyline"] = { 79504, 79505, 79507, 79508, 79510, 79552, 79554, 79555, 79556, 79565, 79680, 79681, 79682, 79683, 79998, 80000, 80058, 80202, 80378, 81999 }, ["description"] = "Important to make sure not take too much. Make sure hive healthy so can come back. Bees eat pollen, yes? So fire bees eat fire pollen? Yes. Bring fire pollen to bees. Grow strong. Bee productive. Check edge of hive for flowers bees not get to yet. When catch fire, you got good one.", ["objectivesText"] = "Gather pollen from Pollen Rich Cinderblooms and return it to nearby bees before it goes out. Progress: Just a little bit on fire. You tough, you be okay.", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 219674, ["x"] = 0.72, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 219674, ["x"] = 0.72, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.72, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 79552, 79998 }, ["questLines"] = { { ["id"] = 5627, ["name"] = "Kobold Culture and Integration", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[80203] = { ["id"] = 80203, ["name"] = "Social Clues", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2213, ["storyline"] = { 80203, 80204, 80205, 80206 }, ["description"] = "<The nerubian keeps her voice low, a careful eye on the guards behind you.> The Weaver sent you, yes? I arrived to petition the Magistrate's approval for Ascension--to infiltrate high society, of course. But he's missing. A rather large inconvenience. I need to ask around. You're just what I've been waiting for! You may pretend to be my... servant. Pet? Whatever makes it more palatable to you. I so rarely get to work alongside a friend. We will have fun together, fellow spy.", ["objectivesText"] = "Help Orator Tx'itk ask around to find the Magistrate. Progress: I have a few old friends who recently Ascended. Surely, one of them has heard something they would be willing to share. For old time's sake. And if not, maybe jealousy in seeing my fashionable new pet will inspire them to offer up what they know.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 219357, ["x"] = 0.715, ["y"] = 0.4445 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 221092, ["x"] = 0.664, ["y"] = 0.361 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.715, ["y"] = 0.4445 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["sourceQuests"] = { 78384 }, ["questLines"] = { { ["id"] = 5613, ["name"] = "Pawns and Puppetry", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2213 },
[80204] = { ["id"] = 80204, ["name"] = "Espionage and Ventriloquism", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2213, ["storyline"] = { 80203, 80204, 80205, 80206 }, ["description"] = "The Puppetmaster is our best lead for finding the Magistrate. But is it just me, or did those puppets seem... horrifically lifelike? If this artist is behind the Magistrate's disappearance, he certainly isn't just off to see a puppet show. We should investigate the Puppetmaster's workshop. Question him, or at least ransack his things. Just a bit. Until we find something useful. You'll have to keep playing your rather undignified role in this charade. But it will pay off for us.", ["objectivesText"] = "Investigate the Puppetmaster's Workshop. Progress: < Orator Tx'itk lowers her voice.> Something isn't right here. Play along just a while longer. Let's see what else we can find.", ["rewardGold"] = 292100, ["rewardXP"] = 10595, ["rewardItems"] = { 219443 }, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 221092, ["x"] = 0.664, ["y"] = 0.361 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 221093, ["x"] = 0.656, ["y"] = 0.417333 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.361 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["sourceQuests"] = { 80203 }, ["questLines"] = { { ["id"] = 5613, ["name"] = "Pawns and Puppetry", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2213 },
[80205] = { ["id"] = 80205, ["name"] = "Pulling Strings", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2213, ["storyline"] = { 80203, 80204, 80205, 80206 }, ["description"] = "Just think of it! Overcrawlers, war prisoners, civilians, fellow nerubians, important nobility being kidnapped and turned into puppets right under the Magistrate's nose. It's horrific--and exactly what I needed! If we save the Magistrate from this fate, he'll owe me. Not just for saving his life, but to keep quiet about all this. We're off to the theater, then. If you can keep the Puppetmaster occupied, I'll free High Elevator Etak'kaht from his grasp. Hopefully he's not part of the show yet.", ["objectivesText"] = "Confront the Puppetmaster to rescue High Elevator Etak'kaht .", ["rewardGold"] = 292100, ["rewardXP"] = 10595, ["rewardCurrencies"] = { { ["id"] = 3004, ["amount"] = 500 }, { ["id"] = 3056, ["amount"] = 250 }, { ["id"] = 3056, ["amount"] = 285 } }, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 221093, ["x"] = 0.656, ["y"] = 0.417333 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 221088, ["x"] = 0.715, ["y"] = 0.455 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.656, ["y"] = 0.417333 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["sourceQuests"] = { 80206 }, ["questLines"] = { { ["id"] = 5613, ["name"] = "Pawns and Puppetry", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2213 },
[80206] = { ["id"] = 80206, ["name"] = "Marionette Mercy", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2213, ["storyline"] = { 80203, 80204, 80205, 80206 }, ["description"] = "It's perfect! The Puppetmaster is so interested in adding you to his collection, he literally invited us to go rescue the Magistrate. I don't want to imply I've been using you as bait this entire time, but... Let's just say certain calculated risks have paid off. Even such a skilled artist must have a way to correct potential errors. There has to be an antitoxin of sorts for that paralytic around here somewhere! Find it. And perhaps we test it before we go use it on the Magistrate. Just in case.", ["objectivesText"] = "Find the Puppetmaster's Antiparalytic Serum . Progress: I would worry we're taking too long, but considering how dramatic that Puppetmaster is, I can't imagine he'll start the show without us. We should be prepared for something... rather unpleasant at that theater.", ["rewardGold"] = 292100, ["rewardXP"] = 10595, ["rewardItems"] = { 219385 }, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 221093, ["x"] = 0.656, ["y"] = 0.417333 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 221093, ["x"] = 0.656, ["y"] = 0.417333 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.656, ["y"] = 0.417333 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["sourceQuests"] = { 80204 }, ["questLines"] = { { ["id"] = 5613, ["name"] = "Pawns and Puppetry", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2213 },
[80207] = { ["id"] = 80207, ["name"] = "How Scandalous!", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 79176, 79521, 79522, 79523, 79525, 79526, 79527, 79528, 79529, 79530, 79542, 79543, 79544, 79545, 79546, 80207 }, ["description"] = "Did you see anything? I was just at the Forgegrounds picking up a jewelry commission and all of a sudden everyone was shouting like the Coreway was under attack--again. But it was not that... Some peacekeepers were heading towards the depot--where crafting shipments are sent up from the Deeps. I bet it's something to do with the machine speakers! The peacekeepers ushered everyone away before I could see what had happened. But maybe you can sneak a glimpse?", ["objectivesText"] = "Investigate the disturbance near the Forgegrounds in Dornogal .", ["rewardGold"] = 30900, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219393, ["x"] = 0.625, ["y"] = 0.218 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219394, ["x"] = 0.498, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.625, ["y"] = 0.218 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 78536 }, ["questLines"] = { { ["id"] = 5605, ["name"] = "Merrix and Steelvein", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[80208] = { ["id"] = 80208, ["name"] = "Digging into Trouble", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80208, 80323, 81656, 81691, 81750, 81767, 82238, 82244, 82256, 82518, 82519, 82523, 82552, 82580, 83028, 83048, 83079, 83080, 83101, 83229, 83537, 83538, 83715, 83930, 84429 }, ["objectivesText"] = "Subdue Moles or Kill Players Subdue Moles", ["rewardXP"] = 11765, ["rewardItems"] = { 223802 }, ["starts"] = { { ["x"] = 0.575, ["y"] = 0.82, ["mapID"] = 2214 } }, ["ends"] = { { ["x"] = 0.575, ["y"] = 0.82, ["mapID"] = 2214 } }, ["coords"] = { ["mapID"] = 2214, ["x"] = 0.575, ["y"] = 0.82 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14795 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5588, ["name"] = "Ringing Deeps - World Quests / Repeatable", ["orderIndex"] = 11, ["flags"] = 0 } }, ["db2Objectives"] = { { ["text"] = "Subdue Moles or Kill Players", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Subdue Moles", ["amount"] = 10, ["type"] = 0, ["objectID"] = 219424, ["orderIndex"] = 2 } }, ["db2LabelIDs"] = { 3302 }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214, ["db2QuestInfoID"] = 113, ["db2QuestInfoName"] = "PvP World Quest" },
[80209] = { ["id"] = 80209, ["name"] = "An Oddball in Dornogal", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 80209, 80210, 80211, 80212, 80213, 80214, 80215, 80216, 80217, 80218, 80456, 83181 }, ["series"] = { 80456 }, ["description"] = "We have received reports that an eccentric Arathi is accosting our citizens. We have little experience with outsiders and my superiors are wary of a diplomatic incident. I have been tasked with finding this \"Lamplighter\" and resolving his concerns. You have worked with the Arathi before - can you assist me? I have a list of earthen who have reported the Lamplighter. You can interview half the list. Between us, we can hopefully locate the Arathi before he troubles more citizens.", ["objectivesText"] = "Interview Concerned Dornogal Citizens to locate the Arathi Lamplighter.", ["rewardGold"] = 154900, ["rewardXP"] = 4760, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 222224, ["x"] = 0.544, ["y"] = 0.195 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 222268, ["x"] = 0.664667, ["y"] = 0.178667 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.195 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 80456 }, ["questLines"] = { { ["id"] = 5571, ["name"] = "Brotherhood in the Skolzgal Wood", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[80210] = { ["id"] = 80210, ["name"] = "Found Around the Unbound", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 80209, 80210, 80211, 80212, 80213, 80214, 80215, 80216, 80217, 80218, 80456, 83181 }, ["description"] = "This Lamplighter is looking for his fellow Arathi. The foreman says he directed an Arathi shipwright to Freywold Village. My superiors insist that Peacekeepers do not leave Dornogal... but per their orders, I must assist Kaerter. And to do that, I have no choice but to leave the city. <Leif quickly hides a smile.> It is decided then. If you are willing, please meet us at Freywold Village. Your continued aid would be appreciated.", ["objectivesText"] = "Meet Peacekeeper Leif outside Freywold Village.", ["rewardGold"] = 30900, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 222268, ["x"] = 0.664667, ["y"] = 0.178667 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 222314, ["x"] = 0.426, ["y"] = 0.71 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.664667, ["y"] = 0.178667 }, ["mapCandidates"] = { ["npc"] = { 2248, 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 80209 }, ["questLines"] = { { ["id"] = 5571, ["name"] = "Brotherhood in the Skolzgal Wood", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[80211] = { ["id"] = 80211, ["name"] = "The Pillage of Freywold Village", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 80209, 80210, 80211, 80212, 80213, 80214, 80215, 80216, 80217, 80218, 80456, 83181 }, ["description"] = "The Arathi shipwright was here but has moved on with most of her entourage. She had left a few Arathi behind but... Soon after the shipwright left, earthen started disappearing. The villagers suspected the Arathi but had no proof. Then one day, the remaining Arathi left town in the middle of the night. The locals said the Arathi stayed at the inn. Can you look there for any clues as to where the Arathi are now? Given the villagers' hostility, the Lamplighter and I shall remain here for the moment.", ["objectivesText"] = "Search for clues as to where the Arathi went. Progress: I am attempting to convince the villagers that the Lamplighter is not involved in these disappearances. Did you find anything useful?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 222314, ["x"] = 0.426, ["y"] = 0.71 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 222314, ["x"] = 0.426, ["y"] = 0.71 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.71 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 80210 }, ["questLines"] = { { ["id"] = 5571, ["name"] = "Brotherhood in the Skolzgal Wood", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[80212] = { ["id"] = 80212, ["name"] = "The Abductors' Obstructors", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 80209, 80210, 80211, 80212, 80213, 80214, 80215, 80216, 80217, 80218, 80456, 83181 }, ["description"] = "The Order of Night is clearly interested in our resources. They have abducted earthen to harvest for them and may continue taking others. We must stop them. The next largest earthen settlement is Rambleshire. If the Order needs more workers, they might have gone there to get them. Go on ahead <name>. I must first speak with Kaerter about why the Arathi are doing this.", ["objectivesText"] = "Meet Peacekeeper Leif at Rambleshire.", ["rewardGold"] = 29200, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 222314, ["x"] = 0.426, ["y"] = 0.71 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 222353, ["x"] = 0.575, ["y"] = 0.3 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.71 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 80211 }, ["questLines"] = { { ["id"] = 5571, ["name"] = "Brotherhood in the Skolzgal Wood", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[80213] = { ["id"] = 80213, ["name"] = "Holy Fire in Rambleshire", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 80209, 80210, 80211, 80212, 80213, 80214, 80215, 80216, 80217, 80218, 80456, 83181 }, ["description"] = "I'm certain there are still Order folks sneaking around here. Now they might be carrying messages on them, just like the clues you found in Freywold. You and I are gonna find out. Here, take these thuribles. They might look like tiny incense burners, but I've enchanted them with Sacred Flame. Just throw one down and you'll get a big bang with a bright flash! Should be enough to stun anyone sneaking around. Just don't throw one at me! Got it?", ["objectivesText"] = "Use Flashfire Thuribles to reveal Order of Night forces in Rambleshire, eliminate them, and search them for clues. Progress: Alright, I'll admit it, the little Pebble is pretty useful. He knows more about the earthen and the surface than I ever will. Anyway, did you find anything?", ["rewardGold"] = 292100, ["rewardXP"] = 9515, ["rewardItems"] = { 224104, 224118 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 222352, ["x"] = 0.575, ["y"] = 0.3 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 222356, ["x"] = 0.62, ["y"] = 0.306 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.575, ["y"] = 0.3 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 80212 }, ["questLines"] = { { ["id"] = 5571, ["name"] = "Brotherhood in the Skolzgal Wood", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[80214] = { ["id"] = 80214, ["name"] = "A Time to Kill at the Lumber Mill", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 80209, 80210, 80211, 80212, 80213, 80214, 80215, 80216, 80217, 80218, 80456, 83181 }, ["description"] = "Alright, let me see if I get all of this. The shipwright brings an entourage up here to get lumber for airships. But the shipwright is actually Order of Night, along with most of her group. So they murder the loyal Arathi, kidnap earthen, and force them to run the lumber mill up here. And now we gotta deal with the Order AND whoever their new friends are. <Kaerter swears and shakes his head.> C'mon, let's head to the mill. We got a lot of bad guys to kill and time's wastin'.", ["objectivesText"] = "Meet Lamplighter Kaerter outside of Skolzgal Mill.", ["rewardGold"] = 29200, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 222356, ["x"] = 0.62, ["y"] = 0.306 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 222360, ["x"] = 0.67, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 80213 }, ["questLines"] = { { ["id"] = 5571, ["name"] = "Brotherhood in the Skolzgal Wood", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[80215] = { ["id"] = 80215, ["name"] = "Ungirthin' the Earthen", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 80209, 80210, 80211, 80212, 80213, 80214, 80215, 80216, 80217, 80218, 80456, 83181 }, ["description"] = "While I do enjoy beating the black blood out of nerubians, we must save the earthen prisoners first. I saw they're being held by Arathi ball and chain. Someone like you should be able to shatter them pretty quick. Just... do that thing you do! Oh, and we should split up to cover more ground. Yeah Leif's gonna complain, but he's always complaining anyway.", ["objectivesText"] = "Free 8 Abducted Lumberjacks.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 222360, ["x"] = 0.67, ["y"] = 0.312 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 222360, ["x"] = 0.67, ["y"] = 0.312 }, { ["mapID"] = 2248, ["npcID"] = 222362, ["x"] = 0.658, ["y"] = 0.246 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 80214 }, ["questLines"] = { { ["id"] = 5571, ["name"] = "Brotherhood in the Skolzgal Wood", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[80216] = { ["id"] = 80216, ["name"] = "Concealed in the Weald", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 80209, 80210, 80211, 80212, 80213, 80214, 80215, 80216, 80217, 80218, 80456, 83181 }, ["description"] = "The nerubians seem to be in league with the Arathi. Many of them are guarding the mill, but I am sure there are more than we can see. We cannot allow such a large enemy force to operate unimpeded this close to Rambleshire. The nerubians attacked and destroyed large sections of Dornogal not too long ago. The Order of Night Arathi are abducting and enslaving our people. We must eliminate as many of them as we can. Preferably all of them.", ["objectivesText"] = "Eliminate Shadowsilk forces at the Skolzgal Mill. Progress: The more enemies we eliminate, the safer we will all be.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 222358, ["x"] = 0.67, ["y"] = 0.312 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 222362, ["x"] = 0.658, ["y"] = 0.246 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 80214 }, ["questLines"] = { { ["id"] = 5571, ["name"] = "Brotherhood in the Skolzgal Wood", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[80217] = { ["id"] = 80217, ["name"] = "A Lamplight for the Shipwright", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 80209, 80210, 80211, 80212, 80213, 80214, 80215, 80216, 80217, 80218, 80456, 83181 }, ["description"] = "Where is Kaerter now? Did he go off on his own again? <Leif sighs.> We've rescued the earthen and eliminated many hostile forces, but our task is not yet complete. Shortly before you arrived, we spotted a group of Arathi traveling up this hill. One of them was identified as the Arathi shipwright. The shipwright is the leader here. Losing her will cripple their efforts to utilize the mill. Head up the hill and find her before she can escape.", ["objectivesText"] = "Confront the Arathi shipwright.", ["rewardGold"] = 154900, ["rewardXP"] = 4760, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 222362, ["x"] = 0.658, ["y"] = 0.246 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 222363, ["x"] = 0.66, ["y"] = 0.238 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.246 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 80215, 80216 }, ["questLines"] = { { ["id"] = 5571, ["name"] = "Brotherhood in the Skolzgal Wood", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[80218] = { ["id"] = 80218, ["name"] = "Up to No Good Down in Silkwood", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 80209, 80210, 80211, 80212, 80213, 80214, 80215, 80216, 80217, 80218, 80456, 83181 }, ["description"] = "The Order is moving the wood through the nerubians. Leif said he saw the shipwright leave the cave and head down to the beach. The nerubian tunnel must be down there. You're going to have to seal that Flameforsaken passage. While slinking around, I noticed the Order brought explosive barrels with them. Find a few and use them to blow the tunnel. Get going <name>. I'll be right behind you.", ["objectivesText"] = "Collect Silkwood Explosive Barrels, then destroy the nerubian tunnel at Silkwood Grotto. Progress: Did you take out the tunnel?", ["rewardGold"] = 619600, ["rewardXP"] = 11895, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 222364, ["x"] = 0.66, ["y"] = 0.238 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 222365, ["x"] = 0.655, ["y"] = 0.205 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.238 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 80217 }, ["questLines"] = { { ["id"] = 5571, ["name"] = "Brotherhood in the Skolzgal Wood", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
