[80310] = { ["id"] = 80310, ["name"] = "Setting Sun Garrison", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 5840, ["mapID"] = 390, ["storyline"] = { 80310 }, ["description"] = "Might you be willing to find Anji at the Setting Sun Garrison to the west? She's been tasked with preparing fresh-faced pandaren to aid the cause. You could show them a thing or two as well, I imagine.", ["objectivesText"] = "Speak to Anji Autumnlight at the Setting Sun Garrison.", ["rewardGold"] = 140450, ["rewardXP"] = 2060, ["starts"] = { { ["mapID"] = 390, ["npcID"] = 64007, ["x"] = 0.63, ["y"] = 0.222 }, { ["mapID"] = 390, ["npcID"] = 64031, ["x"] = 0.847333, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 390, ["npcID"] = 58919, ["x"] = 0.214667, ["y"] = 0.715333 } }, ["coords"] = { ["mapID"] = 390, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.222 }, ["mapCandidates"] = { ["npc"] = { 390 }, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[80311] = { ["id"] = 80311, ["name"] = "Order of the Cloud Serpent", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 30134, 30135, 30136, 30137, 30138, 30139, 30140, 30141, 30142, 30143, 30144, 30145, 30187, 30188, 31810, 31811, 80311 }, ["series"] = { 30134, 30135 }, ["description"] = "Widing toortles is da best! But widing cloud serpents is even better! There's some peepos at da Arboweetum who wide cloud serpents and can teach you how!", ["objectivesText"] = "Speak to Elder Anli at The Arboretum.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 223907 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 63900, ["x"] = 0.49, ["y"] = 0.458 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 58564, ["x"] = 0.576, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.458 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["nextQuests"] = { 30134 }, ["questLines"] = { { ["id"] = 5549, ["name"] = "Order of the Cloud Serpent", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371 },
[80312] = { ["id"] = 80312, ["name"] = "Gasping Plea", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 80312, 80313, 80314, 80315, 80316, 81797 }, ["description"] = "<A gasping, pathetic-looking fish taken from the corpse of a kobyss flops weakly in your hand. Its beady eye twitches, and you suddenly hear a breathless voice in the recesses of your mind.> The water. Take me to the water. Away from these kobyss wretches. Away from the sky.", ["objectivesText"] = "Put the strange fish in safe waters near the kobyss camp at Sunless Strand.", ["rewardGold"] = 30900, ["rewardXP"] = 1275, ["rewardItems"] = { 217352, 222964 }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 219430, ["x"] = 0.552667, ["y"] = 0.198 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.552667, ["y"] = 0.198 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 81797 }, ["questLines"] = { { ["id"] = 5602, ["name"] = "Crushing Depths", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215, ["startItems"] = { 217352 } },
[80313] = { ["id"] = 80313, ["name"] = "Tidal Charms", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 80312, 80313, 80314, 80315, 80316, 81797 }, ["description"] = "<When the fish speaks, its lips do not move. You hear its voice in your head.> No doubt you have found that your senses cannot be trusted when dealing with the kobyss. A tremendous power, is it not? It is only fair that you show them the power they wield is not theirs alone. I will show you how to craft a tool to lure and destroy them. You will find their kind carry shards taken from the deep. Bring them to me.", ["objectivesText"] = "Collect 12 Sunless Shards from the kobyss at Sunless Strand. Progress: Bring the materials. Only then can we continue.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["rewardItems"] = { 217352, 217709, 222964 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 219430, ["x"] = 0.552667, ["y"] = 0.198 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 219430, ["x"] = 0.552667, ["y"] = 0.198 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.552667, ["y"] = 0.198 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 80312 }, ["questLines"] = { { ["id"] = 5602, ["name"] = "Crushing Depths", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[80314] = { ["id"] = 80314, ["name"] = "Voices from the Deep", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 80312, 80313, 80314, 80315, 80316, 81797 }, ["description"] = "To deceive the senses of these kobyss is one matter. To know what will captivate them is another. They champ and drool at the thought of devouring your kind. But it is the voices of the deep that transfix them and lower their guard. It's then that you will strike. Search their shrines to gain an insight for what these wretches hold sacred. See how they have twisted the bellowing truths that lie below.", ["objectivesText"] = "Study three ritual sites for insights on the kobyss. Progress: What have you learned?", ["rewardGold"] = 292100, ["rewardXP"] = 10190, ["rewardItems"] = { 217352, 222964 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 219430, ["x"] = 0.552667, ["y"] = 0.198 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 219430, ["x"] = 0.552667, ["y"] = 0.198 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.552667, ["y"] = 0.198 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 80312 }, ["questLines"] = { { ["id"] = 5602, ["name"] = "Crushing Depths", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[80315] = { ["id"] = 80315, ["name"] = "Alluring Offer", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 80312, 80313, 80314, 80315, 80316, 81797 }, ["description"] = "It is done. Take this tidal charm, cloak your form in the darkness of the sea, and unmake the kobyss. Their strongest warriors gather and scheme against your kind upon that central island. With the lure, they will not see you for what you are. Use that advantage to become their end. But understand, as the kobyss fail to, this is a power you borrow. It belongs to the sea.", ["objectivesText"] = "Lure and assassinate Gillcarver and his Kobyss Tidemarshals on the island off the Sunless Strand. Progress: Isolate them. Destroy them.", ["rewardGold"] = 619600, ["rewardXP"] = 12740, ["rewardItems"] = { 217352, 222964 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 219430, ["x"] = 0.552667, ["y"] = 0.198 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 219430, ["x"] = 0.552667, ["y"] = 0.198 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.552667, ["y"] = 0.198 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 80313, 80314 }, ["questLines"] = { { ["id"] = 5602, ["name"] = "Crushing Depths", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[80316] = { ["id"] = 80316, ["name"] = "Return to the Sea", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 80312, 80313, 80314, 80315, 80316, 81797 }, ["description"] = "I remain weakened by my time so near the searing Light of the surface. I ask that you take me to deeper waters, away from these kobyss, where I can return to my kind.", ["objectivesText"] = "Take the Peculiar Fish to deeper waters.", ["rewardGold"] = 232300, ["rewardXP"] = 7645, ["rewardItems"] = { 217352, 222964 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 25 }, { ["id"] = 2899, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 219430, ["x"] = 0.552667, ["y"] = 0.198 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 219430, ["x"] = 0.552667, ["y"] = 0.198 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.552667, ["y"] = 0.198 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 80315 }, ["questLines"] = { { ["id"] = 5602, ["name"] = "Crushing Depths", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
