[80334] = { ["id"] = 80334, ["name"] = "Shattered Spires", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78529, 78530, 78531, 78532, 78533, 78534, 78535, 78536, 80334, 83548 }, ["series"] = { 78532 }, ["description"] = "With nothing to contain their arcane power, Dalaran's spires are crumbling. If we let their energies continue to bleed out unchecked, that power could destabilize and destroy what is left of our forces. Find Aethas! He will know what to do.", ["objectivesText"] = "Find Aethas at the Tranquil Strand.", ["rewardGold"] = 30900, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 211994, ["x"] = 0.294, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 223166, ["x"] = 0.308, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.294, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78530, 78531 }, ["questLines"] = { { ["id"] = 5539, ["name"] = "Breaking Point", ["orderIndex"] = 4, ["flags"] = 1 }, { ["id"] = 6008, ["name"] = "Catch Up: War Within: Wrapper 2", ["orderIndex"] = 8, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5539, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5539, ["questLineOrder"] = 2 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6008, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[80349] = { ["id"] = 80349, ["name"] = "Time to Return", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster", "important" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 80349 }, ["series"] = { 80018 }, ["description"] = "You'd best be on your way now. That portal should take you back to the village.", ["objectivesText"] = "Return to Moratari .", ["starts"] = { { ["mapID"] = 371, ["npcID"] = 218469, ["x"] = 0.652, ["y"] = 0.372 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 218468, ["x"] = 0.342667, ["y"] = 0.375333 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["sourceQuests"] = { 80018 } },
[80378] = { ["id"] = 80378, ["name"] = "A Light of the Dark", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79504, 79505, 79507, 79508, 79510, 79552, 79554, 79555, 79556, 79565, 79680, 79681, 79682, 79683, 79998, 80000, 80058, 80202, 80378, 81999 }, ["description"] = "The image of a purple candle, burning with glorious power springs unbidden to your mind as you contemplate the decaying filth before you, followed by a faint whisper echoing through your mind: \"One candle to rule them all, and in its brightness bind them.\" Bring Janky the candlesmith in Gundargaz enough Coagulated Black Blood to forge a most unfortunate candle.", ["objectivesText"] = "Collect Coagulated Black Blood and bring it to Janky the kobold candlesmith in Gundargaz. Progress: < Janky shivers as you approach.> Ah!", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["rewardItems"] = { 44018, 44039, 44041, 44042, 44043, 217390, 217391, 220161, 221776, 223472, 257143, 265106, 265631 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 25 }, { ["id"] = 2902, ["amount"] = 500 } }, ["starts"] = { { ["x"] = 0.648, ["y"] = 0.808, ["mapID"] = 2255 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 216598, ["x"] = 0.455, ["y"] = 0.332 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.332 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5627, ["name"] = "Kobold Culture and Integration", ["orderIndex"] = 13, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[80382] = { ["id"] = 80382, ["name"] = "Eggs in One Basket", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 80382 }, ["description"] = "<This work order remains unfilled. Aliya Hillhelm would be quite happy if you helped complete the order.>", ["objectivesText"] = "Collect 10 Hillhelm Eggs to place in this basket. Progress: Inform Aliya that the work order is complete.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 206350, 217396 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 40 }, { ["id"] = 2899, ["amount"] = 200 }, { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.608, ["y"] = 0.279, ["mapID"] = 2215, ["objectID"] = 430581 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 206528, ["x"] = 0.612, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78658, 79573 } },
[80384] = { ["id"] = 80384, ["name"] = "A Keg-Stamped Package", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 80384 }, ["description"] = "<A note, attached to a small and crumpled package, is shoved into your hands by a nondescript figure. Just as quickly, they disappear into the crowd. The letters on the note are scrawled crudely, as if by a dagger dipped in ink.> Here's yer share of the plunder. Sent the mates to the inn. <You look around to see if there is anything else on the note. There is a picture of a keg at the bottom. You shake the package gently and hear the telltale sound of coins.>", ["objectivesText"] = "Bring the Keg-Stamped Note to Da'kash Grimledger at the Roasted Ram Inn in Valdrakken .", ["rewardGold"] = 289300, ["rewardXP"] = 9515, ["rewardItems"] = { 217397 }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 219760, ["x"] = 0.466, ["y"] = 0.455333 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.455333 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[80385] = { ["id"] = 80385, ["name"] = "Last Hurrah: Dragon Isles", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70750, 71232, 72068, 72373, 72374, 72375, 72585, 75259, 75859, 75860, 75861, 77254, 77976, 78446, 78447, 78861, 80385, 80386, 80388, 80389 }, ["description"] = "You've become quite popular with our allies, <name>! To the south the Iskaara Tuskarr need your help with their community feast. To the west the Maruuks have requested your aid with their hunts. To the north the Obsidian Outcasts request your help reclaiming Dragonbane Keep. Sounds like you have a full day ahead of you! Best of luck.", ["objectivesText"] = "Assist the Tuskarr with their community feast, the Maruuk with their Hunt, and help reclaim Dragonbane Keep. Progress: We're lucky to have you on our side, <name>.", ["rewardItems"] = { 217109 }, ["starts"] = { { ["x"] = 0.507, ["y"] = 0.58, ["mapID"] = 2112, ["npcID"] = 196499 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.5605 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questGiverID"] = 196499, ["questType"] = "standard", ["sourceQuests"] = { 71232, 72366 }, ["questLines"] = { { ["id"] = 1367, ["name"] = "Dragon Isles Emissary", ["orderIndex"] = 16, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 201, ["title"] = "Dragonflight", ["questLineID"] = 1367, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 3342 }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
[80386] = { ["id"] = 80386, ["name"] = "Last Hurrah: Zaralek Caverns and Time Rifts", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70750, 71232, 72068, 72373, 72374, 72375, 72585, 75259, 75859, 75860, 75861, 77254, 77976, 78446, 78447, 78861, 80385, 80386, 80388, 80389 }, ["description"] = "Our allies are once again requesting your aid, <name>. In the Zaralek caverns the Dragonscale Expedition needs you to protect their researchers. We're also concerned with the Zaqali invasions in the Ohn'ahran Plains and Azure Span. Meanwhile, the Bronze Dragonflight has asked for you to help them deal with temporal anomalies to the east of Valdrakken . Hurry <name>, time is of the essence.", ["objectivesText"] = "Protect the Researchers under Fire, loot a Secured Shipment from a Suffusion Camp, and assist Soridormi in dispelling a Time Rift. Progress: Do you bring news of your success?", ["rewardItems"] = { 213089, 217110 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.5605 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 71232, 72366 }, ["questLines"] = { { ["id"] = 1367, ["name"] = "Dragon Isles Emissary", ["orderIndex"] = 17, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 201, ["title"] = "Dragonflight", ["questLineID"] = 1367, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 3342 }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
[80388] = { ["id"] = 80388, ["name"] = "Last Hurrah: Emerald Dream", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70750, 71232, 72068, 72373, 72374, 72375, 72585, 75259, 75859, 75860, 75861, 77254, 77976, 78446, 78447, 78861, 80385, 80386, 80388, 80389 }, ["description"] = "The druids call for aid! Energy from the Emerald Dream is spreading across the Dragon Isles, please help them investigate it. They also ask you travel to the Emerald Dream and assist Sprucecrown in creating a Superbloom. Some of the druids also wish for you to plant Dreamseeds in the Emerald Dream. Please help them, <name>.", ["objectivesText"] = "Gather one hundred Dreamsurge Coalescence across the Dragon isles, assist Sprucecrown in creating a Superbloom, and plant 3 Dreamseeds of any quality in the Emerald Dream. Dreamseeds can be acquired from most activities in the Emerald Dream. Progress: How are the druids doing?", ["rewardItems"] = { 207026, 217111 }, ["starts"] = { { ["x"] = 0.507, ["y"] = 0.58, ["mapID"] = 2112, ["npcID"] = 196499 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.5605 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questGiverID"] = 196499, ["questType"] = "standard", ["sourceQuests"] = { 71232, 72366 }, ["questLines"] = { { ["id"] = 1367, ["name"] = "Dragon Isles Emissary", ["orderIndex"] = 18, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 201, ["title"] = "Dragonflight", ["questLineID"] = 1367, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 3342 }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
[80389] = { ["id"] = 80389, ["name"] = "Last Hurrah", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = { "campaign" }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 70750, 71232, 72068, 72373, 72374, 72375, 72585, 75259, 75859, 75860, 75861, 77254, 77976, 78446, 78447, 78861, 80385, 80386, 80388, 80389 }, ["rewardItems"] = { 217109, 217110, 217111 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13862 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1367, ["name"] = "Dragon Isles Emissary", ["orderIndex"] = 19, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 201, ["title"] = "Dragonflight", ["questLineID"] = 1367, ["questLineOrder"] = 0 } } },
[80392] = { ["id"] = 80392, ["name"] = "The Caretaker of Brunwin's Terrace", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80392, 80401, 80402, 80404, 80405, 80406, 80407, 80408, 80689 }, ["description"] = "Greetings, outlander. You must be the problem solver I've heard about! I'm Caretaker Batzvara . I tend to earthen who have gone into stasis, like our friend here. I often patrol Brunwin's Terrace to honor my fellow earthen with an offering of cinderbrew. Recently, however, I've drawn the attention of a local species of moles. They have a nose for sweets, and greedy claws for all else. You look like you can defend yourself. Will you accompany me to pay respect to those who have gone into stasis?", ["objectivesText"] = "Offer cinderbrew to 6 inert earthen and kill 10 Sweetsnufflers .", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 219784, ["x"] = 0.491, ["y"] = 0.302 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 224362, ["x"] = 0.494, ["y"] = 0.405333 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.491, ["y"] = 0.302 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79573, 80434 }, ["questLines"] = { { ["id"] = 5620, ["name"] = "The Caretaker of Brunwin's Terrace", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[80394] = { ["id"] = 80394, ["name"] = "Along for the Ride", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 80295, 80394, 80395, 81465, 81512, 81615, 81621, 81639, 81675, 81710, 81854, 82225, 82234, 82237, 82291, 82292, 82355, 82448, 82451, 82454, 82455, 82456, 82470 }, ["objectivesText"] = "Kill Players or Subdue Creatures Kill Players Subdue Moose or Rams", ["rewardXP"] = 11765, ["rewardItems"] = { 223802 }, ["starts"] = { { ["x"] = 0.616, ["y"] = 0.214, ["mapID"] = 2248 } }, ["ends"] = { { ["x"] = 0.616, ["y"] = 0.214, ["mapID"] = 2248 } }, ["coords"] = { ["mapID"] = 2248, ["x"] = 0.616, ["y"] = 0.214 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14717 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5589, ["name"] = "Isle of Dorn - World Quests", ["orderIndex"] = 20, ["flags"] = 0 } }, ["db2Objectives"] = { { ["text"] = "Kill Players or Subdue Creatures", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Kill Players", ["amount"] = 7, ["type"] = 9, ["objectID"] = 459, ["orderIndex"] = 1 }, { ["text"] = "Subdue Moose or Rams", ["amount"] = 10, ["type"] = 0, ["objectID"] = 221027, ["orderIndex"] = 2 } }, ["db2LabelIDs"] = { 3302 }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248, ["db2QuestInfoID"] = 113, ["db2QuestInfoName"] = "PvP World Quest" },
[80395] = { ["id"] = 80395, ["name"] = "Elemental Excavation", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 80295, 80394, 80395, 81465, 81512, 81615, 81621, 81639, 81675, 81710, 81854, 82225, 82234, 82237, 82291, 82292, 82355, 82448, 82451, 82454, 82455, 82456, 82470 }, ["objectivesText"] = "Kill Elementals or Players at Dhar Bandar Kill Players Kill Sand Elemental Kill Water Elemental Kill Kelp Elemental Kill Sand Elemental", ["rewardXP"] = 11765, ["rewardItems"] = { 218124, 223802 }, ["starts"] = { { ["x"] = 0.748, ["y"] = 0.551, ["mapID"] = 2248 } }, ["ends"] = { { ["x"] = 0.748, ["y"] = 0.551, ["mapID"] = 2248 } }, ["coords"] = { ["mapID"] = 2248, ["x"] = 0.748, ["y"] = 0.551 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14717 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5589, ["name"] = "Isle of Dorn - World Quests", ["orderIndex"] = 19, ["flags"] = 0 } }, ["db2Objectives"] = { { ["text"] = "Kill Elementals or Players at Dhar Bandar", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Kill Players", ["amount"] = 7, ["type"] = 9, ["objectID"] = 459, ["orderIndex"] = 1 }, { ["text"] = "Kill Sand Elemental", ["amount"] = 13, ["type"] = 0, ["objectID"] = 220544, ["orderIndex"] = 2 }, { ["text"] = "Kill Water Elemental", ["amount"] = 13, ["type"] = 0, ["objectID"] = 220545, ["orderIndex"] = 3 }, { ["text"] = "Kill Kelp Elemental", ["amount"] = 9, ["type"] = 0, ["objectID"] = 220547, ["orderIndex"] = 4 }, { ["text"] = "Kill Sand Elemental", ["amount"] = 5, ["type"] = 0, ["objectID"] = 220794, ["orderIndex"] = 5 } }, ["db2LabelIDs"] = { 3302 }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248, ["db2QuestInfoID"] = 113, ["db2QuestInfoName"] = "PvP World Quest" },
[80397] = { ["id"] = 80397, ["name"] = "Sweets Seekers", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80397 }, ["description"] = "Earthen cinderbrew is a potent drink. It's dangerous to those who lack our constitution. Even worse, it has a sweet aroma that draws the attention of a vicious species of mole. They'll do anything to get their claws on it! As I honor the earthen of Brunwin's Terrace with a sweet libation, my potent potable will draw their attention. If you're anywhere near me, be on your guard, so you can put down any who pop up.", ["objectivesText"] = "Kill 12 sweetsnufflers .", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14795 } }, ["questType"] = "standard" },
[80399] = { ["id"] = 80399, ["name"] = "Rations and Revelations", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78233, 78234, 78236, 78237, 78249, 78250, 78251, 78254, 78255, 78256, 78383, 79175, 79625, 80399 }, ["description"] = "We found these prisoners fleeing a nearby nerubian military base. The circumstances of their escape are... unclear, even to them. As if someone else created the opening they needed to escape. They need rest, but we need to find out what happened in there. Food first. Maybe once they've regained some of their strength, they'll remember something.", ["objectivesText"] = "Hand out 3 Arathi Rations . Progress: We managed to throw together a simple stew of sorts. It's not the tastiest, but it has to be better than whatever they had to eat in spider prison.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["rewardItems"] = { 217614 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 211409, ["x"] = 0.592, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 211409, ["x"] = 0.592, ["y"] = 0.194 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 78233 }, ["questLines"] = { { ["id"] = 5521, ["name"] = "Unraveling the Trapped", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5521, ["questLineOrder"] = 1 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5521, ["questLineOrder"] = 12 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[80401] = { ["id"] = 80401, ["name"] = "A Perfect Sponge", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80392, 80401, 80402, 80404, 80405, 80406, 80407, 80408, 80689 }, ["description"] = "Welcome, stalwart colleague, to Shimmermist Falls! It's always damp here--a thriving paradise for green, living things. Unfortunately, it's also the perfect climate for moss to grow on my inert earthen charges. We'll need to gather a few supplies for removing the moss. First, we need a sponge to wash their surfaces. It needs to be soft enough to not damage them but strong enough to hold up to an earthen's rough stone skin. The caps from the lashrooms down below are perfect!", ["objectivesText"] = "Collect one perfect lashroom cap . Progress: These lashroom caps make for perfect sponges!", ["rewardGold"] = 292100, ["rewardXP"] = 9920, ["rewardItems"] = { 218131 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 219899, ["x"] = 0.441, ["y"] = 0.368 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 219899, ["x"] = 0.441, ["y"] = 0.368 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.441, ["y"] = 0.368 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 80408 }, ["questLines"] = { { ["id"] = 5620, ["name"] = "The Caretaker of Brunwin's Terrace", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[80402] = { ["id"] = 80402, ["name"] = "Buckets and Blooms", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80392, 80401, 80402, 80404, 80405, 80406, 80407, 80408, 80689 }, ["description"] = "Down among the creeping lashrooms grows an orange flower. When mixed with water, its blooms make a caustic solvent that is perfect for removing moss from earthen skin. I also left a bucket next to this earthen the last time I was here, which I use to make the solvent. Something seems to have made off with it. Could I delegate the task of gathering these to you? I'll wait here. The moles from the terrace have given me enough excitement for one day.", ["objectivesText"] = "Collect 8 caustic blooms and find the missing bucket . Progress: The acidity from the plants is strong enough to remove the moss but gentle enough not to harm the earthen. Plus it has a pleasing smell to it. Almost like sulfur.", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["rewardItems"] = { 218187, 218355 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 219899, ["x"] = 0.441, ["y"] = 0.368 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 219899, ["x"] = 0.441, ["y"] = 0.368 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.441, ["y"] = 0.368 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 80408 }, ["questLines"] = { { ["id"] = 5620, ["name"] = "The Caretaker of Brunwin's Terrace", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[80404] = { ["id"] = 80404, ["name"] = "Mossy Earthen", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80392, 80401, 80402, 80404, 80405, 80406, 80407, 80408, 80689 }, ["description"] = "Excellent work gathering everything together. I've mixed the solvent for you. Now all that's left is to gently clean off our mossy friends down there.", ["objectivesText"] = "Tend to 4 mossy earthen. Progress: Let's get these folks cleaned up.", ["rewardGold"] = 219000, ["rewardXP"] = 7440, ["rewardItems"] = { 218353 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 219899, ["x"] = 0.441, ["y"] = 0.368 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 219899, ["x"] = 0.441, ["y"] = 0.368 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.441, ["y"] = 0.368 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 80401, 80402 }, ["questLines"] = { { ["id"] = 5620, ["name"] = "The Caretaker of Brunwin's Terrace", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[80405] = { ["id"] = 80405, ["name"] = "Too Much Drip", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80392, 80401, 80402, 80404, 80405, 80406, 80407, 80408, 80689 }, ["description"] = "This is Ausgazur . His hand is usually full of a selection of his favorite gems. We don't really know what it's like when we go into stasis, but he wanted to spend his last moments contemplating the natural beauty of Azeroth and her bounty. I am afraid someone or something has made off with the jewels he usually holds. Let's look around. See if you can find any clues where they may have gone off to.", ["objectivesText"] = "Examine Ausgazur for clues. Progress: Ausgazur will never forgive me if his gems go missing. This is very upsetting. Who would steal from an earthen in stasis?", ["rewardGold"] = 146000, ["rewardXP"] = 4960, ["rewardItems"] = { 219216 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 220784, ["x"] = 0.419, ["y"] = 0.4 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 220784, ["x"] = 0.419, ["y"] = 0.4 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.419, ["y"] = 0.4 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 80689 }, ["questLines"] = { { ["id"] = 5620, ["name"] = "The Caretaker of Brunwin's Terrace", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[80406] = { ["id"] = 80406, ["name"] = "Seeking Ausgazur's Gems", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80392, 80401, 80402, 80404, 80405, 80406, 80407, 80408, 80689 }, ["description"] = "So it was kobolds who made off with Ausgazur's gems. I did not realize the Waterworks was under attack. Our timing is lucky for the defenders down below! We must get those jewels back! I'll stay here and guard the remaining gems, but I implore you to complete a critical task: go down into the Waterworks and retrieve the rest.", ["objectivesText"] = "Recover 4 of Ausgazur's gems. Progress: We need to find the rest of Ausgazur's gems! Critical priority!", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["rewardItems"] = { 219015 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 220784, ["x"] = 0.419, ["y"] = 0.4 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 220784, ["x"] = 0.419, ["y"] = 0.4 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.419, ["y"] = 0.4 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 80405 }, ["questLines"] = { { ["id"] = 5620, ["name"] = "The Caretaker of Brunwin's Terrace", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[80407] = { ["id"] = 80407, ["name"] = "Glintwick the Gem Grabber", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80392, 80401, 80402, 80404, 80405, 80406, 80407, 80408, 80689 }, ["description"] = "The kobold mentioned Glintwick, did he? It sounds like she's the driving force behind these gem thieves. I'll bet my beard she's got Ausgazur's last gem! Look for her in the Waterworks and see if she has the final gem. She may also be behind the attack that's happening, so taking her out will help the defenders.", ["objectivesText"] = "Kill Glintwick. Progress: Glintwick will not get away with this thievery!", ["rewardGold"] = 619600, ["rewardXP"] = 12400, ["rewardItems"] = { 219213, 228658 }, ["rewardCurrencies"] = { { ["id"] = 2902, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 220784, ["x"] = 0.419, ["y"] = 0.4 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 220784, ["x"] = 0.419, ["y"] = 0.4 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.419, ["y"] = 0.4 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 80405, 80406 }, ["questLines"] = { { ["id"] = 5620, ["name"] = "The Caretaker of Brunwin's Terrace", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[80408] = { ["id"] = 80408, ["name"] = "Shimmermist Falls", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80392, 80401, 80402, 80404, 80405, 80406, 80407, 80408, 80689 }, ["description"] = "West of Gundargaz is another green space - a lovely area with waterfalls and more terraces. My schedule takes me in that direction next, and I would be very glad of your company to help deal with the wildlife there as well. If your other duties are not pressing, let us meet there.", ["objectivesText"] = "Meet Batzvara in Shimmermist Falls.", ["rewardGold"] = 73000, ["rewardXP"] = 2480, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 224362, ["x"] = 0.494, ["y"] = 0.405333 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 219899, ["x"] = 0.441, ["y"] = 0.368 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.494, ["y"] = 0.405333 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 80392 }, ["questLines"] = { { ["id"] = 5620, ["name"] = "The Caretaker of Brunwin's Terrace", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
