[80434] = { ["id"] = 80434, ["name"] = "Into the Deeps", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2339, ["storyline"] = { 78555, 78557, 78631, 78634, 78635, 78636, 78637, 78638, 78639, 78640, 78641, 78642, 78837, 78838, 78839, 79205, 79267, 80082, 80434, 83550 }, ["series"] = { 78555, 83550 }, ["description"] = "Onward and downward it is, then. We'd best follow after Speaker Brinthe and see what state the nerubians have left her home in. Magni, Dagran, and I will accompany you down in due time. Would you mind roving ahead and making sure there's a warm welcome awaiting us?", ["objectivesText"] = "Find Speaker Brinthe at the bottom of the Coreway.", ["rewardGold"] = 73000, ["rewardXP"] = 2480, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 217887, ["x"] = 0.319, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212592, ["x"] = 0.4, ["y"] = 0.284 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.319, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 2214, 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 78546 }, ["questLines"] = { { ["id"] = 5533, ["name"] = "By Candlelight", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 6008, ["name"] = "Catch Up: War Within: Wrapper 2", ["orderIndex"] = 17, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5533, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5533, ["questLineOrder"] = 5 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6008, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
