[80448] = { ["id"] = 80448, ["name"] = "A Fresh Scene", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster", "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 5841, ["mapID"] = 371, ["storyline"] = { 80448 }, ["description"] = "Uh-uh honey, I'm not gonna let you spend all day in stuffy dungeons where no one can see your getup! Put on your going-out look and let's get you somewhere fresh!", ["objectivesText"] = "Complete a scenario. Progress: You wouldn't catch me dead in a dungeon, nuh-uh. You know what's down there? Mud! Cobwebs! People wearing those shoulderpads way too big for 'em. No sir, I'll stay right here, thank you.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 94221, 226142, 226143, 226144, 226145 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 219025, ["x"] = 0.428, ["y"] = 0.276 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 219025, ["x"] = 0.428, ["y"] = 0.276 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.276 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5841 } }, ["questType"] = "standard" },
