[80500] = { ["id"] = 80500, ["name"] = "The Bronzebeard Family", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 78529, 78713, 78714, 78715, 78716, 78717, 78718, 78719, 78721, 78722, 79105, 79106, 80321, 80500, 81930, 81966 }, ["description"] = "We need to let Brann and my son Dagran know what happened. They're at Dalaran 's visitor center. Could ye go get them for me? Father needs his family right now.", ["objectivesText"] = "Head to Brann and Dagran in the Dalaran Visitor Center to inform them of what has happened to Magni. Progress: My son always has been the scholarly sort. Takes after his father in that way... We're all quite proud of him.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["x"] = 0.405, ["y"] = 0.577, ["mapID"] = 629, ["npcID"] = 214651 } }, ["ends"] = { { ["x"] = 0.405, ["y"] = 0.577, ["mapID"] = 629, ["npcID"] = 214651 } }, ["coords"] = { ["mapID"] = 629, ["x"] = 0.405, ["y"] = 0.577 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questGiverID"] = 214651, ["questTurnInID"] = 214651, ["questType"] = "standard", ["sourceQuests"] = { 78716 }, ["questLines"] = { { ["id"] = 5513, ["name"] = "Visions of Azeroth", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5638, ["name"] = "Dalaran Intro", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 235, ["title"] = "Visions of Azeroth", ["questLineID"] = 5513, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5513, ["questLineOrder"] = 1 }, { ["id"] = 261, ["title"] = "Expansion Intro Skip", ["questLineID"] = 5638, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 629 },
[80502] = { ["id"] = 80502, ["name"] = "Don't Cry for Me, Azj-Kahet", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2213, ["storyline"] = { 79630, 79631, 80502 }, ["description"] = "<You find a crumpled page of journal paper wrapped around a small key.> I always suspected Arax'ne was a traditionalist, but I didn't think she'd go this far. I don't know where I'm going, but I just have to get away from her. To whoever finds this, it means the worst has come to pass. This key unlocks a chest that contains all my worldly possessions. They are yours. All I ask is that you avenge me by slaying Arax'ne .", ["objectivesText"] = "Avenge Klaskin and kill Arax'ne in the Umbral Bazaar. Progress: The key glints silver in the light of Azj-Kahet .", ["rewardGold"] = 292100, ["rewardXP"] = 10595, ["rewardItems"] = { 226173, 226174, 226175, 226176 }, ["rewardCurrencies"] = { { ["id"] = 3002, ["amount"] = 500 }, { ["id"] = 3056, ["amount"] = 35 } }, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 220690, ["x"] = 0.638, ["y"] = 0.16 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 220690, ["x"] = 0.638, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.638, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questTurnInID"] = 220690, ["questType"] = "standard", ["sourceQuests"] = { 79631 }, ["questLines"] = { { ["id"] = 5649, ["name"] = "Grieve & Weave", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2213, ["startItems"] = { 218084 } },
[80508] = { ["id"] = 80508, ["name"] = "Dread in the Den", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80508, 80509, 80510, 80511, 80512, 80513, 80514, 80515, 80516, 81981 }, ["description"] = "You kobold friend, yes? Need help. Bad things happening in the Chittering Den. Glumtooth Gang setting up camp. Cronies of Candle King, want war with earthen. Can't stop them alone. Meet me at camp.", ["objectivesText"] = "Meet Scrit at her camp in the Chittering Den.", ["rewardGold"] = 153400, ["rewardXP"] = 4960, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 222234, ["x"] = 0.64, ["y"] = 0.433 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 222234, ["x"] = 0.64, ["y"] = 0.433 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.433 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79573, 80434 }, ["questLines"] = { { ["id"] = 5624, ["name"] = "Dread in the Den", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[80509] = { ["id"] = 80509, ["name"] = "A Suit of Slime", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80508, 80509, 80510, 80511, 80512, 80513, 80514, 80515, 80516, 81981 }, ["series"] = { 80510, 80511 }, ["description"] = "Glumtooth Gang no let you into camp looking like that. Need disguise. Make you look like bug, then we walk right in. First, need wax. Plenty here. Take from slime beasts or scrape off hoppers. Then we stick wax on you. Stick bug bits to wax. Perfect disguise.", ["objectivesText"] = "Collect 20 Sticky Wax from Waxy Runoffs and Wax-addled Hoppers . Progress: With right disguise, no one know you not bug.", ["rewardGold"] = 292100, ["rewardXP"] = 9920, ["rewardItems"] = { 220218 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 222234, ["x"] = 0.64, ["y"] = 0.433 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 222234, ["x"] = 0.64, ["y"] = 0.433 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.433 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 80508 }, ["questLines"] = { { ["id"] = 5624, ["name"] = "Dread in the Den", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[80510] = { ["id"] = 80510, ["name"] = "Healing the Headwaters", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80508, 80509, 80510, 80511, 80512, 80513, 80514, 80515, 80516, 81981 }, ["series"] = { 80509, 80511 }, ["description"] = "Glumtooth Gang so wasteful! They leave much scrap in the water. Bad for water. Bad for scrap. Go clean it up.", ["objectivesText"] = "Remove 6 Waxy Scrap.", ["rewardGold"] = 292100, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 222234, ["x"] = 0.64, ["y"] = 0.433 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 222234, ["x"] = 0.64, ["y"] = 0.433 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.433 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 80508 }, ["questLines"] = { { ["id"] = 5624, ["name"] = "Dread in the Den", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[80511] = { ["id"] = 80511, ["name"] = "Casing the Camp", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80508, 80509, 80510, 80511, 80512, 80513, 80514, 80515, 80516, 81981 }, ["series"] = { 80509, 80510 }, ["description"] = "Now we take you to camp. You see what Boss Whiskerlash do. Put on bug disguise when we close to camp. Let me do talking.", ["objectivesText"] = "Investigate the Glumtooth Gang camp. Progress: Can no let this camp stand. Too much to lose for kobold and earthen.", ["rewardGold"] = 154900, ["rewardXP"] = 4960, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 222234, ["x"] = 0.64, ["y"] = 0.433 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 222234, ["x"] = 0.64, ["y"] = 0.433 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.433 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questTurnInID"] = 222234, ["questType"] = "standard", ["sourceQuests"] = { 80509, 80510 }, ["questLines"] = { { ["id"] = 5624, ["name"] = "Dread in the Den", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[80512] = { ["id"] = 80512, ["name"] = "Beat the Best", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80508, 80509, 80510, 80511, 80512, 80513, 80514, 80515, 80516, 81981 }, ["description"] = "If Glumtooth Gang succeed, this earthen first captive of many. We need free him. He prize. Every kobold here want fight him. Must earn our place. You beat up strong bugs, they think me strong trainer. Then they let you into ring. May best bug win.", ["objectivesText"] = "Defeat the bug-trainers. Progress: Beat other three contenders and we can rescue the earthen.", ["rewardGold"] = 619600, ["rewardXP"] = 12400, ["starts"] = { { ["npcID"] = 222239 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14795 } }, ["questGiverID"] = 222239, ["questType"] = "standard", ["sourceQuests"] = { 80511 }, ["questLines"] = { { ["id"] = 5624, ["name"] = "Dread in the Den", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[80513] = { ["id"] = 80513, ["name"] = "Snouty Sabotage", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80508, 80509, 80510, 80511, 80512, 80513, 80514, 80515, 80516, 81981 }, ["description"] = "You need good distraction to get earthen out. I need Glumtooth Gang stopped. Have perfect thing for both. Some fool mix Cinderbrew with candle wax in the Warrens. Candles burn normal at first, then boom. Big boom. Place around camp. Explosions good distraction for escape. While you at it, loosen some bug leashes. Let Glumtooth Gang see how scary bugs are.", ["objectivesText"] = "Place Cinder-Flash Candles and loosen bug leashes. Progress: Boss Whiskerlash regret day he help turn kobolds to war.", ["rewardGold"] = 292100, ["rewardXP"] = 9920, ["starts"] = { { ["npcID"] = 222239 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14795 } }, ["questGiverID"] = 222239, ["questType"] = "standard", ["sourceQuests"] = { 80511 }, ["questLines"] = { { ["id"] = 5624, ["name"] = "Dread in the Den", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[80514] = { ["id"] = 80514, ["name"] = "Break out Berrund!", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80508, 80509, 80510, 80511, 80512, 80513, 80514, 80515, 80516, 81981 }, ["description"] = "You work good. Now they let you into ring to \"fight\" earthen. You go to ring when ready. Cinder-flash candles could go off any moment. I head back to camp. Wait for you and earthen there. You good one. No get killed.", ["objectivesText"] = "Escort Berrund from the camp.", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["starts"] = { { ["npcID"] = 222239 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 220220, ["x"] = 0.675, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.675, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questGiverID"] = 222239, ["questType"] = "standard", ["sourceQuests"] = { 80512, 80513 }, ["questLines"] = { { ["id"] = 5624, ["name"] = "Dread in the Den", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[80515] = { ["id"] = 80515, ["name"] = "Put the Shine On", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80508, 80509, 80510, 80511, 80512, 80513, 80514, 80515, 80516, 81981 }, ["description"] = "Hate to admit, but loud earthen right. Boss Whiskerlash have strongest bugs. But everything have weakness. Spiders afraid of light, and our friend very shiny. If we make him shinier, no spider want to fight. Glumtooth Gang been capturing candleflies. Free them and rub off some glow dust. We make big earthen big shiny!", ["objectivesText"] = "Free Candleflies and collect their luminescence. Progress: This better not go to his head.", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["rewardItems"] = { 220485 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 222234, ["x"] = 0.64, ["y"] = 0.433 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 222234, ["x"] = 0.64, ["y"] = 0.433 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.433 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 80514 }, ["questLines"] = { { ["id"] = 5624, ["name"] = "Dread in the Den", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[80516] = { ["id"] = 80516, ["name"] = "Bump off the Boss", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80508, 80509, 80510, 80511, 80512, 80513, 80514, 80515, 80516, 81981 }, ["description"] = "That kobold knows her stuff. Scrit says Boss Whiskerlash has his own cadre of spiders in a cave nearby. Don't worry, I'll lead the charge. Come on, we've got a boss to take down.", ["objectivesText"] = "Slay Boss Whiskerlash .", ["rewardGold"] = 619600, ["rewardXP"] = 12400, ["rewardItems"] = { 228654, 228655, 228656, 228657, 258265 }, ["rewardCurrencies"] = { { ["id"] = 2902, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 220220, ["x"] = 0.675, ["y"] = 0.41 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 222234, ["x"] = 0.64, ["y"] = 0.433 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.675, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 80515 }, ["questLines"] = { { ["id"] = 5624, ["name"] = "Dread in the Den", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[80517] = { ["id"] = 80517, ["name"] = "Back to Where it Began", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79022, 79023, 79024, 79025, 79026, 79027, 79028, 79029, 79030, 79217, 79324, 79325, 80145, 80517 }, ["description"] = "<Zee-Zee is ready to head back to the Deepforge Golemworks.>", ["objectivesText"] = "Meet up with Brinthe and Dagran outside the Deepforge Golemworks.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["npcID"] = 218622 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 214663, ["x"] = 0.541, ["y"] = 0.748 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.541, ["y"] = 0.748 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questGiverID"] = 218622, ["questType"] = "standard", ["sourceQuests"] = { 80145 }, ["questLines"] = { { ["id"] = 5531, ["name"] = "The Machines March to War", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5531, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214, ["db2QuestHubAreaPoiID"] = 7911 },
[80558] = { ["id"] = 80558, ["name"] = "Nothing Ventured", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79538, 79539, 79540, 79541, 80558 }, ["description"] = "These niffen have been down here a long time--long enough to build a village and set up trade with the nerubians. Some of them are even able to trade in that big nerubian city! The goblins, though? They're from the Venture Company. No wonder General Anub'azal was skeptical of me, if he's used to dealing with them. What are they doing all the way down here? Let's try to learn what led them to this place.", ["objectivesText"] = "Learn what you can from the goblins in Mmarl. Progress: Take a good look around for loose-lipped goblins.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 217029, ["x"] = 0.775, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 217029, ["x"] = 0.775, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.775, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 79651 }, ["questLines"] = { { ["id"] = 5541, ["name"] = "Haggling with Mmarl", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[80562] = { ["id"] = 80562, ["name"] = "Blossoming Delight", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["description"] = "Few followers of the light would dare to attempt the dish I plan to make. A mix of traditional Imperial spices combined with the forbidden harvest of the nearby fungal blooms. This dish will delight the palate and remind one of the adventurous spirit that founded the Hallowfall expedition. Please journey to the Mycomancer Cavern nearby and harvest the blooms I require.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 215448, 228741 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 40 }, { ["id"] = 2899, ["amount"] = 200 } }, ["starts"] = { { ["npcID"] = 206533, ["x"] = 0.644, ["y"] = 0.31, ["mapID"] = 2215 } }, ["ends"] = { { ["npcID"] = 206533, ["x"] = 0.644, ["y"] = 0.31, ["mapID"] = 2215 } }, ["coords"] = { ["x"] = 0.644, ["y"] = 0.31, ["source"] = "quest_giver", ["mapID"] = 2215 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78466 } },
[80563] = { ["id"] = 80563, ["name"] = "Tool of Attunement", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 80563, 80564, 80565, 80566, 80567, 80568, 80569, 80570, 80571, 80572, 82143 }, ["series"] = { 80564, 80565, 82143 }, ["description"] = "The nerubians must have some means of cleansing themselves after Black Blood exposure. If they did not, they would not have been so successful in their harvesting operation. If necessary, I can pick up on the harmony of this world with ease to restore my mind to this reality. But for your sake and Hannan's, we should probably obtain whatever it is they use. Although we can spare the trouble... if you don't mind the threat of forever splitting your consciousness between two realities.", ["objectivesText"] = "Find a Tuning Crystal . Progress: The nerubians must have something on them to cleanse their minds after such direct proximity to the Black Blood.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["rewardItems"] = { 218188 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 220595, ["x"] = 0.446, ["y"] = 0.664 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 220595, ["x"] = 0.446, ["y"] = 0.664 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.664 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questTurnInID"] = 220595, ["questType"] = "standard", ["sourceQuests"] = { 83306 }, ["questLines"] = { { ["id"] = 5618, ["name"] = "Melody of Madness", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2256 },
[80564] = { ["id"] = 80564, ["name"] = "Field Research", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 80563, 80564, 80565, 80566, 80567, 80568, 80569, 80570, 80571, 80572, 82143 }, ["series"] = { 80563, 80565, 82143 }, ["description"] = "The nerubians are harvesting Black Blood nearby. If allowed to persist, the corruption caused by excavating the veins may spread. It will continue until it consumes everything. I have no intention of sitting and waiting for it to taint the roots. I am trying to learn and understand their methods... so that I may strike at the heart of the operation. You're welcome to join me. If, of course, you would also prefer your world not to drown in oozing pools of Black Blood.", ["objectivesText"] = "Investigate the Black Blood harvesting site. Progress: These disgusting pustules, the veins of corruption... this is only the beginning of the damage this horrific operation could cause.", ["rewardGold"] = 297900, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 220595, ["x"] = 0.446, ["y"] = 0.664 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 220595, ["x"] = 0.446, ["y"] = 0.664 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.664 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questTurnInID"] = 220595, ["questType"] = "standard", ["sourceQuests"] = { 83306 }, ["questLines"] = { { ["id"] = 5618, ["name"] = "Melody of Madness", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2256 },
[80565] = { ["id"] = 80565, ["name"] = "Resounding Repercussions", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 80563, 80564, 80565, 80566, 80567, 80568, 80569, 80570, 80571, 80572, 82143 }, ["series"] = { 80563, 80564, 82143 }, ["description"] = "I did not mean for... < Orweyna 's eyes narrow.> Fetch him, <name>. You were exposed to the Black Blood, too. But Hannan took most of it. He has entered the Unseeming, his mind shifted to a realm beyond our eyes through exposure to the Black Blood. You may need to join him, however far in he ventured, to retrieve him. I will activate the nerubian cleansing instrument for when you return. Do not lose yourself in that altered state.", ["objectivesText"] = "Retrieve Hannan from the Abandoned Harvest Site inside the cave. Progress: Is this real? Am I imagining the monsters?", ["rewardGold"] = 29200, ["rewardXP"] = 1325, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 220603, ["x"] = 0.598, ["y"] = 0.638 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 220608, ["x"] = 0.618, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.638 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 82143 }, ["questLines"] = { { ["id"] = 5618, ["name"] = "Melody of Madness", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[80566] = { ["id"] = 80566, ["name"] = "Enemies Abound", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 80563, 80564, 80565, 80566, 80567, 80568, 80569, 80570, 80571, 80572, 82143 }, ["series"] = { 80567, 80568 }, ["description"] = "< Hannan is barely responsive and less corporeal than he should be, lost deeper in the Unseeming than you.> Some of the canisters exploded... Then the spiders appeared. Kill the--kill the spiders!", ["objectivesText"] = "Find and kill the spiders.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 220608, ["x"] = 0.618, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 223285, ["x"] = 0.598, ["y"] = 0.638 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 80565 }, ["questLines"] = { { ["id"] = 5618, ["name"] = "Melody of Madness", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[80567] = { ["id"] = 80567, ["name"] = "Song of Restoring", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 80563, 80564, 80565, 80566, 80567, 80568, 80569, 80570, 80571, 80572, 82143 }, ["series"] = { 80566, 80568 }, ["description"] = "< Orweyna looks relieved at the sight of Hannan , but does not seem dissuaded from her task.> I cannot say I am surprised at what you found in that cave. Nerubians stuck in the Unseeming, trapped in a realm of monsters and madness... I would pity them, but they sought this out. You, however, need to shift back before the influence of the Black Blood becomes too strong on your mind.", ["objectivesText"] = "Use the Harmonizing Instrument . Progress: It is a relief that the tuning crystal we found worked on this strange instrument. For once we should be grateful for the ingenuity of the nerubians. If this device had not worked, we may have been stuck in the Unseeming forever. Like the nerubians in the cave.", ["rewardGold"] = 146000, ["rewardXP"] = 5300, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 223285, ["x"] = 0.598, ["y"] = 0.638 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 223286, ["x"] = 0.598, ["y"] = 0.64 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.638 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 80566 }, ["questLines"] = { { ["id"] = 5618, ["name"] = "Melody of Madness", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[80568] = { ["id"] = 80568, ["name"] = "Leave No Trace", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["series"] = { 80566, 80567 }, ["description"] = "I need to go make sure she's all right. What I saw in that cave... If she's more sensitive to this... Hannan nearly growls.> But she's making a mess out here, drawing attention and leaving a trail leading outsiders right to her! Right to us. We're supposed to be subtle. Unseen. Keep to the brush, hide in our other forms as much as possible. I hate to ask this of you, but can you use my scythe to take care of the evidence while I check on her?", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["starts"] = { { ["npcID"] = 223286, ["x"] = 0.598, ["y"] = 0.64, ["mapID"] = 2255 } }, ["ends"] = { { ["npcID"] = 227158, ["x"] = 0.624, ["y"] = 0.79, ["mapID"] = 2255 } }, ["coords"] = { ["x"] = 0.598, ["y"] = 0.64, ["source"] = "quest_giver", ["mapID"] = 2255 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 80567 }, ["questLines"] = { { ["id"] = 5618, ["name"] = "Melody of Madness", ["orderIndex"] = 5, ["flags"] = 0 } } },
[80569] = { ["id"] = 80569, ["name"] = "Harmonious Approach", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 80563, 80564, 80565, 80566, 80567, 80568, 80569, 80570, 80571, 80572, 82143 }, ["description"] = "I know I cannot stop Orweyna from going down there and drawing attention to our presence. But... perhaps we could stop word of our presence from spreading. Find whoever is in charge of this harvest site. And... do what is needed to ensure they can't spread the word.", ["objectivesText"] = "Kill Harvest Warden Izk'tilak . Progress: I'm not going to leave her down here alone. But we have to be cautious. We must deal with anyone who sees us.", ["rewardGold"] = 619600, ["rewardXP"] = 13245, ["starts"] = { { ["x"] = 0.625, ["y"] = 0.791, ["mapID"] = 2256, ["npcID"] = 227158 } }, ["ends"] = { { ["x"] = 0.625, ["y"] = 0.791, ["mapID"] = 2256, ["npcID"] = 227158 } }, ["coords"] = { ["mapID"] = 2256, ["x"] = 0.625, ["y"] = 0.791 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14752 } }, ["questGiverID"] = 227158, ["questTurnInID"] = 227158, ["questType"] = "standard", ["sourceQuests"] = { 80570, 80571 }, ["questLines"] = { { ["id"] = 5618, ["name"] = "Melody of Madness", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2256 },
[80570] = { ["id"] = 80570, ["name"] = "Staunch the Flow", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 80563, 80564, 80565, 80566, 80567, 80568, 80569, 80570, 80571, 80572, 82143 }, ["series"] = { 80571, 80572 }, ["description"] = "Do they even understand what they are doing? Orweyna bares her teeth, practically growling.> Destroy as many of those extractors as you can. Shatter the bulbs, snap the limbs, burn the wreckage. We cannot stop them all, not today. But a bit of destruction may temper my rage.", ["objectivesText"] = "Destroy 8 Extractors.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["starts"] = { { ["x"] = 0.626, ["y"] = 0.792, ["mapID"] = 2256, ["npcID"] = 220610 } }, ["ends"] = { { ["x"] = 0.626, ["y"] = 0.792, ["mapID"] = 2256, ["npcID"] = 220610 } }, ["coords"] = { ["mapID"] = 2256, ["x"] = 0.626, ["y"] = 0.792 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14752 } }, ["questGiverID"] = 220610, ["questTurnInID"] = 220610, ["questType"] = "standard", ["sourceQuests"] = { 80568 }, ["questLines"] = { { ["id"] = 5618, ["name"] = "Melody of Madness", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2256 },
[80571] = { ["id"] = 80571, ["name"] = "Decipher the Cacophony", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 80563, 80564, 80565, 80566, 80567, 80568, 80569, 80570, 80571, 80572, 82143 }, ["series"] = { 80570, 80572 }, ["description"] = "This is far worse than I thought. It's as if they're feeding the corruption. Encouraging it. The dissonance growing louder and louder... Orweyna seems shaken, but not deterred.> I can hardly hear anything else. My head is pounding. I... I need to see how far gone this land truly is. . Bring me something from the Unseeming.", ["objectivesText"] = "Collect 10 Discordant Essence from Discordant enemies in the Unseeming. Progress: What have the nerubians done to this place?", ["rewardGold"] = 292100, ["rewardXP"] = 10595, ["rewardItems"] = { 217391, 221776 }, ["starts"] = { { ["x"] = 0.626, ["y"] = 0.792, ["mapID"] = 2256, ["npcID"] = 220610 } }, ["ends"] = { { ["x"] = 0.626, ["y"] = 0.792, ["mapID"] = 2256, ["npcID"] = 220610 } }, ["coords"] = { ["mapID"] = 2256, ["x"] = 0.626, ["y"] = 0.792 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14752 } }, ["questGiverID"] = 220610, ["questTurnInID"] = 220610, ["questType"] = "standard", ["sourceQuests"] = { 80568 }, ["questLines"] = { { ["id"] = 5618, ["name"] = "Melody of Madness", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2256 },
[80572] = { ["id"] = 80572, ["name"] = "Discordant Measures", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 80563, 80564, 80565, 80566, 80567, 80568, 80569, 80570, 80571, 80572, 82143 }, ["series"] = { 80570, 80571 }, ["description"] = "I cannot stand to look at this any longer. I must act. . You have survived the Unseeming before. Now we must go there together. I must see it for myself if I am to believe this vile place truly cannot be cleansed. We will kill what we can and search for some sliver of hope that we can still restore this land.", ["objectivesText"] = "Acquire 50 stacks of Unseeming Shift and collect 3 samples from elite enemies lost in the Unseeming. In addition to destroying extractors, you can also acquire Unseeming Shift by standing in pools of Black Blood. However, be careful as you will gain stacks quickly by doing so. Progress: Hannan's concerns are not unfounded. But I cannot simply witness this corruption and make no attempt to root it out.", ["rewardGold"] = 619600, ["rewardXP"] = 13245, ["rewardItems"] = { 225696, 225697, 225698 }, ["rewardCurrencies"] = { { ["id"] = 3002, ["amount"] = 500 }, { ["id"] = 3056, ["amount"] = 250 }, { ["id"] = 3056, ["amount"] = 285 } }, ["starts"] = { { ["x"] = 0.626, ["y"] = 0.792, ["mapID"] = 2256, ["npcID"] = 220610 } }, ["ends"] = { { ["x"] = 0.626, ["y"] = 0.792, ["mapID"] = 2256, ["npcID"] = 220610 } }, ["coords"] = { ["mapID"] = 2256, ["x"] = 0.626, ["y"] = 0.792 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14752 } }, ["questGiverID"] = 220610, ["questTurnInID"] = 220610, ["questType"] = "standard", ["sourceQuests"] = { 80570, 80571 }, ["questLines"] = { { ["id"] = 5618, ["name"] = "Melody of Madness", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2256 },
[80573] = { ["id"] = 80573, ["name"] = "Dropping Eaves: Spoils of War", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 80573, 81470, 81471, 81472, 81473, 81475, 81476, 81477, 81478, 81479, 81480, 81481, 81482, 81483, 81484, 81487, 81488, 81489, 81490, 81491, 81492, 81493, 81494, 81495, 81496, 81497, 81498, 81499, 81500, 81501, 81502, 81503, 81504, 81505, 81506, 81555 }, ["objectivesText"] = "Have a drink and eavesdrop Sureki War Chest looted", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 218456, 219016, 219017 }, ["starts"] = { { ["x"] = 0.55, ["y"] = 0.266, ["mapID"] = 2213, ["npcID"] = 224193 } }, ["ends"] = { { ["x"] = 0.55, ["y"] = 0.266, ["mapID"] = 2213, ["npcID"] = 224193 } }, ["coords"] = { ["mapID"] = 2213, ["x"] = 0.55, ["y"] = 0.266 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14752 } }, ["questGiverID"] = 224193, ["questTurnInID"] = 224193, ["questType"] = "standard", ["sourceQuests"] = { 78393, 80544, 80545, 80546 }, ["questLines"] = { { ["id"] = 5573, ["name"] = "The Severed Threads", ["orderIndex"] = 12, ["flags"] = 0 } }, ["db2Objectives"] = { { ["text"] = "Have a drink and eavesdrop", ["amount"] = 1, ["type"] = 0, ["objectID"] = 228735, ["orderIndex"] = 0 }, { ["text"] = "Sureki War Chest looted", ["amount"] = 1, ["type"] = 0, ["objectID"] = 220889, ["orderIndex"] = 1 } }, ["db2LabelIDs"] = { 3555 }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2213 },
[80576] = { ["id"] = 80576, ["name"] = "Listener Lost", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80576, 80577, 80578, 80593, 80676, 80682, 81613, 82144, 82224 }, ["description"] = "Blast it all! Brennok and I were on our way to Shadowvein Point to conduct a recitation ceremony. We were attacked by scorpids. Now the hauler has a scorpid stinger lodged in its gears, and Brennok wandered off. He said he was going to stretch his legs while I fixed the hauler, but that was a while ago. I need to get the bot moving again, can you look for him?", ["objectivesText"] = "Find Brennok .", ["rewardGold"] = 30900, ["rewardXP"] = 1240, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 220600, ["x"] = 0.589333, ["y"] = 0.446667 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 220597, ["x"] = 0.613143, ["y"] = 0.446 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.589333, ["y"] = 0.446667 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79573, 80434 }, ["questLines"] = { { ["id"] = 5626, ["name"] = "Tired of Rest", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[80577] = { ["id"] = 80577, ["name"] = "Readying the Recitation", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80576, 80577, 80578, 80593, 80676, 80682, 81613, 82144, 82224 }, ["series"] = { 80676, 81613 }, ["description"] = "Once a year, Brennok and I take the long road through The Ringing Deeps . We stop at each outpost, and Brennok tells the residents a story from their past. One they entrusted to him to remember, even when they forget. It's my duty to ready the ceremony site. Would you come with me? I could use the help.", ["objectivesText"] = "Prepare the recitation site. Progress: Brennok usually seems more excited for a recitation.", ["rewardGold"] = 154900, ["rewardXP"] = 4960, ["rewardItems"] = { 224008 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 220600, ["x"] = 0.589333, ["y"] = 0.446667 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 220600, ["x"] = 0.589333, ["y"] = 0.446667 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.589333, ["y"] = 0.446667 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 81613 }, ["questLines"] = { { ["id"] = 5626, ["name"] = "Tired of Rest", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[80578] = { ["id"] = 80578, ["name"] = "The Common Costume", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80576, 80577, 80578, 80593, 80676, 80682, 81613, 82144, 82224 }, ["series"] = { 82224 }, ["description"] = "I'll slip away after the recitation. It's easy to vanish in a crowd of earthen enjoying a keg of cinderbrew. However, I can't be recognized when I leave town. I don't want anyone to stop me. Or worse, to think I'm abandoning my oath. Better to just disappear. If you find me a spare set of Miner's Clothes , I'll be able to get away without being noticed.", ["objectivesText"] = "Find a spare set of Miner's Clothes . Progress: Did you find them yet?", ["rewardGold"] = 146000, ["rewardXP"] = 4960, ["rewardItems"] = { 221472 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 220597, ["x"] = 0.613143, ["y"] = 0.446 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 220597, ["x"] = 0.613143, ["y"] = 0.446 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.613143, ["y"] = 0.446 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 81613, 82224 }, ["questLines"] = { { ["id"] = 5626, ["name"] = "Tired of Rest", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[80592] = { ["id"] = 80592, ["name"] = "Forge a Pact", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "weekly", "repeatable", "meta" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 80592 }, ["description"] = "Let us renew your Pact. Remember, you may only enter a Pact with one of the Severed Threads at a time. These contracts are temporary, though, so you will have many opportunities to prove yourself to all three.", ["objectivesText"] = "Choose a Severed Threads Pact.", ["rewardXP"] = 14705, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 220867, ["x"] = 0.552, ["y"] = 0.412 }, { ["mapID"] = 2255, ["npcID"] = 223750, ["x"] = 0.552, ["y"] = 0.412 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 220867, ["x"] = 0.552, ["y"] = 0.412 }, { ["mapID"] = 2255, ["npcID"] = 223750, ["x"] = 0.552, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 79573, 84682 }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255, ["db2QuestInfoID"] = 284, ["db2QuestInfoName"] = "Meta Quest" },
[80593] = { ["id"] = 80593, ["name"] = "A Sip of Cinder", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80576, 80577, 80578, 80593, 80676, 80682, 81613, 82144, 82224 }, ["description"] = "Now there's one last thing we need. It wouldn't be a proper recitation ceremony without mead. However, Hearthkeeper Zirc tells me the last couple deliveries of cinderbrew haven't arrived. It seems the local flayers in the Rumbling Wastes have a taste for it and raid the shipments. Here, take a spare keg. See what you can recover from the flayers.", ["objectivesText"] = "Fill a keg with Cinderbrew Mead. Progress: Careful out there, flayers are already dangerous enough. I wouldn't want to meet one that's been guzzling cinderbrew.", ["rewardGold"] = 292100, ["rewardXP"] = 9920, ["rewardItems"] = { 221000, 221001 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 220600, ["x"] = 0.589333, ["y"] = 0.446667 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 220600, ["x"] = 0.589333, ["y"] = 0.446667 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.589333, ["y"] = 0.446667 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 80577 }, ["questLines"] = { { ["id"] = 5626, ["name"] = "Tired of Rest", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[80670] = { ["id"] = 80670, ["name"] = "Eyes of the Weaver", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "weekly", "repeatable", "meta" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 80670, 80671, 80672 }, ["description"] = "The Weaver's many eyes lurk throughout the city, learning as much as they can about Ansurek's machinations. Still, intelligence enough will not be sufficient to turn the tide against the Sureki forces. The Weaver requires someone willing to get their hands dirty. Lucky you, I suppose.", ["objectivesText"] = "Continue your efforts in aiding the Weaver in Azj-Kahet. Progress: Chk-chaah! You return at least. What news of the city do you bring me, hrm?", ["rewardXP"] = 17650, ["rewardItems"] = { 225571, 239125, 250769 }, ["rewardCurrencies"] = { { ["id"] = 3002, ["amount"] = 1500 } }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 220867, ["x"] = 0.552, ["y"] = 0.412 }, { ["mapID"] = 2255, ["npcID"] = 223750, ["x"] = 0.552, ["y"] = 0.412 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 224734, ["x"] = 0.564, ["y"] = 0.432 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 80592, 84682 }, ["questLines"] = { { ["id"] = 5558, ["name"] = "Underworld Operative", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255, ["db2QuestInfoID"] = 284, ["db2QuestInfoName"] = "Meta Quest" },
[80671] = { ["id"] = 80671, ["name"] = "Blade of the General", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "weekly", "repeatable", "meta" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 80670, 80671, 80672 }, ["description"] = "Even now, General Anub'azal's forces work tirelessly to ensure the security of Azj-Kahet. Ansurek's reach extends to every corner of her domain. The General seeks to undermine her military authority. If we stretch her resources thin, then we may find new opportunities to strike.", ["objectivesText"] = "Continue your efforts in aiding the General in Azj-Kahet. Progress: Hrmph. It is about time that you've returned. What news?", ["rewardXP"] = 17650, ["rewardItems"] = { 225572, 239122, 250767 }, ["rewardCurrencies"] = { { ["id"] = 3003, ["amount"] = 1500 } }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 220867, ["x"] = 0.552, ["y"] = 0.412 }, { ["mapID"] = 2255, ["npcID"] = 223750, ["x"] = 0.552, ["y"] = 0.412 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 224729, ["x"] = 0.558, ["y"] = 0.422 }, { ["mapID"] = 2255, ["npcID"] = 229184, ["x"] = 0.558, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 80592, 84682 }, ["questLines"] = { { ["id"] = 5558, ["name"] = "Underworld Operative", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255, ["db2QuestInfoID"] = 284, ["db2QuestInfoName"] = "Meta Quest" },
[80672] = { ["id"] = 80672, ["name"] = "Hand of the Vizier", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "weekly", "repeatable", "meta" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 80670, 80671, 80672 }, ["description"] = "The Vizier works even now to spread our conspiracy's influence amongst the well-to-do of Azj-Kahet's elite. Given his position, though, he can offer little in the way of direct support. That is where you come in. Your growing reputation precedes you; you can move in ways that the Vizier cannot. Just take care not to get eaten, hrm?", ["objectivesText"] = "Continue your efforts in aiding the Vizier in Azj-Kahet. Progress: I fear that our task grows more arduous with each passing day. I hope you are not wasting time.", ["rewardXP"] = 17650, ["rewardItems"] = { 210796, 210799, 210802, 210805, 210808, 210930, 210933, 210936, 212664, 212667, 224828, 225573, 228950, 228952, 239124, 250768 }, ["rewardCurrencies"] = { { ["id"] = 3004, ["amount"] = 1500 } }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 220867, ["x"] = 0.552, ["y"] = 0.412 }, { ["mapID"] = 2255, ["npcID"] = 223750, ["x"] = 0.552, ["y"] = 0.412 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 224733, ["x"] = 0.562, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 80592, 84682 }, ["questLines"] = { { ["id"] = 5558, ["name"] = "Underworld Operative", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255, ["db2QuestInfoID"] = 284, ["db2QuestInfoName"] = "Meta Quest" },
[80673] = { ["id"] = 80673, ["name"] = "Runway Scare-a-way", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 80673, 80677, 80678, 82810, 82813 }, ["description"] = "'Lo there. Me and Mags are generally in charge of clearing the sky in this area during our Lamplighting route. If we don't cull the moths in the area, they start spreading up towards the skydocks and start laying eggs in the machinery of our ships. Unfortunately we're not as spry as we used to be. Could you lend a helping hand? They're pretty frail so they'll squish easily to any high velocity flight. Or you could just smack 'em the old-fashioned way.", ["objectivesText"] = "Kill 25 moths either by flying through them or killing them normally. Progress: Nasty critters...", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 220718, ["x"] = 0.604, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 220718, ["x"] = 0.604, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78658 }, ["questLines"] = { { ["id"] = 5609, ["name"] = "Memories of the Sky", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[80676] = { ["id"] = 80676, ["name"] = "Defragmenting Memory", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80576, 80577, 80578, 80593, 80676, 80682, 81613, 82144, 82224 }, ["series"] = { 80577, 81613 }, ["description"] = "My oath is to be a compiler. I collect and tell the stories of our people. < Brennok sighs.> Is there wisdom in stories told by someone who never lived them? I've never had an adventure. I was afraid to overwrite the stories entrusted to me. So I started transcribing them into a book I hid here. Each time we returned to Shadowvein Point, I added more. I was going to leave and pass on the book, but scorpids ransacked it. Please, find the missing pages before they stuff them into their nests.", ["objectivesText"] = "Collect 100 Missing Pages of Brennok 's book. Progress: Thousands of stories, now they're probably lining some animal's den...", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["rewardItems"] = { 220999 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 220597, ["x"] = 0.613143, ["y"] = 0.446 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 220597, ["x"] = 0.613143, ["y"] = 0.446 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.613143, ["y"] = 0.446 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 80576 }, ["questLines"] = { { ["id"] = 5626, ["name"] = "Tired of Rest", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[80677] = { ["id"] = 80677, ["name"] = "Torching Lights", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 80673, 80677, 80678, 82810, 82813 }, ["description"] = "No matter how many moths we swat, if we don't take care of the eggs they'll just continue to be a problem. Take this firearm, use it to torch some of the eggs on the top of the mire's canopy.", ["objectivesText"] = "Torch 15 moth eggs . Progress: Watch the torch trigger, it's an older piece.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 219943 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 220718, ["x"] = 0.604, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 220718, ["x"] = 0.604, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78658 }, ["questLines"] = { { ["id"] = 5609, ["name"] = "Memories of the Sky", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[80678] = { ["id"] = 80678, ["name"] = "Time Lost", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 80673, 80677, 80678, 82810, 82813 }, ["description"] = "Now that the job's done -- one thing I've always done on this route is muck around for some of the valuables that fall from the docks. As things get moved onto ships small items can fall off. Sometimes people chuck 'em for luck or in rage, and the like. But some of those items have memories in 'em. Things so precious that losing it might as well be losing part of your heart. If you could help me look I'd be grateful.", ["objectivesText"] = "Find 6 lost mementos. Progress: What'd you find?", ["rewardGold"] = 169800, ["rewardXP"] = 11765, ["rewardItems"] = { 219524, 219809, 219810, 219811, 219812, 219813, 219814, 219815, 219816 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 220718, ["x"] = 0.604, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 220718, ["x"] = 0.604, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 80673, 80677 }, ["questLines"] = { { ["id"] = 5609, ["name"] = "Memories of the Sky", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[80679] = { ["id"] = 80679, ["name"] = "Stuffed Lynx Toy", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 80679 }, ["objectivesText"] = "Progress: That item in your pack looks familiar...", ["rewardGold"] = 29200, ["rewardXP"] = 1470, ["rewardItems"] = { 219105, 219809 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 218486, ["x"] = 0.432, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 218486, ["x"] = 0.432, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 80678 } },
