[80682] = { ["id"] = 80682, ["name"] = "One Last Story", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80576, 80577, 80578, 80593, 80676, 80682, 81613, 82144, 82224 }, ["series"] = { 82144 }, ["description"] = "Well, it's time. I'll be holding the recitation at the mine entrance. I'll see you there, though don't feel obligated to stay the whole time. I'll leave my book for Haimaz to find. She'll take care of it. After the ceremony, I would like to say goodbye properly. Meet me by the bridge outside of town. I'll head there after the recitation.", ["objectivesText"] = "Attend the recitation.", ["rewardGold"] = 154900, ["rewardXP"] = 4960, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 220597, ["x"] = 0.613143, ["y"] = 0.446 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 220600, ["x"] = 0.589333, ["y"] = 0.446667 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.613143, ["y"] = 0.446 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 80593 }, ["questLines"] = { { ["id"] = 5626, ["name"] = "Tired of Rest", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
