[80689] = { ["id"] = 80689, ["name"] = "Tending to Ausgazur", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80392, 80401, 80402, 80404, 80405, 80406, 80407, 80408, 80689 }, ["description"] = "Assigned tasks complete! I'll check back on these folks on my next scheduled patrol. There is one more earthen I must tend to today. He was... he is very special to me. You've been an especially considerate colleague, so I'd like for you to see him. Let us travel west a bit, closer to the falls.", ["objectivesText"] = "Meet Batzvara in Shimmermist Falls.", ["rewardGold"] = 77400, ["rewardXP"] = 2480, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 219899, ["x"] = 0.441, ["y"] = 0.368 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 220784, ["x"] = 0.419, ["y"] = 0.4 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.441, ["y"] = 0.368 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 80404 }, ["questLines"] = { { ["id"] = 5620, ["name"] = "The Caretaker of Brunwin's Terrace", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
