[81510] = { ["id"] = 81510, ["name"] = "Ship It!", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 81510 }, ["description"] = "What a haul! I was able tae give a bit of what we found tae Dagran so he could finish off one of his projects. He should be here any minute. Ah, I can't hold back. Surprise! It's a gift tae help you get around.", ["objectivesText"] = "Speak with Brann Bronzebeard Progress: Wait 'till ye see what Dagran has cooked up.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 219391 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 206017, ["x"] = 0.475, ["y"] = 0.445 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 206017, ["x"] = 0.475, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 81514 }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
