[81514] = { ["id"] = 81514, ["name"] = "Bountiful Delves", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 81514 }, ["description"] = "We're going tae need lots of resources to fight off Xal'atath. Lucky for you, we've uncovered a source! Some delves we've found are \"bountiful\" on account of the baddies there hoardin' more treasure. This treasure can only be unlocked with special keys found throughout Khaz Algar. Keys and key fragments can be found all about the world. Hunt them down and dive into a bountiful delve!", ["objectivesText"] = "Complete Special Assignment World Quests, World Activities, or Weekly Quests to recover a Restored Coffer Key or Coffer Key Shards to unlock a chest within a Bountiful Delve. Progress: Did ye find the key yet?", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 219391 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 25 }, { ["id"] = 3008, ["amount"] = 15 } }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 206017, ["x"] = 0.475, ["y"] = 0.445 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 206017, ["x"] = 0.475, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 83315 } },
[81555] = { ["id"] = 81555, ["name"] = "Wet Work: Tithe to Kill", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 80573, 81470, 81471, 81472, 81473, 81475, 81476, 81477, 81478, 81479, 81480, 81481, 81482, 81483, 81484, 81487, 81488, 81489, 81490, 81491, 81492, 81493, 81494, 81495, 81496, 81497, 81498, 81499, 81500, 81501, 81502, 81503, 81504, 81505, 81506, 81555 }, ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 217996 }, ["starts"] = { { ["x"] = 0.415, ["y"] = 0.224, ["mapID"] = 2213, ["npcID"] = 224190 } }, ["ends"] = { { ["x"] = 0.415, ["y"] = 0.224, ["mapID"] = 2213, ["npcID"] = 224190 } }, ["coords"] = { ["mapID"] = 2213, ["x"] = 0.415, ["y"] = 0.224 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14753 } }, ["questGiverID"] = 224190, ["questTurnInID"] = 224190, ["questType"] = "standard", ["sourceQuests"] = { 78393, 80544, 80545, 80546 }, ["questLines"] = { { ["id"] = 5573, ["name"] = "The Severed Threads", ["orderIndex"] = 34, ["flags"] = 0 } }, ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 1, ["amount"] = 4, ["objectID"] = 217996 } }, ["db2LabelIDs"] = { 3555 }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2213 },
[81556] = { ["id"] = 81556, ["name"] = "Foreign Fog", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 81556, 81557, 81558, 81559 }, ["description"] = "Pleasure to meet you, adventurer. I wonder if you might be willing to help me with some research? I'm sure you've noticed the fog beasts that have recently started encroaching upon this area. People see them as a bad omen, they always seem to show up during periods of ecological imbalance. I disagree with this assertion. Still as an expert in all vapor-based magics, I've been hired to find out where they're coming from so they can be cut off at the source.", ["objectivesText"] = "Place the fog collector and collect fog samples from different areas occupied by fog beasts. Progress: Have you collected the fog samples?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 221043, ["x"] = 0.567, ["y"] = 0.632 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 221043, ["x"] = 0.567, ["y"] = 0.632 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.567, ["y"] = 0.632 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79573, 80434 }, ["questLines"] = { { ["id"] = 5655, ["name"] = "Into the Fog", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[81557] = { ["id"] = 81557, ["name"] = "Fog Tags", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 81556, 81557, 81558, 81559 }, ["description"] = "While I analyze these fog samples, I have another task for you. My employers have asked me to figure out where these fog beasts are coming from. I've developed these trackers. If you could, please attach them to an assortment of fog beasts. You'll have to get close, so... be careful. Hopefully they don't mind it too much!", ["objectivesText"] = "Attach trackers to fog beasts in and around Taelloch. Progress: Have you attached all the trackers?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 219469 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 221043, ["x"] = 0.567, ["y"] = 0.632 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 221043, ["x"] = 0.567, ["y"] = 0.632 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.567, ["y"] = 0.632 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 81556 }, ["questLines"] = { { ["id"] = 5655, ["name"] = "Into the Fog", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[81558] = { ["id"] = 81558, ["name"] = "Unnatural Predators", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 81556, 81557, 81558, 81559 }, ["description"] = "It would be no use tagging fog beasts to study if they all were to die, would it? Could you clear out some of the aggressive deepflayers that have flocked to feast on the fog beasts? They'll ruin my data if left unchecked, I'm sure of it.", ["objectivesText"] = "Kill Deepflayer Hunters . Progress: Have you taken out the deepflayers?", ["rewardGold"] = 292100, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 221043, ["x"] = 0.567, ["y"] = 0.632 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 221043, ["x"] = 0.567, ["y"] = 0.632 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.567, ["y"] = 0.632 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 81556 }, ["questLines"] = { { ["id"] = 5655, ["name"] = "Into the Fog", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[81559] = { ["id"] = 81559, ["name"] = "Fog Follower", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 81556, 81557, 81558, 81559 }, ["description"] = "With the trackers attached, we should be able to find out where the fog beasts are coming from. The trackers leave a residue in the air. It's invisible to the naked eye, but I can use the mists to reveal it in places where there's a high enough concentration. Theoretically, this should lead us to the places they most frequent. Maybe a nest! That I'll then have to report to my employer... hm. Anyway. Let's see what we can find.", ["objectivesText"] = "Help Noli find the source of the fog beasts with her mist tracking ability. Progress: I know we'll be able to find them. Let's keep looking!", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 180 }, { ["id"] = 2902, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 221043, ["x"] = 0.567, ["y"] = 0.632 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 221043, ["x"] = 0.567, ["y"] = 0.632 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.567, ["y"] = 0.632 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 81557, 81558 }, ["questLines"] = { { ["id"] = 5655, ["name"] = "Into the Fog", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[81560] = { ["id"] = 81560, ["name"] = "Winter's Presents", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 81560 }, ["description"] = "I hear Greatfather Winter has put presents for everyone under the tree in Ironforge. You should definitely check it out. I'm sure Greatfather Winter has some presents with your name on them.", ["objectivesText"] = "Speak with Greatfather Winter . He is located near the Smokywood Pastures vendor area in Ironforge.", ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 220307, ["x"] = 0.46, ["y"] = 0.546 }, { ["mapID"] = 2339, ["npcID"] = 220865, ["x"] = 0.566667, ["y"] = 0.286 }, { ["mapID"] = 2339, ["npcID"] = 220870, ["x"] = 0.41, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 87, ["npcID"] = 13444, ["x"] = 0.352615, ["y"] = 0.627385 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.546 }, ["mapCandidates"] = { ["npc"] = { 87, 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard" },
