[81564] = { ["id"] = 81564, ["name"] = "The Story of Noodles", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 81564 }, ["description"] = "Ah, being here again makes me hungry. Have I ever told you about the time I learned to cook from Sungshin Ironpaw? Perhaps you can experience it for yourself. Say the word and I will take you to a version of this timeline where you--yes YOU--ran your own noodle stand! It all began with the Lin family's secret recipe...", ["objectivesText"] = "Talk to Grandmaster Jakkus to complete the scenario Finding the Secret Ingredient. Progress: Mmm, noodles...", ["rewardGold"] = 625600, ["rewardXP"] = 5990, ["starts"] = { { ["mapID"] = 376, ["npcID"] = 220895, ["x"] = 0.532, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 376, ["npcID"] = 220895, ["x"] = 0.532, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 376, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 376 }, ["zone"] = { 5805 } }, ["questType"] = "standard" },
