[81712] = { ["id"] = 81712, ["name"] = "Lisky Business", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 81693, 81712, 81713 }, ["description"] = "Hrandaz is going to have to wait. My beloved Lisky is missing! She went into this cave and hasn't come out. I think whatever's making that terrible stench drew her attention. Please, go in and find my Lisky ? She hasn't drawn the attention of the horrid creatures inside yet, but it's only a matter of time!", ["objectivesText"] = "Rescue Lisky from the cave. Progress: My sweet precious Lisky ! Please get her out of there.", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 220446, ["x"] = 0.629, ["y"] = 0.415 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 220446, ["x"] = 0.629, ["y"] = 0.415 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.629, ["y"] = 0.415 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 81693 }, ["questLines"] = { { ["id"] = 5622, ["name"] = "Frolicking in the Fetid Grotto", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[81713] = { ["id"] = 81713, ["name"] = "Oozemodious", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 81693, 81712, 81713 }, ["description"] = "I tried to get Lisky back myself, but she ran to the far end of the cave. The whole thing is full of disgusting masses of worms. As if they aren't bad enough, down the back there's a creature so vile and slimy and oozy that I ran for my life! No, I am not proud of leaving Lisky behind. I was just about to work up the courage to get back in there when you arrived. While you're looking for Lisky, you should dispose of those gross things in there! I'm pretty sure they're multiplying!", ["objectivesText"] = "Kill 6 slimes and Oozemodius . Progress: I am counting on you to do this dirty work. If I'm behind honest, I have an irrational fear of worms and sticky things. I much prefer dry, solid, gritty creatures. Especially if they have nice hard scales!", ["rewardGold"] = 584200, ["rewardXP"] = 12400, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 180 }, { ["id"] = 2902, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 220446, ["x"] = 0.629, ["y"] = 0.415 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 220446, ["x"] = 0.629, ["y"] = 0.415 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.629, ["y"] = 0.415 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 81693, 81712 }, ["questLines"] = { { ["id"] = 5622, ["name"] = "Frolicking in the Fetid Grotto", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
