[81869] = { ["id"] = 81869, ["name"] = "Can Catch More Fires with Honey", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2214, ["storyline"] = { 81692, 81751, 81869, 81896 }, ["description"] = "Crafting with flame demands a fuel that burns pure and has sustainable power. Among these, the honey created by Cinderwold bees stands out! A source of elemental fire, organic and untainted. I've longed for a supply of this honey, yet never had the chance to procure it. Take my harvesting device and gather a quantity for our purpose. We shall infuse it into your tinderbox. Exercise caution, for some of the earthen revere these bees as sacred creatures.", ["objectivesText"] = "Collect 10 Pure Fire Honey from the Overladen Drones in Cinderwold. Progress: Have you acquired the honey?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 219960, 220130 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 217128, ["x"] = 0.453, ["y"] = 0.32 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 217128, ["x"] = 0.453, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.453, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 81692 }, ["questLines"] = { { ["id"] = 5671, ["name"] = "Zone 3 Neck 2", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214, ["db2QuestHubAreaPoiID"] = 7911 },
[81886] = { ["id"] = 81886, ["name"] = "For the Alliance", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredRaces"] = { 85 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 79200, 79201, 79202, 79203, 79204, 81886, 81887, 83328 }, ["series"] = { 81887 }, ["description"] = "For the first time in our history, the outside world is ours to explore and experience. An off-island faction known as the Alliance came to the aid of our kin. Valiant and wise, the stalwart Alliance has extended an open hand to our people. Will you be among the first to accept and visit their lands, learn their histories and walk amongst their people? If that path calls to you, then I hope you'll return to share those experiences and show the earthen what the world has to offer.", ["objectivesText"] = "Meet Ambassador Moorgard at the Stormwind Embassy.", ["rewardGold"] = 5350, ["rewardXP"] = 175, ["rewardItems"] = { 23002, 23007, 23015, 23022, 37500, 42792, 42805, 42817, 42830, 65618, 65625, 65639, 65642, 66073, 94219, 108908, 108909, 108910, 108912, 108913, 108914, 108918, 108919, 116202, 151557, 157022, 157756, 157758, 161329, 165010, 165872, 166883, 168615, 168850, 169764, 174068, 174507, 204616, 204617, 204618, 204619, 223907, 241215 }, ["starts"] = { { ["x"] = 0.087, ["y"] = 0.496, ["mapID"] = 2322, ["npcID"] = 221890 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 133362, ["x"] = 0.530667, ["y"] = 0.150667 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.530667, ["y"] = 0.150667 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questGiverID"] = 221890, ["questType"] = "standard", ["sourceQuests"] = { 79204 }, ["questLines"] = { { ["id"] = 5593, ["name"] = "New Awakenings", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 84 },
[81887] = { ["id"] = 81887, ["name"] = "Stranger in a Strange Land", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredRaces"] = { 85 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 79200, 79201, 79202, 79203, 79204, 81886, 81887, 83328 }, ["series"] = { 81886 }, ["description"] = "Welcome to Stormwind, <race>. I invite you to explore our fair city. Say, you look like someone who appreciates fine stonework! We have many impressive stone buildings and walls. Ah, but that can wait, a bronze dragon has asked to talk to you. She is sitting under the nearby tree, on an hourglass of all things! After that, an emissary of yours is waiting to welcome you to the city. Sounds like a busy day for you! Have a pleasant stay, <name>!", ["objectivesText"] = "Talk to Chromie in Stormwind City. Progress: Greetings, <name>.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 246740, 246795 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 133362, ["x"] = 0.530667, ["y"] = 0.150667 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 224806, ["x"] = 0.56, ["y"] = 0.175 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.530667, ["y"] = 0.150667 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["sourceQuests"] = { 81886 }, ["questLines"] = { { ["id"] = 5593, ["name"] = "New Awakenings", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiUiMapID"] = 84 },
[81888] = { ["id"] = 81888, ["name"] = "For the Horde", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 79200, 79201, 79202, 79203, 79204, 81888, 81889, 83328 }, ["series"] = { 81889 }, ["description"] = "For the first time in our history, the outside world is ours to explore and experience. An off-island faction known as the Horde came to the aid of our kin. Spiritual and mighty, the honorable Horde has opened their hand to our people. Will you be among the first to go where no earthen has ever gone? To walk their lands, hear their songs and learn from their people? If that path calls to you, then I hope you'll return to share those experiences and show the earthen what the world has to offer.", ["objectivesText"] = "Meet with Ambassador Blackguard at the Orgrimmar Embassy.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 23002, 23007, 23015, 23022, 29928, 29930, 29931, 29934, 29938, 29941, 29943, 29945, 37956, 37964, 37998, 38006, 38041, 38048, 38081, 38102, 38110, 57509, 57510, 57511, 57512, 65680, 65701, 65719, 65728, 66073, 94220, 111535, 111536, 111537, 111538, 111539, 111540, 111541, 111542, 116202, 118761, 118762, 118763, 118764, 118765, 131486, 131696, 131697, 151557, 155662, 157028, 157757, 157759, 161328, 165001, 165871, 166883, 167169, 168615, 168850, 169765, 174069, 174508, 223907, 241215 }, ["starts"] = { { ["x"] = 0.087, ["y"] = 0.496, ["mapID"] = 2322, ["npcID"] = 221890 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 133407, ["x"] = 0.395, ["y"] = 0.794 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.794 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questGiverID"] = 221890, ["questType"] = "standard", ["sourceQuests"] = { 79204 }, ["questLines"] = { { ["id"] = 5593, ["name"] = "New Awakenings", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85 },
[81889] = { ["id"] = 81889, ["name"] = "Stranger in a Strange Land", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 79200, 79201, 79202, 79203, 79204, 81888, 81889, 83328 }, ["series"] = { 81888 }, ["description"] = "Hi. I'm Ambassador Blackguard . I am honored to welcome you to Orgrimmar, <race>. <He smiles unconvincingly.> As a lifetime of adventure unfolds before you, be assured that... uh... You know what? I've been saying this same greeting all day. Enough's enough. Talk to Chromie on top of the hourglass, then talk to your emissary. Run along.", ["objectivesText"] = "Talk to Chromie . Progress: Greetings, <name>.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 246740, 246795 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 133407, ["x"] = 0.395, ["y"] = 0.794 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 224807, ["x"] = 0.406, ["y"] = 0.802 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.794 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["sourceQuests"] = { 81888 }, ["questLines"] = { { ["id"] = 5593, ["name"] = "New Awakenings", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85 },
[81890] = { ["id"] = 81890, ["name"] = "Unfulfilled Requests", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2213, ["storyline"] = { 81890, 81928, 81959, 81962, 81963 }, ["series"] = { 81928 }, ["description"] = "I have heard the citizens of the Silken Ward are having trouble with a group of Ascended called the Pale Weavelashers. The new ward is supposed to be a fresh start for citizens of the capital, at least that is the way the Queen tells it. In actuality it is a way for her to tighten her grip on those she distrust. Meet with my assistant Sum'latha . I sent her there ahead of time to gather information. She can fill you in on any details.", ["objectivesText"] = "Meet with Sum'latha at the Silken Ward.", ["rewardGold"] = 30900, ["rewardXP"] = 1325, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 208782, ["x"] = 0.526667, ["y"] = 0.462667 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 221948, ["x"] = 0.514, ["y"] = 0.638 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.526667, ["y"] = 0.462667 }, ["mapCandidates"] = { ["npc"] = { 2213, 2255 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["sourceQuests"] = { 78384, 79573 }, ["nextQuests"] = { 81928 }, ["questLines"] = { { ["id"] = 5646, ["name"] = "Silken Ward", ["orderIndex"] = 0, ["flags"] = 1 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[81896] = { ["id"] = 81896, ["name"] = "New and Improved", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 81692, 81751, 81869, 81896 }, ["description"] = "I've completed the modifications. I must say, this is some of my finest work! Despite its modest design, a bit of cog grease and elbow dust has transformed it into a device that even the surliest of the flame worshippers could appreciate. If any of them want to know how it's done, send them my way.", ["objectivesText"] = "Accept the new improved Tinderbox from Kuldas.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 220157 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 217128, ["x"] = 0.453, ["y"] = 0.32 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 217128, ["x"] = 0.453, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.453, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 81751, 81869 }, ["questLines"] = { { ["id"] = 5671, ["name"] = "Zone 3 Neck 2", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214, ["db2QuestHubAreaPoiID"] = 7911 },
[81906] = { ["id"] = 81906, ["name"] = "Whispers from the Web", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 81906, 81908, 81909, 81910 }, ["description"] = "Hey! Hey! You won't believe me, but I found the cutest, fuzziest puppy! With a bell! Around its neck! It gave me this to give to you. Take it, I gotta go catch that puppy!", ["objectivesText"] = "Meet with Ct'nak in the Burrows of Azj-Kahet.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 219503, 220157, 220158, 220212, 220215, 220359 }, ["starts"] = { { ["x"] = 0.413, ["y"] = 0.531, ["mapID"] = 2215, ["npcID"] = 221867 } }, ["ends"] = { { ["x"] = 0.413, ["y"] = 0.531, ["mapID"] = 2215, ["npcID"] = 221867 } }, ["coords"] = { ["mapID"] = 2215, ["x"] = 0.413, ["y"] = 0.531 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14753 } }, ["questGiverID"] = 221867, ["questTurnInID"] = 221867, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5672, ["name"] = "Zone 3 Neck 3", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2216 },
[81908] = { ["id"] = 81908, ["name"] = "A Flame in the Dark", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 81906, 81908, 81909, 81910 }, ["description"] = "Contained within the Underkeep lies a tinderbox, once belonging to the late Aelric Leid. This item reeks of powerful, corruptive energy. Its close proximity has leeched out to touch many nerubians. Your task is to retrieve that box and deliver it to me. To be safe, gather any tinderboxes you may find--we'll destroy them all, just in case.", ["objectivesText"] = "Search various containers inside the Underkeep for 8 Unidentified Tinderboxes and Aelric's Corrupted Tinderbox . Progress: Did you find the tinderboxes?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 220212, 220215 }, ["starts"] = { { ["x"] = 0.469, ["y"] = 0.501, ["mapID"] = 2216, ["npcID"] = 221902 } }, ["ends"] = { { ["x"] = 0.469, ["y"] = 0.501, ["mapID"] = 2216, ["npcID"] = 221902 } }, ["coords"] = { ["mapID"] = 2216, ["x"] = 0.469, ["y"] = 0.501 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14753 } }, ["questGiverID"] = 221902, ["questTurnInID"] = 221902, ["questType"] = "standard", ["sourceQuests"] = { 81906 }, ["questLines"] = { { ["id"] = 5672, ["name"] = "Zone 3 Neck 3", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2216 },
[81909] = { ["id"] = 81909, ["name"] = "Absolute Power", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2215, ["storyline"] = { 81906, 81908, 81909, 81910 }, ["description"] = "The dark allure of this item surpasses my initial expectations. I can sense a surge of power coursing through me. We must delve deeper into its mysteries. However, it is unwise to discuss this matter openly. Follow me inside, where we may deliberate further.", ["objectivesText"] = "Discuss the tinderbox's destruction with Ct'nak . Progress: What's that you have there?", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 220158, 220212, 220215, 220359 }, ["starts"] = { { ["x"] = 0.469, ["y"] = 0.501, ["mapID"] = 2216, ["npcID"] = 221902 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 214380, ["x"] = 0.432, ["y"] = 0.564 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.564 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14753 } }, ["questGiverID"] = 221902, ["questType"] = "standard", ["sourceQuests"] = { 81908 }, ["questLines"] = { { ["id"] = 5672, ["name"] = "Zone 3 Neck 3", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[81910] = { ["id"] = 81910, ["name"] = "A Great Responsibility", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 81906, 81908, 81909, 81910 }, ["description"] = "To witness such corruption is deeply unsettling. Despite the dark energies intertwined with this tinderbox, there remains a flicker of the Sacred Flame, struggling to escape. I will not destroy that flicker, champion. Yet I dare not hold onto it any longer. Perhaps your purity of spirit can withstand the darkness it holds. Please, <name>, carry it with you. Protect that small spark of purity, and help it break free of the dark magic that ensnares it.", ["objectivesText"] = "Accept the tinderbox.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 220158, 220212, 220215, 220359 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 214380, ["x"] = 0.432, ["y"] = 0.564 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 214380, ["x"] = 0.432, ["y"] = 0.564 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.564 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 81909 }, ["questLines"] = { { ["id"] = 5672, ["name"] = "Zone 3 Neck 3", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[81912] = { ["id"] = 81912, ["name"] = "Flight Training 102", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 79107, 79124, 79129, 79140, 79145, 79146, 79147, 79156, 79157, 79475, 79476, 79477, 79480, 81912, 81913, 81914, 81915 }, ["series"] = { 79147, 79477, 81913, 81915 }, ["description"] = "Dunnae think I had nae noticed those rooks spittin' lightnin'. Sure beats tossin' hammers. But it won't mean nothin' if the Stormriders can't hit what they're fightin'. Let's test their aim. Got some gnomish contraptions here that'll project easy targets for practice. Take Shraubendre back out there an' show them how it's done!", ["objectivesText"] = "Help Kurdran train recruits in aerial targeting. Progress: Flyin' takes a firm hand. An' boy do these earthen have that!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 215211, ["x"] = 0.4685, ["y"] = 0.662 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 215211, ["x"] = 0.4685, ["y"] = 0.662 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.4685, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 79147 }, ["questLines"] = { { ["id"] = 5523, ["name"] = "Ties That Bind", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5523, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[81913] = { ["id"] = 81913, ["name"] = "Flight Training 103", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 79107, 79124, 79129, 79140, 79145, 79146, 79147, 79156, 79157, 79475, 79476, 79477, 79480, 81912, 81913, 81914, 81915 }, ["series"] = { 79147, 79477, 81912, 81915 }, ["description"] = "These recruits seem tae be up for a challenge. Let's find them somethin' with a little bite! I saw a poor giant just off shore bein' pestered by a swarm of flying devils. Let's see if these rooks can shoot the wings off 'em an' provide some relief. You and Shraubendre are settin' a good example for the rest. Keep it up!", ["objectivesText"] = "Help Kurdran train recruits in aerial combat.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 224161 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 215211, ["x"] = 0.4685, ["y"] = 0.662 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 214995, ["x"] = 0.522667, ["y"] = 0.489 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.4685, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 81912 }, ["questLines"] = { { ["id"] = 5523, ["name"] = "Ties That Bind", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5523, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[81914] = { ["id"] = 81914, ["name"] = "Dhar Oztan", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 79107, 79124, 79129, 79140, 79145, 79146, 79147, 79156, 79157, 79475, 79476, 79477, 79480, 81912, 81913, 81914, 81915 }, ["series"] = { 79124 }, ["description"] = "I love the stormrooks. Taking care of them was my directive, so they're all I've ever known. But even so, there are questions about them that even I don't have answers to. Baelgrim--Stormward Baelgrim--he was the expert. I'd pester him about them at every opportunity. And he shared what he could. He told me once about summoning rooks at Dhar Oztan. It's an old Stormrider outpost that predates the Stormperch. If you want to know more about stormrooks, that's where we need to go.", ["objectivesText"] = "Travel to Dhar Oztan.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 215039, ["x"] = 0.266, ["y"] = 0.594667 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 214995, ["x"] = 0.522667, ["y"] = 0.489 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.266, ["y"] = 0.594667 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 79107 }, ["questLines"] = { { ["id"] = 5523, ["name"] = "Ties That Bind", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5523, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[81915] = { ["id"] = 81915, ["name"] = "Home to Roost", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 79107, 79124, 79129, 79140, 79145, 79146, 79147, 79156, 79157, 79475, 79476, 79477, 79480, 81912, 81913, 81914, 81915 }, ["series"] = { 79147, 79477, 81912, 81913 }, ["description"] = "You've already done us a great service here, <name>. We will carry on by the example you have set. You should return to Dhar Oztan and see to these new Stormriders you've recruited. They will undoubtedly benefit from the same diligence you have shown here. And, you can get away from these two and their posturing. I envy you, <name>...", ["objectivesText"] = "Return to Dhar Oztan.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 215277, ["x"] = 0.451, ["y"] = 0.569 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 215039, ["x"] = 0.266, ["y"] = 0.594667 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.451, ["y"] = 0.569 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 79140, 79145 }, ["questLines"] = { { ["id"] = 5523, ["name"] = "Ties That Bind", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5523, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[81928] = { ["id"] = 81928, ["name"] = "The Voice of the People", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 81890, 81928, 81959, 81962, 81963 }, ["series"] = { 81890 }, ["description"] = "As you might have heard, things haven't gone as intended for the citizens of the Silken Ward. The Pale Weavelashers have been keeping a tight grasp on the citizens. I wasn't able to find much before an Ascended kicked me out for snooping around. You are a fresh face, go around the Silken Ward and speak to the citizens, see if you can find a way to help them. Also seek out Alchemist Talbax . I heard his name spoken a few times. He could be a useful contact.", ["objectivesText"] = "Speak with 3 Silken Ward citizens. Progress: The Silken Ward was supposed to be a new start for these people. Let's see what we can do to help.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 221948, ["x"] = 0.514, ["y"] = 0.638 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 221842, ["x"] = 0.598, ["y"] = 0.54 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.514, ["y"] = 0.638 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 81890, 83324 }, ["questLines"] = { { ["id"] = 5646, ["name"] = "Silken Ward", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[81929] = { ["id"] = 81929, ["name"] = "Here's the Plan", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 81929, 81945, 81950, 81964, 81965, 81969, 82248, 82268, 82284 }, ["series"] = { 81945, 82248 }, ["description"] = "<name>, the time has come to deal with the nerubian army. General Zev'kall is massing a sizeable force to the east. He intends to breach the wall and invade Hallowfall. There isn't much time. We do not have the strength for an all-out assault. To that end, the Weaver has sent Gazlowe here to assist us. I'm willing to do what it takes to save my people. And as fate would have it, I have a personal matter to attend to while we are there.", ["objectivesText"] = "Help Faerin prepare while she explains her plan. Progress: I'm learning not all nerubians are bad or the same. I just hope the three of us are enough.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 211409, ["x"] = 0.592, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 211409, ["x"] = 0.592, ["y"] = 0.194 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 82248 }, ["questLines"] = { { ["id"] = 5562, ["name"] = "All Good Things...", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[81930] = { ["id"] = 81930, ["name"] = "The War Within", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 9310, ["mapID"] = 84, ["storyline"] = { 78529, 78714, 78715, 78716, 78717, 78718, 78719, 78721, 78722, 79105, 79106, 80321, 80500, 81930, 81966 }, ["description"] = "People are experiencing visions of a \"Radiant Song\" all across Azeroth. We have reason to believe it's a warning of some kind. Meet me in Silithus. Perhaps Azeroth's Speaker can shed some light on what this warning might mean.", ["objectivesText"] = "Go to Silithus to talk with Jaina about the visions spreading across Azeroth. Progress: These visions grow stronger by the day.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 135539, 227669 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 221967, ["x"] = 0.624667, ["y"] = 0.725333 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 213625, ["x"] = 0.418, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.624667, ["y"] = 0.725333 }, ["mapCandidates"] = { ["npc"] = { 81, 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5513, ["name"] = "Visions of Azeroth", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5638, ["name"] = "Dalaran Intro", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 235, ["title"] = "Visions of Azeroth", ["questLineID"] = 5513, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5513, ["questLineOrder"] = 1 }, { ["id"] = 261, ["title"] = "Expansion Intro Skip", ["questLineID"] = 5638, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 81 },
[81945] = { ["id"] = 81945, ["name"] = "To Arathi's End", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 81929, 81945, 81950, 81964, 81965, 81969, 82248, 82268, 82284 }, ["series"] = { 81929, 82248 }, ["description"] = "We will regroup on the outskirts of Arathi's End to the east. Their forces are nearly ready and there isn't much time, <name>.", ["objectivesText"] = "Regroup with Faerin and Gazlowe at Arathi's End.", ["rewardGold"] = 29200, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 211409, ["x"] = 0.592, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 221977, ["x"] = 0.636, ["y"] = 0.178 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 81929 }, ["questLines"] = { { ["id"] = 5562, ["name"] = "All Good Things...", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[81950] = { ["id"] = 81950, ["name"] = "BOOM Treats!", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 81929, 81945, 81950, 81964, 81965, 81969, 82248, 82268, 82284 }, ["description"] = "If we're gonna stop this invasion, we need to take out their big guns. In this case, big guns equals ballistae. Remember how I had ya pick up them Betelsnax? Yeah, I didn't do that for no good reason. See, the nerubians here have their beetles haul their bombs. And those haulers love them some snacks. I mean, who doesn't? You place the snacks next to a ballista, then a bomb beetle walks up, and BOOM!", ["objectivesText"] = "Place Betelsnax to lure bomb-laden beetles into destroying Nerubian Ballistae. Progress: Those ballista ain't gonna destroy themselves, ya know?!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 221977, ["x"] = 0.636, ["y"] = 0.178 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 221977, ["x"] = 0.636, ["y"] = 0.178 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.636, ["y"] = 0.178 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questTurnInID"] = 221977, ["questType"] = "standard", ["sourceQuests"] = { 81945 }, ["questLines"] = { { ["id"] = 5562, ["name"] = "All Good Things...", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[81959] = { ["id"] = 81959, ["name"] = "Collecting a Concoction", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 81890, 81928, 81959, 81962, 81963 }, ["description"] = "The Pale Weavelashers did indeed throw my alchemical supply down the cliffside. The potions will give the citizens of the Silken Ward the edge they need to rise up. I need someone to go down the Whispering Cliffs and collect any bottles that haven't broken open. I would go myself but the kobyss have made the area a hunting ground and I'm no fighter. This would be a simple task for one such as yourself, eh?", ["objectivesText"] = "Collect 8 Brightshade Potions in the Whispering Cliffs. Progress: The kobyss are beyond a nuisance. I need to get my Brightshade Potions back.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["rewardItems"] = { 221755 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 221842, ["x"] = 0.598, ["y"] = 0.54 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 221842, ["x"] = 0.598, ["y"] = 0.54 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 81928 }, ["questLines"] = { { ["id"] = 5646, ["name"] = "Silken Ward", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[81962] = { ["id"] = 81962, ["name"] = "A Nudge in the Right Direction", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 81890, 81928, 81959, 81962, 81963 }, ["description"] = "Wonderful, wonderful! Now that we have recovered my Brightshade Potions, I want you to go around the Silken Ward and show them off! This will draw the ire of the Pale Weavelashers, I'm sure, but I want to show the populace that we don't need to live under their thumb. With a little aggressive motivation we can strike out on our own. Yes, yes, this will do! Go around the Silken Ward and kill Pale Weavelashers. My potions will provide an extra kick the citizens will certainly love.", ["objectivesText"] = "Kill 10 Pale Weavelashers around the Silken Ward. Progress: Be wary of any side effects the potions might have so I can document them.", ["rewardGold"] = 292100, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 221842, ["x"] = 0.598, ["y"] = 0.54 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 221842, ["x"] = 0.598, ["y"] = 0.54 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 81959 }, ["questLines"] = { { ["id"] = 5646, ["name"] = "Silken Ward", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[81963] = { ["id"] = 81963, ["name"] = "The Fruits of Our Labor", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 81890, 81928, 81959, 81962, 81963 }, ["description"] = "You put on quite the show, yes? The orders are already coming in. The citizens can't wait to get their mandibles on the potions. I have one final task for you. I want you to take these latest orders and deliver them. You will accept, yes? The citizens are stirring. Now is the time to show the Pale Weavelashers what we can do. If any try and stop you, you know what to do.", ["objectivesText"] = "Deliver 3 Brightshade Potions to Silken Ward citizens. Progress: The time is now, friend. The Pale Weavelashers aren't unstoppable.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["rewardItems"] = { 228443, 228444 }, ["rewardChoices"] = { 228443, 228444 }, ["rewardCurrencies"] = { { ["id"] = 3002, ["amount"] = 500 }, { ["id"] = 3056, ["amount"] = 35 } }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 221842, ["x"] = 0.598, ["y"] = 0.54 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 221842, ["x"] = 0.598, ["y"] = 0.54 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 81962 }, ["questLines"] = { { ["id"] = 5646, ["name"] = "Silken Ward", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[81964] = { ["id"] = 81964, ["name"] = "The Blacksmith's Fate", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 81929, 81945, 81950, 81964, 81965, 81969, 82248, 82268, 82284 }, ["series"] = { 81965, 81969, 82268, 82284 }, ["description"] = "While we're here, I must find out what happened to my old friend, Ryton Blackholme. He was Hallowfall's finest blacksmith--and he was taken in a surprise nerubian attack. I could not save him. I searched for him, but found nothing except for his bloodied helm. I'd given up hope. But recently, I heard rumor about a blacksmith from a survivor who'd been pulled down off the Aegis Wall. Could it be Ryton? Will you help me, <name>?", ["objectivesText"] = "Assist Faerin Lothar to uncover the fate of Ryton Blackholme. Progress: Thank you for your help with this, <name>.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 223157 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 221961, ["x"] = 0.636, ["y"] = 0.178 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 221961, ["x"] = 0.636, ["y"] = 0.178 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.636, ["y"] = 0.178 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questTurnInID"] = 221961, ["questType"] = "standard", ["sourceQuests"] = { 81945 }, ["questLines"] = { { ["id"] = 5562, ["name"] = "All Good Things...", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[81965] = { ["id"] = 81965, ["name"] = "Invasion Disruption", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 81929, 81945, 81950, 81964, 81965, 81969, 82248, 82268, 82284 }, ["series"] = { 81964, 81969, 82268, 82284 }, ["description"] = "While we cannot eliminate the nerubian threat here, we can disrupt their invasion plans. There are any number of opportunities to accomplish our goal. Let's see what kind of damage we can do.", ["objectivesText"] = "Disrupt the nerubian invasion efforts at Arathi's End. Progress: The more we can accomplish here, the safer we make things for Hallowfall.", ["rewardGold"] = 774500, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 221961, ["x"] = 0.636, ["y"] = 0.178 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 221961, ["x"] = 0.636, ["y"] = 0.178 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.636, ["y"] = 0.178 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questTurnInID"] = 221961, ["questType"] = "standard", ["sourceQuests"] = { 81945 }, ["questLines"] = { { ["id"] = 5562, ["name"] = "All Good Things...", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
