[81969] = { ["id"] = 81969, ["name"] = "An End to the End", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2274, ["storyline"] = { 81929, 81945, 81950, 81964, 81965, 81969, 82248, 82268, 82284 }, ["series"] = { 81964, 81965, 82268, 82284 }, ["description"] = "I want to honor my friend. But first, we need to deal the killing blow to this Light-forsaken place. It's known that General Zev'kall has been overseeing the creation of a monstrosity... a void-corrupted, malformed nerubian. The scouting report pinpointed the location at the top of the canyon. We're going to deprive him of his horrific pet. That should put an end to his plans to invade Hallowfall. At least for a little while longer.", ["objectivesText"] = "Work with Faerin and Gazlowe to take down the monstrosity known as Surek'tak the Sundered .", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 5579, 5580, 10752, 24351, 24352, 24353, 24354, 33226, 37277, 37447, 37475, 37545, 37941, 37984, 38028, 38092, 38661, 39113, 39114, 39118, 39124, 39125, 39127, 39789, 39825, 39858, 39893, 45588, 45608, 45614, 45618, 46320, 46321, 46322, 46323, 57393, 61626, 61628, 61630, 61632, 63018, 63019, 63020, 63021, 63022, 81769, 81770, 81771, 81772, 81773, 81774, 81775, 81776, 81777, 85575, 87379, 87380, 87381, 87382, 87383, 87384, 87385, 87386, 87387, 129258, 129259, 129260, 129346, 129347, 129348, 129349, 131586, 133006, 133007, 133008, 133009, 133010, 133011, 133012, 133013, 133014, 133016, 133040, 133041, 133042, 133043, 133044, 133045, 133046, 133047, 133048, 133050, 133699, 141393, 141405, 141618, 141619, 155385, 155386, 155387, 155404, 155405, 155406, 155407, 155408, 174959, 175176, 175177, 175178, 175179, 175208, 175209, 175210, 175211, 175442, 175443, 175444, 175445, 175647, 175660, 175661, 175662, 202201, 219314, 221154, 223424, 223441, 223456, 223464, 246445, 246936, 248621, 249