[81990] = { ["id"] = 81990, ["name"] = "The Light's Call", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 81990 }, ["description"] = "Attention, residents of Hallowfall ! Urgent assistance is needed to reclaim the shadowed outskirts. As darkness grips countless family farms, your aid is needed to ignite the sacred flame and restore safety to our lands.", ["objectivesText"] = "Report to Keyrra Flamestonge for further service.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213145, ["x"] = 0.418, ["y"] = 0.54 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 215527, ["x"] = 0.654, ["y"] = 0.322 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["nextQuests"] = { 76588, 79232 }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[81993] = { ["id"] = 81993, ["name"] = "The Stormrider's Bond", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 81993 }, ["series"] = { 81994 }, ["description"] = "This beauty is no ordinary gryphon. It's got the storm within it. I've been trying all day tae calm it down. It reminds me of an ol' Wildhammer myth. Stormrooks, they were called. Only able to be bonded by gryphon riders of great renown. If we can show ye got the spirit of the storm, maybe it'll open up tae ye. Try proving yerself in battle.", ["objectivesText"] = "Collect 50 Storm Spirits by slaying powerful creatures of the Dragon Isles. Progress: I've never met such a stubborn gryphon before!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 192615, 192663, 198970, 220737 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 222277, ["x"] = 0.383, ["y"] = 0.945 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 222277, ["x"] = 0.383, ["y"] = 0.945 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.383, ["y"] = 0.945 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
[81994] = { ["id"] = 81994, ["name"] = "A Sacred Connection", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 81994 }, ["series"] = { 81993 }, ["description"] = "Aye, the stormrook is beginning to take a liking to us. But the bond between rider and gryphon is forged over many trials. Ye may have the spirit of the storm, but let's show how ye mastered it. Time to really prove yer mettle in battle.", ["objectivesText"] = "Collect 500 Storm Spirits by slaying powerful creatures of the Dragon Isles. Progress: I think I'm starting tae get this one to trust me.", ["rewardGold"] = 1123600, ["rewardXP"] = 2830, ["rewardItems"] = { 192786, 201815, 202173, 220737 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 222277, ["x"] = 0.383, ["y"] = 0.945 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 222277, ["x"] = 0.383, ["y"] = 0.945 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.383, ["y"] = 0.945 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 81993, 83024 }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
[81999] = { ["id"] = 81999, ["name"] = "New Home, New Candle!", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 79504, 79505, 79507, 79508, 79510, 79552, 79554, 79555, 79556, 79565, 79680, 79681, 79682, 79683, 79998, 80000, 80058, 80202, 80378, 81999 }, ["description"] = "Janky hears there are giant fire bees on surface. Fire bees make fire beeswax, yes? What if make candle from fire bee wax? What that be like? Janky must know!", ["objectivesText"] = "Meet Janky in the Cinderwold. Progress: What wait for?", ["rewardGold"] = 30900, ["rewardXP"] = 1240, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 216567, ["x"] = 0.461333, ["y"] = 0.305333 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 219674, ["x"] = 0.72, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.461333, ["y"] = 0.305333 }, ["mapCandidates"] = { ["npc"] = { 2214, 2248 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5627, ["name"] = "Kobold Culture and Integration", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248, ["db2QuestHubAreaPoiID"] = 7911 },
[82007] = { ["id"] = 82007, ["name"] = "Tale of Tails", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 82007 }, ["description"] = "The newborn lynx have wandered off again! Those rascally cats are always up to mischief, darting off without a care. With Peevish missing and only Vesper and I to hold this position, your assistance would be a boon! I reckon those pesky felines are somewhere nearby. See if you can bring them back. I would use a light and search the cave, the spider-infested area to the south, and the coast to the north.", ["objectivesText"] = "Locate Beans , Beef , Thunder , and Cap'n Elaena . Then return them to Attica Whiskervale . Progress: Have you found all the cats?", ["rewardItems"] = { 206350, 211073, 217344, 219148, 219198, 220756, 220782, 224552 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 212419, ["x"] = 0.644, ["y"] = 0.188 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 212419, ["x"] = 0.644, ["y"] = 0.188 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.644, ["y"] = 0.188 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 82006 } },
