[82080] = { ["id"] = 82080, ["name"] = "More Torch Tossing", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["event"] = "Midsummer Fire Festival", ["expansion"] = 10, ["zoneID"] = 3557, ["mapID"] = 84, ["storyline"] = { 82080 }, ["description"] = "Hello, fire juggler! Are you having fun and making fiery mayhem? That's what I like to hear! Now, do you think you're an expert at torch tossing? Then I have a test for you... You know the rules: toss torches at the marked braziers. This time, however, you are timed and have a LOT more braziers to hit. Ready?", ["objectivesText"] = "Win the torch tossing game, then speak with the Master Fire Eater . Progress: Quick! There's no time to waste!", ["rewardGold"] = 252720, ["rewardXP"] = 200, ["rewardItems"] = { 23247 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 25975, ["x"] = 0.4985, ["y"] = 0.7205 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 25975, ["x"] = 0.4985, ["y"] = 0.7205 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.4985, ["y"] = 0.7205 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 3557 } }, ["questType"] = "standard", ["sourceQuests"] = { 11657 }, ["db2LabelIDs"] = { 3459 }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 97 },
[82087] = { ["id"] = 82087, ["name"] = "Torch Tossing", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Midsummer Fire Festival", ["expansion"] = 10, ["zoneID"] = 3557, ["mapID"] = 84, ["storyline"] = { 82087 }, ["series"] = { 11657, 11731 }, ["description"] = "So you want to be a fire juggler? Do you have what it takes? The dexterity? The reflexes? ...the courage? If you think so, then let's give you a little practice! Stand near the bonfire and you'll see braziers with markers flashing above them. Toss a torch at a marked brazier. Be quick! Do it before the mark fades if you want credit for the toss! Hit enough marked braziers, then come back here... for your next lesson.", ["objectivesText"] = "Win the torch tossing game, then speak with the Master Fire Eater . Progress: Quick! There's no time to waste!", ["rewardGold"] = 341600, ["rewardXP"] = 200, ["rewardItems"] = { 23247 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 25975, ["x"] = 0.4985, ["y"] = 0.7205 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 25975, ["x"] = 0.4985, ["y"] = 0.7205 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.4985, ["y"] = 0.7205 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 3557 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3459 }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 97 },
