[82120] = { ["id"] = 82120, ["name"] = "Pool Cleaner", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 80412, 81620, 81622, 81862, 82041, 82088, 82120, 82133, 82197, 82206, 82254, 82257, 82258, 82259, 82288, 82582, 82583, 82584, 82585, 82586, 82787, 82852 }, ["rewardXP"] = 9515, ["starts"] = { { ["x"] = 0.511, ["y"] = 0.509, ["mapID"] = 2215 } }, ["ends"] = { { ["x"] = 0.511, ["y"] = 0.509, ["mapID"] = 2215 } }, ["coords"] = { ["mapID"] = 2215, ["x"] = 0.511, ["y"] = 0.509 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14838 } }, ["questType"] = "world", ["questLines"] = { { ["id"] = 5575, ["name"] = "Hallowfall - World Quests/Repeatables", ["orderIndex"] = 15, ["flags"] = 0 } }, ["db2Objectives"] = { { ["orderIndex"] = 0, ["type"] = 0, ["amount"] = 15, ["objectID"] = 217950 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[82121] = { ["id"] = 82121, ["name"] = "Demand Satisfaction", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 82121, 82122, 82123, 82338, 82339 }, ["description"] = "We have worked together for some time now, <name>. I hope you have come to respect my vision as it pertains to the art of warfare. There are, as ever, rules that must be followed. Lines that must not be crossed. Zev'kall has to die, and I have to be the one to do it. Every day that Ascended ruffian tramples upon the ideals of war tarnishes the legacy of our kingdom. Please, do this last thing for me. Travel to the enemy stronghold and plant this flag on its steps. We will do this the correct way.", ["objectivesText"] = "Plant Anub'azal 's Standard inside the Siegehold in Azj-Kahet . Progress: Make haste. I would see this tale end sooner rather than later.", ["rewardGold"] = 146000, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 224345, ["x"] = 0.55, ["y"] = 0.412 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 222788, ["x"] = 0.46, ["y"] = 0.248 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 82339 }, ["questLines"] = { { ["id"] = 5567, ["name"] = "Fractured Legacy of Anub'azal", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[82122] = { ["id"] = 82122, ["name"] = "Duel of the Fates", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 82121, 82122, 82123, 82338, 82339 }, ["description"] = "I am no hapless rube, <name>. I do not expect Zev'kall to honor the nature of this challenge in even the most nominal sense. We are in the enemy's fortress, and we are surrounded by his teeming sycophants. There will be interference. I have two orders for you, soldier. First, you will ward off any malcontents who wish to interrupt the duel. Second and more importantly, you will bring neither sword nor spell to bear against Zev'kall himself. He will fall by my claws.", ["objectivesText"] = "Defend Anub'azal from Zev'kall's minions.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 222788, ["x"] = 0.46, ["y"] = 0.248 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 224547, ["x"] = 0.46, ["y"] = 0.245 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.248 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 82121 }, ["questLines"] = { { ["id"] = 5567, ["name"] = "Fractured Legacy of Anub'azal", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[82123] = { ["id"] = 82123, ["name"] = "The General's Conviction", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 82121, 82122, 82123, 82338, 82339 }, ["description"] = "< Anub'azal retches roughly. Ichor spews from his disjointed maw.> My cohort's obligation to the Severed Threads yet remains. You would do well to report what happened here to the Weaver. Vexing as she is, she will have some idea of how to proceed from here.", ["objectivesText"] = "Inform Widow Arak'nai of what transpired.", ["rewardGold"] = 146000, ["rewardXP"] = 5885, ["rewardItems"] = { 226045 }, ["rewardCurrencies"] = { { ["id"] = 3056, ["amount"] = 35 } }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 224547, ["x"] = 0.46, ["y"] = 0.245 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 207471, ["x"] = 0.556, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.245 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 82122 }, ["questLines"] = { { ["id"] = 5567, ["name"] = "Fractured Legacy of Anub'azal", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[82124] = { ["id"] = 82124, ["name"] = "The Beginning of the End", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2213, ["storyline"] = { 82124, 82125, 82126, 82127, 82130, 82141, 83587 }, ["series"] = { 83587 }, ["description"] = "Queen Ansurek has been busy since the assassination attempt. Her grip is tightening on Azj-Kahet and her ever loyal nobles attend to her darkest whims. On behest of the Queen, her two most loyal nobles Skeinspinner Takazj and Anub'arash, have locked down the Umbral Bazaar. Takazj's insufferable propaganda machinations and Anub'arash's increased military presence have painted a clear picture, ascend or die. I need you to go to the Umbral Bazaar and disrupt their hold.", ["objectivesText"] = "Cause disruption in the Umbral Bazaar. Progress: How disappointing that Queen Ansurek continues to lead us to darkness.", ["rewardGold"] = 341600, ["rewardXP"] = 10190, ["rewardItems"] = { 129258, 129259, 129260, 129346, 129347, 129348, 129349, 141393, 175176, 175177, 175178, 175179, 175208, 175209, 175210, 175211, 224072 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 208782, ["x"] = 0.526667, ["y"] = 0.462667 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 208782, ["x"] = 0.526667, ["y"] = 0.462667 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.526667, ["y"] = 0.462667 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["sourceQuests"] = { 83587 }, ["questLines"] = { { ["id"] = 5716, ["name"] = "To Kill a Queen", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2213 },
[82125] = { ["id"] = 82125, ["name"] = "A Spy Like Us", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2213, ["storyline"] = { 82124, 82125, 82126, 82127, 82130, 82141, 83587 }, ["series"] = { 82126 }, ["description"] = "Distressing news comes from the Burrows, a sinister plan is unfolding in the gutters below. Citizens of the ward have been disappearing at an alarming rate. Skeinspinner Takazj and Anub'arash have all the subtlety of a hammer. I doubt it is their work. This is the hand of someone more subtle. I have a contact in the Burrows. His name is Gut'usul . Meet with him in the Burrows and find out what is going on down below.", ["objectivesText"] = "Meet with Gut'usul in the Burrows.", ["rewardGold"] = 30900, ["rewardXP"] = 1275, ["rewardItems"] = { 224072 }, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 208782, ["x"] = 0.526667, ["y"] = 0.462667 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 208782, ["x"] = 0.526667, ["y"] = 0.462667 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.526667, ["y"] = 0.462667 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questTurnInID"] = 208782, ["questType"] = "standard", ["sourceQuests"] = { 82124 }, ["questLines"] = { { ["id"] = 5716, ["name"] = "To Kill a Queen", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2216 },
[82126] = { ["id"] = 82126, ["name"] = "Defense of the People", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 82124, 82125, 82126, 82127, 82130, 82141, 83587 }, ["series"] = { 82125 }, ["description"] = "The Vizier no doubt filled you in on some of the details. Citizens in the Burrows are missing, that much you know. But whispers on the wind tell a bigger story. Our citizens are being taken to the Transformatory and never returned! We must stop this at all costs. More have been taken but it's not too late for them yet. They are still being kept in the Burrows. Find them and free them.", ["objectivesText"] = "Free 5 citizens in the Burrows. Progress: Act swiftly, we may not have long before they are beyond our grasp.", ["rewardGold"] = 341600, ["rewardXP"] = 10190, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.572, ["y"] = 0.41, ["mapID"] = 2216, ["npcID"] = 222790 } }, ["ends"] = { { ["x"] = 0.572, ["y"] = 0.41, ["mapID"] = 2216, ["npcID"] = 222790 } }, ["coords"] = { ["mapID"] = 2216, ["x"] = 0.572, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14753 } }, ["questGiverID"] = 222790, ["questTurnInID"] = 222790, ["questType"] = "standard", ["sourceQuests"] = { 82125 }, ["questLines"] = { { ["id"] = 5716, ["name"] = "To Kill a Queen", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2216 },
[82127] = { ["id"] = 82127, ["name"] = "Make Them Prey", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 82124, 82125, 82126, 82127, 82130, 82141, 83587 }, ["description"] = "These abductors are rounding up citizens and no one in the Burrows can stop them. I think it is about time somebody did something. They stalk the Burrows thinking they are unseen but I can see them, we can all see them. It's just nobody here can oppose them. That is where you come in. Hunt these abductors down and show them who is really the prey.", ["objectivesText"] = "Kill 8 Abductors in the Burrows. Progress: Hit the abductors extra hard for me.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.572, ["y"] = 0.41, ["mapID"] = 2216, ["npcID"] = 222790 } }, ["ends"] = { { ["x"] = 0.572, ["y"] = 0.41, ["mapID"] = 2216, ["npcID"] = 222790 } }, ["coords"] = { ["mapID"] = 2216, ["x"] = 0.572, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14753 } }, ["questGiverID"] = 222790, ["questTurnInID"] = 222790, ["questType"] = "standard", ["sourceQuests"] = { 82125 }, ["questLines"] = { { ["id"] = 5716, ["name"] = "To Kill a Queen", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2216 },
[82130] = { ["id"] = 82130, ["name"] = "A Shot at the Top", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2213, ["storyline"] = { 82124, 82125, 82126, 82127, 82130, 82141, 83587 }, ["series"] = { 82141 }, ["description"] = "While you have been out, I've been keeping busy as well. Your exploits in the Burrows drew the attention of someone much higher up. A strange being wrapped in bandages, with a scent like despair. Fortunately, this unusual monster is paying a visit all the way down in the Burrows to find out why their abductors are missing. Now is our chance to strike, and take down this whole operation.", ["objectivesText"] = "Kill the Master Abductor. Progress: Soon the Burrows will be free.", ["rewardGold"] = 683200, ["rewardXP"] = 12740, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.572, ["y"] = 0.41, ["mapID"] = 2216, ["npcID"] = 222790 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 208782, ["x"] = 0.526667, ["y"] = 0.462667 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.526667, ["y"] = 0.462667 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questGiverID"] = 222790, ["questType"] = "standard", ["sourceQuests"] = { 82126, 82127 }, ["questLines"] = { { ["id"] = 5716, ["name"] = "To Kill a Queen", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2213 },
