[82141] = { ["id"] = 82141, ["name"] = "To Kill a Queen", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14792, ["mapID"] = 2213, ["storyline"] = { 82124, 82125, 82126, 82127, 82130, 82141, 83587 }, ["series"] = { 82130 }, ["description"] = "Tightening her grip on the citizens is something I expected of the Queen but forcefully ascending the population of the Burrows is too far. Queen Ansurek has fallen far greater than I ever expected. I can't sit idly by and watch her lead our people to ruin. The time is now. We must kill Queen Ansurek and lead the people to a brighter future. Otherwise who knows how far she will fall.", ["objectivesText"] = "Kill Queen Ansurek . Progress: It fills me with sorrow that it has come to this.", ["rewardGold"] = 20496000, ["rewardXP"] = 20380, ["rewardItems"] = { 163128, 198353, 224072, 225896, 236956, 260583 }, ["rewardCurrencies"] = { { ["id"] = 3004, ["amount"] = 2500 } }, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 208782, ["x"] = 0.526667, ["y"] = 0.462667 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 208782, ["x"] = 0.526667, ["y"] = 0.462667 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.526667, ["y"] = 0.462667 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questType"] = "raid", ["sourceQuests"] = { 82130 }, ["questLines"] = { { ["id"] = 5716, ["name"] = "To Kill a Queen", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2213 },
[82143] = { ["id"] = 82143, ["name"] = "The Path of Dissonance", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 80563, 80564, 80565, 80566, 80567, 80568, 80569, 80570, 80571, 80572, 82143 }, ["series"] = { 80563, 80564, 80565 }, ["description"] = "Hannan is correct only in that my presence here is not... strictly allowed. But this corruption echoes in my mind, like a disruptive chord in the otherwise pure song of the world. Like a cry for help. I must heed that call. I must follow the dissonance to its source and find the heart of it, so that I may discover how to cleanse it. Join me.", ["objectivesText"] = "Meet Orweyna and Hannan outside the Salien Gutters cave. Progress: You have proven to be formidable. I am sure we can find a way to eliminate what extractors we come across.", ["rewardGold"] = 154900, ["rewardXP"] = 5300, ["starts"] = { { ["x"] = 0.493, ["y"] = 0.602, ["mapID"] = 2256, ["npcID"] = 226672 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 220603, ["x"] = 0.598, ["y"] = 0.638 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.638 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questGiverID"] = 226672, ["questType"] = "standard", ["sourceQuests"] = { 80563, 80564 }, ["questLines"] = { { ["id"] = 5618, ["name"] = "Melody of Madness", ["orderIndex"] = 10, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[82144] = { ["id"] = 82144, ["name"] = "On the Road", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80576, 80577, 80578, 80593, 80676, 80682, 81613, 82144, 82224 }, ["series"] = { 80682 }, ["description"] = "This is the only road to the elevator, he should have been here by now. Unless... he didn't take the road! He wouldn't want to be seen. He has no idea how dangerous the deeps can be. We have to find him!", ["objectivesText"] = "Find Brennok.", ["rewardGold"] = 619600, ["rewardXP"] = 12400, ["rewardItems"] = { 228668, 228671, 228673, 228674, 253040 }, ["rewardCurrencies"] = { { ["id"] = 2902, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 220600, ["x"] = 0.589333, ["y"] = 0.446667 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 220600, ["x"] = 0.589333, ["y"] = 0.446667 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.589333, ["y"] = 0.446667 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 80682 }, ["questLines"] = { { ["id"] = 5626, ["name"] = "Tired of Rest", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
