[82153] = { ["id"] = 82153, ["name"] = "Embassies and Envoys", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 79197, 79333, 79344, 82153, 83271, 83286, 83315 }, ["description"] = "We sailed for what seemed like an eternity. I must admit there were times when I worried we would arrive too late. But seeing all of you, united and strong, has rekindled my hope. Before we begin planning, we must set up a base of operations here in Dornogal.", ["objectivesText"] = "Set up your faction's embassy in Dornogal.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 223546, 223547, 223548, 223549, 223564, 223569, 223584, 223588 }, ["rewardChoices"] = { 223546, 223548, 223588 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 216168, ["x"] = 0.358, ["y"] = 0.814 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 214917, ["x"] = 0.316667, ["y"] = 0.600667 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.358, ["y"] = 0.814 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 79333 }, ["questLines"] = { { ["id"] = 5551, ["name"] = "Against the Current", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5551, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
