[82213] = { ["id"] = 82213, ["name"] = "A Batty Request", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 82213, 82214, 82215, 82216, 82217, 82219, 82220, 82221, 82222, 82223 }, ["description"] = "I'll gather a selection of our major trade goods before we head out for the meet up, but I could use some help in gathering some additional items. Lately we've been struggling with collecting the best bat meat in Hallowfall . Could you gather some before you come to Dunelle's Kindness?", ["objectivesText"] = "Collect 8 Shacklefang Leafnose Meat . Progress: Did you get the meat?", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["rewardItems"] = { 222920 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213145, ["x"] = 0.418, ["y"] = 0.54 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213145, ["x"] = 0.418, ["y"] = 0.54 }, { ["mapID"] = 2215, ["npcID"] = 223267, ["x"] = 0.5392, ["y"] = 0.4808 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 82216 }, ["questLines"] = { { ["id"] = 5563, ["name"] = "Striking Steel", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[82214] = { ["id"] = 82214, ["name"] = "Does Anyone Like Wasps?", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 82213, 82214, 82215, 82216, 82217, 82219, 82220, 82221, 82222, 82223 }, ["description"] = "We haven't been able to gather resources from this area due to hornets moving in. We just haven't been able to spare the resources from the wall to deal with them. If you can, we'd all appreciate it.", ["objectivesText"] = "Kill 10 Shacklefang Hornets . Progress: Damn those hornets. Wasps were bad enough when they were the size of my finger.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213145, ["x"] = 0.418, ["y"] = 0.54 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213145, ["x"] = 0.418, ["y"] = 0.54 }, { ["mapID"] = 2215, ["npcID"] = 223267, ["x"] = 0.5392, ["y"] = 0.4808 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 82216 }, ["questLines"] = { { ["id"] = 5563, ["name"] = "Striking Steel", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[82215] = { ["id"] = 82215, ["name"] = "Regular Fiber", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 82213, 82214, 82215, 82216, 82217, 82219, 82220, 82221, 82222, 82223 }, ["description"] = "There is a plant fiber that grows in Rumshackle and The Fangs that makes for an excellent rope. Because of the hornets, we haven't been able to collect it in a long time and are running very low in our supplies. While you are in the area, could you collect some?", ["objectivesText"] = "Collect 5 Tough Ivy Fibers . Progress: The fibers are like magic. The ropes they make are strong, and supple.", ["rewardGold"] = 292100, ["rewardXP"] = 10190, ["rewardItems"] = { 222925 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213145, ["x"] = 0.418, ["y"] = 0.54 }, { ["mapID"] = 2215, ["npcID"] = 223267, ["x"] = 0.5392, ["y"] = 0.4808 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213145, ["x"] = 0.418, ["y"] = 0.54 }, { ["mapID"] = 2215, ["npcID"] = 223267, ["x"] = 0.5392, ["y"] = 0.4808 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 82216 }, ["questLines"] = { { ["id"] = 5563, ["name"] = "Striking Steel", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[82216] = { ["id"] = 82216, ["name"] = "Economical Request", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 82213, 82214, 82215, 82216, 82217, 82219, 82220, 82221, 82222, 82223 }, ["description"] = "I hear you've come from the surface? Did you meet the earthen? We used to trade with them, but after the Day of Darkness we struggled to send envoys. Those we sent never made it back. Honestly, we thought that they had perished. I'm going to try reaching out again. I'd like for you to write a letter of recommendation , in case we did something to offend them.", ["objectivesText"] = "Write a letter of recommendation in Mereldar in Hallowfall . Progress: I hope this goes well. We really need additional resources.", ["rewardGold"] = 232300, ["rewardXP"] = 7645, ["rewardItems"] = { 216694, 225894 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213145, ["x"] = 0.418, ["y"] = 0.54 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213145, ["x"] = 0.418, ["y"] = 0.54 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78658, 79573 }, ["questLines"] = { { ["id"] = 5563, ["name"] = "Striking Steel", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[82217] = { ["id"] = 82217, ["name"] = "Underground Economics", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 82213, 82214, 82215, 82216, 82217, 82219, 82220, 82221, 82222, 82223 }, ["description"] = "After the Day of Darkness, we haven't seen or heard from the earthen. I don't know why. We used to be on good terms. I'd even have considered Merrix a friend, albeit an odd one. We need this to go well.", ["objectivesText"] = "Assist the Arathi with trade negotiations in Dunelle's Kindness. Progress: We need this trade deal to go through.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["rewardItems"] = { 223638, 223889, 223890, 223892, 225894 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 225711, ["x"] = 0.684, ["y"] = 0.446 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 225711, ["x"] = 0.684, ["y"] = 0.446 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.684, ["y"] = 0.446 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 82213, 82214, 82215 }, ["questLines"] = { { ["id"] = 5563, ["name"] = "Striking Steel", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[82219] = { ["id"] = 82219, ["name"] = "Spice Up Your Life", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 82213, 82214, 82215, 82216, 82217, 82219, 82220, 82221, 82222, 82223 }, ["description"] = "Flames blessing to you, <name>. Trade has been going well now the Ringing Deeps are safe once again and things have, relatively, calmed down. Despite that, our General still won't breathe easily. She's wound tight and it's not healthy. An unhealthy general leads to an unhealthy army. So a day with the family. Can you pick some herbs for the meal? You'll want the big ones, don't bother with the small ones.", ["objectivesText"] = "Gather 7 Light-Bathed Lotus in Hallowfall . Progress: Herbs bathed in the light of Beledar have a fantastic taste.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["rewardItems"] = { 222953 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213145, ["x"] = 0.418, ["y"] = 0.54 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 223267, ["x"] = 0.5392, ["y"] = 0.4808 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 82217 }, ["questLines"] = { { ["id"] = 5563, ["name"] = "Striking Steel", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[82220] = { ["id"] = 82220, ["name"] = "Eagle Eye, Eagle Die", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 82213, 82214, 82215, 82216, 82217, 82219, 82220, 82221, 82222, 82223 }, ["description"] = "The eagles out by the undersea have bathed in the light of Beledar, and it makes them particularly tasty. Could you get a few eagle fillets ? Take this harpoon with you, they can be feisty.", ["objectivesText"] = "Collect 5 Eagle Fillets . Progress: Watch yourself. The eagles can easily injure you.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["rewardItems"] = { 222951, 222976 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213145, ["x"] = 0.418, ["y"] = 0.54 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 223267, ["x"] = 0.5392, ["y"] = 0.4808 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 82217 }, ["questLines"] = { { ["id"] = 5563, ["name"] = "Striking Steel", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[82221] = { ["id"] = 82221, ["name"] = "Full Dress", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 82213, 82214, 82215, 82216, 82217, 82219, 82220, 82221, 82222, 82223 }, ["description"] = "A traditional Arathi family meal involves displaying the various medals, awards, and mementos of the family. Given my mother's illustrious career, it's taking quite a while. Would you mind helping with some of the decorations?", ["objectivesText"] = "Help the Steelstrikes decorate their house in Mereldar in preparation for the upcoming meal. Progress: We have to get this meal right, my mother needs to unwind.", ["rewardGold"] = 280900, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 223267, ["x"] = 0.5392, ["y"] = 0.4808 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 223267, ["x"] = 0.5392, ["y"] = 0.4808 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.5392, ["y"] = 0.4808 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 82219, 82220 }, ["questLines"] = { { ["id"] = 5563, ["name"] = "Striking Steel", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[82222] = { ["id"] = 82222, ["name"] = "Cooking With Style", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 82213, 82214, 82215, 82216, 82217, 82219, 82220, 82221, 82222, 82223 }, ["description"] = "Sorry my daughter roped you into this. I'm sure you had better things to be doing. She has terrible manners. I'll have to have words with whoever raised her. <The general's mouth twitches in a quick smirk.> Still, you are here. Would you like to join us for the more enjoyable activity? We're about to start cooking.", ["objectivesText"] = "Help the Steelstrikes cook a meal in Mereldar. Progress: Why do they say a pinch of salt? Why not a handful? More ingredients has to be better.", ["rewardGold"] = 292100, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 223268, ["x"] = 0.445, ["y"] = 0.507 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 224154, ["x"] = 0.438, ["y"] = 0.496 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.445, ["y"] = 0.507 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 82221 }, ["questLines"] = { { ["id"] = 5563, ["name"] = "Striking Steel", ["orderIndex"] = 9, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[82223] = { ["id"] = 82223, ["name"] = "A Home Cooked Meal", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 82213, 82214, 82215, 82216, 82217, 82219, 82220, 82221, 82222, 82223 }, ["description"] = "Home-cooked stew. There is nothing like it in the world. I grant you, it might not be as tasty as the stew from the Empires Edge Inn. But it was cooked by family. That's what makes it great. Join us. You have more than earned the right.", ["objectivesText"] = "Have a meal at the Steelstrike House in Mereldar in Hallowfall . Progress: It's been such a long time since I had a meal with the entire family.", ["rewardGold"] = 292100, ["rewardXP"] = 10190, ["rewardItems"] = { 198106, 225894 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 25 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 224154, ["x"] = 0.438, ["y"] = 0.496 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 225745, ["x"] = 0.446, ["y"] = 0.506 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.496 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 82222 }, ["questLines"] = { { ["id"] = 5563, ["name"] = "Striking Steel", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[82224] = { ["id"] = 82224, ["name"] = "Check on the Compiler", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80576, 80577, 80578, 80593, 80676, 80682, 81613, 82144, 82224 }, ["series"] = { 80578 }, ["description"] = "That's everything up here. Would you check on Brennok ? Recitations can be stressful, I'm sure he'd appreciate the help.", ["objectivesText"] = "Check in on Brennok .", ["rewardGold"] = 29200, ["rewardXP"] = 1240, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 220600, ["x"] = 0.589333, ["y"] = 0.446667 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 220597, ["x"] = 0.613143, ["y"] = 0.446 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.589333, ["y"] = 0.446667 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 80577 }, ["nextQuests"] = { 80578 }, ["questLines"] = { { ["id"] = 5626, ["name"] = "Tired of Rest", ["orderIndex"] = 8, ["flags"] = 1 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[82225] = { ["id"] = 82225, ["name"] = "Excavation Extravaganza", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 80295, 80394, 80395, 81465, 81512, 81615, 81621, 81639, 81675, 81710, 81854, 82225, 82234, 82237, 82291, 82292, 82355, 82448, 82451, 82454, 82455, 82456, 82470 }, ["objectivesText"] = "Excavation Efforts Supported", ["rewardXP"] = 11765, ["starts"] = { { ["x"] = 0.619, ["y"] = 0.712, ["mapID"] = 2248 } }, ["ends"] = { { ["x"] = 0.619, ["y"] = 0.712, ["mapID"] = 2248 } }, ["coords"] = { ["mapID"] = 2248, ["x"] = 0.619, ["y"] = 0.712 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14717 } }, ["questType"] = "world", ["questLines"] = { { ["id"] = 5589, ["name"] = "Isle of Dorn - World Quests", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2Objectives"] = { { ["text"] = "Excavation Efforts Supported", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[82226] = { ["id"] = 82226, ["name"] = "Papers? Please!", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 82226 }, ["description"] = "Hey pal, what's it gonna take to get you to leave me alone? How about a trip? A POWER trip... I told Boss Sparkshot that I would man the worksite's...er, resort's! Yeah, that I would man the resort's front desk for a bit. Care to take my place? It's just your usual paper-pushing busy work. Check credentials, keep an eye out for corporate sabotage, call in the occasional air strike, etcetera, etcetera... <Garv has already fallen back asleep.>", ["objectivesText"] = "Check papers at the Overseer's Desk in Opportunity Point. Progress: You're in my shade, pal.", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 223184, ["x"] = 0.634, ["y"] = 0.786667 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 223184, ["x"] = 0.634, ["y"] = 0.786667 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.634, ["y"] = 0.786667 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79573, 80434 } },
[82229] = { ["id"] = 82229, ["name"] = "An Uncommon Request", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15105, ["mapID"] = 2239, ["storyline"] = { 80069, 80071, 80072, 80073, 80075, 80077, 82229 }, ["description"] = "<name>, welcome to Bel'ameth. I wonder -- do you have time for a small favor? Earlier today, a young kaldorei named Kelestra came to see me. She sought permission to bury her family in a barrow den. An uncommon request, but I gave her my blessing and directed her to the Barrows of Reverie. She looked... melancholy. After she left, it struck me that she might be the last of her family still alive. If you have the time, could you check on her?", ["objectivesText"] = "Meet Kelestra in the Barrows of Reverie.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 223146 }, ["starts"] = { { ["mapID"] = 2239, ["npcID"] = 216069, ["x"] = 0.4925, ["y"] = 0.6815 } }, ["ends"] = { { ["mapID"] = 2239, ["npcID"] = 218623, ["x"] = 0.7255, ["y"] = 0.7305 } }, ["coords"] = { ["mapID"] = 2239, ["source"] = "quest_giver", ["x"] = 0.4925, ["y"] = 0.6815 }, ["mapCandidates"] = { ["npc"] = { 2239 }, ["zone"] = { 15105 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5547, ["name"] = "Sins of the Sister", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2239 },
