[82284] = { ["id"] = 82284, ["name"] = "Remembrance for the Fallen", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 81929, 81945, 81950, 81964, 81965, 81969, 82248, 82268, 82284 }, ["series"] = { 81964, 81965, 81969, 82268 }, ["description"] = "It is our custom to pay homage to the fallen by burning whatever we can recover of their belongings. Usually, it is their tinderboxes as those are easier to carry. We then return those items to the flame. While we were able to retrieve Sir Ashrealm's tinderbox, Ryton's breastplate will serve to honor his memory. You have placed your life in danger not only for me, but also for Hallowfall . I would be honored if you would assist me this one last time in remembering our fallen.", ["objectivesText"] = "Place the Breastplate and Tinderbox in the forge at Mereldar. Progress: Thank you, <name>.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 223439, 223444, 223450, 223462, 223515 }, ["rewardCurrencies"] = { { ["id"] = 3003, ["amount"] = 500 }, { ["id"] = 3008, ["amount"] = 10 }, { ["id"] = 3056, ["amount"] = 35 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 220406, ["x"] = 0.432, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 220406, ["x"] = 0.432, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 82268 }, ["questLines"] = { { ["id"] = 5562, ["name"] = "All Good Things...", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
