[82338] = { ["id"] = 82338, ["name"] = "Absent Errand", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 82121, 82122, 82123, 82338, 82339 }, ["description"] = "Do you remember the logbook you discovered in Zev'kall's office? It contained critical information about Zev'kall's misuse of our people. I gave it to my assistant, Anub'okki, to bring to the historians in the Skeins. But I have not heard back from Anub'okki. I suspect foul play. See if anyone in the Skeins will admit to having seen him!", ["objectivesText"] = "Seek out Anub'azal 's student in the Skeins of Nerub'ar.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 223765, ["x"] = 0.475, ["y"] = 0.227 }, { ["mapID"] = 2255, ["npcID"] = 224345, ["x"] = 0.55, ["y"] = 0.412 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 223760, ["x"] = 0.41, ["y"] = 0.335 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.227 }, ["mapCandidates"] = { ["npc"] = { 2213, 2255 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5567, ["name"] = "Fractured Legacy of Anub'azal", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2213 },
[82339] = { ["id"] = 82339, ["name"] = "An Honorless Kill", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2213, ["storyline"] = { 82121, 82122, 82123, 82338, 82339 }, ["description"] = "If it will get you out of here sooner, I will tell you what I saw. I did not see what happened to Anub'okki. But I can tell you that corpses are dumped into Pillar-nest Xesh to be forgotten about. The cleanup crew dragged Anub'okki out of here not long ago. If you hurry, you may be able to examine the remains before they are gone.", ["objectivesText"] = "Recover the logbook and discover what happened to Anub'okki. Progress: Did you find Anub'okki?", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["rewardItems"] = { 225635, 225637 }, ["rewardCurrencies"] = { { ["id"] = 3056, ["amount"] = 35 }, { ["id"] = 3056, ["amount"] = 750 } }, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 223760, ["x"] = 0.41, ["y"] = 0.335 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 224345, ["x"] = 0.55, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.41, ["y"] = 0.335 }, ["mapCandidates"] = { ["npc"] = { 2213, 2255 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["sourceQuests"] = { 82338 }, ["questLines"] = { { ["id"] = 5567, ["name"] = "Fractured Legacy of Anub'azal", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[82340] = { ["id"] = 82340, ["name"] = "Loss of Limb", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 82340, 83057 }, ["description"] = "Happy greetings! I am Mr. Sunflower , and this is my tea room and therapy space. It is a safe place for everyone! I wonder if you might be willing to help a patient of mine. Vi'azl is deathly afraid of creatures with fewer limbs. I think it has grown into a deep phobia of dismemberment. I'm trying to get to the bottom of this diagnosis. Would you speak to him, and demonstrate that you, who do not have eight limbs, are not so terrifying after all?", ["objectivesText"] = "Assist Mr. Sunflower in Vi'azl 's therapy session. Progress: Vi'azl must have some terrible trauma related to creatures with fewer limbs. We must help him.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["rewardItems"] = { 205982 }, ["starts"] = { { ["x"] = 0.633, ["y"] = 0.374, ["mapID"] = 2216, ["npcID"] = 223723 } }, ["ends"] = { { ["x"] = 0.633, ["y"] = 0.374, ["mapID"] = 2216, ["npcID"] = 223723 } }, ["coords"] = { ["mapID"] = 2216, ["x"] = 0.633, ["y"] = 0.374 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14753 } }, ["questGiverID"] = 223723, ["questTurnInID"] = 223723, ["questType"] = "standard", ["sourceQuests"] = { 78384 }, ["questLines"] = { { ["id"] = 5612, ["name"] = "Mr. Sunflower's Therapy", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2216 },
