[82452] = { ["id"] = 82452, ["name"] = "Worldsoul: World Quests", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "There so much to be done and so little time to do it! Brinthe and I have been gathering word of the people that need the most aid throughout all of Khaz Algar. There's too many to count! Go out and help them. With your aid, will can bring all our people closer together... so we may all grow stronger.", ["objectivesText"] = "Complete World Quests in Khaz Algar. Progress: Strange, these notes that come from Azj-kahet. I am.. hesitant to send any aid to the nerubians. Not after what they've done to my people. But between your reports and those from our scouts... perhaps we can use their... disagreements to our advantage. And perhaps some are truly in need of aid. Of kindness. I do not want my eyes to be clouded by hate. And yet... <Faerin sighs.> Who knows. All I do know I won't regret a kindness.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["rewardItems"] = { 224784, 229354, 239118, 244865 }, ["rewardCurrencies"] = { { ["id"] = 3100, ["amount"] = 2 }, { ["id"] = 3100, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.461, ["y"] = 0.496, ["mapID"] = 2339, ["npcID"] = 223875 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223875, ["x"] = 0.46, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questGiverID"] = 223875, ["questType"] = "standard", ["sourceQuests"] = { 79197, 79573 }, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 49, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[82453] = { ["id"] = 82453, ["name"] = "Worldsoul: Encore!", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "Have you seen the fliers around? They're staging some earthen plays in the Proscenium! I can't remember the last time I've seen a play, but I've got my hands full, as usual. You'll go, right? I'm sure everyone here could use their spirits raised. A play might be just the thing everyone needs. Make sure it's a night to remember!", ["objectivesText"] = "Participate in the Theater Troupe event and complete World Quests in Khaz Algar Progress: Once, when I was a kid, I decided to put a play on for my family! <Faerin grimaces.> It didn't... it didn't go well.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["rewardItems"] = { 224784, 229354, 239118, 244865 }, ["rewardCurrencies"] = { { ["id"] = 3100, ["amount"] = 2 }, { ["id"] = 3100, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.461, ["y"] = 0.496, ["mapID"] = 2339, ["npcID"] = 223875 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223875, ["x"] = 0.46, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questGiverID"] = 223875, ["questType"] = "standard", ["sourceQuests"] = { 79197, 79573 }, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
