[82470] = { ["id"] = 82470, ["name"] = "Arcane Riddles", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 80295, 80394, 80395, 81465, 81512, 81615, 81621, 81639, 81675, 81710, 81854, 82225, 82234, 82237, 82291, 82292, 82355, 82448, 82451, 82454, 82455, 82456, 82470 }, ["objectivesText"] = "Flow of Magic fixed", ["rewardXP"] = 11765, ["starts"] = { { ["x"] = 0.308, ["y"] = 0.522, ["mapID"] = 2248 } }, ["ends"] = { { ["x"] = 0.308, ["y"] = 0.522, ["mapID"] = 2248 } }, ["coords"] = { ["mapID"] = 2248, ["x"] = 0.308, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14717 } }, ["questType"] = "world", ["questLines"] = { { ["id"] = 5589, ["name"] = "Isle of Dorn - World Quests", ["orderIndex"] = 18, ["flags"] = 0 } }, ["db2Objectives"] = { { ["text"] = "Flow of Magic fixed", ["amount"] = 1, ["type"] = 0, ["objectID"] = 223921, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[82477] = { ["id"] = 82477, ["name"] = "A Helping Farmhand", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 82477, 82478, 82479, 82480 }, ["description"] = "Greetings, $p, name's Orren. We've got a whole mess of Jawcrawlers that came up from underground attacking the crops. Something a <class> like yourself could really help out with! Hunger is never far away in Hallowfall , so saving these crops is my priority. But if you'd be willing to drive them off for me, I'll be able to focus on my long-term plan to feed people more effectively. Meet me over by the shed! And bring any food that's not too chewed up.", ["objectivesText"] = "Recover 8 Slightly Chewed Harvest Bounty from Gluttonous Jawcrawlers. Progress: This'll keep our crops safe in the future. And perhaps the leftovers can go... in a stew.", ["rewardGold"] = 292100, ["rewardXP"] = 10190, ["rewardItems"] = { 224051 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 223920, ["x"] = 0.49, ["y"] = 0.62 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 224378, ["x"] = 0.472, ["y"] = 0.648 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5574, ["name"] = "Apart for Purpose", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[82478] = { ["id"] = 82478, ["name"] = "Regularly Scheduled Maintenance", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 82477, 82478, 82479, 82480 }, ["description"] = "I've got another problem that's a bit more... personal, $p. My girlfriend, Aemyra, is a Lamplighter. I thought she'd be back from her last mission, to Velhan's Claim, by now. Could you go make sure she's okay, and deliver this message? I'm worried to the point of distraction. Maybe you could also pick some of her favorite flowers, up that hill? I'd go myself, but if I can get ELIZA working right, it would do so much to feed people in Hallowfall . And give me more time to spend with Aemyra, too!", ["objectivesText"] = "Take Orren's Message , 6 Crimson Charmer and 6 Amber Bloom to Aemyra at Velhan's Claim. Progress: These are from Orren? I think they go well together, even though they're so different.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["rewardItems"] = { 224098, 224099, 224193 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 224378, ["x"] = 0.472, ["y"] = 0.648 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213613, ["x"] = 0.472667, ["y"] = 0.147333 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.648 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 82477 }, ["questLines"] = { { ["id"] = 5574, ["name"] = "Apart for Purpose", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[82479] = { ["id"] = 82479, ["name"] = "The Sword is Mightier", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 82477, 82478, 82479, 82480 }, ["series"] = { 82480 }, ["description"] = "I had told Orren I'd be back by now, but Velhan's Claim has larger problems than I expected. The people here need my help against the kobyss. $p, I've always been better with a sword than a pen. Strong feelings and being far apart makes it even harder. I'm more at home protecting the vulnerable than being vulnerable. Perhaps I could tell you what I want to get across and you could write it for me?", ["objectivesText"] = "Help Aemyra choose the right words for her message to Orren. Progress: Did you find Aemyra? Is she alright?", ["rewardGold"] = 232300, ["rewardXP"] = 7645, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213613, ["x"] = 0.472667, ["y"] = 0.147333 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 224379, ["x"] = 0.465, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.472667, ["y"] = 0.147333 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 82478 }, ["questLines"] = { { ["id"] = 5574, ["name"] = "Apart for Purpose", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[82480] = { ["id"] = 82480, ["name"] = "Job Killing Robot Or...", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 82477, 82478, 82479, 82480 }, ["series"] = { 82479 }, ["description"] = "I shouldn't have set ELIZA to simply gather as much food as she could. She was working, but when a wagon came by, full of food for Mereldar, she started chasing it! And she wouldn't let me access her decision sprockets or tensor springs! I kept trying, but ELIZA wouldn't stop. Eventually, she outran me. $p, I need you to stop her before someone gets killed.", ["objectivesText"] = "Stop ELIZA . Progress: Were you able to stop ELIZA ?", ["rewardGold"] = 584200, ["rewardXP"] = 12740, ["rewardItems"] = { 225947 }, ["rewardCurrencies"] = { { ["id"] = 2899, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 224379, ["x"] = 0.465, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 224380, ["x"] = 0.483, ["y"] = 0.634 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 82479 }, ["questLines"] = { { ["id"] = 5574, ["name"] = "Apart for Purpose", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[82481] = { ["id"] = 82481, ["name"] = "Enforcer Extermination", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78974, 78995, 79116, 79722, 79958, 79959, 79960, 80409, 80457, 82266, 82295, 82297, 82324, 82332, 82363, 82364, 82387, 82414, 82468, 82481, 82521, 82524, 82526, 82531, 82533, 82536, 83536, 83718 }, ["objectivesText"] = "Pale Weavelashers slain", ["rewardXP"] = 11765, ["starts"] = { { ["x"] = 0.561, ["y"] = 0.584, ["mapID"] = 2255 } }, ["ends"] = { { ["x"] = 0.561, ["y"] = 0.584, ["mapID"] = 2255 } }, ["coords"] = { ["mapID"] = 2255, ["x"] = 0.561, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14752 } }, ["questType"] = "world", ["questLines"] = { { ["id"] = 5564, ["name"] = "Azj-Kahet - World Quests/Repeatables", ["orderIndex"] = 38, ["flags"] = 0 } }, ["db2Objectives"] = { { ["text"] = "Pale Weavelashers slain", ["amount"] = 12, ["type"] = 0, ["objectID"] = 224009, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[82482] = { ["id"] = 82482, ["name"] = "Worldsoul: Snuffling", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "I've wanted to be able to explore beyond Hallowfall's caves for so long now. Of course, I hardly have time, but when I do... there's such surprises everywhere! Treasures, friends in need, foes great and small... All so wonderful. I'll just have to live vicariously through you. Deeds need doing! Go out and seek the surprises in every nook and cranny. I'm certain you will find things that need doing!", ["objectivesText"] = "Find Disturbed Earth piles to Snuffle and discover Worldsoul Motes by skyriding all around Khaz Algar. Progress: Oh, what have you found?! Tell me everything.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["rewardItems"] = { 224784, 229354 }, ["rewardCurrencies"] = { { ["id"] = 3100, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.461, ["y"] = 0.496, ["mapID"] = 2339, ["npcID"] = 223875 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223875, ["x"] = 0.46, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questGiverID"] = 223875, ["questType"] = "standard", ["sourceQuests"] = { 79197, 79573 }, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[82483] = { ["id"] = 82483, ["name"] = "Worldsoul: Spreading the Light", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "Darkness continues to spread through Hallowfall. We need your help to keep the fires burning! The shadows are deep and dark. My people are strong, but we always need more hope. More sparks for the flame. You are the brightest spark of all.", ["objectivesText"] = "Complete Spreading the Light objectives and slay Rare creatures in Khaz Algar.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["rewardItems"] = { 224784, 229354 }, ["rewardCurrencies"] = { { ["id"] = 3100, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.461, ["y"] = 0.496, ["mapID"] = 2339, ["npcID"] = 223875 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223875, ["x"] = 0.46, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questGiverID"] = 223875, ["questType"] = "standard", ["sourceQuests"] = { 79197, 79573 }, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[82485] = { ["id"] = 82485, ["name"] = "Worldsoul: Cinderbrew Meadery", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "Ah, Cinderbrew. It really is as stout and fiery a brew as they claim. I can't help but imagine it's how Beledar would taste... The earthen love it! And it's an important part of their heritage. And so we can't let their meadery fall into the wrong hands. But... watch out for the cinderbees. I hear their stingers are... well, I won't scare you with that. But I am glad I'm leaving this to you.", ["objectivesText"] = "Complete the Cinderbrew Meadery dungeon on Normal difficulty or higher.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["rewardItems"] = { 224784, 229354 }, ["starts"] = { { ["x"] = 0.461, ["y"] = 0.496, ["mapID"] = 2339, ["npcID"] = 223875 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223875, ["x"] = 0.46, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questGiverID"] = 223875, ["questType"] = "standard", ["sourceQuests"] = { 79197, 79573 }, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 48, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[82486] = { ["id"] = 82486, ["name"] = "Worldsoul: The Rookery", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = { "campaign" }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "The stormrooks these earthen tend are wonders to behold! Such magnificent plumage, such fierce personalities! It must be an honor to care for such creatures. But I hear there's some trouble at the Stormrider rookery and headquarters, the Stormperch. I haven't heard many details, but I'm certain our earthen allies would appreciate any assistance we can give. Look into it, .", ["objectivesText"] = "Complete the Rookery dungeon on Normal difficulty or higher.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["starts"] = { { ["x"] = 0.461, ["y"] = 0.496, ["mapID"] = 2339, ["npcID"] = 223875 } }, ["ends"] = { { ["x"] = 0.461, ["y"] = 0.496, ["mapID"] = 2339, ["npcID"] = 223875 } }, ["coords"] = { ["mapID"] = 2339, ["x"] = 0.461, ["y"] = 0.496 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 223875, ["questTurnInID"] = 223875, ["questType"] = "standard", ["sourceQuests"] = { 79197, 79573 }, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 47, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[82487] = { ["id"] = 82487, ["name"] = "Worldsoul: The Stonevault", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "Brinthe has been a wonderful resource for helping to reconnect the Arathi and the earthen. She's told me everything that happened recently with her people in the Ringing Deeps. I can... relate to feeling frustrated with the direction your people are taking. Fortunately, Steelstrike is a more reasonable leader than this... High Speaker Eirich. Eirich fled to the Stonevault to gather his forces. I know it would mean a lot to Brinthe and her people if you went after him and stopped his plans!", ["objectivesText"] = "Complete the Stonevault dungeon on Normal difficulty or higher. Progress: To corrupt your own people... I can't imagine how the old High Speaker could bear to do that.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["rewardItems"] = { 224784, 229354 }, ["rewardCurrencies"] = { { ["id"] = 3100, ["amount"] = 2 }, { ["id"] = 3100, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.461, ["y"] = 0.496, ["mapID"] = 2339, ["npcID"] = 223875 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223875, ["x"] = 0.46, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questGiverID"] = 223875, ["questType"] = "standard", ["sourceQuests"] = { 79197, 79573 }, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 46, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[82488] = { ["id"] = 82488, ["name"] = "Worldsoul: Darkflame Cleft", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = { "campaign" }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "Kobolds! They can be vicious critters but-- oh, I can't help but feel a certain kinship with them! Their little candles... keeping their little flames lit... So brave! They would be ideal Lamplighters, if only they would share! And... were less likely to claw your eyes out. Reports of their activities in Darkflame Cleft have the earthen worried. Though I wish the kobolds were kinder, we can't allow them to hurt our allies. Please investigate!", ["objectivesText"] = "Complete the Darkflame Cleft dungeon on Normal difficulty or higher.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["starts"] = { { ["x"] = 0.461, ["y"] = 0.496, ["mapID"] = 2339, ["npcID"] = 223875 } }, ["ends"] = { { ["x"] = 0.461, ["y"] = 0.496, ["mapID"] = 2339, ["npcID"] = 223875 } }, ["coords"] = { ["mapID"] = 2339, ["x"] = 0.461, ["y"] = 0.496 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 223875, ["questTurnInID"] = 223875, ["questType"] = "standard", ["sourceQuests"] = { 79197, 79573 }, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 44, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[82489] = { ["id"] = 82489, ["name"] = "Worldsoul: The Dawnbreaker", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "The Dawnbreaker... the magnus opus of the Hallowfall Arathi. The ship to end all wars. It is ready for launch. My friend, will you join it's charge? There are many who would dare step in its path.", ["objectivesText"] = "Complete The Dawnbreaker dungeon on Normal difficulty or higher.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["rewardItems"] = { 224784, 229354 }, ["rewardCurrencies"] = { { ["id"] = 3100, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.461, ["y"] = 0.496, ["mapID"] = 2339, ["npcID"] = 223875 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223875, ["x"] = 0.46, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questGiverID"] = 223875, ["questType"] = "standard", ["sourceQuests"] = { 79197, 79573 }, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[82490] = { ["id"] = 82490, ["name"] = "Worldsoul: Priory of the Sacred Flame", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = { "campaign" }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "My people have always had a close bond to the Light. A faith I once thought was unshakeable. But there are some-- There are some who believe that faith should be... enforced. This has always been something the Arathi has struggled with, even back in the Empire. But things have gone to far. These... zealots have taken over the Priory of the Sacred Flame. They're hurting people! This isn't what the Light is about, . Stop them.", ["objectivesText"] = "Complete the Priory of the Sacred Flame dungeon at Normal difficulty or higher.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["starts"] = { { ["x"] = 0.461, ["y"] = 0.496, ["mapID"] = 2339, ["npcID"] = 223875 } }, ["ends"] = { { ["x"] = 0.461, ["y"] = 0.496, ["mapID"] = 2339, ["npcID"] = 223875 } }, ["coords"] = { ["mapID"] = 2339, ["x"] = 0.461, ["y"] = 0.496 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 223875, ["questTurnInID"] = 223875, ["questType"] = "standard", ["sourceQuests"] = { 79197, 79573 }, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 17, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[82491] = { ["id"] = 82491, ["name"] = "Worldsoul: Ara-Kara, City of Echoes", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "Information from Azj-Kahet comes more in the form of... whispers than reports. We need more information. There's hints of a city beneath the city. Ara-Kara, they call it. We don't know the details, but they are doing something with Black Blood down there. We need to find out what's going on. Bring together your strongest companions and investigate!", ["objectivesText"] = "Complete the Ara-Kara, City of Echoes dungeon on Normal difficulty or higher.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["rewardItems"] = { 224784, 229354 }, ["rewardCurrencies"] = { { ["id"] = 3100, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.461, ["y"] = 0.496, ["mapID"] = 2339, ["npcID"] = 223875 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223875, ["x"] = 0.46, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questGiverID"] = 223875, ["questType"] = "standard", ["sourceQuests"] = { 79197, 79573 }, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 19, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[82492] = { ["id"] = 82492, ["name"] = "Worldsoul: City of Threads", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "Xal'atath has \"gifted\" the nerubians with Black Blood... giving them the means to ascend into things more terrible than they were before. We must take advantage of the confusion in the city. Bring together your allies and get ready to infiltrate... we must put a stop to them!", ["objectivesText"] = "Complete the City of Threads dungeon on Normal difficulty or higher.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["rewardItems"] = { 224784, 229354 }, ["rewardCurrencies"] = { { ["id"] = 3100, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.461, ["y"] = 0.496, ["mapID"] = 2339, ["npcID"] = 223875 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223875, ["x"] = 0.46, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questGiverID"] = 223875, ["questType"] = "standard", ["sourceQuests"] = { 79197, 79573 }, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 20, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[82493] = { ["id"] = 82493, ["name"] = "Worldsoul: The Dawnbreaker", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "The Dawnbreaker... the magnus opus of the Hallowfall Arathi. The ship to end all wars. It is ready for launch. My friend, will you join it's charge? There are many who would dare step in its path.", ["objectivesText"] = "Complete The Dawnbreaker dungeon on Heroic difficulty or higher. Progress: How goes the preparations?", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["rewardItems"] = { 224784, 229354 }, ["rewardCurrencies"] = { { ["id"] = 3100, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.461, ["y"] = 0.496, ["mapID"] = 2339, ["npcID"] = 223875 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223875, ["x"] = 0.46, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questGiverID"] = 223875, ["questType"] = "standard", ["sourceQuests"] = { 79197, 79573 }, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 21, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[82494] = { ["id"] = 82494, ["name"] = "Worldsoul: Ara-Kara, City of Echoes", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "Information from Azj-Kahet comes more in the form of... whispers than reports. We need more information. There's hints of a city beneath the city. Ara-Kara, they call it. We don't know the details, but they are doing something with Black Blood down there. We need to find out what's going on. Bring together your strongest companions and investigate!", ["objectivesText"] = "Complete the Ara-Kara, City of Echoes dungeon on Heroic difficulty or higher.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["rewardItems"] = { 224784, 229354 }, ["rewardCurrencies"] = { { ["id"] = 3100, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.461, ["y"] = 0.496, ["mapID"] = 2339, ["npcID"] = 223875 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223875, ["x"] = 0.46, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questGiverID"] = 223875, ["questType"] = "standard", ["sourceQuests"] = { 79197, 79573 }, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 22, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[82495] = { ["id"] = 82495, ["name"] = "Worldsoul: Cinderbrew Meadery", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "Ah, Cinderbrew. It really is as stout and fiery a brew as they claim. I can't help but imagine it's how Beledar would taste... The earthen love it! And it's an important part of their heritage. And so we can't let their meadery fall into the wrong hands. But... watch out for the cinderbees. I hear their stingers are... well, I won't scare you with that. But I am glad I'm leaving this to you.", ["objectivesText"] = "Complete the Cinderbrew Meadery dungeon on Heroic difficulty or higher.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["rewardItems"] = { 224784, 229354 }, ["starts"] = { { ["x"] = 0.461, ["y"] = 0.496, ["mapID"] = 2339, ["npcID"] = 223875 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223875, ["x"] = 0.46, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questGiverID"] = 223875, ["questType"] = "standard", ["sourceQuests"] = { 79197, 79573 }, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 52, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
