[82659] = { ["id"] = 82659, ["name"] = "Worldsoul: Nerub-ar Palace", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "Queen Ansurek has proven herself both cruel and cunning. We cannot allow her forces to continue to grow in strength with Xal'atath's black blood. It has come to this. A daunting task indeed. With the greatest of our forces, we shall lay siege to Nerub-ar Palace!", ["objectivesText"] = "Complete the Nerub-ar Palace raid on Normal difficulty or higher.", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["starts"] = { { ["x"] = 0.461, ["y"] = 0.496, ["mapID"] = 2339, ["npcID"] = 223875 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 223875, ["x"] = 0.46, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questGiverID"] = 223875, ["questType"] = "standard", ["sourceQuests"] = { 79197, 79573 }, ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[82672] = { ["id"] = 82672, ["name"] = "Another Timely Invitation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 1637, ["mapID"] = 84, ["storyline"] = { 82672 }, ["series"] = { 84254 }, ["description"] = "The bronze dragonflight is throwing a celebration just outside the Caverns of Time in Tanaris! There are all sorts of new activities to partake in that honor and remember what has transpired over the years. Head to Tanaris and join in the festivities.", ["objectivesText"] = "Visit the celebration in Tanaris outside the Caverns of Time.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 224334, ["x"] = 0.496, ["y"] = 0.71 }, { ["mapID"] = 85, ["npcID"] = 224419, ["x"] = 0.476, ["y"] = 0.779 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 223877, ["x"] = 0.628, ["y"] = 0.506 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.496, ["y"] = 0.71 }, ["mapCandidates"] = { ["npc"] = { 71, 84, 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 4063 }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[82676] = { ["id"] = 82676, ["name"] = "Broken Masquerade", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15, ["mapID"] = 70, ["storyline"] = { 82676 }, ["description"] = "I cannot remember how I arrived at this swamp, but it was great luck that I did. As I wandered, I spotted Lady Katrana Prestor entering a strange toothy cave. Now, what would a noblewoman be doing in such a ghoulish place? Following her closely, I found a great clutch of black dragon eggs within the lair. Such evidence is clear. Katrana is Lady Onyxia! I beg of you, aid me in defeating this vile dragon once and for all.", ["objectivesText"] = "Defeat Remembered Onyxia during a Radiant Echoes event. Progress: If only Varian were here. Surely he'd have no issue slaying her.", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 70, ["npcID"] = 224367, ["x"] = 0.454667, ["y"] = 0.575333 } }, ["ends"] = { { ["mapID"] = 70, ["npcID"] = 224367, ["x"] = 0.454667, ["y"] = 0.575333 } }, ["coords"] = { ["mapID"] = 70, ["source"] = "quest_giver", ["x"] = 0.454667, ["y"] = 0.575333 }, ["mapCandidates"] = { ["npc"] = { 70 }, ["zone"] = { 15 } }, ["questType"] = "standard" },
[82678] = { ["id"] = 82678, ["name"] = "Archives: The First Disc", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "I am pleased to report progress has been made restoring the titan Vault of Memory in the Archive. I have the mainframe up and running--but part of its internal mechanism has failed over time. Getting parts for it will be a challenge, which is why we need your help. Come with me to the Vault of Memory. We can discuss what we need with Dagran.", ["objectivesText"] = "Meet with Dagran in the Vault of Memory and assist him in finding titan disc fragments . These disc fragments can be looted from dungeons, delves, and dangerous creatures and treasures across Khaz Algar. Progress: Did you happen to find anything?", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["rewardItems"] = { 224784, 225741, 229354, 239118, 244865 }, ["rewardCurrencies"] = { { ["id"] = 3100, ["amount"] = 2 }, { ["id"] = 3100, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226511, ["x"] = 0.462, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226511, ["x"] = 0.462, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.462, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questTurnInID"] = 226511, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[82679] = { ["id"] = 82679, ["name"] = "Archives: Seeking History", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "meta" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "We're still processing the data in the Archive and restoring what we can. But... the discs we've recovered so far in the Archive itself are unusable. Finding more of these discs are a priority. We must reclaim our memories. Return what you find to Dagran. He is assisting me in rebuilding the Archive.", ["objectivesText"] = "Collect 100 titan disc fragments . These disc fragments can be looted from dungeons, delves, and dangerous creatures and treasures across Khaz Algar. Progress: Have ye found anythin'?", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["rewardItems"] = { 224784, 225741, 229354, 239118, 244865 }, ["rewardCurrencies"] = { { ["id"] = 3100, ["amount"] = 2 }, { ["id"] = 3100, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226511, ["x"] = 0.462, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226511, ["x"] = 0.462, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.462, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questTurnInID"] = 226511, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[82680] = { ["id"] = 82680, ["name"] = "Birdman of the Three Shields", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 82680, 82681, 82682, 82768 }, ["series"] = { 82681 }, ["description"] = "Are you here to watch the mosswools? No? That's too bad. I find the elemental creatures on our isle fascinating. I'm not the only one. An old friend of mine named Olbarig resides out on the Three Shields. He studies the wild cloudrooks there. But come to think of it, I haven't heard from him in awhile. Maybe someone should check on him. Hm. Would you mind?", ["objectivesText"] = "Find Olbarig on the Three Shields.", ["rewardGold"] = 77400, ["rewardXP"] = 2380, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 224394, ["x"] = 0.602, ["y"] = 0.282 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 224392, ["x"] = 0.7255, ["y"] = 0.1955 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.282 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78536 }, ["nextQuests"] = { 82681 }, ["questLines"] = { { ["id"] = 5590, ["name"] = "Life Finds a Way", ["orderIndex"] = 0, ["flags"] = 1 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[82681] = { ["id"] = 82681, ["name"] = "Cloudrook Down", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 82680, 82681, 82682, 82768 }, ["series"] = { 82680 }, ["description"] = "You see that flock in the distance? Wild cloudrooks. They've lived on these islands peacefully for ages. But recent events have stirred other elementals from the earth and sea. One of the cloudrooks was attacked, and it was... disincorporated. Now the flock circles endlessly. Surely they will tire soon. If they get too tired... Perhaps if we cleared the hostile elementals from this island, they will return and take their rest.", ["objectivesText"] = "Cull the riled elementals from the central Shield. Progress: This is the cloudrooks' habitat. Your crash and our war with the nerubians is what caused the other elementals to come. We should set this right.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 224392, ["x"] = 0.7255, ["y"] = 0.1955 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 224392, ["x"] = 0.7255, ["y"] = 0.1955 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.7255, ["y"] = 0.1955 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 82680 }, ["questLines"] = { { ["id"] = 5590, ["name"] = "Life Finds a Way", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[82682] = { ["id"] = 82682, ["name"] = "Elemental Hors D'Oeuvres", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 82680, 82681, 82682, 82768 }, ["description"] = "The cloudrooks cannot possibly circle forever, and I cannot bear more of them being lost. But maybe they'd roost if we tempted them with their favorite food? The eels that swim in these waters carry a small electrical charge not unlike the mosswool favored by their faster, stronger cousins the stormrooks. I once reasoned that cloudrooks might enjoy the eels for similar reasons. And I confess... I've been feeding them the eels ever since. Gather some up and give it a go.", ["objectivesText"] = "Gather 10 Electric Eels . Progress: The eels may not pack quite the punch of Rambleshire mosswool, but the cloudrooks seem to prefer it that way.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 232510 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 224392, ["x"] = 0.7255, ["y"] = 0.1955 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 224392, ["x"] = 0.7255, ["y"] = 0.1955 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.7255, ["y"] = 0.1955 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 82681 }, ["questLines"] = { { ["id"] = 5590, ["name"] = "Life Finds a Way", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[82689] = { ["id"] = 82689, ["name"] = "Only Darkness", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 65, ["mapID"] = 115, ["storyline"] = { 82689 }, ["description"] = "Long have I waited for this day, hero. Are you and your allies prepared to bring the Lich King to justice? We charge on your command!", ["objectivesText"] = "Defeat Remembered Lich King during a Radiant Echoes event. Progress: We battle for the fate of Azeroth. For the light of dawn!", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 115, ["npcID"] = 224373, ["x"] = 0.595, ["y"] = 0.52 } }, ["ends"] = { { ["mapID"] = 115, ["npcID"] = 224373, ["x"] = 0.595, ["y"] = 0.52 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.595, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 65 } }, ["questType"] = "standard" },
[82690] = { ["id"] = 82690, ["name"] = "Lingering Shadows", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2339, ["storyline"] = { 82690, 82691, 82692, 82693, 82694, 82695, 82696, 82697, 82698, 82699, 82700, 82701, 82702 }, ["description"] = "When we faced Xal'atath's forces in Hallowfall , I sensed something dark just beneath the surface. Something that was not her, but it still troubles me. I have learned that running into every situation myself is not always the best tactic. Sometimes, a leader must stand back to see the field. So, I send you. Go to Hallowfall , and uncover what you can about this mysterious force. I don't want to be caught blind again.", ["objectivesText"] = "Return to where Alleria sensed Black Blood in Hallowfall .", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 227758, ["x"] = 0.422, ["y"] = 0.27 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 224395, ["x"] = 0.63, ["y"] = 0.675 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 2215, 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5630, ["name"] = "Lingering Shadows", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 260, ["title"] = "Lingering Shadows", ["questLineID"] = 5630, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215, ["db2QuestHubAreaPoiID"] = 7898 },
[82691] = { ["id"] = 82691, ["name"] = "No Breathing Room", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 82690, 82691, 82692, 82693, 82694, 82695, 82696, 82697, 82698, 82699, 82700, 82701, 82702 }, ["description"] = "We all followed Orweyna to these surface caves because we believed in what we were doing. But this... We did not bargain for so many injuries, so much dogged searching. For now, we just need a little breathing room. Slay the creatures out there that are harming us, and we can get the space to address the real issue.", ["objectivesText"] = "Slay Seeping creatures. Progress: Our people are fierce and strong. We are accustomed to being outnumbered. But this is too much.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 56667, 56668, 56669, 131322 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 224397, ["x"] = 0.63, ["y"] = 0.675 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 224397, ["x"] = 0.63, ["y"] = 0.675 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.675 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 82690 }, ["questLines"] = { { ["id"] = 5630, ["name"] = "Lingering Shadows", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 260, ["title"] = "Lingering Shadows", ["questLineID"] = 5630, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[82692] = { ["id"] = 82692, ["name"] = "Price of a Mission", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 82690, 82691, 82692, 82693, 82694, 82695, 82696, 82697, 82698, 82699, 82700, 82701, 82702 }, ["description"] = "I don't know what prompted you to come here, but we could use your help. We came to investigate signs of the Black Blood in this area, but the creatures overwhelmed us. Several of us are still out in the field. You are hale and hearty. Go find my people so they can return. And, if you have the strength, take a closer look at the strange flowers that grow from the blood that seeps beneath the ground. They may hold a clue as to how we can fight against its corruption.", ["objectivesText"] = "Find the pinned-down haranir and examine Strange Flowers . Progress: Have you found my people?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 224395, ["x"] = 0.63, ["y"] = 0.675 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 224395, ["x"] = 0.63, ["y"] = 0.675 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.675 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 82690 }, ["questLines"] = { { ["id"] = 5630, ["name"] = "Lingering Shadows", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 260, ["title"] = "Lingering Shadows", ["questLineID"] = 5630, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[82693] = { ["id"] = 82693, ["name"] = "Standing in the Way", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 82690, 82691, 82692, 82693, 82694, 82695, 82696, 82697, 82698, 82699, 82700, 82701, 82702 }, ["description"] = "Some of these creatures are stronger than others. When we were able to act together and fresh to the fight, these creatures were no threat. Now our injuries and separation leave us vulnerable. My people are resilient, but we are not immortal. There is one beast larger than all the others. That beast is making it difficult for the haranir to return and recover. Slay it, so they can be safe.", ["objectivesText"] = "Defeat the Bloodcrust Behemoth . Progress: Once we are together again I know we will be able to regroup and continue.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 224395, ["x"] = 0.63, ["y"] = 0.675 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 224395, ["x"] = 0.63, ["y"] = 0.675 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.675 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 82690 }, ["questLines"] = { { ["id"] = 5630, ["name"] = "Lingering Shadows", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 260, ["title"] = "Lingering Shadows", ["questLineID"] = 5630, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[82694] = { ["id"] = 82694, ["name"] = "Together, Alone", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 82690, 82691, 82692, 82693, 82694, 82695, 82696, 82697, 82698, 82699, 82700, 82701, 82702 }, ["description"] = "I am not blind. I know that they are tired and weary. But we are so close to figuring out what we can do about the Black Blood. The importance of what we uncover goes beyond Hallowfall , or the nerubian kingdom. There is so much more work if we are to find a solution. For now, let us withdraw and recover. Somewhere away from these creatures.", ["objectivesText"] = "Meet Hannan in Hallowfall to hear the plan.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 224395, ["x"] = 0.63, ["y"] = 0.675 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 224740, ["x"] = 0.248, ["y"] = 0.516 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.675 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 82691, 82692, 82693 }, ["questLines"] = { { ["id"] = 5630, ["name"] = "Lingering Shadows", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 260, ["title"] = "Lingering Shadows", ["questLineID"] = 5630, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[82695] = { ["id"] = 82695, ["name"] = "The Voice", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 82690, 82691, 82692, 82693, 82694, 82695, 82696, 82697, 82698, 82699, 82700, 82701, 82702 }, ["description"] = "Here is where I must focus. I can hear the voice of my goddess, and she must be near. I will enter a meditation to ask what I must do. How can I continue this mission alone? How can I go on without the others? Stay close. I don't know what may lurk or threaten while I am concentrating.", ["objectivesText"] = "Defend Orweyna as she meditates. Progress: < Orweyna is unresponsive as she focuses entirely on her meditation.>", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 38718, 38751, 39022, 39051, 39089 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 15 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 224740, ["x"] = 0.248, ["y"] = 0.516 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 224740, ["x"] = 0.248, ["y"] = 0.516 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.248, ["y"] = 0.516 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 82694 }, ["questLines"] = { { ["id"] = 5630, ["name"] = "Lingering Shadows", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 260, ["title"] = "Lingering Shadows", ["questLineID"] = 5630, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[82696] = { ["id"] = 82696, ["name"] = "Ringing in the Deeps", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2215, ["storyline"] = { 82690, 82691, 82692, 82693, 82694, 82695, 82696, 82697, 82698, 82699, 82700, 82701, 82702 }, ["description"] = "My vision was clear to me. I need to continue this work. I need to find out how we can stop the Black Blood from spreading, before it's too late for your people, and for mine. Meet me in the Ringing Deeps . I will be in a form that allows me to hide and to listen without anyone noticing.", ["objectivesText"] = "Meet Orweyna at Camp Murroch in the Ringing Deeps .", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 224740, ["x"] = 0.248, ["y"] = 0.516 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 224856, ["x"] = 0.558667, ["y"] = 0.646 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.248, ["y"] = 0.516 }, ["mapCandidates"] = { ["npc"] = { 2214, 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 82695 }, ["questLines"] = { { ["id"] = 5630, ["name"] = "Lingering Shadows", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 260, ["title"] = "Lingering Shadows", ["questLineID"] = 5630, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[82697] = { ["id"] = 82697, ["name"] = "Good Help These Days", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 82690, 82691, 82692, 82693, 82694, 82695, 82696, 82697, 82698, 82699, 82700, 82701, 82702 }, ["series"] = { 82699 }, ["description"] = "Seeing you here is a welcome surprise! There's something big happening over at Opportunity Point, but it's hard to know what without getting closer to the people working there. I know Haxle's involved. We'll need his paperwork if we want to be able to ask around without trouble. He's headed down to Opportunity Point. Go, follow him, and see if he's got anything on him we can use. Don't worry about the mess-- I know you're discreet when you need to be. And... also not, when you need to be.", ["objectivesText"] = "Find Haxle Drillbit and shake him down for access to the operation. Progress: Got that work order? We can open up way more doors with it than without it.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 225913 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 224857, ["x"] = 0.570667, ["y"] = 0.646 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 224874, ["x"] = 0.631333, ["y"] = 0.796 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.570667, ["y"] = 0.646 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 82696 }, ["questLines"] = { { ["id"] = 5630, ["name"] = "Lingering Shadows", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 260, ["title"] = "Lingering Shadows", ["questLineID"] = 5630, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[82698] = { ["id"] = 82698, ["name"] = "Haywired and Hostile", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 82690, 82691, 82692, 82693, 82694, 82695, 82696, 82697, 82698, 82699, 82700, 82701, 82702 }, ["description"] = "I saw many machines nearby, and all of them seem to make dreadful noises. I cannot hear the one that I heard in the vision, though, at least not clearly. Destroy the excess ones. They are only in the way. While you are quieting the scene, I will hunt and scout.", ["objectivesText"] = "Destroy the haywire excavators . Progress: You're not who I expected to see here.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 224866, ["x"] = 0.630667, ["y"] = 0.796 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 224913, ["x"] = 0.583, ["y"] = 0.87 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.630667, ["y"] = 0.796 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 82697 }, ["questLines"] = { { ["id"] = 5630, ["name"] = "Lingering Shadows", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 260, ["title"] = "Lingering Shadows", ["questLineID"] = 5630, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[82699] = { ["id"] = 82699, ["name"] = "Hey, What's Going On?", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 82690, 82691, 82692, 82693, 82694, 82695, 82696, 82697, 82698, 82699, 82700, 82701, 82702 }, ["series"] = { 82697 }, ["description"] = "Time to do some networking. There's a bunch of goblins outside of Opportunity Point, over there in the Abyssal Excavation. I heard some of them grumbling as they started their shift. Let's see what some friendly words shake loose. While you're out there, check out the used fuel drums . They wouldn't let me look inside the full drums, but they just drop the used ones around the work site.", ["objectivesText"] = "Search for clues by questioning goblins and uncovering evidence in the Abyssal Excavation. Progress: We've got to stop meeting like this. Assuming we've met before, which, maybe we have.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 224874, ["x"] = 0.631333, ["y"] = 0.796 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 224913, ["x"] = 0.583, ["y"] = 0.87 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.631333, ["y"] = 0.796 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 82697 }, ["questLines"] = { { ["id"] = 5630, ["name"] = "Lingering Shadows", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 260, ["title"] = "Lingering Shadows", ["questLineID"] = 5630, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[82700] = { ["id"] = 82700, ["name"] = "Built to Blast", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 82690, 82691, 82692, 82693, 82694, 82695, 82696, 82697, 82698, 82699, 82700, 82701, 82702 }, ["description"] = "We've got an intel problem, but we've also got a clank problem. If you look over there, there's a big, haywire mech that's just going crazy. There's no way anyone's going to uncover anything while that's out in the field. We should do something about that.", ["objectivesText"] = "Destroy the Haywire MEK IV .", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 15 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 224913, ["x"] = 0.583, ["y"] = 0.87 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 224866, ["x"] = 0.630667, ["y"] = 0.796 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.583, ["y"] = 0.87 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 82698, 82699 }, ["questLines"] = { { ["id"] = 5630, ["name"] = "Lingering Shadows", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 260, ["title"] = "Lingering Shadows", ["questLineID"] = 5630, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[82701] = { ["id"] = 82701, ["name"] = "Bat Versus World", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 82690, 82691, 82692, 82693, 82694, 82695, 82696, 82697, 82698, 82699, 82700, 82701, 82702 }, ["description"] = "When I scouted, I heard and saw things that I don't understand. Perhaps if I describe it to you and the goblins, you will know what it means.", ["objectivesText"] = "Experience Orweyna 's scouting mission.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardCurrencies"] = { { ["id"] = 2919, ["amount"] = 5 }, { ["id"] = 3008, ["amount"] = 15 }, { ["id"] = 3111, ["amount"] = 5 }, { ["id"] = 3285, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 224866, ["x"] = 0.630667, ["y"] = 0.796 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 224866, ["x"] = 0.630667, ["y"] = 0.796 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.630667, ["y"] = 0.796 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 82700 }, ["questLines"] = { { ["id"] = 5630, ["name"] = "Lingering Shadows", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 260, ["title"] = "Lingering Shadows", ["questLineID"] = 5630, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[82702] = { ["id"] = 82702, ["name"] = "Found Friends", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 82690, 82691, 82692, 82693, 82694, 82695, 82696, 82697, 82698, 82699, 82700, 82701, 82702 }, ["description"] = "So Gallywix has chosen to show his ugly face here, and it looks like he's got himself organized. We should report this to Alleria. See how she wants to handle it.", ["objectivesText"] = "Report to Alleria in Dornogal.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 224874, ["x"] = 0.631333, ["y"] = 0.796 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 227758, ["x"] = 0.422, ["y"] = 0.27 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.631333, ["y"] = 0.796 }, ["mapCandidates"] = { ["npc"] = { 2214, 2339 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 82701 }, ["questLines"] = { { ["id"] = 5630, ["name"] = "Lingering Shadows", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 260, ["title"] = "Lingering Shadows", ["questLineID"] = 5630, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[82706] = { ["id"] = 82706, ["name"] = "Delves: Worldwide Research", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "meta" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82449, 82452, 82453, 82482, 82483, 82485, 82486, 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495, 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504, 82505, 82506, 82507, 82508, 82509, 82510, 82511, 82512, 82516, 82659, 82678, 82679, 82706, 87417, 87419, 87422, 87423, 87424, 89039, 89492, 89502, 89514, 91052, 91205, 91855, 92331, 92332 }, ["description"] = "It's been all quiet recently. I've nae heard of any issues. This seems like a good opportunity for exploration, eh? I'm at yer disposal! We can go wherever it is ye want tae go!", ["objectivesText"] = "Complete 3 Delves in The War Within. Progress: Dangerous exploration? Survivin' by the skin of our teeth? Makes this ol' <race> feel alive!", ["rewardGold"] = 619600, ["rewardXP"] = 14275, ["rewardItems"] = { 224784, 229354, 239118, 244865 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 206017, ["x"] = 0.475, ["y"] = 0.445 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 206017, ["x"] = 0.475, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5572, ["name"] = "Khaz Algar Emissary", ["orderIndex"] = 51, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[82739] = { ["id"] = 82739, ["name"] = "Twilight Scheming", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 1584, ["mapID"] = 84, ["storyline"] = { 82739 }, ["description"] = "The influence of Twilight's Hammer grows within Blackrock Depths . They have allied with the Dark Iron dwarves and seek to convince them to strike outside the mountain. We must destroy the instruments of the Twilight's Hammer agitation. Their influence over the Dark Irons must be minimized. I want you to go into Domicile portion of Blackrock Depths and use this torch to burn the books that the Twilight's Hammer is distributing there.", ["objectivesText"] = "Use the Glowing Torch to destroy 8 copies of The Twilight Creed in the Domicile of Blackrock Depths .", ["rewardGold"] = 638000, ["rewardXP"] = 3455, ["rewardItems"] = { 63428, 65616, 65633, 65634, 65635, 65636, 65637 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1584 } }, ["questType"] = "dungeon" },
[82740] = { ["id"] = 82740, ["name"] = "Twilight Scheming", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 1584, ["mapID"] = 84, ["storyline"] = { 82740 }, ["description"] = "The influence of Twilight's Hammer grows within Blackrock Depths . They have allied with the Dark Iron dwarves and seek to convince them to strike outside the mountain. We must destroy the instruments of the Twilight's Hammer agitation. Their influence over the Dark Irons must be minimized. I want you to go into Domicile portion of Blackrock Depths and use this torch to burn the books that the Twilight's Hammer is distributing there.", ["objectivesText"] = "Use the Glowing Torch to destroy 8 copies of The Twilight Creed in the Domicile of Blackrock Depths .", ["rewardGold"] = 210000, ["rewardXP"] = 3455, ["rewardItems"] = { 63428, 65616, 65633, 65634, 65635, 65636, 65637 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1584 } }, ["questType"] = "dungeon" },
[82747] = { ["id"] = 82747, ["name"] = "Crossroads Plaza", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 82747 }, ["description"] = "Hello, outlander. Do you want to know about news from outside the city? The Crossroads is a key place for earthen to exchange information and goods, no matter their allegiances or edicts. My friend Bondaz unofficially maintains the square. He would be delighted to see you in person. I'm sure he has already heard a hundred different stories of how you and the outlanders made it to our isle.", ["objectivesText"] = "Meet Bondaz in Crossroads Plaza.", ["rewardGold"] = 28900, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 224544, ["x"] = 0.465, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 224566, ["x"] = 0.552, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 2248, 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[82748] = { ["id"] = 82748, ["name"] = "Deephaul Ravine", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14990, ["mapID"] = 2339, ["storyline"] = { 82748 }, ["description"] = "We've received reports of troubles in the earthen depths. Explore the Deephaul Ravine and the resources available, then report to Ruffious .", ["objectivesText"] = "Complete the Deephaul Ravine battleground.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219260, ["x"] = 0.588, ["y"] = 0.754 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.754 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "pvp" },
[82762] = { ["id"] = 82762, ["name"] = "Keeping a Close Tabard", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 82762 }, ["description"] = "Wow! That's a super nifty tabard! And it's all yours to customize however you want. Kessa should be able to help you bring your designs to life. Go ahead and pay her a visit to get started!", ["objectivesText"] = "Speak with Kessa in the Victorious Visage. Progress: Kessa is a very skilled tabard designer!", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 216946, ["x"] = 0.403714, ["y"] = 0.557429 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 224600, ["x"] = 0.295, ["y"] = 0.473 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.403714, ["y"] = 0.557429 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["sourceQuests"] = { 79513 } },
[82768] = { ["id"] = 82768, ["name"] = "Cloud Fishing", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 82680, 82681, 82682, 82768 }, ["description"] = "Now that we have the eels, we can try to lure the cloudrooks back to land. Head over to the neighboring island. Get as close as you can and make an offering to the rooks. With luck, they'll cease their circling and come down for a nourishing meal.", ["objectivesText"] = "Offer 7 Electric Eels to Wild Cloudrooks. Progress: Nothing better than electric eels to sate a tired and hungry cloudrook.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 109076, 224119, 228370, 228371, 228372, 228373 }, ["rewardCurrencies"] = { { ["id"] = 2897, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 224392, ["x"] = 0.7255, ["y"] = 0.1955 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 224392, ["x"] = 0.7255, ["y"] = 0.1955 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.7255, ["y"] = 0.1955 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 82682 }, ["questLines"] = { { ["id"] = 5590, ["name"] = "Life Finds a Way", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[82771] = { ["id"] = 82771, ["name"] = "Heritage of the Earthen", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["requiredRaces"] = { 84, 85 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82771 }, ["description"] = "The time has come to give back to the Archives. All earthen wanderers are invited to share their experiences for the preservation of what has come before and the betterment of those who will come after. This knowledge and experience of the wider world of Azeroth is a priceless treasure, and the practice of sharing it is key to our earthen heritage.", ["objectivesText"] = "Upload experiences to the Archives in Dornogal. Progress: Have you uploaded your experiences yet?", ["starts"] = { { ["x"] = 0.29, ["y"] = 0.596, ["mapID"] = 2339, ["npcID"] = 224790 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 224790, ["x"] = 0.292667, ["y"] = 0.595333 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.292667, ["y"] = 0.595333 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questGiverID"] = 224790, ["questType"] = "standard" },
[82773] = { ["id"] = 82773, ["name"] = "A Functional Favor", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 82773, 82774, 82785, 82786, 82814, 82969, 82990 }, ["series"] = { 82774 }, ["description"] = "I am seeking my mentor, Foreman Arbauch. He is... missing. Under other circumstances, I would send for a search party from Gundargaz, but there is no time. I suspect he passed through here, but the only lead I have is DelGizmo. He wants the local fog beasts removed. Reluctance. But if he has seen Arbauch, I must learn what he knows. The lurkers to the south carry powerful Galvanic Glands . They have enough charge to disperse even the thickest fog. Retrieve some. Compensation assured.", ["objectivesText"] = "Collect 6 Galvanic Glands . Progress: Haste is appreciated. I must find Arbauch.", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["rewardItems"] = { 224271 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 224602, ["x"] = 0.5692, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 224602, ["x"] = 0.5692, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.5692, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79573, 80434 }, ["questLines"] = { { ["id"] = 5611, ["name"] = "Routine Maintenance", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[82774] = { ["id"] = 82774, ["name"] = "Antifogmatic", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 82773, 82774, 82785, 82786, 82814, 82969, 82990 }, ["series"] = { 82773 }, ["description"] = "Machine speakers have no love for fog beasts. Where there is fog, rust is sure to follow. Still, I'd prefer not to harm them. Arbauch always said it was bad luck. Take this device. The glands you collected should provide enough power to disperse the fog without hurting the fog beasts within. Caution. Fog beasts are skittish, but other creatures may also lurk.", ["objectivesText"] = "Disperse the fog around Camp Murroch. Progress: Is it done? We have little time to waste.", ["rewardGold"] = 154900, ["rewardXP"] = 4960, ["rewardItems"] = { 224438 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 224602, ["x"] = 0.5692, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 224602, ["x"] = 0.5692, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.5692, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 82773 }, ["questLines"] = { { ["id"] = 5611, ["name"] = "Routine Maintenance", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[82775] = { ["id"] = 82775, ["name"] = "Quickchange Artist", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 82775 }, ["description"] = "You seem to have the programming of a great actor within you, $p! I know it because I have that fire myself--no matter what the rest of these so-called \"actors\" say. I'm very impressed with how fast you change costumes. I am a master of the quickchange artist's ways myself, you know. You're very close to figuring it out. You just need a few pointers from an expert--like me!", ["objectivesText"] = "Receive tips from Wendeline in the Proscenium.", ["rewardGold"] = 29200, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 215748, ["x"] = 0.568, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 215748, ["x"] = 0.568, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14776 } }, ["questType"] = "standard" },
[82778] = { ["id"] = 82778, ["name"] = "Hallowfall Fishing Derby", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 82778, 83529, 83530, 83531, 83532 }, ["description"] = "Life is always on the edge here, $p. Nerubians, kobyss, hunger--there's always something ready to kill you. So we need to find times to relax, and challenge ourselves at something other than survival. Like fishing. My dad always spent Saturdays fishing, when I was growing up. He'd say, \"Take some time for yourself, or you can't be effective for others.\" So every Saturday, I challenge people to the Hallowfall Fishing Derby. You have one hour to catch trophy fish. See what you can bring me!", ["objectivesText"] = "Catch these Trophy Fish before the Derby Dasher buff expires: Nibbling Minnow, Arathor Hammerfish, Queen's Lureback.", ["rewardItems"] = { 33820, 44050, 168417, 191356, 202207, 212310, 217375, 219002, 219003, 219004, 219005, 219006, 220134, 220135, 220136, 220137, 220138, 220139, 220141, 220142, 220143, 220144, 220145, 220146, 220147, 220148, 220149, 220150, 220151, 220152, 220153, 221790, 222533, 222745, 222842, 223286, 223979, 224717, 224727, 224752, 225592, 225758, 225763, 225770, 225771, 225892, 226376, 226378, 226379, 226392, 228421, 228422, 228423, 228954 }, ["rewardChoices"] = { 224752, 225771, 225770 }, ["rewardCurrencies"] = { { ["id"] = 3055, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 226846, ["x"] = 0.424667, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 226846, ["x"] = 0.424667, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.424667, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5637, ["name"] = "Hallowfall Fishing Derby", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[82781] = { ["id"] = 82781, ["name"] = "Attention-Getter", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 82781 }, ["description"] = "My, $p, it seems you have drawn the attention of a particular audience member. This fan letter was mistakenly included in my fan mail. I'm not surprised. Sorting my copious fan mail must be a difficult chore... Here, take it. It belongs to you, of course. I'm sure this is very new for you. I have a few pieces of wisdom for greeting eager fans, if you would like to hear it...", ["objectivesText"] = "Receive tips from Elma in the Proscenium.", ["rewardGold"] = 30900, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 217248, ["x"] = 0.566, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 217248, ["x"] = 0.566, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard" },
[82782] = { ["id"] = 82782, ["name"] = "Authenticity in Dress", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 82782 }, ["description"] = "You've done very well as an actor on stage, $p. But as an actor in a troupe, there are other directives we must carry out. One directive is to preserve our costumes for use in future plays. Many costumes we use more than once. I think we can trust you with using and preserving the troupes' costumes, don't you think? It would mean you could practice with us more frequently...", ["objectivesText"] = "Speak with Rabaan in the Proscenium.", ["rewardGold"] = 29200, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 215745, ["x"] = 0.566, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 215745, ["x"] = 0.566, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14776 } }, ["questType"] = "standard" },
[82783] = { ["id"] = 82783, ["name"] = "Chromie's Codex", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 82783 }, ["description"] = "Hello there! I could really use your help. You see, my codex has gotten a bit jumbled in all my travels lately, and I have to give a time tour back to the gates of Ahn'Qiraj in an hour. I need you to jump in with me to sort out any... inconsistencies. Then it should be right as rain and all the visitors here will have a fun, not-super-dangerous tour!", ["objectivesText"] = "Complete the Codex of Chromie event. Progress: Whew, that was pretty dicey there for a moment. I thought you might not have made it!", ["rewardItems"] = { 232877, 233014 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 100 }, { ["id"] = 1166, ["amount"] = 200 }, { ["id"] = 3100, ["amount"] = 3 } }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 226368, ["x"] = 0.626, ["y"] = 0.5 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226368, ["x"] = 0.626, ["y"] = 0.5 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.626, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 4063 }, ["db2QuestSortName"] = "Nightborne" },
[82784] = { ["id"] = 82784, ["name"] = "Resonant Performance", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 82784 }, ["description"] = "$p, I have learned a lot from watching you perform. You change your nature so easily. In one play, I have seen you change from enemy to friend, from anger to sorrow... It's like watching mercury flow. With you on our stage, I feel we complete our plays to the letter of our directives with the highest satisfaction for our audience. If you have a moment, I would like to thank you for your support.", ["objectivesText"] = "Speak with Burkhalt in the Proscenium.", ["rewardGold"] = 30900, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 215744, ["x"] = 0.566, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 215744, ["x"] = 0.566, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14776 } }, ["questType"] = "standard" },
[82785] = { ["id"] = 82785, ["name"] = "Ghosts in the Machine", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 82773, 82774, 82785, 82786, 82814, 82969, 82990 }, ["series"] = { 82786, 82814, 82969, 82990 }, ["description"] = "There's a substation directly below us? Perhaps that is where Arbauch went to hide it... Disregard, we must investigate. With luck, Arbauch may still be here. The entrance should be to the north, near the pool of water from the burst pipe. Please, come with me. He may need our help. I will explain everything once he is located.", ["objectivesText"] = "Find Foreman Arbauch.", ["rewardGold"] = 146000, ["rewardXP"] = 4960, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 224602, ["x"] = 0.5692, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 224602, ["x"] = 0.5692, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.5692, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 82774 }, ["questLines"] = { { ["id"] = 5611, ["name"] = "Routine Maintenance", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[82786] = { ["id"] = 82786, ["name"] = "Duty of Care", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 82773, 82774, 82785, 82786, 82814, 82969, 82990 }, ["series"] = { 82785, 82814, 82969, 82990 }, ["description"] = "The golem is unstable. I doubt it can travel far. We will track it, but haste failed me once already. Arbauch showed true devotion to the machines--we will follow his example. Repairs must come first. Machine systems are delicate. We must activate the backup before the failure can cascade. Exterminate any pests you find as well. Even the smallest creature can ruin delicate machinery. I am damaged. I will send my cogwalker with you to relay instructions.", ["objectivesText"] = "Activate the backup systems along the Cataract River. Progress: Our primary duty is to mend.", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 224602, ["x"] = 0.5692, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 224618, ["x"] = 0.467, ["y"] = 0.62 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.5692, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 82990 }, ["questLines"] = { { ["id"] = 5611, ["name"] = "Routine Maintenance", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[82787] = { ["id"] = 82787, ["name"] = "Special Assignment: Rise of the Colossals", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 80412, 81620, 81622, 81862, 82041, 82088, 82120, 82133, 82197, 82206, 82254, 82257, 82258, 82259, 82288, 82582, 82583, 82584, 82585, 82586, 82787, 82852 }, ["description"] = "WQ", ["objectivesText"] = "Kill Colossal beasts", ["rewardXP"] = 11765, ["rewardItems"] = { 224183 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14838 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5575, ["name"] = "Hallowfall - World Quests/Repeatables", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2Objectives"] = { { ["text"] = "Gather Bleak Chum to bait Frothing Waters", ["amount"] = 3, ["type"] = 1, ["objectID"] = 224183, ["orderIndex"] = 0 }, { ["text"] = "Colossals Slain", ["amount"] = 3, ["type"] = 0, ["objectID"] = 224621, ["orderIndex"] = 1 } }, ["activities"] = { ["groupFinder"] = { { ["id"] = 1537, ["name"] = "Hallowfall", ["mapID"] = 0, ["difficultyID"] = 0, ["expansion"] = 10, ["maxPlayers"] = 0 } } }, ["db2LabelIDs"] = { 3549 }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215, ["db2QuestInfoID"] = 286, ["db2QuestInfoName"] = "Capstone World Quest" },
[82792] = { ["id"] = 82792, ["name"] = "All Ore Nothing", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 82792, 82796, 82797, 82798, 82799, 82800, 82801 }, ["series"] = { 82796 }, ["description"] = "Outlander. Your aid is requested. The earthen here have said you would be of help. Our fellow earthen at the Opalcreg have not reported their quota for the past day. There must be something causing a disruption. Would you pay Foreman Alvegar a visit?", ["objectivesText"] = "Go to the Opalcreg and seek out Alvegar .", ["rewardGold"] = 28900, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 218535, ["x"] = 0.41, ["y"] = 0.72 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 224707, ["x"] = 0.467333, ["y"] = 0.619333 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.41, ["y"] = 0.72 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78536, 79573 }, ["questLines"] = { { ["id"] = 5591, ["name"] = "Opalcreg", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[82796] = { ["id"] = 82796, ["name"] = "Third Mine Blind", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 82792, 82796, 82797, 82798, 82799, 82800, 82801 }, ["series"] = { 82792 }, ["description"] = "I got cut off from the rest of the crew. We did not expect to be attacked by nerubians. Though I can't imagine the rest quitting. Our duty is too important to give up just yet. Barging right into the mine could cause the nerubians to frenzy and hurt the others. So, I found a third way to get in earlier. Though undetected will still be tough. Follow me.", ["objectivesText"] = "Meet Alvegar at the third entrance of the Opalcreg.", ["rewardGold"] = 154900, ["rewardXP"] = 4760, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 224707, ["x"] = 0.467333, ["y"] = 0.619333 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 224707, ["x"] = 0.467333, ["y"] = 0.619333 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.467333, ["y"] = 0.619333 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 82792 }, ["questLines"] = { { ["id"] = 5591, ["name"] = "Opalcreg", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[82797] = { ["id"] = 82797, ["name"] = "Hit Rock Bottom", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 82792, 82796, 82797, 82798, 82799, 82800, 82801 }, ["description"] = "A long way down to be sure, but I am certain that you can make it. If you doubt yourself, I made some parachutes to help you stick the landing. Once you get to the bottom of the cave, look for Cenderragg . She's the most senior of the group and probably has the best idea on how to rescue the team.", ["objectivesText"] = "Get to the bottom of the mine and find Cenderragg .", ["rewardGold"] = 154900, ["rewardXP"] = 4760, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 224707, ["x"] = 0.467333, ["y"] = 0.619333 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 224708, ["x"] = 0.48, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.467333, ["y"] = 0.619333 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 82796 }, ["questLines"] = { { ["id"] = 5591, ["name"] = "Opalcreg", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[82798] = { ["id"] = 82798, ["name"] = "An Opal of Mine", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 82792, 82796, 82797, 82798, 82799, 82800, 82801 }, ["description"] = "I'll be direct with you. We have a goal here and those opals are the center of it. No one will leave until we get the job done, the opals are too important. If you could gather enough ore, we could convince them to leave. But be careful, those nerubians are dangerous.", ["objectivesText"] = "Help Cenderragg collect 8 Opal Ore from the Opalcreg. Progress: Why did the nerubians have to show up? We were almost complete.", ["rewardGold"] = 292100, ["rewardXP"] = 9515, ["rewardItems"] = { 224808 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 224708, ["x"] = 0.48, ["y"] = 0.608 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 224708, ["x"] = 0.48, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 82797 }, ["questLines"] = { { ["id"] = 5591, ["name"] = "Opalcreg", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[82799] = { ["id"] = 82799, ["name"] = "Web Beats Rock", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 82792, 82796, 82797, 82798, 82799, 82800, 82801 }, ["description"] = "So, Foreman Alvegar sent you? That explains it. The situation is not great. This place is crawling with nerubians and they're showing us no mercy. They forced us to mine and took our hard-earned opals. When you disobey, they web you up. I was barely able to escape them when they came. The others... Well, that's where you come in. With you here distracting them, I can go rally the webbed earthen.", ["objectivesText"] = "Rescue 6 earthen workers in the Opalcreg.", ["rewardGold"] = 300800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 224708, ["x"] = 0.48, ["y"] = 0.608 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 224708, ["x"] = 0.48, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 82797 }, ["questLines"] = { { ["id"] = 5591, ["name"] = "Opalcreg", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[82800] = { ["id"] = 82800, ["name"] = "A Sedimental Moment", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 82792, 82796, 82797, 82798, 82799, 82800, 82801 }, ["description"] = "Some have started to evacuate, but there's a stubborn few that just won't let go. Could you say something? Maybe an outsider's perspective will get them moving.", ["objectivesText"] = "Help Cenderrag inspire the earthen workers in the Opalcreg. Progress: Why must these few be so stubborn?", ["rewardGold"] = 300800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 224708, ["x"] = 0.48, ["y"] = 0.608 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 224708, ["x"] = 0.48, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 82798, 82799 }, ["questLines"] = { { ["id"] = 5591, ["name"] = "Opalcreg", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[82801] = { ["id"] = 82801, ["name"] = "Beetlejeweled", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 82792, 82796, 82797, 82798, 82799, 82800, 82801 }, ["description"] = "To make sure no other earthen gets harmed we're going to have to eliminate their leader. You know the saying, rid yourself of the foreman and the whole line collapses. Either way, to get to safety we're going to have to go through them.", ["objectivesText"] = "Defeat Kix'arak outside of the Opalcreg Mine.", ["rewardGold"] = 584200, ["rewardXP"] = 11895, ["rewardItems"] = { 228374, 228375, 228376, 228377 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 25 }, { ["id"] = 2897, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 224708, ["x"] = 0.48, ["y"] = 0.608 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 218535, ["x"] = 0.41, ["y"] = 0.72 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 82800 }, ["questLines"] = { { ["id"] = 5591, ["name"] = "Opalcreg", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[82809] = { ["id"] = 82809, ["name"] = "Gryphons of a Feather", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 16105, ["mapID"] = 2352, ["storyline"] = { 82809 }, ["description"] = "Hey there! I notice ye got a stormrook that's lookin' rather unhappy. Let's see what we can do to cheer 'em up.", ["objectivesText"] = "Find a way to cheer up Squally . Progress: Kwee wah?", ["rewardGold"] = 341600, ["rewardItems"] = { 200476, 224259, 224260, 224261 }, ["starts"] = { { ["npcID"] = 209681 } }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16105 } }, ["questGiverID"] = 209681, ["questType"] = "standard" },
[82810] = { ["id"] = 82810, ["name"] = "Time Found", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 80673, 80677, 80678, 82810, 82813 }, ["description"] = "Yer back! If you're up for it, there's more things in the muck to be found. Might have to dig a bit deeper this time.", ["objectivesText"] = "Find 6 lost mementos. Progress: What'd you find?", ["rewardXP"] = 11765, ["rewardItems"] = { 224179, 224184, 224186, 224187, 224188, 224189, 224266, 224267, 224268 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 220718, ["x"] = 0.604, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 220718, ["x"] = 0.604, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 80678 }, ["questLines"] = { { ["id"] = 5609, ["name"] = "Memories of the Sky", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[82813] = { ["id"] = 82813, ["name"] = "Time Borrowed", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 80673, 80677, 80678, 82810, 82813 }, ["description"] = "Ah, now there's my good friend! Me and Mags are still here, looking for memories. Got a moment to spare for help?", ["objectivesText"] = "Find 6 lost mementos. Progress: What'd you find?", ["rewardGold"] = 202200, ["rewardXP"] = 11765, ["rewardItems"] = { 139506, 139770, 224187, 224238, 224239, 224250, 224254, 224257, 224272, 224273, 224274 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 220718, ["x"] = 0.604, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 220718, ["x"] = 0.604, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 82810 }, ["questLines"] = { { ["id"] = 5609, ["name"] = "Memories of the Sky", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[82814] = { ["id"] = 82814, ["name"] = "Decommissioning Darkness", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 82773, 82774, 82785, 82786, 82814, 82969, 82990 }, ["series"] = { 82785, 82786, 82969, 82990 }, ["description"] = "Decommissioning a machine is a rare necessity. It must be done with care and regret. We put much of ourselves into our work. To destroy it is to destroy a part of ourselves. In doing so, we admit our failure to protect the Titans' work. But where stone rebels against stone, we must stand firm. Imperative: Destroy it. Recover Arbauch's memory gem .", ["objectivesText"] = "Destroy the Corrupted Golem and recover Foreman Arbauch's memory gem . Progress: Regret. This should have been my burden.", ["rewardGold"] = 619600, ["rewardXP"] = 12400, ["rewardItems"] = { 224555 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 180 }, { ["id"] = 2902, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 224618, ["x"] = 0.467, ["y"] = 0.62 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 224602, ["x"] = 0.5692, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.467, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 82786, 82969 }, ["questLines"] = { { ["id"] = 5611, ["name"] = "Routine Maintenance", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[82815] = { ["id"] = 82815, ["name"] = "Sturdy Locket", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 82815 }, ["objectivesText"] = "Progress: What do you have there?", ["rewardGold"] = 29200, ["rewardXP"] = 1470, ["rewardItems"] = { 219105, 224274 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 220859, ["x"] = 0.4288, ["y"] = 0.5028 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 220859, ["x"] = 0.4288, ["y"] = 0.5028 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.4288, ["y"] = 0.5028 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 82813 } },
[82817] = { ["id"] = 82817, ["name"] = "Disturbance Detected: Blackrock Depths", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 1584, ["mapID"] = 71, ["storyline"] = { 82817 }, ["description"] = "The Timewalkers claim that they detected a time-displaced object in Blackrock Depths . While that fight may have ended in our defeat, the Dark Iron clan knows what's at stake should history change. We could lose the current dwarven alliance and all the good it has brought. Recover the object and protect our current peace.", ["objectivesText"] = "Recover the Timewarped Ironforge Blueprints from Emperor Thaurissan in Blackrock Depths . Progress: It brings me no pleasure, asking you tae fight against us. I feel for the bronze dragons and all the work they do tae protect the timeline.", ["rewardItems"] = { 224278, 232471, 232877 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 300 }, { ["id"] = 1166, ["amount"] = 500 }, { ["id"] = 2915, ["amount"] = 10 }, { ["id"] = 3008, ["amount"] = 45 } }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 229494, ["x"] = 0.63, ["y"] = 0.496 }, { ["mapID"] = 84, ["npcID"] = 234556, ["x"] = 0.558, ["y"] = 0.186 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 229494, ["x"] = 0.63, ["y"] = 0.496 }, { ["mapID"] = 84, ["npcID"] = 234556, ["x"] = 0.558, ["y"] = 0.186 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.496 }, ["mapCandidates"] = { ["npc"] = { 71, 84 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
