[82836] = { ["id"] = 82836, ["name"] = "Zero Out Xerosh", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78658, 78659, 78665, 78666, 78667, 78668, 78669, 78670, 78671, 79999, 82836, 83551 }, ["description"] = "$p, the nerubians all seem to be taking orders from that siegelord south of here. If we can defeat her, that may turn the tide of this attack. Without a leader organizing the attack, the Arathi may be able to drive back the nerubians, especially if Faerin is able to light this dawntower she spoke of. But the longer we delay, the greater damage to the Arathi airships. Go quickly!", ["objectivesText"] = "Defeat Siegelord Xerosh . Progress: Were you able to defeat the siegelord?", ["rewardGold"] = 619600, ["rewardXP"] = 12740, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 213120, ["x"] = 0.645667, ["y"] = 0.576333 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213120, ["x"] = 0.645667, ["y"] = 0.576333 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.645667, ["y"] = 0.576333 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78669, 78670 }, ["questLines"] = { { ["id"] = 5529, ["name"] = "The Guiding Star", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5529, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5529, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215, ["db2QuestHubAreaPoiID"] = 7911 },
[82843] = { ["id"] = 82843, ["name"] = "Something Earthy", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 82843, 82844, 82847, 82848 }, ["series"] = { 84392 }, ["description"] = "Ah, another one of you lot, eh? Well, if you want to eat, you need to help. Pick me a fresh taro, will you?", ["objectivesText"] = "Harvest a nearby taro plant for the chef Progress: Have you brought the taro?", ["rewardGold"] = 219000, ["rewardXP"] = 7645, ["rewardItems"] = { 224396 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 224741, ["x"] = 0.699, ["y"] = 0.325 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 224741, ["x"] = 0.699, ["y"] = 0.325 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.699, ["y"] = 0.325 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 84392 }, ["questLines"] = { { ["id"] = 5645, ["name"] = "The Mysterious Chef", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[82844] = { ["id"] = 82844, ["name"] = "Something Not Ruined", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 82843, 82844, 82847, 82848 }, ["description"] = "Alright, I'll come with you. Show you how to do this properly. If I'm up, we might as well stock up on taro. Can't rely on adventurers to do delicate work, I suppose.", ["objectivesText"] = "Harvest 6 taro with the chef. Properly, this time. Progress: Is that all of them?", ["rewardGold"] = 292100, ["rewardXP"] = 10190, ["rewardItems"] = { 224397 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 224741, ["x"] = 0.699, ["y"] = 0.325 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 224741, ["x"] = 0.699, ["y"] = 0.325 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.699, ["y"] = 0.325 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 82843 }, ["questLines"] = { { ["id"] = 5645, ["name"] = "The Mysterious Chef", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
