[82847] = { ["id"] = 82847, ["name"] = "Enough Garlic", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 82843, 82844, 82847, 82848 }, ["description"] = "Normally, this would do. I'm not so picky. But you're a guest. So we'll need some garlic. I found some growing on a hill not far off. Shouldn't be there. But it is. Too bad hydras found it, too. You have weapons and such, right?", ["objectivesText"] = "Collect garlic for the chef. Progress: You think that's enough?", ["rewardGold"] = 292100, ["rewardXP"] = 10190, ["rewardItems"] = { 224395 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 224741, ["x"] = 0.699, ["y"] = 0.325 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 224741, ["x"] = 0.699, ["y"] = 0.325 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.699, ["y"] = 0.325 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 82844 }, ["questLines"] = { { ["id"] = 5645, ["name"] = "The Mysterious Chef", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
