[82965] = { ["id"] = 82965, ["name"] = "Light and Shadow", ["level"] = 68, ["requiredLevel"] = 68, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82965 }, ["description"] = "There are two herbs that I am missing. The first is Arathor's Spear , and the second, and far more rare, would be Orbinid . Now I know what you are thinking: these are both rare. Yes, to a point, but I am not asking for many and the pay is well worth it. What do you think? Can I trust you for the task?", ["objectivesText"] = "Gather 5 Arathor's Spear and 5 Orbinid for Akdan in Dornogal . Progress: Did you get both?", ["rewardGold"] = 309800, ["rewardXP"] = 9245, ["rewardItems"] = { 210802, 210808, 224817 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219101, ["x"] = 0.448, ["y"] = 0.695 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219101, ["x"] = 0.448, ["y"] = 0.695 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.695 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 34, ["db2LabelIDs"] = { 3866 } },
