[82969] = { ["id"] = 82969, ["name"] = "Stone Tracing", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 82773, 82774, 82785, 82786, 82814, 82969, 82990 }, ["series"] = { 82785, 82786, 82814, 82990 }, ["description"] = "Couldn't help overhearing. Not to brag, but goblins are specialists in the field of rampaging robots. If that golem's as unstable as Danagh says, it'll be leaking all sorts of energy. Take this, run a few scans, and you'll find it. Oh, and be careful. Animals tend to go a little cuckoo when you power this thing on. No charge--a murderous golem's bad for business. And I kinda feel bad making you work just to find a dead guy.", ["objectivesText"] = "Scan remnants of the golem to triangulate its location.", ["rewardGold"] = 292100, ["rewardXP"] = 9920, ["rewardItems"] = { 224451 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 216311, ["x"] = 0.568, ["y"] = 0.642 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 224618, ["x"] = 0.467, ["y"] = 0.62 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.642 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 82990 }, ["questLines"] = { { ["id"] = 5611, ["name"] = "Routine Maintenance", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[82970] = { ["id"] = 82970, ["name"] = "A Bloom and a Blossom", ["level"] = 68, ["requiredLevel"] = 68, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82970 }, ["description"] = "Hi, you there! I have a task for you. I require a handful of Mycobloom and some Blessing Blossoms . There is a nice payment for them if you are up for the task.", ["objectivesText"] = "Gather 10 Mycobloom and 10 Blessing Bloom for Akdan in Dornogal . Progress: I have your reward waiting for you if you got me the herbs.", ["rewardGold"] = 309800, ["rewardXP"] = 9245, ["rewardItems"] = { 210796, 210805, 224817 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219101, ["x"] = 0.448, ["y"] = 0.695 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219101, ["x"] = 0.448, ["y"] = 0.695 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.695 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 34, ["db2LabelIDs"] = { 3866 } },
