[82990] = { ["id"] = 82990, ["name"] = "Undoing the Damage", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 82773, 82774, 82785, 82786, 82814, 82969, 82990 }, ["series"] = { 82785, 82786, 82814, 82969 }, ["description"] = "Apologies. Arbauch was not here for repairs--he stole that golem. Arbauch and I worked alongside it for years in the darkest reaches of the Deeps. The work took its toll on the golem. It became erratic, dangerous even. We planned to decommission it, but when the time came, Arbauch couldn't bear it. He'd become attached. Before it could be destroyed, he took it and fled. It must be found, but the damage to this substation is catastrophic. With your help, I will attempt repairs.", ["objectivesText"] = "Defend Danagh while he repairs the substation.", ["rewardGold"] = 292100, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 224602, ["x"] = 0.5692, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 224602, ["x"] = 0.5692, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.5692, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 82785 }, ["questLines"] = { { ["id"] = 5611, ["name"] = "Routine Maintenance", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[82992] = { ["id"] = 82992, ["name"] = "Stormcharged Goods", ["level"] = 68, ["requiredLevel"] = 68, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82992 }, ["description"] = "Greetings my friend! I am looking for someone who is willing to run a quick errand. I am running out of goods and I have not heard from my leather supplier for quiet some time. If I can not supply skins and leathers, the leatherworker will not be able to produce apparels. I will reward you if you can bring me several Stormcharged leathers .", ["objectivesText"] = "Gather 20 Stormcharged Leathers and deliver them to Ginnad in Dornogal . Progress: Any good news? I still have not heard from my leather supplier.", ["rewardGold"] = 309800, ["rewardXP"] = 9245, ["rewardItems"] = { 212664, 224807 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219083, ["x"] = 0.544, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219083, ["x"] = 0.544, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 36, ["db2LabelIDs"] = { 3866 } },
[82993] = { ["id"] = 82993, ["name"] = "From Shadows", ["level"] = 68, ["requiredLevel"] = 68, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 82993 }, ["description"] = "Hello there! I have heard of fantastic materials that can be thread and put together from some... peculiar materials. If you are the type who enjoys travelling through the last sunny parts of Khaz-Algar, will you be kind enough to gather Kaheti Swarm Chitin and Sunless Carapace for me? I will reward you nicely if you can supply me with some samples.", ["objectivesText"] = "Gather 5 Kaheti Swarm Chitin and 5 Sunless Carapace , and deliver them to Ginnad in Dornogal . Progress: I feel a certain eagerness to get my hands on these materials.", ["rewardGold"] = 309800, ["rewardXP"] = 9245, ["rewardItems"] = { 54985, 54986, 58217, 66247, 212674, 218336, 219007, 224807, 253469 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219083, ["x"] = 0.544, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219083, ["x"] = 0.544, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 36, ["db2LabelIDs"] = { 3866 } },
