[83024] = { ["id"] = 83024, ["name"] = "The Stormrider's Bond", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83024 }, ["series"] = { 83025, 84908 }, ["description"] = "So, you think yourself worthy of a Stormrider's armor? We Stormriders were titan-made to fight and to ride stormrooks. Even so, we must prove our competence in battle before we gain clearance to wear Stormrider armor. I see no reason why you should not undergo the same challenges. Go. Show me you have the power of the storm within you.", ["objectivesText"] = "Collect 50 Storm Spirits by slaying powerful creatures of Khaz Algar. Progress: Come back only when you've proven yourself worthy.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 220737 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 225347, ["x"] = 0.352, ["y"] = 0.384 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 225347, ["x"] = 0.352, ["y"] = 0.384 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.352, ["y"] = 0.384 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[83025] = { ["id"] = 83025, ["name"] = "A Sacred Connection", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83025 }, ["series"] = { 83024, 84908 }, ["description"] = "I may have granted you clearance to wear our armor, but to focus the storm's power through it as the greatest Stormriders do... The greatest Stormriders in our order do not merely possess the power of the storm. They have mastered it. And this mastery is forged over many battles. It is time to prove yourself as one of our best.", ["objectivesText"] = "Collect 500 Storm Spirits by slaying powerful creatures of Khaz Algar. Progress: Your reward shall be properly equal to your efforts.", ["rewardGold"] = 1239200, ["rewardXP"] = 19030, ["rewardItems"] = { 220737 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 225347, ["x"] = 0.352, ["y"] = 0.384 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 225347, ["x"] = 0.352, ["y"] = 0.384 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.352, ["y"] = 0.384 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
