[83057] = { ["id"] = 83057, ["name"] = "Setting Boundaries", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 82340, 83057 }, ["description"] = "Vi'azl has undergone a level of torture that I was unaware of. We cannot help Vi with his fear until Vi is actually safe. Whenever possible, I advocate friendship, recovery, and reconciliation. I ask others to act with compassion and empathy. Everyone deserves a chance to recover. I dedicate my life to this. But hearing and seeing what is happening to Vi'azl... I think I've changed my mind. Enough is enough. We must act.", ["objectivesText"] = "Kill the Ascended nerubian who is torturing Vi'azl. Progress: Nobody deserves this torturous treatment.", ["rewardGold"] = 619600, ["rewardXP"] = 13245, ["rewardCurrencies"] = { { ["id"] = 3003, ["amount"] = 500 }, { ["id"] = 3056, ["amount"] = 250 }, { ["id"] = 3056, ["amount"] = 285 } }, ["starts"] = { { ["x"] = 0.55, ["y"] = 0.391, ["mapID"] = 2216, ["npcID"] = 223723 } }, ["ends"] = { { ["x"] = 0.55, ["y"] = 0.391, ["mapID"] = 2216, ["npcID"] = 223723 } }, ["coords"] = { ["mapID"] = 2216, ["x"] = 0.55, ["y"] = 0.391 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14753 } }, ["questGiverID"] = 223723, ["questTurnInID"] = 223723, ["questType"] = "standard", ["sourceQuests"] = { 82340 }, ["questLines"] = { { ["id"] = 5612, ["name"] = "Mr. Sunflower's Therapy", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2216 },
