[83081] = { ["id"] = 83081, ["name"] = "Not Enough Minerals", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78465, 78467, 79213, 79716, 83081, 83082, 83083, 83084, 83087 }, ["description"] = "I did nae think the Opalcreg would be under attack! I'm sure Brinthe did nae either. Peacekeeper Hektare will nae let me fight, but maybe she will let you. I'll stay here an' tend to this earthen. I know a trick or two after bein' in Dornogal. Oh, but... Brinthe really needed those opals...", ["objectivesText"] = "Collect 6 Earthen Fire Opals from the Opalcreg in the Isle of Dorn . Progress: I'm sure I can make a poultice for this earthen. Oh, 'tis a shame I cannae get any opals.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 225451, ["x"] = 0.448, ["y"] = 0.644 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 225451, ["x"] = 0.448, ["y"] = 0.644 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.644 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78536 }, ["questLines"] = { { ["id"] = 5634, ["name"] = "Hidden Edicts", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[83082] = { ["id"] = 83082, ["name"] = "The Opalfront", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78465, 78467, 79213, 79716, 83081, 83082, 83083, 83084, 83087 }, ["description"] = "I'm a city guard, not a soldier! But these people need our help! There are too many nerubians for us to clear out. We can only keep this chokepoint and hope the miners make their way to us. That one was too small. But you look like a fighter. Help us!", ["objectivesText"] = "Kill nerubian forces at the Opalcreg in the Isle of Dorn . Progress: We will do what we can to help the miners escape.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 225454, ["x"] = 0.448, ["y"] = 0.642 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 225454, ["x"] = 0.448, ["y"] = 0.642 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.642 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 78536 }, ["questLines"] = { { ["id"] = 5634, ["name"] = "Hidden Edicts", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[83083] = { ["id"] = 83083, ["name"] = "A Place Forgotten", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78465, 78467, 79213, 79716, 83081, 83082, 83083, 83084, 83087 }, ["description"] = "There is... a place behind Dornogal that I cannot go. And I am not the only one. Something--a force, most likely titan in origin--keeps the earthen from investigating a small portion of the island behind the city. This, of course, fires my curiosity. But for thousands of years I have dutifully kept away. It seemed the titans' will. The site emits a faint signal like the one from this device. Perhaps it is \"the key\" in a literal sense to what lies there. We will see.", ["objectivesText"] = "Meet with Speaker Brinthe and Dagran behind Dornogal in the Isle of Dorn .", ["rewardGold"] = 30900, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 225478, ["x"] = 0.616, ["y"] = 0.702 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 226841, ["x"] = 0.448, ["y"] = 0.205 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.702 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 79213 }, ["questLines"] = { { ["id"] = 5634, ["name"] = "Hidden Edicts", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[83084] = { ["id"] = 83084, ["name"] = "The Old Orders", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78465, 78467, 79213, 79716, 83081, 83082, 83083, 83084, 83087 }, ["description"] = "Long ago, there were once plans to build a tunnel through the mountain into Dornogal. Before excavation could begin, the surrounding area was suddenly abandoned. There is no record of what happened. Only a... deterrence--the field--that keeps earthen away from this region. Every part of my cognitive matrix is pressing for me to leave. But we must persist. The device's signal indicates something lies within the nearby tower.", ["objectivesText"] = "Investigate the abandoned tower behind Dornogal. Progress: I'm not sure what's afflicting Brinthe, but it's clear she's in pain. I offered to escort her back to the city but she refused. I will stay with her an' make sure she does nae take a turn for the worse and try an' figure this device out more too.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 225887, 226015 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 226841, ["x"] = 0.448, ["y"] = 0.205 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 225472, ["x"] = 0.448, ["y"] = 0.206 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.205 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 83083 }, ["questLines"] = { { ["id"] = 5634, ["name"] = "Hidden Edicts", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[83085] = { ["id"] = 83085, ["name"] = "DEPRECATED", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 83085 }, ["rewardGold"] = 134000, ["rewardXP"] = 200, ["rewardItems"] = { 94219, 128823, 128868, 209353 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14717 } }, ["questType"] = "standard" },
[83087] = { ["id"] = 83087, ["name"] = "The Old Guard", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78465, 78467, 79213, 79716, 83081, 83082, 83083, 83084, 83087 }, ["description"] = "Dornic... Galan... I've heard those names at the Proscenium! But who was speakin'? They were nae happy with Galan. All those earthen bodies... Repurposed... like reprogrammed? Tae protect what? Let's chase the other signal. Looks like it leads up ahead intae the hills. I'm goin' to stay here with Brinthe an' investigate this tower further. You take the device.", ["objectivesText"] = "Follow the signal and witness a second memory Progress: I'll stay here with Brinthe. I dunnae want anythin' to happen tae her.", ["rewardGold"] = 619600, ["rewardXP"] = 11895, ["rewardItems"] = { 225887, 228369 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 180 }, { ["id"] = 2897, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 225472, ["x"] = 0.448, ["y"] = 0.206 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 225472, ["x"] = 0.448, ["y"] = 0.206 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.206 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 83084 }, ["questLines"] = { { ["id"] = 5634, ["name"] = "Hidden Edicts", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[83088] = { ["id"] = 83088, ["name"] = "Caustic Collectables", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83088, 83089, 83091 }, ["description"] = "Boxenkle is my boss--and my mentor. Best slimediver there ever was! Until now... It's not him--slimediving isn't what it used to be! The slimes have gotten more toxic over time. I think it's gotten so bad that we all should be wearin' eye protection--not just me. But ol' Enkle's a traditionalist. It'll take more than a few red eyes to convince him. That's where you come in. If you can get residue samples from the really nasty slimes, maybe I can make a compelling case for ol' Enkle!", ["objectivesText"] = "Collect 6 Stinging Residue from Acidic Salvage in The Vatworks. Progress: Have you found enough residue from the oozing salvage? Make sure to get the really nasty stuff. You know, the stuff that sticks to you but also melts your skin?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 226223 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225481, ["x"] = 0.405, ["y"] = 0.871 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225481, ["x"] = 0.405, ["y"] = 0.871 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.405, ["y"] = 0.871 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83130 }, ["questLines"] = { { ["id"] = 5659, ["name"] = "Hazards of Slimediving", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83089] = { ["id"] = 83089, ["name"] = "Giving Goblins Goggles", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83088, 83089, 83091 }, ["description"] = "My mentor Enkle may be the loudest voice around here, but he's not the only one who needs help. Our whole crew only listens to him! Which means no one's wearing proper protective equipment. Take these goggles and convince everyone to take 'em on a trial run. Maybe if they all start changing their minds, Enkle will listen.", ["objectivesText"] = "Talk to 5 Slimedivers in The Vatworks. Progress: Everyone's working along this river here. You can't miss them! Unless they haven't found the river. But that only happens half the time, so I'm sure it's fine.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225481, ["x"] = 0.405, ["y"] = 0.871 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225481, ["x"] = 0.405, ["y"] = 0.871 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.405, ["y"] = 0.871 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83130 }, ["questLines"] = { { ["id"] = 5659, ["name"] = "Hazards of Slimediving", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83091] = { ["id"] = 83091, ["name"] = "Shield Your Eyes", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83088, 83089, 83091 }, ["description"] = "Causticaria ? Is he crazy? No one has ever been able to process that monster! We have to stop Enkle before he gets himself hurt! Causticaria lurks down this canal. Grab your goggles and follow me!", ["objectivesText"] = "Defeat Causticaria in The Vatworks. Progress: Has Causticaria gotten even bigger? The stench is burning my nose hairs from here!", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 232772, 232777, 232780, 232785 }, ["rewardCurrencies"] = { { ["id"] = 3118, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225481, ["x"] = 0.405, ["y"] = 0.871 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 228095, ["x"] = 0.386, ["y"] = 0.846667 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.405, ["y"] = 0.871 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83088, 83089 }, ["questLines"] = { { ["id"] = 5659, ["name"] = "Hazards of Slimediving", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83092] = { ["id"] = 83092, ["name"] = "An Igneous End", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83092, 83152, 83153, 83160 }, ["description"] = "When the magma transport pipe failed, our workers rushed down to begin repairs. The elementals caught us unawares, rising up and attacking with great gouts of lava. Fortunately, we earthen are made of stern stuff and a little magma is hardly going to be the end of us. Unfortunately, the cooling magma has hardened into stone shells, entombing our repair crews where they stood. Smash their stony prisons and free my workers!", ["objectivesText"] = "Free Entombed Earthen from their stone shells near Hallowfall Gate. Progress: Don't worry about hurting them, just get them free.", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 225582, ["x"] = 0.389, ["y"] = 0.214 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 225582, ["x"] = 0.389, ["y"] = 0.214 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.389, ["y"] = 0.214 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79573, 80434 }, ["questLines"] = { { ["id"] = 5654, ["name"] = "Magma-nificence", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[83096] = { ["id"] = 83096, ["name"] = "Welcome to Undermine", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83096, 83109, 83163, 83167, 83168, 83169, 83170, 83171, 83172, 83173, 83174, 83175, 83176, 85941, 86297 }, ["description"] = "There ya are! I'm Grimla. Welcome to Undermine . If you wanna get up to speed with the current situation, you've come to the right goblin. Pamsy vouched for you, that's good enough for me. I've got a coupon you can use at the Incontinental Hotel. We'll start there. Let's take a ride in \" Gramps ,\" my hot rod! Hop in when you're ready.", ["objectivesText"] = "Go to the Incontinental Hotel with Grimla and learn more about Undermine . Progress: Did you hear anything good while you were gettin' yourself settled?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3118, ["amount"] = 2500 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225500, ["x"] = 0.369, ["y"] = 0.523 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225500, ["x"] = 0.369, ["y"] = 0.523 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.369, ["y"] = 0.523 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83151 }, ["questLines"] = { { ["id"] = 5661, ["name"] = "Undermine Awaits", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5661, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83097] = { ["id"] = 83097, ["name"] = "Cinder and Storm", ["level"] = 68, ["requiredLevel"] = 68, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83097 }, ["description"] = "The wild creatures here have stunning properties. I wonder what might happen if I combine them? Be on the lookout for Bottled Storm and Burning Cinderbee Setae . I'll reward you generously if you can bring me some samples. Oh, and if you gather them yourself, mind that you don't get burned. Or zapped. Or both.", ["objectivesText"] = "Gather 5 Bottled Storm and 5 Burning Cinderbee Setae , and deliver them to Ginnad in Dornogal . Progress: Who knows what could happen if we combine these materials!", ["rewardGold"] = 309800, ["rewardXP"] = 9245, ["rewardItems"] = { 218338, 218339, 224807 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219083, ["x"] = 0.544, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219083, ["x"] = 0.544, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 36, ["db2LabelIDs"] = { 3866 } },
[83098] = { ["id"] = 83098, ["name"] = "Snap and Crackle", ["level"] = 68, ["requiredLevel"] = 68, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83098 }, ["description"] = "Do you have a moment? I'm looking for some materials with an edge. Something sharp and with a bit of sizzle. If you can find me Honed Bone Shards and Thunderous Hide , I'd be more than happy to compensate you.", ["objectivesText"] = "Gather 5 Honed Bone Shards and 2 Thunderous Hide , and deliver them to Ginnad in Dornogal . Progress: Together, these materials will make a real statement.", ["rewardGold"] = 309800, ["rewardXP"] = 9245, ["rewardItems"] = { 212670, 218337, 224807 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219083, ["x"] = 0.544, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219083, ["x"] = 0.544, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 36, ["db2LabelIDs"] = { 3866 } },
[83099] = { ["id"] = 83099, ["name"] = "Mergers and Acquisitions", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15103, ["mapID"] = 2248, ["storyline"] = { 83099 }, ["description"] = "When the nerubians launched their attack on my meadery, they left it a burnt-out husk. Adelgonn promised to rebuild it, but I got impatient and accepted the Venture Co.'s offer to help with its \"restructuring.\" But now, it's clear they had their own agenda. Blasted goblins have taken over, and they're driving the place into the ground. They've ramped up production to unsafe levels, pushing the cinderbees and our equipment to their limits. Please help fix this, <name>.", ["objectivesText"] = "Defeat Goldie Baronbottom and help Wenbrandt reclaim the Cinderbrew Meadery . Progress: Thinking about those goblins in my meadery... Oh, it makes my head feel molten. And that makes me think of my cinderbrew!", ["rewardGold"] = 1239200, ["rewardXP"] = 23530, ["rewardItems"] = { 221054, 221060, 221198 }, ["rewardChoices"] = { 221054, 221060, 221198 }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 226409, ["x"] = 0.756, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 226409, ["x"] = 0.756, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.756, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 15103 } }, ["questType"] = "dungeon" },
[83100] = { ["id"] = 83100, ["name"] = "Cracking the Shell", ["level"] = 68, ["requiredLevel"] = 68, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83100 }, ["description"] = "Welcome! You wouldn't believe the amount of materials we go through up here, and not just the rare stuff! We could always do with more Gloom Chitin . If you find some, bring it to me. I'll see to it you get paid.", ["objectivesText"] = "Gather 20 Gloom Chitin and deliver it to Ginnad in Dornogal . Progress: Manage to lay your hands on some yet?", ["rewardGold"] = 309800, ["rewardXP"] = 9245, ["rewardItems"] = { 212667, 224807 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219083, ["x"] = 0.544, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219083, ["x"] = 0.544, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 36, ["db2LabelIDs"] = { 3866 } },
[83101] = { ["id"] = 83101, ["name"] = "Reaching for Resources", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80208, 80323, 81656, 81691, 81750, 81767, 82238, 82244, 82256, 82518, 82519, 82523, 82552, 82580, 83028, 83048, 83079, 83080, 83101, 83229, 83537, 83538, 83715, 83930, 84429 }, ["objectivesText"] = "Climbing Gear acquired Find a handhold on the cliff Ancient Celestite collected", ["rewardXP"] = 11765, ["starts"] = { { ["x"] = 0.51, ["y"] = 0.508, ["mapID"] = 2214 } }, ["ends"] = { { ["x"] = 0.51, ["y"] = 0.508, ["mapID"] = 2214 } }, ["coords"] = { ["mapID"] = 2214, ["x"] = 0.51, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14795 } }, ["questType"] = "world", ["questLines"] = { { ["id"] = 5588, ["name"] = "Ringing Deeps - World Quests / Repeatable", ["orderIndex"] = 20, ["flags"] = 0 } }, ["db2Objectives"] = { { ["text"] = "Climbing Gear acquired", ["amount"] = 1, ["type"] = 0, ["objectID"] = 225504, ["orderIndex"] = 0 }, { ["text"] = "Find a handhold on the cliff", ["amount"] = 1, ["type"] = 0, ["objectID"] = 225506, ["orderIndex"] = 1 }, { ["text"] = "Ancient Celestite collected", ["amount"] = 7, ["type"] = 0, ["objectID"] = 225516, ["orderIndex"] = 2 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[83102] = { ["id"] = 83102, ["name"] = "Bismuth is Business", ["level"] = 68, ["requiredLevel"] = 68, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83102 }, ["description"] = "Do you know the backbone of a good mining operation? It's not the rare, flashy ores. It's good, common Bismuth . And we don't have nearly enough! Wherever you go, keep an eye out for Bismuth . Bring me as much as you can. Compensation is assured.", ["objectivesText"] = "Gather 20 Bismuth and deliver it to Tarib in Dornogal . Progress: Bismuth is business, and business is booming!", ["rewardGold"] = 309800, ["rewardXP"] = 9245, ["rewardItems"] = { 210930, 224818 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219097, ["x"] = 0.525, ["y"] = 0.525 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219097, ["x"] = 0.525, ["y"] = 0.525 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.525 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 45, ["db2LabelIDs"] = { 3866 } },
[83103] = { ["id"] = 83103, ["name"] = "Acquiring Aqirite", ["level"] = 68, ["requiredLevel"] = 68, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83103 }, ["description"] = "You there! Have you heard of Aqirite ? Valuable, versatile, very often surrounded by nerubians. I need that ore, and I don't care how you get it. If a nerubian does try to stop you, give them a whack for me.", ["objectivesText"] = "Gather 10 Aqirite and deliver it to Tarib in Dornogal . Progress: Well, have you got it yet?", ["rewardGold"] = 309800, ["rewardXP"] = 9245, ["rewardItems"] = { 210933, 212308, 224818 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219097, ["x"] = 0.525, ["y"] = 0.525 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219097, ["x"] = 0.525, ["y"] = 0.525 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.525 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 45, ["db2LabelIDs"] = { 3866 } },
[83104] = { ["id"] = 83104, ["name"] = "Identifying Ironclaw", ["level"] = 68, ["requiredLevel"] = 68, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83104 }, ["description"] = "I sent a team to mine some Ironclaw Ore , they said they didn't see any. Can you believe that? It's a blasted great claw coming out of the ground! I'm not sending them again. I trust you'll know Ironclaw Ore when you see it. Bring it to me, and you'll be rewarded.", ["objectivesText"] = "Gather 10 Ironclaw Ore and deliver it to Tarib in Dornogal . Progress: Trust me, you can't miss it.", ["rewardGold"] = 309800, ["rewardXP"] = 9245, ["rewardItems"] = { 210936, 224818 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219097, ["x"] = 0.525, ["y"] = 0.525 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219097, ["x"] = 0.525, ["y"] = 0.525 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.525 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 45, ["db2LabelIDs"] = { 3866 } },
[83105] = { ["id"] = 83105, ["name"] = "Rush-order Requisition", ["level"] = 68, ["requiredLevel"] = 68, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83105 }, ["description"] = "Good to see you, I've got work. The blacksmiths just sent a last-minute requisition for rare ores. Gravel-munching hammer-heavers, would it kill them to plan ahead? Well, I'm sure you can handle it. Looks like you'll need to track down Aqirite and Ironclaw Ore .", ["objectivesText"] = "Gather 5 Aqirite and 5 Ironclaw Ore , and deliver them to Tarib in Dornogal . Progress: Do you have them? The smiths have been chewing my ear off.", ["rewardGold"] = 309800, ["rewardXP"] = 9245, ["rewardItems"] = { 210933, 210936, 224818 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219097, ["x"] = 0.525, ["y"] = 0.525 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219097, ["x"] = 0.525, ["y"] = 0.525 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.525 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 45, ["db2LabelIDs"] = { 3866 } },
[83106] = { ["id"] = 83106, ["name"] = "Null Pebble Excavation", ["level"] = 68, ["requiredLevel"] = 68, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83106 }, ["description"] = "Ever seen a Null Stone ? Well, you will. They're rare, but we know how to put them to good use. Don't worry, I only need a couple. While you're at it, pick up any Bismuth you find. You can never have enough Bismuth .", ["objectivesText"] = "Gather 10 Bismuth and 2 Null Stone , and deliver them to Tarib in Dornogal . Progress: Any luck with those Null Stones ?", ["rewardGold"] = 309800, ["rewardXP"] = 9245, ["rewardItems"] = { 210930, 210939, 224818 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219097, ["x"] = 0.525, ["y"] = 0.525 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219097, ["x"] = 0.525, ["y"] = 0.525 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.525 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 45, ["db2LabelIDs"] = { 3866 } },
[83108] = { ["id"] = 83108, ["name"] = "Daily Diagnostics", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83108 }, ["description"] = "It is my duty and honor to take diagnostic readings every day. I determine the output and efficiency of the Stonevault's great machines. The burden is mine. Describing complication: now that skardyn have overrun the Stonevault, I cannot reach my machines! Solution proposed: I have heard that you are a hero of great renown. Please go in and gather today's readings for me. Timing will be critical in the event anything goes wrong. Awaiting confirmation.", ["objectivesText"] = "Take diagnostic readings of 4 machines within the Stonevault. Progress: There are numerous consoles that assist with the running of the great machines within the Stonevault. Work does not cease, even in the face of this madness. Please, get me those readings as soon as you can!", ["rewardGold"] = 1239200, ["rewardXP"] = 19840, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 225533, ["x"] = 0.451, ["y"] = 0.316 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 225533, ["x"] = 0.451, ["y"] = 0.316 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.451, ["y"] = 0.316 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "dungeon", ["sourceQuests"] = { 79354 }, ["db2QuestHubAreaPoiID"] = 7911 },
[83109] = { ["id"] = 83109, ["name"] = "The Grimla Express", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83096, 83109, 83163, 83167, 83168, 83169, 83170, 83171, 83172, 83173, 83174, 83175, 83176, 85941, 86297 }, ["description"] = "Next stop, Tailgate Park. Bilgewater Cartel used to be in charge there, but Gallywix had other plans. Now the Darkfuse act like they own the place and the Bilgewater... Well, they do the best they can. I'm not sure who runs it now, if anyone does.", ["objectivesText"] = "Head to Tailgate Park in Grimla's hot rod.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225500, ["x"] = 0.369, ["y"] = 0.523 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 229246, ["x"] = 0.452, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.369, ["y"] = 0.523 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83096 }, ["questLines"] = { { ["id"] = 5661, ["name"] = "Undermine Awaits", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5661, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83110] = { ["id"] = 83110, ["name"] = "Deliver Equipment", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 83110 }, ["description"] = "Deliver safety equipment to Steamwheedle goblins to allow them to perform black blood experiments more safely. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(83110)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(83110))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[83113] = { ["id"] = 83113, ["name"] = "Recover Tools", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 83113 }, ["description"] = "Kill black blood slimes and recover tools absorbed by the slimes. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(83113)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(83113))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[83114] = { ["id"] = 83114, ["name"] = "Red Tape", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83114, 83115, 83116, 83117, 83118, 83119, 83120, 83121, 83122, 83123, 83124, 83125, 83933, 84121, 84122 }, ["description"] = "First it was just Black Blood, now ethereals? I don't know how all this squares, but we need help if we wanna find out. Orweyna left to get Alleria a while ago. We should head over to Slam Central Station to see if they've made it down here yet.", ["objectivesText"] = "Find Alleria at Slam Central Station. Progress: We shoulda known. These guys see an outsider unescorted and try to pull a fast one. See if you can change their minds.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 229236, ["x"] = 0.424667, ["y"] = 0.514667 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225570, ["x"] = 0.18, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.424667, ["y"] = 0.514667 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83176 }, ["questLines"] = { { ["id"] = 5614, ["name"] = "Uncovering the Truth", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5614, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346, ["db2QuestHubAreaPoiID"] = 8189 },
[83115] = { ["id"] = 83115, ["name"] = "In the Mix", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83114, 83115, 83116, 83117, 83118, 83119, 83120, 83121, 83122, 83123, 83124, 83125, 83933, 84121, 84122 }, ["description"] = "I don't like thinkin' that Noggenfogger's part of this, but the only way we'll know is if we go and talk to him. Steamwheedle's headquarters is probably a good place to start lookin' for him. We'll give him a chance to explain himself. If it's a misunderstanding, or he's just gotten himself into trouble, I need to know.", ["objectivesText"] = "Speak to Marin Noggenfogger at the Vatworks. Progress: You see how many Darkfuse they've got here?", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 133814, 204985, 205188 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225570, ["x"] = 0.18, ["y"] = 0.508 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225625, ["x"] = 0.275, ["y"] = 0.71 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.18, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83114 }, ["questLines"] = { { ["id"] = 5614, ["name"] = "Uncovering the Truth", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5614, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83116] = { ["id"] = 83116, ["name"] = "Potion Commotion", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83114, 83115, 83116, 83117, 83118, 83119, 83120, 83121, 83122, 83123, 83124, 83125, 83933, 84121, 84122 }, ["description"] = "It really is great to see you and Gazlowe! I was just thinkin' about how much I wanted to see you both on my birthday. A day when I'm under no forms of duress or coercion whatsoever! N-None at all. <Cautiously, he glances at the Darkfuse guards, then whispers to you.> I'll tell you whatever I can if you get rid of them. <He nods subtly towards his alchemy station.>", ["objectivesText"] = "Collect some Semi-Deluxe Noggenfogger Elixirs , then use them to distract 8 Stationed Labguards. Progress: I'll keep an eye on Noggenfogger. You get it done.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 226157 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225624, ["x"] = 0.275, ["y"] = 0.709 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225625, ["x"] = 0.275, ["y"] = 0.71 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.275, ["y"] = 0.709 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83115 }, ["questLines"] = { { ["id"] = 5614, ["name"] = "Uncovering the Truth", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5614, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83117] = { ["id"] = 83117, ["name"] = "Chasing a Lead", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83114, 83115, 83116, 83117, 83118, 83119, 83120, 83121, 83122, 83123, 83124, 83125, 83933, 84121, 84122 }, ["description"] = "Venture doesn't exactly have a history of being an upstanding cartel. Their loyalties can be bought cheap, and they don't got qualms about means justifyin' ends. We knew they was working with Gallywix, we just didn't know how deep they were in with him. Let's go check out those kaja'mite supply lines. No time to lose.", ["objectivesText"] = "Meet Gazlowe outside the Heaps.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225625, ["x"] = 0.275, ["y"] = 0.71 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225635, ["x"] = 0.46, ["y"] = 0.786 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.275, ["y"] = 0.71 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83116 }, ["questLines"] = { { ["id"] = 5614, ["name"] = "Uncovering the Truth", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5614, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83118] = { ["id"] = 83118, ["name"] = "Check the Schedule", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83114, 83115, 83116, 83117, 83118, 83119, 83120, 83121, 83122, 83123, 83124, 83125, 83933, 84121, 84122 }, ["description"] = "If there's one thing Venture does keep in order, it's their paperwork. They're real particular with dividing their workforce and keepin' everything on schedule. They're efficient, I'll give 'em that. Up ahead is one of their scrapyards. They should have schedules posted around the place for Venture employees to record their hours worked and see what they got comin' up. Grab as many as you can find. We'll check out Venture's headquarters in the meantime.", ["objectivesText"] = "Gather 3 Employee Schedules . Progress: They should have schedules posted all over the place. Hopefully this isn't a wild flamingo chase.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 226380 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225635, ["x"] = 0.46, ["y"] = 0.786 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225639, ["x"] = 0.532, ["y"] = 0.71 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.786 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83117 }, ["questLines"] = { { ["id"] = 5614, ["name"] = "Uncovering the Truth", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5614, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83119] = { ["id"] = 83119, ["name"] = "It's Worth a Shot", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83114, 83115, 83116, 83117, 83118, 83119, 83120, 83121, 83122, 83123, 83124, 83125, 83933, 84121, 84122 }, ["description"] = "Venture Co. has a pretty bad track record, but not everyone workin' for the cartel is bad news. Some of us are tryin' to make ends meet. Maybe we can talk sense into some of 'em. Less Venture workers means less people doin' Gallywix's dirty work. Venture Co. employs a lot of non-goblins, so no one will question you bein' around as long as you've got a uniform on. I've got a spare that will probably, mostly, sorta fit you. See if you can get 'em to quit. If they start a fight, do what you gotta do.", ["objectivesText"] = "Attempt to convince 10 Underpaid Workers to quit Venture Co.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 226358 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225637, ["x"] = 0.46, ["y"] = 0.786 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225638, ["x"] = 0.535, ["y"] = 0.71 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.786 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83117 }, ["questLines"] = { { ["id"] = 5614, ["name"] = "Uncovering the Truth", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5614, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83120] = { ["id"] = 83120, ["name"] = "Stealing the Keys", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83114, 83115, 83116, 83117, 83118, 83119, 83120, 83121, 83122, 83123, 83124, 83125, 83933, 84121, 84122 }, ["description"] = "If you gotta get to a confidential work site like the Kaja'Coast, you gotta check out a punch card from Krome's office up here. Lead Foreman Krome is one of the big bosses who organizes how Venture's workforce gets split up. Should be easy enough for Renzik to slip in and grab the punch card, but you'll need to take care of Krome and his guard hyena. If we're gettin' to the Kaja'Coast, let's do it without becomin' chew toys first, yeah?", ["objectivesText"] = "Slay Lead Foreman Krome . Progress: You clear the way for Renzik to get the punch card yet?", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 226391, 232355, 232400, 232402, 232404 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225638, ["x"] = 0.535, ["y"] = 0.71 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225639, ["x"] = 0.532, ["y"] = 0.71 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.71 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83118, 83119 }, ["questLines"] = { { ["id"] = 5614, ["name"] = "Uncovering the Truth", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5614, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83121] = { ["id"] = 83121, ["name"] = "Asset Management", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 862, ["storyline"] = { 83114, 83115, 83116, 83117, 83118, 83119, 83120, 83121, 83122, 83123, 83124, 83125, 83933, 84121, 84122 }, ["description"] = "I took a quick look inside that mine up ahead while you were gone. Looks like they've got Venture Co. mining out all the kaja'mite and bringin' it down to the beach. It's gettin' packaged up down there, but I couldn't tell where it was goin' afterward. We need to cut off the supply at the origin. Deal with the supervisors in the mine, and I'm willin' to bet their workers will have enough sense to run afterward.", ["objectivesText"] = "Slay 6 Venture Supervisors in the Lucky Break Mines. Progress: It won't stop the kaja'mite supply for good, but at least it'll slow them down.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 228132, ["x"] = 0.22, ["y"] = 0.576 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 228132, ["x"] = 0.22, ["y"] = 0.576 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.22, ["y"] = 0.576 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["sourceQuests"] = { 84121, 84122 }, ["questLines"] = { { ["id"] = 5614, ["name"] = "Uncovering the Truth", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5614, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862 },
[83122] = { ["id"] = 83122, ["name"] = "Crashing the Market", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 862, ["storyline"] = { 83114, 83115, 83116, 83117, 83118, 83119, 83120, 83121, 83122, 83123, 83124, 83125, 83933, 84121, 84122 }, ["description"] = "When I left the Bilgewater Cartel in charge of the kaja'mite mining in Zuldazar, it was clean and safe. Well, cleaner and safer. We made a lot of deals with the Zandalari to secure that. So not only is Gallywix steppin' on our territory, but he's threatenin' the respect and trust we earned by letting Venture make a mess of this operation. Blow up the kaja'mite stockpiles you find in that mine. I don't want any dishonest kaja'mite goin' anywhere, no matter who's buyin' or sellin'.", ["objectivesText"] = "Destroy 5 Kaja'mite Stockpiles in the Lucky Break Mines. Progress: We need to keep that kaja'mite out of circulation.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 225648, ["x"] = 0.22, ["y"] = 0.576 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 225648, ["x"] = 0.22, ["y"] = 0.576 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.22, ["y"] = 0.576 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["sourceQuests"] = { 84121, 84122 }, ["questLines"] = { { ["id"] = 5614, ["name"] = "Uncovering the Truth", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5614, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862 },
[83123] = { ["id"] = 83123, ["name"] = "A Miner Mistake", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 862, ["storyline"] = { 83114, 83115, 83116, 83117, 83118, 83119, 83120, 83121, 83122, 83123, 83124, 83125, 83933, 84121, 84122 }, ["description"] = "<On the corpse of the Venture Co. employee, you find a crumpled piece of paper stuffed into an envelope. It appears to be a paystub from a kaja'mite depot in the Venture Co. area of Undermine . Below the full address of the employer, there is a header stamped in red ink.> GALLYWIX'S SECRET KAJA'MITE WAREHOUSE - INTERNAL ONLY DO NOT ACTUALLY PRINT THAT <A note from Gallywix is poorly taped to the back of the paystub.>", ["objectivesText"] = "Read the Crumpled Paystub , then bring it back to Gazlowe. Progress: What do you got there?", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 232464 }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 225648, ["x"] = 0.22, ["y"] = 0.576 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.22, ["y"] = 0.576 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["sourceQuests"] = { 84121, 84122 }, ["questLines"] = { { ["id"] = 5614, ["name"] = "Uncovering the Truth", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5614, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["startItems"] = { 226854 } },
[83124] = { ["id"] = 83124, ["name"] = "B.I.R.D. Watching", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 862, ["storyline"] = { 83114, 83115, 83116, 83117, 83118, 83119, 83120, 83121, 83122, 83123, 83124, 83125, 83933, 84121, 84122 }, ["description"] = "I took those parts you collected and hotwired the components into some new machinery, then stuffed it back into the bot. Now it can be piloted usin' this remote control. The remote also lets us see and hear anything the bot does. I don't think we're gonna learn what we need to just by killin'. We're gonna need to beat Gallywix at his own game and spy on his workers. You wanna do us the honors, <name>? I'll talk you through it.", ["objectivesText"] = "Control the Hotwired B.I.R.D. to spy on Darkfuse activities on the Kaja'Coast. Progress: They'll never suspect nothin'.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 225648, ["x"] = 0.22, ["y"] = 0.576 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 225648, ["x"] = 0.22, ["y"] = 0.576 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.22, ["y"] = 0.576 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["sourceQuests"] = { 83121, 83122, 83123 }, ["questLines"] = { { ["id"] = 5614, ["name"] = "Uncovering the Truth", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5614, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862 },
[83125] = { ["id"] = 83125, ["name"] = "Price Hike", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 862, ["storyline"] = { 83114, 83115, 83116, 83117, 83118, 83119, 83120, 83121, 83122, 83123, 83124, 83125, 83933, 84121, 84122 }, ["description"] = "So Noggenfogger wasn't lyin'. Darkfuse strongarmed Steamwheedle into figurin' out how to make kaja'mite contain Black Blood. Looks like that's how they've been gettin' it into weapons without blowin' themselves up--or worse. These stakes are higher than I thought, and I get the feeling this goes even deeper. I need to get Noggenfogger somewhere safe. You and Renzik take out that overseer, then meet us back at Steamwheedle.", ["objectivesText"] = "Slay Overseer Dritz , then meet up with Gazlowe in Undermine .", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 232883 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 225648, ["x"] = 0.22, ["y"] = 0.576 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225667, ["x"] = 0.292, ["y"] = 0.695 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.22, ["y"] = 0.576 }, ["mapCandidates"] = { ["npc"] = { 862, 2346 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["sourceQuests"] = { 83124 }, ["questLines"] = { { ["id"] = 5614, ["name"] = "Uncovering the Truth", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5614, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83126] = { ["id"] = 83126, ["name"] = "Ethereal Invasion", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83126, 83127, 83128, 83129, 83130, 85449, 85450 }, ["description"] = "Just moments ago, these ethereals appeared out of nowhere. They attacked Noggenfogger and attempted to haul him off. I made short work of the first attackers, but they keep coming. Now they're searching every building and killing anyone who stands in their way. I don't know what they're looking for, but we can't allow them to continue this slaughter. Let's teach them a lesson.", ["objectivesText"] = "Kill 12 ethereals in the Vatworks. Progress: We cannot let this chaos continue.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225669, ["x"] = 0.294667, ["y"] = 0.694 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225669, ["x"] = 0.294667, ["y"] = 0.694 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.294667, ["y"] = 0.694 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questTurnInID"] = 225669, ["questType"] = "standard", ["sourceQuests"] = { 83125 }, ["questLines"] = { { ["id"] = 5615, ["name"] = "Breaking the Shackles", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 6009, ["name"] = "Catch Up: War Within: Wrapper 4", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5615, ["questLineOrder"] = 3 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6009, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83127] = { ["id"] = 83127, ["name"] = "Racing the Clock", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83126, 83127, 83128, 83129, 83130, 85449, 85450 }, ["description"] = "We were out of time before, but now we're REALLY out of time. The ethereals are gonna beat us to the warehouse, but we might still be able to beat them to the Dark Heart. C'mon!", ["objectivesText"] = "Meet Gazlowe outside Gallywix's secret warehouse in the Heaps.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 229261, ["x"] = 0.27, ["y"] = 0.718 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225719, ["x"] = 0.555, ["y"] = 0.635 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.27, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 85450 }, ["questLines"] = { { ["id"] = 5615, ["name"] = "Breaking the Shackles", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 6009, ["name"] = "Catch Up: War Within: Wrapper 4", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5615, ["questLineOrder"] = 3 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6009, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83128] = { ["id"] = 83128, ["name"] = "Get Our People Out", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83126, 83127, 83128, 83129, 83130, 85449, 85450 }, ["description"] = "While Alleria looks for the Dark Heart, we need to look for the hostages. Here's hoping they're still safe. They left some ambushers behind, but we got the best of SI:7 on our side. You think you see one of them hidin', point them out to Renzik. He'll toss a smoke bomb. That'll flush 'em out and stun 'em, so we can turn the tables.", ["objectivesText"] = "Save any hostages Gallywix is keeping in the warehouse and slay 10 Ethereal Heartseekers .", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 232354, 232401, 232403, 232405 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225719, ["x"] = 0.555, ["y"] = 0.635 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225730, ["x"] = 0.585, ["y"] = 0.595 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.635 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83127 }, ["questLines"] = { { ["id"] = 5615, ["name"] = "Breaking the Shackles", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 6009, ["name"] = "Catch Up: War Within: Wrapper 4", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5615, ["questLineOrder"] = 3 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6009, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83129] = { ["id"] = 83129, ["name"] = "Nowhere Left to Hide", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83126, 83127, 83128, 83129, 83130, 85449, 85450 }, ["description"] = "This barricade looks intentional. Hobart said Gallywix went off to a cave, and I'd say this sure looks like one. Gallywix has to have the Dark Heart in there. Help me blast this barricade open and get ready to fight.", ["objectivesText"] = "Destroy the Makeshift Barricade, then follow Gazlowe into the Hoardroom to confront Gallywix.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225730, ["x"] = 0.585, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 234048, ["x"] = 0.615, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.585, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83128 }, ["questLines"] = { { ["id"] = 5615, ["name"] = "Breaking the Shackles", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 6009, ["name"] = "Catch Up: War Within: Wrapper 4", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5615, ["questLineOrder"] = 3 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6009, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83130] = { ["id"] = 83130, ["name"] = "Sour Victory", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83126, 83127, 83128, 83129, 83130, 85449, 85450 }, ["description"] = "That's it. It's over. We're done. Gallywix lost, but the ethereals got the Dark Heart. Alleria needs to track them down. We need to check on everyone back at Bilgewater Flats, and then we need to go. There's nothin' else in this town for us.", ["objectivesText"] = "Meet Gazlowe at the Scrapshop in Bilgewater Flats.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardCurrencies"] = { { ["id"] = 3118, ["amount"] = 1000 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 234048, ["x"] = 0.615, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225756, ["x"] = 0.388, ["y"] = 0.246 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83128 }, ["questLines"] = { { ["id"] = 5615, ["name"] = "Breaking the Shackles", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5615, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83137] = { ["id"] = 83137, ["name"] = "When Opportunity Explodes", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2339, ["storyline"] = { 83137, 83139, 83140, 83141, 83142, 83143, 83144, 83145, 83146, 83147, 83148, 83149, 83150, 83151, 84683, 85409, 85410, 85444 }, ["description"] = "There ya are, <name>! Have you heard the latest news? There's a big hole blown in the side of the mountain out by Opportunity Point in the Ringing Deeps . There were opportunistic folks taking it over, and now there's even more. We'd better hurry over there.", ["objectivesText"] = "Investigate the blasted hole in Opportunity Point.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 230936 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 225571, ["x"] = 0.422, ["y"] = 0.27 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 227531, ["x"] = 0.63, ["y"] = 0.784 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 2214, 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5617, ["name"] = "Trust Issues", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5617, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[83138] = { ["id"] = 83138, ["name"] = "End of the Day", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83138, 83194, 83195, 83196, 83197, 83198, 83199, 83200, 83201, 83202, 83203, 83204, 83205, 83206, 83207, 85174, 85562, 85724, 85780, 86417 }, ["description"] = "Sprinkle and Seahorn are fine. Marin and Hobart are recoverin'. We didn't stop Gallywix, but at least the Dark Heart is... well, it's not in his hands. Which means we can leave. Nothin' left for us to do here. Finish up whatever business you've got in Undermine . I need to get out of this damn place.", ["objectivesText"] = "Speak to Renzik.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225756, ["x"] = 0.388, ["y"] = 0.246 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225757, ["x"] = 0.398, ["y"] = 0.242 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.246 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83130 }, ["questLines"] = { { ["id"] = 5668, ["name"] = "Ignite the Fuel of Change", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5668, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83139] = { ["id"] = 83139, ["name"] = "Mixed Messages", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83137, 83139, 83140, 83141, 83142, 83143, 83144, 83145, 83146, 83147, 83148, 83149, 83150, 83151, 84683, 85409, 85410, 85444 }, ["description"] = "Lots of these workers are headed to a Venture camp just down the road. That's a great first stop for information. We'll pay the tollbooth fee. It's best to just play along for now.", ["objectivesText"] = "Pay the toll at the tollbooth, then gather information from the northern goblin camp. Progress: See what these goblins know about the area!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 227531, ["x"] = 0.63, ["y"] = 0.784 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 225587, ["x"] = 0.658, ["y"] = 0.755 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.784 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 83137 }, ["questLines"] = { { ["id"] = 5617, ["name"] = "Trust Issues", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5617, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[83140] = { ["id"] = 83140, ["name"] = "Hostile Work Environment", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83137, 83139, 83140, 83141, 83142, 83143, 83144, 83145, 83146, 83147, 83148, 83149, 83150, 83151, 84683, 85409, 85410, 85444 }, ["description"] = "Bigger and more dangerous than Opportunity Point? These south mines sound real bad, even if ya have a high tolerance for bad working conditions. But what are they mining? Something here is worth big money. We'll need to check it out. I'll head past the big Darkfuse camp with Renzik, stealth mode. Make a big distraction for us, will ya? I'm sure you can slow down production while you're over there.", ["objectivesText"] = "Kill Darkfuse to keep the heat off Gazlowe and Renzik. Progress: Give us some time!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 225587, ["x"] = 0.658, ["y"] = 0.755 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 225587, ["x"] = 0.658, ["y"] = 0.755 }, { ["mapID"] = 2214, ["npcID"] = 225597, ["x"] = 0.719667, ["y"] = 0.816333 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.755 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 83139 }, ["questLines"] = { { ["id"] = 5617, ["name"] = "Trust Issues", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5617, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[83141] = { ["id"] = 83141, ["name"] = "Miner Investigations", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83137, 83139, 83140, 83141, 83142, 83143, 83144, 83145, 83146, 83147, 83148, 83149, 83150, 83151, 84683, 85409, 85410, 85444 }, ["description"] = "What \"riches\" are they mining out of the earth? Could this deep digging be related to my visions? Surely these goblins would not find value in something like Black Blood. We must get a closer look. Together we will gain insight into their operation.", ["objectivesText"] = "Examine suspicious canisters and crates with Orwenya.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 232741, 232747, 232752, 232756 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 227691, ["x"] = 0.644, ["y"] = 0.768 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 227688, ["x"] = 0.719333, ["y"] = 0.783333 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.644, ["y"] = 0.768 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 83139 }, ["questLines"] = { { ["id"] = 5617, ["name"] = "Trust Issues", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5617, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[83142] = { ["id"] = 83142, ["name"] = "Order of Magnitude", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83137, 83139, 83140, 83141, 83142, 83143, 83144, 83145, 83146, 83147, 83148, 83149, 83150, 83151, 84683, 85409, 85410, 85444 }, ["description"] = "<This document requires anyone with information about who opened the western wall to bring the information to their supervisor. It details the reward: a promotion to working inside Undermine. It also includes a promise of the favor and \"appreciation\" of Gallywix. Gazlowe will want to know about this.>", ["objectivesText"] = "Give the Bounty from Gallywix to Gazlowe. Progress: What'd you find?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 224772 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.721, ["y"] = 0.785, ["mapID"] = 2214, ["objectID"] = 456062 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 225587, ["x"] = 0.658, ["y"] = 0.755 }, { ["mapID"] = 2214, ["npcID"] = 225597, ["x"] = 0.719667, ["y"] = 0.816333 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.755 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 83139 }, ["questLines"] = { { ["id"] = 5617, ["name"] = "Trust Issues", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5617, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214, ["startItems"] = { 224772 } },
[83143] = { ["id"] = 83143, ["name"] = "Good Honest Work", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83137, 83139, 83140, 83141, 83142, 83143, 83144, 83145, 83146, 83147, 83148, 83149, 83150, 83151, 84683, 85409, 85410, 85444 }, ["description"] = "You're new here, right? I can tell by your questions. But don't worry, Zirdo 's your best pal! I'll give you a personalized tour. Gutterville, the Venture Company town, is just south down the road. It'll be informative and interactive. You can't ask for a better experience, trust me!", ["objectivesText"] = "Follow Zirdo on his \"tour.\" Progress: I lack words.", ["rewardGold"] = 232300, ["rewardXP"] = 8825, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 228017, ["x"] = 0.725, ["y"] = 0.792 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 225596, ["x"] = 0.718, ["y"] = 0.804 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.725, ["y"] = 0.792 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 83140, 83141, 83142 }, ["questLines"] = { { ["id"] = 5617, ["name"] = "Trust Issues", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5617, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[83144] = { ["id"] = 83144, ["name"] = "Bloodletting", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83137, 83139, 83140, 83141, 83142, 83143, 83144, 83145, 83146, 83147, 83148, 83149, 83150, 83151, 84683, 85409, 85410, 85444 }, ["description"] = "The land aches underfoot. These pipes carry Black Blood north in a massive volume! I've never seen the land become infected this rapidly. Clear away the rot--perhaps we can save it yet. I'll go after the structures. Point out weak spots as you find them and I will focus our assault!", ["objectivesText"] = "Kill Black Blood creatures and signal Orweyna to attack weak points in the pipeline. Progress: The horrors these goblins have brought forth are truly a blight on this land.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 232417, 232418 }, ["rewardChoices"] = { 232417, 232418 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 225596, ["x"] = 0.718, ["y"] = 0.804 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 228034, ["x"] = 0.695, ["y"] = 0.84 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.718, ["y"] = 0.804 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 83143 }, ["questLines"] = { { ["id"] = 5617, ["name"] = "Trust Issues", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5617, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[83145] = { ["id"] = 83145, ["name"] = "Paranoia Prevention", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83137, 83139, 83140, 83141, 83142, 83143, 83144, 83145, 83146, 83147, 83148, 83149, 83150, 83151, 84683, 85409, 85410, 85444 }, ["description"] = "What information is Gallywix after here in Gutterville? Let's see if some of these goblins will give us a hint. Let's start with any Bilgewater goblins we can find.", ["objectivesText"] = "Investigate Gutterville's spy problem. Progress: This seems like it's more about keeping people quiet than actually learning anything.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 225597, ["x"] = 0.719667, ["y"] = 0.816333 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 232491, ["x"] = 0.722, ["y"] = 0.822 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.719667, ["y"] = 0.816333 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 84683 }, ["questLines"] = { { ["id"] = 5617, ["name"] = "Trust Issues", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5617, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[83146] = { ["id"] = 83146, ["name"] = "Pamsy's Prized Pump", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83137, 83139, 83140, 83141, 83142, 83143, 83144, 83145, 83146, 83147, 83148, 83149, 83150, 83151, 84683, 85409, 85410, 85444 }, ["description"] = "I got a team of engineers. All of them got families. They keep having horrible accidents and infections from the Black Blood. I just couldn't stand another death. I opened the wall. I wanted it to bring us some hope. You show up and want to stop the Black Blood. It doesn't do anythin' good to stop these pipes up here. We gotta get to the pump station. So, my crew and the pumps? They're all at the same station. But we should hurry.", ["objectivesText"] = "Go to the pump station and meet Pamsy .", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 232491, ["x"] = 0.722, ["y"] = 0.822 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 228214, ["x"] = 0.705, ["y"] = 0.885 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.722, ["y"] = 0.822 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 83145, 85409 }, ["questLines"] = { { ["id"] = 5617, ["name"] = "Trust Issues", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5617, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[83147] = { ["id"] = 83147, ["name"] = "Bloody Business", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83137, 83139, 83140, 83141, 83142, 83143, 83144, 83145, 83146, 83147, 83148, 83149, 83150, 83151, 84683, 85409, 85410, 85444 }, ["description"] = "The horrors of the Black Blood here cannot be underestimated. The strength of it in this place is causing my visions to feel distant, like odd whispers. Kill the manifestations of this rot, before they grow stronger.", ["objectivesText"] = "Kill blood horrors for Orweyna . Progress: I cannot ignore this blight on the land.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 228894, ["x"] = 0.705, ["y"] = 0.886 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 228894, ["x"] = 0.705, ["y"] = 0.886 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.705, ["y"] = 0.886 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 83146 }, ["questLines"] = { { ["id"] = 5617, ["name"] = "Trust Issues", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5617, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[83148] = { ["id"] = 83148, ["name"] = "X-Treme Chill", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83137, 83139, 83140, 83141, 83142, 83143, 83144, 83145, 83146, 83147, 83148, 83149, 83150, 83151, 84683, 85409, 85410, 85444 }, ["description"] = "Pamsy and I came up with an idea. Since we can't access the controls, and we can't blow it up, what if we freeze the pump station? Stay with me! Pamsy mentioned that a lot of the machines up north are overheating lately, because all the coolant is being used down south. And it's even harder to get, because the blood slimes eat it. What if we found all of that coolant supply and dumped it into the pump station? We put the whole operation on ice, and it'd take ages to fix!", ["objectivesText"] = "Kill Chillgut Slimes to collect Chillburst Canisters . Progress: Get enough to freeze this station solid!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 224846 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 225598, ["x"] = 0.705, ["y"] = 0.886 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 225598, ["x"] = 0.705, ["y"] = 0.886 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.705, ["y"] = 0.886 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 83147, 85444 }, ["questLines"] = { { ["id"] = 5617, ["name"] = "Trust Issues", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5617, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[83149] = { ["id"] = 83149, ["name"] = "Avenge Them", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83137, 83139, 83140, 83141, 83142, 83143, 83144, 83145, 83146, 83147, 83148, 83149, 83150, 83151, 84683, 85409, 85410, 85444 }, ["description"] = "I followed Zirdo's trail south. I found a nasty piece o' work named Gozzic Cogcrane pushin' workers around and talking about \"another lesson.\" Zirdo must have snitched to this Gozzic guy, but I need to confirm it. I think this Gozzic will have the proof on him. Gozzic could've given the orders, but lookin' at that bloody shredder and the marks on Pamsy's crew, I'm sure he got involved personally. You should do the same. Kill Gozzic and check him for any sign Zirdo got word to him.", ["objectivesText"] = "Kill the Darkfuse that killed Pamsy's engineers. Progress: These engineers deserved better.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 231089 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 225599, ["x"] = 0.703333, ["y"] = 0.892 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 225599, ["x"] = 0.703333, ["y"] = 0.892 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.703333, ["y"] = 0.892 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 83147, 85444 }, ["questLines"] = { { ["id"] = 5617, ["name"] = "Trust Issues", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5617, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[83150] = { ["id"] = 83150, ["name"] = "Expanding the Plan", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83137, 83139, 83140, 83141, 83142, 83143, 83144, 83145, 83146, 83147, 83148, 83149, 83150, 83151, 84683, 85409, 85410, 85444 }, ["description"] = "Here's the plan. If we just freeze the outside, it'll all melt in a bit and go back to normal. But we got Orweyna. She can target cracks and leaks in the pipes so the coolant can get inside and really muck things up. Since you gathered all the canisters, I think you should get the honor of freezing the pipe solid. Pamsy has a rocketboard, and you'll be able to dispense icy justice down upon the station's key areas. Follow Orweyna!", ["objectivesText"] = "Ride the rocketboard and shoot the pipeline with ice. Progress: Hop onto the rocketboard and shoot away!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 232425, 232435, 232441, 232442, 232444, 232445, 232446, 232447, 235660, 238249, 238250 }, ["rewardChoices"] = { 232435 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 225598, ["x"] = 0.705, ["y"] = 0.886 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 228887, ["x"] = 0.703, ["y"] = 0.891 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.705, ["y"] = 0.886 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 83148, 83149 }, ["questLines"] = { { ["id"] = 5617, ["name"] = "Trust Issues", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5617, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[83151] = { ["id"] = 83151, ["name"] = "Down Undermine", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83137, 83139, 83140, 83141, 83142, 83143, 83144, 83145, 83146, 83147, 83148, 83149, 83150, 83151, 84683, 85409, 85410, 85444 }, ["description"] = "We've done what we could here. It's time to get a look at Undermine. Pamsy 's got a contact, a Venture goblin named Grimla. We can start there when we arrive. Let's get Gazlowe and get going. Undermine's not the kinda problem you solve with a knife. We need someone like Gazlowe on board for this. You know, the builder and leader type.", ["objectivesText"] = "Talk with Gazlowe, then go to Undermine using the rocket drill.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3118, ["amount"] = 1000 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 225599, ["x"] = 0.703333, ["y"] = 0.892 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225661, ["x"] = 0.32, ["y"] = 0.521 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.703333, ["y"] = 0.892 }, ["mapCandidates"] = { ["npc"] = { 2214, 2346 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 85410 }, ["questLines"] = { { ["id"] = 5617, ["name"] = "Trust Issues", ["orderIndex"] = 17, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5617, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83152] = { ["id"] = 83152, ["name"] = "Magmanagement", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83092, 83152, 83153, 83160 }, ["description"] = "As if the pipe going down wasn't enough, a horde of magmatic elementals burst out when it failed. We can't risk sending anyone else down to attempt repairs while the area is overrun, but that magma is vital to powering the whole Deeps. If you are capable, clear them out so we can get that magma flowing again.", ["objectivesText"] = "Kill Risen Magma and Slag Bubbles near Hallowfall Gate. Progress: Is it done?", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 225582, ["x"] = 0.389, ["y"] = 0.214 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 225582, ["x"] = 0.389, ["y"] = 0.214 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.389, ["y"] = 0.214 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79573, 80434 }, ["questLines"] = { { ["id"] = 5654, ["name"] = "Magma-nificence", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[83153] = { ["id"] = 83153, ["name"] = "Sampling Steam", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83092, 83152, 83153, 83160 }, ["description"] = "The effects of the magmatic buildup are clear to see, but what we still do not understand is the root cause. In order to determine it, and prevent it in the future, I need samples of the volcanic gases you can see bursting from the ground. Fresh samples. Very fresh. You're going to have to stand in them as they erupt in order to gather what I need.", ["objectivesText"] = "Stand in gas vents near Hallowfall Gate as they erupt to gather samples. Progress: Do you have the samples?", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["rewardItems"] = { 219455, 219456, 219457, 219458, 219459, 219460, 219461, 219462, 219463, 219464, 219465, 219466, 219467 }, ["rewardChoices"] = { 219455, 219456, 219457, 219458, 219459, 219460, 219461, 219462, 219463, 219464, 219465, 219466, 219467 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 25 }, { ["id"] = 2902, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 225583, ["x"] = 0.389, ["y"] = 0.214 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 225583, ["x"] = 0.389, ["y"] = 0.214 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.389, ["y"] = 0.214 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79573, 80434 }, ["questLines"] = { { ["id"] = 5654, ["name"] = "Magma-nificence", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[83154] = { ["id"] = 83154, ["name"] = "Knicknack's Knickknacks", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83154 }, ["description"] = "Not fair! Not fair! Knicknack collect many shiny things over long life. But now stupid wax for brains Candleclaws push out Knicknack and family. Shiny things all left behind! Here, goblin friend helped made list of all my treasures inside Darkflame Cleft. You go take back!", ["objectivesText"] = "Retrieve Knicknack 's treasures from Darkflame Cleft. Progress: Treasures all very important. Very valuable. You no take for you! Bring back to me!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 224773, 224774, 224775, 224778 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 225555, ["x"] = 0.450667, ["y"] = 0.302667 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 225555, ["x"] = 0.450667, ["y"] = 0.302667 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.450667, ["y"] = 0.302667 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "dungeon", ["db2QuestHubAreaPoiID"] = 7911 },
[83155] = { ["id"] = 83155, ["name"] = "Tired of Tripping", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83155, 83159, 83162 }, ["description"] = "All that's between us and the juiciest excavation site I've ever seen is a couple of moles and a leggy deer. Sorry, getting ahead of myself. See these shredders? State of the art in the field of maiming and killing. And they keep getting stuck in holes! Listen, I'm as ecologically conscientious as the next goblin, but these moles have got to go. I'm gonna need you to give these hardheads a hard time. And if you see any of my crew, help 'em out, wontcha?", ["objectivesText"] = "\"Remove\" 15 Hardhead moles. Progress: You deal with 'em yet? I'm not hauling another shredder out of the mud.", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 225608, ["x"] = 0.617, ["y"] = 0.792 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 225608, ["x"] = 0.617, ["y"] = 0.792 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.617, ["y"] = 0.792 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79573, 80434 }, ["questLines"] = { { ["id"] = 5623, ["name"] = "Abysmal Extraction", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[83159] = { ["id"] = 83159, ["name"] = "A Little Off the Top", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83155, 83159, 83162 }, ["description"] = "Ever seen a deepstrider before? This one sure ain't happy to see us. Made quick work of the shredders that made it past the moles. Real shame, those pilots are gonna have to work overtime to pay off the damages. Now if someone were to take care of it and bring back something as proof, well, I'm sure there'd be a nice payday.", ["objectivesText"] = "Slay Alhainr and collect its skull. Progress: What did you do?!", ["rewardGold"] = 619600, ["rewardXP"] = 12400, ["rewardItems"] = { 224779 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 225608, ["x"] = 0.617, ["y"] = 0.792 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 226336, ["x"] = 0.617, ["y"] = 0.792 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.617, ["y"] = 0.792 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 83155 }, ["questLines"] = { { ["id"] = 5623, ["name"] = "Abysmal Extraction", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[83160] = { ["id"] = 83160, ["name"] = "Cinderbrew Reserve", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83092, 83152, 83153, 83160 }, ["description"] = "Trade may have been restricted, but I'll calcify before I let my Cinderbrew Reserve fall into the hands of these stripped screws or go up when some elemental looks at it funny. The inspectors are watching me, stranger, so I can't go fetch it myself, but they won't be paying any special attention to you. I left it behind the desk in my old office, down below. Just don't get too close to an enforcer or they'll confiscate any cinderbrew you're carrying and I'll be left with nothing to drink.", ["objectivesText"] = "Bring the Cinderbrew Reserve to Cogwin at the Hallowfall Gate. Progress: Do you have it?", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["rewardItems"] = { 253172 }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 225616, ["x"] = 0.4, ["y"] = 0.224667 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 225616, ["x"] = 0.4, ["y"] = 0.224667 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.224667 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 79573, 80434 }, ["questLines"] = { { ["id"] = 5654, ["name"] = "Magma-nificence", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[83162] = { ["id"] = 83162, ["name"] = "Put it Back, Put it Back!", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83155, 83159, 83162 }, ["description"] = "It's going to ruin everything! Who wants to visit a resort with a thirty-foot tall ghost-deer? Ok, no need to panic. It's probably just a little miffed you took its skull. First, you gotta get rid of some of these slimes. Then, get that skull out of here. The farther the better. Oh man, they're gonna get ectoplasm in the hot pools!", ["objectivesText"] = "Stomp slimes and take Alhainr's Skull away from town. Progress: Hurry up, before this whole place is wrecked!", ["rewardGold"] = 292100, ["rewardXP"] = 9920, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 180 }, { ["id"] = 2902, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 226336, ["x"] = 0.617, ["y"] = 0.792 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 225608, ["x"] = 0.617, ["y"] = 0.792 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.617, ["y"] = 0.792 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 83159 }, ["questLines"] = { { ["id"] = 5623, ["name"] = "Abysmal Extraction", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[83163] = { ["id"] = 83163, ["name"] = "Split Venture", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83096, 83109, 83163, 83167, 83168, 83169, 83170, 83171, 83172, 83173, 83174, 83175, 83176, 85941, 86297 }, ["description"] = "We're headed to my home turf next, Venturewood. It's next to the Heaps. The Venture Company is mostly on board for Gallywix. That means a lot of the top brass are as dirty as him. Watch your step. But there are some good folks there too. Like Pamsy and her crew. The little guy at Venture gets it rough. Everyone thinks of Venture Co. as just the baddies, so no one looks after them. But I gotta try right? Hop in the hot rod, I'll show you what I mean.", ["objectivesText"] = "Ride the hot rod to the Venturewood and assist friendly Venture Co. goblins. Progress: Seems like there's no respect for the little guys.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 232448, 232449, 232450, 232451, 232452, 232453, 235661, 238251 }, ["rewardChoices"] = { 235661 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 229246, ["x"] = 0.452, ["y"] = 0.422 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 229247, ["x"] = 0.435, ["y"] = 0.605 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 85941, 86297 }, ["questLines"] = { { ["id"] = 5661, ["name"] = "Undermine Awaits", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5661, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83164] = { ["id"] = 83164, ["name"] = "City of Threads: Splice the Splicer", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 83164 }, ["description"] = "\"Ascension\" is no true evolution. It is defilement. It is doom. And Ansurek further etches that doom in stone with each passing day. If we bring down the Transformatory, then we can potentially rid Azj-Kahet of these abominations for good. Izo the Grand Splicer is Ansurek's chosen overseer of the Ascension process. Cut that wretch's head from her body, and perhaps these mutations will cease.", ["objectivesText"] = "Enter the City of Threads and defeat Izo the Grand Splicer. Progress: Have you dealt with the Transformatory, <name>?", ["rewardGold"] = 1239200, ["rewardXP"] = 19030, ["rewardItems"] = { 221181, 221189 }, ["rewardChoices"] = { 221181, 221189 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 224733, ["x"] = 0.562, ["y"] = 0.422 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 224733, ["x"] = 0.562, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "dungeon" },
[83165] = { ["id"] = 83165, ["name"] = "Badly Behaved Bot", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83165 }, ["description"] = "Go ahead, laugh. I would be as well if I didn't have such pressing business. My bot's foot clipped a nearby rock, spilled me out and then righted herself. Without me in the cockpit! I'm grounded while she floats there quite cheerfully. Can you believe it? Listen, if you are heading up to Shadowvein Point, will you let Kagfritha know that I'll be late for my shift? I need to wait for this hunk of metal to run out of fuel and dip low enough for me to get back in the driver's seat.", ["objectivesText"] = "Speak with Kagfritha in Shadowvein Point.", ["rewardGold"] = 154900, ["rewardXP"] = 4960, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 223759, ["x"] = 0.582, ["y"] = 0.57 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 220417, ["x"] = 0.601, ["y"] = 0.468 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.582, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard" },
[83166] = { ["id"] = 83166, ["name"] = "Ara-Kara, the City of Echoes: Harvest's End", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 83166 }, ["description"] = "You've seen it yourself, haven't you? The \"Black Blood,\" as we call it. We will not stand idle any longer. Not while Ansurek mutilates, drills, and exsanguinates our precious land for the last, fetid dribbles of the old gods' death rattle. Seek out the old city beneath us--Ara-Kara, The City of Echoes. You will receive a handsome bounty should you slay the crony in charge of the excavation. Her people call her Ki'katal, the Harvester.", ["objectivesText"] = "Enter the Ara-Kara, The City of Echoes and defeat Ki'katal the Harvester. Progress: Have you been to Ara-Kara yet?", ["rewardGold"] = 1239200, ["rewardXP"] = 19030, ["rewardItems"] = { 219314, 221154 }, ["rewardChoices"] = { 219314 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 224733, ["x"] = 0.562, ["y"] = 0.422 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 224733, ["x"] = 0.562, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "dungeon" },
[83167] = { ["id"] = 83167, ["name"] = "Eyes from Above", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83096, 83109, 83163, 83167, 83168, 83169, 83170, 83171, 83172, 83173, 83174, 83175, 83176, 85941, 86297 }, ["description"] = "That was rough, with Nikki. And worse, those Darkfuse spy-copters saw everything. Feels like we can't get away from all the spies, don't it? The last thing Venture needs is Gallywix thinking these workers ain't loyal 'cause they got caught on footage during one of Nikki's tantrums. We don't want a repeat of what happened to my last crew. Go take the footage from the spy-copters. They usually lurk around the workshops, or follow Venture workers around.", ["objectivesText"] = "Kill 8 Spy-Copters to steal their footage. Progress: There is nothing better than breaking bad machines for a good cause.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 232902 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225618, ["x"] = 0.436, ["y"] = 0.608 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225618, ["x"] = 0.436, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.436, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83163 }, ["questLines"] = { { ["id"] = 5661, ["name"] = "Undermine Awaits", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5661, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83168] = { ["id"] = 83168, ["name"] = "A Trail of Black Blood", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83096, 83109, 83163, 83167, 83168, 83169, 83170, 83171, 83172, 83173, 83174, 83175, 83176, 85941, 86297 }, ["description"] = "While you have been getting familiar with the state of Undermine , I have been tracking our prey. The presence of Black Blood is everywhere, hidden behind noisy distractions. But this city cannot fool me. I discovered a Black Blood shipment at a place called Hovel Hill, but there were machines guarding it. We should go together.", ["objectivesText"] = "Investigate Hovel Hill for Black Blood shipments. Progress: Tracking the shipments should show us who's using 'em. Check out any labels or letters layin' around! I think I stunned all of the defenses, they'll leave us be.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 232944 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225659, ["x"] = 0.356, ["y"] = 0.5384 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 229233, ["x"] = 0.33, ["y"] = 0.478 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.356, ["y"] = 0.5384 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83163 }, ["questLines"] = { { ["id"] = 5661, ["name"] = "Undermine Awaits", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5661, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83169] = { ["id"] = 83169, ["name"] = "Long Way from Booty Bay", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83096, 83109, 83163, 83167, 83168, 83169, 83170, 83171, 83172, 83173, 83174, 83175, 83176, 85941, 86297 }, ["series"] = { 83170 }, ["description"] = "There is no doubt about it. These shipments have Blackwater Cartel written all over them... literally. The Black Blood comes in here and then Blackwater takes it somewhere in the city by couriers. So if we want to find out where, we go right to the top-- Baron Revilgaz . Grimla mentioned Revilgaz has a temporary set up nearby, here in Hovel Hill. Let's go pay him a visit. The ethereal thing will have to wait.", ["objectivesText"] = "Locate Baron Revilgaz at Hovel Hill. Progress: I have a bad feeling about all this, but let's talk to Revilgaz.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 229233, ["x"] = 0.33, ["y"] = 0.478 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225686, ["x"] = 0.308, ["y"] = 0.395 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.33, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83163 }, ["questLines"] = { { ["id"] = 5661, ["name"] = "Undermine Awaits", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5661, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83170] = { ["id"] = 83170, ["name"] = "Not Again!", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83096, 83109, 83163, 83167, 83168, 83169, 83170, 83171, 83172, 83173, 83174, 83175, 83176, 85941, 86297 }, ["series"] = { 83169 }, ["description"] = "The Darkfuse are moving into Hovel Hill. It's the same thing they did at Blackwater Marina. Once they move in, they start pushing the locals around. Sometimes they just make 'em go away. It ain't right. I want to fight back, but my hands are tied. If an outsider showed up and started making trouble, that'd be a different story.", ["objectivesText"] = "Make trouble with the Darkfuse in Hovel Hill for Revilgaz. Progress: Fairness is a loose concept in Undermine , but the Darkfuse push it too far.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 2772, 24118, 24119, 24120, 25631, 25632, 25633, 29333, 29334, 29335, 29336, 32569, 34125, 37829, 44785, 44788, 46723, 46800, 46824, 52593, 52617, 52640, 52644, 52673, 53563, 53564, 53565, 62210, 62211, 62212, 62213, 65678, 65699, 65717, 116404, 131283, 131655, 131695, 140255, 142054, 156996, 181501, 181502, 181503, 181507, 181625, 181638, 181645, 181646, 181647, 181648, 181649, 181651, 181652, 181653, 181654, 181655, 181660, 181661, 181662, 181663, 181664, 181665, 181666, 181667, 181668, 181669, 181670, 181672, 181675, 181676, 181677, 181679, 181680, 181689, 181695, 184305, 184772, 184773, 184774, 184775, 184776, 198608, 242715 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225686, ["x"] = 0.308, ["y"] = 0.395 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225686, ["x"] = 0.308, ["y"] = 0.395 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.308, ["y"] = 0.395 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83169 }, ["questLines"] = { { ["id"] = 5661, ["name"] = "Undermine Awaits", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5661, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83171] = { ["id"] = 83171, ["name"] = "Eye Sores for Sore Eyes", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83096, 83109, 83163, 83167, 83168, 83169, 83170, 83171, 83172, 83173, 83174, 83175, 83176, 85941, 86297 }, ["description"] = "They call them recruitment posters, but that ain't all they're for. They're there to remind everyone the Darkfuse are in charge and can do whatever they want. If me or one of the locals rip 'em down, it goes bad for us. But the Darkfuse hate you anyway. If you torched all the posters, I would owe you one.", ["objectivesText"] = "Burn 8 Darkfuse Recruitment Posters on and around Revilgaz's house. Progress: I'm sick of seeing those recruitment posters. Burn them.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 232740, 232748, 232750, 232761 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225686, ["x"] = 0.308, ["y"] = 0.395 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225686, ["x"] = 0.308, ["y"] = 0.395 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.308, ["y"] = 0.395 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83169 }, ["questLines"] = { { ["id"] = 5661, ["name"] = "Undermine Awaits", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5661, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83172] = { ["id"] = 83172, ["name"] = "Black Blood Baton Pass", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83096, 83109, 83163, 83167, 83168, 83169, 83170, 83171, 83172, 83173, 83174, 83175, 83176, 85941, 86297 }, ["description"] = "Blackwater is just one step on the journey, and they like to keep this stuff moving. Revilgaz has his people take it from the station, hide it for a bit, then deliver it to the drop sites. The drop sites change, but the current one is a depot in the Heaps. We're gonna check it out and find out where the Black Blood goes from there. He says it's guarded, so look for us out near the edge.", ["objectivesText"] = "Meet with Renzik and Gazlowe at the next Black Blood depot in the Heaps.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 229242, ["x"] = 0.308, ["y"] = 0.395 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 229243, ["x"] = 0.616, ["y"] = 0.718 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.308, ["y"] = 0.395 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83170, 83171 }, ["questLines"] = { { ["id"] = 5661, ["name"] = "Undermine Awaits", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5661, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83173] = { ["id"] = 83173, ["name"] = "Clearing Out the Depot", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83096, 83109, 83163, 83167, 83168, 83169, 83170, 83171, 83172, 83173, 83174, 83175, 83176, 85941, 86297 }, ["description"] = "The Heaps are crawling with guards. We've got an opportunity to disrupt the Black Blood operation in Undermine and we should take it. We can't stop all the Black Blood from getting around the city, but we can clear out some guards and smash some shipments. Mess them up enough to disrupt things. Every little bit helps.", ["objectivesText"] = "Clear the depot area in the Heaps. Progress: Every guards or shipment lost costs them time and money. And Gallywix hates losing both.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 229243, ["x"] = 0.616, ["y"] = 0.718 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 229243, ["x"] = 0.616, ["y"] = 0.718 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83172 }, ["questLines"] = { { ["id"] = 5661, ["name"] = "Undermine Awaits", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5661, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83174] = { ["id"] = 83174, ["name"] = "Our Good Pal", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83096, 83109, 83163, 83167, 83168, 83169, 83170, 83171, 83172, 83173, 83174, 83175, 83176, 85941, 86297 }, ["description"] = "Our old pal Zirdo 's back. It looks like he's been promoted to Overseer of the Heaps, keeping track of the Black Blood shipments. We owe him some payback for sellin' us out in Gutterville. He got a lot of good goblins killed to get on Gallywix's good side. Give the little snitch what he deserves.", ["objectivesText"] = "Kill Zirdo .", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 232393, 232395, 232397, 232399 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 229235, ["x"] = 0.616, ["y"] = 0.718 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 229235, ["x"] = 0.616, ["y"] = 0.718 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83172 }, ["questLines"] = { { ["id"] = 5661, ["name"] = "Undermine Awaits", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5661, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83175] = { ["id"] = 83175, ["name"] = "Another Piece of the Puzzle", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83096, 83109, 83163, 83167, 83168, 83169, 83170, 83171, 83172, 83173, 83174, 83175, 83176, 85941, 86297 }, ["description"] = "<The ledger has longwinded ramblings about Zirdo's achievements, but also contains various deliveries of Black Blood across Undermine . Multiple entries in the ledger stick out as odd: - One thousand units for Secret Project, Deliver to Secret Project Site. - Twenty units for Developmental Ammunition, Deliver via Courier. Transfers approved by Noggenfogger of Steamwheedle.>", ["objectivesText"] = "Discuss the contents of Zirdo's Ledger with Gazlowe in the Heaps. Progress: Noggenfogger knows better than to get mixed up with Gallywix.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 224797 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.656, ["y"] = 0.808, ["mapID"] = 2346, ["objectID"] = 500619 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 229235, ["x"] = 0.616, ["y"] = 0.718 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83172 }, ["questLines"] = { { ["id"] = 5661, ["name"] = "Undermine Awaits", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5661, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346, ["startItems"] = { 224797 } },
[83176] = { ["id"] = 83176, ["name"] = "Just a Hunch", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83096, 83109, 83163, 83167, 83168, 83169, 83170, 83171, 83172, 83173, 83174, 83175, 83176, 85941, 86297 }, ["description"] = "It's time to sort out what to do next. This Noggenfogger business has Gazlowe on edge and we gotta move quickly to find out what's going on. Something's got me on edge too. We should get outta the Heaps fast. But let's make sure Gazlowe's on board.", ["objectivesText"] = "Check in with Renzik about Gazlowe, and then meet Gazlowe outside of the Heaps.", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 245310 }, ["rewardCurrencies"] = { { ["id"] = 3118, ["amount"] = 1000 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 229243, ["x"] = 0.616, ["y"] = 0.718 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 229236, ["x"] = 0.424667, ["y"] = 0.514667 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83173, 83174, 83175 }, ["questLines"] = { { ["id"] = 5661, ["name"] = "Undermine Awaits", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5661, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83177] = { ["id"] = 83177, ["name"] = "Socialized Medicine", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2213, ["storyline"] = { 83177 }, ["description"] = "It has come to my attention that the most downtrodden residents of the Burrows have fallen prey to some sort of malady. Take this potion and dose the sick. This will strengthen the citizens and curtail further outbreak.", ["objectivesText"] = "Dose Downtrodden Residents with Nizrek's potion . Progress: Have you aided the residents of the Burrows?", ["rewardGold"] = 292100, ["rewardXP"] = 11765, ["rewardItems"] = { 224799 }, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 208782, ["x"] = 0.526667, ["y"] = 0.462667 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 208782, ["x"] = 0.526667, ["y"] = 0.462667 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.526667, ["y"] = 0.462667 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questType"] = "standard" },
[83178] = { ["id"] = 83178, ["name"] = "Rules and Consequences", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2213, ["storyline"] = { 83178 }, ["description"] = "I fear I have grown too brazen in my offerings of succor as of late. I seem to have attracted some untoward eyes. Be on guard. A veiled threat looms.", ["objectivesText"] = "Defeat the Assassin. Progress: Have you handled the interloper?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3056, ["amount"] = 35 }, { ["id"] = 3056, ["amount"] = 750 } }, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 208782, ["x"] = 0.526667, ["y"] = 0.462667 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 208782, ["x"] = 0.526667, ["y"] = 0.462667 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.526667, ["y"] = 0.462667 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["sourceQuests"] = { 83177 } },
[83181] = { ["id"] = 83181, ["name"] = "Best Friends, Same Ends", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 80209, 80210, 80211, 80212, 80213, 80214, 80215, 80216, 80217, 80218, 80456, 83181 }, ["description"] = "I saw the shipwright leave the cave and head down to the beach. She was accompanied by a formidable looking nerubian. The shipwright is the mastermind behind this entire operation. She knows precisely how the lumber is to be cut and what lumber is needed for their airships. The nerubians know this and likely assigned one of their best to protect her. If we can eliminate the shipwright, we can bring all of their carefully laid plans to ruin.", ["objectivesText"] = "Eliminate Shipwright Isaebela and Shadowspinner Azarak at Silkwood Grotto. Progress: Is it done <name>?", ["rewardGold"] = 584200, ["rewardXP"] = 11895, ["rewardItems"] = { 223424, 223441, 223456, 223464, 228428 }, ["rewardCurrencies"] = { { ["id"] = 2897, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 222363, ["x"] = 0.66, ["y"] = 0.238 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 222363, ["x"] = 0.66, ["y"] = 0.238 }, { ["mapID"] = 2248, ["npcID"] = 222366, ["x"] = 0.654, ["y"] = 0.204 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.238 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 80217 }, ["questLines"] = { { ["id"] = 5571, ["name"] = "Brotherhood in the Skolzgal Wood", ["orderIndex"] = 11, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[83182] = { ["id"] = 83182, ["name"] = "A Bloody Inheritance", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 79151, 79152, 79153, 79154, 83182 }, ["description"] = "When the kobyss killed my parents, they stole some of their most cherished things. Not me, obviously. Cherished items. While we are murdering kobyss, let's find them.", ["objectivesText"] = "Retrieve Alyza's parents' items in the Hungering Pool in Hallowfall . Progress: Stupid kobyss. I hate them.", ["rewardGold"] = 292100, ["rewardXP"] = 10190, ["rewardItems"] = { 215446, 216524, 216525, 216526 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 218062, ["x"] = 0.524, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 215254, ["x"] = 0.50519, ["y"] = 0.501 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.524, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 79151 }, ["questLines"] = { { ["id"] = 5527, ["name"] = "An Orphan's Dilemma", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[83194] = { ["id"] = 83194, ["name"] = "Under Fire", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83138, 83194, 83195, 83196, 83197, 83198, 83199, 83200, 83201, 83202, 83203, 83204, 83205, 83206, 83207, 85174, 85562, 85724, 85780, 86417 }, ["description"] = "I'm only standing here because of Renzik. He didn't even think about it--he just...", ["objectivesText"] = "Be there for Monte Gazlowe . Progress: We're not finished here.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 200073, 201921, 201922, 201923, 201924 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225757, ["x"] = 0.398, ["y"] = 0.242 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225523, ["x"] = 0.398, ["y"] = 0.242 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.398, ["y"] = 0.242 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83138 }, ["questLines"] = { { ["id"] = 5668, ["name"] = "Ignite the Fuel of Change", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5668, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83195] = { ["id"] = 83195, ["name"] = "Rally the People", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83138, 83194, 83195, 83196, 83197, 83198, 83199, 83200, 83201, 83202, 83203, 83204, 83205, 83206, 83207, 85174, 85562, 85724, 85780, 86417 }, ["description"] = "No one's been stepped on harder by Gallywix than the Bilgewater Cartel. Plenty already want to rise up, but that ain't enough. We gotta show them what Gallywix has done and convince them that now is the time. Let's start with a headline. C'mon, pitch me. A big shot like you carries our message better than anyone else.", ["objectivesText"] = "Pick a headline with Dirk Greasedealer and then spread the word of revolution in Tailgate Park. Progress: Now is the time to rise up. Tell 'em, <name>.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 228196 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 226660, ["x"] = 0.485, ["y"] = 0.408 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225866, ["x"] = 0.51, ["y"] = 0.36 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.408 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 85174 }, ["questLines"] = { { ["id"] = 5668, ["name"] = "Ignite the Fuel of Change", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5668, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83196] = { ["id"] = 83196, ["name"] = "Disperse!", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83138, 83194, 83195, 83196, 83197, 83198, 83199, 83200, 83201, 83202, 83203, 83204, 83205, 83206, 83207, 85174, 85562, 85724, 85780, 86417 }, ["description"] = "Gallywix can't hide the truth, but he can beat us down until folks have no choice but to accept it. We ain't lettin' that happen again. You see someone hurting a Bilgewater goblin, return the favor.", ["objectivesText"] = "Kill 20 Darkfuse at Tailgate Park. Progress: The people have to know the streets are safe. It's on us to make them so.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 228196 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 226660, ["x"] = 0.485, ["y"] = 0.408 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225866, ["x"] = 0.51, ["y"] = 0.36 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.408 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 85174 }, ["questLines"] = { { ["id"] = 5668, ["name"] = "Ignite the Fuel of Change", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5668, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83197] = { ["id"] = 83197, ["name"] = "Who Owns the Streets?", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83138, 83194, 83195, 83196, 83197, 83198, 83199, 83200, 83201, 83202, 83203, 83204, 83205, 83206, 83207, 85174, 85562, 85724, 85780, 86417 }, ["description"] = "Her! Nikki the Fixer, Venture Company's top enforcer. Renzik's blood is on her hands. I can't worry if she's got another bullet. We gotta go after her. You with me, <name>?", ["objectivesText"] = "Confront Renzik's killer, Nikki the Fixer.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 234551, ["x"] = 0.508667, ["y"] = 0.349333 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225868, ["x"] = 0.584667, ["y"] = 0.332667 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.508667, ["y"] = 0.349333 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83195, 83196 }, ["questLines"] = { { ["id"] = 5668, ["name"] = "Ignite the Fuel of Change", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5668, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83198] = { ["id"] = 83198, ["name"] = "Backyard Navy", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83138, 83194, 83195, 83196, 83197, 83198, 83199, 83200, 83201, 83202, 83203, 83204, 83205, 83206, 83207, 85174, 85562, 85724, 85780, 86417 }, ["description"] = "Gallywix and his crew have been meddling in our business for too long. Look at what they're doing to my marina! So comfortable with their holdings that they're doing donuts on jetskis! It's time we introduce them to a little high seas firepower. Take this cannon and blow those Darkfuse vessels skimming our waters sky-high. After that, do me a favor and check up on the big guy, won't ya?", ["objectivesText"] = "Destroy the Darkfuse Joyriders in the Blackwater Marina. Progress: Did my Captain send you? He knew I'd need help...", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 228975 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225868, ["x"] = 0.584667, ["y"] = 0.332667 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225870, ["x"] = 0.638, ["y"] = 0.175 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.584667, ["y"] = 0.332667 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83197 }, ["questLines"] = { { ["id"] = 5668, ["name"] = "Ignite the Fuel of Change", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5668, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83199] = { ["id"] = 83199, ["name"] = "Been Savin' This One", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83138, 83194, 83195, 83196, 83197, 83198, 83199, 83200, 83201, 83202, 83203, 83204, 83205, 83206, 83207, 85174, 85562, 85724, 85780, 86417 }, ["description"] = "Listen <name>, Sprinkle's been cooking something for a long time that I'm finally ready to cash in. A little alchemist's secret ingredient. Citrus! Delivers twice the kick of Noggenfogger's Restorative Elixirs at half the speed. Strengthens your bones, grows your muscles, does your taxes. The whole nine yards! Problem is, I've got nothing of the sort on hand. These resort types may have what you need. We've been saving this recipe for a heavy hitter. Make sure Seahorn's alright before cooking it up, yeah?", ["objectivesText"] = "Collect Limes from the Resort Staff at the Blackwater Marina. Progress: Ngh. Did they get me with that Black Blood?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 226203, 226217 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225867, ["x"] = 0.584667, ["y"] = 0.332667 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225870, ["x"] = 0.638, ["y"] = 0.175 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.584667, ["y"] = 0.332667 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83197 }, ["questLines"] = { { ["id"] = 5668, ["name"] = "Ignite the Fuel of Change", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5668, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83200] = { ["id"] = 83200, ["name"] = "A Vast, Ye Swabs", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83138, 83194, 83195, 83196, 83197, 83198, 83199, 83200, 83201, 83202, 83203, 83204, 83205, 83206, 83207, 85174, 85562, 85724, 85780, 86417 }, ["description"] = "Urgh. I've been locked up for so long. In my anger, I got reckless. Whatever Noggenfogger gave ya, I promise not to squander. Get me back in the fight and we'll bring the full swell of Blackwater's might down on these invaders.", ["objectivesText"] = "Brew the Noggenfogger Deluxe with Lime and feed it to Fleet Master Seahorn .", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 226372 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225870, ["x"] = 0.638, ["y"] = 0.175 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 233296, ["x"] = 0.638, ["y"] = 0.175 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.638, ["y"] = 0.175 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83198, 83199 }, ["questLines"] = { { ["id"] = 5668, ["name"] = "Ignite the Fuel of Change", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5668, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83201] = { ["id"] = 83201, ["name"] = "Expedited Delivery", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83138, 83194, 83195, 83196, 83197, 83198, 83199, 83200, 83201, 83202, 83203, 83204, 83205, 83206, 83207, 85174, 85562, 85724, 85780, 86417 }, ["description"] = "Blackwater can take the marina from here. But the people aren't safe with Black Blood that's already out there. Those flying transports must be taking the Black Blood somewhere under Venture Co. control. Commandeer one, and you might find Grimla. She was headed in that direction when we split up, shouting that a friend of hers was on the way.", ["objectivesText"] = "Hitch a ride on a Malfunctioning Cratemover.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["npcID"] = 235849 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225871, ["x"] = 0.452, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questGiverID"] = 235849, ["questType"] = "standard", ["sourceQuests"] = { 85562, 85724 }, ["questLines"] = { { ["id"] = 5668, ["name"] = "Ignite the Fuel of Change", ["orderIndex"] = 11, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5668, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83202] = { ["id"] = 83202, ["name"] = "Punching Up", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83138, 83194, 83195, 83196, 83197, 83198, 83199, 83200, 83201, 83202, 83203, 83204, 83205, 83206, 83207, 85174, 85562, 85724, 85780, 86417 }, ["description"] = "The time for talking out our differences is over. I'm done second-guessing who is still standing with Gallywix. Some of Nikki's people are keeping these new weapons in production. So, we take them out. It makes cleaning up Venture Co. after all this is done way simpler too. Just be careful. Nikki won't stick her neck out for her lieutenants, but she'll take the chance to rig a fight against you.", ["objectivesText"] = "Defeat the three Venture Co. loyalist lieutenants.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 194368 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225871, ["x"] = 0.452, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225874, ["x"] = 0.485, ["y"] = 0.775 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83201 }, ["questLines"] = { { ["id"] = 5668, ["name"] = "Ignite the Fuel of Change", ["orderIndex"] = 12, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5668, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83203] = { ["id"] = 83203, ["name"] = "Weapons Hot", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83138, 83194, 83195, 83196, 83197, 83198, 83199, 83200, 83201, 83202, 83203, 83204, 83205, 83206, 83207, 85174, 85562, 85724, 85780, 86417 }, ["description"] = "The destructive impulses of those who harvest Azeroth for their own profit never cease to horrify me. But these weapons are like nothing that has come before. All containers of Black Blood must be overturned and destroyed. Weapons fueled by it crushed and dismantled. Those who wield it against others, put down. The people of this city, and this world, won't be safe until we do.", ["objectivesText"] = "Destroy Black Blood crates and weapons in the Heaps.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225873, ["x"] = 0.452, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 234728, ["x"] = 0.485, ["y"] = 0.775 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83201 }, ["questLines"] = { { ["id"] = 5668, ["name"] = "Ignite the Fuel of Change", ["orderIndex"] = 13, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5668, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83204] = { ["id"] = 83204, ["name"] = "The Thingamajig", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83138, 83194, 83195, 83196, 83197, 83198, 83199, 83200, 83201, 83202, 83203, 83204, 83205, 83206, 83207, 85174, 85562, 85724, 85780, 86417 }, ["description"] = "Nikki's tech is powered by Black Blood. I know that because I worked on half of it. That also means I have an idea on how we might knock her out of the sky for long enough to take her out. No time for pre-production. We gotta build. Remember our flashy little hoverboard adventure? Ice is nice, eh? I'm thinkin' of a similar principle--the trash heap oughta have all the salvage we'll need to build this hypothetical thingamajig.", ["objectivesText"] = "Recover parts for Pamsy in the Heaps. Progress: You got time to yap, then you've got time to smash!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 228792, 233512, 233513, 234489 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 233390, ["x"] = 0.516889, ["y"] = 0.708222 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 233390, ["x"] = 0.516889, ["y"] = 0.708222 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.516889, ["y"] = 0.708222 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83202, 83203 }, ["questLines"] = { { ["id"] = 5668, ["name"] = "Ignite the Fuel of Change", ["orderIndex"] = 14, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5668, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83205] = { ["id"] = 83205, ["name"] = "Production Halted", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83138, 83194, 83195, 83196, 83197, 83198, 83199, 83200, 83201, 83202, 83203, 83204, 83205, 83206, 83207, 85174, 85562, 85724, 85780, 86417 }, ["description"] = "< Orweyna rubs her palms with dirt, then cracks her knuckles.> Now, we teach those who toy with Black Blood nature's wrath. I am eager to call upon the roots twisting through Azeroth. Join me. Unleash nature's fury as we did before. Let us destroy their prized stockpiles of Black Blood.", ["objectivesText"] = "Destroy the Black Blood stockpiles in the Heaps. Progress: I would not have guessed Orweyna was that much of a natural at dodging rockets.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 234728, ["x"] = 0.485, ["y"] = 0.775 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225876, ["x"] = 0.565, ["y"] = 0.6755 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.775 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83202, 83203 }, ["questLines"] = { { ["id"] = 5668, ["name"] = "Ignite the Fuel of Change", ["orderIndex"] = 15, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5668, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83206] = { ["id"] = 83206, ["name"] = "We Own the Streets", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83138, 83194, 83195, 83196, 83197, 83198, 83199, 83200, 83201, 83202, 83203, 83204, 83205, 83206, 83207, 85174, 85562, 85724, 85780, 86417 }, ["description"] = "The trade princes ain't exactly been fair to the goblins here, so this can't be just another cartel war. The crowd needs to know they ain't fighting for Bilgewater or Steamwheedle. They're fightin' for Undermine . We need someone who ain't a cartel big shot to help rile 'em up and keep 'em safe. Do whatever it takes to get them to the Gallagio and show these goblins this is their city.", ["objectivesText"] = "Rally the people of Undermine against Gallywix.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 232356, 232406, 232407, 232408, 232523 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 230268, ["x"] = 0.564, ["y"] = 0.675 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 225878, ["x"] = 0.564667, ["y"] = 0.445333 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.675 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 86417 }, ["questLines"] = { { ["id"] = 5668, ["name"] = "Ignite the Fuel of Change", ["orderIndex"] = 17, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5668, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83207] = { ["id"] = 83207, ["name"] = "My Top Gal", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83138, 83194, 83195, 83196, 83197, 83198, 83199, 83200, 83201, 83202, 83203, 83204, 83205, 83206, 83207, 85174, 85562, 85724, 85780, 86417 }, ["description"] = "We've got Gallywix backed against the wall. Seeing Undermine and its people he's kept under his thumb finally rising up. He thinks this \"Fixer\" of his will keep him safe. Let's show Gallywix, Nikki, and everyone else that things are different this time. <Gazlowe looks over the thingamajig he's just finished jury-rigging.> Watch this.", ["objectivesText"] = "Defeat Nikki the Fixer .", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 235516 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 225878, ["x"] = 0.564667, ["y"] = 0.445333 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 235238, ["x"] = 0.57, ["y"] = 0.446 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.564667, ["y"] = 0.445333 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83206 }, ["questLines"] = { { ["id"] = 5668, ["name"] = "Ignite the Fuel of Change", ["orderIndex"] = 18, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 264, ["title"] = "Undermine", ["questLineID"] = 5668, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83229] = { ["id"] = 83229, ["name"] = "Special Assignment: When the Deeps Stir", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80208, 80323, 81656, 81691, 81750, 81767, 82238, 82244, 82256, 82518, 82519, 82523, 82552, 82580, 83028, 83048, 83079, 83080, 83101, 83229, 83537, 83538, 83715, 83930, 84429 }, ["objectivesText"] = "Awakened Elementals defeated", ["rewardXP"] = 11765, ["starts"] = { { ["x"] = 0.487, ["y"] = 0.147, ["mapID"] = 2214 } }, ["ends"] = { { ["x"] = 0.487, ["y"] = 0.147, ["mapID"] = 2214 } }, ["coords"] = { ["mapID"] = 2214, ["x"] = 0.487, ["y"] = 0.147 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14795 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5588, ["name"] = "Ringing Deeps - World Quests / Repeatable", ["orderIndex"] = 21, ["flags"] = 0 } }, ["db2Objectives"] = { { ["text"] = "Awakened Elementals defeated", ["amount"] = 4, ["type"] = 0, ["objectID"] = 225898, ["orderIndex"] = 0 } }, ["db2LabelIDs"] = { 3549 }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214, ["db2QuestInfoID"] = 286, ["db2QuestInfoName"] = "Capstone World Quest" },
[83240] = { ["id"] = 83240, ["name"] = "The Theater Troupe", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 83240 }, ["description"] = "Since you're an honorary member of the theater troupe, <name>, what do you think about playing a part in our plays? No big parts--I don't want to upset the rest of the troupe by taking away their limelight. You know how they are. Are you available, say, once a week?", ["objectivesText"] = "Participate in the Theater Troupe event. Progress: The show must go on! And on. And on. We've been renewed for a permanent showing. For the earthen that means... well, it means we're all employed for a long time.", ["rewardItems"] = { 217011, 217012, 217013, 226263, 235151, 239128, 250763 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 200 }, { ["id"] = 2897, ["amount"] = 1000 } }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 214296, ["x"] = 0.564, ["y"] = 0.514 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 214296, ["x"] = 0.564, ["y"] = 0.514 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.514 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14776 } }, ["questType"] = "standard" },
[83247] = { ["id"] = 83247, ["name"] = "Suspicious Minds", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 83247, 83279, 83283 }, ["description"] = "For many years, the only non-Arathi we ever saw in Hallowfall were trying to kill us. Nerubians, shadow creatures, beasts. So, forgive me if I view your sudden arrival with suspicion. However, my better half would urge me to be more welcoming... and I want to try to be better. For her. Some of the salamanthers in Rumshackle have been bothering us. Kill them and bring me proof.", ["objectivesText"] = "Find 9 Salamanther Hearts in Rumshackle. Progress: Others may be satisfied with just your word that you have done what I'd ask. I am not.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["rewardItems"] = { 225179, 228435, 228436, 228437, 228438 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 25 }, { ["id"] = 2899, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 225879, ["x"] = 0.653, ["y"] = 0.415 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 225879, ["x"] = 0.653, ["y"] = 0.415 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.653, ["y"] = 0.415 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78658 }, ["questLines"] = { { ["id"] = 5628, ["name"] = "Suspicious Neighbors", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[83271] = { ["id"] = 83271, ["name"] = "There's Always Another Secret", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 79197, 79328, 79333, 79344, 82153, 83271, 83286, 83315 }, ["description"] = "After me da' did whatever he did, the titans' machines are back online--even the ones here in Dornogal. Dagran was havin' enough fun with Brinthe askin' her a thousand questions, but now he's helpin' her sort through the Archive. An' now he wants your help. He was too excited to tell me why, but he wanted ye to meet him in the Archive.", ["objectivesText"] = "Check in on Dagran Thaurissan II and Brinthe in the Archive in Dornogal.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 214917, ["x"] = 0.316667, ["y"] = 0.600667 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 214917, ["x"] = 0.316667, ["y"] = 0.600667 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.316667, ["y"] = 0.600667 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questTurnInID"] = 214917, ["questType"] = "standard", ["sourceQuests"] = { 79328, 82153 }, ["questLines"] = { { ["id"] = 5551, ["name"] = "Against the Current", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5551, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2367 },
[83274] = { ["id"] = 83274, ["name"] = "An Original Path Through Time", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 1637, ["mapID"] = 71, ["storyline"] = { 83274 }, ["description"] = "Old warriors keep spinning tales about how things were so much tougher around Azeroth back in their day. I bet they would say you're not tough enough to last 10 minutes in their world. Think you're tough enough to find out? How 'bout you show me.", ["objectivesText"] = "Complete 5 Timewalking dungeons. Progress: You're not givin' up, are ya?", ["rewardItems"] = { 212446, 220305, 225582, 226194, 233014 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 1 }, { ["id"] = 3100, ["amount"] = 3 } }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 223884, ["x"] = 0.628, ["y"] = 0.502 }, { ["mapID"] = 84, ["npcID"] = 234555, ["x"] = 0.560667, ["y"] = 0.19 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 223884, ["x"] = 0.628, ["y"] = 0.502 }, { ["mapID"] = 84, ["npcID"] = 234555, ["x"] = 0.560667, ["y"] = 0.19 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 71, 84 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 4063 } },
[83275] = { ["id"] = 83275, ["name"] = "Gear Enchanting", ["level"] = 68, ["requiredLevel"] = 68, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83275 }, ["description"] = "Hello, outlander! I've heard of your exploits since your dramatic arrival on our shores. We earthen welcome your aid. I can teach you how to enchant your gear with resources from my land. To defeat our enemies, every bit of power helps.", ["objectivesText"] = "Complete the item enchantment tutorial by enchanting any ring using the enchantment given from Ellerdin , Enchant Ring - Glimmering Haste . Progress: The enchantment and ring I gave you are fitting for each other.", ["rewardGold"] = 154900, ["rewardXP"] = 4625, ["rewardItems"] = { 223657, 223663, 223666, 223669 }, ["rewardChoices"] = { 223657, 223663, 223666, 223669 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226287, ["x"] = 0.518, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226287, ["x"] = 0.518, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard" },
[83276] = { ["id"] = 83276, ["name"] = "Saving Private Spindle", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 83276 }, ["description"] = "One of my weave-rats has failed to check in for an unusually long time. I sent Spindle to retrieve information we could use against one of Ansurek's favored wretches, but she has not returned from her assignment. Meesk the Venomtongue is a wretch and a sycophant, but he is dangerous all the same. While I have much trust in my dear Spindle 's abilities, I fear what a malefactor such as Meesk would do to one of my little ones should he find them. Find Spindle . Make sure she is well.", ["objectivesText"] = "Find Spindle in the High Hollows. Progress: <All of Spindle 's eyes widen with both relief and embarrassment at the sight of you.>", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 207471, ["x"] = 0.556, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 226019, ["x"] = 0.878, ["y"] = 0.592 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 2213, 2255 }, ["zone"] = { 14753 } }, ["questType"] = "standard" },
[83277] = { ["id"] = 83277, ["name"] = "Personal Pilfering", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14753, ["mapID"] = 2213, ["storyline"] = { 83277 }, ["description"] = "<The little spider looks around the room, each of her eyes narrowing. You recall The Weaver telling you to retrieve evidence to blackmail Meesk. But it appears as though ransacking Meesk's storage is now personal for Spindle .>", ["objectivesText"] = "Find 3 pieces of Incriminating Evidence in Meesk's Retreat. Progress: Well, my morsel? Did you find anything of note?", ["rewardGold"] = 292100, ["rewardXP"] = 11765, ["rewardItems"] = { 225344 }, ["rewardCurrencies"] = { { ["id"] = 3056, ["amount"] = 35 }, { ["id"] = 3056, ["amount"] = 750 } }, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 226019, ["x"] = 0.878, ["y"] = 0.592 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 207471, ["x"] = 0.556, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.878, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 2213, 2255 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["sourceQuests"] = { 83276 } },
[83278] = { ["id"] = 83278, ["name"] = "Hillhelm Family: A Lost Shoe", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 83278 }, ["description"] = "<A shoe in the style worn by members of the Hillhelm family. Maybe Aliya Hillhelm can shed some light on it.>", ["objectivesText"] = "Deliver The Lost Shoe to Aliya Hillhelm at Hillhelm Stead. Provided item:", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 225336 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 40 }, { ["id"] = 2899, ["amount"] = 200 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 206528, ["x"] = 0.612, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3718 }, ["startItems"] = { 225336 } },
[83279] = { ["id"] = 83279, ["name"] = "Prove One's Mettle", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 83247, 83279, 83283 }, ["description"] = "Yes, you helped us out with these pests, but it is not enough. I need more. One of the areas near our town has been overrun by shadow. If you are truly not being controlled by your... strange background, you would have no problem destroying the source of this danger, would you?", ["objectivesText"] = "Defeat the Coalesced Iniquity in Rumshackle. Progress: If you are truly here to help the Arathi, you would have no problem with what I am asking of you.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 225879, ["x"] = 0.653, ["y"] = 0.415 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 225879, ["x"] = 0.653, ["y"] = 0.415 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.653, ["y"] = 0.415 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 83247 }, ["questLines"] = { { ["id"] = 5628, ["name"] = "Suspicious Neighbors", ["orderIndex"] = 2, ["flags"] = 1 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[83282] = { ["id"] = 83282, ["name"] = "Hillhelm Family: A Clutch of Eggs", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 83282 }, ["description"] = "<A clutch of chicken eggs , they must have come from a nearby farm. Maybe Aliya Hillhelm can shed some light on it.>", ["objectivesText"] = "Deliver The Clutch of Eggs to Aliya Hillhelm at Hillhelm Stead. Provided item:", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 225339 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 40 }, { ["id"] = 2899, ["amount"] = 200 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 206528, ["x"] = 0.612, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3718 }, ["startItems"] = { 225339 } },
[83283] = { ["id"] = 83283, ["name"] = "For Morale", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 83247, 83279, 83283 }, ["description"] = "Please excuse my husband's rudeness. When we signed up for our expedition, we expected to be away from our families for a few years at worst. Instead, we settled here as we guard against--well, against the end, against Renilash. Who knows when our watch will end? I've been stockpiling a cache of wine from our church vineyards to share with everyone when tensions got high. My hiding place, Rumshackle, has been overrun by creatures. Can you get the wine for me?", ["objectivesText"] = "Retrieve 6 barrels of Imperial Brut from Rumshackle. Progress: Imagine twenty Arathi huddling under the safety of a single light for ten years. Imagine they're waiting for a chance to let their hair down with a good drink with their comrades. Now imagine how they'll feel once they hear the wine is gone. ...please hurry.", ["rewardGold"] = 309800, ["rewardXP"] = 10190, ["rewardItems"] = { 225340 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 225857, ["x"] = 0.68, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 225857, ["x"] = 0.68, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.68, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78658 }, ["questLines"] = { { ["id"] = 5628, ["name"] = "Suspicious Neighbors", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[83285] = { ["id"] = 83285, ["name"] = "The Ancient Scroll", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 83285 }, ["description"] = "A haze seems to obscure the details of the scroll at first. As you concentrate on making out the scroll's features, the haze briefly dissipates revealing a pristine scroll made of the finest vellum, with a seal that looks so fresh the wax doesn't even seem set yet. In a blink, the scroll feels dangerously brittle, and the seal so delicate it could crack at any moment. As the haze begins to form again, you see the scroll shimmer through all possible points between these two extremes.", ["rewardGold"] = 276200, ["rewardXP"] = 200, ["rewardItems"] = { 129747, 129928, 133377, 133378, 143776, 167921, 167922, 187611, 225348 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 200 }, { ["id"] = 1166, ["amount"] = 500 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 223885, ["x"] = 0.626, ["y"] = 0.504 }, { ["mapID"] = 84, ["npcID"] = 234556, ["x"] = 0.558, ["y"] = 0.186 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.626, ["y"] = 0.504 }, ["mapCandidates"] = { ["npc"] = { 71, 84 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Nightborne", ["startItems"] = { 225348 } },
[83286] = { ["id"] = 83286, ["name"] = "What's Hidden Beneath Dornogal", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 13390, ["mapID"] = 2367, ["storyline"] = { 79197, 79328, 79333, 79344, 82153, 83271, 83286, 83315 }, ["description"] = "Strange. The mechanism and console here is receiving power, but I cannot initialize the reboot sequence. Dagran's query may have to wait. I have been able to ascertain the facility's designation: the \"Vault of Memory.\" This leads me to believe that my original theory was correct. It is connected to the Archive in Dornogal. Perhaps, since both of you are familiar with this type of titan installation, you may have a better chance bringing it fully online.", ["objectivesText"] = "Restart the central mainframe in the Vault of Memory in Dornogal. Progress: Take your time. It has been here for millennia. I am sure it is not going anywhere.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["npcID"] = 226040, ["x"] = 0.5, ["y"] = 0.598, ["zoneID"] = 13390 } }, ["ends"] = { { ["npcID"] = 226040, ["x"] = 0.5, ["y"] = 0.598, ["zoneID"] = 13390 } }, ["coords"] = { ["x"] = 0.5, ["y"] = 0.598, ["source"] = "quest_giver", ["zoneID"] = 13390 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13390 } }, ["questType"] = "standard", ["sourceQuests"] = { 83271 }, ["questLines"] = { { ["id"] = 5551, ["name"] = "Against the Current", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5551, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2367 },
[83306] = { ["id"] = 83306, ["name"] = "Where the Wild Things Camp", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 83306 }, ["description"] = "Some of my people found a few haranir setting up one of their camps to the southwest. They were missing some vital supplies, so my people offered to help out. However, I worry about how they're all getting along over there. Could you check in on them? Make sure we're being good hosts to the haranir... and that nobody has inadvertently offended anyone. Please.", ["objectivesText"] = "Meet Orweyna at Wildcamp Ul'ar.", ["rewardGold"] = 30900, ["rewardXP"] = 1325, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 211409, ["x"] = 0.592, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 220595, ["x"] = 0.446, ["y"] = 0.664 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 78384 }, ["nextQuests"] = { 80563, 80564 } },
[83315] = { ["id"] = 83315, ["name"] = "Preparing for the Unknown", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 79197, 79328, 79333, 79344, 82153, 83271, 83286, 83315 }, ["description"] = "This will be a long process. Longer, I fear, than Dagran can stay here in the Isles. But perhaps... There are many titan relics I can use as \"keys\" to unlocking information in the mainframe or to repair it. That may make the process go more quickly. Only time will tell. You have helped us enough, <name>. Go back to Moira and tell her what we have discovered.", ["objectivesText"] = "Return to Moira Thaurissan in Dornogal.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["x"] = 0.499, ["y"] = 0.608, ["mapID"] = 2367, ["npcID"] = 226040 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 214917, ["x"] = 0.316667, ["y"] = 0.600667 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.316667, ["y"] = 0.600667 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questGiverID"] = 226040, ["questType"] = "standard", ["sourceQuests"] = { 83286 }, ["questLines"] = { { ["id"] = 5551, ["name"] = "Against the Current", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5551, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[83321] = { ["id"] = 83321, ["name"] = "Strange Bats", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 83321 }, ["description"] = "Hey. Her ladyship has a lead on some really strange bat that was flying around the Wormlands. The spies reported it behaving more like a person than a bat. We think we might have a druid out there, but it ain't revealin' itself to the nerubians on purpose. You have one of those faces that make people hesitate before punching. Head out there and take a look.", ["objectivesText"] = "Investigate a possible druid sighting.", ["rewardGold"] = 28090, ["rewardXP"] = 1325, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 223754, ["x"] = 0.558, ["y"] = 0.436 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 211652, ["x"] = 0.422, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.436 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 78233 }, ["nextQuests"] = { 78897, 78898, 78901 } },
[83322] = { ["id"] = 83322, ["name"] = "The Dawnbreaker: The Christening", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 83322 }, ["description"] = "The flagship of the Arathi armada is the Dawnbreaker. She is a marvel of Arathi engineering and faith in the Sacred Flame. Her presence in the Hallowfall sky will help us push back the nerubians when next they dare launch another assault on our lands. As someone who has helped us so much in the past, you are cordially invited to the christening ceremony of the Dawnbreaker. If you could make sure it goes off without a hitch, you will have my personal gratitude.", ["objectivesText"] = "Help the christening ceremony in the Dawnbreaker dungeon succeed. Progress: The Dawnbreaker will cause problems for the nerubians once she is active. It is very important everything goes off without a hitch.", ["rewardGold"] = 1239200, ["rewardXP"] = 23530, ["rewardItems"] = { 226141 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 25 }, { ["id"] = 2899, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 215335, ["x"] = 0.405, ["y"] = 0.508 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 215335, ["x"] = 0.405, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.405, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "dungeon" },
[83324] = { ["id"] = 83324, ["name"] = "A Silken Thread", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 83324 }, ["description"] = "You looking for work or something? <Linny squints her eyes at you.> If you're just hanging around I've heard some whispers from the capital. An associate of the Weaver is looking into some business in the Silken Ward. The new ward is supposed to be a fresh start for citizens of the capital but the Queen's Pale Weavelashers have been treating it like a military camp. This isn't sittin' well with the populace. Meet with a nerubian named Sum'latha outside the ward. She can fill you in on the details.", ["objectivesText"] = "Meet with Sum'latha at the Silken Ward.", ["rewardGold"] = 30900, ["rewardXP"] = 1325, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 223754, ["x"] = 0.558, ["y"] = 0.436 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 221948, ["x"] = 0.514, ["y"] = 0.638 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.436 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 78256 }, ["nextQuests"] = { 81928 } },
[83325] = { ["id"] = 83325, ["name"] = "Bountiful Beetles", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 79114, 79115, 79117, 79118, 79119, 79120, 79121, 79122, 79123, 83325 }, ["description"] = "General Anub'azal has great plans in motion for the swarmery, Rak-Ush. He intends to return it to working order, to support his war campaign. However... I have my reservations about the two he left in charge. Kish'nal seems to have a good head on his shoulders, but Vix'aron? Volatile is an understatement. They may require some... prodding. Seek out Kish'nal at Rak-Ush and follow up on Anub'azal's orders.", ["objectivesText"] = "Speak with Kish'nal in Rak-Ush.", ["rewardGold"] = 29200, ["rewardXP"] = 1325, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 224729, ["x"] = 0.558, ["y"] = 0.422 }, { ["mapID"] = 2255, ["npcID"] = 229184, ["x"] = 0.558, ["y"] = 0.422 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 214359, ["x"] = 0.755, ["y"] = 0.815 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 78384, 79573 }, ["nextQuests"] = { 79119 }, ["questLines"] = { { ["id"] = 5648, ["name"] = "Rak-Ush", ["orderIndex"] = 0, ["flags"] = 1 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[83326] = { ["id"] = 83326, ["name"] = "The Final Candle", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78827, 78860, 78879, 78900, 78918, 83326 }, ["description"] = "You are good candle-taker. We have one last job for you, your waxiness! One more job! Then no more sticky business. BIG candle in basement. Stone-ones use it to keep rats away from their honey juice. We no rats! We kobo--ooolds. Nothing rhymes with kobolds, hm. Get us big candle!", ["objectivesText"] = "Steal the final candle for the suspicious vent in the Gundargaz Inn. Progress: Candles! Candles! Candles!", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["rewardItems"] = { 220156 }, ["starts"] = { { ["npcID"] = 413694, ["x"] = 0.481, ["y"] = 0.32, ["mapID"] = 2214 } }, ["ends"] = { { ["npcID"] = 413694, ["x"] = 0.481, ["y"] = 0.32, ["mapID"] = 2214 } }, ["coords"] = { ["x"] = 0.481, ["y"] = 0.32, ["source"] = "quest_giver", ["mapID"] = 2214 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 78860 }, ["questLines"] = { { ["id"] = 5656, ["name"] = "Exploring Gundargaz", ["orderIndex"] = 8, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[83328] = { ["id"] = 83328, ["name"] = "The Analysis Interface", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredRaces"] = { 85 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["mapID"] = 2322, ["storyline"] = { 79200, 79201, 79202, 79203, 79204, 81886, 81887, 81888, 81889, 83328 }, ["description"] = "This is the Analysis Interface. In order to ensure our primary programming remained intact, these consoles were installed with a series of inquiries to assess the memory matrix of the newly awakened. Although Dawn will encourage you to answer in any way that you please--I... well, I hope you'll answer truthfully. Proceed when ready.", ["objectivesText"] = "Complete the Analyzing Sequence in the Analysis Interface.", ["rewardGold"] = 17450, ["rewardXP"] = 1415, ["starts"] = { { ["x"] = 0.626, ["y"] = 0.492, ["mapID"] = 2322, ["npcID"] = 221891 } }, ["ends"] = { { ["x"] = 0.626, ["y"] = 0.492, ["mapID"] = 2322, ["npcID"] = 221891 } }, ["coords"] = { ["mapID"] = 2322, ["x"] = 0.626, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questGiverID"] = 221891, ["questTurnInID"] = 221891, ["questType"] = "standard", ["sourceQuests"] = { 79200 }, ["questLines"] = { { ["id"] = 5593, ["name"] = "New Awakenings", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2739, ["db2PoiUiMapID"] = 2322 },
[83331] = { ["id"] = 83331, ["name"] = "Preserve and Pretend", ["level"] = 73, ["requiredLevel"] = 73, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83331 }, ["description"] = "Chive dig for history. You help find? Got history detector from goblin. Said it finds history underground! You use. Chive dig.", ["objectivesText"] = "Help find places to dig for \"historical objects\" by using the goblin \"history detector\".", ["rewardGold"] = 309800, ["rewardXP"] = 9920, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 180 }, { ["id"] = 2815, ["amount"] = 205 }, { ["id"] = 2902, ["amount"] = 500 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 226255, ["x"] = 0.562, ["y"] = 0.32 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 226255, ["x"] = 0.562, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["sourceQuests"] = { 80434 } },
[83333] = { ["id"] = 83333, ["name"] = "Gearing Up for Trouble", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 82946, 83333 }, ["description"] = "Greetings friend, The machine is once again in disrepair and requires restoration. I am in need of your expertise to successfully perform maintenance. A reward shall be provided for well-executed assistance.", ["objectivesText"] = "Complete 20 waves of the Awakening the Machine event. Progress: Status report?", ["rewardGold"] = 619600, ["rewardItems"] = { 225767, 226273, 239121, 250765 }, ["rewardCurrencies"] = { { ["id"] = 3100, ["amount"] = 1 }, { ["id"] = 3100, ["amount"] = 8 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 216164, ["x"] = 0.448667, ["y"] = 0.352 }, { ["mapID"] = 2214, ["npcID"] = 217128, ["x"] = 0.453, ["y"] = 0.32 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 216164, ["x"] = 0.448667, ["y"] = 0.352 }, { ["mapID"] = 2214, ["npcID"] = 217128, ["x"] = 0.453, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.448667, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5711, ["name"] = "Ringing Deeps - Weekly Quests", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214, ["db2QuestHubAreaPoiID"] = 7911 },
[83334] = { ["id"] = 83334, ["name"] = "The Wealth of an Empire", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 83334 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 2000 } }, ["starts"] = { { ["npcID"] = 213145, ["x"] = 0.412, ["y"] = 0.53, ["mapID"] = 2215 } }, ["ends"] = { { ["npcID"] = 213145, ["x"] = 0.412, ["y"] = 0.53, ["mapID"] = 2215 } }, ["coords"] = { ["x"] = 0.412, ["y"] = 0.53, ["source"] = "quest_giver", ["mapID"] = 2215 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard" },
[83335] = { ["id"] = 83335, ["name"] = "Wanted: The Boroughbreaker", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 83335, 83336, 83337, 83338, 83339 }, ["description"] = "<This note is nailed into the post with a small chitinous plate.> For crimes impeding the Edicts of Dornogal, the Council has deemed a reward be yielded to any who slays the chitinous beast known as Stik'kar. A sample of Stik'kar's armor is attached. If you are unable to damage it, you are urged to carry on in your duties and leave this task for another.", ["objectivesText"] = "Slay Boroughbreaker Stik'kar in the Isle of Dorn .", ["rewardGold"] = 619600, ["rewardXP"] = 11895, ["rewardItems"] = { 227916, 227917, 227918, 227919 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 5 }, { ["id"] = 2897, ["amount"] = 100 } }, ["starts"] = { { ["x"] = 0.553, ["y"] = 0.559, ["mapID"] = 2248, ["objectID"] = 454463 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226761, ["x"] = 0.54, ["y"] = 0.2 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.2 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5635, ["name"] = "Threats on the Isle of Dorn", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[83336] = { ["id"] = 83336, ["name"] = "The Earthwound", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 83335, 83336, 83337, 83338, 83339 }, ["description"] = "<Etterca grumbles as you approach.> Ground is shaking. 'Tis no good. Troubles are awakening the elements again. Stirs rot in them. Danger to us all. Bring them to heel and give its heart here. Only then the earth can begin to heal. Only then can Etterca do her duties.", ["objectivesText"] = "Acquire the Broken Stoneheart from Roth the Earthwound in the Isle of Dorn . Progress: <Etterca grumbles and stares at you blankly.>", ["rewardGold"] = 619600, ["rewardXP"] = 11895, ["rewardItems"] = { 225674 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 5 }, { ["id"] = 2897, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 226750, ["x"] = 0.555, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 226750, ["x"] = 0.555, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5635, ["name"] = "Threats on the Isle of Dorn", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[83337] = { ["id"] = 83337, ["name"] = "Stormscarred", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 83335, 83336, 83337, 83338, 83339 }, ["description"] = "Take a look around this beautiful town. What do you see? Ranchers 'n' their mosswools. But where is this rancher's flock? In the guts of a beast, they are. Stormscar they call 'im. Stormscar , whose howl is as the thunder. Whose bite is lightning. Whose belly is full of my life's work. I came here to buy weapons and all we have is ranching equipment. You look strong. Would you put an end to Stormscar 's reign in our pastures?", ["objectivesText"] = "Slay Stormscar in the pastures near Rambleshire in the Isle of Dorn . Progress: Have you done it yet?", ["rewardGold"] = 619600, ["rewardXP"] = 11895, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 5 }, { ["id"] = 2897, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 226792, ["x"] = 0.584, ["y"] = 0.282 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 226792, ["x"] = 0.584, ["y"] = 0.282 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.282 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5635, ["name"] = "Threats on the Isle of Dorn", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[83338] = { ["id"] = 83338, ["name"] = "The Mage Slayer", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 83335, 83336, 83337, 83338, 83339 }, ["description"] = "I confess I have come here with reason. There is one entity that may be out there still that cannot be allowed its freedom. A prisoner from the Violet Hold that we begrudgingly know as the Mage Slayer. I had come to request aid from these people, but they are farmers and ranchers. I hope you are better equipped for a challenge. Seek out this fiend and put an end to its existence.", ["objectivesText"] = "Slay Mage Slayer Phytethil near Rambleshire in the Isle of Dorn .", ["rewardGold"] = 601600, ["rewardXP"] = 11895, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 5 }, { ["id"] = 2897, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 226791, ["x"] = 0.582, ["y"] = 0.272 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 226791, ["x"] = 0.582, ["y"] = 0.272 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.582, ["y"] = 0.272 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5635, ["name"] = "Threats on the Isle of Dorn", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[83339] = { ["id"] = 83339, ["name"] = "The Spirebreaker", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 83335, 83336, 83337, 83338, 83339 }, ["description"] = "We are no strangers to nerubian attacks. The Kirin Tor is well equipped to handle such a threat. Dalaran... Was equipped. I cannot fend off all of this town's foes, but you might be able to. I spotted an ambush near the road on the way here. An all too familiar tactic of an all too familiar foe. Go spring the trap and slay the monster that lurks below.", ["objectivesText"] = "Slay Anub'esska on the road near Rambleshire in the Isle of Dorn . Progress: Are they safe now?", ["rewardGold"] = 619600, ["rewardXP"] = 11895, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 5 }, { ["id"] = 2897, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 226791, ["x"] = 0.582, ["y"] = 0.272 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 226791, ["x"] = 0.582, ["y"] = 0.272 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.582, ["y"] = 0.272 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5635, ["name"] = "Threats on the Isle of Dorn", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[83347] = { ["id"] = 83347, ["name"] = "Emissary of War", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83347 }, ["description"] = "Are you up for a real challenge? Delve into the darkest places and soar to the highest heights while upping the challenge. By pressing ourselves to the extreme we can truly test our skills.", ["objectivesText"] = "Complete 4 dungeons on Mythic difficulty. Progress: By pressing ourselves to the extreme we can truly test our skills.", ["rewardGold"] = 70225, ["rewardXP"] = 25, ["rewardItems"] = { 226194, 234731, 247820, 250117 }, ["rewardCurrencies"] = { { ["id"] = 3100, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "dungeon" },
[83357] = { ["id"] = 83357, ["name"] = "The Very Best", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83357 }, ["description"] = "The bond between us and our machines is much like the one others have with their pets. You must be in harmony with your companions in order to accomplish great things! Show me that you can work as a team with your pets. Defeat your enemies with their assistance!", ["objectivesText"] = "Defeat 5 players through Find Battle with a team of level 25 pets. Progress: You must be in harmony with your companions in order to accomplish great things!", ["rewardItems"] = { 122457 }, ["rewardChoices"] = { 122457 }, ["rewardCurrencies"] = { { ["id"] = 3100, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard" },
[83358] = { ["id"] = 83358, ["name"] = "The Arena Calls", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83358 }, ["description"] = "Have you proven your mettle in the arena? Win enough battles, and we might even find your tales worthy of storage in the Archives one day.", ["objectivesText"] = "Win 10 Arena Skirmish battles. Progress: Do not let your guard down in the arena!", ["rewardCurrencies"] = { { ["id"] = 1602, ["amount"] = 110 }, { ["id"] = 1792, ["amount"] = 2000 }, { ["id"] = 3100, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard" },
[83359] = { ["id"] = 83359, ["name"] = "A Shattered Path Through Time", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83359, 83360, 83362, 83363, 83364, 83365, 88805, 92649 }, ["description"] = "One of your people brought me a strange tale of the cataclysm that tore Azeroth apart. In your lands, this was felt most direly due to the machinations of the wicked creature Deathwing. Travel through space and time and engage with him and other threats.", ["objectivesText"] = "Defeat 5 Timewalking raid bosses or dungeons. Progress: Only the titans should reshape the world.", ["rewardItems"] = { 127853, 226193, 226194, 247821, 250116 }, ["rewardCurrencies"] = { { ["id"] = 3100, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1416, ["name"] = "Bonus Event Holiday Quests", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[83360] = { ["id"] = 83360, ["name"] = "A Fel Path Through Time", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83359, 83360, 83362, 83363, 83364, 83365, 88805, 92649 }, ["description"] = "I have heard tales of an entire Legion of threats that lurks along the paths of space and time. Defeat them and bring me back news of their demise.", ["objectivesText"] = "Complete 5 Timewalking dungeons. Progress: Some of my people may see the arrival of the outlanders as an invasion, but I am glad it was you who landed on our shoes, and not the Burning Legion.", ["rewardItems"] = { 226194 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1416, ["name"] = "Bonus Event Holiday Quests", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[83362] = { ["id"] = 83362, ["name"] = "A Shrouded Path Through Time", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83359, 83360, 83362, 83363, 83364, 83365, 88805, 92649 }, ["description"] = "One of your people brought me tales of Pandaria! I would very much like to fly through those skies one day. Walk through mist and time and bring back news of your deeds.", ["objectivesText"] = "Complete 5 Timewalking dungeons. Progress: I wonder what it is like to be covered in fur like a pandaren. I hear there are many floating places to visit in those lands. May they all stay afloat.", ["rewardItems"] = { 226194, 234729, 247820, 247821, 250116 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1416, ["name"] = "Bonus Event Holiday Quests", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[83363] = { ["id"] = 83363, ["name"] = "A Burning Path Through Time", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83359, 83360, 83362, 83363, 83364, 83365, 88805, 92649 }, ["description"] = "Your people have brought me tales of a Dark Portal wherein lie many enemies and challenges. I would like to hear more of these tales. Travel through time and space to this outlandish place, vanquish its foes, and bring me news of their demise.", ["objectivesText"] = "Defeat 5 Timewalking raid bosses or dungeons. Progress: Some of my people may see the arrival of the outlanders as an invasion, but I am glad it was you who landed on our shoes, and not the Burning Legion.", ["rewardItems"] = { 127853, 226193, 226194, 247820 }, ["rewardCurrencies"] = { { ["id"] = 3100, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1416, ["name"] = "Bonus Event Holiday Quests", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[83364] = { ["id"] = 83364, ["name"] = "A Savage Path Through Time", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83359, 83360, 83362, 83363, 83364, 83365, 88805, 92649 }, ["description"] = "Ever since your city fell out of the sky, I have learned more of this world's history and the challenges that heroes like yourself have faced. Learning from the past is how we ensure our future. Walk through time to a past limed with hellfire to defeat those threats once more and bring those lessons forward.", ["objectivesText"] = "Complete 5 Timewalking dungeons.", ["rewardItems"] = { 226194, 234729, 247820, 247821 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1416, ["name"] = "Bonus Event Holiday Quests", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[83365] = { ["id"] = 83365, ["name"] = "A Frozen Path Through Time", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83359, 83360, 83362, 83363, 83364, 83365, 88805, 92649 }, ["description"] = "Ever since your city fell out of the sky, I have learned more of this world's history and the challenges that heroes like yourself have faced. Learning from the past is how we ensure our future. Walk through time to the frozen past, defeat those threats once more, and bring those lessons forward.", ["objectivesText"] = "Defeat 5 Timewalking raid bosses or dungeons. Progress: Much has happened in the greater world while we worked in this place. I hear you had a hand in quite a bit of those tales.", ["rewardItems"] = { 127853, 226193, 226194, 247820, 247821 }, ["rewardCurrencies"] = { { ["id"] = 3100, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 1416, ["name"] = "Bonus Event Holiday Quests", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[83366] = { ["id"] = 83366, ["name"] = "The World Awaits", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83366 }, ["description"] = "Perhaps we can turn your tragedy into a mutually beneficial experience for us both. There is much you can do to be of assistance to the earthen. Lend a hand where you can.", ["objectivesText"] = "Complete 10 World Quests in Khaz Algar. Progress: My people face a wide range of difficulties these days, as do yours. We can make the best of what's befallen us both.", ["rewardItems"] = { 2815, 3056, 255881 }, ["rewardChoices"] = { 2815, 3056, 255881 }, ["rewardCurrencies"] = { { ["id"] = 3100, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226919, ["x"] = 0.465, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard" },
[83417] = { ["id"] = 83417, ["name"] = "Out-laws", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83417, 83418, 83419, 83420, 83421, 85438, 87008 }, ["description"] = "We're a traditional goblin family, an' my sweetie's intended's from one too. Young people start work on a contract, an' buy each other out when they get hitched so they can get time off. I've got the cash for my sweetie to buy her intended's contract out, but it would be... embarrassin' if her intended didn't have the moolah for my perfect peach's contract, ya know? Go talk to that kid and make sure he's set for the big day. And if he's not? Fix it.", ["objectivesText"] = "Talk to Vrizek and make sure he has the Contract Fee. Progress: Everything needs to be perfect for my girl's big day. Or else.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 226518, ["x"] = 0.2595, ["y"] = 0.4265 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226518, ["x"] = 0.2595, ["y"] = 0.4265 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.2595, ["y"] = 0.4265 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 85438 }, ["questLines"] = { { ["id"] = 5642, ["name"] = "The Perfect Wedding", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83418] = { ["id"] = 83418, ["name"] = "The Perfect Coat", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83417, 83418, 83419, 83420, 83421, 85438, 87008 }, ["description"] = "My princess deserves only the very best Azeroth has to offer--and that goes double for her clothes. How else are people supposed'ta know how incredible I think she is? I got a guy who's hooked me up with an amazin' and rare pelt for my little girl to turn into a fabulous coat. Go meet the guy and bring back the goods. And you better not get anythin' on it.", ["objectivesText"] = "Acquire the fabulously feathered coat material. Progress: Tick tock!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 225971 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 226518, ["x"] = 0.2595, ["y"] = 0.4265 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226518, ["x"] = 0.2595, ["y"] = 0.4265 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.2595, ["y"] = 0.4265 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83417 }, ["questLines"] = { { ["id"] = 5642, ["name"] = "The Perfect Wedding", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83419] = { ["id"] = 83419, ["name"] = "The Perfect Guest List", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83417, 83418, 83419, 83420, 83421, 85438, 87008 }, ["description"] = "The perfect weddin' has the perfect guest list! But I'm still waiting on some RSVPs. Papa said he'd make sure they showed up, so that means you gotta remind them they'd love to come to my weddin'. It's gonna be the biggest bash this town has ever seen! Why wouldn't they want to come? We're family! Mostly. Anyway, get everyone on this list to agree to come to my weddin'. Remind them Papa said \"or else.\"", ["objectivesText"] = "Get positive RSVPs from the remaining guests. Progress: You talk to all my slacker relatives yet? I have to organize the tables.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 226522, ["x"] = 0.255, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226522, ["x"] = 0.255, ["y"] = 0.418 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.255, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 85438 }, ["questLines"] = { { ["id"] = 5642, ["name"] = "The Perfect Wedding", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83420] = { ["id"] = 83420, ["name"] = "Catering to Perfection", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83417, 83418, 83419, 83420, 83421, 85438, 87008 }, ["description"] = "My perfect day needs the perfect food! I've been looking at things on Gobstagram, and Chef Hardslice is my one and only choice for catering. Papa promised I'd have the best, and he's good to his word! I need you to make sure that everything on my menu makes it to the table for picture perfection. Everyone needs to see how fabulous my wedding is. Ahh! I am so excited! I can't wait to see Chef Hardslice 's creations on my table at my wedding!", ["objectivesText"] = "Speak with Chef Hardslice and obtain missing ingredients. Progress: Isn't Chef Hardslice a genius?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 226192 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 226522, ["x"] = 0.255, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226522, ["x"] = 0.255, ["y"] = 0.418 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.255, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83419 }, ["questLines"] = { { ["id"] = 5642, ["name"] = "The Perfect Wedding", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83421] = { ["id"] = 83421, ["name"] = "The Perfect Wedding", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83417, 83418, 83419, 83420, 83421, 85438, 87008 }, ["description"] = "I hired some goons to crash the wedding. Only the best weddings get crashed, right? But, I don't want to lose my deposit on this here venue. So, I need you to stop my crashers from getting too crashy, ya know?", ["objectivesText"] = "Stop the wedding crashers from doing too much damage to the venue. Progress: Stop those goons from doing too much damage, or I'll take my deposit outta your hide!", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 232736, 232737 }, ["rewardChoices"] = { 232736, 232737 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 25 }, { ["id"] = 3008, ["amount"] = 10 }, { ["id"] = 3118, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 226518, ["x"] = 0.2595, ["y"] = 0.4265 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226518, ["x"] = 0.2595, ["y"] = 0.4265 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.2595, ["y"] = 0.4265 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83418, 83420 }, ["questLines"] = { { ["id"] = 5642, ["name"] = "The Perfect Wedding", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83432] = { ["id"] = 83432, ["name"] = "The Rookery", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83432 }, ["description"] = "My contacts around Dornogal have told me to keep this a secret, but I trust you mainly because I need someone to do the job. We have a problem within the Rookery's walls--a skardyn outbreak. I need someone to clear the Rookery of skardyn, find the source of the outbreak, and drop the boulder on it. Once you complete the mission, come back to me for your reward. And remember... this stays between us.", ["objectivesText"] = "Biergoth wants you to enter The Rookery and put an end to the skardyn threat. Progress: Back so soon? Good news, I hope?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 2899, 2902, 237014 }, ["rewardChoices"] = { 2899, 2902, 237014 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226623, ["x"] = 0.465333, ["y"] = 0.483333 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226623, ["x"] = 0.465333, ["y"] = 0.483333 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.465333, ["y"] = 0.483333 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "dungeon" },
[83436] = { ["id"] = 83436, ["name"] = "Cinderbrew Meadery", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83436 }, ["description"] = "Word has come from a contact of mine named Wenbrandt. You may have heard of him. He runs the Cinderbrew Meadery. He says that goblins affiliated with an organization calling itself Venture Co. are trying to take over the meadery. We cannot have that. I need you to get into the meadery and remove that threat. Cinderbrew is an earthen product and should be under earthen control. Wenbrandt will teach them this lesson--but until then, I will count on you to finish the job.", ["objectivesText"] = "Biergoth wants you to remove the Venture Co. from the Cinderbrew Meadery. Progress: Any news are better than no news at all. Do not keep me waiting. Unlike the mountains, my patience is like that of a landslide.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 2815, 2899, 2902, 3056, 224784, 229354, 237014 }, ["rewardChoices"] = { 2815, 2899, 2902, 3056, 237014 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226623, ["x"] = 0.465333, ["y"] = 0.483333 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226623, ["x"] = 0.465333, ["y"] = 0.483333 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.465333, ["y"] = 0.483333 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "dungeon" },
[83442] = { ["id"] = 83442, ["name"] = "Tossed and Torqued", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83442, 83445, 83446 }, ["description"] = "All my notes. My plans! <Snap is shaking with anger.> I just know it was Mite Sparkcog who tossed my apartment. He's my work rival and probably wanted my newest invention for himself--the Smellersweller 5000! It's an attachment for the grills we design. I'd just finished the schematic for our boss when I stepped out for some grub. By the time I got back... Maybe he didn't find it. Help me look first, then we can deal with Mite.", ["objectivesText"] = "Search Snap Vellumgrease 's apartment for the schematic in Undermine . Progress: The schematic is of a muffler-type part that sticks onto a grill. It's so amazin' that you can't miss it!", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 230203 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 226569, ["x"] = 0.3235, ["y"] = 0.306 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226569, ["x"] = 0.3235, ["y"] = 0.306 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.3235, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83176 }, ["questLines"] = { { ["id"] = 5660, ["name"] = "Copyright Infringement", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83443] = { ["id"] = 83443, ["name"] = "Darkflame Cleft", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83443 }, ["description"] = "A new ally of ours, a kobold from the Ringing Deeps named Skitter, has contacted me. I need you to go to Darkflame Cleft and remove a certain threat--something that Skitter called The Darkness. How can a kobold be afraid of the darkness when they spend most of their time underground? It makes no sense to me. But kobolds will be kobolds, and I will not busy myself with understanding.", ["objectivesText"] = "Biergoth wants you to venture into Darkflame Cleft and face The Darkness. Progress: Let me know if you figure out what this darkness is all about.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 237014 }, ["rewardChoices"] = { 237014 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226623, ["x"] = 0.465333, ["y"] = 0.483333 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226623, ["x"] = 0.465333, ["y"] = 0.483333 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.465333, ["y"] = 0.483333 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "dungeon" },
[83445] = { ["id"] = 83445, ["name"] = "Something Smells", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83442, 83445, 83446 }, ["description"] = "Ooh! That Mite makes me so mad! He even took credit for it. An' I was right. He's going to present the Smellersweller to our boss! In fact, he's probably presenting it right now! That gives me an idea though. We may not have the schematic, but Mite won't know how to operate it. If we can show the boss it's not Mite's design, maybe I'll still get credit! How good are you at pressing buttons? Will you help me present the prototype?", ["objectivesText"] = "Speak with Snap Vellumgrease at Cheap Grillz in Hovel Hill. Progress: We've got to hurry! Mite's had most of an hour to prepare. All while I was on a break, that mook!", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 226569, ["x"] = 0.3235, ["y"] = 0.306 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226703, ["x"] = 0.289333, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.3235, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83442 }, ["questLines"] = { { ["id"] = 5660, ["name"] = "Copyright Infringement", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83446] = { ["id"] = 83446, ["name"] = "Cease and Desist", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83442, 83445, 83446 }, ["description"] = "Our presentation showed that we were the ones that could actually operate the device! If Sammy weren't so focused on the documentation bein' in Mite's hands... Anyone else could clearly see we had made the thing even if we didn't have the schematics! But this ain't over. You saw how Mite overloaded the Smellersweller? We can do that too! Punch a bunch of buttons all at once and we can exploit his half-baked, all-stolen idea! We go in, we mess up the prototype, an' we set production back months!", ["objectivesText"] = "Stop the Smellersweller 5000 production at Cheap Grillz in Hovel Hill. Progress: Mite... might actually have a good point there.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 232739, 232746, 232755, 232758 }, ["rewardCurrencies"] = { { ["id"] = 3118, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 226703, ["x"] = 0.289333, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226709, ["x"] = 0.273333, ["y"] = 0.352667 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.289333, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83445 }, ["questLines"] = { { ["id"] = 5660, ["name"] = "Copyright Infringement", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83457] = { ["id"] = 83457, ["name"] = "The Stonevault", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83457 }, ["description"] = "I have a job for you from High Speaker Brinthe herself. The skardyn corruption is taking over the Stonevault. To contain the panic, High Speaker Brinthe has asked us for help. I told her she could trust us like we trust the bedrock under our feet. Go to The Stonevault and remove the skardyn corruption. Let me know when the job is done.", ["objectivesText"] = "Biergoth wants you to end the skardyn corruption within The Stonevault. Progress: Any news I can report to High Speaker Brinthe?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 2815, 2899, 2902, 3056, 224784, 229354, 237014 }, ["rewardChoices"] = { 237014 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226623, ["x"] = 0.465333, ["y"] = 0.483333 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226623, ["x"] = 0.465333, ["y"] = 0.483333 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.465333, ["y"] = 0.483333 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "dungeon" },
[83458] = { ["id"] = 83458, ["name"] = "Priory of the Sacred Flame", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83458 }, ["description"] = "Good to see you, <name>. I have a job just for you. Sister Etna Blayze of the Arathi is convinced that something is wrong within the Sacred Flame Priory. She did not expand on the matter at hand. Please head out to the Priory of the Sacred Flame and join the sister. A stomach pebble tells me she might be right and will need your help.", ["objectivesText"] = "Biergoth wants you to go to the Priory of the Sacred Flame and help Sister Etna Blayze. Progress: I am not sure if you are still here or already back.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 2815, 2899, 2902, 3056, 226134, 226137, 226138, 226139, 237014 }, ["rewardChoices"] = { 2815, 2899, 2902, 3056, 237014 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226623, ["x"] = 0.465333, ["y"] = 0.483333 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226623, ["x"] = 0.465333, ["y"] = 0.483333 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.465333, ["y"] = 0.483333 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "dungeon" },
[83459] = { ["id"] = 83459, ["name"] = "The Dawnbreaker", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83459 }, ["description"] = "I have received word from General Steelstrike of the Arathi. She asked for you to attend a ceremony aboard The Dawnbreaker. By attending, she means she needs an extra pair of eyes--maybe two or five. Have you ever secured a ceremony before? It feels like a puddle of sticky mud down in the Forgegrounds. I'm sorry, but General Steelstrike asked, and I replied with a simple \"yes.\" As the saying goes, not every hill is going to be exciting.", ["objectivesText"] = "Biergoth wants you to go to The Dawnbreaker and help General Steelstrike with securing the ceremony. Progress: I know ceremonies are not your cup of cinderbrew. They are not mine either, but our job is important.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 2815, 2899, 2902, 3056, 224784, 226141, 229354, 237014 }, ["rewardChoices"] = { 2815, 2899, 2902, 3056, 237014 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226623, ["x"] = 0.465333, ["y"] = 0.483333 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226623, ["x"] = 0.465333, ["y"] = 0.483333 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.465333, ["y"] = 0.483333 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "dungeon" },
[83465] = { ["id"] = 83465, ["name"] = "Ara-Kara, City of Echoes", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83465 }, ["description"] = "Tulumun, an agent of a new contact known as the Vizier, has approached us. I never expected a nerubian to come to us for help, but what they brought to our attention could threaten us all. I will need you to descend into Azj-Kahet and infiltrate Ara-Kara, the City of Echoes. If what Tulumun told me is true, we cannot let whatever they have woven down there escape. Put an end to their operation. Bring back evidence of what you find.", ["objectivesText"] = "Biergoth wants you to stop the operation taking place within Ara-Kara. Progress: Move quickly. Their operation cannot be allowed to come to fruition.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 2815, 2899, 2902, 3056, 219314, 221154, 224784, 229354, 237014 }, ["rewardChoices"] = { 2815, 2899, 2902, 3056, 237014 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226623, ["x"] = 0.465333, ["y"] = 0.483333 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226623, ["x"] = 0.465333, ["y"] = 0.483333 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.465333, ["y"] = 0.483333 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "dungeon" },
[83469] = { ["id"] = 83469, ["name"] = "City of Threads", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83469 }, ["description"] = "Tulumun, our Nerubian ally, contacted us once again. He spoke of a place called the Transformatory where horrific experiments take place. I will need you to infiltrate the city and then rendezvous with the Vizier himself for the rest of the mission. Eliminate the Vizier's enemies, end the threat, and return to me for your payment.", ["objectivesText"] = "Biergoth wants you to eliminate all threats within the City of Threads. Progress: Make it quick. I do not wish for you to spend more time than you have to in a nerubian city.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 2815, 2899, 2902, 3056, 221181, 221189, 224784, 229354, 237014 }, ["rewardChoices"] = { 2815, 2899, 2902, 3056, 237014 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226623, ["x"] = 0.465333, ["y"] = 0.483333 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 226623, ["x"] = 0.465333, ["y"] = 0.483333 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.465333, ["y"] = 0.483333 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "dungeon" },
[83484] = { ["id"] = 83484, ["name"] = "Oh, Rats!", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83484, 83485, 83486, 83487, 85711 }, ["description"] = "Okay, scout's honor this ain't a joke. I need help because... I turned my best friend into a rat. My friend Allie is the cook here. She tries her best but she's... no good. She's got a bum sniffer. So, I bought her a potion that would make her smell better! ...I mean, improve her sense of smell. But it turned her into a rat! Then she ran off! Ya gotta find her for me. Dealer had another potion to understand rats. I'm too afraid to drink it though. Can you use it an' find her?", ["objectivesText"] = "Find Alice Grillspark. Progress: The rat tilts its head, observing you closely.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 62996, 62997, 62998, 228614, 263358, 263359, 263362, 263364 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 226728, ["x"] = 0.382, ["y"] = 0.884 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226710, ["x"] = 0.332, ["y"] = 0.844 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.382, ["y"] = 0.884 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83130 }, ["questLines"] = { { ["id"] = 5631, ["name"] = "Oh, Rats!", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83485] = { ["id"] = 83485, ["name"] = "Potent Potables", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83484, 83485, 83486, 83487, 85711 }, ["description"] = "<sniff> <sniff> This potion has the scent of the Vatworks on it. There's a vendor at the northern edge there who sells potions. It must be from him. If you can find him, maybe you can get him to hand over an antidote. Please help. You're the only one who can understand me!", ["objectivesText"] = "Help Alice Grillspark.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 228614 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 226710, ["x"] = 0.332, ["y"] = 0.844 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226710, ["x"] = 0.332, ["y"] = 0.844 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.332, ["y"] = 0.844 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questTurnInID"] = 226710, ["questType"] = "standard", ["sourceQuests"] = { 83484 }, ["questLines"] = { { ["id"] = 5631, ["name"] = "Oh, Rats!", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83486] = { ["id"] = 83486, ["name"] = "Remote Work", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 83484, 83485, 83486, 83487, 85711 }, ["description"] = "If you're reading this, I'm out scavenging for reagents along the Kaja'Coast. If you're here to collect on a debt, you are TRESPASSING and must disregard this note . -Getry", ["objectivesText"] = "Locate Getry Sellswill at the Kaja'Coast in Zandalar. Progress: The pack has largely escaped damage. A well-worn book is visible from underneath the open flap.", ["rewardGold"] = 232300, ["rewardXP"] = 8825, ["rewardItems"] = { 232770, 232776, 232781, 232783 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["npcID"] = 454456, ["x"] = 0.324, ["y"] = 0.559, ["mapID"] = 2346 } }, ["ends"] = { { ["npcID"] = 466110, ["x"] = 0.209, ["y"] = 0.588, ["mapID"] = 862 } }, ["coords"] = { ["x"] = 0.324, ["y"] = 0.559, ["source"] = "quest_giver", ["mapID"] = 862 }, ["mapCandidates"] = { ["npc"] = { 862, 2346 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["sourceQuests"] = { 83485 }, ["questLines"] = { { ["id"] = 5631, ["name"] = "Oh, Rats!", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862 },
[83487] = { ["id"] = 83487, ["name"] = "Occupational Hazard", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83484, 83485, 83486, 83487, 85711 }, ["description"] = "<You surmise that collecting enough redberries and returning them to Humphrey should allow Alice to turn back into her usual goblin self.>", ["objectivesText"] = "Collect the redberry reagents and return to Humphrey. Progress: Any luck with that antidote, <name>?", ["rewardGold"] = 619600, ["rewardXP"] = 14705, ["rewardItems"] = { 231369 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["x"] = 0.209, ["y"] = 0.588, ["mapID"] = 862, ["objectID"] = 466110 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226728, ["x"] = 0.382, ["y"] = 0.884 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.382, ["y"] = 0.884 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["sourceQuests"] = { 83486 }, ["questLines"] = { { ["id"] = 5631, ["name"] = "Oh, Rats!", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83489] = { ["id"] = 83489, ["name"] = "Gathering All Gladiators!", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83489 }, ["description"] = "Come one, come all, straight to Dornogal ! In addition to the usual selection of powerful equipment offered at the Contender's Gate, aspiring combatants and proven gladiators can purchase heraldry tokens which can be used to craft equipment certified for use in arenas and battlegrounds! Present this brochure to Hotharn to receive a few of these, on us! - Aisha", ["objectivesText"] = "Deliver the advertisement to Hotharn at the Contender's Gate in Dornogal .", ["rewardItems"] = { 210233, 225772 }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219215, ["x"] = 0.555, ["y"] = 0.77 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.77 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["startItems"] = { 225772 } },
[83492] = { ["id"] = 83492, ["name"] = "Warbands: Warbanding Together", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 83492, 83493, 83494, 83495, 83496 }, ["description"] = "<name>, some adventurers have gotten together to form a warband and could use your help. Find Blue and her group in Gadgetzan.", ["objectivesText"] = "Meet Blue and her Warband in Gadgetzan.", ["rewardGold"] = 5350, ["rewardXP"] = 345, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 133407, ["x"] = 0.395, ["y"] = 0.794 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226658, ["x"] = 0.511333, ["y"] = 0.284 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.794 }, ["mapCandidates"] = { ["npc"] = { 71, 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5632, ["name"] = "Warbanding Together", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 71, ["startItems"] = { 228623 } },
[83493] = { ["id"] = 83493, ["name"] = "Warbands: Rift Reader", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 83492, 83493, 83494, 83495, 83496 }, ["description"] = "I bet you're wondering what we're working on, huh? We're going to make our Warband Bank accessible from anywhere! Rivet's calling it a Warband Bank Distance Inhibitor until I can think of something more fun, but we need a little help to get it over the finish line. If we're going to make sure we can access our shared stash from multiple locations, we're going to need portals! And we tracked some doozies down out here. If you could get us some scans of the local anomalies, it'd be a big help!", ["objectivesText"] = "Scan Transpositional Anomalies near Gadgetzan. Progress: Did you find them?", ["rewardGold"] = 341600, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 226658, ["x"] = 0.511333, ["y"] = 0.284 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226658, ["x"] = 0.511333, ["y"] = 0.284 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.511333, ["y"] = 0.284 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["sourceQuests"] = { 83492 }, ["questLines"] = { { ["id"] = 5632, ["name"] = "Warbanding Together", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 71, ["db2QuestSortName"] = "Nightborne" },
[83494] = { ["id"] = 83494, ["name"] = "Warbands: Space Ghosts by the Coast", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 83492, 83493, 83494, 83495, 83496 }, ["description"] = "There are an awful lot of half-teleported things wandering around the desert not too far from here. Really, any at all would be a surprising amount, but there are a bunch of them for some reason! They don't seem particularly nice, but I bet we could learn from their predicament to ensure the Warband Bank Distance Inhibitor doesn't teleport our sweet loot into a tree! See if you can find anything that might help us figure out what went wrong. It's not like people randomly teleport around, right?", ["objectivesText"] = "Collect Spatial Residue from the Partially Teleported creatures near Gadgetzan. Progress: Any clues?", ["rewardGold"] = 341600, ["rewardXP"] = 2765, ["rewardItems"] = { 225783 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 226658, ["x"] = 0.511333, ["y"] = 0.284 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226658, ["x"] = 0.511333, ["y"] = 0.284 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.511333, ["y"] = 0.284 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["sourceQuests"] = { 83492 }, ["questLines"] = { { ["id"] = 5632, ["name"] = "Warbanding Together", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 71, ["db2QuestSortName"] = "Nightborne" },
[83495] = { ["id"] = 83495, ["name"] = "Warbands: Twinsposition", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 83492, 83493, 83494, 83495, 83496 }, ["description"] = "We're on a roll! We picked up an even more anomalous anomaly while you were out and tracked it down to just west of town. We've got a brand-new Transpositional Signal Recombobulatron already set up out there, but I didn't want to start without you. You've been a big help, after all. All you have to do is dial it in and throw the switch! Easy as pie, which I'm told is very easy. Rivet says that the odds of something cataclysmic happening are pretty good, so I know nothing bad can happen!", ["objectivesText"] = "Activate the Transpositional Signal Recombobulatron outside Gadgetzan and deal with the consequences. Progress: Throw the switch!", ["rewardGold"] = 683200, ["rewardXP"] = 3455, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 226658, ["x"] = 0.511333, ["y"] = 0.284 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226658, ["x"] = 0.511333, ["y"] = 0.284 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.511333, ["y"] = 0.284 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["sourceQuests"] = { 83493, 83494 }, ["questLines"] = { { ["id"] = 5632, ["name"] = "Warbanding Together", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 71, ["db2QuestSortName"] = "Nightborne" },
[83496] = { ["id"] = 83496, ["name"] = "Warbands: Spacetime is Money", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 83492, 83493, 83494, 83495, 83496 }, ["description"] = "Now that we've got all the transpositional data we could ever hope for, all we need to do is set up a wormhole in a suitable banking establishment and we'll be dropping gear into each other's pockets from the field in no time! And there just happens to be a bank right here in Gadgetzan! You can even attune your own portal at the same time so you can access your own Warband Bank from anywhere. It's going to be so convenient!", ["objectivesText"] = "Place the De-Recombobulatron Matrix in the Gadgetzan Bank. Progress: Did you find the bank?", ["rewardGold"] = 170800, ["rewardXP"] = 1385, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 226658, ["x"] = 0.511333, ["y"] = 0.284 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226658, ["x"] = 0.511333, ["y"] = 0.284 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.511333, ["y"] = 0.284 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["sourceQuests"] = { 83495 }, ["questLines"] = { { ["id"] = 5632, ["name"] = "Warbanding Together", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 71, ["db2QuestSortName"] = "Nightborne" },
[83497] = { ["id"] = 83497, ["name"] = "A Concerned Friend", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2339, ["storyline"] = { 79165, 79166, 79167, 79168, 83497 }, ["description"] = "Ah, <name>, there you are! Great Kyron was asking after you and your friend Anduin. I think they want to talk to you about Faerin. Nothing urgent mind you, she probably just needs some good company. But we're all a bit worried about her. Check in with Kyron when you have a moment, will you?", ["objectivesText"] = "Meet Great Kyron in Mereldar.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 226708, ["x"] = 0.51, ["y"] = 0.464 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 215341, ["x"] = 0.43, ["y"] = 0.524 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.464 }, ["mapCandidates"] = { ["npc"] = { 2215, 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["nextQuests"] = { 79165 }, ["questLines"] = { { ["id"] = 5542, ["name"] = "Rest at Last", ["orderIndex"] = 0, ["flags"] = 1 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[83499] = { ["id"] = 83499, ["name"] = "Arcane Wasteland", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 83031, 83499, 83502, 83539, 83553, 83554, 83555, 83556, 83641, 83643, 84223 }, ["description"] = "Kirin Tor survivors have been hesitant to return to this area. A great deal of energy was dispelled before and after Dalaran's crash. An invisible yet tangible miasma lingers in the area for those who are sensitive to it. It is unclear if the site is hazardous or if other more corporeal dangers still lurk here. I can protect us, but I expended all my reagents at the Proscenium. Will you aid me in procuring more?", ["objectivesText"] = "Help Aethas Sunreaver gather reagents required for a protective spell in the Tranquil Strand. Progress: The last few days have been... difficult.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 225662, 225663, 225895 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 225355, ["x"] = 0.295, ["y"] = 0.58 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 225355, ["x"] = 0.295, ["y"] = 0.58 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.295, ["y"] = 0.58 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 83031 }, ["questLines"] = { { ["id"] = 5664, ["name"] = "Arcane Desolation", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 265, ["title"] = "Fate of the Kirin Tor", ["questLineID"] = 5664, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[83500] = { ["id"] = 83500, ["name"] = "Zekvir, Hand of the Harbinger", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 81595, 81596, 83500, 84224 }, ["description"] = "We'll have tae watch out for Zekvir as we go exploring into delves. I don't think we're strong enough tae take him on just yet, but we will be! Let's keep explorin' and gettin' treasure until we're tough enough tae track down his lair and defeat him.", ["objectivesText"] = "Defeat Zekvir , the Hand of the Harbinger within his own delve.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 212171, 212265, 212280, 222504, 222720, 222768, 224572, 225542, 225547, 228984 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 206017, ["x"] = 0.475, ["y"] = 0.445 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 206017, ["x"] = 0.475, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["sourceQuests"] = { 81596 }, ["questLines"] = { { ["id"] = 5633, ["name"] = "Delves - Season 1", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[83502] = { ["id"] = 83502, ["name"] = "Lessons in Defensive Magic", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 83031, 83499, 83502, 83539, 83553, 83554, 83555, 83556, 83641, 83643, 84223 }, ["description"] = "The spell for the barrier is ready, but I must channel it and define its perimeter. While I channel the spell, take these wards and place them at the edges of our would-be barrier. We will empower the spell when you are finished.", ["objectivesText"] = "Help Aethas Sunreaver cast a spell to create a protective arcane dome in the Tranquil Strand.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 225355, ["x"] = 0.295, ["y"] = 0.58 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 226895, ["x"] = 0.296, ["y"] = 0.58 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.295, ["y"] = 0.58 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 83499 }, ["questLines"] = { { ["id"] = 5664, ["name"] = "Arcane Desolation", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 265, ["title"] = "Fate of the Kirin Tor", ["questLineID"] = 5664, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[83503] = { ["id"] = 83503, ["name"] = "Return to Dornogal", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78941, 78942, 78943, 78948, 78950, 83503 }, ["description"] = "The battle is finally over and I suppose it's time we lick our wounds. Head back to Dornogal, Champion. I'll be right there as soon as Khadgar is healthy enough to withstand travel.", ["objectivesText"] = "Return to Dornogal in the Isle of Dorn and report what happened.", ["rewardGold"] = 30300, ["rewardXP"] = 1470, ["rewardItems"] = { 223572 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 220688, ["x"] = 0.36, ["y"] = 0.354 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 217864, ["x"] = 0.405, ["y"] = 0.259 }, { ["mapID"] = 2339, ["npcID"] = 225897, ["x"] = 0.254, ["y"] = 0.662667 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.36, ["y"] = 0.354 }, ["mapCandidates"] = { ["npc"] = { 2215, 2339 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["sourceQuests"] = { 78948 }, ["questLines"] = { { ["id"] = 5550, ["name"] = "A Light in the Dark", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 6006, ["name"] = "Catch Up: War Within: Wrapper 3", ["orderIndex"] = 16, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 240, ["title"] = "The Dark Heart", ["questLineID"] = 5550, ["questLineOrder"] = 4 }, { ["id"] = 318, ["title"] = "Catch Up: The War Within", ["questLineID"] = 6006, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[83519] = { ["id"] = 83519, ["name"] = "But What About the Casino?", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83519, 83522, 83524, 83527, 83528, 83534, 83535, 83540, 83541, 83542, 83546, 83558, 83563, 83566, 83569, 84221, 84242, 84244, 84249, 85189 }, ["description"] = "Times are a changing. Now that ol' Jastor is kaput, the cartel heads are chomping at the bit to settle the fate of Undermine 's crown jewel: the Gallagio. There's a court proceeding tomorrow to make a final determination, but luckily the deed is squarely in the hands of someone I trust. Their name: Rosebud Gallywix. I know. I know. But Rosey is a good egg. I'll introduce you to him later on. First, do me a favor. Ask the power players here at the party how they feel about the new owner.", ["objectivesText"] = "Ask about Rosebud Gallywix at the Gallagio's opening party. Progress: Don't get turned off by the Gallywix name. He had a big family, and they ain't all evil crankshafts.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 226273, ["x"] = 0.6544, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226273, ["x"] = 0.6544, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.6544, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 87297 }, ["questLines"] = { { ["id"] = 5641, ["name"] = "Hard Ways at the Gallagio", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83521] = { ["id"] = 83521, ["name"] = "Little Help, Please?", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83521 }, ["description"] = "So, uh, I swear this never happens, but this kind fellow here pulled me over for a busted tail light. I just got that fixed. I swear it! Would you do me a favor? Keep him and any of his colleagues entertained. My license is in one of these compartments somewhere, I just gotta find it. Shouldn't be more than a minute. Two at most!", ["objectivesText"] = "Deal with the Venture Co. \"Policers\".", ["rewardGold"] = 117000, ["rewardXP"] = 5885, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 15347 } }, ["questType"] = "standard" },
[83522] = { ["id"] = 83522, ["name"] = "Debting For A Living", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83519, 83522, 83524, 83527, 83528, 83534, 83535, 83540, 83541, 83542, 83546, 83558, 83563, 83566, 83569, 84221, 84242, 84244, 84249, 85189 }, ["description"] = "First of Rosebud's Chiefs on our list are the genius gaming duo: Kayjay and Fantastic Davey. Now, I heard from my wife's brother that Venture Co. bought up all the debt those boys got. Happened the minute Rosebud was done in. Did they murder him? Not a great motive if their debt was sky high, but you never know whose pocket a goblin is in either. Best we see how comfortable they are here at the ol' Venturewood landfill. If they don't want to sign the new deed, we might have our culprits!", ["objectivesText"] = "Speak with Kayjay and Fantastic Davey about signing the new Gallagio deed. Progress: You'll find all those in my employ are quite content. I've got the bills from various corporate training seminars to prove it.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 226277, ["x"] = 0.5145, ["y"] = 0.714 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 228420, ["x"] = 0.526, ["y"] = 0.728 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.5145, ["y"] = 0.714 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 84242 }, ["questLines"] = { { ["id"] = 5641, ["name"] = "Hard Ways at the Gallagio", ["orderIndex"] = 4, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83524] = { ["id"] = 83524, ["name"] = "Gold In Them There Trash", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83519, 83522, 83524, 83527, 83528, 83534, 83535, 83540, 83541, 83542, 83546, 83558, 83563, 83566, 83569, 84221, 84242, 84244, 84249, 85189 }, ["description"] = "Kayjay and Davey are indeed masters of creating games. They've created a new one for me that's been an absolute hit. If you're willing to accept the risk, then I will give you the chance to win their employment, and debt, from me. Grab a pickaxe, and enter the landfill. When the whistle blows, you'll compete against all my other \"employees.\" Win by the final bell, and I'll let these two go. Lose, and I'll own you. It's called Slot Mining. And it will indebt you to me for life.", ["objectivesText"] = "Compete in Slot Mining at The Heaps. Progress: <Tarbonara says nothing. He simply snarls through his shiny teeth.>", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 232766, 232767, 234188 }, ["rewardChoices"] = { 232766, 232767 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 228420, ["x"] = 0.526, ["y"] = 0.728 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 228474, ["x"] = 0.556, ["y"] = 0.76 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.728 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83522 }, ["questLines"] = { { ["id"] = 5641, ["name"] = "Hard Ways at the Gallagio", ["orderIndex"] = 5, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83527] = { ["id"] = 83527, ["name"] = "Winning is for Losers, Anyway", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83519, 83522, 83524, 83527, 83528, 83534, 83535, 83540, 83541, 83542, 83546, 83558, 83563, 83566, 83569, 84221, 84242, 84244, 84249, 85189 }, ["description"] = "This is the worst job I've ever had. And I used to work Turtle Toss at Darkmoon Faire. We're not imprisoned here physically with shackles, but Tarbonara owns all of our debts. He imprinted the information on Debt Markers, which his goons hold on to in case any of us want to know where we stand. But if you get a hold of those markers, we're all free. You'd have to crack some skulls to get them though, so I'll give you points for each of his goons bring down. You like collecting points, don'tcha?", ["objectivesText"] = "Collect Debt Markers and free the Indenture Debtors.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 228473, ["x"] = 0.558, ["y"] = 0.76 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 232823, ["x"] = 0.5645, ["y"] = 0.655 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.76 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83524 }, ["questLines"] = { { ["id"] = 5641, ["name"] = "Hard Ways at the Gallagio", ["orderIndex"] = 6, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83528] = { ["id"] = 83528, ["name"] = "All Part of the Game", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83519, 83522, 83524, 83527, 83528, 83534, 83535, 83540, 83541, 83542, 83546, 83558, 83563, 83566, 83569, 84221, 84242, 84244, 84249, 85189 }, ["description"] = "Look. I know we're the ones that incurred our own debts, but Rosebud believed in us! With him, there was a light at the end of the casino floor. With him gone... We're just two halves of a gaming genius, working for hire instead of salary. But Zoomcart told us there's still a chance we could work the Gallagio. Is that true? If it is, Davey and I are in. Problem is that Davey and I's Debt Markers are held by the gaming commissioner himself: Kudd Milktooth. And he's deep in Tarby's pocket.", ["objectivesText"] = "Collect Kayjay and Fantastic Davey's Debt Markers from Commissioner Kudd Milktooth.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardCurrencies"] = { { ["id"] = 3118, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 228474, ["x"] = 0.556, ["y"] = 0.76 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 232823, ["x"] = 0.5645, ["y"] = 0.655 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.76 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83524 }, ["questLines"] = { { ["id"] = 5641, ["name"] = "Hard Ways at the Gallagio", ["orderIndex"] = 7, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83529] = { ["id"] = 83529, ["name"] = "Hallowfall Fishing Derby", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 82778, 83529, 83530, 83531, 83532 }, ["description"] = "Life is always on the edge here, $p. Nerubians, kobyss, hunger--there's always something ready to kill you. So we need to find times to relax, and challenge ourselves at something other than survival. Like fishing. My dad always spent Saturdays fishing, when I was growing up. He'd say, \"Take some time for yourself, or you can't be effective for others.\" So every Saturday, I challenge people to the Hallowfall Fishing Derby. You have one hour to catch trophy fish. See what you can bring me!", ["objectivesText"] = "Catch these Trophy Fish before the Derby Dasher buff expires: Bismuth Butterling, Whispering Stargazer, Regal Dottyback. Progress: Any bites, <name>?", ["rewardItems"] = { 168417, 191356, 212310, 217375, 219002, 219003, 219004, 219005, 219006, 220134, 220135, 220136, 220137, 220138, 220139, 220141, 220142, 220143, 220144, 220145, 220146, 220147, 220148, 220149, 220150, 220151, 220152, 220153, 221790, 222533, 222745, 222842, 223286, 223979, 224717, 224727, 224752, 225592, 225758, 225763, 225770, 225771, 225892, 226376, 226378, 226379, 226392, 228421, 228422, 228423, 228954 }, ["rewardChoices"] = { 224752, 225771, 225770 }, ["rewardCurrencies"] = { { ["id"] = 3055, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 226846, ["x"] = 0.424667, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 226846, ["x"] = 0.424667, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.424667, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5637, ["name"] = "Hallowfall Fishing Derby", ["orderIndex"] = 1, 