[83538] = { ["id"] = 83538, ["name"] = "Excavation Liberation", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80208, 80323, 81656, 81691, 81750, 81767, 82238, 82244, 82256, 82518, 82519, 82523, 82552, 82580, 83028, 83048, 83079, 83080, 83101, 83229, 83537, 83538, 83715, 83930, 84429 }, ["objectivesText"] = "Defeat hostile creatures and retrieve earthen tools", ["rewardXP"] = 11765, ["starts"] = { { ["x"] = 0.578, ["y"] = 0.849, ["mapID"] = 2214 } }, ["ends"] = { { ["x"] = 0.578, ["y"] = 0.849, ["mapID"] = 2214 } }, ["coords"] = { ["mapID"] = 2214, ["x"] = 0.578, ["y"] = 0.849 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14795 } }, ["questType"] = "world", ["questLines"] = { { ["id"] = 5588, ["name"] = "Ringing Deeps - World Quests / Repeatable", ["orderIndex"] = 25, ["flags"] = 0 } }, ["db2Objectives"] = { { ["text"] = "Defeat hostile creatures and retrieve earthen tools", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[83539] = { ["id"] = 83539, ["name"] = "Feeling Blue", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 83031, 83499, 83502, 83539, 83553, 83554, 83555, 83556, 83641, 83643, 84223 }, ["description"] = "I fear... that it may just be me that remains, <name>. Or that the others are too far away to receive my missive. It may be up to us to build an outpost here and see to the cleansing of the crash site. So be it. It is just as well...", ["objectivesText"] = "Build the Kirin Tor outpost in the Tranquil Strand. Progress: It's hard to describe what I feel right now.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 226895, ["x"] = 0.296, ["y"] = 0.58 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 227067, ["x"] = 0.298, ["y"] = 0.578 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.296, ["y"] = 0.58 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 83502 }, ["questLines"] = { { ["id"] = 5664, ["name"] = "Arcane Desolation", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 265, ["title"] = "Fate of the Kirin Tor", ["questLineID"] = 5664, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[83540] = { ["id"] = 83540, ["name"] = "Work the Line", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83519, 83522, 83524, 83527, 83528, 83534, 83535, 83540, 83541, 83542, 83546, 83558, 83563, 83566, 83569, 84221, 84242, 84244, 84249, 85189 }, ["description"] = "Not sure if your schnoz picked up what mine did on the drive over, but there were some delightful smells coming from the street below. Problem was, the crowds were too thick for me to find Gobdre anywhere. That's where Noggy comes in. He's a pretty important fella these days, so I figure he'd have some sorta in for us. He's generally an unfeeling scientist-type who doesn't spill secrets. But his pride is also fragile as my wife's Rumble figurines. Give it a poke and he should spill.", ["objectivesText"] = "Get Marin Noggenfogger to spill the beans on Jojo Gobdre 's whereabouts. Progress: Did you just cut the line?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 152668, 227663 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 226932, ["x"] = 0.328, ["y"] = 0.802 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226934, ["x"] = 0.369, ["y"] = 0.876 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.328, ["y"] = 0.802 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 84249 }, ["questLines"] = { { ["id"] = 5641, ["name"] = "Hard Ways at the Gallagio", ["orderIndex"] = 12, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83541] = { ["id"] = 83541, ["name"] = "Review Bombed", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83519, 83522, 83524, 83527, 83528, 83534, 83535, 83540, 83541, 83542, 83546, 83558, 83563, 83566, 83569, 84221, 84242, 84244, 84249, 85189 }, ["description"] = "Show me you ain't just talk. I give Diner Cards to each customer. They're supposed to fill it out with their reviews on my menu, and return it here. But I haven't seen any yet. Fishy much? Definitely. And not the kind I like. Go. Fetch. Get my reviews back. I ain't budging an inch in the Gallagio's direction without them.", ["objectivesText"] = "Retrieve 100 Diner Review Cards . Progress: How'd they like the Junglevine-soaked Stormray? Bet they said it was bitter. I knew that batch was bitter. Ran outta salt when I was cooking it.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 227666 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 226934, ["x"] = 0.369, ["y"] = 0.876 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226934, ["x"] = 0.369, ["y"] = 0.876 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.369, ["y"] = 0.876 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83540 }, ["questLines"] = { { ["id"] = 5641, ["name"] = "Hard Ways at the Gallagio", ["orderIndex"] = 13, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83542] = { ["id"] = 83542, ["name"] = "Quick Gills for Gold Now", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83519, 83522, 83524, 83527, 83528, 83534, 83535, 83540, 83541, 83542, 83546, 83558, 83563, 83566, 83569, 84221, 84242, 84244, 84249, 85189 }, ["description"] = "Ah, crabs... I knew this would happen. The diners overwhelmingly scored one dish above all others: pan-seared deepwalker thigh with blood-spiced confit algarian orbinid. Long name, right? I was hoping that would dissuade the customers from writing it on their cards. Trouble is that I can't make pan-seared anything without a pan, now can I? And I sold my best pan when the Gallagio deal fell through. Want me back on board? Then get my pan. Those deepwalker thighs ain't gonna sear themselves.", ["objectivesText"] = "Exchange Gold Fish for Gobdre's Prized Pan . Progress: Blair and Chub Bass. The scammiest lovebirds you'll ever meet. But they did source me some terrific fish.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 227673, 227674, 237345, 237346, 237347 }, ["rewardCurrencies"] = { { ["id"] = 3118, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 226934, ["x"] = 0.369, ["y"] = 0.876 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226934, ["x"] = 0.369, ["y"] = 0.876 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.369, ["y"] = 0.876 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83541 }, ["questLines"] = { { ["id"] = 5641, ["name"] = "Hard Ways at the Gallagio", ["orderIndex"] = 14, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83543] = { ["id"] = 83543, ["name"] = "Adventuring in Khaz Algar", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2339, ["storyline"] = { 78713, 78714, 78715, 78716, 78717, 78718, 78719, 78721, 78722, 79105, 79106, 80321, 80500, 81930, 81966, 83543 }, ["description"] = "We've got scouts in every corner o' Khaz Algar, an' they all report the same thing: trouble. Seems we got here just in time, eh? Check the scouting map on the table behind ye and lend a hand where ye can.", ["objectivesText"] = "Review the Scouting Map to choose an area within Khaz Algar to support.", ["rewardGold"] = 30900, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 206017, ["x"] = 0.475, ["y"] = 0.445 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 206017, ["x"] = 0.475, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questTurnInID"] = 206017, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5513, ["name"] = "Visions of Azeroth", ["orderIndex"] = 15, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 235, ["title"] = "Visions of Azeroth", ["questLineID"] = 5513, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5513, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2339 },
[83546] = { ["id"] = 83546, ["name"] = "Responsibility", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83519, 83522, 83524, 83527, 83528, 83534, 83535, 83540, 83541, 83542, 83546, 83558, 83563, 83566, 83569, 84221, 84242, 84244, 84249, 85189 }, ["description"] = "Today's the day for shiny shoes, <name>! We've got our deed signatures. We've got support from the cartels. And we've got... my kids. My wife was supposed to come with us today as well, but she slipped in the shower! Can you believe that? She'll be at the chiropractor all morning. I feel awful for her. Absolutely awful. Welp! Her loss! Let's pack up what we need and I'll drive us all over to the court room!", ["objectivesText"] = "Pack up and drive to court. Progress: You look worried. You shouldn't be worried. I'm not worried.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 220158 }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 227018, ["x"] = 0.386, ["y"] = 0.338 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 227032, ["x"] = 0.562667, ["y"] = 0.438667 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.386, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 85189 }, ["questLines"] = { { ["id"] = 5641, ["name"] = "Hard Ways at the Gallagio", ["orderIndex"] = 16, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83547] = { ["id"] = 83547, ["name"] = "Welcome to the Neighborhood", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 6170, ["mapID"] = 37, ["storyline"] = { 83547, 84832 }, ["description"] = "Welcome to Borogrove, ! I'm Llyssabel Dawnpetal, the local steward. I'll be helping you get better acquainted with the neighborhood. Once you've settled in, please come see me at Town Hall.", ["objectivesText"] = "Speak with Llyssabel Dawnpetal at Town Hall.", ["rewardGold"] = 292100, ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6170 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5636, ["name"] = "Housing NPC Prototype", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5689, ["name"] = "Neighborhood Prototype Quests", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2698, ["db2PoiUiMapID"] = 2321 },
[83548] = { ["id"] = 83548, ["name"] = "Isle of Dorn", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 78529, 78530, 78531, 78532, 78533, 78534, 78535, 78536, 80334, 83548 }, ["series"] = { 78530 }, ["description"] = "Survivors from the attack on Dalaran are beset by nerubians led by Queensguard Zirix. Lend your aid to protect whomever remains.", ["objectivesText"] = "Speak with Lady Jaina Proudmoore on the Isle of Dorn .", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["starts"] = { { ["x"] = 0.482, ["y"] = 0.437, ["mapID"] = 2339, ["npcID"] = 227038 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 211994, ["x"] = 0.294, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.294, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questGiverID"] = 227038, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5539, ["name"] = "Breaking Point", ["orderIndex"] = 9, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 236, ["title"] = "Isle of Dorn", ["questLineID"] = 5539, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5539, ["questLineOrder"] = 2 } }, ["db2AdventureMapPoiID"] = 190, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[83550] = { ["id"] = 83550, ["name"] = "The Ringing Deeps", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 78555, 78557, 78631, 78634, 78635, 78636, 78637, 78638, 78639, 78640, 78641, 78642, 78837, 78838, 78839, 79205, 79267, 80082, 80434, 83550 }, ["series"] = { 78555, 80434 }, ["description"] = "Speaker Brinthe has gone to The Ringing Deeps to see how the Machine Speakers have fared while she was away. She has asked for adventurers to join her at the bottom of the Coreway.", ["objectivesText"] = "Meet Speaker Brinthe in The Ringing Deeps .", ["rewardGold"] = 30900, ["rewardXP"] = 1190, ["starts"] = { { ["x"] = 0.482, ["y"] = 0.437, ["mapID"] = 2339, ["npcID"] = 227038 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 212592, ["x"] = 0.4, ["y"] = 0.284 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.284 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questGiverID"] = 227038, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5533, ["name"] = "By Candlelight", ["orderIndex"] = 19, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 237, ["title"] = "The Ringing Deeps", ["questLineID"] = 5533, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5533, ["questLineOrder"] = 5 } }, ["db2AdventureMapPoiID"] = 191, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214 },
[83551] = { ["id"] = 83551, ["name"] = "Hallowfall", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 78658, 78659, 78665, 78666, 78667, 78668, 78669, 78670, 78671, 79999, 82836, 83551 }, ["series"] = { 78659 }, ["description"] = "Anduin Wrynn hopes to gain the trust and aid of the Arathi in Hallowfall . He will need help to win over these potential allies.", ["objectivesText"] = "Speak to Faerin Lothar in Hallowfall .", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 224752, 225246, 225770, 225771 }, ["starts"] = { { ["x"] = 0.482, ["y"] = 0.437, ["mapID"] = 2339, ["npcID"] = 227038 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 213116, ["x"] = 0.6712, ["y"] = 0.5712 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.6712, ["y"] = 0.5712 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questGiverID"] = 227038, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5529, ["name"] = "The Guiding Star", ["orderIndex"] = 11, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 238, ["title"] = "The Hallowfall Arathi", ["questLineID"] = 5529, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5529, ["questLineOrder"] = 8 } }, ["db2AdventureMapPoiID"] = 192, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[83552] = { ["id"] = 83552, ["name"] = "Azj-Kahet", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78348, 78350, 78352, 78353, 78354, 78384, 78392, 78393, 79139, 83552 }, ["series"] = { 78350 }, ["description"] = "An Arathi airship is stranded in Azj-Kahet following a vicious nerubian ambush. Aid the survivors as they withstand the nerubian assault.", ["objectivesText"] = "Speak to Faerin Lothar aboard The Reckoning in Azj-Kahet .", ["rewardGold"] = 30900, ["rewardXP"] = 1190, ["rewardItems"] = { 226166, 226173, 226174, 226175, 226176 }, ["starts"] = { { ["x"] = 0.482, ["y"] = 0.437, ["mapID"] = 2339, ["npcID"] = 227038 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 211699, ["x"] = 0.309, ["y"] = 0.446 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.309, ["y"] = 0.446 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questGiverID"] = 227038, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5520, ["name"] = "Friends in the Dark", ["orderIndex"] = 9, ["flags"] = 1 } }, ["campaigns"] = { { ["id"] = 239, ["title"] = "Azj-Kahet", ["questLineID"] = 5520, ["questLineOrder"] = 0 }, { ["id"] = 312, ["title"] = "The War Within", ["questLineID"] = 5520, ["questLineOrder"] = 11 } }, ["db2AdventureMapPoiID"] = 193, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[83553] = { ["id"] = 83553, ["name"] = "Magic-stealing Kobolds", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 83031, 83499, 83502, 83539, 83553, 83554, 83555, 83556, 83641, 83643, 84223 }, ["description"] = "I'm afraid that our \"clean up\" of Dalaran extends far from the shores of the Isle of Dorn . In my attempts to find you, I circled this island many times. During my flight, I sensed the magic of many familiar items--items that were formerly housed in Dalaran. Dangerous items. Someone or something has taken them who knows where. We must find these objects before innocent bystanders come to harm. Follow me.", ["objectivesText"] = "Meet with Kalecgos at Mourning Rise in the Isle of Dorn .", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 227067, ["x"] = 0.298, ["y"] = 0.578 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 227063, ["x"] = 0.616, ["y"] = 0.415 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.298, ["y"] = 0.578 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 83539 }, ["questLines"] = { { ["id"] = 5664, ["name"] = "Arcane Desolation", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 265, ["title"] = "Fate of the Kirin Tor", ["questLineID"] = 5664, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[83554] = { ["id"] = 83554, ["name"] = "Trinkets, Curios and Other Powerful Objects", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15000, ["mapID"] = 2248, ["storyline"] = { 83031, 83499, 83502, 83539, 83553, 83554, 83555, 83556, 83641, 83643, 84223 }, ["description"] = "The kobolds here could get up to untold mischief with the items they have stolen. Take what you can back from them by... whatever means you see fit. While you deal with the kobolds around Mourning Rise's grave sites, I will go underground and search Kriegval's Rest and do the same. Meet me near Kriegval's Rest when you have secured the Kirin Tor artifacts the kobolds stole.", ["objectivesText"] = "Reclaim stolen Kirin Tor artifacts from the kobolds in the Mourning Rise. Progress: We must search and reclaim what we can. Even the smallest curio could be meaningful to someone... or dangerous.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 225920, 226162 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 227063, ["x"] = 0.616, ["y"] = 0.415 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 227375, ["x"] = 0.615, ["y"] = 0.428 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.415 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 83553 }, ["questLines"] = { { ["id"] = 5664, ["name"] = "Arcane Desolation", ["orderIndex"] = 6, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 265, ["title"] = "Fate of the Kirin Tor", ["questLineID"] = 5664, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[83555] = { ["id"] = 83555, ["name"] = "Mysterious Necklace", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 83031, 83499, 83502, 83539, 83553, 83554, 83555, 83556, 83641, 83643, 84223 }, ["description"] = "<The gem pulses with arcane energy, hinting at ancient magic woven into its very core.>", ["objectivesText"] = "Return the necklace to Kalecgos at Mourning Rise in the Isle of Dorn .", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 228520, ["x"] = 0.62, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 227375, ["x"] = 0.615, ["y"] = 0.428 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 83553 }, ["questLines"] = { { ["id"] = 5664, ["name"] = "Arcane Desolation", ["orderIndex"] = 7, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 265, ["title"] = "Fate of the Kirin Tor", ["questLineID"] = 5664, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248, ["startItems"] = { 225927 } },
[83556] = { ["id"] = 83556, ["name"] = "Maybe You Shouldn't Touch That", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 83031, 83499, 83502, 83539, 83553, 83554, 83555, 83556, 83641, 83643, 84223 }, ["description"] = "This necklace... It is clearly full of powerful magic, but... it is elusive--as if it is hiding its origin from me. You take another look. Maybe there's something obvious I'm missing.", ["objectivesText"] = "Investigate the Emerald Necklace in Mourning Rise.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 227375, ["x"] = 0.615, ["y"] = 0.428 } }, ["ends"] = { { ["mapID"] = 947, ["npcID"] = 227208, ["x"] = 0, ["y"] = 0 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.428 }, ["mapCandidates"] = { ["npc"] = { 947, 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 83554, 83555 }, ["questLines"] = { { ["id"] = 5664, ["name"] = "Arcane Desolation", ["orderIndex"] = 8, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 265, ["title"] = "Fate of the Kirin Tor", ["questLineID"] = 5664, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[83558] = { ["id"] = 83558, ["name"] = "Casino Court", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83519, 83522, 83524, 83527, 83528, 83534, 83535, 83540, 83541, 83542, 83546, 83558, 83563, 83566, 83569, 84221, 84242, 84244, 84249, 85189 }, ["description"] = "I'm all set to make our case. Just one tiny, little, minor thing to let you know about... There's a bomb under my desk here. Don't be alarmed! It ain't the first time this has happened. But there's a lot of people here, and I'd hate to interrupt the proceeding for one little explosive. Take this X-Plo-Dar 64k. Use it to trace the bomb's signature back to the goblin with the trigger. My lawyer's instinct is telling me that the culprit behind this explosive is also Rosebud's killer. Just a hunch.", ["objectivesText"] = "Use the X-Plo-Dar 64k to reveal who's holding the bomb's trigger. Progress: Have you found the source yet?", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 232768, 232773, 232782, 232786 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 227032, ["x"] = 0.562667, ["y"] = 0.438667 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 227032, ["x"] = 0.562667, ["y"] = 0.438667 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.562667, ["y"] = 0.438667 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83546 }, ["questLines"] = { { ["id"] = 5641, ["name"] = "Hard Ways at the Gallagio", ["orderIndex"] = 17, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83563] = { ["id"] = 83563, ["name"] = "Coffee is for Closers", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83519, 83522, 83524, 83527, 83528, 83534, 83535, 83540, 83541, 83542, 83546, 83558, 83563, 83566, 83569, 84221, 84242, 84244, 84249, 85189 }, ["description"] = "You've got us the hard evidence we needed. All that's left to do is reveal Rosebud's killer to the judge. I imagine Tarbonara won't go down lightly, so be prepared for one of any number of goblin-like reactions. You know what I mean. Explosions or cannons or crying or casino heists or whatever. I'm not worried though, you seem capable.", ["objectivesText"] = "Defeat Tarbonara Fizzlecrank, and ensure Judge Landro notarizes the new Gallagio deed. Progress: I had a feeling this would be a great case.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 227032, ["x"] = 0.562667, ["y"] = 0.438667 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226894, ["x"] = 0.565, ["y"] = 0.3975 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.562667, ["y"] = 0.438667 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83558 }, ["questLines"] = { { ["id"] = 5641, ["name"] = "Hard Ways at the Gallagio", ["orderIndex"] = 18, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83566] = { ["id"] = 83566, ["name"] = "Oh, That Casino!", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83519, 83522, 83524, 83527, 83528, 83534, 83535, 83540, 83541, 83542, 83546, 83558, 83563, 83566, 83569, 84221, 84242, 84244, 84249, 85189 }, ["description"] = "You'd make a good lawyerer, you know that? Hah! Just kidding! The real industry secret is that there's no such thing as a good lawyerer! Why don't you join me at the Gallagio's entrance? It'll be a nice send off for the kids who are gonna run this place now. Not to mention that we should actually hand them the notarized deed!", ["objectivesText"] = "Hand the Gallagio over. Progress: You teary-eyed because our adventure is over? Or because you were secretly hoping the place would go to auction, and you'd have a chance to buy it up? Bet it was the latter! Hah!", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardItems"] = { 234125 }, ["rewardCurrencies"] = { { ["id"] = 3118, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 226894, ["x"] = 0.565, ["y"] = 0.3975 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 226273, ["x"] = 0.6544, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.565, ["y"] = 0.3975 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83563 }, ["questLines"] = { { ["id"] = 5641, ["name"] = "Hard Ways at the Gallagio", ["orderIndex"] = 19, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83569] = { ["id"] = 83569, ["name"] = "Death and Taxes", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 15347, ["mapID"] = 2346, ["storyline"] = { 83519, 83522, 83524, 83527, 83528, 83534, 83535, 83540, 83541, 83542, 83546, 83558, 83563, 83566, 83569, 84221, 84242, 84244, 84249, 85189 }, ["description"] = "He just... exploded... If a goblin's gotta go, that's the way. All I can say for poor Rosey. And that I'm gonna miss him. AND that we're gonna find out who did this! But the more immediate pickle is this: Who owns the Gallagio now? It's time to turn to an expert on legal mumbo jumbo. The State of Undermine assigned a public defender to us for the court case tomorrow, a fella named Zoomcart. He's all we got. Take what's left of the deed to his office in Hovel Hill, and sort this out.", ["objectivesText"] = "Meet the State of Undermine 's assigned Public Defender.", ["rewardGold"] = 154900, ["rewardXP"] = 5885, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2346, ["npcID"] = 226273, ["x"] = 0.6544, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 2346, ["npcID"] = 228369, ["x"] = 0.388667, ["y"] = 0.332667 } }, ["coords"] = { ["mapID"] = 2346, ["source"] = "quest_giver", ["x"] = 0.6544, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 2346 }, ["zone"] = { 15347 } }, ["questType"] = "standard", ["sourceQuests"] = { 83519 }, ["questLines"] = { { ["id"] = 5641, ["name"] = "Hard Ways at the Gallagio", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2706, ["db2PoiUiMapID"] = 2346 },
[83587] = { ["id"] = 83587, ["name"] = "Our Chance to Strike", ["level"] = 75, ["requiredLevel"] = 75, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 82124, 82125, 82126, 82127, 82130, 82141, 83587 }, ["series"] = { 82124 }, ["description"] = "<The child-like spider presents you with a sealed scroll. The sealed letter bears the markings of the Vizier.> The balance of power is shifting in Azj-Kahet . The Queen grows more unstable by the day and I fear we must act before our opportunity to stop her slips from our grasp. Meet me at the Royal Apothecary when you receive this letter.", ["objectivesText"] = "Meet with the Vizier at the Royal Apothecary.", ["rewardGold"] = 30900, ["rewardXP"] = 1275, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 227217, ["x"] = 0.57, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 208782, ["x"] = 0.526667, ["y"] = 0.462667 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 2213, 2255 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5716, ["name"] = "To Kill a Queen", ["orderIndex"] = 0, ["flags"] = 1 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2213 },
[83616] = { ["id"] = 83616, ["name"] = "The Entrenched", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 81667, 81668, 81683, 81685, 81687, 81688, 83616 }, ["series"] = { 81683 }, ["description"] = "And now the other piece to this coup. I've been operating under Grand Overspinner Antourix 's mandibles for a while now. She's entrenched in Rak-Ahat, and thinks nothing can touch her at the top. She has already refused to submit to Ren'khat. Even she knows that if Ren'khat has the backing of the throne then it is only a matter of time. Let us expedite her attempts to oust this upstart. See how quickly they turn on each other.", ["objectivesText"] = "Offer your services to Grand Overspinner Antourix against Ren'khat. Progress: An overcrawler? Here? In MY dominion?! Minions! Slay them! Wait! Wait... You might be useful...", ["rewardGold"] = 232300, ["rewardXP"] = 7945, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 222136, ["x"] = 0.696, ["y"] = 0.48 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 221557, ["x"] = 0.756, ["y"] = 0.525 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.696, ["y"] = 0.48 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5600, ["name"] = "Subterfuge in Silk", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[83627] = { ["id"] = 83627, ["name"] = "The Beginning of Something Beautiful", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2213, ["storyline"] = { 83627 }, ["description"] = "<This seems like it would be of interest to a nerubian alchemist. Ascension is their specialty, and this may be key to understanding more about the process.>", ["objectivesText"] = "Take the Vial of Skyrazor Blood to Shalba .", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 224025, 224150, 225950, 225952, 226135, 226136 }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 218171, ["x"] = 0.451333, ["y"] = 0.136 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.451333, ["y"] = 0.136 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["startItems"] = { 225952 } },
[83628] = { ["id"] = 83628, ["name"] = "Tense Recovery", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 83628, 83629, 83632, 83639 }, ["description"] = "Things with these strangers are... tense. We do appreciate being allowed to take cover here in their camp. But they only seem to tolerate us at best. We offered to share our supplies, but that offended them, somehow. My sister is gravely wounded. I can see herbs I could use to help her in that tent over there, but that giant snail is blocking the entrance. I can't get to them. I asked the guard on the hill for aid, but all he did was glare. I don't know what to do! Perhaps he'll listen to you?", ["objectivesText"] = "Speak to the strangers to improve relations with the Arathi.", ["rewardGold"] = 232300, ["rewardXP"] = 7945, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 227222, ["x"] = 0.236, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 227224, ["x"] = 0.238, ["y"] = 0.406 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.236, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 83716 }, ["questLines"] = { { ["id"] = 5644, ["name"] = "The Wild Camp", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[83629] = { ["id"] = 83629, ["name"] = "Ancient Respite", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 83628, 83629, 83632, 83639 }, ["description"] = "This was once a great lake. Over time the roots ruptured its floor, and drained the water away. I have lived here for all of my lifetime and witnessed it all. But now, darker changes have come. Sometimes changes comes with death. Decay is natural. But the mites that feed upon my people are not. They spread an odd infestation that makes my bark feel like it crawls from my body. Destroy these mites, so that I may rest without fear of their mouths upon my sleeping form.", ["objectivesText"] = "Kill 15 Feasting Mites for Goehi . Progress: The sound of their gnawing fills me with dread.", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 227224, ["x"] = 0.238, ["y"] = 0.406 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 227224, ["x"] = 0.238, ["y"] = 0.406 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.238, ["y"] = 0.406 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 83628 }, ["questLines"] = { { ["id"] = 5644, ["name"] = "The Wild Camp", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[83632] = { ["id"] = 83632, ["name"] = "Rings of Memory", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 83628, 83629, 83632, 83639 }, ["description"] = "I appreciate what you have done. Do not worry--I am not finished yet. If you please, take this root to those who sent you. They can read the history of my life within the rings of wood therein. My life is one of many in the tapestry, but we are all intertwined. These strangers you encountered may be reclusive--secretive even--but they understand this tapestry like no other, and guard it with their lives.", ["objectivesText"] = "Bring Goehi's Root to Wild Camp Or'lay. Progress: Did you find the ancients?", ["rewardGold"] = 309800, ["rewardXP"] = 10595, ["rewardItems"] = { 225973 }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 227224, ["x"] = 0.238, ["y"] = 0.406 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 215724, ["x"] = 0.233, ["y"] = 0.527 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.238, ["y"] = 0.406 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 83629 }, ["questLines"] = { { ["id"] = 5644, ["name"] = "The Wild Camp", ["orderIndex"] = 2, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[83639] = { ["id"] = 83639, ["name"] = "Open Communications", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 83628, 83629, 83632, 83639 }, ["description"] = "You understand that others lead lives different to your own. Our ways restrict us. Our traditions are not for the ears of strangers. I have only spoken to you at all due to Orweyna's word. But I can feel On'hiea's disapproval from here. It is uncomfortable to have mysteries at times. It is why so many fear the dark. It is unknown. I know I must seem cryptic. But our ways do not mean we are offended by the Arathi. They are creating tension where it does not exist for us.", ["objectivesText"] = "Speak to Ysabel and clear up the misunderstanding. Progress: I can't leave my sister like this.", ["rewardGold"] = 146000, ["rewardXP"] = 5300, ["rewardCurrencies"] = { { ["id"] = 3002, ["amount"] = 500 }, { ["id"] = 3056, ["amount"] = 250 }, { ["id"] = 3056, ["amount"] = 285 } }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 215724, ["x"] = 0.233, ["y"] = 0.527 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 227222, ["x"] = 0.236, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.233, ["y"] = 0.527 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 83632 }, ["questLines"] = { { ["id"] = 5644, ["name"] = "The Wild Camp", ["orderIndex"] = 3, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[83641] = { ["id"] = 83641, ["name"] = "Trapped Between Life and Death", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 947, ["storyline"] = { 83031, 83499, 83502, 83539, 83553, 83554, 83555, 83556, 83641, 83643, 84223 }, ["description"] = "A pocket dimension. This is old magic. Malygos used pocket dimensions on occasion when he did not wish to be disturbed. They were mainly used by mages as research spaces or for testing dangerous spells. Or if a mage wanted to hide what they were doing... I wonder who made this one? I suppose it doesn't matter. We need to get out. Thankfully, every pocket dimension has an exit. Though, it is normally well hidden. Let's find it.", ["objectivesText"] = "Find a way out of the pocket dimension.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 158149, 210974 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 15 } }, ["starts"] = { { ["mapID"] = 947, ["npcID"] = 227208, ["x"] = 0, ["y"] = 0 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 227392, ["x"] = 0.615, ["y"] = 0.428 } }, ["coords"] = { ["mapID"] = 947, ["source"] = "quest_giver", ["x"] = 0, ["y"] = 0 }, ["mapCandidates"] = { ["npc"] = { 947, 2248 }, ["zone"] = { 15000 } }, ["questType"] = "standard", ["sourceQuests"] = { 83553, 83555 }, ["questLines"] = { { ["id"] = 5664, ["name"] = "Arcane Desolation", ["orderIndex"] = 9, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 265, ["title"] = "Fate of the Kirin Tor", ["questLineID"] = 5664, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[83643] = { ["id"] = 83643, ["name"] = "Somehow We Survived", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 83031, 83499, 83502, 83539, 83553, 83554, 83555, 83556, 83641, 83643, 84223 }, ["description"] = "What we experienced in Kel'Thuzad's pocket dimension is a timely reminder of what can happen when magic is used without regard to ethics or regulation. To me, this underlines the importance of the Kirin Tor. But, on the other hand, Kel'Thuzad was Kirin Tor. It is also a reminder of how power corrupts. Now that we have made sure these artifacts will not cause anyone else to go on an unexpected trip... Let's return to Aethas. Perhaps now more have responded to his letter.", ["objectivesText"] = "Regroup with Kalecgos at the Tranquil Strand.", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 227392, ["x"] = 0.615, ["y"] = 0.428 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 227407, ["x"] = 0.31, ["y"] = 0.578 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.428 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 83641 }, ["questLines"] = { { ["id"] = 5664, ["name"] = "Arcane Desolation", ["orderIndex"] = 10, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 265, ["title"] = "Fate of the Kirin Tor", ["questLineID"] = 5664, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[83707] = { ["id"] = 83707, ["name"] = "LFGDungeons - 11.0 The War Within - Raid Finder - 1st", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["storyline"] = { 83707 }, ["rewardGold"] = 3098000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[83711] = { ["id"] = 83711, ["name"] = "Weapons of Conquest", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14771, ["mapID"] = 2339, ["storyline"] = { 83711 }, ["description"] = "Tales of your prowess have reached even me, hero. If you fight as well as they say you do - then I reckon you would be even better with one of my creations. Write your name in history. Return when you've proven yourself both skilled and honorable.", ["objectivesText"] = "Obtain Conquest in Rated Arenas and Battlegrounds.", ["rewardItems"] = { 232602, 232603 }, ["starts"] = { { ["mapID"] = 2339, ["npcID"] = 219222, ["x"] = 0.552, ["y"] = 0.762 } }, ["ends"] = { { ["mapID"] = 2339, ["npcID"] = 219222, ["x"] = 0.552, ["y"] = 0.762 } }, ["coords"] = { ["mapID"] = 2339, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.762 }, ["mapCandidates"] = { ["npc"] = { 2339 }, ["zone"] = { 14771 } }, ["questTurnInID"] = 219222, ["questType"] = "pvp" },
[83715] = { ["id"] = 83715, ["name"] = "Claimed Salvage", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 80208, 80323, 81656, 81691, 81750, 81767, 82238, 82244, 82256, 82518, 82519, 82523, 82552, 82580, 83028, 83048, 83079, 83080, 83101, 83229, 83537, 83538, 83715, 83930, 84429 }, ["objectivesText"] = "Goblins Slain Salvage Reclaimed", ["rewardXP"] = 11765, ["rewardItems"] = { 226020 }, ["starts"] = { { ["x"] = 0.555, ["y"] = 0.806, ["mapID"] = 2214 } }, ["ends"] = { { ["x"] = 0.555, ["y"] = 0.806, ["mapID"] = 2214 } }, ["coords"] = { ["mapID"] = 2214, ["x"] = 0.555, ["y"] = 0.806 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14795 } }, ["questType"] = "world", ["questLines"] = { { ["id"] = 5588, ["name"] = "Ringing Deeps - World Quests / Repeatable", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2Objectives"] = { { ["text"] = "Goblins Slain", ["amount"] = 12, ["type"] = 0, ["objectID"] = 227374, ["orderIndex"] = 0 }, { ["text"] = "Salvage Reclaimed", ["amount"] = 6, ["type"] = 1, ["objectID"] = 226020, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2214, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[83716] = { ["id"] = 83716, ["name"] = "Beneath the Roots", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 83716 }, ["description"] = "I am glad to see you are well, <name>. I have recently received word that a number of the Aeroknights have taken shelter in a camp close to where the airship was seized in mid-air. Would you check on them?", ["objectivesText"] = "Find the camp sheltering the Aeroknights in western Azj'kahet.", ["rewardGold"] = 29200, ["rewardXP"] = 1325, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 211409, ["x"] = 0.592, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 227295, ["x"] = 0.235, ["y"] = 0.52 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 78384 }, ["nextQuests"] = { 83628 } },
[83718] = { ["id"] = 83718, ["name"] = "Eggstraction", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 78974, 78995, 79116, 79722, 79958, 79959, 79960, 80409, 80457, 82266, 82295, 82297, 82324, 82332, 82363, 82364, 82387, 82414, 82468, 82481, 82521, 82524, 82526, 82531, 82533, 82536, 83536, 83718 }, ["objectivesText"] = "Climbing Gear acquired Find a handhold on the cliff Collect Swarmite Egg", ["rewardXP"] = 11765, ["starts"] = { { ["x"] = 0.79, ["y"] = 0.785, ["mapID"] = 2255 } }, ["ends"] = { { ["x"] = 0.79, ["y"] = 0.785, ["mapID"] = 2255 } }, ["coords"] = { ["mapID"] = 2255, ["x"] = 0.79, ["y"] = 0.785 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14752 } }, ["questType"] = "world", ["questLines"] = { { ["id"] = 5564, ["name"] = "Azj-Kahet - World Quests/Repeatables", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2Objectives"] = { { ["text"] = "Climbing Gear acquired", ["amount"] = 1, ["type"] = 0, ["objectID"] = 227401, ["orderIndex"] = 0 }, { ["text"] = "Find a handhold on the cliff", ["amount"] = 1, ["type"] = 0, ["objectID"] = 227402, ["orderIndex"] = 1 }, { ["text"] = "Collect Swarmite Egg", ["amount"] = 7, ["type"] = 0, ["objectID"] = 227403, ["orderIndex"] = 2 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[83719] = { ["id"] = 83719, ["name"] = "Those Are Chitin Words", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2213, ["storyline"] = { 83719 }, ["description"] = "Well now, this is certainly an interesting specimen. It seems the original creator who worked on this creature made grave errors in balancing the genetic materials. No wonder the creature you encountered was an abomination. What terrible technique! With the right materials however, I may just be able to perfect it. Siesbarg here will be our test-subject. Perhaps his Ascension will finally catch the attention of those in charge of administering promotions!", ["objectivesText"] = "Collect enough Nerubian Chitin for Shalba 's experiment. Progress: Chitin samples will help define the strength of Siesbarg's new form.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 224025, 224150, 225950, 225952, 226135, 226136 }, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 218171, ["x"] = 0.451333, ["y"] = 0.136 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 218171, ["x"] = 0.451333, ["y"] = 0.136 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.451333, ["y"] = 0.136 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["sourceQuests"] = { 83627 } },
[83720] = { ["id"] = 83720, ["name"] = "Venom? More Like Get 'Em", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2213, ["storyline"] = { 83720 }, ["description"] = "Now that we've acquired enough chitin samples to splice into the perfect armor, we need the perfect venom. Don't look at me like that. Our forms should always be powerful and capable of defending themselves! I'll begin incorporating the new carapace requirements for Siesbarg's Ascension while you harvest what I need. Do keep in mind though, it must be nerubian venom , specifically. I'm afraid beetles and spiders simply won't do this time around. As for where you find it, well that's up to you.", ["objectivesText"] = "Collect enough Nerubian Venom for Shalba 's experiment. Progress: Very good! This is exactly what I was looking for.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 224025, 224150, 225950, 225952, 226135, 226136 }, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 218171, ["x"] = 0.451333, ["y"] = 0.136 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 218171, ["x"] = 0.451333, ["y"] = 0.136 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.451333, ["y"] = 0.136 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["sourceQuests"] = { 83719 } },
[83721] = { ["id"] = 83721, ["name"] = "A Small Ocean's Worth of Blood", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2213, ["storyline"] = { 83721 }, ["description"] = "Excellent! The end draws near! But although we near completion, we cannot go without the most important part of this genetic equation--the blood. We need a small ocean's worth of nerubian blood . However, to make this new form foolproof, the blood must come from the strongest nerubians to exist. Whether skyrazor or Ascended, it doesn't matter. This will guarantee we have the best genetic material available. The kind of material that Siesbarg deserves!", ["objectivesText"] = "Collect enough Nerubian Blood for Shalba 's experiment. Progress: Our experiment nears fruition, overcrawler.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 224025, 224150, 225950, 225952, 226135, 226136 }, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 218171, ["x"] = 0.451333, ["y"] = 0.136 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 218171, ["x"] = 0.451333, ["y"] = 0.136 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.451333, ["y"] = 0.136 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["sourceQuests"] = { 83720 } },
[83722] = { ["id"] = 83722, ["name"] = "Consolation Flies", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2213, ["storyline"] = { 83722 }, ["description"] = "Well... that's unfortunate. It appears my experiment has failed and Siesbarg paid the price. Still, I am optimistic for the future I am destined to acquire. It's only a matter of time until I perfect my process. When I do, perhaps I shall engineer my own Ascension! While his physical form isn't what I intended, it appears Siesbarg 's mind is intact. I'm certain he can still be of use. Take him. His new form can provide better service on the field of battle than in my tiny shop.", ["objectivesText"] = "Take Siesbarg off Shalba 's hands.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 224150, 225952 }, ["starts"] = { { ["mapID"] = 2213, ["npcID"] = 218171, ["x"] = 0.451333, ["y"] = 0.136 } }, ["ends"] = { { ["mapID"] = 2213, ["npcID"] = 228200, ["x"] = 0.443, ["y"] = 0.135 } }, ["coords"] = { ["mapID"] = 2213, ["source"] = "quest_giver", ["x"] = 0.451333, ["y"] = 0.136 }, ["mapCandidates"] = { ["npc"] = { 2213 }, ["zone"] = { 14753 } }, ["questType"] = "standard", ["sourceQuests"] = { 84246 } },
[83723] = { ["id"] = 83723, ["name"] = "A Helping Hand", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["description"] = "Kalecgos's hypothesis that Dalaran's debris interferes with long-range teleportation seems correct. Mage portals have appeared along the shore, but no one has stepped through them. There are likely mages trapped within the portals. Or, something mana hungry--like felhunters--may be being lured here by the release of Dalaran's power. We must investigate. Mages of the Kirin Tor may be in danger. The felhunters are an acceptable risk. Let us not waste any more time.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["npcID"] = 212829, ["x"] = 0.31, ["y"] = 0.578, ["mapID"] = 2248 } }, ["ends"] = { { ["npcID"] = 227409, ["x"] = 0.298, ["y"] = 0.578, ["mapID"] = 2248 } }, ["coords"] = { ["x"] = 0.31, ["y"] = 0.578, ["source"] = "quest_giver", ["mapID"] = 2248 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 83643 }, ["questLines"] = { { ["id"] = 5666, ["name"] = "Strength Amidst Ruins", ["orderIndex"] = 0, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 265, ["title"] = "Fate of the Kirin Tor", ["questLineID"] = 5666, ["questLineOrder"] = 1 } } },
[83738] = { ["id"] = 83738, ["name"] = "Notorious with The Weaver", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 83738 }, ["description"] = "Many many thanks for you from the Weave-mother. Come back to the Lair. I have good goods for you. I have webbed up and protected them, so no you worry!", ["objectivesText"] = "Speak with Bobbin in the Weaver's Lair.", ["rewardItems"] = { 226103 }, ["rewardCurrencies"] = { { ["id"] = 2903, ["amount"] = 2500 } }, ["starts"] = { { ["x"] = 0.564, ["y"] = 0.432, ["mapID"] = 2255, ["npcID"] = 224733 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 224734, ["x"] = 0.564, ["y"] = 0.432 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questGiverID"] = 224733, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2648, ["threshold"] = 2500 } } } },
[83739] = { ["id"] = 83739, ["name"] = "Notorious with The General", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 83739 }, ["description"] = "Word of your deeds has reached many of The General's acolytes! Find me at the Weaver's Lair. We have prepared a tribute for you!", ["objectivesText"] = "Speak with Aspirant Kiipka in the Weaver's Lair.", ["rewardItems"] = { 226045 }, ["rewardCurrencies"] = { { ["id"] = 2903, ["amount"] = 2500 } }, ["starts"] = { { ["x"] = 0.558, ["y"] = 0.422, ["mapID"] = 2255, ["npcID"] = 229184 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 229184, ["x"] = 0.558, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questGiverID"] = 229184, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2649, ["threshold"] = 2500 } } } },
[83740] = { ["id"] = 83740, ["name"] = "Notorious with The Vizier", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 83740 }, ["description"] = "The Vizier has asked me to provide you with additional resources towards your efforts. Come to the Weaver's Lair. I'll be waiting for you with a parcel.", ["objectivesText"] = "Speak with Tulumun in the Weaver's Lair.", ["rewardItems"] = { 226045, 226100, 226103 }, ["rewardCurrencies"] = { { ["id"] = 2903, ["amount"] = 2500 } }, ["starts"] = { { ["x"] = 0.562, ["y"] = 0.422, ["mapID"] = 2255, ["npcID"] = 224733 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 224733, ["x"] = 0.562, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questGiverID"] = 224733, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2647, ["threshold"] = 2500 } } } },
[83742] = { ["id"] = 83742, ["name"] = "Call to Attention", ["level"] = 78, ["requiredLevel"] = 78, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["storyline"] = { 83742 }, ["description"] = "Hail, soldier. General Anub'azal requests your presence at Siegehold immediately. He requires your expertise in the investigation of a sensitive matter. I am not at liberty to say more here. Seek out the General for further briefing. For Azj-Kahet. See if you've already completed this by typing: /run print(C_QuestLog.IsQuestFlaggedCompleted(83742)) WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(83742))\"); const cta = WH.Tools.createWowheadClientCta(); if (cta) { $('.db-page-collection-tracker-cta').append(cta); }", ["objectivesText"] = "Report to General Anub'azal in Siegehold.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[83743] = { ["id"] = 83743, ["name"] = "Arcane Cold War", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 83723, 83743, 83762, 83763, 83764, 83773 }, ["description"] = "A few mages have come but... I expected more to act on Aethas's call to action. But perhaps that was wishful thinking. We need more help despite what you and Kalecgos did at Mourning Rise. Aside from Kel'Thuzad's pendant, the kobolds' plunder was middling-powered artifacts. Meanwhile, there have been reports of powerful magical objects filtering through Azj-Kahet, meaning the nerubians must have scavenged Dalaran's crash first! We must find these artifacts before they are used against us.", ["objectivesText"] = "Travel to Azj-Kahet and meet with Lady Jaina Proudmoore .", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 227409, ["x"] = 0.298, ["y"] = 0.578 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 227529, ["x"] = 0.352, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.298, ["y"] = 0.578 }, ["mapCandidates"] = { ["npc"] = { 2248, 2255 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 83723 }, ["questLines"] = { { ["id"] = 5666, ["name"] = "Strength Amidst Ruins", ["orderIndex"] = 1, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 265, ["title"] = "Fate of the Kirin Tor", ["questLineID"] = 5666, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[83749] = { ["id"] = 83749, ["name"] = "Delves: The Waterworks", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83749 }, ["description"] = "What a trip! Can ye believe how much exists below the depths here? The Machine Speakers were telling me of problems they're having over at a place called the Waterworks. Sounds like kobolds are making trouble again. They're also storing some treasure deeper within the place. What do ye say? Let's go on an adventure and help out these folks!", ["objectivesText"] = "Complete the Waterworks delve on any difficulty.", ["rewardGold"] = 929400, ["rewardXP"] = 14275, ["rewardItems"] = { 211481, 229371, 232049, 232371 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 227477, ["x"] = 0.451, ["y"] = 0.318 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 227492, ["x"] = 0.441, ["y"] = 0.48 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.451, ["y"] = 0.318 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard" },
[83750] = { ["id"] = 83750, ["name"] = "Wanted: Zuramat the Obliterator", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 83750 }, ["description"] = "_", ["objectivesText"] = "Find Zuramat the Obliterator and collect his soul stone in Azj'Kahet.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 226158 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14752 } }, ["questType"] = "standard" },
[83752] = { ["id"] = 83752, ["name"] = "Threats of Zekvir", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83752 }, ["description"] = "Someone's watchin' us, <name>. They put this chest here for us to find. Let me know when you're ready. I'll trigger the trap here to see just what exactly is going on.", ["objectivesText"] = "Speak with Brann Bronzebeard to investigate the strange chest.", ["rewardGold"] = 30900, ["rewardXP"] = 1190, ["rewardItems"] = { 229371, 232049, 232371 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2214, ["npcID"] = 227492, ["x"] = 0.441, ["y"] = 0.48 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 227492, ["x"] = 0.441, ["y"] = 0.48 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.441, ["y"] = 0.48 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard" },
[83753] = { ["id"] = 83753, ["name"] = "Cannon Karma", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 83753, 83827, 83932, 84001, 84222, 84225, 84241, 84248, 84252, 84299, 84430, 84432, 84627, 84680, 85051, 85589 }, ["description"] = "This is gettin' serious, <name>! Those pirate goons have a cannon and are threatenin' to blow us outta the sky! But this may also be an opportunity. If youse get rid of the monkey firin' the cannon, we maybe can get control of it for ourselves for some payback!", ["objectivesText"] = "Bilge Rat attack disrupted and Cannon Master Jin'chu eliminated. Progress: Ya better be tellin' me dem pirates is all gone!", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 226133 }, ["rewardCurrencies"] = { { ["id"] = 3090, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 227818, ["x"] = 0.694, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 227818, ["x"] = 0.694, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.694, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["questType"] = "standard", ["sourceQuests"] = { 84725 }, ["questLines"] = { { ["id"] = 5767, ["name"] = "Siren Isle Weeklies", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2127, ["db2PoiUiMapID"] = 2369 },
[83755] = { ["id"] = 83755, ["name"] = "Delves: Nightfall Sanctum", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 83755, 83761 }, ["description"] = "Good tae see you again! I've run into a bit of a mess since we last met. Some nerubian called \"Zekvir\" wants the expedition to stop explorin' this land. You know what that means. We've got to explore even more! These Order of Night cultists might have information regarding Zekvir. Let's go to Nightfall Sanctum and see what we can find out.", ["objectivesText"] = "Find evidence of Zekvir within the Nightfall Sanctum and complete the delve on any difficulty.", ["rewardGold"] = 929400, ["rewardXP"] = 14275, ["rewardItems"] = { 229371, 232049, 232371 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 227523, ["x"] = 0.434, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 227528, ["x"] = 0.352, ["y"] = 0.458 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.434, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5650, ["name"] = "11.0 Delves - Level Up Guidance - (STM)", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2215 },
[83758] = { ["id"] = 83758, ["name"] = "Delver's Call: Fungal Folly", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 83758 }, ["description"] = "We've got more reports of fungarians returning to a place we've dubbed \"Fungal Folly.\" Explore the cave and eliminate any threats you find.", ["objectivesText"] = "Complete the Fungal Folly delve on any difficulty. Progress: Are you the one who grabbed the task for Fungal Folly?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 229371, 232049, 232371 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 100 } }, ["starts"] = { { ["x"] = 0.553, ["y"] = 0.559, ["mapID"] = 2248, ["objectID"] = 455716 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 224566, ["x"] = 0.552, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard" },
[83759] = { ["id"] = 83759, ["name"] = "Delver's Call: Kriegval's Rest", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 83759 }, ["description"] = "HELP WANTED Kriegval's Rest has become overrun by kobolds! This once sacred resting place of the earthen must be restored.", ["objectivesText"] = "Complete the Kriegval's Rest delve on any difficulty. Progress: Are you investigating Kriegval's Rest?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 198827, 229371, 232049, 232371 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 100 } }, ["starts"] = { { ["x"] = 0.553, ["y"] = 0.559, ["mapID"] = 2248, ["objectID"] = 455713 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 224566, ["x"] = 0.552, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard" },
[83761] = { ["id"] = 83761, ["name"] = "Delves: The Underkeep", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 83755, 83761 }, ["description"] = "Who would've thought I'd be cozying up in a nerubian's lair! There's a nasty named Zekvir threatening folks trying to explore the island. I've been asking the Weaver for any information she's got. Supposedly, there's a place called the Underkeep that might have records on him. Let's check it out and see what we can find!", ["objectivesText"] = "Find information on Zekvir within the Underkeep and complete the delve at any difficulty.", ["rewardGold"] = 929400, ["rewardXP"] = 14275, ["rewardItems"] = { 229371, 232049, 232371 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 100 } }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 227544, ["x"] = 0.572, ["y"] = 0.422 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 227548, ["x"] = 0.6, ["y"] = 0.188 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.572, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5650, ["name"] = "11.0 Delves - Level Up Guidance - (STM)", ["orderIndex"] = 0, ["flags"] = 0 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[83762] = { ["id"] = 83762, ["name"] = "Critical Mass", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 83723, 83743, 83762, 83763, 83764, 83773 }, ["description"] = "This is exactly what I had feared. Thalen Songweaver's notes on the mana bomb he devised to devastate Theramore were under guard in Dalaran. Few knew of this. I argued they should be destroyed. But others argued if such a bomb was again created, we would need them to disarm it. And now those notes are both the problem and the solution. Thankfully, I have read these notes, <name>. I will walk you through disarming the mana bomb.", ["objectivesText"] = "Help Lady Jaina Proudmoore disarm the mana bomb in the Breathing Pit.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 2919, ["amount"] = 5 }, { ["id"] = 3008, ["amount"] = 15 }, { ["id"] = 3111, ["amount"] = 5 }, { ["id"] = 3285, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 227529, ["x"] = 0.352, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 229763, ["x"] = 0.355, ["y"] = 0.524 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.352, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 83743 }, ["questLines"] = { { ["id"] = 5666, ["name"] = "Strength Amidst Ruins", ["orderIndex"] = 2, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 265, ["title"] = "Fate of the Kirin Tor", ["questLineID"] = 5666, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2601, ["db2PoiUiMapID"] = 2255 },
[83763] = { ["id"] = 83763, ["name"] = "Preserve the Legacy", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 83723, 83743, 83762, 83763, 83764, 83773 }, ["description"] = "The larger threat has been contained, <name>, but I believe there are still other artifacts important to our legacy--good and bad--here in Azj-Kahet . While they are still dangerous, their knowledge may benefit us in the long run. And, we must not allow the nerubians to profit from what they and Xal'atath did to Dalaran. Leave no dark corners here in the Breathing Pit unexplored, <name>.", ["objectivesText"] = "Collect valuable items from the Breathing Pit. Progress: We must reclaim what we can of the Kirin Tor's legacy.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 228820, 228821, 228823 }, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 229763, ["x"] = 0.355, ["y"] = 0.524 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 228963, ["x"] = 0.314, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.355, ["y"] = 0.524 }, ["mapCandidates"] = { ["npc"] = { 2248, 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 83762 }, ["questLines"] = { { ["id"] = 5666, ["name"] = "Strength Amidst Ruins", ["orderIndex"] = 3, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 265, ["title"] = "Fate of the Kirin Tor", ["questLineID"] = 5666, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[83764] = { ["id"] = 83764, ["name"] = "Too Powerful, Too Dangerous", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 83723, 83743, 83762, 83763, 83764, 83773 }, ["description"] = "Some of the relics the nerubians now possess were housed in carefully-designed containment vaults on Dalaran. That is how dangerous and powerful they are. With those vaults gone, the only course of action we can take is to destroy them. In hindsight, it seems a grave mistake to have gathered so many powerful artifacts in one place--even if that place was Dalaran. I would trust no one else with this task, <name>. Find and destroy those artifacts.", ["objectivesText"] = "Find dangerous artifacts scattered around in the Breathing Pit and destroy them.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardCurrencies"] = { { ["id"] = 3008, ["amount"] = 10 } }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 229763, ["x"] = 0.355, ["y"] = 0.524 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 228963, ["x"] = 0.314, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.355, ["y"] = 0.524 }, ["mapCandidates"] = { ["npc"] = { 2248, 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard", ["sourceQuests"] = { 83762 }, ["questLines"] = { { ["id"] = 5666, ["name"] = "Strength Amidst Ruins", ["orderIndex"] = 4, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 265, ["title"] = "Fate of the Kirin Tor", ["questLineID"] = 5666, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
[83766] = { ["id"] = 83766, ["name"] = "Delver's Call: Dread Pit", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14795, ["mapID"] = 2214, ["storyline"] = { 83766 }, ["description"] = "Two things are bad for business. Earnest competition and the Dread Pit caves. We need someone to deal with the latter! Something bad is going on here. We lost a bunch of workers in this cave. We need you to deal with the threat, so we can keep business booming!", ["objectivesText"] = "Complete the Dread Pit delve on any difficulty. Progress: Glad I finally found someone to check out the Dread Pit!", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 229371, 232049, 232371 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 100 } }, ["starts"] = { { ["x"] = 0.541, ["y"] = 0.642, ["mapID"] = 2214, ["objectID"] = 455685 } }, ["ends"] = { { ["mapID"] = 2214, ["npcID"] = 216311, ["x"] = 0.568, ["y"] = 0.642 } }, ["coords"] = { ["mapID"] = 2214, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.642 }, ["mapCandidates"] = { ["npc"] = { 2214 }, ["zone"] = { 14795 } }, ["questType"] = "standard" },
[83767] = { ["id"] = 83767, ["name"] = "Delver's Call: The Sinkhole", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 83767 }, ["description"] = "We have reports of large amounts of kobyss gathering towards a lair called the Sinkhole. There are concerns they plan to attack the smaller coast villages when they get the chance. There's a hefty reward for anyone who can go into the Sinkhole and stop whatever they're planning!", ["objectivesText"] = "Complete the Sinkhole delve on any difficulty. Progress: Beware of what lurks within the Sinkhole.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 116271, 229371, 232049, 232371 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 100 } }, ["starts"] = { { ["x"] = 0.487, ["y"] = 0.395, ["mapID"] = 2215, ["objectID"] = 455704 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 214019, ["x"] = 0.492, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard" },
[83768] = { ["id"] = 83768, ["name"] = "Delver's Call: The Skittering Breach", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 83768 }, ["description"] = "Call For Any Who Can Swing a Sword or Sling a Spell! The nerubians perform foul rituals in the shadow of our once beautiful Aegis Wall. Word is that a dark temple dedicated to their cursed gods rests beneath the ground. Someone must investigate this foul place and put an end to their schemes.", ["objectivesText"] = "Complete the Skittering Breach delve on any difficulty. Progress: The Skittering Breach is a dangerous place. Be on your guard if you're going in.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 229371, 232049, 232371 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 100 } }, ["starts"] = { { ["x"] = 0.678, ["y"] = 0.457, ["mapID"] = 2215, ["objectID"] = 455694 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 225857, ["x"] = 0.68, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.68, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard" },
[83769] = { ["id"] = 83769, ["name"] = "Delver's Call: Mycomancer Cavern", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 83769 }, ["description"] = "Spice Help Needed! Fungarians in the Mycomancer Caverns have been raiding spice crates bound for Lorel's Crossing. Someone needs to go into those caverns and push back the fungarian menace! Will pay well.", ["objectivesText"] = "Complete the Mycomancer Cavern delve on any difficulty.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 229371, 232049, 232371 }, ["rewardCurrencies"] = { { ["id"] = 2815, ["amount"] = 100 } }, ["starts"] = { { ["x"] = 0.689, ["y"] = 0.444, ["mapID"] = 2215, ["objectID"] = 455690 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 217611, ["x"] = 0.692, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.692, ["y"] = 0.456 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard" },
[83770] = { ["id"] = 83770, ["name"] = "Delver's Call: Spiral Weave", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 83770 }, ["description"] = "A lot of us survivors have heard stories about the Spiral Weave. Seems like it's a place where the nerubians have some heavy military operations going on. Taking the fight to them would help put a serious dent in the nerubians' war plans.", ["objectivesText"] = "Complete the Spiral Weave delve on any difficulty Progress: You're going into the heart of a nerubian military base. Be careful.", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardCurrencies"] = { { ["id"] = 3056, ["amount"] = 150 } }, ["starts"] = { { ["mapID"] = 2255, ["npcID"] = 211721, ["x"] = 0.588, ["y"] = 0.186 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 211721, ["x"] = 0.588, ["y"] = 0.186 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.186 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard" },
[83771] = { ["id"] = 83771, ["name"] = "Delver's Call: Tak-Rethan Abyss", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14752, ["mapID"] = 2255, ["storyline"] = { 83771 }, ["description"] = "WEAVER'S ORDERS The Tak-Rethan Abyss continues to be a place of great unrest and trouble. Someone must keep the threats in check before they interfere with our plans.", ["objectivesText"] = "Complete the Tak-Rethan Abyss delve on any difficulty. Progress: Are you investigating those kobyss?", ["rewardGold"] = 309800, ["rewardXP"] = 9515, ["rewardItems"] = { 116271 }, ["rewardCurrencies"] = { { ["id"] = 3056, ["amount"] = 150 } }, ["starts"] = { { ["x"] = 0.568, ["y"] = 0.407, ["mapID"] = 2255, ["objectID"] = 455720 } }, ["ends"] = { { ["mapID"] = 2255, ["npcID"] = 207471, ["x"] = 0.556, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 2255, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 2255 }, ["zone"] = { 14752 } }, ["questType"] = "standard" },
[83773] = { ["id"] = 83773, ["name"] = "Farewell, City of Magic", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 14717, ["mapID"] = 2248, ["storyline"] = { 83723, 83743, 83762, 83763, 83764, 83773 }, ["description"] = "Not all the Kirin Tor's issues can be solved in one day. But one way we can act is to honor those who have fallen. After speaking with everyone here, we have cobbled together a ceremony to send off those we have lost... and Dalaran. We would be honored if you would join us and participate in remembering our fallen comrades in the Kirin Tor.", ["objectivesText"] = "Place mementos brought by Dalaran survivors on the boats in the Tranquil Strand. Progress: One thing I am sure of is that the Kirin Tor's future is not another floating fortress in the sky. No, whatever path the Kirin Tor chooses, it will be firmly rooted here, on Azeroth, among the people it serves.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["starts"] = { { ["mapID"] = 2248, ["npcID"] = 227436, ["x"] = 0.315, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 2248, ["npcID"] = 227436, ["x"] = 0.315, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 2248, ["source"] = "quest_giver", ["x"] = 0.315, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 2248 }, ["zone"] = { 14717 } }, ["questType"] = "standard", ["sourceQuests"] = { 83763, 83764 }, ["questLines"] = { { ["id"] = 5666, ["name"] = "Strength Amidst Ruins", ["orderIndex"] = 5, ["flags"] = 0 } }, ["campaigns"] = { { ["id"] = 265, ["title"] = "Fate of the Kirin Tor", ["questLineID"] = 5666, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 2552, ["db2PoiUiMapID"] = 2248 },
