[83794] = { ["id"] = 83794, ["name"] = "Soggy Celebration Crate", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 83794 }, ["description"] = "<The crate is pretty wet and smells a bit fishy, but looks to be mostly sealed tight. Alyx would appreciate the supplies returned.>", ["objectivesText"] = "Return the Soggy Celebration Crate to Alyx . Progress: Oh, I am so busy. But what can I help you with?", ["rewardItems"] = { 225996, 226200, 228694 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 5 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 226683, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232404, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232410, ["x"] = 0.63, ["y"] = 0.502 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 4061, 4063 }, ["db2QuestSortName"] = "Nightborne", ["startItems"] = { 226200 } },
