[83825] = { ["id"] = 83825, ["name"] = "Restoring A Grand Tale", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 83825 }, ["description"] = "It was terrible! My book was shredded, and the pages flew everywhere! I saw some caught in the sand devils that went down the tunnel, others caught on adventurers heading out to face the big monsters in Tanaris, and others are scattered around here. Maybe that bird thing of yours could find them? Please help me get the pages back so I can restore my book! Oh, and watch out for that shady Cravitz Lorent. He's selling new copies for a hundred gold under the Fashion Frenzy stage. Robbery!", ["objectivesText"] = "Return a Green Hills of Stranglethorn to Raenie Fizzlebog outside the Caverns of Time Progress: Were you able to find all the pages and repair my book?", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 207730, 225252, 226241, 226242, 231907 }, ["rewardCurrencies"] = { { ["id"] = 1166, ["amount"] = 5 }, { ["id"] = 3100, ["amount"] = 5 } }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 231433, ["x"] = 0.63, ["y"] = 0.52 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 231433, ["x"] = 0.63, ["y"] = 0.52 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["sourceQuests"] = { 83832 }, ["db2LabelIDs"] = { 4018, 4061, 4063 }, ["db2QuestSortName"] = "Nightborne" },
[83827] = { ["id"] = 83827, ["name"] = "Silence the Song", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 10416, ["mapID"] = 2369, ["storyline"] = { 83753, 83827, 83932, 84001, 84222, 84225, 84241, 84248, 84252, 84299, 84430, 84432, 84627, 84680, 85051, 85589 }, ["description"] = "The sirens... they're out there! And I wonder... was it the crystal or these creatures that the Kul Tirans named this isle after? Whichever it may be, these sirens' call has lured many of our forces to their doom. Our goblin allies have prepared a device to remove the control they have over our troops. Eliminate these \"sirens\" and dispel the charm that holds our troops captive.", ["objectivesText"] = "Free 7 Charmed Troops and slay Macabea The Sea Banshee . Progress: Have you eliminated the siren threat?", ["rewardGold"] = 309800, ["rewardXP"] = 8825, ["rewardItems"] = { 226261 }, ["rewardCurrencies"] = { { ["id"] = 3090, ["amount"] = 200 } }, ["starts"] = { { ["mapID"] = 2369, ["npcID"] = 232753, ["x"] = 0.4545, ["y"] = 0.6755 } }, ["ends"] = { { ["mapID"] = 2369, ["npcID"] = 232753, ["x"] = 0.4545, ["y"] = 0.6755 } }, ["coords"] = { ["mapID"] = 2369, ["source"] = "quest_giver", ["x"] = 0.4545, ["y"] = 0.6755 }, ["mapCandidates"] = { ["npc"] = { 2369 }, ["zone"] = { 10416 } }, ["questType"] = "standard", ["sourceQuests"] = { 84725 }, ["questLines"] = { { ["id"] = 5767, ["name"] = "Siren Isle Weeklies", ["orderIndex"] = 1, ["flags"] = 0 } }, ["db2PoiMapID"] = 2127, ["db2PoiUiMapID"] = 2369 },
[83832] = { ["id"] = 83832, ["name"] = "Torn Dreams", ["level"] = 10, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 10, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 83832 }, ["description"] = "Hello again! I could really use your help here. A visitor by the name of Addie Fizzlebog had a book damaged by some time devils that swept through here last night. I am still dealing with all the other problems they caused and was hoping you could help Addie with her issue.", ["objectivesText"] = "Seek out Raenie Fizzlebog outside the Caverns of Time.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 226683, ["x"] = 0.63, ["y"] = 0.502 }, { ["mapID"] = 71, ["npcID"] = 232404, ["x"] = 0.63, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 231433, ["x"] = 0.63, ["y"] = 0.52 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["sourceQuests"] = { 83831 }, ["db2LabelIDs"] = { 4063 }, ["db2QuestSortName"] = "Nightborne" },
